int missingNumber(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    int expectedSum = ((n + 1) * (n + 2)) / 2;
    int actualSum = 0;
    for (int i = 0; i < n; ++i) {
        actualSum += nums[i];
    }
    return expectedSum - actualSum;
}

