std::vector<int> josephusOrder(int n) {
    std::vector<int> people(n);
    for (int i = 0; i < n; ++i) people[i] = i + 1;
    std::vector<int> order;
    int idx = 0;
    while (!people.empty()) {
        idx = (idx + 1) % (int)people.size();
        order.push_back(people[idx]);
        people.erase(people.begin() + idx);
        if (idx == (int)people.size()) idx = 0;
    }
    return order;
}

