int ferrisWheel(std::vector<int> people, int limit) {
    std::sort(people.begin(), people.end());
    int left = 0;
    int right = static_cast<int>(people.size()) - 1;
    int count = 0;
    while (left <= right) {
        if (people[left] + people[right] <= limit) {
            ++left;
        }
        --right;
        ++count;
    }
    return count;
}

