int removingDigits(int n) {
    std::vector<int> dp(n + 1, INT_MAX);
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        int temp = i;
        while (temp > 0) {
            int d = temp % 10;
            if (d > 0) dp[i] = std::min(dp[i], dp[i - d] + 1);
            temp /= 10;
        }
    }
    return dp[n];
}

