int bookShop(const std::vector<int>& prices, const std::vector<int>& pages, int budget) {
    int n = static_cast<int>(prices.size());
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(budget + 1, 0));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= budget; ++j) {
            if (prices[i - 1] > j) {
                dp[i][j] = dp[i - 1][j];
            } else {
                dp[i][j] = std::max(dp[i - 1][j], dp[i - 1][j - prices[i - 1]] + pages[i - 1]);
            }
        }
    }
    return dp[n][budget];
}

