std::vector<int> buildTeams(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> graph(n);
    for (auto& e : edges) {
        graph[e[0]].push_back(e[1]);
        graph[e[1]].push_back(e[0]);
    }
    std::vector<int> team(n, 0);
    for (int start = 0; start < n; ++start) {
        if (team[start] != 0) continue;
        team[start] = 1;
        std::queue<int> q;
        q.push(start);
        while (!q.empty()) {
            int node = q.front(); q.pop();
            for (int nb : graph[node]) {
                if (team[nb] == 0) {
                    team[nb] = team[node] == 1 ? 2 : 1;
                    q.push(nb);
                } else if (team[nb] == team[node]) {
                    return {}; // IMPOSSIBLE (empty vector sentinel)
                }
            }
        }
    }
    return team;
}

