std::vector<double> shortestRoutes(const std::vector<std::vector<int>>& graph, int start) {
    std::vector<double> distances(graph.size(), std::numeric_limits<double>::infinity());
    distances[start] = 0;
    std::deque<int> queue;
    queue.push_back(start);
    while (!queue.empty()) {
        int currentNode = queue.front();
        queue.pop_front();
        for (size_t i = 0; i < graph.size(); ++i) {
            if (graph[currentNode][i] != 0 && distances[currentNode] + graph[currentNode][i] < distances[i]) {
                distances[i] = distances[currentNode] + graph[currentNode][i];
                queue.push_back(static_cast<int>(i));
            }
        }
    }
    return distances;
}

