long long shortestRoutes(int n, const std::vector<std::vector<int>>& edges, int src, int dest) {
    std::vector<std::vector<std::pair<int, int>>> graph(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int w = e[2];
        graph[u].push_back({v, w});
        graph[v].push_back({u, w});
    }
    const long long INF = std::numeric_limits<long long>::max();
    std::vector<long long> distance(n, INF);
    distance[src] = 0;
    std::vector<std::pair<int, long long>> pq;
    pq.push_back({src, 0});
    while (!pq.empty()) {
        int currentNode = pq.front().first;
        long long currentDistance = pq.front().second;
        pq.erase(pq.begin());
        if (currentDistance > distance[currentNode]) continue;
        for (const auto& neighborInfo : graph[currentNode]) {
            int neighbor = neighborInfo.first;
            int weight = neighborInfo.second;
            long long newDistance = currentDistance + weight;
            if (newDistance < distance[neighbor]) {
                distance[neighbor] = newDistance;
                pq.push_back({neighbor, newDistance});
                std::sort(pq.begin(), pq.end(),
                    [](const std::pair<int, long long>& a, const std::pair<int, long long>& b) {
                        return a.second < b.second;
                    });
            }
        }
    }
    return distance[dest] == INF ? -1 : distance[dest];
}

