long long wordCombinations(const std::string& s, const std::vector<std::string>& words) {
    int n = s.size();
    std::vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (const auto& w : words) {
            int L = w.size();
            if (L <= i && s.compare(i - L, L, w) == 0) {
                dp[i] = (dp[i] + dp[i - L]) % 1000000007;
            }
        }
    }
    return dp[n];
}

