std::vector<int> findBorders(const std::string& s) {
    std::vector<int> borders(s.length(), 0);
    int maxLength = 0;
    for (std::size_t i = 1; i < s.length(); ++i) {
        int j = maxLength;
        while (j > 0 && s[i] != s[j]) {
            j = borders[j - 1];
        }
        if (s[i] == s[j]) {
            maxLength = j + 1;
        }
        borders[i] = maxLength;
    }
    return borders;
}

