double findMedianSortedArrays(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    if (nums1.size() > nums2.size()) return findMedianSortedArrays(nums2, nums1);
    int x = static_cast<int>(nums1.size());
    int y = static_cast<int>(nums2.size());
    int start = 0, end = x;
    const double INF = std::numeric_limits<double>::infinity();
    while (start <= end) {
        int partitionX = (start + end) / 2;
        int partitionY = (x + y + 1) / 2 - partitionX;
        double maxLeftX = (partitionX == 0) ? -INF : static_cast<double>(nums1[partitionX - 1]);
        double minRightX = (partitionX == x) ? INF : static_cast<double>(nums1[partitionX]);
        double maxLeftY = (partitionY == 0) ? -INF : static_cast<double>(nums2[partitionY - 1]);
        double minRightY = (partitionY == y) ? INF : static_cast<double>(nums2[partitionY]);
        if (maxLeftX <= minRightY && maxLeftY <= minRightX) {
            if ((x + y) % 2 == 0) {
                return (std::max(maxLeftX, maxLeftY) + std::min(minRightX, minRightY)) / 2.0;
            } else {
                return std::max(maxLeftX, maxLeftY);
            }
        } else if (maxLeftX > minRightY) {
            end = partitionX - 1;
        } else {
            start = partitionX + 1;
        }
    }
    return 0.0;
}

class Solution {
public:
    string longestPalindrome(string s) {
        if (s.empty()) return "";
        int start = 0, maxLen = 1;
        int n = s.size();
        for (int center = 0; center < 2*n-1; center++) {
            int l = center/2, r = l + center%2;
            while (l >= 0 && r < n && s[l] == s[r]) { l--; r++; }
            l++; r--;
            if (r - l + 1 > maxLen) { maxLen = r-l+1; start = l; }
        }
        return s.substr(start, maxLen);
    }
};

