int reverse(int x) {
    bool isNegative = x < 0;
    long long xx = x;
    if (xx < 0) xx = -xx;
    long long reversed = 0;
    while (xx > 0) {
        int digit = xx % 10;
        xx = xx / 10;
        if (reversed > (static_cast<long long>(INT_MAX) - digit) / 10) return 0;
        reversed = reversed * 10 + digit;
    }
    if (isNegative) reversed = -reversed;
    return static_cast<int>(reversed);
}

