ListNode* mergeKLists(std::vector<ListNode*>& lists) {
    std::vector<std::tuple<int, int, ListNode*>> minHeap;
    for (int i = 0; i < static_cast<int>(lists.size()); ++i) {
        if (lists[i]) {
            minHeap.emplace_back(lists[i]->val, i, lists[i]);
        }
    }
    ListNode dummy(0);
    ListNode* current = &dummy;
    while (!minHeap.empty()) {
        std::sort(minHeap.begin(), minHeap.end(),
                  [](const std::tuple<int, int, ListNode*>& a,
                     const std::tuple<int, int, ListNode*>& b) {
                      return std::get<0>(a) < std::get<0>(b);
                  });
        int val = std::get<0>(minHeap.front());
        int listIndex = std::get<1>(minHeap.front());
        ListNode* node = std::get<2>(minHeap.front());
        minHeap.erase(minHeap.begin());
        current->next = node;
        current = current->next;
        if (node->next) {
            minHeap.emplace_back(node->next->val, listIndex, node->next);
        }
    }
    return dummy.next;
}

