std::vector<int> findSubstring(const std::string& s, const std::vector<std::string>& words) {
    std::vector<int> result;
    int wordCount = static_cast<int>(words.size());
    if (wordCount == 0) return result;
    int wordLength = static_cast<int>(words[0].size());
    int totalLength = wordCount * wordLength;
    std::unordered_map<std::string, int> wordMap;
    for (const std::string& word : words) {
        ++wordMap[word];
    }
    int sLen = static_cast<int>(s.size());
    for (int i = 0; i <= sLen - totalLength; ++i) {
        std::unordered_map<std::string, int> seen;
        for (int j = 0; j < wordCount; ++j) {
            int start = i + j * wordLength;
            std::string word = s.substr(start, wordLength);
            if (wordMap.find(word) == wordMap.end()) {
                break;
            }
            ++seen[word];
            if (seen[word] > wordMap[word]) {
                break;
            }
            if (j == wordCount - 1) {
                result.push_back(i);
            }
        }
    }
    return result;
}

