    while (i >= 0 && nums[i] >= nums[i + 1]) {
        --i;
    }
    if (i >= 0) {
        int j = n - 1;
        while (j > i && nums[j] <= nums[i]) {
            --j;
        }
        std::swap(nums[i], nums[j]);
    }
    int left = i + 1;
    int right = n - 1;
    while (left < right) {
        std::swap(nums[left], nums[right]);
        ++left;
        --right;
    }
    return nums;
}

