        int subCol = 3 * (col / 3) + i % 3;
        if (board[subRow][subCol] == ch) return false;
    }
    return true;
}

bool backtrack(std::vector<std::vector<char>>& board) {
    for (int r = 0; r < 9; ++r) {
        for (int c = 0; c < 9; ++c) {
            if (board[r][c] == '.') {
                for (char d = '1'; d <= '9'; ++d) {
                    if (isValid(board, r, c, d)) {
                        board[r][c] = d;
                        if (backtrack(board)) return true;
                        board[r][c] = '.';
                    }
                }
                return false;
            }
        }
    }
    return true;
}

std::vector<std::vector<char>> solveSudoku(std::vector<std::vector<char>>& board) {
    backtrack(board);
    return board;
}

