int firstMissingPositive(std::vector<int>& nums) {
    int j = 0;
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        if (nums[i] > 0) {
            std::swap(nums[i], nums[j]);
            ++j;
        }
    }
    for (int i = 0; i < j; ++i) {
        int num = std::abs(nums[i]);
        if (num - 1 < j) {
            nums[num - 1] = -std::abs(nums[num - 1]);
        }
    }
    for (int i = 0; i < j; ++i) {
        if (nums[i] > 0) {
            return i + 1;
