std::string multiply(const std::string& num1, const std::string& num2) {
    std::vector<int> result(num1.size() + num2.size(), 0);
    for (int i = static_cast<int>(num1.size()) - 1; i >= 0; --i) {
        for (int j = static_cast<int>(num2.size()) - 1; j >= 0; --j) {
            int mul = (num1[i] - '0') * (num2[j] - '0');
            int p1 = i + j;
            int p2 = i + j + 1;
            int sum = mul + result[p2];
            result[p1] += sum / 10;
            result[p2] = sum % 10;
        }
    }
    std::size_t start = 0;
    while (start < result.size() - 1 && result[start] == 0) {
        ++start;
    }
    std::string res;
    for (std::size_t i = start; i < result.size(); ++i) {
        res.push_back(static_cast<char>('0' + result[i]));
    }
    return res.empty() ? std::string("0") : res;
}

