bool isMatch(const std::string& s, const std::string& p) {
    int sIndex = 0, pIndex = 0, starIndex = -1, matchIndex = 0;
    int sLen = static_cast<int>(s.size());
    int pLen = static_cast<int>(p.size());
    while (sIndex < sLen) {
        if (pIndex < pLen && p[pIndex] == '*') {
            starIndex = pIndex;
            matchIndex = sIndex;
            ++pIndex;
        } else if (pIndex < pLen && (p[pIndex] == '?' || p[pIndex] == s[sIndex])) {
            ++pIndex;
            ++sIndex;
        } else if (starIndex != -1) {
            pIndex = starIndex + 1;
            ++matchIndex;
            sIndex = matchIndex;
        } else {
            return false;
        }
    }
    while (pIndex < pLen && p[pIndex] == '*') {
        ++pIndex;
    }
    return pIndex == pLen;
}

