std::vector<std::vector<std::string>> solveNQueens(int n) {
    std::vector<std::vector<std::string>> result;
    std::vector<std::vector<char>> board(n, std::vector<char>(n, '.'));

    std::function<bool(int, int)> isValid = [&](int row, int col) -> bool {
        for (int i = 0; i < row; ++i) {
            if (board[i][col] == 'Q') return false;
        }
        for (int i = row - 1, j = col - 1; i >= 0 && j >= 0; --i, --j) {
            if (board[i][j] == 'Q') return false;
        }
        for (int i = row - 1, j = col + 1; i >= 0 && j < n; --i, ++j) {
            if (board[i][j] == 'Q') return false;
        }
        return true;
    };

    std::function<void(int)> backtrack = [&](int row) {
        if (row == n) {
            std::vector<std::string> boardCopy;
            boardCopy.reserve(n);
            for (const auto& r : board) {
                boardCopy.emplace_back(r.begin(), r.end());
            }
            result.push_back(std::move(boardCopy));
            return;
        }
        for (int col = 0; col < n; ++col) {
            if (isValid(row, col)) {
                board[row][col] = 'Q';
                backtrack(row + 1);
                board[row][col] = '.';
            }
        }
    };

    backtrack(0);
    return result;
}

