int totalNQueens(int n) {
    std::function<bool(const std::vector<int>&, int, int)> isSafe = [&](const std::vector<int>& board, int row, int col) -> bool {
        for (int i = 0; i < row; ++i) {
            if (board[i] == col ||
                board[i] - i == col - row ||
                board[i] + i == col + row) {
                return false;
            }
        }
        return true;
    };
    std::function<int(std::vector<int>&, int)> placeQueens = [&](std::vector<int>& board, int row) -> int {
        if (row == n) {
            return 1;
        }
        int count = 0;
        for (int col = 0; col < n; ++col) {
            if (isSafe(board, row, col)) {
                board[row] = col;
                count += placeQueens(board, row + 1);
            }
        }
        return count;
    };
    std::vector<int> board(n, -1);
    return placeQueens(board, 0);
}

