bool isNumber(const std::string& s) {
    bool seenE = false, seenDot = false, seenDigit = false;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (std::isdigit(static_cast<unsigned char>(c))) {
            seenDigit = true;
        } else if (c == '-' || c == '+') {
            if (i != 0 && std::tolower(static_cast<unsigned char>(s[i - 1])) != 'e') return false;
        } else if (std::tolower(static_cast<unsigned char>(c)) == 'e') {
            if (seenE || !seenDigit) return false;
            seenE = true;
            seenDigit = false;
        } else if (c == '.') {
            if (seenDot || seenE) return false;
            seenDot = true;
        } else {
            return false;
        }
    }
    return seenDigit;
}

