            std::string line;
            if (gaps == 0) {
                line = currentLine[0];
                line.append(spaces, ' ');
            } else {
                int extraSpaces = spaces / gaps;
                int remainingSpaces = spaces % gaps;
                for (size_t j = 0; j < currentLine.size(); ++j) {
                    line += currentLine[j];
                    if (j < currentLine.size() - 1) {
                        int spaceCount = extraSpaces + (static_cast<int>(j) < remainingSpaces ? 1 : 0);
                        line.append(spaceCount, ' ');
                    }
                }
            }
            result.push_back(line);
            currentLine.clear();
            currentLine.push_back(words[i]);
            currentWidth = static_cast<int>(words[i].size());
        } else {
            currentLine.push_back(words[i]);
            currentWidth += static_cast<int>(words[i].size());
        }
    }
    std::string lastLine;
    for (size_t i = 0; i < currentLine.size(); ++i) {
        lastLine += currentLine[i];
        if (i < currentLine.size() - 1) {
            lastLine += ' ';
        }
    }
    lastLine.append(maxWidth - static_cast<int>(lastLine.size()), ' ');
    result.push_back(lastLine);
    return result;
}

