    long long left = 2;
    long long right = x / 2;
    while (left <= right) {
        long long mid = (left + right) / 2;
        long long square = mid * mid;
        if (square == x) return mid;
        if (square < x) left = mid + 1;
        else right = mid - 1;
    }
    return right;
}

