std::string minWindow(const std::string& s, const std::string& t) {
    if (s.size() < t.size()) return "";
    std::unordered_map<char, int> tCount;
    for (char ch : t) {
        ++tCount[ch];
    }
    int requiredChars = tCount.size();
    int left = 0, right = 0;
    int formedChars = 0;
    std::unordered_map<char, int> windowCounts;
    std::pair<int, int> minWindow = {0, INT_MAX};
    while (right < static_cast<int>(s.size())) {
        char c = s[right];
        auto it = tCount.find(c);
        if (it != tCount.end()) {
            ++windowCounts[c];
            if (windowCounts[c] == it->second) {
                ++formedChars;
            }
        }
        while (left <= right && formedChars == requiredChars) {
            if (right - left + 1 < minWindow.second - minWindow.first) {
                minWindow = {left, right + 1};
            }
            char cl = s[left];
            auto itl = tCount.find(cl);
            if (itl != tCount.end()) {
                --windowCounts[cl];
                if (windowCounts[cl] < itl->second) {
                    --formedChars;
                }
            }
            ++left;
        }
        ++right;
    }
    return minWindow.second == INT_MAX ? "" : s.substr(minWindow.first, minWindow.second - minWindow.first);
}

