bool exist(const std::vector<std::vector<char>>& board, const std::string& word) {
    int rows = static_cast<int>(board.size());
    int cols = static_cast<int>(board[0].size());
    std::vector<std::vector<bool>> visited(rows, std::vector<bool>(cols, false));

    std::function<bool(int, int, int)> dfs = [&](int row, int col, int index) -> bool {
        if (index == static_cast<int>(word.size())) return true;
        if (row < 0 || row >= rows || col < 0 || col >= cols || visited[row][col] || board[row][col] != word[index]) return false;
        visited[row][col] = true;
        bool found = dfs(row + 1, col, index + 1) ||
                     dfs(row - 1, col, index + 1) ||
                     dfs(row, col + 1, index + 1) ||
                     dfs(row, col - 1, index + 1);
        visited[row][col] = false;
        return found;
    };

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (dfs(i, j, 0)) return true;
        }
    }
    return false;
}

