bool isScramble(const std::string& s1, const std::string& s2) {
    static std::unordered_map<std::string, bool> memo;
    if (s1.size() != s2.size()) return false;
    if (s1 == s2) return true;
    std::string key = s1 + "#" + s2;
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;
    if (sortString(s1) != sortString(s2)) {
        memo[key] = false;
        return false;
    }
    for (size_t i = 1; i < s1.size(); ++i) {
        if (isScramble(s1.substr(0, i), s2.substr(0, i)) &&
            isScramble(s1.substr(i), s2.substr(i))) {
            memo[key] = true;
            return true;
        }
        if (isScramble(s1.substr(0, i), s2.substr(s2.size() - i)) &&
            isScramble(s1.substr(i), s2.substr(0, s2.size() - i))) {
            memo[key] = true;
            return true;
        }
    }
    memo[key] = false;
    return false;
}

