std::vector<int> grayCode(int n) {
    std::vector<int> result;
    for (int i = 0; i < (1 << n); ++i) {
        int j = i >> 1;
        if ((i ^ j) == (i ^ (i >> 1))) {
            result.push_back(i);
        }
    }
    std::vector<int> grayCodeSequence;
    if (n == 0) {
        grayCodeSequence.push_back(0);
    } else {
        std::vector<int> subSequence = grayCode(n - 1);
        for (size_t i = 0; i < subSequence.size(); ++i) {
            grayCodeSequence.push_back(subSequence[i]);
        }
        for (int i = static_cast<int>(subSequence.size()) - 1; i >= 0; --i) {
            grayCodeSequence.push_back(subSequence[i] + (1 << (n - 1)));
        }
    }
    return grayCodeSequence;
}

