static void backtrack(const std::string& s, std::size_t start, std::vector<std::string> path, std::vector<std::string>& result) {
    if (path.size() == 4 && start == s.size()) {
        std::string ip;
        for (std::size_t i = 0; i < path.size(); ++i) {
            ip += path[i];
            if (i != path.size() - 1) ip += '.';
        }
        result.push_back(ip);
        return;
    }
    if (path.size() == 4 || start == s.size()) {
        return;
    }
    for (std::size_t len = 1; len <= 3; ++len) {
        if (start + len > s.size()) break;
        std::string part = s.substr(start, len);
        if (isValidPart(part)) {
            std::vector<std::string> newPath = path;
            newPath.push_back(part);
            backtrack(s, start + len, newPath, result);
        }
    }
}

