std::vector<std::vector<int>> zigzagLevelOrder(TreeNode* root) {
    if (!root) return {};
    std::vector<std::vector<int>> result;
    std::deque<TreeNode*> queue;
    queue.push_back(root);
    bool isLeftToRight = true;
    while (!queue.empty()) {
        int levelSize = queue.size();
        std::vector<int> levelValues;
        for (int i = 0; i < levelSize; ++i) {
            TreeNode* currentNode = queue.front();
            queue.pop_front();
            if (isLeftToRight) levelValues.push_back(currentNode->val);
            else levelValues.insert(levelValues.begin(), currentNode->val);
            if (currentNode->left) queue.push_back(currentNode->left);
            if (currentNode->right) queue.push_back(currentNode->right);
        }
        result.push_back(std::move(levelValues));
        isLeftToRight = !isLeftToRight;
    }
    return result;
}

