TreeNode* buildTree(const std::vector<int>& preorder, const std::vector<int>& inorder) {
    if (preorder.empty()) return nullptr;
    TreeNode* root = new TreeNode(preorder[0]);
    auto it = std::find(inorder.begin(), inorder.end(), preorder[0]);
    int index = static_cast<int>(std::distance(inorder.begin(), it));
    std::vector<int> leftPre(preorder.begin() + 1, preorder.begin() + index + 1);
    std::vector<int> leftIn(inorder.begin(), inorder.begin() + index);
    root->left = buildTree(leftPre, leftIn);
    std::vector<int> rightPre(preorder.begin() + index + 1, preorder.end());
    std::vector<int> rightIn(inorder.begin() + index + 1, inorder.end());
    root->right = buildTree(rightPre, rightIn);
    return root;
}

