    if (node == nullptr) {
        return std::make_pair(-1, true);
    }
    std::pair<int, bool> left = checkBalance(node->left);
    std::pair<int, bool> right = checkBalance(node->right);
    bool balanced = left.second && right.second && std::abs(left.first - right.first) <= 1;
    int height = std::max(left.first, right.first) + 1;
    return std::make_pair(height, balanced);
}

