long long numDistinct(const std::string& s, const std::string& t) {
    size_t sLength = s.length();
    size_t tLength = t.length();
    std::vector<std::vector<long long>> dp(tLength + 1, std::vector<long long>(sLength + 1, 0));
    for (size_t j = 0; j <= sLength; ++j) {
        dp[0][j] = 1;
    }
    for (size_t i = 1; i <= tLength; ++i) {
        for (size_t j = 1; j <= sLength; ++j) {
            if (t[i - 1] == s[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + dp[i][j - 1];
            } else {
                dp[i][j] = dp[i][j - 1];
            }
        }
    }
    return dp[tLength][sLength];
}

