int minimumTotal(const std::vector<std::vector<int>>& triangle) {
    int n = static_cast<int>(triangle.size());
    std::vector<std::vector<int>> dp;
    dp.reserve(n);
    for (int i = 0; i < n; ++i) {
        dp.emplace_back(triangle[i].size(), 0);
    }
    dp[0][0] = triangle[0][0];
    for (int i = 1; i < n; ++i) {
        for (int j = 0; j < static_cast<int>(triangle[i].size()); ++j) {
            if (j == 0) {
                dp[i][j] = dp[i - 1][j] + triangle[i][j];
            } else if (j == static_cast<int>(triangle[i].size()) - 1) {
                dp[i][j] = dp[i - 1][j - 1] + triangle[i][j];
            } else {
                dp[i][j] = std::min(dp[i - 1][j - 1], dp[i - 1][j]) + triangle[i][j];
            }
        }
    }
    int minSum = dp[n - 1][0];
    for (int i = 1; i < static_cast<int>(triangle[n - 1].size()); ++i) {
        minSum = std::min(minSum, dp[n - 1][i]);
    }
    return minSum;
}

