static inline bool isAlphanumeric(char c) {
    return std::isalnum(static_cast<unsigned char>(c)) != 0;
}

bool isPalindrome(const std::string& s) {
    std::size_t left = 0;
    std::size_t right = s.length() == 0 ? 0 : s.length() - 1;
    while (left < right) {
        if (!isAlphanumeric(s[left])) {
            ++left;
        } else if (!isAlphanumeric(s[right])) {
            --right;
        } else if (std::tolower(static_cast<unsigned char>(s[left])) != std::tolower(static_cast<unsigned char>(s[right]))) {
            return false;
        } else {
            ++left;
            --right;
        }
    }
    return true;
}

