int ladderLength(const std::string& beginWord, const std::string& endWord, const std::vector<std::string>& wordList) {
    std::unordered_set<std::string> wordSet(wordList.begin(), wordList.end());
    std::queue<std::pair<std::string, int>> q;
    q.emplace(beginWord, 1);
    while (!q.empty()) {
        std::string word = q.front().first;
        int length = q.front().second;
        q.pop();
        if (word == endWord) {
            return length;
        }
        for (size_t i = 0; i < word.size(); ++i) {
            for (int j = 0; j < 26; ++j) {
                std::string nextWord = word;
                nextWord[i] = static_cast<char>('a' + j);
                if (wordSet.find(nextWord) != wordSet.end()) {
                    q.emplace(nextWord, length + 1);
                    wordSet.erase(nextWord);
                }
            }
        }
    }
    return 0;
}

