std::vector<std::vector<std::string>> findLadders(const std::string& beginWord, const std::string& endWord, const std::vector<std::string>& wordList) {
    std::unordered_set<std::string> wordSet(wordList.begin(), wordList.end());
    if (wordSet.find(endWord) == wordSet.end()) {
        return {};
    }
    std::deque<std::vector<std::string>> queue;
    queue.push_back({beginWord});
    std::unordered_set<std::string> visited;
    visited.insert(beginWord);
    int shortestPathLength = INT_MAX;
    std::vector<std::vector<std::string>> result;
    while (!queue.empty()) {
        std::vector<std::string> path = std::move(queue.front());
        queue.pop_front();
        const std::string& currentWord = path.back();
        for (size_t i = 0; i < currentWord.size(); ++i) {
            for (int j = 0; j < 26; ++j) {
                std::string nextWord = currentWord;
                nextWord[i] = static_cast<char>('a' + j);
                if (wordSet.find(nextWord) != wordSet.end() && visited.find(nextWord) == visited.end()) {
                    if (nextWord == endWord) {
                        if (static_cast<int>(path.size()) + 1 < shortestPathLength) {
                            shortestPathLength = static_cast<int>(path.size()) + 1;
                            result.clear();
                            std::vector<std::string> newPath = path;
                            newPath.push_back(nextWord);
                            result.push_back(std::move(newPath));
                        } else if (static_cast<int>(path.size()) + 1 == shortestPathLength) {
                            std::vector<std::string> newPath = path;
                            newPath.push_back(nextWord);
                            result.push_back(std::move(newPath));
                        }
                    } else {
                        std::vector<std::string> newPath = path;
                        newPath.push_back(nextWord);
                        queue.push_back(std::move(newPath));
                        visited.insert(nextWord);
                    }
                }
            }
        }
    }
    return result;
}

