void backtrack(const std::string& s, int start, std::vector<std::string>& path, std::vector<std::vector<std::string>>& result) {
    if (start == static_cast<int>(s.size())) {
        result.push_back(path);
        return;
    }
    for (int i = start; i < static_cast<int>(s.size()); ++i) {
        std::string substring = s.substr(start, i - start + 1);
        if (isPalindrome(substring)) {
            path.push_back(substring);
            backtrack(s, i + 1, path, result);
            path.pop_back();
        }
    }
}

std::vector<std::vector<std::string>> partition(const std::string& s) {
    std::vector<std::vector<std::string>> result;
    std::vector<std::string> path;
    backtrack(s, 0, path, result);
    return result;
}

