int minCut(const std::string& s) {
    int n = static_cast<int>(s.length());
    if (n == 0) return 0;
    std::vector<std::vector<bool>> isPalindrome(n, std::vector<bool>(n, false));
    std::vector<int> dp(n);

    for (int i = n - 1; i >= 0; --i) {
        for (int j = i; j < n; ++j) {
            isPalindrome[i][j] = (s[i] == s[j]) && (j - i < 2 || isPalindrome[i + 1][j - 1]);
        }
    }

    for (int i = 0; i < n; ++i) {
        dp[i] = i;
    }

    for (int i = 0; i < n; ++i) {
        if (isPalindrome[0][i]) {
            dp[i] = 0;
        } else {
            for (int j = 0; j < i; ++j) {
                if (isPalindrome[j + 1][i]) {
                    dp[i] = std::min(dp[i], dp[j] + 1);
                }
            }
        }
    }

    return dp[n - 1];
}

