Node* copyRandomList(Node* head) {
    if (!head) return nullptr;
    std::unordered_map<Node*, Node*> map;
    Node* oldNode = head;
    while (oldNode) {
        map[oldNode] = new Node(oldNode->val);
        oldNode = oldNode->next;
    }
    oldNode = head;
    while (oldNode) {
        if (oldNode->next) map[oldNode]->next = map[oldNode->next];
        if (oldNode->random) map[oldNode]->random = map[oldNode->random];
        oldNode = oldNode->next;
    }
    return map[head];
}

