bool wordBreak(const std::string& s, const std::vector<std::string>& wordDict) {
    std::unordered_map<std::size_t, bool> memo;
    std::function<bool(std::size_t)> dp = [&](std::size_t start) -> bool {
        if (start == s.size()) return true;
        auto it = memo.find(start);
        if (it != memo.end()) return it->second;
        for (std::size_t end = start + 1; end <= s.size(); ++end) {
            std::string sub = s.substr(start, end - start);
            if (std::find(wordDict.begin(), wordDict.end(), sub) != wordDict.end() && dp(end)) {
                memo[start] = true;
                return true;
            }
        }
        memo[start] = false;
        return false;
    };
    return dp(0);
}

