std::vector<std::string> wordBreak(const std::string& s, const std::vector<std::string>& wordDict) {
    std::unordered_set<std::string> dict(wordDict.begin(), wordDict.end());
    std::vector<std::string> result;
    std::vector<std::string> path;
    std::function<void(int)> dfs = [&](int index) {
        if (index == static_cast<int>(s.size())) {
            std::string sentence;
            for (size_t i = 0; i < path.size(); ++i) {
                if (i) sentence.push_back(' ');
                sentence += path[i];
            }
            result.push_back(sentence);
            return;
        }
        for (int i = index; i < static_cast<int>(s.size()); ++i) {
            std::string word = s.substr(index, i - index + 1);
            if (dict.count(word)) {
                path.push_back(word);
                dfs(i + 1);
                path.pop_back();
            }
        }
    };
    dfs(0);
    return result;
}

