struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

std::vector<int> preorderTraversal(TreeNode* root) {
    std::vector<int> result;
    std::vector<TreeNode*> stack;
    stack.push_back(root);
    while (!stack.empty()) {
        TreeNode* node = stack.back();
        stack.pop_back();
        if (node) {
            result.push_back(node->val);
            stack.push_back(node->right);
            stack.push_back(node->left);
        }
    }
    return result;
}

vector<int> postorderTraversal(TreeNode* root) {
    vector<int> result;
    vector<TreeNode*> stack;
    stack.push_back(root);
    unordered_set<TreeNode*> visited;
    while (!stack.empty()) {
        TreeNode* node = stack.back();
        if (!node || (node->left == nullptr && node->right == nullptr) ||
            ((node->left == nullptr || visited.count(node->left)) && (node->right == nullptr || visited.count(node->right)))) {
            stack.pop_back();
            if (node) { result.push_back(node->val); visited.insert(node); }
        } else {
            if (node->right) stack.push_back(node->right);
            if (node->left) stack.push_back(node->left);
        }
    }
    return result;
}

class LRUCache {
    int capacity;
    list<pair<int,int>> items;
    unordered_map<int, list<pair<int,int>>::iterator> pos;
public:
    LRUCache(int cap) : capacity(cap) {}
    int get(int key) { if (!pos.count(key)) return -1; auto it = pos[key]; items.splice(items.begin(), items, it); return it->second; }
    void put(int key, int value) {
        if (pos.count(key)) { auto it = pos[key]; it->second = value; items.splice(items.begin(), items, it); return; }
        items.push_front({key, value}); pos[key] = items.begin();
        if ((int)items.size() > capacity) { pos.erase(items.back().first); items.pop_back(); }
    }
};

