static std::string calculateSlope(const std::vector<int>& p1, const std::vector<int>& p2) {
    int dx = p2[0] - p1[0];
    int dy = p2[1] - p1[1];
    if (dx == 0) {
        return "inf";
    }
    double slope = static_cast<double>(dy) / static_cast<double>(dx);
    return std::to_string(slope);
}

int maxPoints(const std::vector<std::vector<int>>& points) {
    int maxPoints = 0;
    for (size_t i = 0; i < points.size(); ++i) {
        std::unordered_map<std::string, int> slopeMap;
        int samePoint = 1;
        for (size_t j = i + 1; j < points.size(); ++j) {
            std::string slope = calculateSlope(points[i], points[j]);
            if (slope == "inf" && points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                ++samePoint;
            } else {
                ++slopeMap[slope];
            }
        }
        int localMax = 0;
        for (const auto& kv : slopeMap) {
            localMax = std::max(localMax, kv.second);
        }
        maxPoints = std::max(maxPoints, localMax + samePoint);
    }
    return maxPoints;
}

