int evalRPN(const std::vector<std::string>& tokens) {
    std::vector<int> stack;
    for (const std::string& token : tokens) {
        if (token == "+" || token == "-" || token == "*" || token == "/") {
            int rightOperand = stack.back();
            stack.pop_back();
            int leftOperand = stack.back();
            stack.pop_back();
            int result;
            if (token == "+") result = leftOperand + rightOperand;
            else if (token == "-") result = leftOperand - rightOperand;
            else if (token == "*") result = leftOperand * rightOperand;
            else result = leftOperand / rightOperand;
            stack.push_back(result);
        } else {
            stack.push_back(std::stoi(token));
        }
    }
    return stack[0];
}

