std::string reverseWords(const std::string& s) {
    std::vector<std::string> words;
    std::string token;
    for (char c : s) {
        if (c == ' ') {
            if (!token.empty()) {
                words.push_back(token);
                token.clear();
            }
        } else {
            token.push_back(c);
        }
    }
    if (!token.empty()) {
        words.push_back(token);
    }
    std::reverse(words.begin(), words.end());
    std::string result;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i) result.push_back(' ');
        result += words[i];
    }
    return result;
}

