int maximumGap(const std::vector<int>& nums) {
    if (nums.size() < 2) return 0;
    int minVal = *std::min_element(nums.begin(), nums.end());
    int maxVal = *std::max_element(nums.begin(), nums.end());
    if (minVal == maxVal) return 0;
    int bucketSize = std::max(1, (maxVal - minVal) / static_cast<int>(nums.size() - 1));
    int bucketCount = (maxVal - minVal + bucketSize - 1) / bucketSize;
    struct Bucket { long long min; long long max; };
    std::vector<Bucket> buckets(bucketCount, { std::numeric_limits<long long>::max(), std::numeric_limits<long long>::min() });
    for (int num : nums) {
        int index = (num - minVal) / bucketSize;
        if (buckets[index].min > num) buckets[index].min = num;
        if (buckets[index].max < num) buckets[index].max = num;
    }
    int maxGap = 0;
    long long prevMax = buckets[0].max;
    for (int i = 1; i < bucketCount; ++i) {
        if (buckets[i].min != std::numeric_limits<long long>::max()) {
            int gap = static_cast<int>(buckets[i].min - prevMax);
            if (gap > maxGap) maxGap = gap;
            prevMax = buckets[i].max;
        }
    }
    return maxGap;
}

