std::string fractionToDecimal(long long numerator, long long denominator) {
    if (numerator == 0) return "0";
    std::string result;
    if ((numerator > 0) != (denominator > 0)) result += '-';
    numerator = std::abs(numerator);
    denominator = std::abs(denominator);
    result += std::to_string(numerator / denominator);
    long long remainder = numerator % denominator;
    if (remainder == 0) return result;
    result += '.';
    std::unordered_map<long long, size_t> map;
    std::string fractionalPart;
    while (remainder != 0) {
        auto it = map.find(remainder);
        if (it != map.end()) {
            size_t idx = it->second;
            fractionalPart = fractionalPart.substr(0, idx) + '(' + fractionalPart.substr(idx) + ')';
            break;
        }
        map[remainder] = fractionalPart.size();
        remainder *= 10;
        fractionalPart += std::to_string(remainder / denominator);
        remainder %= denominator;
    }
    result += fractionalPart;
    return result;
}

