int rob(const std::vector<int>& nums) {
    if (nums.size() == 1) return nums[0];
    if (nums.size() == 2) return std::max(nums[0], nums[1]);

    auto helper = [](const std::vector<int>& arr) -> int {
        std::vector<int> dp(arr.size(), 0);
        dp[0] = arr[0];
        dp[1] = std::max(arr[0], arr[1]);
        for (size_t i = 2; i < arr.size(); ++i) {
            dp[i] = std::max(dp[i - 1], dp[i - 2] + arr[i]);
        }
        return dp[arr.size() - 1];
    };

    std::vector<int> slice1(nums.begin(), nums.end() - 1);
    std::vector<int> slice2(nums.begin() + 1, nums.end());

    return std::max(helper(slice1), helper(slice2));
}

