int findKthLargest(std::vector<int>& nums, int k) {
    auto partition = [&](int left, int right) -> int {
        int pivot = nums[(left + right) / 2];
        int i = left, j = right;
        while (i <= j) {
            while (nums[i] < pivot) ++i;
            while (nums[j] > pivot) --j;
            if (i <= j) {
                std::swap(nums[i], nums[j]);
                ++i;
                --j;
            }
        }
        return i - 1;
    };

    std::function<int(int, int, int)> quickSelect = [&](int left, int right, int target) -> int {
        int pivotIndex = partition(left, right);
        if (target == pivotIndex) return nums[target];
        else if (target < pivotIndex) return quickSelect(left, pivotIndex - 1, target);
        else return quickSelect(pivotIndex + 1, right, target);
    };

    return quickSelect(0, static_cast<int>(nums.size()) - 1, static_cast<int>(nums.size()) - k);
}

struct TrieNodeW { unordered_map<char, TrieNodeW*> children; bool isEnd=false; };
class WordDictionary {
    TrieNodeW* root;
    bool dfs(TrieNodeW* node, const string& word, int i) {
        if (i == (int)word.size()) return node->isEnd;
        char c = word[i];
        if (c == '.') {
            for (auto& p : node->children) if (dfs(p.second, word, i+1)) return true;
            return false;
        }
        if (!node->children.count(c)) return false;
        return dfs(node->children[c], word, i+1);
    }
public:
    WordDictionary() { root = new TrieNodeW(); }
    void addWord(string word) {
        TrieNodeW* node = root;
        for (char c : word) { if (!node->children.count(c)) node->children[c] = new TrieNodeW(); node = node->children[c]; }
        node->isEnd = true;
    }
    bool search(string word) { return dfs(root, word, 0); }
};

