    std::string end;
};

void backtrack(int i, int j, TrieNode* node, std::vector<std::vector<char>>& board, std::vector<std::string>& result, const std::vector<std::pair<int, int>>& dirs) {
    char c = board[i][j];
    auto it = node->children.find(c);
    if (it == node->children.end()) return;
    node = it->second;
    if (!node->end.empty()) {
        result.push_back(node->end);
        node->end.clear();
    }
    char temp = board[i][j];
    board[i][j] = '#';
    for (const auto& d : dirs) {
        int x = i + d.first;
        int y = j + d.second;
        if (x >= 0 && x < static_cast<int>(board.size()) && y >= 0 && y < static_cast<int>(board[0].size())) {
            backtrack(x, y, node, board, result, dirs);
        }
    }
    board[i][j] = temp;
}

std::vector<std::string> findWords(std::vector<std::vector<char>>& board, const std::vector<std::string>& words) {
    std::vector<std::string> result;
    TrieNode* trie = new TrieNode();
    for (const std::string& word : words) {
        TrieNode* node = trie;
        for (char ch : word) {
            if (node->children.find(ch) == node->children.end()) {
                node->children[ch] = new TrieNode();
            }
            node = node->children[ch];
        }
        node->end = word;
    }
    std::vector<std::pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    for (int i = 0; i < static_cast<int>(board.size()); ++i) {
        for (int j = 0; j < static_cast<int>(board[0].size()); ++j) {
            backtrack(i, j, trie, board, result, directions);
        }
    }
    std::sort(result.begin(), result.end());
    return result;
}

