bool containsNearbyAlmostDuplicate(const std::vector<long long>& nums, long long indexDiff, long long valueDiff) {
    std::unordered_map<long long, long long> buckets;
    long long bucketSize = valueDiff + 1;
    for (std::size_t i = 0; i < nums.size(); ++i) {
        long long num = nums[i];
        long long bucketId = num / bucketSize;
        if (num < 0 && num % bucketSize != 0) {
            --bucketId;
        }
        if (buckets.find(bucketId) != buckets.end() ||
            (buckets.find(bucketId - 1) != buckets.end() && std::llabs(num - buckets[bucketId - 1]) <= valueDiff) ||
            (buckets.find(bucketId + 1) != buckets.end() && std::llabs(num - buckets[bucketId + 1]) <= valueDiff)) {
            return true;
        }
        buckets[bucketId] = num;
        if (i >= static_cast<std::size_t>(indexDiff)) {
            long long oldNum = nums[i - indexDiff];
            long long oldBucketId = oldNum / bucketSize;
            if (oldNum < 0 && oldNum % bucketSize != 0) {
                --oldBucketId;
            }
            buckets.erase(oldBucketId);
        }
    }
    return false;
}

