std::vector<std::vector<int>> getSkyline(const std::vector<std::vector<int>>& buildings) {
    std::vector<std::vector<int>> points;
    points.reserve(buildings.size() * 2);
    for (const auto& b : buildings) {
        points.push_back({b[0], -b[2]}); // start
        points.push_back({b[1],  b[2]}); // end
    }
    std::sort(points.begin(), points.end(),
        [](const std::vector<int>& a, const std::vector<int>& b) {
            return a[0] == b[0] ? a[1] < b[1] : a[0] < b[0];
        });

    std::multiset<int> heights;
    heights.insert(0);
    int prevHeight = 0;
    std::vector<std::vector<int>> result;

    for (const auto& p : points) {
        if (p[1] < 0) {
            heights.insert(-p[1]);
        } else {
            auto it = heights.find(p[1]);
            if (it != heights.end()) heights.erase(it);
        }
        int currHeight = *heights.rbegin();
        if (currHeight != prevHeight) {
            result.push_back({p[0], currHeight});
            prevHeight = currHeight;
        }
    }
    return result;
}

