long long computeArea(long long ax1, long long ay1, long long ax2, long long ay2,
                      long long bx1, long long by1, long long bx2, long long by2) {
    long long area1 = (ax2 - ax1) * (ay2 - ay1);
    long long area2 = (bx2 - bx1) * (by2 - by1);
    long long overlapWidth = std::max(0LL, std::min(ax2, bx2) - std::max(ax1, bx1));
    long long overlapHeight = std::max(0LL, std::min(ay2, by2) - std::max(ay1, by1));
    long long overlapArea = overlapWidth * overlapHeight;
    return area1 + area2 - overlapArea;
}

