int calculate(const std::string& s) {
    std::vector<int> stack;
    int num = 0;
    char sign = '+';
    const size_t n = s.size();
    for (size_t i = 0; i < n; ++i) {
        char c = s[i];
        if (std::isdigit(static_cast<unsigned char>(c))) {
            num = num * 10 + (c - '0');
        }
        if ((!std::isdigit(static_cast<unsigned char>(c)) && c != ' ') || i == n - 1) {
            if (sign == '+') {
                stack.push_back(num);
            } else if (sign == '-') {
                stack.push_back(-num);
            } else if (sign == '*') {
                int prev = stack.back();
                stack.pop_back();
                stack.push_back(prev * num);
            } else if (sign == '/') {
                int prev = stack.back();
                stack.pop_back();
                stack.push_back(prev / num);
            }
            if (c != ' ') {
                sign = c;
            }
            num = 0;
        }
    }
    int result = 0;
    for (int v : stack) {
        result += v;
    }
    return result;
}

