    if (op == '-') return a - b;
    return a * b;
}

std::vector<int> compute(const std::string& expr, std::unordered_map<std::string, std::vector<int>>& memo) {
    auto it = memo.find(expr);
    if (it != memo.end()) return it->second;
    std::vector<int> results;
    for (size_t i = 0; i < expr.size(); ++i) {
        char c = expr[i];
        if (c == '+' || c == '-' || c == '*') {
            std::vector<int> left = compute(expr.substr(0, i), memo);
            std::vector<int> right = compute(expr.substr(i + 1), memo);
            for (int l : left) {
                for (int r : right) {
                    results.push_back(applyOp(l, r, c));
                }
            }
        }
    }
    if (results.empty()) {
        results.push_back(std::stoi(expr));
    }
    std::sort(results.begin(), results.end());
    memo[expr] = results;
    return results;
}

