int nthUglyNumber(int n) {
    std::vector<long long> uglyNumbers;
    uglyNumbers.push_back(1);
    std::size_t i2 = 0, i3 = 0, i5 = 0;
    while (uglyNumbers.size() < static_cast<std::size_t>(n)) {
        long long nextUgly = std::min({uglyNumbers[i2] * 2, uglyNumbers[i3] * 3, uglyNumbers[i5] * 5});
        uglyNumbers.push_back(nextUgly);
        if (nextUgly == uglyNumbers[i2] * 2) ++i2;
        if (nextUgly == uglyNumbers[i3] * 3) ++i3;
        if (nextUgly == uglyNumbers[i5] * 5) ++i5;
    }
    return static_cast<int>(uglyNumbers[n - 1]);
}

