int findMissingNumber(const std::vector<int>& nums) {
    size_t n = nums.size();
    long long expectedSum = (static_cast<long long>(n) * (n + 1)) / 2;
    long long actualSum = 0;
    for (size_t i = 0; i < n; ++i) {
        actualSum += nums[i];
    }
    return static_cast<int>(expectedSum - actualSum);
}

