static std::string helper(int num, const std::vector<std::string>& ones, const std::vector<std::string>& tens) {
    if (num == 0) {
        return "";
    } else if (num < 20) {
        return ones[num];
    } else if (num < 100) {
        std::string res = tens[num / 10];
        if (num % 10 != 0) {
            res += " " + ones[num % 10];
        }
        return res;
    } else {
        std::string res = ones[num / 100] + " Hundred";
        if (num % 100 != 0) {
            res += " " + helper(num % 100, ones, tens);
        }
        return res;
    }
}

static std::string trim(const std::string& s) {
    size_t start = 0;
    while (start < s.size() && s[start] == ' ') ++start;
    size_t end = s.size();
    while (end > start && s[end - 1] == ' ') --end;
    return s.substr(start, end - start);
}

std::string numberToWords(int num) {
    const std::vector<std::string> ones = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"};
    const std::vector<std::string> tens = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};
    const std::vector<std::string> thousands = {"", "Thousand", "Million", "Billion"};
    if (num == 0) return "Zero";
    std::string result = "";
    int i = 0;
    while (num > 0) {
        if (num % 1000 != 0) {
            result = helper(num % 1000, ones, tens) + " " + thousands[i] + " " + result;
        }
        num = num / 1000;
        ++i;
    }
    return trim(result);
}

