int hIndex(const std::vector<int>& citations) {
    int left = 0;
    int right = static_cast<int>(citations.size()) - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (static_cast<int>(citations.size()) - mid <= citations[mid]) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    return static_cast<int>(citations.size()) - left;
}

