int numSquares(int n) {
    const int INF = INT_MAX / 2;
    std::vector<int> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        int j = 1;
        while (j * j <= i) {
            dp[i] = std::min(dp[i], dp[i - j * j] + 1);
            ++j;
        }
    }
    return dp[n];
}

