#include <bits/stdc++.h>

std::vector<std::string> addOperators(const std::string& num, long long target) {
    std::vector<std::string> result;
    std::function<void(int, const std::string&, long long, long long)> backtrack =
        [&](int index, const std::string& path, long long value, long long prev) {
            if (index == static_cast<int>(num.size())) {
                if (value == target) result.push_back(path);
                return;
            }
            for (int i = index; i < static_cast<int>(num.size()); ++i) {
                if (i != index && num[index] == '0') break;
                std::string curStr = num.substr(index, i - index + 1);
                long long currNum = std::stoll(curStr);
                if (path.empty()) {
                    backtrack(i + 1, curStr, currNum, currNum);
                } else {
                    backtrack(i + 1, path + "*" + curStr, value - prev + prev * currNum, prev * currNum);
                    backtrack(i + 1, path + "+" + curStr, value + currNum, currNum);
                    backtrack(i + 1, path + "-" + curStr, value - currNum, -currNum);
                }
            }
        };
    backtrack(0, "", 0, 0);
    return result;
}

template<typename Iterator>
class PeekingIterator {
    Iterator it, end_;
    bool hasPeeked = false;
    typename std::iterator_traits<Iterator>::value_type peekedVal;
public:
    PeekingIterator(Iterator begin, Iterator end) : it(begin), end_(end) {}
    int peek() {
        if (!hasPeeked) { peekedVal = *it; ++it; hasPeeked = true; }
        return peekedVal;
    }
    int next() {
        if (hasPeeked) { hasPeeked = false; return peekedVal; }
        int v = *it; ++it; return v;
    }
    bool hasNext() { return hasPeeked || it != end_; }
};

