bool wordPattern(const std::string& pattern, const std::string& s) {
    std::vector<std::string> words;
    std::istringstream iss(s);
    std::string w;
    while (iss >> w) {
        words.push_back(w);
    }
    if (pattern.size() != words.size()) return false;
    std::unordered_map<char, std::string> patternToWord;
    std::unordered_map<std::string, char> wordToPattern;
    for (size_t i = 0; i < pattern.size(); ++i) {
        char p = pattern[i];
        const std::string& word = words[i];
        if (patternToWord.find(p) == patternToWord.end()) patternToWord[p] = word;
        if (wordToPattern.find(word) == wordToPattern.end()) wordToPattern[word] = p;
        if (patternToWord[p] != word || wordToPattern[word] != p) return false;
    }
    return true;
}

