class MedianFinder {
    priority_queue<int> small;
    priority_queue<int, vector<int>, greater<int>> large;
public:
    void addNum(int num) {
        small.push(num);
        large.push(small.top()); small.pop();
        if (large.size() > small.size()) { small.push(large.top()); large.pop(); }
    }
    double findMedian() {
        if (small.size() > large.size()) return small.top();
        return (small.top() + large.top()) / 2.0;
    }
};

string serialize(TreeNode* node) {
    if (!node) return "X,";
    return to_string(node->val) + "," + serialize(node->left) + serialize(node->right);
}
TreeNode* deserializeHelper(const vector<string>& nodes, int& idx) {
    if (idx >= (int)nodes.size()) return nullptr;
    string val = nodes[idx++];
    if (val == "X") return nullptr;
    TreeNode* node = new TreeNode(stoi(val));
    node->left = deserializeHelper(nodes, idx);
    node->right = deserializeHelper(nodes, idx);
    return node;
}
TreeNode* deserialize(const string& data) {
    vector<string> nodes;
    stringstream ss(data);
    string item;
    while (getline(ss, item, ',')) nodes.push_back(item);
    int idx = 0;
    return deserializeHelper(nodes, idx);
}

