std::string getHint(const std::string& secret, const std::string& guess) {
    int bulls = 0;
    int cows = 0;
    std::unordered_map<char, int> secretCount;
    std::unordered_map<char, int> guessCount;
    for (size_t i = 0; i < secret.size(); ++i) {
        if (secret[i] == guess[i]) {
            ++bulls;
        } else {
            ++secretCount[secret[i]];
            ++guessCount[guess[i]];
        }
    }
    for (const auto& kv : secretCount) {
        auto it = guessCount.find(kv.first);
        if (it != guessCount.end()) {
            cows += std::min(kv.second, it->second);
        }
    }
    return std::to_string(bulls) + "A" + std::to_string(cows) + "B";
}

