bool isValid(const std::string& str) {
    int balance = 0;
    for (char c : str) {
        if (c == '(') {
            ++balance;
        } else if (c == ')') {
            if (balance == 0) return false;
            --balance;
        }
    }
    return balance == 0;
}

std::vector<std::string> removeInvalidParentheses(const std::string& s) {
    std::unordered_map<std::string, int> level;
    level.emplace(s, 1);
    while (true) {
        std::vector<std::string> valid;
        for (const auto& kv : level) {
            if (isValid(kv.first)) {
                valid.push_back(kv.first);
            }
        }
        if (!valid.empty()) {
            return valid;
        }
        std::unordered_map<std::string, int> nextLevel;
        for (const auto& kv : level) {
            const std::string& str = kv.first;
            for (size_t i = 0; i < str.size(); ++i) {
                char c = str[i];
                if (c == '(' || c == ')') {
                    std::string newStr = str.substr(0, i) + str.substr(i + 1);
                    if (nextLevel.find(newStr) == nextLevel.end()) {
                        nextLevel.emplace(newStr, 1);
                    }
                }
            }
        }
        level = std::move(nextLevel);
    }
}

