bool isValid(const std::string& s) {
    return !(s.size() > 1 && s[0] == '0');
}

std::string addStrings(const std::string& a, const std::string& b) {
    int i = static_cast<int>(a.size()) - 1;
    int j = static_cast<int>(b.size()) - 1;
    int carry = 0;
    std::string res;
    while (i >= 0 || j >= 0 || carry) {
        int sum = carry;
        if (i >= 0) sum += a[i--] - '0';
        if (j >= 0) sum += b[j--] - '0';
        res.push_back('0' + (sum % 10));
        carry = sum / 10;
    }
    std::reverse(res.begin(), res.end());
    return res;
}

bool backtrack(const std::string& num, int start, const std::vector<std::string>& path) {
    if (start == static_cast<int>(num.size()) && path.size() >= 3) return true;
    for (int i = start; i < static_cast<int>(num.size()); ++i) {
        std::string currNum = num.substr(start, i - start + 1);
        if (!isValid(currNum)) continue;
        if (path.size() < 2) {
            std::vector<std::string> newPath = path;
            newPath.push_back(currNum);
            if (backtrack(num, i + 1, newPath)) return true;
        } else {
            std::string sum = addStrings(path[path.size() - 1], path[path.size() - 2]);
            if (sum == currNum) {
                std::vector<std::string> newPath = path;
                newPath.push_back(currNum);
                if (backtrack(num, i + 1, newPath)) return true;
            }
        }
    }
    return false;
}

bool isAdditiveNumber(const std::string& num) {
    return backtrack(num, 0, {});
}

class NumArray {
    int n; vector<int> tree, nums;
public:
    NumArray(vector<int>& in) { n = in.size(); tree.assign(n+1,0); nums.assign(n,0); for (int i=0;i<n;i++) update(i, in[i]); }
    void update(int index, int val) { int delta = val - nums[index]; nums[index]=val; for (int i=index+1;i<=n;i+=i&(-i)) tree[i]+=delta; }
    int prefixSum(int i) { int s=0; for (int idx=i+1; idx>0; idx-=idx&(-idx)) s+=tree[idx]; return s; }
    int sumRange(int left, int right) { return prefixSum(right) - (left>0?prefixSum(left-1):0); }
};

