int maxProfit(const std::vector<int>& prices) {
    long long buy = std::numeric_limits<long long>::min();
    long long sell = 0;
    long long cooldown = 0;
    for (int price : prices) {
        long long newBuy = std::max(buy, cooldown - price);
        long long newCooldown = std::max(cooldown, sell);
        long long newSell = std::max(sell, buy + price);
        buy = newBuy;
        sell = newSell;
        cooldown = newCooldown;
    }
    return static_cast<int>(std::max(sell, cooldown));
}

