std::vector<int> findMinHeightTrees(int n, const std::vector<std::vector<int>>& edges) {
    if (n == 1) return std::vector<int>{0};
    std::vector<std::vector<int>> graph(n);
    std::vector<int> degree(n, 0);
    for (const auto& edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].push_back(v);
        graph[v].push_back(u);
        ++degree[u];
        ++degree[v];
    }
    std::deque<int> queue;
    for (int i = 0; i < n; ++i) {
        if (degree[i] == 1) queue.push_back(i);
    }
    int remaining = n;
    while (remaining > 2) {
        int size = static_cast<int>(queue.size());
        remaining -= size;
        for (int i = 0; i < size; ++i) {
            int node = queue.front();
            queue.pop_front();
            for (int neighbor : graph[node]) {
                --degree[neighbor];
                if (degree[neighbor] == 1) queue.push_back(neighbor);
            }
        }
    }
    return std::vector<int>(queue.begin(), queue.end());
}

