std::string removeDuplicateLetters(const std::string& s) {
    std::unordered_map<char, int> lastOccurrence;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        lastOccurrence[s[i]] = i;
    }
    std::vector<char> stack;
    std::unordered_map<char, bool> seen;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        if (seen[s[i]]) continue;
        while (!stack.empty() && stack.back() > s[i] && lastOccurrence[stack.back()] > i) {
            seen[stack.back()] = false;
            stack.pop_back();
        }
        stack.push_back(s[i]);
        seen[s[i]] = true;
    }
    return std::string(stack.begin(), stack.end());
}

#include <bits/stdc++.h>

std::vector<int> countSmallerNumbersAfterSelf(std::vector<int> nums) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return {};
    std::vector<std::pair<int, int>> arr(n);
    for (int i = 0; i < n; ++i) arr[i] = {nums[i], i};
    std::vector<std::pair<int, int>> temp(n);
    std::vector<int> result(n, 0);
    std::function<void(int, int)> mergeSort = [&](int left, int right) {
        if (left >= right) return;
        int mid = (left + right) / 2;
        mergeSort(left, mid);
        mergeSort(mid + 1, right);
        int i = left, j = mid + 1, k = left;
        int rightCount = 0;
        while (i <= mid && j <= right) {
            if (arr[j].first < arr[i].first) {
                ++rightCount;
                temp[k++] = arr[j++];
            } else {
                result[arr[i].second] += rightCount;
                temp[k++] = arr[i++];
            }
        }
        while (i <= mid) {
            result[arr[i].second] += rightCount;
            temp[k++] = arr[i++];
        }
        while (j <= right) {
            temp[k++] = arr[j++];
        }
        for (int p = left; p <= right; ++p) {
            arr[p] = temp[p];
        }
    };
    mergeSort(0, n - 1);
    return result;
}

