int nthSuperUglyNumber(int n, const std::vector<int>& primes) {
    std::vector<long long> uglyNumbers;
    uglyNumbers.reserve(n);
    uglyNumbers.push_back(1);
    std::vector<int> indices(primes.size(), 0);
    while (static_cast<int>(uglyNumbers.size()) < n) {
        long long nextUgly = std::numeric_limits<long long>::max();
        for (size_t i = 0; i < primes.size(); ++i) {
            long long candidate = uglyNumbers[indices[i]] * static_cast<long long>(primes[i]);
            if (candidate < nextUgly) {
                nextUgly = candidate;
            }
        }
        uglyNumbers.push_back(nextUgly);
        for (size_t i = 0; i < primes.size(); ++i) {
            if (uglyNumbers[indices[i]] * static_cast<long long>(primes[i]) == nextUgly) {
                ++indices[i];
            }
        }
    }
    return static_cast<int>(uglyNumbers.back());
}

