int bulbSwitch(int n) {
    std::vector<bool> bulbs(n, false);
    for (int i = 1; i <= n; ++i) {
        for (int j = i - 1; j < n; j += i) {
            bulbs[j] = !bulbs[j];
        }
    }
    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (bulbs[i]) ++count;
    }
    return count;
}

