long long mergeSort(std::vector<long long>& sums, int left, int right, long long lower, long long upper) {
    if (left >= right) return 0;
    int mid = left + (right - left) / 2;
    long long count = mergeSort(sums, left, mid, lower, upper) + mergeSort(sums, mid + 1, right, lower, upper);
    int lo = mid + 1, hi = mid + 1;
    for (int i = left; i <= mid; ++i) {
        while (lo <= right && sums[lo] - sums[i] < lower) ++lo;
        while (hi <= right && sums[hi] - sums[i] <= upper) ++hi;
        count += (hi - lo);
    }
    std::vector<long long> temp;
    temp.reserve(right - left + 1);
    int i = left, j = mid + 1;
    while (i <= mid && j <= right) {
        if (sums[i] <= sums[j]) {
            temp.push_back(sums[i++]);
        } else {
            temp.push_back(sums[j++]);
        }
    }
    while (i <= mid) temp.push_back(sums[i++]);
    while (j <= right) temp.push_back(sums[j++]);
    std::copy(temp.begin(), temp.end(), sums.begin() + left);
    return count;
}

int countRangeSum(const std::vector<int>& nums, int lower, int upper) {
    std::vector<long long> prefixSums;
    prefixSums.reserve(nums.size() + 1);
    prefixSums.push_back(0);
    long long sum = 0;
    for (int num : nums) {
        sum += num;
        prefixSums.push_back(sum);
    }
    return static_cast<int>(mergeSort(prefixSums, 0, static_cast<int>(prefixSums.size()) - 1, lower, upper));
}

