std::vector<std::string> findItinerary(const std::vector<std::vector<std::string>>& tickets) {
    std::unordered_map<std::string, std::deque<std::string>> graph;
    for (size_t i = 0; i < tickets.size(); ++i) {
        const std::string& from = tickets[i][0];
        const std::string& to = tickets[i][1];
        graph[from].push_back(to);
    }
    for (auto& entry : graph) {
        std::vector<std::string> temp(entry.second.begin(), entry.second.end());
        std::sort(temp.begin(), temp.end());
        entry.second = std::deque<std::string>(temp.begin(), temp.end());
    }
    std::vector<std::string> path;
    path.push_back("JFK");
    std::function<bool()> dfs = [&]() -> bool {
        if (path.size() - 1 == tickets.size()) return true;
        const std::string& currentAirport = path.back();
        auto it = graph.find(currentAirport);
        if (it == graph.end() || it->second.empty()) return false;
        std::deque<std::string>& destinations = it->second;
        size_t originalSize = destinations.size();
        for (size_t i = 0; i < originalSize; ++i) {
            std::string nextDestination = destinations.front();
            destinations.pop_front();
            path.push_back(nextDestination);
            if (dfs()) return true;
            path.pop_back();
            destinations.push_front(nextDestination);
        }
        return false;
    };
    dfs();
    return path;
}

