int maxCoins(std::vector<int> nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> a;
    a.reserve(n + 2);
    a.push_back(1);
    for (int v : nums) a.push_back(v);
    a.push_back(1);
    std::vector<std::vector<int>> dp(n + 2, std::vector<int>(n + 2, 0));
    for (int len = 2; len <= n + 1; ++len) {
        for (int left = 0; left + len <= n + 1; ++left) {
            int right = left + len;
            for (int i = left + 1; i < right; ++i) {
                int candidate = dp[left][i] + dp[i][right] + a[left] * a[i] * a[right];
                dp[left][right] = std::max(dp[left][right], candidate);
            }
        }
    }
    return dp[0][n + 1];
}

#include <bits/stdc++.h>

std::vector<std::vector<int>> palindromePairs(const std::vector<std::string>& words) {
    std::unordered_map<std::string, int> indexMap;
    for (int i = 0; i < (int)words.size(); ++i) {
        indexMap[words[i]] = i;
    }

    auto isPalindrome = [&](const std::string& s, int l, int r) -> bool {
        while (l < r) {
            if (s[l] != s[r]) return false;
            ++l; --r;
        }
        return true;
    };

    std::vector<std::vector<int>> result;
    for (int i = 0; i < (int)words.size(); ++i) {
        const std::string& w = words[i];
        int n = (int)w.size();
        for (int cut = 0; cut <= n; ++cut) {
            // left = w[0, cut), right = w[cut, n)
            // If right part is palindrome, we can place reversed left after current word
            if (isPalindrome(w, cut, n - 1)) {
                std::string leftRev = w.substr(0, cut);
                std::reverse(leftRev.begin(), leftRev.end());
                auto it = indexMap.find(leftRev);
                if (it != indexMap.end() && it->second != i) {
                    result.push_back({i, it->second});
                }
            }
            // If left part is palindrome, we can place reversed right before current word
            if (cut > 0 && isPalindrome(w, 0, cut - 1)) {
                std::string rightRev = w.substr(cut);
                std::reverse(rightRev.begin(), rightRev.end());
                auto it = indexMap.find(rightRev);
                if (it != indexMap.end() && it->second != i) {
                    result.push_back({it->second, i});
                }
            }
        }
    }
    return result;
}

