std::pair<long long, long long> dfs(TreeNode* node) {
    if (!node) return {0, 0};
    auto left = dfs(node->left);
    auto right = dfs(node->right);
    long long withCurrent = node->val + left.second + right.second;
    long long withoutCurrent = std::max(left.first, left.second) + std::max(right.first, right.second);
    return {withCurrent, withoutCurrent};
}

long long rob(TreeNode* root) {
    auto result = dfs(root);
    return std::max(result.first, result.second);
}

