class SummaryRanges {
    map<int,int> intervals;
public:
    void addNum(int value) {
        auto it = intervals.upper_bound(value);
        bool mergeLeft = false, mergeRight = false;
        if (it != intervals.begin()) {
            auto prev = std::prev(it);
            if (prev->second >= value) return;
            if (prev->second == value - 1) mergeLeft = true;
        }
        if (it != intervals.end() && it->first == value + 1) mergeRight = true;
        if (mergeLeft && mergeRight) {
            auto prev = std::prev(it);
            prev->second = it->second;
            intervals.erase(it);
        } else if (mergeLeft) {
            std::prev(it)->second = value;
        } else if (mergeRight) {
            int end = it->second;
            intervals.erase(it);
            intervals[value] = end;
        } else {
            intervals[value] = value;
        }
    }
    vector<pair<int,int>> getIntervals() {
        vector<pair<int,int>> res;
        for (auto& p : intervals) res.push_back(p);
        return res;
    }
};

