        [](const std::vector<int>& a, const std::vector<int>& b) {
            if (a[0] == b[0]) return a[1] > b[1];
            return a[0] < b[0];
        });
    std::vector<int> dp(envelopes.size(), 1);
    for (size_t i = 1; i < envelopes.size(); ++i) {
