int maxSumSubarray(const std::vector<long long>& arr, int k) {
    long long best = LLONG_MIN;
    std::set<long long> prefixSet;
    prefixSet.insert(0);
    long long cur = 0;
    for (long long val : arr) {
        cur += val;
        auto it = prefixSet.lower_bound(cur - static_cast<long long>(k));
        if (it != prefixSet.end()) {
            long long candidate = cur - *it;
            if (candidate > best) best = candidate;
        }
        prefixSet.insert(cur);
    }
    return static_cast<int>(best);
}

int maxSumSubmatrix(const std::vector<std::vector<int>>& matrix, int k) {
    int maxSum = INT_MIN;
    int rows = static_cast<int>(matrix.size());
    int cols = static_cast<int>(matrix[0].size());
    for (int left = 0; left < cols; ++left) {
        std::vector<long long> temp(rows, 0);
        for (int right = left; right < cols; ++right) {
            for (int i = 0; i < rows; ++i) {
                temp[i] += matrix[i][right];
            }
            int current = maxSumSubarray(temp, k);
            if (current > maxSum) maxSum = current;
        }
    }
    return maxSum;
}

