bool canMeasureWater(int x, int y, int target) {
    std::queue<std::array<int, 2>> queue;
    queue.push({0, 0});
    std::unordered_set<std::string> visited;
    visited.insert("0,0");
    while (!queue.empty()) {
        std::array<int, 2> cur = queue.front();
        queue.pop();
        int currX = cur[0];
        int currY = cur[1];
        if (currX + currY == target) return true;
        std::vector<std::array<int, 2>> nextStates = {
            {x, currY},
            {currX, y},
            {0, currY},
            {currX, 0},
            {std::max(0, currX - (y - currY)), std::min(y, currY + currX)},
            {std::min(x, currX + currY), std::max(0, currY - (x - currX))}
        };
        for (const auto& nextState : nextStates) {
            std::string nextStateStr = std::to_string(nextState[0]) + "," + std::to_string(nextState[1]);
            if (visited.find(nextStateStr) == visited.end()) {
                queue.push(nextState);
                visited.insert(nextStateStr);
            }
        }
    }
    return false;
}

