std::vector<std::vector<int>> kSmallestPairs(const std::vector<int>& nums1, const std::vector<int>& nums2, int k) {
    std::vector<std::vector<int>> result;
    if (nums1.empty() || nums2.empty() || k == 0) return result;

    struct Node {
        long long sum;
        int i;
        int j;
        bool operator>(const Node& other) const {
            return sum > other.sum;
        }
    };

    int n1 = static_cast<int>(nums1.size());
    int n2 = static_cast<int>(nums2.size());

    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> minHeap;
    std::unordered_set<long long> visited;

    auto encode = [&](int i, int j) -> long long {
        return static_cast<long long>(i) * n2 + j;
    };

    // start with pair (0,0)
    minHeap.push({static_cast<long long>(nums1[0]) + nums2[0], 0, 0});
    visited.insert(encode(0, 0));

    while (!minHeap.empty() && static_cast<int>(result.size()) < k) {
        Node cur = minHeap.top();
        minHeap.pop();
        result.push_back({nums1[cur.i], nums2[cur.j]});

        // move in nums1
        if (cur.i + 1 < n1) {
            long long key = encode(cur.i + 1, cur.j);
            if (visited.find(key) == visited.end()) {
                minHeap.push({static_cast<long long>(nums1[cur.i + 1]) + nums2[cur.j], cur.i + 1, cur.j});
                visited.insert(key);
            }
        }
        // move in nums2
        if (cur.j + 1 < n2) {
            long long key = encode(cur.i, cur.j + 1);
            if (visited.find(key) == visited.end()) {
                minHeap.push({static_cast<long long>(nums1[cur.i]) + nums2[cur.j + 1], cur.i, cur.j + 1});
                visited.insert(key);
            }
        }
    }

    return result;
}

