int kthSmallest(const std::vector<std::vector<int>>& matrix, int k) {
    int n = static_cast<int>(matrix.size());
    int low = matrix[0][0];
    int high = matrix[n - 1][n - 1];
    while (low < high) {
        int mid = low + (high - low) / 2;
        int count = 0;
        int j = n - 1;
        for (int i = 0; i < n; ++i) {
            while (j >= 0 && matrix[i][j] > mid) {
                --j;
            }
            count += (j + 1);
        }
        if (count < k) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return low;
}

class RandomizedSet {
    vector<int> values; unordered_map<int,int> indexMap;
public:
    bool insert(int val) {
        if (indexMap.count(val)) return false;
        indexMap[val]=values.size(); values.push_back(val); return true;
    }
    bool remove(int val) {
        if (!indexMap.count(val)) return false;
        int idx=indexMap[val], last=values.back();
        values[idx]=last; indexMap[last]=idx;
        values.pop_back(); indexMap.erase(val); return true;
    }
    int getRandom() { return values[rand()%values.size()]; }
};

class Solution {
    ListNode* head;
public:
    Solution(ListNode* h) : head(h) {}
    int getRandom() {
        int result = 0, i = 1;
        for (ListNode* node = head; node; node = node->next, i++) if (rand() % i == 0) result = node->val;
        return result;
    }
};

class RandomizedCollection {
    vector<int> values;
    unordered_map<int, unordered_set<int>> idxMap;
public:
    bool insert(int val) {
        bool present = idxMap.count(val) && !idxMap[val].empty();
        idxMap[val].insert(values.size()); values.push_back(val);
        return !present;
    }
    bool remove(int val) {
        if (!idxMap.count(val) || idxMap[val].empty()) return false;
        int idx = *idxMap[val].begin();
        idxMap[val].erase(idx);
        int last = values.back(); int lastIdx = values.size()-1;
        values[idx] = last;
        if (idx != lastIdx) { idxMap[last].erase(lastIdx); idxMap[last].insert(idx); }
        values.pop_back();
        return true;
    }
    int getRandom() { return values[rand()%values.size()]; }
};

