class NestedInteger {
    bool is_int_;
    int value_;
    std::vector<NestedInteger> list_;
public:
    NestedInteger() : is_int_(false), value_(0) {}
    NestedInteger(int value) : is_int_(true), value_(value) {}
    bool isInteger() const { return is_int_; }
    int getInteger() const { return value_; }
    void setInteger(int value) { is_int_ = true; value_ = value; list_.clear(); }
    void add(const NestedInteger& ni) {
        if (is_int_) { is_int_ = false; list_.clear(); }
        list_.push_back(ni);
    }
    const std::vector<NestedInteger>& getList() const { return list_; }
};

NestedInteger deserialize(const std::string& s) {
    if (s.empty()) return NestedInteger();
    if (s[0] != '[') {
        return NestedInteger(std::stoi(s));
    }
    std::vector<NestedInteger> stack;
    std::string currNum;
    bool hasNum = false;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '[') {
            stack.push_back(NestedInteger());
        } else if (c == '-' || (c >= '0' && c <= '9')) {
            currNum += c;
            hasNum = true;
        } else if (c == ',' || c == ']') {
            if (hasNum) {
                stack.back().add(NestedInteger(std::stoi(currNum)));
                currNum.clear();
                hasNum = false;
            }
            if (c == ']') {
                NestedInteger top = stack.back();
                stack.pop_back();
                if (stack.empty()) {
                    return top;
                }
                stack.back().add(top);
            }
        }
    }
    return stack.empty() ? NestedInteger() : stack[0];
}

