int lengthLongestPath(const std::string& input) {
    int maxLen = 0;
    std::vector<int> depthLen(input.size() + 2, 0);
    size_t start = 0;
    while (start <= input.size()) {
        size_t end = input.find('\n', start);
        if (end == std::string::npos) end = input.size();
        std::string line = input.substr(start, end - start);
        int depth = 0;
        while (depth < static_cast<int>(line.size()) && line[depth] == '\t') {
            ++depth;
        }
        std::string name = line.substr(depth);
        if (name.find('.') != std::string::npos) {
            maxLen = std::max(maxLen, depthLen[depth] + static_cast<int>(name.length()));
        } else {
            depthLen[depth + 1] = depthLen[depth] + static_cast<int>(name.length()) + 1;
        }
        if (end == input.size()) break;
        start = end + 1;
    }
    return maxLen;
}

