char findTheDifference(const std::string& s, const std::string& t) {
    std::unordered_map<char, int> sCount;
    std::unordered_map<char, int> tCount;
    for (char c : s) {
        auto it = sCount.find(c);
        if (it != sCount.end()) {
            ++it->second;
        } else {
            sCount[c] = 1;
        }
    }
    for (char c : t) {
        auto it = tCount.find(c);
        if (it != tCount.end()) {
            ++it->second;
        } else {
            tCount[c] = 1;
        }
    }
    for (const auto& kv : tCount) {
        char c = kv.first;
        int tcnt = kv.second;
        auto it = sCount.find(c);
        if (it == sCount.end() || tcnt > it->second) {
            return c;
        }
    }
    return '\0';
}

