int lastRemaining(int n) {
    bool left = true;
    int remaining = n;
    int step = 1;
    int head = 1;
    while (remaining > 1) {
        if (left || (remaining % 2 == 1)) {
            head = head + step;
        }
        step = step * 2;
        remaining = remaining / 2;
        left = !left;
    }
    return head;
}

