bool isRectangleCover(const std::vector<std::vector<int>>& rectangles) {
    long long area = 0;
    long long minX = std::numeric_limits<long long>::max();
    long long minY = std::numeric_limits<long long>::max();
    long long maxX = std::numeric_limits<long long>::min();
    long long maxY = std::numeric_limits<long long>::min();
    std::unordered_set<std::string> corners;
    for (const auto& rectangle : rectangles) {
        long long x = rectangle[0];
        long long y = rectangle[1];
        long long a = rectangle[2];
        long long b = rectangle[3];
        area += (a - x) * (b - y);
        if (x < minX) minX = x;
        if (y < minY) minY = y;
        if (a > maxX) maxX = a;
        if (b > maxY) maxY = b;
        std::vector<std::pair<long long, long long>> points = {
            {x, y}, {x, b}, {a, y}, {a, b}
        };
        for (const auto& point : points) {
            std::string key = std::to_string(point.first) + "," + std::to_string(point.second);
            if (corners.find(key) != corners.end()) {
                corners.erase(key);
            } else {
                corners.insert(key);
            }
        }
    }
    if (area != (maxX - minX) * (maxY - minY)) {
        return false;
    }
    if (corners.size() != 4) {
        return false;
    }
    std::string c1 = std::to_string(minX) + "," + std::to_string(minY);
    std::string c2 = std::to_string(minX) + "," + std::to_string(maxY);
    std::string c3 = std::to_string(maxX) + "," + std::to_string(minY);
    std::string c4 = std::to_string(maxX) + "," + std::to_string(maxY);
    if (corners.find(c1) == corners.end() ||
        corners.find(c2) == corners.end() ||
        corners.find(c3) == corners.end() ||
        corners.find(c4) == corners.end()) {
        return false;
    }
    return true;
}

