long long rotateFunction(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    long long maxVal = LLONG_MIN;
    long long totalSum = 0;
    long long initialSum = 0;
    for (int i = 0; i < n; ++i) {
        totalSum += nums[i];
        initialSum += static_cast<long long>(i) * nums[i];
    }
    maxVal = initialSum;
    for (int k = 1; k < n; ++k) {
        initialSum = initialSum + totalSum - static_cast<long long>(n) * nums[n - k];
        maxVal = std::max(maxVal, initialSum);
    }
    return maxVal;
}

