std::string decodeString(const std::string& s) {
    std::vector<std::string> stackString;
    std::vector<int> stackNumber;
    std::string currentString;
    int currentNumber = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        if (std::isdigit(static_cast<unsigned char>(s[i]))) {
            currentNumber = currentNumber * 10 + (s[i] - '0');
        } else if (s[i] >= 'a' && s[i] <= 'z') {
            currentString.push_back(s[i]);
        } else if (s[i] == '[') {
            stackString.push_back(currentString);
            stackNumber.push_back(currentNumber);
            currentString.clear();
            currentNumber = 0;
        } else if (s[i] == ']') {
            int number = stackNumber.back();
            stackNumber.pop_back();
            std::string previousString = stackString.back();
            stackString.pop_back();
            std::string repeated;
            repeated.reserve(currentString.size() * number);
            for (int k = 0; k < number; ++k) {
                repeated += currentString;
            }
            currentString = previousString + repeated;
        }
    }
    return currentString;
}

