double dfs(const std::string& a, const std::string& b,
           const std::unordered_map<std::string, std::vector<std::pair<std::string, double>>>& graph,
           std::unordered_set<std::string>& visited) {
    if (a == b) return 1.0;
    visited.insert(a);
    auto it = graph.find(a);
    if (it == graph.end()) return -1.0;
    for (const auto& neighbor_pair : it->second) {
        const std::string& neighbor = neighbor_pair.first;
        double value = neighbor_pair.second;
        if (neighbor == b && visited.find(neighbor) == visited.end()) return value;
        if (visited.find(neighbor) == visited.end()) {
            double result = dfs(neighbor, b, graph, visited);
            if (result != -1.0) return value * result;
        }
    }
    return -1.0;
}

std::vector<double> calcEquation(const std::vector<std::vector<std::string>>& equations,
                                 const std::vector<double>& values,
                                 const std::vector<std::vector<std::string>>& queries) {
    std::unordered_map<std::string, std::vector<std::pair<std::string, double>>> graph;
    for (size_t i = 0; i < equations.size(); ++i) {
        const std::string& a = equations[i][0];
        const std::string& b = equations[i][1];
        double val = values[i];
        if (graph.find(a) == graph.end()) graph[a] = {};
        if (graph.find(b) == graph.end()) graph[b] = {};
        graph[a].push_back({b, val});
        graph[b].push_back({a, 1.0 / val});
    }

    std::vector<double> result;
    for (const auto& q : queries) {
        const std::string& a = q[0];
        const std::string& b = q[1];
        if (graph.find(a) == graph.end() || graph.find(b) == graph.end()) {
            result.push_back(-1.0);
        } else {
            std::unordered_set<std::string> visited;
            result.push_back(dfs(a, b, graph, visited));
        }
    }
    return result;
}

