int findNthDigit(long long n) {
    long long length = 1;
    long long count = 9;
    long long start = 1;
    while (n > length * count) {
        n -= length * count;
        ++length;
        count *= 10;
        start *= 10;
    }
    start += (n - 1) / length;
    std::string s = std::to_string(start);
    return s[(n - 1) % length] - '0';
}

