bool canCross(const std::vector<int>& stones) {
    int n = static_cast<int>(stones.size());
    std::unordered_set<int> stoneSet(stones.begin(), stones.end());
    std::unordered_map<std::string, bool> memo;
    std::function<bool(int, int)> dfs = [&](int stone, int k) -> bool {
        std::string key = std::to_string(stone) + "," + std::to_string(k);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        if (stone == stones[n - 1]) return true;
        for (int jump = k - 1; jump <= k + 1; ++jump) {
            if (jump <= 0) continue;
            if (stoneSet.find(stone + jump) != stoneSet.end()) {
                if (dfs(stone + jump, jump)) {
                    memo[key] = true;
                    return true;
                }
            }
        }
        memo[key] = false;
        return false;
    };
    return dfs(stones[0], 1);
}

