std::string toHex(int num) {
    if (num == 0) return "0";
    std::string result;
    bool isNegative = num < 0;
    long long n = num;
    if (isNegative) n += (1LL << 32);
    while (n > 0) {
        int remainder = n % 16;
        char ch;
        if (remainder < 10) ch = static_cast<char>(48 + remainder);
        else ch = static_cast<char>(87 + remainder);
        result.insert(result.begin(), ch);
        n /= 16;
    }
    return result;
}

