int longestPalindrome(const std::string& s) {
    std::unordered_map<char, int> charCount;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        auto it = charCount.find(c);
        if (it != charCount.end()) {
            it->second++;
        } else {
            charCount[c] = 1;
        }
    }
    int length = 0;
    bool oddFound = false;
    for (const auto& kv : charCount) {
        int cnt = kv.second;
        length += cnt - (cnt % 2);
        if (cnt % 2 != 0) oddFound = true;
    }
    if (oddFound) ++length;
    return length;
}

