long long trapRainWater(std::vector<std::vector<int>>& heightMap) {
    int m = static_cast<int>(heightMap.size());
    int n = static_cast<int>(heightMap[0].size());
    std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));
    std::vector<std::array<int, 3>> pq;
    long long volume = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == 0 || j == 0 || i == m - 1 || j == n - 1) {
                visited[i][j] = true;
                pq.push_back({heightMap[i][j], i, j});
            }
        }
    }
    std::sort(pq.begin(), pq.end(), [](const std::array<int,3>& a, const std::array<int,3>& b) {
        return a[0] < b[0];
    });
    const std::array<std::array<int,2>,4> directions = {{{{-1,0}},{{1,0}},{{0,-1}},{{0,1}}}};
    while (!pq.empty()) {
        std::array<int,3> cur = pq.front();
        pq.erase(pq.begin());
        int height = cur[0];
        int x = cur[1];
        int y = cur[2];
        for (const auto& d : directions) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && !visited[nx][ny]) {
                volume += std::max(0, height - heightMap[nx][ny]);
                heightMap[nx][ny] = std::max(heightMap[nx][ny], height);
                visited[nx][ny] = true;
                pq.push_back({heightMap[nx][ny], nx, ny});
                std::sort(pq.begin(), pq.end(), [](const std::array<int,3>& a, const std::array<int,3>& b) {
                    return a[0] < b[0];
                });
            }
        }
    }
    return volume;
}

