long long splitArray(const std::vector<int>& nums, int k) {
    long long left = *std::max_element(nums.begin(), nums.end());
    long long right = std::accumulate(nums.begin(), nums.end(), 0LL);
    while (left < right) {
        long long mid = (left + right) / 2;
        int count = 1;
        long long sum = 0;
        for (int num : nums) {
            sum += num;
            if (sum > mid) {
                ++count;
                sum = num;
            }
        }
        if (count > k) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

