int strongPasswordChecker(const std::string& password) {
    int missingTypes = 3;
    bool one = false, upper = false, digit = false;
    int totalLength = static_cast<int>(password.size());
    int changes = 0;

    for (int i = 0; i < totalLength; ++i) {
        if (password[i] >= 'a' && password[i] <= 'z') one = true;
        else if (password[i] >= 'A' && password[i] <= 'Z') upper = true;
        else if (password[i] >= '0' && password[i] <= '9') digit = true;
    }
    if (one) missingTypes--;
    if (upper) missingTypes--;
    if (digit) missingTypes--;

    if (totalLength < 6) {
        changes += 6 - totalLength;
    } else if (totalLength > 20) {
        changes += totalLength - 20;
    }

    int i = 2;
    while (i < totalLength) {
        if (password[i] == password[i - 1] && password[i] == password[i - 2]) {
            int length = 2;
            while (i + 1 < totalLength && password[i] == password[i + 1]) {
                ++i;
                ++length;
            }
            changes += length / 3;
        }
        ++i;
    }

    return std::max(missingTypes, changes);
}

