std::vector<std::vector<int>> pacificAtlantic(const std::vector<std::vector<int>>& heights) {
    if (heights.empty() || heights[0].empty()) {
        return {};
    }
    int m = static_cast<int>(heights.size());
    int n = static_cast<int>(heights[0].size());
    std::vector<std::vector<bool>> pacific(m, std::vector<bool>(n, false));
    std::vector<std::vector<bool>> atlantic(m, std::vector<bool>(n, false));

    std::function<void(int, int, std::vector<std::vector<bool>>&)> dfs = [&](int row, int col, std::vector<std::vector<bool>>& visited) {
        visited[row][col] = true;
        const int directions[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (const auto& d : directions) {
            int nr = row + d[0];
            int nc = col + d[1];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && heights[nr][nc] >= heights[row][col]) {
                dfs(nr, nc, visited);
            }
        }
    };

    for (int i = 0; i < m; ++i) {
        dfs(i, 0, pacific);
    }
    for (int j = 0; j < n; ++j) {
        dfs(0, j, pacific);
    }

    for (int i = 0; i < m; ++i) {
        dfs(i, n - 1, atlantic);
    }
    for (int j = 0; j < n; ++j) {
        dfs(m - 1, j, atlantic);
    }

    std::vector<std::vector<int>> result;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (pacific[i][j] && atlantic[i][j]) {
                result.push_back({i, j});
            }
        }
    }
    return result;
}

