struct TrieNode {
    TrieNode* child[2];
    TrieNode() : child{nullptr, nullptr} {}
};

int findMaximumXOR(const std::vector<int>& nums) {
    int maximumXOR = 0;
    TrieNode* root = new TrieNode();

    for (int num : nums) {
        TrieNode* node = root;
        for (int i = 31; i >= 0; --i) {
            int bit = (num >> i) & 1;
            if (!node->child[bit]) {
                node->child[bit] = new TrieNode();
            }
            node = node->child[bit];
        }
    }

    for (int num : nums) {
        TrieNode* node = root;
        int currentXOR = 0;
        for (int i = 31; i >= 0; --i) {
            int bit = (num >> i) & 1;
            if (node->child[1 - bit]) {
                currentXOR |= (1 << i);
                node = node->child[1 - bit];
            } else {
                node = node->child[bit];
            }
        }
        maximumXOR = std::max(maximumXOR, currentXOR);
    }

    return maximumXOR;
}

