    std::vector<Any> vecValue;
    bool isInt;
    Any(int v) : intValue(v), isInt(true) {}
    Any(const std::vector<Any>& v) : vecValue(v), isInt(false) {}
    Any(std::vector<Any>&& v) : vecValue(std::move(v)), isInt(false) {}
};

std::vector<Any> construct(const std::vector<std::vector<int>>& grid) {
    std::function<std::vector<Any>(int, int, int)> constructQuadTree;
    constructQuadTree = [&](int x, int y, int n) -> std::vector<Any> {
        bool isLeaf = true;
        int val = grid[x][y];
        for (int i = x; i < x + n; ++i) {
            for (int j = y; j < y + n; ++j) {
                if (grid[i][j] != val) {
                    isLeaf = false;
                    break;
                }
            }
            if (!isLeaf) break;
        }
        if (isLeaf) {
            return std::vector<Any>{Any(1), Any(val)};
        }
        std::vector<Any> node;
        node.push_back(Any(0));
        node.push_back(Any(0));
        int half = n / 2;
        node.push_back(Any(constructQuadTree(x, y, half)));
        node.push_back(Any(constructQuadTree(x, y + half, half)));
        node.push_back(Any(constructQuadTree(x + half, y, half)));
        node.push_back(Any(constructQuadTree(x + half, y + half, half)));
        return node;
    };
    return constructQuadTree(0, 0, static_cast<int>(grid.size()));
}

