int minMutation(const std::string& startGene, const std::string& endGene, const std::vector<std::string>& bank) {
    std::unordered_set<std::string> bankSet(bank.begin(), bank.end());
    std::queue<std::pair<std::string, int>> q;
    q.push({startGene, 0});
    std::unordered_set<std::string> visited;
    visited.insert(startGene);
    const char chars[4] = {'A', 'C', 'G', 'T'};
    while (!q.empty()) {
        std::pair<std::string, int> front = q.front();
        q.pop();
        std::string currentGene = front.first;
        int steps = front.second;
        if (currentGene == endGene) {
            return steps;
        }
        for (int i = 0; i < 8; ++i) {
            for (char c : chars) {
                std::string nextGene = currentGene.substr(0, i) + c + currentGene.substr(i + 1);
                if (bankSet.find(nextGene) != bankSet.end() && visited.find(nextGene) == visited.end()) {
                    q.push({nextGene, steps + 1});
                    visited.insert(nextGene);
                }
            }
        }
    }
    return -1;
}

