class AllOne {
    struct Node { int count; unordered_set<string> keys; Node* prev; Node* next; Node(int c):count(c),prev(nullptr),next(nullptr){} };
    Node *head, *tail;
    unordered_map<string, Node*> keyNode;
    Node* insertAfter(Node* node, int count) {
        Node* n = new Node(count);
        n->prev = node; n->next = node->next; node->next->prev = n; node->next = n;
        return n;
    }
    void remove(Node* node) { node->prev->next = node->next; node->next->prev = node->prev; }
public:
    AllOne() { head = new Node(0); tail = new Node(0); head->next = tail; tail->prev = head; }
    void inc(string key) {
        if (!keyNode.count(key)) {
            Node* n = (head->next->count == 1) ? head->next : insertAfter(head, 1);
            n->keys.insert(key); keyNode[key] = n;
        } else {
            Node* node = keyNode[key]; node->keys.erase(key);
            Node* n = (node->next->count == node->count+1) ? node->next : insertAfter(node, node->count+1);
            n->keys.insert(key); keyNode[key] = n;
            if (node->keys.empty()) remove(node);
        }
    }
    void dec(string key) {
        Node* node = keyNode[key]; node->keys.erase(key);
        if (node->count == 1) { keyNode.erase(key); }
        else {
            Node* n = (node->prev->count == node->count-1) ? node->prev : nullptr;
            if (!n) { n = new Node(node->count-1); n->prev = node->prev; n->next = node; node->prev->next = n; node->prev = n; }
            n->keys.insert(key); keyNode[key] = n;
        }
        if (node->keys.empty()) remove(node);
    }
    string getMaxKey() { return tail->prev == head ? "" : *tail->prev->keys.begin(); }
    string getMinKey() { return head->next == tail ? "" : *head->next->keys.begin(); }
};

