std::vector<int> findRightInterval(const std::vector<std::vector<int>>& intervals) {
    std::vector<int> result(intervals.size());
    std::vector<std::pair<int, int>> intervalIndices;
    intervalIndices.reserve(intervals.size());
    for (size_t i = 0; i < intervals.size(); ++i) {
        intervalIndices.emplace_back(intervals[i][0], static_cast<int>(i));
    }
    std::sort(intervalIndices.begin(), intervalIndices.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            return a.first < b.first;
        });
    for (size_t i = 0; i < intervals.size(); ++i) {
        int target = intervals[i][1];
        int left = 0;
        int right = static_cast<int>(intervals.size()) - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (intervalIndices[mid].first >= target) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        result[i] = left < static_cast<int>(intervals.size()) ? intervalIndices[left].second : -1;
    }
    return result;
}

