        pCount[ch]++;
    }

    int left = 0;
    int right = 0;
    int pLen = static_cast<int>(p.size());

    while (right < static_cast<int>(s.size())) {
        char rc = s[right];
        if (sCount.find(rc) == sCount.end()) sCount[rc] = 0;
        sCount[rc]++;

        if (right - left + 1 == pLen) {
            bool isAnagram = true;
            for (const auto& kv : pCount) {
                char ch = kv.first;
                int cnt = kv.second;
                if (sCount[ch] != cnt) {
                    isAnagram = false;
                    break;
                }
            }
            if (isAnagram) {
                result.push_back(left);
            }

            char lc = s[left];
            sCount[lc]--;
            if (sCount[lc] == 0) {
                sCount.erase(lc);
            }
            left++;
        }
        right++;
    }

    return result;
}

