long long findKthNumber(long long n, long long k) {
    long long cur = 1;
    k--;
    while (k > 0) {
        long long step = 0;
        long long first = cur;
        long long last = cur + 1;
        while (first <= n) {
            step += std::min(n + 1, last) - first;
            first *= 10;
            last *= 10;
        }
        if (k >= step) {
            k -= step;
            cur++;
        } else {
            k--;
            cur *= 10;
        }
    }
    return cur;
}

