int arrangeCoins(int n) {
    long long left = 1, right = n;
    while (left <= right) {
        long long mid = (left + right) / 2;
        long long sum = mid * (mid + 1) / 2;
        if (sum <= n) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return static_cast<int>(right);
}

