struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr;
    while (head) {
        ListNode* nxt = head->next;
        head->next = prev;
        prev = head;
        head = nxt;
    }
    return prev;
}

ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
    ListNode* reversedL1 = reverseList(l1);
    ListNode* reversedL2 = reverseList(l2);
    ListNode* dummy = new ListNode(0);
    ListNode* current = dummy;
    int carry = 0;
    while (reversedL1 || reversedL2 || carry) {
        int sum = (reversedL1 ? reversedL1->val : 0) + (reversedL2 ? reversedL2->val : 0) + carry;
        carry = sum / 10;
        current->next = new ListNode(sum % 10);
        current = current->next;
        reversedL1 = reversedL1 ? reversedL1->next : nullptr;
        reversedL2 = reversedL2 ? reversedL2->next : nullptr;
    }
    return reverseList(dummy->next);
}

