bool circularArrayLoop(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    for (int i = 0; i < n; ++i) {
        bool direction = nums[i] > 0;
        int slow = i, fast = i;
        while (true) {
            slow = nextIndex(nums, slow, direction);
            if (slow == -1) break;
            fast = nextIndex(nums, fast, direction);
            if (fast == -1) break;
            fast = nextIndex(nums, fast, direction);
            if (fast == -1) break;
            if (slow == fast) {
                if (slow != nextIndex(nums, slow, direction))
                    return true;
                else
                    break;
            }
        }
    }
    return false;
}

