class LFUCache {
    int capacity, minFreq;
    unordered_map<int,int> keyVal, keyFreq;
    unordered_map<int, list<int>> freqKeys;
    unordered_map<int, list<int>::iterator> keyIter;
public:
    LFUCache(int cap) : capacity(cap), minFreq(0) {}
    void touch(int key) {
        int freq = keyFreq[key]; freqKeys[freq].erase(keyIter[key]);
        if (freqKeys[freq].empty()) { freqKeys.erase(freq); if (minFreq == freq) minFreq++; }
        keyFreq[key] = freq+1; freqKeys[freq+1].push_front(key); keyIter[key] = freqKeys[freq+1].begin();
    }
    int get(int key) { if (!keyVal.count(key)) return -1; touch(key); return keyVal[key]; }
    void put(int key, int value) {
        if (capacity <= 0) return;
        if (keyVal.count(key)) { keyVal[key]=value; touch(key); return; }
        if ((int)keyVal.size() >= capacity) {
            int oldest = freqKeys[minFreq].back(); freqKeys[minFreq].pop_back();
            if (freqKeys[minFreq].empty()) freqKeys.erase(minFreq);
            keyVal.erase(oldest); keyFreq.erase(oldest); keyIter.erase(oldest);
        }
        keyVal[key]=value; keyFreq[key]=1; freqKeys[1].push_front(key); keyIter[key]=freqKeys[1].begin(); minFreq=1;
    }
};

