std::string validIPAddress(const std::string& queryIP) {
    if (queryIP.find('.') != std::string::npos) {
        std::vector<std::string> parts = split(queryIP, '.');
        if (parts.size() != 4) return "Neither";
        for (const std::string& part : parts) {
            if (part.empty()) return "Neither";
            for (char c : part) {
                if (!std::isdigit(static_cast<unsigned char>(c))) return "Neither";
            }
            if (part.size() > 1 && part[0] == '0') return "Neither";
            try {
                int val = std::stoi(part);
                if (val < 0 || val > 255) return "Neither";
            } catch (...) {
                return "Neither";
            }
        }
        return "IPv4";
    } else if (queryIP.find(':') != std::string::npos) {
        std::vector<std::string> parts = split(queryIP, ':');
        if (parts.size() != 8) return "Neither";
        for (const std::string& part : parts) {
            if (part.empty() || part.size() > 4) return "Neither";
            for (char c : part) {
                if (!std::isdigit(static_cast<unsigned char>(c)) &&
                    !(c >= 'a' && c <= 'f') &&
                    !(c >= 'A' && c <= 'F')) {
                    return "Neither";
                }
            }
        }
        return "IPv6";
    } else {
        return "Neither";
    }
}

