bool makesquare(std::vector<int> matchsticks) {
    long long totalLength = 0;
    for (int len : matchsticks) {
        totalLength += len;
    }
    if (totalLength % 4 != 0) return false;
    int sideLength = static_cast<int>(totalLength / 4);
    std::vector<int> sides(4, 0);
    std::sort(matchsticks.begin(), matchsticks.end(), std::greater<int>());
    std::function<bool(int)> backtrack = [&](int index) -> bool {
        if (index == static_cast<int>(matchsticks.size())) {
            return sides[0] == sideLength && sides[1] == sideLength && sides[2] == sideLength && sides[3] == sideLength;
        }
        for (int i = 0; i < 4; ++i) {
            if (sides[i] + matchsticks[index] > sideLength) continue;
            sides[i] += matchsticks[index];
            if (backtrack(index + 1)) return true;
            sides[i] -= matchsticks[index];
        }
        return false;
    };
    return backtrack(0);
}

#include <bits/stdc++.h>

bool canIWin(int maxChoosableInteger, int desiredTotal) {
    int maxSum = maxChoosableInteger * (maxChoosableInteger + 1) / 2;
    if (maxSum < desiredTotal) return false;
    if (desiredTotal <= 0) return true;
    std::unordered_map<int, bool> memo;
    std::function<bool(int, int)> dfs = [&](int used, int total) -> bool {
        auto it = memo.find(used);
        if (it != memo.end()) return it->second;
        for (int i = 1; i <= maxChoosableInteger; ++i) {
            int bit = 1 << (i - 1);
            if ((used & bit) == 0) {
                if (total + i >= desiredTotal) {
                    memo[used] = true;
                    return true;
                }
                if (!dfs(used | bit, total + i)) {
                    memo[used] = true;
                    return true;
                }
            }
        }
        memo[used] = false;
        return false;
    };
    return dfs(0, 0);
}

