int findMaxForm(const std::vector<std::string>& strs, int m, int n) {
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));
    for (const std::string& str : strs) {
        int zeros = 0, ones = 0;
        for (char c : str) {
            if (c == '0') ++zeros;
            else ++ones;
