int largestPalindromeProduct(int n) {
    if (n == 1) {
        return 9 % 1337;
    }
    long long upper = 1;
    for (int i = 0; i < n; ++i) upper *= 10;
    upper -= 1;
    long long lower = 1;
    for (int i = 1; i < n; ++i) lower *= 10;
    long long pow10n = 1;
    for (int i = 0; i < n; ++i) pow10n *= 10;
    long long maxPalindrome = 0;
    for (long long left = upper; left >= lower; --left) {
        long long pal = left * pow10n + reverseNumber(left);
        for (long long i = upper; i >= lower; --i) {
            if (pal % i == 0) {
                long long j = pal / i;
                if (j >= lower && j <= upper) {
                    maxPalindrome = pal;
                    break;
                }
            }
        }
        if (maxPalindrome) break;
    }
    return static_cast<int>(maxPalindrome % 1337);
}

