std::string reduceBoard(const std::string& s) {
    std::string board = s;
    bool changed = true;
    while (changed) {
        changed = false;
        for (size_t i = 0; i < board.size();) {
            size_t j = i;
            while (j < board.size() && board[j] == board[i]) ++j;
            if (j - i >= 3) {
                board.erase(i, j - i);
                changed = true;
                break;
            } else {
                i = j;
            }
        }
    }
    return board;
}

int findMinStep(const std::string& board, const std::string& hand) {
    std::unordered_map<std::string, int> memo;
    std::function<int(const std::string&, const std::string&)> dfs =
        [&](const std::string& b, const std::string& h) -> int {
            std::string key = b + ',' + h;
            auto it = memo.find(key);
            if (it != memo.end()) return it->second;
            if (b.empty()) return 0;
            int best = INT_MAX;
            for (size_t i = 0; i < h.size(); ++i) {
                std::string newHand = h.substr(0, i) + h.substr(i + 1);
                for (size_t pos = 0; pos <= b.size(); ++pos) {
                    std::string newBoard = b.substr(0, pos) + h[i] + b.substr(pos);
                    newBoard = reduceBoard(newBoard);
                    if (newBoard.empty()) {
                        memo[key] = 1;
                        return 1;
                    }
                    if (!newHand.empty()) {
                        int sub = dfs(newBoard, newHand);
                        if (sub != -1) {
                            best = std::min(best, 1 + sub);
                        }
                    }
                }
            }
            if (best == INT_MAX) best = -1;
            memo[key] = best;
            return best;
        };
    return dfs(board, hand);
}

