std::vector<std::vector<int>> findSubsequences(const std::vector<int>& nums) {
    std::set<std::vector<int>> result;
    std::vector<int> current;
    std::function<void(int)> backtrack = [&](int start) {
        if (current.size() >= 2) {
            result.insert(current);
        }
        for (int i = start; i < static_cast<int>(nums.size()); ++i) {
            if (current.empty() || nums[i] >= current.back()) {
                current.push_back(nums[i]);
                backtrack(i + 1);
                current.pop_back();
            }
        }
    };
    backtrack(0);
    return std::vector<std::vector<int>>(result.begin(), result.end());
}

