        if (index == static_cast<int>(nums.size())) {
            if (sum == target) ++count;
            return;
        }
        backtrack(index + 1, sum + nums[index]);
        backtrack(index + 1, sum - nums[index]);
    };
    backtrack(0, 0);
    return count;
}

