long long reversePairs(std::vector<int> nums) {
    std::vector<int> temp(nums.size());
    std::function<long long(int,int)> mergeCount = [&](int left, int right) -> long long {
        if (left >= right) return 0;
        int mid = left + (right - left) / 2;
        long long cnt = mergeCount(left, mid) + mergeCount(mid + 1, right);
        int j = mid + 1;
        for (int i = left; i <= mid; ++i) {
            while (j <= right && static_cast<long long>(nums[i]) > 2LL * nums[j]) ++j;
            cnt += (j - (mid + 1));
        }
        int p = left, q = mid + 1, k = left;
        while (p <= mid && q <= right) {
            if (nums[p] <= nums[q]) temp[k++] = nums[p++];
            else temp[k++] = nums[q++];
        }
        while (p <= mid) temp[k++] = nums[p++];
        while (q <= right) temp[k++] = nums[q++];
        for (int i = left; i <= right; ++i) nums[i] = temp[i];
        return cnt;
    };
    return mergeCount(0, static_cast<int>(nums.size()) - 1);
}

