class Solution {
    std::vector<std::vector<int>> rects;
    std::vector<long long> weights;
    long long totalWeight;
public:
    Solution(const std::vector<std::vector<int>>& rects) : rects(rects) {
        weights.reserve(rects.size());
        totalWeight = 0;
        for (const auto& rect : rects) {
            long long weight = static_cast<long long>(rect[2] - rect[0] + 1) * (rect[3] - rect[1] + 1);
            weights.push_back(weight);
            totalWeight += weight;
        }
    }
    std::vector<int> pick() {
        static std::mt19937_64 rng(std::random_device{}());
        std::uniform_int_distribution<long long> dist(0, totalWeight - 1);
        long long rand = dist(rng);
        long long cumulativeWeight = 0;
        for (size_t i = 0; i < rects.size(); i++) {
            cumulativeWeight += weights[i];
            if (rand < cumulativeWeight) {
                auto& rect = rects[i];
                long long pointsInRect = rand - (cumulativeWeight - weights[i]);
                long long width = rect[2] - rect[0] + 1;
                int x = rect[0] + (int)(pointsInRect % width);
                int y = rect[1] + (int)(pointsInRect / width);
                return {x, y};
            }
        }
        return {};
    }
};

