int findMaximizedCapital(int k, int w, const std::vector<int>& profits, const std::vector<int>& capital) {
    std::vector<std::pair<int, int>> projects;
    projects.reserve(profits.size());
    for (size_t i = 0; i < profits.size(); ++i) {
        projects.emplace_back(profits[i], capital[i]);
    }
    std::sort(projects.begin(), projects.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            return a.second < b.second;
        });
    std::vector<int> availableProjects;
    size_t i = 0;
    while (k > 0) {
        while (i < projects.size() && projects[i].second <= w) {
            availableProjects.push_back(projects[i].first);
            ++i;
        }
        if (availableProjects.empty()) break;
        std::sort(availableProjects.begin(), availableProjects.end(), std::greater<int>());
        w += availableProjects[0];
        availableProjects.erase(availableProjects.begin());
        --k;
    }
    return w;
}

