int findRotateSteps(const std::string& ring, const std::string& key) {
    int n = static_cast<int>(ring.size());
    int m = static_cast<int>(key.size());
    const int INF = INT_MAX / 2;
    std::vector<std::vector<int>> dp(m, std::vector<int>(n, INF));
    for (int j = 0; j < n; ++j) {
        if (ring[j] == key[0]) {
            dp[0][j] = std::min(dp[0][j], std::min(j, n - j) + 1);
        }
    }
    for (int i = 1; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            for (int k = 0; k < n; ++k) {
                if (ring[k] == key[i - 1]) {
                    int diff = std::abs(j - k);
                    int step = std::min(diff, n - diff);
                    dp[i][j] = std::min(dp[i][j], dp[i - 1][k] + step + 1);
                }
            }
        }
    }
    int minSteps = INF;
    for (int j = 0; j < n; ++j) {
        if (ring[j] == key[m - 1]) {
            minSteps = std::min(minSteps, dp[m - 1][j]);
        }
    }
    return minSteps;
}

