long long findMinMoves(const std::vector<int>& machines) {
    long long totalDresses = std::accumulate(machines.begin(), machines.end(), 0LL);
    long long n = machines.size();
    if (n == 0) return 0;
    if (totalDresses % n != 0) return -1;
    long long averageDressesPerMachine = totalDresses / n;
    long long maxMoves = 0;
    long long currentImbalance = 0;
    for (size_t i = 0; i < machines.size(); ++i) {
        currentImbalance += static_cast<long long>(machines[i]) - averageDressesPerMachine;
        maxMoves = std::max(maxMoves, std::abs(currentImbalance));
        maxMoves = std::max(maxMoves, static_cast<long long>(machines[i]) - averageDressesPerMachine);
    }
    return maxMoves;
}

