class Solution {
    int m, n, total;
    unordered_map<int,int> mapping;
public:
    Solution(int mm, int nn) : m(mm), n(nn), total(mm*nn) {}
    vector<int> flip() {
        int r = rand() % total; total--;
        int x = mapping.count(r) ? mapping[r] : r;
        mapping[r] = mapping.count(total) ? mapping[total] : total;
        return {x / n, x % n};
    }
    void reset() { total = m*n; mapping.clear(); }
};

