int findLUSlength(const std::vector<std::string>& strs) {
    std::unordered_map<std::string, int> count;
    for (const auto& str : strs) {
        ++count[str];
    }

    std::vector<std::string> uniqueStrs;
    for (const auto& kv : count) {
        if (kv.second == 1) {
            uniqueStrs.push_back(kv.first);
        }
    }

    if (uniqueStrs.empty()) return -1;

    std::sort(uniqueStrs.begin(), uniqueStrs.end(),
              [](const std::string& a, const std::string& b) {
                  return a.size() > b.size();
              });

    for (const auto& candidate : uniqueStrs) {
        bool isSubseq = false;
        for (const auto& s : strs) {
            if (candidate == s) continue;
            if (isSubsequenceOf(candidate, s)) {
                isSubseq = true;
                break;
            }
        }
        if (!isSubseq) return static_cast<int>(candidate.size());
    }

    return -1;
}

