int pickIndex(const std::vector<int>& w) {
    double totalSum = 0;
    for (size_t i = 0; i < w.size(); ++i) {
        totalSum += w[i];
    }
    static thread_local std::mt19937 gen(std::random_device{}());
    std::uniform_real_distribution<double> dist(0.0, totalSum);
    double randomNum = dist(gen);
    double cumulativeSum = 0;
    for (size_t i = 0; i < w.size(); ++i) {
        cumulativeSum += w[i];
        if (cumulativeSum >= randomNum) {
            return static_cast<int>(i);
        }
    }
    return static_cast<int>(w.size() - 1);
}

