int getMinimumDifference(TreeNode* root) {
    int minDiff = std::numeric_limits<int>::max();
    int prevVal = 0;
    bool hasPrev = false;
    std::function<void(TreeNode*)> inorder = [&](TreeNode* node) {
        if (node) {
            inorder(node->left);
            if (hasPrev) {
                int diff = std::abs(node->val - prevVal);
                if (diff < minDiff) minDiff = diff;
            }
            prevVal = node->val;
            hasPrev = true;
            inorder(node->right);
        }
    };
    inorder(root);
    return minDiff;
}

