    int rows = board.size();
    int cols = board[0].size();
    int row = click[0];
    int col = click[1];
    if (board[row][col] == 'M') {
        board[row][col] = 'X';
    } else {
        int count = 0;
        for (int i = -1; i <= 1; ++i) {
            for (int j = -1; j <= 1; ++j) {
                int newRow = row + i;
                int newCol = col + j;
                if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && board[newRow][newCol] == 'M') {
                    ++count;
                }
            }
        }
        if (count == 0) {
            board[row][col] = 'B';
            dfs(board, row, col);
        } else {
            board[row][col] = static_cast<char>('0' + count);
        }
    }
    return board;
}

