static const std::string base62_chars = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

static std::unordered_map<std::string, std::string> long_to_short;
static std::unordered_map<std::string, std::string> short_to_long;
static long long counter = 1;

static std::string encodeBase62(long long num) {
    std::string s;
    while (num > 0) {
        s.push_back(base62_chars[num % 62]);
        num /= 62;
    }
    if (s.empty()) s.push_back(base62_chars[0]);
    std::reverse(s.begin(), s.end());
    return s;
}

std::string encode(const std::string& longUrl) {
    auto it = long_to_short.find(longUrl);
    if (it != long_to_short.end()) {
        return it->second;
    }
    std::string code = encodeBase62(counter++);
    std::string shortUrl = "http://tinyurl.com/" + code;
    long_to_short[longUrl] = shortUrl;
    short_to_long[shortUrl] = longUrl;
    return shortUrl;
}

std::string decode(const std::string& shortUrl) {
    auto it = short_to_long.find(shortUrl);
    if (it != short_to_long.end()) {
        return it->second;
    }
    return shortUrl;
}

