std::string complexNumberMultiply(const std::string& num1, const std::string& num2) {
    size_t plusPos1 = num1.find('+');
    int num1Real = std::stoi(num1.substr(0, plusPos1));
    int num1Imaginary = std::stoi(num1.substr(plusPos1 + 1, num1.size() - plusPos1 - 2));

    size_t plusPos2 = num2.find('+');
    int num2Real = std::stoi(num2.substr(0, plusPos2));
    int num2Imaginary = std::stoi(num2.substr(plusPos2 + 1, num2.size() - plusPos2 - 2));

    int resultReal = num1Real * num2Real - num1Imaginary * num2Imaginary;
    int resultImaginary = num1Real * num2Imaginary + num1Imaginary * num2Real;

    return std::to_string(resultReal) + "+" + std::to_string(resultImaginary) + "i";
}

