std::string reverseStrII(const std::string& s, int k) {
    std::string result;
    for (size_t i = 0; i < s.size(); i += 2 * static_cast<size_t>(k)) {
        size_t first_end = std::min(i + static_cast<size_t>(k), s.size());
        std::string reversed = s.substr(i, first_end - i);
        std::reverse(reversed.begin(), reversed.end());
        size_t second_start = first_end;
        size_t second_end = std::min(i + 2 * static_cast<size_t>(k), s.size());
        result += reversed + s.substr(second_start, second_end - second_start);
    }
    return result;
}

