std::vector<std::vector<int>> updateMatrix(const std::vector<std::vector<int>>& mat) {
    std::size_t rows = mat.size();
    std::size_t cols = mat[0].size();
    std::vector<std::pair<int, int>> directions = { {-1, 0}, {1, 0}, {0, -1}, {0, 1} };
    std::queue<std::pair<int, int>> queue;
    std::vector<std::vector<int>> result(rows, std::vector<int>(cols, INT_MAX));

    for (std::size_t i = 0; i < rows; ++i) {
        for (std::size_t j = 0; j < cols; ++j) {
            if (mat[i][j] == 0) {
                queue.push({static_cast<int>(i), static_cast<int>(j)});
                result[i][j] = 0;
            }
        }
    }

    while (!queue.empty()) {
        auto current = queue.front();
        queue.pop();
        int x = current.first;
        int y = current.second;
        for (const auto& dir : directions) {
            int newX = x + dir.first;
            int newY = y + dir.second;
            if (newX >= 0 && newX < static_cast<int>(rows) && newY >= 0 && newY < static_cast<int>(cols) && result[newX][newY] > result[x][y] + 1) {
                result[newX][newY] = result[x][y] + 1;
                queue.push({newX, newY});
            }
        }
    }
    return result;
}

