int removeBoxes(const std::vector<int>& boxes) {
    struct Key {
        int l, r, k;
        bool operator==(const Key& other) const noexcept {
            return l == other.l && r == other.r && k == other.k;
        }
    };
    struct KeyHash {
        std::size_t operator()(const Key& key) const noexcept {
            std::size_t h1 = static_cast<std::size_t>(key.l);
            std::size_t h2 = static_cast<std::size_t>(key.r);
            std::size_t h3 = static_cast<std::size_t>(key.k);
            return (h1 * 1000003) ^ (h2 * 9176) ^ (h3 * 131);
        }
    };
    std::unordered_map<Key, int, KeyHash> memo;
    std::function<int(int,int,int)> dp = [&](int l, int r, int k) -> int {
        if (l > r) return 0;
        while (r > l && boxes[r] == boxes[r - 1]) {
            --r;
            ++k;
        }
        Key key{l, r, k};
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int best = dp(l, r - 1, 0) + (k + 1) * (k + 1);
        for (int i = l; i < r; ++i) {
            if (boxes[i] == boxes[r]) {
                int cand = dp(l, i, k + 1) + dp(i + 1, r - 1, 0);
                if (cand > best) best = cand;
            }
        }
        memo[key] = best;
        return best;
    };
    return dp(0, static_cast<int>(boxes.size()) - 1, 0);
}

