#include <bits/stdc++.h>

int checkRecord(int n) {
    const int MOD = 1000000007;
    std::vector<std::vector<std::vector<long long>>> dp(n + 1,
        std::vector<std::vector<long long>>(2, std::vector<long long>(3, 0)));
    dp[0][0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int a = 0; a <= 1; ++a) {
            for (int l = 0; l <= 2; ++l) {
                long long cur = dp[i][a][l];
                if (!cur) continue;
                // add 'P'
                dp[i + 1][a][0] = (dp[i + 1][a][0] + cur) % MOD;
                // add 'L' if allowed
                if (l < 2) {
                    dp[i + 1][a][l + 1] = (dp[i + 1][a][l + 1] + cur) % MOD;
                }
                // add 'A' if not used yet
                if (a == 0) {
                    dp[i + 1][1][0] = (dp[i + 1][1][0] + cur) % MOD;
                }
            }
        }
    }
    long long res = 0;
    for (int a = 0; a <= 1; ++a) {
        for (int l = 0; l <= 2; ++l) {
            res = (res + dp[n][a][l]) % MOD;
        }
    }
    return static_cast<int>(res);
}

