int nextGreaterElement(int n) {
    std::string numStr = std::to_string(n);
    int i = static_cast<int>(numStr.size()) - 2;
    while (i >= 0 && numStr[i] >= numStr[i + 1]) {
        i--;
    }
    if (i < 0) return -1;
    int j = static_cast<int>(numStr.size()) - 1;
    while (j > i && numStr[j] <= numStr[i]) {
        j--;
    }
    std::string numArr = numStr;
    std::swap(numArr[i], numArr[j]);
    std::string right = numArr.substr(i + 1);
    std::sort(right.begin(), right.end());
    numArr = numArr.substr(0, i + 1) + right;
    long long result = std::stoll(numArr);
    return result > 2147483647LL ? -1 : static_cast<int>(result);
}

