QuadNode intersect(const QuadNode& quadTree1, const QuadNode& quadTree2) {
    if (quadTree1.leaf && quadTree2.leaf) {
        return QuadNode{1, quadTree1.val | quadTree2.val, {}};
    }
    if (quadTree1.leaf) {
        return quadTree1.val ? quadTree1 : quadTree2;
    }
    if (quadTree2.leaf) {
        return quadTree2.val ? quadTree2 : quadTree1;
    }
    return QuadNode{
        0,
        0,
        {
            intersect(quadTree1.children[0], quadTree2.children[0]),
            intersect(quadTree1.children[1], quadTree2.children[1]),
            intersect(quadTree1.children[2], quadTree2.children[2]),
            intersect(quadTree1.children[3], quadTree2.children[3])
