std::vector<std::vector<int>> matrixReshape(const std::vector<std::vector<int>>& mat, int r, int c) {
    int originalRows = mat.size();
    int originalColumns = mat[0].size();
    if (originalRows * originalColumns != r * c) {
        return mat;
    }
    std::vector<std::vector<int>> reshapedMatrix(r, std::vector<int>(c));
    int index = 0;
    for (int i = 0; i < r; ++i) {
        for (int j = 0; j < c; ++j) {
