int findPaths(int m, int n, int maxMove, int startRow, int startColumn) {
    const int MOD = 1000000007;
    const std::vector<std::pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    std::unordered_map<std::string, int> memo;
    std::function<int(int, int, int)> dfs = [&](int row, int col, int moves) -> int {
        if (row < 0 || row >= m || col < 0 || col >= n) return 1;
        if (moves <= 0) return 0;
        std::string key = std::to_string(row) + "," + std::to_string(col) + "," + std::to_string(moves);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        long long paths = 0;
        for (const auto& dir : directions) {
            paths = (paths + dfs(row + dir.first, col + dir.second, moves - 1)) % MOD;
        }
        memo[key] = static_cast<int>(paths);
        return memo[key];
    };
    return dfs(startRow, startColumn, maxMove);
}

