static long long cross(const std::pair<int,int>& O,
                       const std::pair<int,int>& A,
                       const std::pair<int,int>& B) {
    return (long long)(A.first - O.first) * (B.second - O.second) -
           (long long)(A.second - O.second) * (B.first - O.first);
}

std::vector<std::vector<int>> outerTrees(std::vector<std::vector<int>>& trees) {
    int n = static_cast<int>(trees.size());
    if (n <= 1) return trees;
    std::vector<std::pair<int,int>> pts;
    pts.reserve(n);
    for (auto &p : trees) pts.emplace_back(p[0], p[1]);
    std::sort(pts.begin(), pts.end());

    bool collinear = true;
    for (int i = 2; i < n; ++i) {
        if (cross(pts[0], pts[1], pts[i]) != 0) {
            collinear = false;
            break;
        }
    }
    if (collinear) {
        std::vector<std::vector<int>> res;
        res.reserve(n);
        for (int i = n - 1; i >= 0; --i) {
            res.push_back({pts[i].first, pts[i].second});
        }
        return res;
    }

    std::vector<std::pair<int,int>> lower, upper;
    for (const auto &p : pts) {
        while (lower.size() >= 2 && cross(lower[lower.size()-2], lower[lower.size()-1], p) < 0)
            lower.pop_back();
        lower.push_back(p);
    }
    for (int i = n - 1; i >= 0; --i) {
        const auto &p = pts[i];
        while (upper.size() >= 2 && cross(upper[upper.size()-2], upper[upper.size()-1], p) < 0)
            upper.pop_back();
        upper.push_back(p);
    }
    lower.pop_back();
    upper.pop_back();
    std::vector<std::pair<int,int>> hull;
    hull.reserve(lower.size() + upper.size());
    hull.insert(hull.end(), lower.begin(), lower.end());
    hull.insert(hull.end(), upper.begin(), upper.end());

    std::vector<std::vector<int>> result;
    result.reserve(hull.size());
    for (const auto &p : hull) {
        result.push_back({p.first, p.second});
    }
    return result;
}

