bool isValid(const std::string& code) {
    std::vector<std::string> stack;
    std::size_t i = 0;
    const std::size_t n = code.size();
    while (i < n) {
        if (code[i] != '<') {
            if (stack.empty()) return false;
            ++i;
            continue;
        }
        if (i + 9 <= n && code.substr(i, 9) == "<![CDATA[") {
            if (stack.empty()) return false;
            i += 9;
            std::size_t end = code.find("]]>", i);
            if (end == std::string::npos) return false;
            i = end + 3;
        } else if (i + 2 < n && code[i + 1] == '/') {
            std::size_t j = i + 2;
            std::size_t gt = code.find('>', j);
            if (gt == std::string::npos) return false;
            std::string tag = code.substr(j, gt - j);
            if (tag.empty() || tag.size() > 9) return false;
            for (char c : tag) if (c < 'A' || c > 'Z') return false;
            if (stack.empty() || stack.back() != tag) return false;
            stack.pop_back();
            i = gt + 1;
            if (stack.empty() && i != n) return false;
        } else {
            std::size_t j = i + 1;
            std::size_t gt = code.find('>', j);
            if (gt == std::string::npos) return false;
            std::string tag = code.substr(j, gt - j);
            if (tag.empty() || tag.size() > 9) return false;
            for (char c : tag) if (c < 'A' || c > 'Z') return false;
            stack.push_back(tag);
            i = gt + 1;
        }
    }
    return stack.empty();
}

