            std::string content = file.substr(openPos + 1, closePos - openPos - 1);
            contentMap[content].push_back(directory + '/' + filename);
        }
    }
    std::vector<std::vector<std::string>> result;
    for (auto& kv : contentMap) {
        if (kv.second.size() > 1) {
            result.push_back(std::move(kv.second));
        }
    }
    return result;
}

