int leastInterval(const std::vector<char>& tasks, int n) {
    std::unordered_map<char, int> frequencyMap;
    for (char task : tasks) {
        ++frequencyMap[task];
    }

    int maxFrequency = 0;
    int maxFrequencyCount = 0;
    for (const auto& entry : frequencyMap) {
        if (entry.second > maxFrequency) {
            maxFrequency = entry.second;
            maxFrequencyCount = 1;
        } else if (entry.second == maxFrequency) {
            ++maxFrequencyCount;
        }
    }

    int intervals = (maxFrequency - 1) * (n + 1) + maxFrequencyCount;
    return std::max(static_cast<int>(tasks.size()), intervals);
}

