class MyCircularQueue {
    int capacity;
    std::vector<int> queue;
    int head, tail, size;
public:
    MyCircularQueue(int k) : capacity(k), queue(k), head(0), tail(-1), size(0) {}
    bool enQueue(int value) {
        if (size == capacity) return false;
        tail = (tail + 1) % capacity;
        queue[tail] = value;
        size++;
        return true;
    }
    bool deQueue() {
        if (size == 0) return false;
        head = (head + 1) % capacity;
        size--;
        return true;
    }
    int Front() { return size == 0 ? -1 : queue[head]; }
    int Rear() { return size == 0 ? -1 : queue[tail]; }
    bool isEmpty() { return size == 0; }
    bool isFull() { return size == capacity; }
};

