int kInversePairs(int n, int k) {
    const int MOD = 1000000007;
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(k + 1, 0));
    for (int i = 0; i <= n; ++i) {
        dp[i][0] = 1;
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= k; ++j) {
            long long sum = 0;
            for (int p = 0; p <= i - 1 && p <= j; ++p) {
                sum = (sum + dp[i - 1][j - p]) % MOD;
            }
            dp[i][j] = static_cast<int>(sum);
        }
    }
    return dp[n][k];
}

