struct Node {
    int val;
    int listIdx;
    int elemIdx;
};

struct Compare {
    bool operator()(const Node& a, const Node& b) const {
        return a.val > b.val;
    }
};

std::vector<int> smallestRange(const std::vector<std::vector<int>>& nums) {
    std::priority_queue<Node, std::vector<Node>, Compare> minHeap;
    int maxVal = std::numeric_limits<int>::min();
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        if (!nums[i].empty()) {
            int v = nums[i][0];
            minHeap.push({v, i, 0});
            maxVal = std::max(maxVal, v);
        }
    }
    std::vector<int> smallestRange = {std::numeric_limits<int>::min(), std::numeric_limits<int>::max()};
    long long bestWidth = std::numeric_limits<long long>::max();
    while (minHeap.size() == nums.size()) {
        Node cur = minHeap.top();
        minHeap.pop();
        long long width = static_cast<long long>(maxVal) - cur.val;
        if (width < bestWidth) {
            bestWidth = width;
            smallestRange[0] = cur.val;
            smallestRange[1] = maxVal;
        }
        if (cur.elemIdx + 1 < static_cast<int>(nums[cur.listIdx].size())) {
            int nextVal = nums[cur.listIdx][cur.elemIdx + 1];
            minHeap.push({nextVal, cur.listIdx, cur.elemIdx + 1});
            maxVal = std::max(maxVal, nextVal);
        } else {
            break;
        }
    }
    return smallestRange;
}

