std::vector<int> findExclusiveTimes(int n, const std::vector<std::string>& logs) {
    std::vector<int> stack;
    std::vector<int> exclusiveTimes(n, 0);
    int prevTime = 0;
    for (const std::string& log : logs) {
        size_t pos1 = log.find(':');
        size_t pos2 = log.find(':', pos1 + 1);
        int functionId = std::stoi(log.substr(0, pos1));
        std::string eventType = log.substr(pos1 + 1, pos2 - pos1 - 1);
        int timestamp = std::stoi(log.substr(pos2 + 1));
        if (eventType == "start") {
            if (!stack.empty()) {
                exclusiveTimes[stack.back()] += timestamp - prevTime;
            }
            stack.push_back(functionId);
            prevTime = timestamp;
        } else {
            exclusiveTimes[stack.back()] += timestamp - prevTime + 1;
            stack.pop_back();
            prevTime = timestamp + 1;
        }
    }
    return exclusiveTimes;
}

