int numDecodings(const std::string& s) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(s.size());
    std::vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= n; ++i) {
        if (s[i - 1] != '*') {
            if (s[i - 1] != '0') {
                dp[i] += dp[i - 1];
            }
            if (i >= 2 && (s[i - 2] == '1' || (s[i - 2] == '2' && s[i - 1] <= '6'))) {
                dp[i] += dp[i - 2];
            }
        } else {
            dp[i] += dp[i - 1] * 9;
            if (i >= 2) {
                if (s[i - 2] == '1') {
                    dp[i] += dp[i - 2] * 9;
                } else if (s[i - 2] == '2') {
                    dp[i] += dp[i - 2] * 6;
                }
            }
        }
        dp[i] %= MOD;
    }
    return static_cast<int>(dp[n]);
}

