std::string solveEquation(const std::string& equation) {
    long long leftX = 0, leftVal = 0, rightX = 0, rightVal = 0;
    bool left = true;
    long long num = 0;
    int sign = 1;
    for (size_t i = 0; i < equation.size(); ++i) {
        char c = equation[i];
        if (std::isdigit(static_cast<unsigned char>(c))) {
            num = num * 10 + (c - '0');
        } else if (c == 'x') {
            if (num == 0) num = 1;
            if (left) leftX += sign * num;
            else rightX += sign * num;
            num = 0;
        } else if (c == '+' || c == '-') {
            if (num != 0) {
                if (left) leftVal += sign * num;
                else rightVal += sign * num;
                num = 0;
            }
            sign = (c == '+') ? 1 : -1;
        } else if (c == '=') {
            left = false;
            sign = 1;
        }
    }
    if (num != 0) {
        if (left) leftVal += sign * num;
        else rightVal += sign * num;
    }
    long long newX = leftX - rightX;
    long long newVal = rightVal - leftVal;
    if (newX == 0 && newVal == 0) return "Infinite solutions";
    if (newX == 0) return "No solution";
    return "x=" + std::to_string(newVal / newX);
}

