struct MyCircularDequeResult {
    std::function<bool(int)> addFront;
    std::function<bool(int)> addRear;
    std::function<bool()> deleteFront;
    std::function<bool()> deleteRear;
    std::function<int()> getFront;
    std::function<int()> getRear;
    std::function<bool()> isEmpty;
    std::function<bool()> isFull;
};

MyCircularDequeResult MyCircularDeque(int k) {
    int capacity = k;
    auto size = std::make_shared<int>(0);
    auto head = std::make_shared<int>(0);
    auto tail = std::make_shared<int>(0);
    auto data = std::make_shared<std::vector<int>>(k, 0);

    MyCircularDequeResult result;

    result.addFront = [capacity, size, head, tail, data](int value) -> bool {
        if (*size == capacity) return false;
        *head = (*head - 1 + capacity) % capacity;
        (*data)[*head] = value;
        (*size)++;
        return true;
    };

    result.addRear = [capacity, size, head, tail, data](int value) -> bool {
        if (*size == capacity) return false;
        (*data)[*tail] = value;
        *tail = (*tail + 1) % capacity;
        (*size)++;
        return true;
    };

    result.deleteFront = [capacity, size, head, tail]( ) -> bool {
        if (*size == 0) return false;
        *head = (*head + 1) % capacity;
        (*size)--;
        return true;
    };

    result.deleteRear = [capacity, size, head, tail]( ) -> bool {
        if (*size == 0) return false;
        *tail = (*tail - 1 + capacity) % capacity;
        (*size)--;
        return true;
    };

    result.getFront = [capacity, size, head, data]() -> int {
        if (*size == 0) return -1;
        return (*data)[*head];
    };

    result.getRear = [capacity, size, tail, data]() -> int {
        if (*size == 0) return -1;
        int index = (*tail - 1 + capacity) % capacity;
        return (*data)[index];
    };

    result.isEmpty = [size]() -> bool {
        return *size == 0;
    };

    result.isFull = [size, capacity]() -> bool {
        return *size == capacity;
    };

    return result;
}

