std::string replaceWords(const std::vector<std::string>& dictionary, const std::string& sentence) {
    struct Node {
        std::unordered_map<char, Node*> child;
        std::string word;
    };
    Node* trie = new Node();
    for (const std::string& w : dictionary) {
        Node* node = trie;
        for (char ch : w) {
            auto it = node->child.find(ch);
            if (it == node->child.end()) {
                Node* nxt = new Node();
                node->child[ch] = nxt;
                node = nxt;
            } else {
                node = it->second;
            }
        }
        node->word = w;
    }

    std::vector<std::string> words;
    std::istringstream iss(sentence);
    std::string token;
    while (iss >> token) {
        words.push_back(token);
    }

    for (std::string& w : words) {
        Node* node = trie;
        for (char ch : w) {
            auto it = node->child.find(ch);
            if (it == node->child.end()) break;
            node = it->second;
            if (!node->word.empty()) {
                w = node->word;
                break;
            }
        }
    }

    std::string result;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i) result.push_back(' ');
        result += words[i];
    }
    return result;
}

