            radiantQueue.push_back(radiantQueue.front() + n);
            radiantQueue.pop_front();
            direQueue.pop_front();
        } else {
            direQueue.push_back(direQueue.front() + n);
            direQueue.pop_front();
            radiantQueue.pop_front();
        }
    }
    return radiantQueue.empty() ? "Dire" : "Radiant";
}

