TreeNode* constructMaximumBinaryTree(const std::vector<int>& nums) {
    if (nums.empty()) return nullptr;
    size_t maxIndex = 0;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] > nums[maxIndex]) maxIndex = i;
