    TreeNode* node = new TreeNode(nums[maxIndex]);
    std::vector<int> leftSlice(nums.begin(), nums.begin() + maxIndex);
    std::vector<int> rightSlice(nums.begin() + maxIndex + 1, nums.end());
    node->left = constructMaximumBinaryTree(leftSlice);
    node->right = constructMaximumBinaryTree(rightSlice);
    return node;
}

