int widthOfBinaryTree(TreeNode* root) {
    if (!root) return 0;
    unsigned long long maxWidth = 0;
    std::vector<std::pair<TreeNode*, unsigned long long>> queue;
    queue.emplace_back(root, 0);
    while (!queue.empty()) {
        size_t size = queue.size();
        unsigned long long leftmost = queue.front().second;
        unsigned long long rightmost = queue.back().second;
        maxWidth = std::max(maxWidth, rightmost - leftmost + 1);
        std::vector<std::pair<TreeNode*, unsigned long long>> next;
        next.reserve(size * 2);
        for (size_t i = 0; i < size; ++i) {
            TreeNode* node = queue[i].first;
            unsigned long long index = queue[i].second;
            if (node->left) next.emplace_back(node->left, 2 * index + 1);
            if (node->right) next.emplace_back(node->right, 2 * index + 2);
        }
        queue.swap(next);
    }
    return static_cast<int>(maxWidth);
}

