int bfs(const std::vector<std::vector<int>>& forest, const std::pair<int, int>& start, const std::array<int, 3>& target) {
    int m = forest.size();
    int n = forest[0].size();
    std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));
    std::queue<std::pair<int, int>> q;
    q.push(start);
    visited[start.first][start.second] = true;
    int steps = 0;
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};
    while (!q.empty()) {
        int sz = q.size();
        for (int i = 0; i < sz; ++i) {
            auto cur = q.front();
            q.pop();
            if (cur.first == target[1] && cur.second == target[2]) {
                return steps;
            }
            for (int d = 0; d < 4; ++d) {
                int nr = cur.first + dr[d];
                int nc = cur.second + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && forest[nr][nc] != 0) {
                    visited[nr][nc] = true;
                    q.emplace(nr, nc);
                }
            }
        }
        ++steps;
    }
    return -1;
}

int cutOffTree(std::vector<std::vector<int>>& forest) {
    int m = forest.size();
    int n = forest[0].size();
    std::vector<std::array<int, 3>> trees;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (forest[i][j] > 1) {
                trees.push_back({forest[i][j], i, j});
            }
        }
    }
    std::sort(trees.begin(), trees.end(), [](const std::array<int, 3>& a, const std::array<int, 3>& b) {
        return a[0] < b[0];
    });
    std::pair<int, int> start = {0, 0};
    int totalSteps = 0;
    for (const auto& tree : trees) {
        int steps = bfs(forest, start, tree);
        if (steps == -1) {
            return -1;
        }
        totalSteps += steps;
        start = {tree[1], tree[2]};
    }
    return totalSteps;
}

