bool validUtf8(const std::vector<int>& data) {
    int bytesLeft = 0;
    for (size_t i = 0; i < data.size(); ++i) {
        std::string binary = std::bitset<8>(data[i]).to_string();
        if (bytesLeft == 0) {
            if (binary[0] == '0') {
                continue;
            } else if (binary.substr(0, 3) == "110") {
                bytesLeft = 1;
            } else if (binary.substr(0, 4) == "1110") {
                bytesLeft = 2;
            } else if (binary.substr(0, 5) == "11110") {
                bytesLeft = 3;
            } else {
                return false;
            }
        } else {
            if (binary.substr(0, 2) != "10") {
                return false;
            }
            --bytesLeft;
        }
    }
    return bytesLeft == 0;
}

