}

std::vector<int> maxNumber(const std::vector<int>& nums1, const std::vector<int>& nums2, int k) {
    std::vector<int> result;
    int start = std::max(0, k - static_cast<int>(nums2.size()));
    int end = std::min(k, static_cast<int>(nums1.size()));
    for (int i = start; i <= end; ++i) {
        std::vector<int> subsequence1 = maxSubsequence(nums1, i);
        std::vector<int> subsequence2 = maxSubsequence(nums2, k - i);
        std::vector<int> merged = merge(subsequence1, subsequence2);
        if (greater(merged, result)) {
            result = merged;
        }
    }
    return result;
}

