int shortestPathLength(const std::vector<std::vector<int>>& graph) {
    int n = static_cast<int>(graph.size());
    std::queue<std::tuple<int, int, int>> q;
    std::vector<std::vector<int>> visited(n, std::vector<int>(1 << n, INT_MAX));
    for (int i = 0; i < n; ++i) {
        q.emplace(i, 1 << i, 0);
        visited[i][1 << i] = 0;
    }
    int allVisited = (1 << n) - 1;
    while (!q.empty()) {
        int node, state, pathLength;
        std::tie(node, state, pathLength) = q.front();
        q.pop();
        if (state == allVisited) return pathLength;
        for (int neighbor : graph[node]) {
            int newState = state | (1 << neighbor);
            if (visited[neighbor][newState] > pathLength + 1) {
                visited[neighbor][newState] = pathLength + 1;
                q.emplace(neighbor, newState, pathLength + 1);
            }
        }
    }
    return -1;
}

