int kSimilarity(const std::string& s1, const std::string& s2) {
    std::vector<std::string> queue = {s1};
    std::unordered_set<std::string> visited = {s1};
    int step = 0;
    while (true) {
        std::vector<std::string> nextQueue;
        for (const std::string& s : queue) {
            if (s == s2) return step;
            for (size_t i = 0; i < s.size(); ++i) {
                if (s[i] != s2[i]) {
                    for (size_t j = i + 1; j < s.size(); ++j) {
                        if (s[j] == s2[i]) {
                            std::string nextS = s;
                            std::swap(nextS[i], nextS[j]);
                            if (visited.find(nextS) == visited.end()) {
                                nextQueue.push_back(nextS);
                                visited.insert(nextS);
                            }
                        }
                    }
                    break;
                }
            }
        }
        queue = std::move(nextQueue);
        ++step;
    }
}

