int shortestPathAllKeys(const std::vector<std::string>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    std::unordered_set<char> allKeys;
    std::pair<int, int> start{-1, -1};
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == '@') start = {i, j};
            if (grid[i][j] >= 'a' && grid[i][j] <= 'f') allKeys.insert(grid[i][j]);
        }
    }
    int allKeysSize = allKeys.size();
    std::deque<std::pair<std::pair<int, int>, std::unordered_set<char>>> queue;
    queue.push_back({start, std::unordered_set<char>{}});
    std::unordered_set<std::string> visited;
    const int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
    int steps = 0;
    while (!queue.empty()) {
        int size = queue.size();
        for (int i = 0; i < size; ++i) {
            auto cur = queue.front();
            queue.pop_front();
            int x = cur.first.first;
            int y = cur.first.second;
            const std::unordered_set<char>& keys = cur.second;
            if ((int)keys.size() == allKeysSize) return steps;
            for (const auto& d : dirs) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] != '#') {
                    std::unordered_set<char> newKeys = keys;
                    char cell = grid[nx][ny];
                    if (cell >= 'a' && cell <= 'f') newKeys.insert(cell);
                    if (cell >= 'A' && cell <= 'F' && newKeys.find(std::tolower(cell)) == newKeys.end()) continue;
                    std::vector<char> sortedKeys(newKeys.begin(), newKeys.end());
                    std::sort(sortedKeys.begin(), sortedKeys.end());
                    std::string state = std::to_string(nx) + "," + std::to_string(ny) + ",";
                    for (char c : sortedKeys) state.push_back(c);
                    if (visited.find(state) == visited.end()) {
                        queue.push_back({{nx, ny}, newKeys});
                        visited.insert(state);
                    }
                }
            }
        }
        ++steps;
    }
    return -1;
}

