double mincostToHireWorkers(const std::vector<int>& quality, const std::vector<int>& wage, int k) {
    struct Worker {
        double ratio;
        int q;
    };
    std::vector<Worker> workers;
    workers.reserve(quality.size());
    for (size_t i = 0; i < quality.size(); ++i) {
        workers.push_back({ static_cast<double>(wage[i]) / quality[i], quality[i] });
    }
    std::sort(workers.begin(), workers.end(),
        [](const Worker& a, const Worker& b) { return a.ratio < b.ratio; });
    std::priority_queue<int> maxHeap;
    long long sumQuality = 0;
    double minCost = std::numeric_limits<double>::infinity();
    for (const Worker& w : workers) {
        sumQuality += w.q;
        maxHeap.push(w.q);
        if (static_cast<int>(maxHeap.size()) > k) {
            sumQuality -= maxHeap.top();
            maxHeap.pop();
        }
        if (static_cast<int>(maxHeap.size()) == k) {
            double cost = sumQuality * w.ratio;
            if (cost < minCost) {
                minCost = cost;
            }
        }
    }
    return minCost;
}

