class RLEIterator {
    std::vector<int> encoding;
    size_t index = 0;
public:
    RLEIterator(const std::vector<int>& encoding) : encoding(encoding) {}
    int next(int num) {
        while (index < encoding.size()) {
            int remaining = encoding[index];
            if (num <= remaining) {
                encoding[index] -= num;
                return encoding[index + 1];
            }
            num -= remaining;
            index += 2;
        }
        return -1;
    }
};

