int dieSimulator(int n, const std::vector<int>& rollMax) {
    const int MOD = 1000000007;
    std::unordered_map<std::string, long long> memo;
    std::function<long long(int, int, int)> dp = [&](int roll, int last, int count) -> long long {
        if (roll == n) return 1;
        std::string key = std::to_string(roll) + "," + std::to_string(last) + "," + std::to_string(count);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        long long res = 0;
        for (int i = 1; i <= 6; ++i) {
            if (i == last && count == rollMax[i - 1]) continue;
            int newCount = (i == last) ? count + 1 : 1;
            res = (res + dp(roll + 1, i, newCount)) % MOD;
        }
        memo[key] = res;
        return res;
    };
    return static_cast<int>(dp(0, 0, 0));
}

