std::vector<int> threeEqualParts(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    int totalOnes = 0;
    for (int bit : arr) totalOnes += bit;
    if (totalOnes % 3 != 0) return std::vector<int>{-1, -1};
    if (totalOnes == 0) return std::vector<int>{0, n - 1};
    int k = totalOnes / 3;
    int first = -1, second = -1, third = -1;
    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (arr[i] == 1) {
            ++count;
            if (count == 1) first = i;
            else if (count == k + 1) second = i;
            else if (count == 2 * k + 1) third = i;
        }
    }
    while (third < n && arr[first] == arr[second] && arr[second] == arr[third]) {
        ++first;
        ++second;
        ++third;
    }
    if (third == n) {
        return std::vector<int>{first - 1, second};
    }
    return std::vector<int>{-1, -1};
}

