bool canMakeEqualFreq(const std::unordered_map<int, int>& countMap,
                      const std::unordered_map<int, int>& freqMap) {
    int maxFreq = 0;
    for (const auto& p : freqMap) {
        if (p.first > maxFreq) maxFreq = p.first;
    }
    int total = 0;
    for (const auto& p : countMap) {
        total += p.second;
    }
    if (maxFreq == 1) return true;
    int cntMax = freqMap.count(maxFreq) ? freqMap.at(maxFreq) : 0;
    int cntSecond = freqMap.count(maxFreq - 1) ? freqMap.at(maxFreq - 1) : 0;
    int cntOne = freqMap.count(1) ? freqMap.at(1) : 0;
    if (cntMax == 1 && cntMax * maxFreq + cntSecond * (maxFreq - 1) == total) return true;
    if (cntOne == 1 && cntMax * maxFreq == total - 1) return true;
    return false;
}

int maxEqualFreq(const std::vector<int>& nums) {
    std::unordered_map<int, int> countMap;
    std::unordered_map<int, int> freqMap;
    int maxLen = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        int num = nums[i];
        int oldCount = countMap[num];
        if (oldCount > 0) {
            auto it = freqMap.find(oldCount);
            if (it != freqMap.end()) {
                if (--it->second == 0) freqMap.erase(it);
            }
        }
        int newCount = oldCount + 1;
        countMap[num] = newCount;
        freqMap[newCount] += 1;
        if (canMakeEqualFreq(countMap, freqMap)) {
            maxLen = static_cast<int>(i) + 1;
        }
    }
    return maxLen;
}

