int minNumberOfSemesters(int n, const std::vector<std::vector<int>>& relations, int k) {
    std::vector<std::vector<int>> graph(n + 1);
    std::vector<int> inDegree(n + 1, 0);
    for (const auto& rel : relations) {
        int prev = rel[0];
        int next = rel[1];
        graph[prev].push_back(next);
        ++inDegree[next];
    }

    std::deque<int> queue;
    for (int i = 1; i <= n; ++i) {
        if (inDegree[i] == 0) {
            queue.push_back(i);
        }
    }

    int semesters = 0;
    int taken = 0;
    unsigned long long bitmask = 0;

    while (!queue.empty()) {
        std::vector<int> tempQueue;
        unsigned long long tempBitmask = 0;
        int count = 0;
        while (!queue.empty() && count < k) {
            int node = queue.front();
            queue.pop_front();
            tempBitmask |= (1ULL << (node - 1));
            ++count;
            for (int neighbor : graph[node]) {
                --inDegree[neighbor];
                if (inDegree[neighbor] == 0) {
                    tempQueue.push_back(neighbor);
                }
            }
        }
        bitmask |= tempBitmask;
        for (int v : tempQueue) {
            queue.push_back(v);
        }
        ++semesters;
        taken += count;
        if (taken == n) {
            break;
        }
    }
    return semesters;
}

