        std::vector<std::pair<int, int>> st;
        long long sum = 0;
        for (int j = 0; j < n; ++j) {
            int cnt = 1;
            while (!st.empty() && st.back().first >= height[j]) {
                sum -= static_cast<long long>(st.back().second) * (st.back().first - height[j]);
                cnt += st.back().second;
                st.pop_back();
            }
            st.emplace_back(height[j], cnt);
            sum += static_cast<long long>(height[j]);
            ans += sum;
        }
    }
    return ans;
}

