std::vector<bool> canEat(const std::vector<long long>& candiesCount, const std::vector<std::vector<long long>>& queries) {
    std::vector<long long> prefixSum(candiesCount.size() + 1, 0);
    for (size_t i = 0; i < candiesCount.size(); ++i) {
        prefixSum[i + 1] = prefixSum[i] + candiesCount[i];
    }
    std::vector<bool> answer;
    answer.reserve(queries.size());
    for (const auto& q : queries) {
        long long favoriteType = q[0];
        long long favoriteDay = q[1];
        long long dailyCap = q[2];
        long long minCandiesEaten = favoriteDay + 1;                         // at least one candy per day
        long long maxCandiesEaten = (favoriteDay + 1) * dailyCap;            // at most dailyCap candies per day
        long long beforeType = prefixSum[favoriteType];
        long long afterType = prefixSum[favoriteType + 1];
        bool possible = (maxCandiesEaten > beforeType) && (minCandiesEaten <= afterType);
        answer.push_back(possible);
    }
    return answer;
}

