int maximumScore(int a, int b, int c) {
    int score = 0;
    while ((a > 0 && b > 0) || (a > 0 && c > 0) || (b > 0 && c > 0)) {
        int max_val = std::max({a, b, c});
        int min_val = std::min({a, b, c});
        int mid = a + b + c - max_val - min_val;
        if (max_val == a) {
            if (mid == b) {
                a--;
                b--;
            } else {
                a--;
                c--;
            }
        } else if (max_val == b) {
            if (mid == a) {
                a--;
                b--;
            } else {
                b--;
                c--;
            }
        } else {
            if (mid == a) {
                a--;
                c--;
            } else {
                b--;
                c--;
            }
        }
        ++score;
    }
    return score;
}

