int maxValue(std::vector<std::vector<int>>& events, int k) {
    std::sort(events.begin(), events.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        return a[0] < b[0];
    });
    int n = static_cast<int>(events.size());
    std::vector<int> starts(n);
    for (int i = 0; i < n; ++i) starts[i] = events[i][0];
    std::vector<int> nextIdx(n);
    for (int i = 0; i < n; ++i) {
        int lo = i + 1, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (events[mid][0] > events[i][1]) hi = mid;
            else lo = mid + 1;
        }
        nextIdx[i] = lo;
    }
    std::vector<std::vector<long long>> dp(n + 1, std::vector<long long>(k + 1, 0));
    for (int i = n - 1; i >= 0; --i) {
        for (int j = 1; j <= k; ++j) {
            long long take = static_cast<long long>(events[i][2]) + dp[nextIdx[i]][j - 1];
            long long skip = dp[i + 1][j];
            dp[i][j] = take > skip ? take : skip;
        }
    }
    return static_cast<int>(dp[0][k]);
}

