std::vector<int> countPairs(int n, const std::vector<std::vector<int>>& edges, const std::vector<int>& queries) {
    std::vector<std::vector<int>> graph(n + 1);
    for (const auto& edge : edges) {
        graph[edge[0]].push_back(edge[1]);
        graph[edge[1]].push_back(edge[0]);
    }

    std::vector<int> degrees(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        degrees[i] = static_cast<int>(graph[i].size());
