                int incident = degrees[a] + degrees[b];
                if (std::find(graph[a].begin(), graph[a].end(), b) != graph[a].end()) {
                    incident -= 1;
                }
                if (incident > query) {
                    ++count;
                }
            }
        }
        answers[i] = count;
    }
    return answers;
}

