int minTrioDegree(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> graph(n + 1);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    int minDegree = INT_MAX;
    for (int i = 1; i <= n; ++i) {
        for (int j = i + 1; j <= n; ++j) {
            for (int k = j + 1; k <= n; ++k) {
                if (std::find(graph[i].begin(), graph[i].end(), j) != graph[i].end() &&
                    std::find(graph[j].begin(), graph[j].end(), k) != graph[j].end() &&
                    std::find(graph[k].begin(), graph[k].end(), i) != graph[k].end()) {
                    int degree = 0;
                    for (int node : {i, j, k}) {
                        for (int neighbor : graph[node]) {
                            if (neighbor != i && neighbor != j && neighbor != k) {
                                ++degree;
                            }
                        }
                    }
                    if (degree < minDegree) {
                        minDegree = degree;
                    }
                }
            }
        }
    }
    return minDegree == INT_MAX ? -1 : minDegree;
}

