    std::size_t repeats = (b.size() + a.size() - 1) / a.size();
    std::string repeatedA;
    repeatedA.reserve(a.size() * (repeats + 1));
    for (std::size_t i = 0; i < repeats; ++i) {
        repeatedA += a;
    }
    if (repeatedA.find(b) != std::string::npos) {
        return static_cast<int>(repeats);
    }
    repeatedA += a;
    ++repeats;
    if (repeatedA.find(b) != std::string::npos) {
        return static_cast<int>(repeats);
    }
    return -1;
}

