#include <bits/stdc++.h>
#include <vector>

std::vector<int> findRedundantDirectedConnection(const std::vector<std::vector<int>>& edges) {
    int n = edges.size();
    std::vector<int> firstEdge(n + 1, -1);
    int cand1Idx = -1, cand2Idx = -1;

    for (int i = 0; i < n; ++i) {
        int u = edges[i][0];
        int v = edges[i][1];
        if (firstEdge[v] == -1) {
            firstEdge[v] = i;
        } else {
            cand1Idx = firstEdge[v];
            cand2Idx = i;
        }
    }

    std::vector<int> parent(n + 1);
    for (int i = 1; i <= n; ++i) parent[i] = i;

    std::function<int(int)> find = [&](int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    };

    auto unite = [&](int x, int y) -> bool {
        int fx = find(x);
        int fy = find(y);
        if (fx == fy) return false;
        parent[fy] = fx;
        return true;
    };

    for (int i = 0; i < n; ++i) {
        if (i == cand2Idx) continue; // skip second edge if double parent exists
        int u = edges[i][0];
        int v = edges[i][1];
        if (!unite(u, v)) {
            if (cand1Idx != -1) {
                return edges[cand1Idx];
            } else {
                return edges[i];
            }
        }
    }

    // If we reach here, there was a node with two parents but no cycle detected
    return edges[cand2Idx];
}

