double knightProbability(int n, int k, int row, int column) {
    static const std::vector<std::pair<int, int>> directions = {
        {-2, -1}, {-2, 1}, {-1, -2}, {-1, 2},
        {1, -2}, {1, 2}, {2, -1}, {2, 1}
    };
    std::unordered_map<std::string, double> memo;
    std::function<double(int, int, int)> dfs = [&](int r, int c, int moves) -> double {
        if (moves == 0) return (r >= 0 && r < n && c >= 0 && c < n) ? 1.0 : 0.0;
        std::string key = std::to_string(r) + "," + std::to_string(c) + "," + std::to_string(moves);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        double prob = 0.0;
        for (const auto& dir : directions) {
            int nr = r + dir.first;
            int nc = c + dir.second;
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) prob += dfs(nr, nc, moves - 1);
        }
        prob /= 8.0;
        memo[key] = prob;
        return prob;
    };
    return dfs(row, column, k);
}

