    for (int i = 0; i < n; ++i) {
        sum[i + 1] = sum[i] + nums[i];
    }
    std::vector<long long> sums(n - k + 1, 0);
    for (int i = 0; i <= n - k; ++i) {
        sums[i] = sum[i + k] - sum[i];
    }
    long long maxSum = LLONG_MIN;
    std::vector<int> result;
    for (int i = 0; i <= n - k; ++i) {
        for (int j = i + k; j <= n - k; ++j) {
            for (int m = j + k; m <= n - k; ++m) {
                long long totalSum = sums[i] + sums[j] + sums[m];
                if (totalSum > maxSum) {
                    maxSum = totalSum;
                    result = {i, j, m};
                } else if (totalSum == maxSum) {
                    if (result.empty() ||
                        i < result[0] ||
                        (i == result[0] && j < result[1]) ||
                        (i == result[0] && j == result[1] && m < result[2])) {
                        result = {i, j, m};
