int minStickers(const std::vector<std::string>& stickers, const std::string& target) {
    const int INF = std::numeric_limits<int>::max() / 2;
    int n = static_cast<int>(target.size());
    std::unordered_map<int, int> dp;
    dp.reserve(1 << n);
    dp[0] = 0;
    for (int i = 1; i <= (1 << n); ++i) {
        dp[i] = INF;
    }
    for (int mask = 0; mask < (1 << n); ++mask) {
        if (dp[mask] == INF) continue;
        for (const std::string& sticker : stickers) {
            int newMask = mask;
            for (char ch : sticker) {
                for (int i = 0; i < n; ++i) {
                    if (target[i] == ch && ((newMask >> i) & 1) == 0) {
                        newMask |= (1 << i);
                        break;
                    }
                }
            }
            auto it = dp.find(newMask);
            if (it == dp.end() || it->second > dp[mask] + 1) {
                dp[newMask] = dp[mask] + 1;
            }
        }
    }
    int fullMask = (1 << n) - 1;
    if (dp[fullMask] == INF) return -1;
    return dp[fullMask];
}

