    int rows = grid.size();
    if (rows == 0) return 0;
    int cols = grid[0].size();
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (grid[i][j] == 1) {
                int area = 0;
                std::function<void(int, int)> dfs = [&](int row, int col) {
                    if (row < 0 || row >= rows || col < 0 || col >= cols || grid[row][col] == 0) {
