                    grid[row][col] = 0;
                    ++area;
                    dfs(row - 1, col);
                    dfs(row + 1, col);
                    dfs(row, col - 1);
                    dfs(row, col + 1);
                };
                dfs(i, j);
                maxArea = std::max(maxArea, area);
            }
        }
    }
    return maxArea;
}

