bool canPartitionKSubsets(const std::vector<int>& nums, int k) {
    long long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    if (totalSum % k != 0) return false;
    long long targetSum = totalSum / k;
    std::vector<bool> visited(nums.size(), false);
    std::function<bool(int, int, long long)> backtrack = [&](int index, int count, long long currentSum) -> bool {
        if (count == k) return true;
        if (currentSum > targetSum) return false;
        if (currentSum == targetSum) return backtrack(0, count + 1, 0);
        for (int i = index; i < static_cast<int>(nums.size()); ++i) {
            if (visited[i]) continue;
            visited[i] = true;
            if (backtrack(i + 1, count, currentSum + nums[i])) return true;
            visited[i] = false;
        }
        return false;
    };
    return backtrack(0, 0, 0);
}

