int pickRandom(int n, const std::vector<int>& blacklist) {
    int availableNumbers = n - static_cast<int>(blacklist.size());
    std::unordered_map<int, int> mapping;
    int j = 0;
    std::unordered_set<int> blackSet(blacklist.begin(), blacklist.end());
    for (int i = 0; i < n; ++i) {
        if (blackSet.count(i)) {
            continue;
        }
        if (j < static_cast<int>(blacklist.size()) && i > blacklist[j]) {
            mapping[blacklist[j]] = i;
            ++j;
        }
    }
    static std::mt19937 rng(std::random_device{}());
    int randomIndex = std::uniform_int_distribution<int>(0, availableNumbers - 1)(rng);
    for (int i = 0; i < n; ++i) {
        if (!blackSet.count(i)) {
            if (randomIndex == 0) {
                return i;
            }
            --randomIndex;
        }
    }
    return -1;
}

