long long numSubarrayProductLessThanK(const std::vector<int>& nums, int k) {
    if (k <= 1) return 0;
    std::size_t left = 0;
    double product = 1.0;
    long long count = 0;
    for (std::size_t right = 0; right < nums.size(); ++right) {
        product *= nums[right];
        while (product >= k && left <= right) {
            product /= nums[left];
            ++left;
        }
        count += static_cast<long long>(right - left + 1);
    }
    return count;
}

