struct RangeModuleObj {
    std::vector<std::array<int, 2>> ranges;
    void addRange(int left, int right) {
        std::size_t i = 0;
        while (i < ranges.size() && ranges[i][1] < left) ++i;
        std::size_t start = i; // preserve the original prefix boundary -- the loop below mutates i
        std::size_t j = i;
        while (j < ranges.size() && ranges[j][0] <= right) ++j;
        std::array<int, 2> merged = {left, right};
        while (i < j) {
            merged[0] = std::min(merged[0], ranges[i][0]);
            merged[1] = std::max(merged[1], ranges[i][1]);
            ++i;
        }
        std::vector<std::array<int, 2>> newRanges;
        newRanges.insert(newRanges.end(), ranges.begin(), ranges.begin() + start);
        newRanges.push_back(merged);
        newRanges.insert(newRanges.end(), ranges.begin() + j, ranges.end());
        ranges.swap(newRanges);
    }
    bool queryRange(int left, int right) {
        std::size_t i = 0;
        while (i < ranges.size() && ranges[i][1] < left) ++i;
        return i < ranges.size() && ranges[i][0] <= left && right <= ranges[i][1];
    }
    void removeRange(int left, int right) {
        std::size_t i = 0;
        while (i < ranges.size() && ranges[i][1] < left) ++i;
        std::size_t j = i;
        while (j < ranges.size() && ranges[j][0] < right) ++j;
        std::vector<std::array<int, 2>> newRanges(ranges.begin(), ranges.begin() + i);
        if (i < j) {
            if (ranges[i][0] < left) newRanges.push_back({ranges[i][0], left});
            if (ranges[i][1] > right) newRanges.push_back({right, ranges[i][1]});
            ++i;
        }
        while (i < j) {
            if (ranges[i][1] > right) newRanges.push_back({right, ranges[i][1]});
            ++i;
        }
        newRanges.insert(newRanges.end(), ranges.begin() + j, ranges.end());
        ranges.swap(newRanges);
    }
};

RangeModuleObj RangeModule() {
    return RangeModuleObj();
}

