std::vector<std::vector<std::string>> accountsMerge(const std::vector<std::vector<std::string>>& accounts) {
    std::unordered_map<std::string, std::string> parent;
    std::unordered_map<std::string, std::string> emailMap;
    for (size_t i = 0; i < accounts.size(); ++i) {
        for (size_t j = 1; j < accounts[i].size(); ++j) {
            parent[accounts[i][j]] = accounts[i][j];
            emailMap[accounts[i][j]] = accounts[i][0];
        }
    }
    std::function<std::string(const std::string&)> find = [&](const std::string& email) -> std::string {
        if (parent[email] != email) {
            parent[email] = find(parent[email]);
        }
        return parent[email];
    };
    auto unite = [&](const std::string& e1, const std::string& e2) {
        std::string p1 = find(e1);
        std::string p2 = find(e2);
        if (p1 != p2) {
            parent[p1] = p2;
        }
    };
    for (size_t i = 0; i < accounts.size(); ++i) {
        for (size_t j = 2; j < accounts[i].size(); ++j) {
            unite(accounts[i][j], accounts[i][j - 1]);
        }
    }
    std::unordered_map<std::string, std::vector<std::string>> result;
    for (const auto& kv : parent) {
        const std::string& email = kv.first;
        std::string parentEmail = find(email);
        result[parentEmail].push_back(email);
    }
    std::vector<std::vector<std::string>> finalResult;
    for (auto& kv : result) {
        std::vector<std::string>& emails = kv.second;
        std::sort(emails.begin(), emails.end());
        std::vector<std::string> entry;
        entry.push_back(emailMap[kv.first]);
        entry.insert(entry.end(), emails.begin(), emails.end());
        finalResult.push_back(std::move(entry));
    }
    return finalResult;
}

