int pivotIndex(const std::vector<int>& nums) {
    long long totalSum = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        totalSum += nums[i];
    }
    long long leftSum = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (leftSum == totalSum - leftSum - nums[i]) {
            return static_cast<int>(i);
