    ListNode(int x, ListNode* next) : val(x), next(next) {}
};

std::vector<ListNode*> splitListToParts(ListNode* head, int k) {
    int length = 0;
    ListNode* temp = head;
    while (temp != nullptr) {
        ++length;
        temp = temp->next;
    }
    std::vector<ListNode*> result(k);
    int size = length / k;
    int remainder = length % k;
    ListNode* start = head;
    for (int i = 0; i < k; ++i) {
        result[i] = start;
        int partSize = size + (i < remainder ? 1 : 0);
        for (int j = 0; j < partSize - 1; ++j) {
            if (start != nullptr) {
                start = start->next;
            }
        }
        if (start != nullptr) {
            ListNode* next = start->next;
            start->next = nullptr;
            start = next;
        }
    }
    return result;
}

