std::string countOfAtoms(const std::string& formula) {
    std::vector<std::unordered_map<std::string, long long>> stack;
    stack.emplace_back();
    int n = static_cast<int>(formula.size());
    for (int i = 0; i < n; ++i) {
        if (formula[i] == '(') {
            stack.emplace_back();
        } else if (formula[i] == ')') {
            auto current = std::move(stack.back());
            stack.pop_back();
            long long multiplier = 0;
            ++i;
            while (i < n && std::isdigit(static_cast<unsigned char>(formula[i]))) {
                multiplier = multiplier * 10 + (formula[i] - '0');
                ++i;
            }
            if (multiplier == 0) multiplier = 1;
            --i;
            for (const auto& kv : current) {
                stack.back()[kv.first] += kv.second * multiplier;
            }
        } else {
            std::string name;
            name += formula[i];
            ++i;
            while (i < n && formula[i] >= 'a' && formula[i] <= 'z') {
                name += formula[i];
                ++i;
            }
            --i;
            long long multiplier = 0;
            while (i + 1 < n && std::isdigit(static_cast<unsigned char>(formula[i + 1]))) {
                ++i;
                multiplier = multiplier * 10 + (formula[i] - '0');
            }
            if (multiplier == 0) multiplier = 1;
            stack.back()[name] += multiplier;
        }
    }
    std::vector<std::string> result;
    for (const auto& kv : stack[0]) {
        result.push_back(kv.first + (kv.second > 1 ? std::to_string(kv.second) : std::string()));
    }
    std::sort(result.begin(), result.end());
    std::string output;
    for (const auto& s : result) {
        output += s;
    }
    return output;
}

