long long countPalindromicSubsequences(const std::string& s) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(s.size());
    if (n == 0) return 0;
    std::vector<std::vector<int>> nextPos(n, std::vector<int>(26, n));
    std::vector<std::vector<int>> prevPos(n, std::vector<int>(26, -1));
    int last[26];
    std::fill(last, last + 26, -1);
    for (int i = 0; i < n; ++i) {
        for (int c = 0; c < 26; ++c) prevPos[i][c] = last[c];
        last[s[i] - 'a'] = i;
    }
    int nxt[26];
    std::fill(nxt, nxt + 26, n);
    for (int i = n - 1; i >= 0; --i) {
        for (int c = 0; c < 26; ++c) nextPos[i][c] = nxt[c];
        nxt[s[i] - 'a'] = i;
    }
    std::vector<std::vector<long long>> dp(n, std::vector<long long>(n, 0));
    for (int i = 0; i < n; ++i) dp[i][i] = 1;
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            if (s[i] != s[j]) {
                dp[i][j] = (dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1]) % MOD;
            } else {
                int c = s[i] - 'a';
                int i2 = nextPos[i][c];
                int j2 = prevPos[j][c];
                long long inner = (i + 1 <= j - 1) ? dp[i + 1][j - 1] : 0;
                if (i2 > j2) {
                    dp[i][j] = (2 * inner + 2) % MOD;
                } else if (i2 == j2) {
                    dp[i][j] = (2 * inner + 1) % MOD;
                } else {
                    long long inner2 = (i2 + 1 <= j2 - 1) ? dp[i2 + 1][j2 - 1] : 0;
                    dp[i][j] = (2 * inner - inner2) % MOD;
                }
            }
            if (dp[i][j] < 0) dp[i][j] += MOD;
        }
    }
    return dp[0][n - 1];
}

