class MyCalendarThree {
    // Persist events across calls (bug: original free function re-initialized
    // `events` on every call, so it never accumulated bookings and always returned 1)
    std::vector<std::pair<int,int>> events;
public:
    int book(int startTime, int endTime) {
        events.push_back({startTime, endTime});
        std::vector<std::pair<int,int>> sorted = events;
        std::sort(sorted.begin(), sorted.end(),
                  [](const std::pair<int,int>& a, const std::pair<int,int>& b) {
                      return a.first < b.first;
                  });
        int maxKBooking = 0;
        std::vector<int> endTimes;
        for (size_t i = 0; i < sorted.size(); ++i) {
            endTimes.erase(std::remove_if(endTimes.begin(), endTimes.end(),
                                          [&](int et) { return et <= sorted[i].first; }),
                           endTimes.end());
            endTimes.push_back(sorted[i].second);
            maxKBooking = std::max(maxKBooking, (int)endTimes.size());
        }
        return maxKBooking;
    }
};

