std::vector<int> asteroidCollision(const std::vector<int>& asteroids) {
    std::vector<int> st;
    for (int a : asteroids) {
        bool alive = true;
        while (alive && a < 0 && !st.empty() && st.back() > 0) {
            if (st.back() < -a) {
                st.pop_back();
                continue;
            } else if (st.back() == -a) {
                st.pop_back();
                alive = false;
            } else {
                alive = false;
            }
        }
        if (alive) {
            st.push_back(a);
        }
    }
    return st;
}

