using std::string;
using std::vector;
using std::unordered_map;

static void skipSpaces(const string& s, int& i) {
    while (i < (int)s.size() && s[i] == ' ') ++i;
}

static string parseToken(const string& s, int& i) {
    int start = i;
    while (i < (int)s.size() && s[i] != ' ' && s[i] != ')') ++i;
    return s.substr(start, i - start);
}

static int getValue(const string& token, const vector<unordered_map<string,int>>& scopes) {
    if (token.empty()) return 0;
    if (token[0] == '-' || std::isdigit(token[0])) {
        return std::stoi(token);
    }
    for (int k = (int)scopes.size() - 1; k >= 0; --k) {
        auto it = scopes[k].find(token);
        if (it != scopes[k].end()) return it->second;
    }
    return 0; // should not happen for valid input
}

static int eval(const string& s, int& i, vector<unordered_map<string,int>>& scopes) {
    skipSpaces(s, i);
    if (s[i] != '(') {
        string token = parseToken(s, i);
        return getValue(token, scopes);
    }
    ++i; // skip '('
    skipSpaces(s, i);
    string op = parseToken(s, i);
    if (op == "add") {
        int a = eval(s, i, scopes);
        int b = eval(s, i, scopes);
        skipSpaces(s, i);
        ++i; // skip ')'
        return a + b;
    } else if (op == "mult") {
        int a = eval(s, i, scopes);
        int b = eval(s, i, scopes);
        skipSpaces(s, i);
        ++i; // skip ')'
        return a * b;
    } else { // let
        scopes.emplace_back(); // new scope
        while (true) {
            skipSpaces(s, i);
            if (s[i] == ')') {
                // no more tokens, should not happen
                break;
            }
            // If next token starts an expression, it's the final expr
            if (s[i] == '(' || s[i] == '-' || std::isdigit(s[i])) {
                int val = eval(s, i, scopes);
                scopes.pop_back();
                skipSpaces(s, i);
                ++i; // skip ')'
                return val;
            }
            // otherwise it's a variable name
            string var = parseToken(s, i);
            skipSpaces(s, i);
            // Check if this is the final expression (next char is ')')
            if (s[i] == ')') {
                int val = getValue(var, scopes);
                scopes.pop_back();
                ++i; // skip ')'
                return val;
            }
            int val = eval(s, i, scopes);
            scopes.back()[var] = val;
        }
        // Should not reach here
        scopes.pop_back();
        return 0;
    }
}

int evaluate(string expression) {
    int idx = 0;
    vector<unordered_map<string,int>> scopes;
    return eval(expression, idx, scopes);
}

