int monotoneIncreasingDigits(int n) {
    std::string numStr = std::to_string(n);
    int result = -1;
    for (int i = static_cast<int>(numStr.size()) - 1; i >= 0; --i) {
        if (i < static_cast<int>(numStr.size()) - 1 && numStr[i] > numStr[i + 1]) {
            std::string newStr = numStr.substr(0, i);
            int decreased = (numStr[i] - '0') - 1;
            newStr += static_cast<char>('0' + decreased);
            newStr.append(numStr.size() - i - 1, '9');
            numStr = newStr;
            break;
        }
    }
    if (numStr != std::to_string(n)) {
        result = monotoneIncreasingDigits(std::stoi(numStr));
    } else {
        result = n;
    }
    return result;
}

