long long deleteAndEarn(const std::vector<int>& nums) {
    int maxVal = 0;
    for (int num : nums) {
        if (num > maxVal) maxVal = num;
    }
    std::vector<long long> count(maxVal + 1, 0);
    for (int num : nums) {
        count[num] += 1;
    }
    if (maxVal == 0) return 0;
    std::vector<long long> dp(maxVal + 1, 0);
    dp[1] = count[1];
    for (int i = 2; i <= maxVal; ++i) {
        dp[i] = std::max(dp[i - 1], dp[i - 2] + count[i] * i);
    }
    return dp[maxVal];
}

#include <bits/stdc++.h>

int cherryPickup(const std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    const int NEG_INF = -1000000;
    if (n == 0 || grid[0][0] == -1) return 0;
    std::vector<std::vector<std::vector<std::vector<int>>>> memo(
        n, std::vector<std::vector<std::vector<int>>>(
               n, std::vector<std::vector<int>>(
                      n, std::vector<int>(n, NEG_INF - 1))));
    std::function<int(int,int,int,int)> dp = [&](int r1, int c1, int r2, int c2) -> int {
        if (r1 >= n || c1 >= n || r2 >= n || c2 >= n) return NEG_INF;
        if (grid[r1][c1] == -1 || grid[r2][c2] == -1) return NEG_INF;
        if (memo[r1][c1][r2][c2] != NEG_INF - 1) return memo[r1][c1][r2][c2];
        if (r1 == n - 1 && c1 == n - 1) {
            // both at bottom-right
            return memo[r1][c1][r2][c2] = grid[r1][c1];
        }
        int best = NEG_INF;
        best = std::max(best, dp(r1 + 1, c1, r2 + 1, c2));
        best = std::max(best, dp(r1 + 1, c1, r2, c2 + 1));
        best = std::max(best, dp(r1, c1 + 1, r2 + 1, c2));
        best = std::max(best, dp(r1, c1 + 1, r2, c2 + 1));
        if (best == NEG_INF) {
            memo[r1][c1][r2][c2] = NEG_INF;
            return NEG_INF;
        }
        int cur = grid[r1][c1];
        if (r1 != r2 || c1 != c2) cur += grid[r2][c2];
        memo[r1][c1][r2][c2] = best + cur;
        return memo[r1][c1][r2][c2];
    };
    int result = dp(0, 0, 0, 0);
    return result < 0 ? 0 : result;
}

