char nextGreatestLetter(const std::vector<char>& letters, char target) {
    int n = static_cast<int>(letters.size());
    int left = 0, right = n - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (letters[mid] > target) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
    return letters[left % n];
}

