std::unordered_map<std::string, int> WordFilter(const std::vector<std::string>& words) {
    std::unordered_map<std::string, int> trie;
    for (size_t weight = 0; weight < words.size(); ++weight) {
        const std::string& word = words[weight];
        for (size_t i = 0; i < word.size(); ++i) {
            std::string prefix = word.substr(0, i + 1);
            for (size_t j = 0; j < word.size(); ++j) {
                std::string suffix = word.substr(j);
                trie[prefix + "#" + suffix] = static_cast<int>(weight);
            }
        }
    }
    return trie;
}

