int dominantIndex(const std::vector<int>& nums) {
    int maxIndex = 0;
    long long max = nums[0];
    long long secondMax = std::numeric_limits<long long>::min();
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] > max) {
            secondMax = max;
            max = nums[i];
            maxIndex = static_cast<int>(i);
        } else if (nums[i] > secondMax) {
            secondMax = nums[i];
        }
    }
    return (max >= 2 * secondMax) ? maxIndex : -1;
}

