int minCostClimbingStairs(const std::vector<int>& cost) {
    std::size_t n = cost.size();
    std::vector<int> dp(n);
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (std::size_t i = 2; i < n; ++i) {
        dp[i] = std::min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return std::min(dp[n - 1], dp[n - 2]);
}

