int openLock(const std::vector<std::string>& deadends, const std::string& target) {
    std::unordered_set<std::string> dead(deadends.begin(), deadends.end());
    if (dead.find("0000") != dead.end()) {
        return -1;
    }
    std::queue<std::pair<std::string, int>> q;
    q.push({"0000", 0});
    std::unordered_set<std::string> visited;
    visited.insert("0000");
    while (!q.empty()) {
        std::string lock = q.front().first;
        int turns = q.front().second;
        q.pop();
        for (int i = 0; i < 4; ++i) {
            for (int j = -1; j <= 1; j += 2) {
                std::string nextLock = lock;
                int digit = lock[i] - '0';
                int newDigit = (digit + j + 10) % 10;
                nextLock[i] = static_cast<char>('0' + newDigit);
                if (nextLock == target) {
                    return turns + 1;
                }
                if (dead.find(nextLock) == dead.end() && visited.find(nextLock) == visited.end()) {
                    q.push({nextLock, turns + 1});
                    visited.insert(nextLock);
                }
            }
        }
    }
    return -1;
}

