void dfs(std::string& result, std::unordered_set<std::string>& visited, int n, int k, const std::string& node) {
    for (int i = 0; i < k; ++i) {
        std::string edge = node + static_cast<char>('0' + i);
        if (visited.find(edge) != visited.end()) {
            continue;
        }
        visited.insert(edge);
        dfs(result, visited, n, k, edge.substr(1));
        result.push_back(static_cast<char>('0' + i));
    }
}

std::string crackSafe(int n, int k) {
    std::string start(n > 1 ? n - 1 : 0, '0');
    std::string result;
    std::unordered_set<std::string> visited;
    dfs(result, visited, n, k, start);
    result.append(start);
    return result;
}

#include <bits/stdc++.h>

int containVirus(std::vector<std::vector<int>>& isInfected) {
    int m = static_cast<int>(isInfected.size());
    int n = static_cast<int>(isInfected[0].size());
    int totalWalls = 0;
    const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
    while (true) {
        std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));
        struct Region {
            std::vector<std::pair<int,int>> cells;
            std::vector<std::pair<int,int>> frontier;
            int walls = 0;
        };
        std::vector<Region> regions;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (isInfected[i][j] == 1 && !visited[i][j]) {
                    Region reg;
                    std::function<void(int,int)> dfs = [&](int x, int y) {
                        visited[x][y] = true;
                        reg.cells.emplace_back(x, y);
                        for (const auto& d : dirs) {
                            int nx = x + d[0];
                            int ny = y + d[1];
                            if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                            if (isInfected[nx][ny] == 1 && !visited[nx][ny]) {
                                dfs(nx, ny);
                            } else if (isInfected[nx][ny] == 0) {
                                ++reg.walls;
                                reg.frontier.emplace_back(nx, ny);
                            }
                        }
                    };
                    dfs(i, j);
                    // deduplicate frontier cells
                    std::unordered_set<int> uniq;
                    std::vector<std::pair<int,int>> uniqFrontier;
                    uniqFrontier.reserve(reg.frontier.size());
                    for (auto& p : reg.frontier) {
                        int code = p.first * n + p.second;
                        if (uniq.insert(code).second) {
                            uniqFrontier.push_back(p);
                        }
                    }
                    reg.frontier.swap(uniqFrontier);
                    regions.push_back(std::move(reg));
                }
            }
        }
        if (regions.empty()) break;
        int bestIdx = -1;
        size_t maxFrontier = 0;
        for (size_t i = 0; i < regions.size(); ++i) {
            if (regions[i].frontier.size() > maxFrontier) {
                maxFrontier = regions[i].frontier.size();
                bestIdx = static_cast<int>(i);
            }
        }
        if (bestIdx == -1) break;
        totalWalls += regions[bestIdx].walls;
        for (auto& p : regions[bestIdx].cells) {
            isInfected[p.first][p.second] = -1;
        }
        for (size_t i = 0; i < regions.size(); ++i) {
            if (static_cast<int>(i) == bestIdx) continue;
            for (auto& p : regions[i].frontier) {
                isInfected[p.first][p.second] = 1;
            }
        }
    }
    return totalWalls;
}

