int calPoints(const std::vector<std::string>& operations) {
    std::vector<int> scores;
    for (const std::string& operation : operations) {
        if (operation != "C" && operation != "D" && operation != "+") {
            scores.push_back(std::stoi(operation));
        } else if (operation == "C") {
            scores.pop_back();
        } else if (operation == "D") {
            scores.push_back(2 * scores.back());
        } else if (operation == "+") {
            scores.push_back(scores.back() + scores[scores.size() - 2]);
        }
    }
    int total = 0;
    for (int v : scores) {
        total += v;
    }
    return total;
}

