long long findKthNumber(long long m, long long n, long long k) {
    long long left = 1;
    long long right = m * n;
    while (left < right) {
        long long mid = (left + right) / 2;
        long long count = 0;
        long long j = n;
        for (long long i = 1; i <= m; ++i) {
            while (j > 0 && i * j > mid) {
                --j;
            }
            count += j;
        }
        if (count < k) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

