std::string findClosestPalindrome(const std::string& n) {
    long long num = std::stoll(n);
    int len = static_cast<int>(n.size());
    std::vector<std::string> candidates;

    // Edge candidates: 10...01 and 9...9 (or "0" when length is 1)
    candidates.push_back(std::string("1") + std::string(len - 1, '0') + "1");
    candidates.push_back(len == 1 ? std::string("0") : std::string(len - 1, '9'));

    // Prefix for mirroring
    int prefixLen = (len + 1) / 2;
    long long prefix = std::stoll(n.substr(0, prefixLen));

    for (int delta = -1; delta <= 1; ++delta) {
        long long p = prefix + delta;
        if (p < 0) continue;
        std::string pStr = std::to_string(p);
        std::string left = pStr;
        std::string rev = left;
        if (len % 2 == 1) rev.pop_back();
        std::reverse(rev.begin(), rev.end());
        candidates.push_back(left + rev);
    }

    long long bestDiff = LLONG_MAX;
    long long bestVal = 0;
    for (const std::string& candStr : candidates) {
        if (candStr == n) continue;
        long long candVal = std::stoll(candStr);
        long long diff = std::llabs(candVal - num);
        if (diff < bestDiff || (diff == bestDiff && candVal < bestVal)) {
            bestDiff = diff;
            bestVal = candVal;
        }
    }
    return std::to_string(bestVal);
}

