std::string shortestCompletingWord(const std::string& licensePlate, const std::vector<std::string>& words) {
    std::unordered_map<char, int> licensePlateMap;
    for (char ch : licensePlate) {
        char c = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        if (c >= 'a' && c <= 'z') {
            ++licensePlateMap[c];
        }
    }

    std::string shortestWord;
    int shortestLength = std::numeric_limits<int>::max();

    for (const std::string& word : words) {
        std::unordered_map<char, int> wordMap;
        for (char ch : word) {
            char c = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
            ++wordMap[c];
        }

        bool isCompletingWord = true;
        for (const auto& entry : licensePlateMap) {
            char c = entry.first;
            int required = entry.second;
            if (wordMap.find(c) == wordMap.end() || wordMap[c] < required) {
                isCompletingWord = false;
                break;
            }
        }

        if (isCompletingWord && static_cast<int>(word.length()) < shortestLength) {
            shortestWord = word;
            shortestLength = static_cast<int>(word.length());
        }
    }

    return shortestWord;
}

