bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    int i = 5;
    while (i * i <= n) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
        i += 6;
    }
    return true;
}

int countPrimeSetBits(int left, int right) {
    int count = 0;
    for (int i = left; i <= right; ++i) {
        std::string bin = std::bitset<64>(static_cast<unsigned long long>(i)).to_string();
        int setBits = std::count(bin.begin(), bin.end(), '1');
        if (isPrime(setBits)) ++count;
    }
    return count;
}

