int intersectionSize(std::vector<std::vector<int>>& intervals) {
    std::sort(intervals.begin(), intervals.end(),
        [](const std::vector<int>& a, const std::vector<int>& b) {
            if (a[1] != b[1]) return a[1] < b[1];
            return a[0] > b[0];
        });
    int count = 0;
    int first = -1, second = -1; // first < second
    for (const auto& iv : intervals) {
        int l = iv[0], r = iv[1];
        if (l > second) {
            first = r - 1;
            second = r;
            count += 2;
        } else if (l > first) {
            int newPoint = (second == r) ? r - 1 : r;
            first = second;
            second = newPoint;
            ++count;
        }
    }
    return count;
}

