std::vector<int> partitionLabels(const std::string& s) {
    std::unordered_map<char, std::size_t> lastIndex;
    for (std::size_t i = 0; i < s.size(); ++i) {
        lastIndex[s[i]] = i;
    }
    std::vector<int> result;
    std::size_t start = 0, end = 0;
    for (std::size_t i = 0; i < s.size(); ++i) {
        end = std::max(end, lastIndex[s[i]]);
