int minSwapsCouples(std::vector<int>& row) {
    std::size_t n = row.size();
    int count = 0;
    for (std::size_t i = 0; i < n; i += 2) {
        if (row[i] % 2 == 0 && row[i + 1] != row[i] + 1) {
            for (std::size_t j = i + 1; j < n; ++j) {
                if (row[j] == row[i] + 1) {
                    std::swap(row[i + 1], row[j]);
                    ++count;
                    break;
                }
            }
        } else if (row[i] % 2 == 1 && row[i + 1] != row[i] - 1) {
            for (std::size_t j = i + 1; j < n; ++j) {
                if (row[j] == row[i] - 1) {
                    std::swap(row[i + 1], row[j]);
                    ++count;
                    break;
                }
            }
        }
    }
    return count;
}

