int orderOfLargestPlusSign(int n, const std::vector<std::vector<int>>& mines) {
    std::vector<std::vector<int>> grid(n, std::vector<int>(n, 1));
    for (const auto& mine : mines) {
        if (mine.size() >= 2) {
            grid[mine[0]][mine[1]] = 0;
        }
    }
    int maxOrder = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                int order = 1;
                while (i - order >= 0 && i + order < n && j - order >= 0 && j + order < n &&
                       grid[i - order][j] == 1 && grid[i + order][j] == 1 &&
                       grid[i][j - order] == 1 && grid[i][j + order] == 1) {
                    ++order;
                }
                maxOrder = std::max(maxOrder, order);
            }
        }
    }
    return maxOrder;
}

