std::string makeLargestSpecial(const std::string& s) {
    int count = 0;
    int i = 0;
    std::vector<std::string> result;
    for (int j = 0; j < static_cast<int>(s.size()); ++j) {
        if (s[j] == '1') ++count;
        else --count;
        if (count == 0) {
            std::string inner = makeLargestSpecial(s.substr(i + 1, j - i - 1));
            result.push_back(std::string("1") + inner + "0");
            i = j + 1;
        }
    }
    std::sort(result.begin(), result.end(), std::greater<std::string>());
    std::string out;
    for (const auto& part : result) {
        out += part;
    }
    return out;
}

