std::string reorganizeString(const std::string& s) {
    std::unordered_map<char, int> frequencyMap;
    for (char ch : s) {
        if (!frequencyMap.count(ch)) frequencyMap[ch] = 0;
        frequencyMap[ch]++;
    }

    std::vector<std::pair<char, int>> maxHeap;
    for (const auto& entry : frequencyMap) {
        maxHeap.push_back({entry.first, entry.second});
    }
    std::sort(maxHeap.begin(), maxHeap.end(),
              [](const std::pair<char, int>& a, const std::pair<char, int>& b) {
                  return b.second < a.second;
              });

    std::string result;

    while (!maxHeap.empty()) {
        if (!result.empty() && result.back() == maxHeap[0].first) {
            if (maxHeap.size() == 1) return "";
            std::pair<char, int> secondChar = maxHeap[1];
            result += secondChar.first;
            secondChar.second--;
            if (secondChar.second == 0) {
                maxHeap.erase(maxHeap.begin() + 1);
            } else {
                maxHeap[1] = secondChar;
            }
            std::pair<char, int> firstChar = maxHeap[0];
            maxHeap.erase(maxHeap.begin());
            maxHeap.push_back(firstChar);
        } else {
            std::pair<char, int> topChar = maxHeap[0];
            maxHeap.erase(maxHeap.begin());
            result += topChar.first;
            topChar.second--;
            if (topChar.second > 0) {
                maxHeap.push_back(topChar);
            }
        }
        std::sort(maxHeap.begin(), maxHeap.end(),
                  [](const std::pair<char, int>& a, const std::pair<char, int>& b) {
                      return b.second < a.second;
                  });
    }
    return result;
}

