bool pyramidTransition(const std::string& bottom, const std::vector<std::string>& allowed) {
    std::unordered_map<std::string, std::vector<char>> allowedMap;
    for (const std::string& pattern : allowed) {
        std::string key = pattern.substr(0, 2);
        allowedMap[key].push_back(pattern[2]);
    }
    std::unordered_map<std::string, bool> memo;
    std::function<bool(const std::string&)> dfs = [&](const std::string& cur) -> bool {
        if (cur.size() == 1) return true;
        auto memoIt = memo.find(cur);
        if (memoIt != memo.end()) return memoIt->second;
        std::vector<std::string> next;
        for (size_t i = 0; i + 1 < cur.size(); ++i) {
            std::string pair = cur.substr(i, 2);
            auto it = allowedMap.find(pair);
            if (it == allowedMap.end()) return memo[cur] = false;
            const std::vector<char>& candidates = it->second;
            if (next.empty()) {
                next.reserve(candidates.size());
                for (char c : candidates) {
                    next.emplace_back(1, c);
                }
            } else {
                std::vector<std::string> temp;
                temp.reserve(next.size() * candidates.size());
                for (const std::string& n : next) {
                    for (char c : candidates) {
                        temp.push_back(n + c);
                    }
                }
                next = std::move(temp);
            }
        }
        for (const std::string& n : next) {
            if (dfs(n)) return memo[cur] = true;
        }
        return memo[cur] = false;
    };
    return dfs(bottom);
}

