using Poly = std::map<std::vector<std::string>, long long>;

static bool isNumber(const std::string& s) {
    return !s.empty() && std::all_of(s.begin(), s.end(), ::isdigit);
}

static Poly addPoly(const Poly& a, const Poly& b, int sign = 1) {
    Poly res = a;
    for (const auto& kv : b) {
        res[kv.first] += sign * kv.second;
        if (res[kv.first] == 0) res.erase(kv.first);
    }
    return res;
}

static Poly mulPoly(const Poly& a, const Poly& b) {
    Poly res;
    for (const auto& kv1 : a) {
        for (const auto& kv2 : b) {
            std::vector<std::string> mono = kv1.first;
            mono.insert(mono.end(), kv2.first.begin(), kv2.first.end());
            std::sort(mono.begin(), mono.end());
            long long coeff = kv1.second * kv2.second;
            res[mono] += coeff;
            if (res[mono] == 0) res.erase(mono);
        }
    }
    return res;
}

static Poly parseExpression(const std::vector<std::string>& tokens, int& idx,
                            const std::unordered_map<std::string, long long>& evalMap);

static Poly parseFactor(const std::vector<std::string>& tokens, int& idx,
                        const std::unordered_map<std::string, long long>& evalMap) {
    const std::string& tok = tokens[idx];
    if (tok == "(") {
        ++idx; // skip '('
        Poly inside = parseExpression(tokens, idx, evalMap);
        ++idx; // skip ')'
        return inside;
    } else if (isNumber(tok)) {
        long long val = std::stoll(tok);
        ++idx;
        Poly p;
        p[{}] = val;
        return p;
    } else { // variable
        ++idx;
        auto it = evalMap.find(tok);
        if (it != evalMap.end()) {
            Poly p;
            p[{}] = it->second;
            return p;
        } else {
            Poly p;
            p[{tok}] = 1;
            return p;
        }
    }
}

static Poly parseTerm(const std::vector<std::string>& tokens, int& idx,
                      const std::unordered_map<std::string, long long>& evalMap) {
    Poly cur = parseFactor(tokens, idx, evalMap);
    while (idx < (int)tokens.size() && tokens[idx] == "*") {
        ++idx; // skip '*'
        Poly nxt = parseFactor(tokens, idx, evalMap);
        cur = mulPoly(cur, nxt);
    }
    return cur;
}

static Poly parseExpression(const std::vector<std::string>& tokens, int& idx,
                            const std::unordered_map<std::string, long long>& evalMap) {
    Poly cur = parseTerm(tokens, idx, evalMap);
    while (idx < (int)tokens.size() && (tokens[idx] == "+" || tokens[idx] == "-")) {
        std::string op = tokens[idx++];
        Poly nxt = parseTerm(tokens, idx, evalMap);
        if (op == "+")
            cur = addPoly(cur, nxt, 1);
        else
            cur = addPoly(cur, nxt, -1);
    }
    return cur;
}

std::vector<std::string> basicCalculatorIV(std::string expression,
                                            std::vector<std::string> evalvars,
                                            std::vector<int> evalints) {
    // Tokenize
    std::vector<std::string> tokens;
    std::string cur;
    for (char c : expression) {
        if (c == ' ') continue;
        if (c == '(' || c == ')' || c == '+' || c == '-' || c == '*') {
            if (!cur.empty()) {
                tokens.push_back(cur);
                cur.clear();
            }
            tokens.emplace_back(1, c);
        } else {
            cur.push_back(c);
        }
    }
    if (!cur.empty()) tokens.push_back(cur);

    // Build eval map
    std::unordered_map<std::string, long long> evalMap;
    for (size_t i = 0; i < evalvars.size(); ++i) {
        evalMap[evalvars[i]] = evalints[i];
    }

    int idx = 0;
    Poly result = parseExpression(tokens, idx, evalMap);

    // Prepare output
    struct Term {
        std::vector<std::string> mono;
        long long coeff;
    };
    std::vector<Term> terms;
    for (auto& kv : result) {
        if (kv.second != 0) terms.push_back({kv.first, kv.second});
    }
    std::sort(terms.begin(), terms.end(),
              [](const Term& a, const Term& b) {
                  if (a.mono.size() != b.mono.size())
                      return a.mono.size() > b.mono.size(); // degree descending
                  return a.mono < b.mono; // lexicographic
              });

    std::vector<std::string> output;
    for (const auto& t : terms) {
        std::string s = std::to_string(t.coeff);
        for (const auto& var : t.mono) {
            s.push_back('*');
            s += var;
        }
        output.push_back(s);
    }
    return output;
}

