bool canTransform(const std::string& start, const std::string& result) {
    size_t startPointer = 0, resultPointer = 0;
    while (startPointer < start.size() && resultPointer < result.size()) {
        while (startPointer < start.size() && start[startPointer] == 'X') ++startPointer;
        while (resultPointer < result.size() && result[resultPointer] == 'X') ++resultPointer;
        if (startPointer == start.size() && resultPointer == result.size()) return true;
        if (startPointer == start.size() || resultPointer == result.size()) return false;
        if (start[startPointer] != result[resultPointer]) return false;
        if ((start[startPointer] == 'L' && startPointer < resultPointer) ||
            (start[startPointer] == 'R' && startPointer > resultPointer)) return false;
        ++startPointer;
        ++resultPointer;
    }
    return true;
}

