int slidingPuzzle(std::vector<std::vector<int>> board) {
    const std::vector<std::vector<int>> target = {{1,2,3},{4,5,0}};
    const std::vector<std::vector<int>> directions = {{1,3},{0,2,4},{1,5},{0,4},{1,3,5},{2,4}};
    auto serialize = [](const std::vector<std::vector<int>>& b) -> std::string {
        std::string s = "[";
        for (size_t i = 0; i < b.size(); ++i) {
            s += "[";
            for (size_t j = 0; j < b[i].size(); ++j) {
                s += std::to_string(b[i][j]);
                if (j + 1 < b[i].size()) s += ",";
            }
            s += "]";
            if (i + 1 < b.size()) s += ",";
        }
        s += "]";
        return s;
    };
    std::deque<std::pair<std::vector<std::vector<int>>, int>> queue;
    queue.emplace_back(board, 0);
    std::unordered_set<std::string> visited;
    visited.insert(serialize(board));
    const std::string targetStr = serialize(target);
    while (!queue.empty()) {
        auto current = queue.front();
        queue.pop_front();
        const std::vector<std::vector<int>>& state = current.first;
        int moves = current.second;
        if (serialize(state) == targetStr) return moves;
        int zeroIndex = -1;
        for (int i = 0; i < 2; ++i) {
            for (int j = 0; j < 3; ++j) {
                if (state[i][j] == 0) {
                    zeroIndex = i * 3 + j;
                    break;
                }
            }
            if (zeroIndex != -1) break;
        }
        for (int dir : directions[zeroIndex]) {
            std::vector<std::vector<int>> nextState = state;
            int zr = zeroIndex / 3;
            int zc = zeroIndex % 3;
            int nr = dir / 3;
            int nc = dir % 3;
            std::swap(nextState[zr][zc], nextState[nr][nc]);
            std::string nextStr = serialize(nextState);
            if (visited.find(nextStr) == visited.end()) {
                queue.emplace_back(std::move(nextState), moves + 1);
                visited.insert(std::move(nextStr));
            }
        }
    }
    return -1;
}

