int movesToMakeBoard(const std::vector<std::vector<int>>& board) {
    int n = static_cast<int>(board.size());
    if (n == 0) return 0;
    // Validate board can be transformed
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if ((board[0][0] ^ board[i][0] ^ board[0][j] ^ board[i][j]) != 0) {
                return -1;
            }
        }
    }
    // Extract first column and first row patterns
    std::vector<int> rowPattern(n), colPattern(n);
    for (int i = 0; i < n; ++i) {
        rowPattern[i] = board[i][0];
        colPattern[i] = board[0][i];
    }
    int rowSum = std::accumulate(rowPattern.begin(), rowPattern.end(), 0);
    int colSum = std::accumulate(colPattern.begin(), colPattern.end(), 0);
    // Check counts of 1s are valid
    if (std::abs(rowSum - n / 2) > (n % 2)) return -1;
    if (std::abs(colSum - n / 2) > (n % 2)) return -1;
    // Count swaps needed for rows and columns
    int rowSwap = 0, colSwap = 0;
    for (int i = 0; i < n; ++i) {
        if (rowPattern[i] == i % 2) ++rowSwap;
        if (colPattern[i] == i % 2) ++colSwap;
    }
    if (n % 2 == 0) {
        rowSwap = std::min(rowSwap, n - rowSwap);
        colSwap = std::min(colSwap, n - colSwap);
    } else {
        if (rowSwap % 2 == 1) rowSwap = n - rowSwap;
        if (colSwap % 2 == 1) colSwap = n - colSwap;
    }
    return (rowSwap + colSwap) / 2;
}

