std::vector<std::string> letterCasePermutation(const std::string& s) {
    std::vector<std::string> result;
    std::function<void(const std::string&, size_t)> backtrack = [&](const std::string& current, size_t index) {
        if (index == s.size()) {
            result.push_back(current);
        } else {
            char c = s[index];
            if (std::isalpha(static_cast<unsigned char>(c))) {
                backtrack(current + static_cast<char>(std::tolower(static_cast<unsigned char>(c))), index + 1);
                backtrack(current + static_cast<char>(std::toupper(static_cast<unsigned char>(c))), index + 1);
            } else {
                backtrack(current + c, index + 1);
            }
        }
    };
    backtrack("", 0);
    return result;
}

