std::vector<int> kthSmallestPrimeFraction(const std::vector<int>& arr, int k) {
    int n = static_cast<int>(arr.size());
    struct Node { int i; int j; };
    auto cmp = [&](const Node& a, const Node& b) {
        return static_cast<long long>(arr[a.i]) * arr[b.j] > static_cast<long long>(arr[b.i]) * arr[a.j];
    };
    std::priority_queue<Node, std::vector<Node>, decltype(cmp)> pq(cmp);
    for (int i = 0; i < n - 1; ++i) {
        pq.push({i, n - 1});
    }
    Node cur{0, 0};
    for (int count = 0; count < k; ++count) {
        cur = pq.top();
        pq.pop();
        if (cur.j - 1 > cur.i) {
            pq.push({cur.i, cur.j - 1});
        }
    }
    return {arr[cur.i], arr[cur.j]};
}

