int numTilings(int n) {
    const long long MOD = 1000000007LL;
    if (n == 0) return 0;
    if (n == 1) return 1;
    if (n == 2) return 2;
    if (n == 3) return 5;
    std::vector<long long> dp(n + 1, 0);
    dp[0] = 0;
    dp[1] = 1;
    dp[2] = 2;
    dp[3] = 5;
    for (int i = 4; i <= n; ++i) {
        dp[i] = (2 * dp[i - 1] + dp[i - 3]) % MOD;
    }
    return static_cast<int>(dp[n]);
}

