long long preimageSizeFZF(long long k) {
    auto findTrailingZeroes = [](long long x) -> long long {
        long long count = 0;
        long long i = 5;
        while (x / i >= 1) {
            count += x / i;
            i *= 5;
        }
        return count;
    };
    long long left = 0, right = 5 * k;
    while (left < right) {
        long long mid = (left + right) / 2;
        if (findTrailingZeroes(mid) < k) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    if (findTrailingZeroes(left) != k) {
        return 0;
    }
    long long count = 1;
    long long i = 1;
    while (findTrailingZeroes(left + i) == k) {
        ++count;
        ++i;
    }
    i = 1;
    while (left - i >= 0 && findTrailingZeroes(left - i) == k) {
        ++count;
        ++i;
    }
    return count;
}

