int rotateNumber(int x) {
    long long rotated = 0;
    long long multiplier = 1;
    while (x > 0) {
        int d = x % 10;
        int rd;
        switch (d) {
            case 0: rd = 0; break;
            case 1: rd = 1; break;
            case 2: rd = 5; break;
            case 5: rd = 2; break;
            case 6: rd = 9; break;
            case 8: rd = 8; break;
            case 9: rd = 6; break;
            default: return -1;
        }
        rotated = rd * multiplier + rotated;
        multiplier *= 10;
        x /= 10;
    }
    return static_cast<int>(rotated);
}

int rotatedDigits(int n) {
    int count = 0;
    for (int i = 1; i <= n; ++i) {
