int findCheapestPrice(int n, const std::vector<std::vector<int>>& flights, int src, int dst, int k) {
    std::vector<std::vector<std::pair<int, int>>> graph(n);
    for (int i = 0; i < n; ++i) {
        graph[i] = {};
    }
    for (const auto& f : flights) {
        int from = f[0];
        int to = f[1];
        int price = f[2];
        graph[from].push_back({to, price});
    }
    std::deque<std::tuple<int, long long, int>> queue;
    queue.emplace_back(src, 0LL, k + 1);
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<long long> prices(n, INF);
    prices[src] = 0;
    while (!queue.empty()) {
        auto cur = queue.front();
        queue.pop_front();
        int city = std::get<0>(cur);
        long long price = std::get<1>(cur);
        int stops = std::get<2>(cur);
        if (city == dst) {
            prices[dst] = std::min(prices[dst], price);
        }
        if (stops == 0) {
            continue;
        }
        for (const auto& neighborInfo : graph[city]) {
            int neighbor = neighborInfo.first;
            int neighborPrice = neighborInfo.second;
            long long newPrice = price + neighborPrice;
            if (newPrice < prices[neighbor]) {
                prices[neighbor] = newPrice;
                queue.emplace_back(neighbor, newPrice, stops - 1);
            }
        }
    }
    return prices[dst] == INF ? -1 : static_cast<int>(prices[dst]);
}

