double champagneTower(double poured, int query_row, int query_glass) {
    std::vector<std::vector<double>> champagne(query_row + 1, std::vector<double>(query_row + 1, 0.0));
    champagne[0][0] = poured;
    for (int i = 0; i < query_row; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (champagne[i][j] > 1.0) {
                double excess = (champagne[i][j] - 1.0) / 2.0;
                champagne[i + 1][j] += excess;
                champagne[i + 1][j + 1] += excess;
                champagne[i][j] = 1.0;
            }
        }
    }
    return std::min(1.0, champagne[query_row][query_glass]);
}

