int minSwap(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::size_t n = nums1.size();
    if (n == 0) return 0;
    const int INF = static_cast<int>(n) + 5;
    int keep = 0;
    int swap = 1;
    for (std::size_t i = 1; i < n; ++i) {
        int newKeep = INF;
        int newSwap = INF;
        if (nums1[i] > nums1[i - 1] && nums2[i] > nums2[i - 1]) {
            newKeep = std::min(newKeep, keep);
            newSwap = std::min(newSwap, swap + 1);
        }
        if (nums1[i] > nums2[i - 1] && nums2[i] > nums1[i - 1]) {
            newKeep = std::min(newKeep, swap);
            newSwap = std::min(newSwap, keep + 1);
        }
        keep = newKeep;
        swap = newSwap;
    }
    return std::min(keep, swap);
}

