#include <bits/stdc++.h>

std::vector<int> hitBricks(std::vector<std::vector<int>>& grid, std::vector<std::vector<int>>& hits) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    int total = m * n;
    int top = total; // virtual top node

    struct DSU {
        std::vector<int> parent;
        std::vector<int> size;
        DSU(int n) : parent(n), size(n, 1) {
            for (int i = 0; i < n; ++i) parent[i] = i;
        }
        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }
        void unite(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) std::swap(ra, rb);
            parent[rb] = ra;
            size[ra] += size[rb];
        }
        int componentSize(int x) {
            return size[find(x)];
        }
    };

    // Mark bricks to be removed
    std::vector<std::vector<int>> copy = grid;
    for (const auto& h : hits) {
        int r = h[0], c = h[1];
        if (copy[r][c] == 1) copy[r][c] = 2; // mark as to be removed
    }

    DSU dsu(total + 1);

    auto index = [&](int r, int c) { return r * n + c; };

    // Initial unions after removals
    for (int r = 0; r < m; ++r) {
        for (int c = 0; c < n; ++c) {
            if (copy[r][c] != 1) continue;
            if (r == 0) dsu.unite(index(r, c), top);
            const int dr[4] = {0, 0, 1, -1};
            const int dc[4] = {1, -1, 0, 0};
            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && copy[nr][nc] == 1) {
                    dsu.unite(index(r, c), index(nr, nc));
                }
            }
        }
    }

    std::vector<int> result(hits.size(), 0);
    for (int i = static_cast<int>(hits.size()) - 1; i >= 0; --i) {
        int r = hits[i][0];
        int c = hits[i][1];
        if (grid[r][c] == 0) {
            // original cell had no brick
            result[i] = 0;
            continue;
        }
        // original brick existed
        int prevTopSize = dsu.componentSize(top);
        // restore brick
        copy[r][c] = 1;
        if (r == 0) dsu.unite(index(r, c), top);
        const int dr[4] = {0, 0, 1, -1};
        const int dc[4] = {1, -1, 0, 0};
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && copy[nr][nc] == 1) {
                dsu.unite(index(r, c), index(nr, nc));
            }
        }
        int newTopSize = dsu.componentSize(top);
        int fallen = newTopSize - prevTopSize - 1;
        result[i] = fallen > 0 ? fallen : 0;
    }
    return result;
}

