double soupServings(int n) {
    if (n > 4800) return 1.0;
    int m = (n + 24) / 25;
    std::vector<std::vector<double>> memo(m + 1, std::vector<double>(m + 1, -1.0));
    std::function<double(int, int)> dfs = [&](int a, int b) -> double {
        if (a <= 0 && b <= 0) return 0.5;
        if (a <= 0) return 1.0;
        if (b <= 0) return 0.0;
        if (memo[a][b] >= 0) return memo[a][b];
        double prob = 0.25 * (dfs(a - 4, b) + dfs(a - 3, b - 1) + dfs(a - 2, b - 2) + dfs(a - 1, b - 3));
        memo[a][b] = prob;
        return prob;
    };
    return dfs(m, m);
}

