std::vector<std::string> subdomainVisits(const std::vector<std::string>& cpdomains) {
    std::unordered_map<std::string, long long> domainCount;
    std::vector<std::string> result;

    for (size_t i = 0; i < cpdomains.size(); ++i) {
        const std::string& entry = cpdomains[i];
        size_t spacePos = entry.find(' ');
        std::string countStr = entry.substr(0, spacePos);
        std::string domain = entry.substr(spacePos + 1);
        long long count = std::stoll(countStr);

        std::vector<std::string> subdomains;
        size_t start = 0;
        while (true) {
            size_t dotPos = domain.find('.', start);
            if (dotPos == std::string::npos) {
                subdomains.push_back(domain.substr(start));
                break;
            } else {
                subdomains.push_back(domain.substr(start, dotPos - start));
                start = dotPos + 1;
            }
        }

        for (size_t j = 0; j < subdomains.size(); ++j) {
            std::string subdomain = subdomains[j];
            for (size_t k = j + 1; k < subdomains.size(); ++k) {
                subdomain += "." + subdomains[k];
            }
            domainCount[subdomain] += count;
        }
    }

    for (const auto& kv : domainCount) {
        result.push_back(std::to_string(kv.second) + " " + kv.first);
    }

    return result;
}

