int expressiveWords(const std::string& s, const std::vector<std::string>& words) {
    int count = 0;
    for (const std::string& word : words) {
        std::size_t i = 0, j = 0;
        while (i < s.size() && j < word.size()) {
            if (s[i] != word[j]) break;
            char charS = s[i];
            char charWord = word[j];
            int countS = 0, countWord = 0;
            while (i < s.size() && s[i] == charS) { ++countS; ++i; }
            while (j < word.size() && word[j] == charWord) { ++countWord; ++j; }
            if (countWord > countS || (countS < 3 && countS != countWord)) break;
        }
        if (i == s.size() && j == word.size()) ++count;
    }
    return count;
}

