std::string mostCommonWord(const std::string& paragraph, const std::vector<std::string>& banned) {
    std::string cleaned;
    cleaned.reserve(paragraph.size());
    for (char ch : paragraph) {
        char lower = std::tolower(static_cast<unsigned char>(ch));
        if ((lower >= 'a' && lower <= 'z') || (lower >= '0' && lower <= '9')) {
            cleaned.push_back(lower);
        } else {
            cleaned.push_back(' ');
        }
    }
    std::unordered_map<std::string, int> wordCount;
    std::istringstream iss(cleaned);
    std::string word;
    while (iss >> word) {
        ++wordCount[word];
    }
    std::unordered_set<std::string> bannedSet;
    for (const auto& w : banned) {
        std::string lowerW;
        lowerW.reserve(w.size());
        for (char ch : w) {
            lowerW.push_back(std::tolower(static_cast<unsigned char>(ch)));
        }
        bannedSet.insert(lowerW);
    }
    int maxCount = 0;
    std::string result;
    for (const auto& kv : wordCount) {
        const std::string& w = kv.first;
        int cnt = kv.second;
        if (bannedSet.find(w) == bannedSet.end() && cnt > maxCount) {
            maxCount = cnt;
            result = w;
        }
    }
    return result;
}

