int numBusesToDestination(const std::vector<std::vector<int>>& routes, int source, int target) {
    if (source == target) return 0;
    std::unordered_map<int, std::vector<int>> busStops;
    for (size_t i = 0; i < routes.size(); ++i) {
        for (int stop : routes[i]) {
            busStops[stop].push_back(static_cast<int>(i));
        }
    }
    std::queue<std::pair<int, int>> q;
    q.emplace(source, 0);
    std::unordered_set<int> visitedStops;
    visitedStops.insert(source);
    std::unordered_set<int> visitedBuses;
    while (!q.empty()) {
        int stop = q.front().first;
        int busCount = q.front().second;
        q.pop();
        if (stop == target) return busCount;
        auto it = busStops.find(stop);
        if (it == busStops.end()) continue;
        for (int bus : it->second) {
            if (visitedBuses.find(bus) != visitedBuses.end()) continue;
            visitedBuses.insert(bus);
            for (int nextStop : routes[bus]) {
                if (visitedStops.find(nextStop) != visitedStops.end()) continue;
                visitedStops.insert(nextStop);
                q.emplace(nextStop, busCount + 1);
            }
        }
    }
    return -1;
}

