std::vector<std::string> generateNumbers(const std::string& s) {
    std::vector<std::string> res;
    int n = static_cast<int>(s.size());
    if (n == 0) return res;
    if (n == 1) {
        res.push_back(s);
        return res;
    }
    bool leadingZero = (s[0] == '0');
    bool trailingZero = (s[n - 1] == '0');
    if (leadingZero && trailingZero) {
        return res;
    }
    if (leadingZero) {
        if (!trailingZero) {
            res.push_back("0." + s.substr(1));
        }
        return res;
    }
    if (trailingZero) {
        res.push_back(s);
        return res;
    }
    res.push_back(s);
    for (int i = 1; i < n; ++i) {
        std::string left = s.substr(0, i);
        std::string right = s.substr(i);
        res.push_back(left + "." + right);
    }
    return res;
}

std::vector<std::string> ambiguousCoordinates(const std::string& s) {
    std::string inner = s.substr(1, s.size() - 2);
    std::vector<std::string> result;
    int len = static_cast<int>(inner.size());
    for (int i = 1; i < len; ++i) {
        std::string left = inner.substr(0, i);
        std::string right = inner.substr(i);
        std::vector<std::string> leftNums = generateNumbers(left);
        std::vector<std::string> rightNums = generateNumbers(right);
        for (const std::string& leftNum : leftNums) {
            for (const std::string& rightNum : rightNums) {
                result.push_back("(" + leftNum + ", " + rightNum + ")");
            }
        }
    }
    std::sort(result.begin(), result.end());
    return result;
}

