int racecar(int target) {
    std::queue<std::array<int, 3>> queue;
    queue.push({0, 1, 0});
    std::unordered_set<std::string> visited;
    while (!queue.empty()) {
        std::array<int, 3> cur = queue.front();
        queue.pop();
        int position = cur[0];
        int speed = cur[1];
        int steps = cur[2];
        if (position == target) {
            return steps;
        }
        std::string state = std::to_string(position) + "," + std::to_string(speed);
        if (visited.find(state) != visited.end()) {
            continue;
        }
        visited.insert(state);
        queue.push({position + speed, speed * 2, steps + 1});
        queue.push({position, -1, steps + 1});
    }
    return -1;
}

