int flipgame(const std::vector<int>& fronts, const std::vector<int>& backs) {
    std::unordered_set<int> same;
    for (size_t i = 0; i < fronts.size(); ++i) {
        if (fronts[i] == backs[i]) {
            same.insert(fronts[i]);
        }
    }
    long long result = LLONG_MAX;
    for (size_t i = 0; i < fronts.size(); ++i) {
        if (same.find(fronts[i]) == same.end()) {
            result = std::min(result, static_cast<long long>(fronts[i]));
        }
        if (same.find(backs[i]) == same.end()) {
            result = std::min(result, static_cast<long long>(backs[i]));
        }
    }
    return result == LLONG_MAX ? 0 : static_cast<int>(result);
}

