std::string toGoatLatin(const std::string& sentence) {
    std::vector<std::string> words;
    size_t pos = 0;
    while (true) {
        size_t space = sentence.find(' ', pos);
        if (space == std::string::npos) {
            words.push_back(sentence.substr(pos));
            break;
        } else {
            words.push_back(sentence.substr(pos, space - pos));
            pos = space + 1;
        }
    }
    const std::string vowels = "aeiouAEIOU";
    for (size_t i = 0; i < words.size(); ++i) {
        if (!words[i].empty() && vowels.find(words[i][0]) != std::string::npos) {
            words[i] += "ma";
        } else if (!words[i].empty()) {
            words[i] = words[i].substr(1) + words[i][0] + "ma";
        } else {
            words[i] = "ma";
        }
        words[i] += std::string(i + 1, 'a');
    }
    std::string result;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i > 0) result += ' ';
        result += words[i];
    }
    return result;
}

