long long numFactoredBinaryTrees(std::vector<int> arr) {
    const long long MOD = 1000000007LL;
    std::sort(arr.begin(), arr.end());
    std::unordered_map<int, long long> dp;
    for (size_t i = 0; i < arr.size(); ++i) {
        dp[arr[i]] = 1;
    }
    for (size_t i = 0; i < arr.size(); ++i) {
        for (size_t j = 0; j < i; ++j) {
            if (arr[i] % arr[j] == 0) {
                int otherFactor = arr[i] / arr[j];
                auto it = dp.find(otherFactor);
                if (it != dp.end()) {
                    dp[arr[i]] = (dp[arr[i]] + dp[arr[j]] * it->second) % MOD;
                }
            }
        }
    }
    long long totalTrees = 0;
    for (const auto& kv : dp) {
        totalTrees = (totalTrees + kv.second) % MOD;
    }
    return totalTrees;
}

