long long numFriendRequests(const std::vector<int>& ages) {
    const int MAX_AGE = 120;
    std::vector<int> freq(MAX_AGE + 1, 0);
    for (int age : ages) {
        if (age >= 0 && age <= MAX_AGE) {
            ++freq[age];
        }
    }
    std::vector<int> prefix(MAX_AGE + 2, 0);
    for (int i = 1; i <= MAX_AGE + 1; ++i) {
        prefix[i] = prefix[i - 1] + freq[i - 1];
    }
    long long total = 0;
    for (int a = 15; a <= MAX_AGE; ++a) {
        if (freq[a] == 0) continue;
        int lower = static_cast<int>(0.5 * a + 7);
        int start = lower + 1;
        if (start > a) continue;
        long long eligible = prefix[a + 1] - prefix[start];
        total += static_cast<long long>(freq[a]) * (eligible - 1);
    }
    return total;
}

