long long maxProfitAssignment(const std::vector<int>& difficulty, const std::vector<int>& profit, const std::vector<int>& worker) {
    std::vector<std::pair<int, int>> jobDifficultyAndProfit;
    jobDifficultyAndProfit.reserve(difficulty.size());
    for (size_t i = 0; i < difficulty.size(); ++i) {
        jobDifficultyAndProfit.emplace_back(difficulty[i], profit[i]);
    }
    std::sort(jobDifficultyAndProfit.begin(), jobDifficultyAndProfit.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  return a.first < b.first;
              });
    std::vector<int> maxProfitSoFar(jobDifficultyAndProfit.size());
    if (!jobDifficultyAndProfit.empty()) {
        maxProfitSoFar[0] = jobDifficultyAndProfit[0].second;
        for (size_t i = 1; i < jobDifficultyAndProfit.size(); ++i) {
            maxProfitSoFar[i] = std::max(maxProfitSoFar[i - 1], jobDifficultyAndProfit[i].second);
        }
    }
    long long totalMaxProfit = 0;
    for (int w : worker) {
        int left = 0;
        int right = static_cast<int>(jobDifficultyAndProfit.size()) - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (jobDifficultyAndProfit[mid].first <= w) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        if (right >= 0) {
            totalMaxProfit += maxProfitSoFar[static_cast<size_t>(right)];
        }
    }
    return totalMaxProfit;
}

#include <bits/stdc++.h>

long long countUniqueChars(const std::string& s) {
    long long result = 0;
    int n = static_cast<int>(s.size());
    std::vector<int> prev(n), next(n);
    std::unordered_map<char, int> last;
    for (int i = 0; i < n; ++i) {
        auto it = last.find(s[i]);
        prev[i] = (it != last.end()) ? it->second : -1;
        last[s[i]] = i;
    }
    last.clear();
    for (int i = n - 1; i >= 0; --i) {
        auto it = last.find(s[i]);
        next[i] = (it != last.end()) ? it->second : n;
        last[s[i]] = i;
    }
    for (int i = 0; i < n; ++i) {
        long long left = i - prev[i];
        long long right = next[i] - i;
        result += left * right;
    }
    return result;
}

