int dfs(std::vector<std::vector<int>>& grid, int i, int j, int index, const std::vector<std::pair<int,int>>& directions) {
    int n = grid.size();
    grid[i][j] = index;
    int count = 1;
    for (const auto& dir : directions) {
        int x = i + dir.first;
        int y = j + dir.second;
        if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] == 1) {
            count += dfs(grid, x, y, index, directions);
        }
    }
    return count;
}

int largestIsland(std::vector<std::vector<int>>& grid) {
    int n = grid.size();
    std::vector<std::pair<int,int>> directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    std::unordered_map<int,int> area;
    int index = 2;
    int maxArea = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                int a = dfs(grid, i, j, index, directions);
                area[index] = a;
                maxArea = std::max(maxArea, a);
                ++index;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 0) {
                int total = 1;
                std::unordered_set<int> seen;
                for (const auto& dir : directions) {
                    int x = i + dir.first;
                    int y = j + dir.second;
                    if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] > 1) {
                        int id = grid[x][y];
                        if (seen.insert(id).second) {
                            total += area[id];
                        }
                    }
                }
                maxArea = std::max(maxArea, total);
            }
        }
    }

    return maxArea;
}

