std::vector<std::vector<int>> largeGroupPositions(const std::string& s) {
    std::vector<std::vector<int>> result;
    int groupSize = 1;
    for (size_t i = 1; i < s.size(); ++i) {
        if (s[i] == s[i - 1]) {
            ++groupSize;
        } else {
            if (groupSize >= 3) {
                result.push_back({static_cast<int>(i - groupSize), static_cast<int>(i - 1)});
            }
            groupSize = 1;
        }
    }
    if (groupSize >= 3) {
        result.push_back({static_cast<int>(s.size() - groupSize), static_cast<int>(s.size() - 1)});
    }
    return result;
}

