std::string findAndReplace(const std::string& s, const std::vector<int>& indices, const std::vector<std::string>& sources, const std::vector<std::string>& targets) {
    std::unordered_map<int, int> posToIdx;
    for (size_t i = 0; i < indices.size(); ++i) {
        int idx = indices[i];
        const std::string& src = sources[i];
        if (idx + static_cast<int>(src.size()) <= static_cast<int>(s.size()) && s.compare(idx, src.size(), src) == 0) {
            posToIdx[idx] = static_cast<int>(i);
        }
    }
    std::string result;
    for (size_t i = 0; i < s.size(); ) {
        auto it = posToIdx.find(static_cast<int>(i));
        if (it != posToIdx.end()) {
            int j = it->second;
            result.append(targets[j]);
            i += sources[j].size();
        } else {
            result.push_back(s[i]);
            ++i;
        }
    }
