std::string maskPII(const std::string& s) {
    if (s.find('@') != std::string::npos) {
        size_t atPos = s.find('@');
        std::string local = s.substr(0, atPos);
        std::string domain = s.substr(atPos + 1);
        for (char& c : local) c = std::tolower(static_cast<unsigned char>(c));
        for (char& c : domain) c = std::tolower(static_cast<unsigned char>(c));
        std::string maskedLocal;
        maskedLocal.push_back(local[0]);
        maskedLocal += "*****";
        maskedLocal.push_back(local[local.size() - 1]);
        return maskedLocal + "@" + domain;
    } else {
        std::string digits;
        for (char c : s) {
            if (std::isdigit(static_cast<unsigned char>(c))) {
                digits.push_back(c);
            }
        }
        std::string maskedDigits = "***-***-" + digits.substr(digits.size() - 4);
        return maskedDigits;
    }
}

