std::string pushDominoes(const std::string& dominoes) {
    int n = static_cast<int>(dominoes.size());
    std::vector<int> forces(n, 0);
    int force = 0;
    for (int i = 0; i < n; ++i) {
        if (dominoes[i] == 'R') force = n;
        else if (dominoes[i] == 'L') force = 0;
        else force = std::max(force - 1, 0);
        forces[i] += force;
    }
    force = 0;
    for (int i = n - 1; i >= 0; --i) {
        if (dominoes[i] == 'L') force = n;
        else if (dominoes[i] == 'R') force = 0;
        else force = std::max(force - 1, 0);
        forces[i] -= force;
    }
    std::string result;
    result.reserve(n);
    for (int i = 0; i < n; ++i) {
        if (forces[i] > 0) result.push_back('R');
        else if (forces[i] < 0) result.push_back('L');
        else result.push_back('.');
    }
    return result;
}

