double new21Game(int n, int k, int maxPts) {
    if (k == 0) return 1.0;
    if (n >= k + maxPts - 1) return 1.0;

    std::vector<double> dp(n + 1, 0.0);
    dp[0] = 1.0;
    double windowSum = 1.0;
    double answer = 0.0;

    for (int i = 1; i <= n; ++i) {
        dp[i] = windowSum / static_cast<double>(maxPts);
        if (i < k) {
            windowSum += dp[i];
        } else {
            answer += dp[i];
        }
        if (i - maxPts >= 0) {
            windowSum -= dp[i - maxPts];
        }
    }
    answer = std::round(answer * 1e5) / 1e5;
    if (answer > 1.0) answer = 1.0;
    if (answer < 0.0) answer = 0.0;
    return answer;
}

