int numSimilarGroups(const std::vector<std::string>& strs) {
    std::unordered_map<std::string, std::string> parent;
    for (const auto& s : strs) {
        parent[s] = s;
    }

    std::function<std::string(const std::string&)> find = [&](const std::string& x) -> std::string {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    };

    auto unite = [&](const std::string& x, const std::string& y) {
        std::string rootX = find(x);
        std::string rootY = find(y);
        if (rootX != rootY) {
            parent[rootX] = rootY;
        }
    };

    auto isSimilar = [&](const std::string& x, const std::string& y) -> bool {
        int diff = 0;
        for (size_t i = 0; i < x.size(); ++i) {
            if (x[i] != y[i]) {
                ++diff;
            }
            if (diff > 2) {
                return false;
            }
        }
        return diff == 0 || diff == 2;
    };

    for (size_t i = 0; i < strs.size(); ++i) {
        for (size_t j = i + 1; j < strs.size(); ++j) {
            if (isSimilar(strs[i], strs[j])) {
                unite(strs[i], strs[j]);
            }
        }
    }

    std::unordered_set<std::string> groups;
    for (const auto& s : strs) {
        groups.insert(find(s));
    }
    return static_cast<int>(groups.size());
}

