int numMagicSquaresInside(const std::vector<std::vector<int>>& grid) {
    int rows = static_cast<int>(grid.size());
    if (rows < 3) return 0;
    int cols = static_cast<int>(grid[0].size());
    if (cols < 3) return 0;
    int count = 0;
    for (int i = 0; i <= rows - 3; ++i) {
        for (int j = 0; j <= cols - 3; ++j) {
            bool seen[10] = {false};
            bool valid = true;
            for (int r = i; r < i + 3 && valid; ++r) {
                for (int c = j; c < j + 3; ++c) {
                    int val = grid[r][c];
                    if (val < 1 || val > 9 || seen[val]) {
                        valid = false;
                        break;
                    }
                    seen[val] = true;
                }
            }
            if (!valid) continue;
            int sum = grid[i][j] + grid[i][j + 1] + grid[i][j + 2];
            // rows
            for (int r = i + 1; r < i + 3; ++r) {
                int rowSum = grid[r][j] + grid[r][j + 1] + grid[r][j + 2];
                if (rowSum != sum) { valid = false; break; }
            }
            if (!valid) continue;
            // columns
            for (int c = j; c < j + 3; ++c) {
                int colSum = grid[i][c] + grid[i + 1][c] + grid[i + 2][c];
                if (colSum != sum) { valid = false; break; }
            }
            if (!valid) continue;
            // diagonals
            int diag1 = grid[i][j] + grid[i + 1][j + 1] + grid[i + 2][j + 2];
            int diag2 = grid[i][j + 2] + grid[i + 1][j + 1] + grid[i + 2][j];
            if (diag1 != sum || diag2 != sum) continue;
            ++count;
        }
    }
    return count;
}

