bool canVisitAllRooms(const std::vector<std::vector<int>>& rooms) {
    if (rooms.empty()) return true;
    std::unordered_set<int> visited;
    visited.insert(0);
    std::unordered_set<int> keys(rooms[0].begin(), rooms[0].end());
    while (!keys.empty()) {
        std::unordered_set<int> newKeys;
        for (int key : keys) {
            if (visited.find(key) == visited.end()) {
                visited.insert(key);
                for (int newKey : rooms[key]) {
                    newKeys.insert(newKey);
                }
            }
        }
        if (newKeys.empty()) break;
        keys.swap(newKeys);
    }
    return visited.size() == rooms.size();
}

