std::vector<long long> splitIntoFibonacci(const std::string& num) {
    std::vector<long long> result;
    std::function<bool(int, std::vector<long long>&)> backtrack = [&](int start, std::vector<long long>& path) -> bool {
        if (start == static_cast<int>(num.size()) && path.size() >= 3) return true;
        for (int i = 1; i <= static_cast<int>(num.size()) - start; ++i) {
            std::string substr = num.substr(start, i);
            if (substr.size() > 1 && substr[0] == '0') continue;
            long long currNum = std::stoll(substr);
            if (path.size() < 2) {
                path.push_back(currNum);
                if (backtrack(start + i, path)) {
                    result = path;
                    return true;
                }
                path.pop_back();
            } else {
                long long sum = path[path.size() - 1] + path[path.size() - 2];
                if (currNum == sum) {
                    path.push_back(currNum);
                    if (backtrack(start + i, path)) {
                        result = path;
                        return true;
                    }
                    path.pop_back();
                }
            }
        }
        return false;
    };
    std::vector<long long> path;
    backtrack(0, path);
    return result;
}

