std::vector<int> loudAndRich(const std::vector<std::vector<int>>& richer, const std::vector<int>& quiet) {
    int n = quiet.size();
    std::vector<std::vector<int>> graph(n);
    std::vector<int> indegree(n, 0);
    for (size_t i = 0; i < richer.size(); ++i) {
        int u = richer[i][0];
        int v = richer[i][1];
        graph[u].push_back(v);
        indegree[v]++;
    }
    std::vector<int> answer(n);
    for (int i = 0; i < n; ++i) {
        answer[i] = i;
    }
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indegree[i] == 0) {
            q.push(i);
        }
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : graph[u]) {
            if (quiet[answer[u]] < quiet[answer[v]]) {
                answer[v] = answer[u];
            }
            indegree[v]--;
            if (indegree[v] == 0) {
                q.push(v);
            }
        }
    }
    return answer;
}

