#include <bits/stdc++.h>
int rectangleArea(std::vector<std::vector<int>>& rectangles) {
    const long long MOD = 1000000007LL;
    std::vector<long long> xs;
    xs.reserve(rectangles.size() * 2);
    for (const auto& r : rectangles) {
        xs.push_back(r[0]);
        xs.push_back(r[2]);
    }
    std::sort(xs.begin(), xs.end());
    xs.erase(std::unique(xs.begin(), xs.end()), xs.end());

    long long total = 0;
    for (size_t i = 0; i + 1 < xs.size(); ++i) {
        long long x1 = xs[i];
        long long x2 = xs[i + 1];
        long long width = x2 - x1;
        if (width == 0) continue;

        std::vector<std::pair<long long, long long>> intervals;
        intervals.reserve(rectangles.size());
        for (const auto& r : rectangles) {
            if (r[0] <= x1 && r[2] >= x2) {
                intervals.emplace_back(r[1], r[3]);
            }
        }
        if (intervals.empty()) continue;
        std::sort(intervals.begin(), intervals.end());

        long long covered = 0;
        long long curL = intervals[0].first;
        long long curR = intervals[0].second;
        for (size_t j = 1; j < intervals.size(); ++j) {
            long long l = intervals[j].first;
            long long r = intervals[j].second;
            if (l > curR) {
                covered += curR - curL;
                curL = l;
                curR = r;
            } else {
                curR = std::max(curR, r);
            }
        }
        covered += curR - curL;

        total = (total + (width % MOD) * (covered % MOD)) % MOD;
    }
    return static_cast<int>(total);
}

