void findSecretWord(const std::vector<std::string>& wordlist, auto& master, int allowedGuesses) {
    std::vector<std::string> possibleWords = wordlist;
    for (int i = 0; i < allowedGuesses; ++i) {
        int idx = std::rand() % static_cast<int>(possibleWords.size());
        const std::string& guess = possibleWords[idx];
        int matches = master.guess(guess);
        if (matches == 6) return;
        std::vector<std::string> filtered;
        filtered.reserve(possibleWords.size());
        for (const std::string& word : possibleWords) {
            int matchCount = 0;
            for (size_t j = 0; j < 6; ++j) {
                if (word[j] == guess[j]) ++matchCount;
            }
            if (matchCount == matches) {
                filtered.push_back(word);
            }
        }
        possibleWords.swap(filtered);
    }
}

