    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

TreeNode* subtreeWithAllDeepest(TreeNode* root) {
    int maxDepth = 0;
    std::vector<TreeNode*> deepestNodes;
    TreeNode* result = nullptr;

    std::function<void(TreeNode*, int)> dfs = [&](TreeNode* node, int depth) {
        if (depth > maxDepth) {
            maxDepth = depth;
            deepestNodes.clear();
            deepestNodes.push_back(node);
        } else if (depth == maxDepth) {
            deepestNodes.push_back(node);
        }
        if (node->left) dfs(node->left, depth + 1);
        if (node->right) dfs(node->right, depth + 1);
    };

    if (root) dfs(root, 0);

    std::function<TreeNode*(TreeNode*, int)> findLCA = [&](TreeNode* node, int depth) -> TreeNode* {
        if (!node) return nullptr;
        if (std::find(deepestNodes.begin(), deepestNodes.end(), node) != deepestNodes.end())
            return node;
        TreeNode* left = findLCA(node->left, depth + 1);
        TreeNode* right = findLCA(node->right, depth + 1);
        if (left && right) return node;
        return left ? left : right;
    };

    result = findLCA(root, 0);
    return result;
}

