        while (n > 0) {
            binaryString.push_back((n & 1) ? '1' : '0');
            n >>= 1;
        }
        std::reverse(binaryString.begin(), binaryString.end());
    }
    int maxDistance = 0;
    int lastOneIndex = -1;
    for (int i = 0; i < static_cast<int>(binaryString.size()); ++i) {
        if (binaryString[i] == '1') {
            if (lastOneIndex != -1) {
                maxDistance = std::max(maxDistance, i - lastOneIndex);
            }
            lastOneIndex = i;
        }
    }
    return maxDistance;
}

