bool buddyStrings(const std::string& s, const std::string& goal) {
    if (s.length() != goal.length()) return false;
    std::vector<int> diff;
    for (size_t i = 0; i < s.length(); ++i) {
        if (s[i] != goal[i]) diff.push_back(static_cast<int>(i));
    }
    if (diff.empty()) {
        std::unordered_map<char, int> charCount;
        for (char c : s) {
            if (charCount.find(c) != charCount.end()) charCount[c]++;
            else charCount[c] = 1;
        }
        for (const auto& kv : charCount) {
            if (kv.second > 1) return true;
        }
        return false;
    } else if (diff.size() > 2) {
        return false;
    } else if (diff.size() == 2) {
        std::string sCopy = s;
        std::swap(sCopy[diff[0]], sCopy[diff[1]]);
        return sCopy == goal;
    }
    return false;
}

