struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

std::vector<int> distanceK(TreeNode* root, TreeNode* target, int k) {
    std::unordered_map<int, TreeNode*> parentMap;
    std::function<void(TreeNode*, TreeNode*)> buildParentMap = [&](TreeNode* node, TreeNode* parent) {
        if (node) {
            parentMap[node->val] = parent;
            buildParentMap(node->left, node);
            buildParentMap(node->right, node);
        }
    };
    buildParentMap(root, nullptr);

    std::unordered_set<int> visited;
    std::vector<int> result;
    std::function<void(TreeNode*, int)> dfs = [&](TreeNode* node, int distance) {
        if (!node || visited.count(node->val)) return;
        visited.insert(node->val);
        if (distance == k) result.push_back(node->val);
        if (distance < k) {
            dfs(node->left, distance + 1);
            dfs(node->right, distance + 1);
            TreeNode* parent = nullptr;
            auto it = parentMap.find(node->val);
            if (it != parentMap.end()) parent = it->second;
            dfs(parent, distance + 1);
        }
    };
    dfs(target, 0);
    return result;
}

