int minRefuelStops(int target, int startFuel, const std::vector<std::vector<int>>& stations) {
    int currentFuel = startFuel;
    int stops = 0;
    int previousStation = 0;
    std::priority_queue<int> pq;
    for (size_t i = 0; i <= stations.size(); ++i) {
        int distance = (i < stations.size()) ? stations[i][0] - previousStation : target - previousStation;
        while (!pq.empty() && currentFuel < distance) {
            currentFuel += pq.top();
            pq.pop();
            ++stops;
        }
        if (currentFuel < distance) return -1;
        if (i < stations.size()) {
            pq.push(stations[i][1]);
            previousStation = stations[i][0];
        }
        currentFuel -= distance;
    }
    return stops;
}

