int robotSim(const std::vector<int>& commands, const std::vector<std::vector<int>>& obstacles) {
    int maxDistance = 0;
    std::vector<std::vector<int>> directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    int currentDirection = 0;
    std::vector<int> currentPosition = {0, 0};
    std::unordered_set<std::string> obstacleSet;
    for (const auto& obstacle : obstacles) {
        obstacleSet.insert(std::to_string(obstacle[0]) + "," + std::to_string(obstacle[1]));
    }
    for (int command : commands) {
        if (command < 0) {
            currentDirection = (currentDirection + (command == -1 ? 1 : -1) + 4) % 4;
        } else {
            for (int i = 0; i < command; ++i) {
                std::vector<int> nextPosition = {
                    currentPosition[0] + directions[currentDirection][0],
                    currentPosition[1] + directions[currentDirection][1]
                };
                std::string key = std::to_string(nextPosition[0]) + "," + std::to_string(nextPosition[1]);
                if (obstacleSet.find(key) != obstacleSet.end()) {
                    break;
                }
                currentPosition = nextPosition;
                int distance = currentPosition[0] * currentPosition[0] + currentPosition[1] * currentPosition[1];
                maxDistance = std::max(maxDistance, distance);
            }
        }
    }
    return maxDistance;
}

