char decodeAtIndex(const std::string& s, long long k) {
    long long size = 0;
    for (char c : s) {
        if (std::isdigit(c)) {
            size *= (c - '0');
        } else {
            ++size;
        }
    }
    for (long long i = static_cast<long long>(s.size()) - 1; i >= 0; --i) {
        char c = s[i];
        if (std::isdigit(c)) {
            size /= (c - '0');
            k %= size;
            if (k == 0) {
                k = size;
            }
        } else {
            if (k == size) {
                return c;
            }
            --size;
        }
    }
    return '\0';
}

