int profitableSchemes(int n, int minProfit, const std::vector<int>& group, const std::vector<int>& profit) {
    const int MOD = 1000000007;
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(minProfit + 1, 0));
    dp[0][0] = 1;
    for (size_t i = 0; i < group.size(); ++i) {
        int g = group[i];
        int p = profit[i];
        for (int members = n; members >= g; --members) {
            for (int prof = minProfit; prof >= 0; --prof) {
                int prevProf = prof - p;
                if (prevProf < 0) prevProf = 0;
                dp[members][prof] = (dp[members][prof] + dp[members - g][prevProf]) % MOD;
            }
        }
    }
    int result = 0;
    for (int members = 0; members <= n; ++members) {
        result = (result + dp[members][minProfit]) % MOD;
    }
    return result;
}

