int reachableNodes(const std::vector<std::vector<int>>& edges, int maxMoves, int n) {
    std::vector<std::vector<std::pair<int, int>>> graph(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int cnt = e[2];
        int w = cnt + 1;
        graph[u].push_back({v, w});
        graph[v].push_back({u, w});
    }
    const long long INF = 4e18;
    std::vector<long long> dist(n, INF);
    using P = std::pair<long long, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
    dist[0] = 0;
    pq.emplace(0, 0);
    while (!pq.empty()) {
        auto top = pq.top();
        pq.pop();
        long long d = top.first;
        int u = top.second;
        if (d != dist[u]) continue;
        for (const auto& vw : graph[u]) {
            int v = vw.first;
            int w = vw.second;
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.emplace(dist[v], v);
            }
        }
    }
    long long result = 0;
    for (int i = 0; i < n; ++i) {
        if (dist[i] <= maxMoves) ++result;
    }
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int cnt = e[2];
        long long fromU = std::max(0LL, static_cast<long long>(maxMoves) - dist[u]);
        long long fromV = std::max(0LL, static_cast<long long>(maxMoves) - dist[v]);
        result += std::min<long long>(cnt, fromU + fromV);
    }
    return static_cast<int>(result);
}

