TreeNode* constructFromPrePost(const std::vector<int>& preorder, const std::vector<int>& postorder) {
    std::function<TreeNode*(int, int, int, int)> buildTree = [&](int preStart, int preEnd, int postStart, int postEnd) -> TreeNode* {
        if (preStart > preEnd) return nullptr;
        TreeNode* root = new TreeNode(preorder[preStart]);
        if (preStart == preEnd) return root;
        int leftChildIndex = preStart + 1;
        int leftChildPostIndex = postStart;
        while (postorder[leftChildPostIndex] != preorder[leftChildIndex]) ++leftChildPostIndex;
        int leftTreeLength = leftChildPostIndex - postStart + 1;
        root->left = buildTree(leftChildIndex, leftChildIndex + leftTreeLength - 1, postStart, leftChildPostIndex);
        root->right = buildTree(leftChildIndex + leftTreeLength, preEnd, leftChildPostIndex + 1, postEnd - 1);
        return root;
    };
    return buildTree(0, static_cast<int>(preorder.size()) - 1, 0, static_cast<int>(postorder.size()) - 1);
}

