int numPermsDISequence(const std::string& s) {
    const int64_t MOD = 1000000007LL;
    int n = static_cast<int>(s.size());
    std::vector<int64_t> dp(n + 1, 1);
    for (int i = 0; i < n; ++i) {
        int sz = static_cast<int>(dp.size());
        std::vector<int64_t> pref(sz + 1, 0);
        for (int j = 0; j < sz; ++j) {
            pref[j + 1] = (pref[j] + dp[j]) % MOD;
        }
        std::vector<int64_t> ndp;
        ndp.reserve(sz - 1);
        if (s[i] == 'I') {
            for (int j = 0; j < sz - 1; ++j) {
                ndp.push_back(pref[j + 1]);
            }
        } else { // 'D'
            for (int j = 0; j < sz - 1; ++j) {
                ndp.push_back((pref[sz] + MOD - pref[j + 1]) % MOD);
            }
        }
        dp.swap(ndp);
    }
    int64_t res = 0;
    for (int64_t v : dp) {
        res = (res + v) % MOD;
    }
    return static_cast<int>(res);
}

