std::vector<std::string> findAndReplacePattern(const std::vector<std::string>& words, const std::string& pattern) {
    auto isMatch = [&](const std::string& word, const std::string& pat) -> bool {
        std::unordered_map<char, char> patternToWord;
        std::unordered_map<char, char> wordToPattern;
        for (size_t i = 0; i < pat.size(); ++i) {
            if (patternToWord.find(pat[i]) == patternToWord.end()) {
                patternToWord[pat[i]] = word[i];
            }
            if (wordToPattern.find(word[i]) == wordToPattern.end()) {
                wordToPattern[word[i]] = pat[i];
            }
            if (patternToWord[pat[i]] != word[i] || wordToPattern[word[i]] != pat[i]) {
                return false;
            }
        }
        return true;
    };

    std::vector<std::string> result;
    for (const auto& word : words) {
        if (isMatch(word, pattern)) {
            result.push_back(word);
        }
    }
    return result;
}

