struct FreqStackObj {
    std::unordered_map<int, int> frequencyMap;
    std::unordered_map<int, std::vector<int>> frequencyToElements;
    int maxFrequency = 0;
    void push(int x) {
        frequencyMap[x] = frequencyMap[x] + 1;
        int frequency = frequencyMap[x];
        maxFrequency = std::max(maxFrequency, frequency);
        frequencyToElements[frequency].push_back(x);
    }
    int pop() {
        std::vector<int>& mostFrequentElements = frequencyToElements[maxFrequency];
        int removedElement = mostFrequentElements.back();
        mostFrequentElements.pop_back();
        frequencyMap[removedElement]--;
        if (mostFrequentElements.empty()) {
            maxFrequency--;
        }
        return removedElement;
    }
};

FreqStackObj FreqStack() {
    return FreqStackObj{};
}

