long long sumSubseqWidths(std::vector<int> nums) {
    const long long MOD = 1000000007LL;
    std::sort(nums.begin(), nums.end());
    int n = static_cast<int>(nums.size());
    std::vector<long long> pow2(n);
    if (n > 0) {
        pow2[0] = 1;
        for (int i = 1; i < n; ++i) {
            pow2[i] = (pow2[i - 1] * 2) % MOD;
        }
    }
    long long result = 0;
    for (int i = 0; i < n; ++i) {
        long long maxCount = pow2[i];
        long long minCount = pow2[n - 1 - i];
        long long diff = (maxCount - minCount + MOD) % MOD;
        result = (result + (static_cast<long long>(nums[i]) % MOD) * diff) % MOD;
    }
    return result;
}

