        std::string str = std::to_string(num);
        size_t i = 0, j = str.size() - 1;
        while (i < j) {
            if (str[i] != str[j]) return false;
            ++i;
            --j;
        }
        return true;
    };
    int count = 0;
    long long leftVal = std::stoll(left);
    long long rightVal = std::stoll(right);
    for (int i = 1; i <= 10000; ++i) {
        if (isPalindrome(i)) {
            long long square = 1LL * i * i;
            if (square >= leftVal && square <= rightVal && isPalindrome(square)) {
                ++count;
            }
        }
    }
    return count;
}

