int surfaceArea(const std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    int result = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] > 0) result += 2;
            if (grid[i][j] > 0) {
                if (j == 0 || grid[i][j] > grid[i][j - 1]) result += grid[i][j] - (j > 0 ? grid[i][j - 1] : 0);
                if (j == n - 1 || grid[i][j] > grid[i][j + 1]) result += grid[i][j] - (j < n - 1 ? grid[i][j + 1] : 0);
                if (i == 0 || grid[i][j] > grid[i - 1][j]) result += grid[i][j] - (i > 0 ? grid[i - 1][j] : 0);
                if (i == n - 1 || grid[i][j] > grid[i + 1][j]) result += grid[i][j] - (i < n - 1 ? grid[i + 1][j] : 0);
            }
        }
    }
    return result;
}

#include <bits/stdc++.h>

int atMostNGivenDigitSet(const std::vector<std::string>& digits, int n) {
    std::string s = std::to_string(n);
    int m = static_cast<int>(s.size());
    int k = static_cast<int>(digits.size());
    long long count = 0;

    long long pow = 1;
    for (int len = 1; len < m; ++len) {
        pow *= k;
        count += pow;
    }

    std::vector<long long> power(m + 1, 1);
    for (int i = 1; i <= m; ++i) {
        power[i] = power[i - 1] * k;
    }

    for (int i = 0; i < m; ++i) {
        char c = s[i];
        int smaller = 0;
        for (const std::string& d : digits) {
            if (d[0] < c) {
                ++smaller;
            } else {
                break;
            }
        }
        count += static_cast<long long>(smaller) * power[m - i - 1];

        bool found = false;
        for (const std::string& d : digits) {
            if (d[0] == c) {
                found = true;
                break;
            }
        }
        if (!found) {
            return static_cast<int>(count);
        }
    }

    count += 1;
    return static_cast<int>(count);
}

