int sumSubarrayMins(const std::vector<int>& arr) {
    const long long MOD = 1000000007LL;
    size_t n = arr.size();
    std::vector<int> left(n, -1);
    std::vector<int> right(n, static_cast<int>(n));
    std::vector<int> stack;
    for (size_t i = 0; i < n; ++i) {
        while (!stack.empty() && arr[stack.back()] >= arr[i]) {
            stack.pop_back();
        }
        if (!stack.empty()) {
            left[i] = stack.back();
        }
        stack.push_back(static_cast<int>(i));
    }
    stack.clear();
    for (int i = static_cast<int>(n) - 1; i >= 0; --i) {
        while (!stack.empty() && arr[stack.back()] > arr[i]) {
            stack.pop_back();
        }
        if (!stack.empty()) {
            right[i] = stack.back();
        }
        stack.push_back(i);
    }
    long long sum = 0;
    for (size_t i = 0; i < n; ++i) {
        long long count = static_cast<long long>(i - left[i]) * (right[i] - static_cast<int>(i));
        sum = (sum + count * arr[i]) % MOD;
    }
    return static_cast<int>(sum);
}

