int snakesAndLadders(const std::vector<std::vector<int>>& board) {
    int n = board.size();
    std::vector<int> cells(n * n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int idx = (i % 2 == 0) ? i * n + j : i * n + n - j - 1;
            cells[idx] = board[n - i - 1][j];
        }
    }
    std::deque<std::pair<int, int>> queue;
    queue.emplace_back(0, 0);
    std::unordered_set<int> visited;
    visited.insert(0);
    while (!queue.empty()) {
        std::pair<int, int> front = queue.front();
        queue.pop_front();
        int curr = front.first;
        int rolls = front.second;
        if (curr == n * n - 1) return rolls;
        for (int i = 1; i <= 6; ++i) {
            int next = curr + i;
            if (next >= n * n) continue;
            if (cells[next] != -1) next = cells[next] - 1;
            if (visited.find(next) == visited.end()) {
                queue.emplace_back(next, rolls + 1);
                visited.insert(next);
            }
        }
    }
    return -1;
}

