int findGCD(int a, int b) {
    while (b != 0) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a;
}

bool hasGroupsSizeX(const std::vector<int>& deck) {
    std::unordered_map<int, int> countMap;
    for (size_t i = 0; i < deck.size(); ++i) {
        if (countMap.find(deck[i]) != countMap.end()) {
            countMap[deck[i]]++;
        } else {
            countMap[deck[i]] = 1;
        }
    }
    int gcd = -1;
    for (const auto& kv : countMap) {
        if (gcd == -1) {
            gcd = kv.second;
        } else {
            gcd = findGCD(gcd, kv.second);
        }
    }
    return gcd > 1;
}

