std::vector<int> topVotedCandidate(const std::vector<int>& persons, const std::vector<int>& times, const std::vector<int>& queries) {
    std::unordered_map<int, int> voteCount;
    int leader = 0;
    std::unordered_map<int, int> leaderAtTime;
    std::vector<int> result;

    for (size_t i = 0; i < persons.size(); ++i) {
        int p = persons[i];
        if (voteCount.find(p) == voteCount.end()) voteCount[p] = 0;
        voteCount[p]++;

        if (voteCount[p] >= voteCount[leader] || (voteCount[p] == voteCount[leader] && static_cast<int>(i) > leader)) {
            leader = p;
        }
        leaderAtTime[times[i]] = leader;
    }

    for (size_t i = 0; i < queries.size(); ++i) {
        int queryTime = queries[i];
        // FIXED: original scanned forward for the smallest recorded time >= queryTime,
        // incorrectly using a future vote. Correct answer uses the largest recorded
        // time <= queryTime, found via backward scan.
        int leaderAtQueryTime = -1;
        for (int j = static_cast<int>(times.size()) - 1; j >= 0; --j) {
            if (times[j] <= queryTime) {
                leaderAtQueryTime = leaderAtTime[times[j]];
                break;
            }
        }
        result.push_back(leaderAtQueryTime);
    }
    return result;
}

