#include <queue>
#include <tuple>

int catMouseGame(const std::vector<std::vector<int>>& graph) {
    const int n = static_cast<int>(graph.size());
    const int MOUSE_TURN = 0;
    const int CAT_TURN = 1;
    const int DRAW = 0;
    const int MOUSE_WIN = 1;
    const int CAT_WIN = 2;

    std::vector<std::vector<std::array<int, 2>>> result(
        n, std::vector<std::array<int, 2>>(n, std::array<int, 2>{DRAW, DRAW}));
    std::vector<std::vector<std::array<int, 2>>> degree(
        n, std::vector<std::array<int, 2>>(n, std::array<int, 2>{0, 0}));

    for (int m = 0; m < n; ++m) {
        for (int c = 0; c < n; ++c) {
            degree[m][c][MOUSE_TURN] = static_cast<int>(graph[m].size());
            int cnt = 0;
            for (int nxt : graph[c]) {
                if (nxt != 0) ++cnt;
            }
            degree[m][c][CAT_TURN] = cnt;
        }
    }

    std::queue<std::tuple<int, int, int>> q;

    for (int i = 0; i < n; ++i) {
        result[0][i][MOUSE_TURN] = MOUSE_WIN;
        result[0][i][CAT_TURN] = MOUSE_WIN;
        q.emplace(0, i, MOUSE_TURN);
        q.emplace(0, i, CAT_TURN);
        if (i != 0) {
            result[i][i][MOUSE_TURN] = CAT_WIN;
            result[i][i][CAT_TURN] = CAT_WIN;
            q.emplace(i, i, MOUSE_TURN);
            q.emplace(i, i, CAT_TURN);
        }
    }

    while (!q.empty()) {
        auto cur = q.front();
        q.pop();
        int m = std::get<0>(cur);
        int c = std::get<1>(cur);
        int turn = std::get<2>(cur);
        int curRes = result[m][c][turn];
        int prevTurn = 1 - turn;

        if (prevTurn == MOUSE_TURN) {
            for (int prevM : graph[m]) {
                int prevC = c;
                if (result[prevM][prevC][prevTurn] != DRAW) continue;
                if (curRes == MOUSE_WIN) {
                    result[prevM][prevC][prevTurn] = MOUSE_WIN;
                    q.emplace(prevM, prevC, prevTurn);
                } else if (curRes == CAT_WIN) {
                    degree[prevM][prevC][prevTurn]--;
                    if (degree[prevM][prevC][prevTurn] == 0) {
                        result[prevM][prevC][prevTurn] = CAT_WIN;
                        q.emplace(prevM, prevC, prevTurn);
                    }
                }
            }
        } else {
            for (int prevC : graph[c]) {
                if (prevC == 0) continue;
                int prevM = m;
                if (result[prevM][prevC][prevTurn] != DRAW) continue;
                if (curRes == CAT_WIN) {
                    result[prevM][prevC][prevTurn] = CAT_WIN;
                    q.emplace(prevM, prevC, prevTurn);
                } else if (curRes == MOUSE_WIN) {
                    degree[prevM][prevC][prevTurn]--;
                    if (degree[prevM][prevC][prevTurn] == 0) {
                        result[prevM][prevC][prevTurn] = MOUSE_WIN;
                        q.emplace(prevM, prevC, prevTurn);
                    }
                }
            }
        }
    }

    return result[1][2][MOUSE_TURN];
}

