int maxSubarraySumCircular(const std::vector<int>& nums) {
    long long totalSum = 0;
    long long maxKadaneSum = std::numeric_limits<long long>::lowest();
    long long minKadaneSum = std::numeric_limits<long long>::max();
    long long currentMaxSum = 0;
    long long currentMinSum = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        totalSum += nums[i];
        currentMaxSum = std::max<long long>(nums[i], currentMaxSum + nums[i]);
        maxKadaneSum = std::max(maxKadaneSum, currentMaxSum);
        currentMinSum = std::min<long long>(nums[i], currentMinSum + nums[i]);
        minKadaneSum = std::min(minKadaneSum, currentMinSum);
    }
    if (totalSum == minKadaneSum) {
        return static_cast<int>(maxKadaneSum);
    } else {
        long long result = std::max(maxKadaneSum, totalSum - minKadaneSum);
        return static_cast<int>(result);
    }
}

