    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

struct Inserter {
    TreeNode* root;
    std::deque<TreeNode*> queue; // nodes missing at least one child, in level order
};

Inserter CBTInserter(TreeNode* root) {
    Inserter ins;
    ins.root = root;
    std::deque<TreeNode*> q{root};
    while (!q.empty()) {
        TreeNode* node = q.front(); q.pop_front();
        if (!node->left || !node->right) ins.queue.push_back(node);
        if (node->left) q.push_back(node->left);
        if (node->right) q.push_back(node->right);
    }
    return ins;
}

int insertNode(Inserter& ins, int val) {
    TreeNode* node = new TreeNode(val);
    TreeNode* parent = ins.queue.front();
    if (!parent->left) parent->left = node;
    else { parent->right = node; ins.queue.pop_front(); }
    ins.queue.push_back(node);
    return parent->val;
}

TreeNode* getRoot(Inserter& ins) {
    return ins.root;
}

