long long combination(long long n, int r) {
    if (r == 2) {
        return n * (n - 1) / 2;
    }
    if (r == 3) {
        return n * (n - 1) * (n - 2) / 6;
    }
    return 0;
}

long long threeSumMulti(const std::vector<int>& arr, int target) {
    std::unordered_map<int, long long> freq;
    for (int v : arr) {
        ++freq[v];
    }
    std::vector<int> keys;
    keys.reserve(freq.size());
    for (const auto& p : freq) {
        keys.push_back(p.first);
    }
    std::sort(keys.begin(), keys.end());

    long long ans = 0;
    for (size_t a = 0; a < keys.size(); ++a) {
        int i = keys[a];
        for (size_t b = a; b < keys.size(); ++b) {
            int j = keys[b];
            int k = target - i - j;
            if (k < j) continue;
            auto it = freq.find(k);
            if (it == freq.end()) continue;
            long long fi = freq[i];
            long long fj = freq[j];
            long long fk = it->second;
            if (i == j && j == k) {
                ans += combination(fi, 3);
            } else if (i == j) {
                ans += combination(fi, 2) * fk;
            } else if (j == k) {
                ans += combination(fj, 2) * fi;
            } else {
                ans += fi * fj * fk;
            }
        }
    }
    return ans;
}

