int minFallingPathSum(const std::vector<std::vector<int>>& matrix) {
    int n = static_cast<int>(matrix.size());
    std::vector<std::vector<int>> dp(n, std::vector<int>(n, 0));
    for (int i = 0; i < n; ++i) {
        dp[0][i] = matrix[0][i];
    }
    for (int i = 1; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (j == 0) {
                dp[i][j] = matrix[i][j] + std::min(dp[i-1][j], dp[i-1][j+1]);
            } else if (j == n - 1) {
                dp[i][j] = matrix[i][j] + std::min(dp[i-1][j-1], dp[i-1][j]);
            } else {
                dp[i][j] = matrix[i][j] + std::min({dp[i-1][j-1], dp[i-1][j], dp[i-1][j+1]});
            }
        }
    }
    int minSum = INT_MAX;
    for (int i = 0; i < n; ++i) {
        minSum = std::min(minSum, dp[n-1][i]);
    }
    return minSum;
}

