int minMalwareSpread(const std::vector<std::vector<int>>& graph, const std::vector<int>& initial) {
    int n = static_cast<int>(graph.size());
    std::vector<int> parent(n);
    std::vector<int> sz(n, 1);
    for (int i = 0; i < n; ++i) parent[i] = i;

    std::function<int(int)> find = [&](int x) -> int {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    };

    auto union_sets = [&](int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (sz[rootX] < sz[rootY]) {
                parent[rootX] = rootY;
                sz[rootY] += sz[rootX];
            } else {
                parent[rootY] = rootX;
                sz[rootX] += sz[rootY];
            }
        }
    };

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (graph[i][j] == 1) {
                union_sets(i, j);
            }
        }
    }

    std::vector<int> infected(n, 0);
    for (int node : initial) {
        infected[find(node)]++;
    }

    int res = -1;
    int maxSave = 0;
    for (int node : initial) {
        int root = find(node);
        if (infected[root] == 1) {
            if (sz[root] > maxSave) {
                maxSave = sz[root];
                res = node;
            } else if (sz[root] == maxSave) {
                res = std::min(res, node);
            }
        }
    }

    if (res == -1) {
        res = *std::min_element(initial.begin(), initial.end());
    }

    return res;
}

#include <bits/stdc++.h>

int minMalwareSpread(const std::vector<std::vector<int>>& graph, const std::vector<int>& initial) {
    int n = static_cast<int>(graph.size());
    int bestNode = *std::min_element(initial.begin(), initial.end());
    int bestInfected = n + 1;

    for (int rem : initial) {
        std::vector<int> parent(n);
        std::vector<int> sz(n, 1);
        for (int i = 0; i < n; ++i) parent[i] = i;

        std::function<int(int)> find = [&](int x) -> int {
            return parent[x] == x ? x : parent[x] = find(parent[x]);
        };
        auto unite = [&](int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return;
            if (sz[ra] < sz[rb]) std::swap(ra, rb);
            parent[rb] = ra;
            sz[ra] += sz[rb];
        };

        for (int i = 0; i < n; ++i) {
            if (i == rem) continue;
            for (int j = i + 1; j < n; ++j) {
                if (j == rem) continue;
                if (graph[i][j]) unite(i, j);
            }
        }

        std::vector<int> infectedComp(n, 0);
        for (int node : initial) {
            if (node == rem) continue;
            infectedComp[find(node)] = 1;
        }

        int infectedCount = 0;
        for (int i = 0; i < n; ++i) {
            if (i == rem) continue;
            if (infectedComp[find(i)]) ++infectedCount;
        }

        if (infectedCount < bestInfected || (infectedCount == bestInfected && rem < bestNode)) {
            bestInfected = infectedCount;
            bestNode = rem;
        }
    }
    return bestNode;
}

