int knightDialer(int n) {
    const int MOD = 1000000007;
    static const std::vector<std::vector<int>> moves = {
        {4, 6},          // 0
        {6, 8},          // 1
        {7, 9},          // 2
        {4, 8},          // 3
        {0, 3, 9},       // 4
        {},              // 5
        {0, 1, 7},       // 6
        {2, 6},          // 7
        {1, 3},          // 8
        {2, 4}           // 9
    };
    std::vector<long long> dp(10, 1);
    for (int i = 1; i < n; ++i) {
        std::vector<long long> temp(10, 0);
        for (int j = 0; j < 10; ++j) {
            for (int move : moves[j]) {
                temp[j] = (temp[j] + dp[move]) % MOD;
            }
        }
        dp.swap(temp);
    }
    long long total = 0;
    for (long long count : dp) {
        total = (total + count) % MOD;
    }
    return static_cast<int>(total);
}

