std::vector<int> movesToStamp(const std::string& stamp, const std::string& target) {
    int n = static_cast<int>(target.size());
    int m = static_cast<int>(stamp.size());
    std::string cur = target;
    std::vector<int> result;
    std::vector<bool> visited(n, false);
    int stars = 0;

    auto canReplace = [&](int pos) -> int {
        int cnt = 0;
        for (int j = 0; j < m; ++j) {
            char c = cur[pos + j];
            if (c == '?') continue;
            if (c != stamp[j]) return -1;
            ++cnt;
        }
        return cnt;
    };

    while (stars < n) {
        bool madeProgress = false;
        for (int i = 0; i <= n - m; ++i) {
            if (visited[i]) continue;
            int replaceCount = canReplace(i);
            if (replaceCount > 0) {
                for (int j = 0; j < m; ++j) {
                    if (cur[i + j] != '?') {
                        cur[i + j] = '?';
                        ++stars;
                    }
                }
                visited[i] = true;
                result.push_back(i);
                madeProgress = true;
                break;
            }
        }
        if (!madeProgress) {
            return std::vector<int>();
        }
    }

    std::reverse(result.begin(), result.end());
    return result;
}

