int distinctSubseqII(const std::string& s) {
    const long long MOD = 1000000007LL;
    size_t n = s.size();
    std::vector<long long> dp(n + 1, 0);
    std::vector<int> last(26, -1);
    dp[0] = 1;
    for (size_t i = 1; i <= n; ++i) {
        dp[i] = dp[i - 1] * 2 % MOD;
        int idx = s[i - 1] - 'a';
        if (last[idx] != -1) {
            dp[i] = (dp[i] - dp[last[idx]] + MOD) % MOD;
