        return hours >= 0 && hours <= 23 && minutes >= 0 && minutes <= 59;
    };
    std::function<void(int, int)> permute = [&](int start, int end) {
        if (start == end) {
            std::string time = std::to_string(arr[0]) + std::to_string(arr[1]) + ":" + std::to_string(arr[2]) + std::to_string(arr[3]);
            if (isValidTime(time)) {
                int cur = (arr[0] * 10 + arr[1]) * 100 + (arr[2] * 10 + arr[3]);
                maxTime = std::max(maxTime, cur);
            }
        } else {
            for (int i = start; i <= end; ++i) {
                std::swap(arr[start], arr[i]);
                permute(start + 1, end);
                std::swap(arr[start], arr[i]);
            }
        }
    };
    permute(0, static_cast<int>(arr.size()) - 1);
    if (maxTime == -1) return "";
    int hours = maxTime / 100;
    int minutes = maxTime % 100;
    std::string hh = (hours < 10 ? "0" : "") + std::to_string(hours);
    std::string mm = (minutes < 10 ? "0" : "") + std::to_string(minutes);
    return hh + ":" + mm;
}

