int removeStones(const std::vector<std::vector<int>>& stones) {
    std::unordered_map<std::string, std::string> parent;
    std::unordered_map<std::string, int> rank;

    std::function<std::string(const std::string&)> find = [&](const std::string& x) -> std::string {
        if (parent.find(x) == parent.end()) {
            parent[x] = x;
            rank[x] = 0;
        }
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    };

    auto unite = [&](const std::string& x, const std::string& y) {
        std::string rootX = find(x);
        std::string rootY = find(y);
        if (rootX == rootY) return;
        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    };

    for (size_t i = 0; i < stones.size(); ++i) {
        for (size_t j = i + 1; j < stones.size(); ++j) {
            if (stones[i][0] == stones[j][0] || stones[i][1] == stones[j][1]) {
                std::string keyI = std::to_string(stones[i][0]) + "," + std::to_string(stones[i][1]);
                std::string keyJ = std::to_string(stones[j][0]) + "," + std::to_string(stones[j][1]);
                unite(keyI, keyJ);
            }
        }
    }

    std::unordered_set<std::string> groups;
    for (const auto& stone : stones) {
        std::string key = std::to_string(stone[0]) + "," + std::to_string(stone[1]);
        groups.insert(find(key));
    }

    return static_cast<int>(stones.size() - groups.size());
}

