static std::vector<int> getPrimeFactors(int num) {
    std::vector<int> factors;
    int n = num;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            factors.push_back(i);
            while (n % i == 0) {
                n /= i;
            }
        }
    }
    if (n > 1) {
        factors.push_back(n);
    }
    return factors;
}

static int getCommonFactor(const std::vector<int>& a, const std::vector<int>& b) {
    std::unordered_set<int> setA(a.begin(), a.end());
    for (int factor : b) {
        if (setA.find(factor) != setA.end()) {
            return factor;
        }
    }
    return -1;
}

static int find(std::unordered_map<int, int>& parent, int x) {
    if (parent[x] != x) {
        parent[x] = find(parent, parent[x]);
    }
    return parent[x];
}

static void unite(std::unordered_map<int, int>& parent, int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);
    if (rootX != rootY) {
        parent[rootX] = rootY;
    }
}

int largestComponentSize(const std::vector<int>& nums) {
    std::unordered_map<int, std::vector<int>> primeFactors;
    for (int num : nums) {
        primeFactors[num] = getPrimeFactors(num);
    }

    std::unordered_map<int, int> parent;
    for (int num : nums) {
        parent[num] = num;
    }

    for (int num1 : nums) {
        for (int num2 : nums) {
            if (num1 != num2) {
                int commonFactor = getCommonFactor(primeFactors[num1], primeFactors[num2]);
                if (commonFactor != -1) {
                    unite(parent, num1, num2);
                }
            }
        }
    }

    std::unordered_map<int, int> componentSizes;
    for (int num : nums) {
        int root = find(parent, num);
        ++componentSizes[root];
    }

    int maxSize = 0;
    for (const auto& kv : componentSizes) {
        maxSize = std::max(maxSize, kv.second);
    }
    return maxSize;
}

