        }
        if (needDelete) {
            ++deletions;
        } else {
            for (int i = 0; i < n - 1; ++i) {
                if (!sorted[i] && strs[i][col] < strs[i + 1][col]) {
                    sorted[i] = true;
                }
            }
        }
    }
    return deletions;
}

