int tallestBillboard(const std::vector<int>& rods) {
    std::unordered_map<int, int> dp;
    dp[0] = 0;
    for (int rod : rods) {
        std::unordered_map<int, int> cur = dp;
        for (const auto& kv : dp) {
            int diff = kv.first;
            int shortHeight = kv.second;
            int newDiff = diff + rod;
            if (cur.find(newDiff) == cur.end() || shortHeight > cur[newDiff]) {
                cur[newDiff] = shortHeight;
            }
            int newDiff2 = std::abs(diff - rod);
            int newHeight2 = shortHeight + std::min(rod, diff);
            if (cur.find(newDiff2) == cur.end() || newHeight2 > cur[newDiff2]) {
                cur[newDiff2] = newHeight2;
            }
        }
        dp.swap(cur);
    }
    return dp[0];
}

