bool canReorderDoubled(const std::vector<int>& arr) {
    std::unordered_map<long long, int> countMap;
    for (int num : arr) {
        ++countMap[static_cast<long long>(num)];
    }
    std::vector<long long> keys;
    keys.reserve(countMap.size());
    for (const auto& p : countMap) {
        keys.push_back(p.first);
    }
    std::sort(keys.begin(), keys.end(),
              [](long long a, long long b) { return std::llabs(a) < std::llabs(b); });
    for (long long key : keys) {
        int count = countMap[key];
        if (count > 0) {
            long long doubleKey = key * 2;
            int doubleCount = countMap.count(doubleKey) ? countMap[doubleKey] : 0;
            if (count > doubleCount) {
                return false;
            }
            countMap[doubleKey] = doubleCount - count;
        }
    }
    return true;
}

