std::string getNextState(const std::string& state) {
    std::string next(state.size(), '0');
    for (size_t i = 1; i + 1 < state.size(); ++i) {
        next[i] = (state[i - 1] == state[i + 1]) ? '1' : '0';
    }
    return next;
}

std::vector<int> prisonAfterNDays(const std::vector<int>& cells, int n) {
    std::string state;
    state.reserve(cells.size());
    for (int c : cells) {
        state.push_back(c ? '1' : '0');
    }
    std::unordered_map<std::string, int> map;
    int days = 0;
    while (days < n) {
        auto it = map.find(state);
        if (it != map.end()) {
            int cycleLength = days - it->second;
            int remainingDays = (n - days) % cycleLength;
            for (int i = 0; i < remainingDays; ++i) {
                state = getNextState(state);
            }
            break;
        }
        map[state] = days;
        state = getNextState(state);
        ++days;
    }
    std::vector<int> result;
    result.reserve(state.size());
    for (char ch : state) {
        result.push_back(ch - '0');
    }
    return result;
}

