double minAreaFreeRect(const std::vector<std::vector<int>>& points) {
    std::size_t n = points.size();
    if (n < 4) return 0.0;
    std::unordered_set<std::int64_t> pointSet;
    pointSet.reserve(n * 2);
    for (const auto& p : points) {
        std::int64_t key = (static_cast<std::int64_t>(p[0]) << 32) ^ static_cast<std::uint32_t>(p[1]);
        pointSet.insert(key);
    }

    double minArea = std::numeric_limits<double>::infinity();

    for (std::size_t i = 0; i < n; ++i) {
        const int xi = points[i][0];
        const int yi = points[i][1];
        for (std::size_t j = 0; j < n; ++j) {
            if (j == i) continue;
            const int xj = points[j][0];
            const int yj = points[j][1];
            int v1x = xj - xi;
            int v1y = yj - yi;
            for (std::size_t k = 0; k < n; ++k) {
                if (k == i || k == j) continue;
                const int xk = points[k][0];
                const int yk = points[k][1];
                int v2x = xk - xi;
                int v2y = yk - yi;
                // check right angle: dot product zero
                if (static_cast<long long>(v1x) * v2x + static_cast<long long>(v1y) * v2y != 0) continue;
                // fourth point
                int xd = xj + xk - xi;
                int yd = yj + yk - yi;
                std::int64_t dKey = (static_cast<std::int64_t>(xd) << 32) ^ static_cast<std::uint32_t>(yd);
                if (pointSet.find(dKey) == pointSet.end()) continue;
                // area = |cross product|
                double area = std::abs(static_cast<long long>(v1x) * v2y - static_cast<long long>(v1y) * v2x);
                if (area > 0 && area < minArea) minArea = area;
            }
        }
    }

    return std::isinf(minArea) ? 0.0 : minArea;
}

