}

std::string devowel(const std::string& s) {
    std::string res;
    res.reserve(s.size());
    for (char ch : s) {
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
            res.push_back('*');
        } else {
            res.push_back(ch);
        }
    }
    return res;
}

std::vector<std::string> spellchecker(const std::vector<std::string>& wordlist, const std::vector<std::string>& queries) {
    std::unordered_set<std::string> originalWords(wordlist.begin(), wordlist.end());
    std::unordered_map<std::string, std::string> lowerCaseWords;
    std::unordered_map<std::string, std::string> devowelWords;

    for (const std::string& word : wordlist) {
        std::string lower = toLower(word);
        if (lowerCaseWords.find(lower) == lowerCaseWords.end()) {
            lowerCaseWords[lower] = word;
        }
        std::string dev = devowel(lower);
        if (devowelWords.find(dev) == devowelWords.end()) {
            devowelWords[dev] = word;
        }
    }

    std::vector<std::string> result;
    result.reserve(queries.size());
    for (const std::string& query : queries) {
        if (originalWords.find(query) != originalWords.end()) {
            result.push_back(query);
        } else {
            std::string lower = toLower(query);
            auto itLower = lowerCaseWords.find(lower);
            if (itLower != lowerCaseWords.end()) {
                result.push_back(itLower->second);
            } else {
                std::string dev = devowel(lower);
                auto itDev = devowelWords.find(dev);
                if (itDev != devowelWords.end()) {
                    result.push_back(itDev->second);
                } else {
                    result.push_back("");
                }
            }
        }
    }
    return result;
}

