        for (int j = 0; yj <= bound; ++j) {
            long long val = xi + yj;
            if (val <= bound) {
                uniq.insert(static_cast<int>(val));
            }
            if (y == 1) {
                break;
            }
            yj *= y;
        }
        if (x == 1) {
            break;
        }
        xi *= x;
    }
    std::vector<int> result(uniq.begin(), uniq.end());
    std::sort(result.begin(), result.end());
    return result;
}

