static void flip(std::vector<int>& arr, int k) {
    int left = 0;
    int right = k;
    while (left < right) {
        int temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        ++left;
        --right;
    }
}

std::vector<int> pancakeSort(std::vector<int>& arr) {
    std::vector<int> result;
    int n = static_cast<int>(arr.size());
    for (int i = n - 1; i > 0; --i) {
        int maxIndex = 0;
        for (int j = 1; j <= i; ++j) {
            if (arr[j] > arr[maxIndex]) {
                maxIndex = j;
            }
        }
        if (maxIndex == i) {
            continue;
        }
        if (maxIndex != 0) {
            result.push_back(i + 1);
            flip(arr, i);
            int newIdx = i - maxIndex;
            result.push_back(newIdx + 1);
            flip(arr, newIdx);
            result.push_back(i + 1);
            flip(arr, i);
        } else {
            result.push_back(i + 1);
            flip(arr, i);
        }
    }
    return result;
}

