static long long gcd_ll(long long a, long long b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static std::pair<long long, long long> toFraction(const std::string& s) {
    std::string intPart, nonRep, rep;
    std::size_t dotPos = s.find('.');
    std::size_t lparPos = s.find('(');
    std::size_t rparPos = s.find(')');

    if (dotPos == std::string::npos) {
        if (lparPos == std::string::npos) {
            intPart = s;
        } else {
            intPart = s.substr(0, lparPos);
            rep = s.substr(lparPos + 1, rparPos - lparPos - 1);
        }
    } else {
        intPart = s.substr(0, dotPos);
        if (lparPos == std::string::npos) {
            nonRep = s.substr(dotPos + 1);
        } else {
            nonRep = s.substr(dotPos + 1, lparPos - dotPos - 1);
            rep = s.substr(lparPos + 1, rparPos - lparPos - 1);
        }
    }

    long long A = intPart.empty() ? 0 : std::stoll(intPart);
    long long n = static_cast<long long>(nonRep.size());
    long long r = static_cast<long long>(rep.size());

    auto pow10 = [](long long k) -> long long {
        long long res = 1;
        while (k--) res *= 10;
        return res;
    };

    long long pow10n = pow10(n);
    long long numerator, denominator;

    if (r == 0) {
        long long nonInt = nonRep.empty() ? 0 : std::stoll(nonRep);
        denominator = pow10n;
        numerator = A * denominator + nonInt;
    } else {
        long long nonInt = nonRep.empty() ? 0 : std::stoll(nonRep);
        long long repInt = rep.empty() ? 0 : std::stoll(rep);
        long long pow10r = pow10(r);
        denominator = pow10n * (pow10r - 1);
        numerator = A * denominator + nonInt * (pow10r - 1) + repInt;
    }

    long long g = gcd_ll(numerator, denominator);
    numerator /= g;
    denominator /= g;
    return {numerator, denominator};
}

bool isRationalEqual(const std::string& s, const std::string& t) {
    auto f1 = toFraction(s);
    auto f2 = toFraction(t);
    return f1.first == f2.first && f1.second == f2.second;
}

