int oddEvenJumps(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    if (n == 0) return 0;
    std::vector<int> nextHigher(n, -1), nextLower(n, -1);
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) idx[i] = i;

    std::sort(idx.begin(), idx.end(), [&](int a, int b) {
        if (arr[a] != arr[b]) return arr[a] < arr[b];
        return a < b;
    });
    std::stack<int> st;
    for (int i : idx) {
        while (!st.empty() && i > st.top()) {
            nextHigher[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }

    std::sort(idx.begin(), idx.end(), [&](int a, int b) {
        if (arr[a] != arr[b]) return arr[a] > arr[b];
        return a < b;
    });
    while (!st.empty()) st.pop();
    for (int i : idx) {
        while (!st.empty() && i > st.top()) {
            nextLower[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }

    std::vector<char> odd(n, 0), even(n, 0);
    odd[n - 1] = even[n - 1] = 1;
    for (int i = n - 2; i >= 0; --i) {
        if (nextHigher[i] != -1) odd[i] = even[nextHigher[i]];
        if (nextLower[i] != -1) even[i] = odd[nextLower[i]];
    }

    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (odd[i]) ++count;
    }
    return count;
}

