int uniquePathsIII(std::vector<std::vector<int>>& grid) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    int nonObstacles = 0;
    int startX = 0, startY = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 0) {
                ++nonObstacles;
            } else if (grid[i][j] == 1) {
                startX = i;
                startY = j;
            }
        }
    }
    int count = 0;
    std::function<void(int, int, int)> backtrack = [&](int x, int y, int steps) {
        if (x >= 0 && x < m && y >= 0 && y < n && grid[x][y] == 2 && steps == nonObstacles + 1) {
            ++count;
        }
        if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y] == -1 || grid[x][y] == INT_MAX) {
            return;
        }
        int temp = grid[x][y];
        grid[x][y] = INT_MAX;
        backtrack(x + 1, y, steps + 1);
        backtrack(x - 1, y, steps + 1);
        backtrack(x, y + 1, steps + 1);
        backtrack(x, y - 1, steps + 1);
        grid[x][y] = temp;
    };
    backtrack(startX, startY, 0);
    return count;
}

