std::string stringWithoutAAAorBBB(int a, int b) {
    std::string result;
    while (a > 0 || b > 0) {
        bool canPlaceA = false;
        if (a > 0) {
            if (result.size() < 2 || !(result[result.size() - 1] == 'a' && result[result.size() - 2] == 'a')) {
                if (feasible(a - 1, b)) {
                    canPlaceA = true;
                }
            }
        }
        bool canPlaceB = false;
        if (b > 0) {
            if (result.size() < 2 || !(result[result.size() - 1] == 'b' && result[result.size() - 2] == 'b')) {
                if (feasible(a, b - 1)) {
                    canPlaceB = true;
                }
            }
        }
        if (canPlaceA && (!canPlaceB || 'a' < 'b')) {
            result.push_back('a');
            --a;
        } else if (canPlaceB) {
            result.push_back('b');
            --b;
        } else {
            // Fallback: place any allowed character to avoid infinite loop
            if (a > 0) {
                result.push_back('a');
                --a;
            } else if (b > 0) {
                result.push_back('b');
                --b;
            }
        }
    }
    return result;
}

