int mincostTickets(const std::vector<int>& days, const std::vector<int>& costs) {
    int lastDay = days.back();
    std::vector<int> dp(lastDay + 1, 0);
    std::unordered_set<int> travelDays(days.begin(), days.end());
    for (int day = 1; day <= lastDay; ++day) {
        if (travelDays.find(day) == travelDays.end()) {
            dp[day] = dp[day - 1];
        } else {
            int cost1 = dp[std::max(0, day - 1)] + costs[0];
            int cost7 = dp[std::max(0, day - 7)] + costs[1];
            int cost30 = dp[std::max(0, day - 30)] + costs[2];
            dp[day] = std::min({cost1, cost7, cost30});
        }
    }
    return dp[lastDay];
}

