std::vector<std::vector<int>> verticalTraversal(TreeNode* root) {
    if (!root) return {};
    std::unordered_map<int, std::vector<int>> columnTable;
    std::queue<std::pair<TreeNode*, int>> q;
    q.push({root, 0});
    int minColumn = 0, maxColumn = 0;
    while (!q.empty()) {
        auto frontPair = q.front();
        q.pop();
        TreeNode* node = frontPair.first;
        int column = frontPair.second;
        if (node) {
            columnTable[column].push_back(node->val);
            if (column < minColumn) minColumn = column;
            if (column > maxColumn) maxColumn = column;
            q.push({node->left, column - 1});
            q.push({node->right, column + 1});
        }
    }
    std::vector<std::vector<int>> result;
    for (int i = minColumn; i <= maxColumn; ++i) {
        auto it = columnTable.find(i);
        if (it != columnTable.end()) {
            std::sort(it->second.begin(), it->second.end());
            result.push_back(it->second);
        }
    }
    return result;
}

