    std::function<void(int, int)> dfs = [&](int prev, int depth) {
        if (depth == n) {
            ++count;
            return;
        }
        for (int nxt : adj[prev]) {
            if (freq[nxt] == 0) continue;
            --freq[nxt];
            dfs(nxt, depth + 1);
            ++freq[nxt];
        }
    };
    for (auto &p : freq) {
        int val = p.first;
        --freq[val];
        dfs(val, 1);
        ++freq[val];
    }
    return count;
}

