std::vector<std::string> findCommonCharacters(const std::vector<std::string>& words) {
    std::unordered_map<char, int> commonChars;
    for (char ch : words[0]) {
        if (!commonChars.count(ch)) commonChars[ch] = 0;
        commonChars[ch]++;
    }
    for (size_t i = 1; i < words.size(); ++i) {
        std::unordered_map<char, int> currentWord;
        for (char ch : words[i]) {
            if (!currentWord.count(ch)) currentWord[ch] = 0;
            currentWord[ch]++;
        }
        for (auto it = commonChars.begin(); it != commonChars.end(); ) {
            char ch = it->first;
            if (currentWord.count(ch)) {
                it->second = std::min(it->second, currentWord[ch]);
                ++it;
            } else {
                it = commonChars.erase(it);
            }
        }
    }
    std::vector<std::string> result;
    for (const auto& pair : commonChars) {
        for (int i = 0; i < pair.second; ++i) {
            result.push_back(std::string(1, pair.first));
        }
    }
    std::sort(result.begin(), result.end());
    return result;
}

#include <bits/stdc++.h>

int mergeStones(const std::vector<int>& stones, int K) {
    int n = static_cast<int>(stones.size());
    if ((n - 1) % (K - 1) != 0) return -1;
    std::vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) prefix[i + 1] = prefix[i] + stones[i];
    const long long INF = (1LL << 60);
    std::vector<std::vector<std::vector<long long>>> dp(
        n, std::vector<std::vector<long long>>(n, std::vector<long long>(K + 1, INF)));
    for (int i = 0; i < n; ++i) dp[i][i][1] = 0;
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            for (int m = 2; m <= K; ++m) {
                for (int mid = i; mid < j; ++mid) {
                    if (dp[i][mid][m - 1] == INF || dp[mid + 1][j][1] == INF) continue;
                    dp[i][j][m] = std::min(dp[i][j][m], dp[i][mid][m - 1] + dp[mid + 1][j][1]);
                }
            }
            if ((len - 1) % (K - 1) == 0 && dp[i][j][K] != INF) {
                dp[i][j][1] = dp[i][j][K] + (prefix[j + 1] - prefix[i]);
            }
        }
    }
    long long ans = dp[0][n - 1][1];
    return ans == INF ? -1 : static_cast<int>(ans);
}

