std::vector<int> gridIllumination(int n, const std::vector<std::vector<int>>& lamps, const std::vector<std::vector<int>>& queries) {
    std::unordered_set<std::string> lampSet;
    for (const auto& lamp : lamps) {
        lampSet.insert(std::to_string(lamp[0]) + "," + std::to_string(lamp[1]));
    }
    std::vector<int> rowCounts(n, 0);
    std::vector<int> colCounts(n, 0);
    std::vector<int> diagonal1Counts(2 * n - 1, 0);
    std::vector<int> diagonal2Counts(2 * n - 1, 0);
    for (const auto& lamp : lamps) {
        int row = lamp[0];
        int col = lamp[1];
        rowCounts[row]++;
        colCounts[col]++;
        diagonal1Counts[row + col]++;
        diagonal2Counts[row - col + n - 1]++;
    }
    std::vector<int> result(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        int row = queries[i][0];
        int col = queries[i][1];
        result[i] = (rowCounts[row] > 0 || colCounts[col] > 0 || diagonal1Counts[row + col] > 0 || diagonal2Counts[row - col + n - 1] > 0) ? 1 : 0;
        for (int r = std::max(0, row - 1); r <= std::min(n - 1, row + 1); ++r) {
            for (int c = std::max(0, col - 1); c <= std::min(n - 1, col + 1); ++c) {
                std::string lampKey = std::to_string(r) + "," + std::to_string(c);
                if (lampSet.find(lampKey) != lampSet.end()) {
                    lampSet.erase(lampKey);
                    rowCounts[r]--;
                    colCounts[c]--;
                    diagonal1Counts[r + c]--;
                    diagonal2Counts[r - c + n - 1]--;
                }
            }
        }
    }
    return result;
}

