long long clumsy(int n) {
    std::vector<long long> numbers;
    std::vector<char> ops;
    numbers.push_back(n);
    n--;
    const char operations[4] = {'*', '/', '+', '-'};
    int opIndex = 0;
    while (n > 0) {
        char operation = operations[opIndex % 4];
        if (operation == '*') {
            long long top = numbers.back();
            numbers.pop_back();
            numbers.push_back(top * n);
        } else if (operation == '/') {
            long long top = numbers.back();
            numbers.pop_back();
            numbers.push_back(top / n);
        } else {
            ops.push_back(operation);
            numbers.push_back(n);
        }
        ++opIndex;
        --n;
    }
    long long result = numbers[0];
    for (size_t i = 0; i < ops.size(); ++i) {
        if (ops[i] == '+') {
            result += numbers[i + 1];
        } else {
            result -= numbers[i + 1];
        }
    }
    return result;
}

