        bool match = true;
        for (std::size_t i = 0; i < query.size(); ++i) {
            char c = query[i];
            if (patternIndex < pattern.size() && c == pattern[patternIndex]) {
                ++patternIndex;
            } else if (c >= 'A' && c <= 'Z') {
                match = false;
                break;
            }
        }
        if (patternIndex < pattern.size()) {
            match = false;
        }
        result.push_back(match);
    }
    return result;
}

