int longestArithmeticSubsequence(const std::vector<int>& nums) {
    int maxLength = 0;
    std::unordered_map<int, int> numMap;
    for (size_t i = 0; i < nums.size(); ++i) {
        numMap[nums[i]] = static_cast<int>(i);
    }
    for (size_t i = 0; i < nums.size(); ++i) {
        for (size_t j = i + 1; j < nums.size(); ++j) {
            long long diff = static_cast<long long>(nums[j]) - static_cast<long long>(nums[i]);
            int currentLength = 2;
            long long lastNum = nums[j];
            while (numMap.find(static_cast<int>(lastNum + diff)) != numMap.end()) {
                lastNum += diff;
                ++currentLength;
            }
            maxLength = std::max(maxLength, currentLength);
        }
    }
    return maxLength;
}

