struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

static TreeNode* dfs(const std::string& traversal, size_t& index, int depth) {
    int value = 0;
    while (index < traversal.size() && traversal[index] != '-') {
        value = value * 10 + (traversal[index++] - '0');
    }
    TreeNode* node = new TreeNode(value);
    while (index < traversal.size()) {
        size_t save = index;
        int childDepth = 0;
        while (index < traversal.size() && traversal[index] == '-') {
            ++childDepth;
            ++index;
        }
        if (childDepth == depth + 1) {
            if (!node->left) node->left = dfs(traversal, index, childDepth);
            else node->right = dfs(traversal, index, childDepth);
        } else {
            index = save; // rewind: dashes belong to an ancestor level
            break;
        }
    }
    return node;
}

TreeNode* recoverFromPreorder(const std::string& traversal) {
    size_t index = 0;
    return dfs(traversal, index, 0);
}

