int maxSumTwoNoOverlapSubarrays(const std::vector<int>& nums, int firstLen, int secondLen) {
    int maxSum = 0;
    std::vector<int> prefixSum;
    prefixSum.reserve(nums.size() + 1);
    prefixSum.push_back(0);
    for (size_t i = 0; i < nums.size(); ++i) {
        prefixSum.push_back(prefixSum[i] + nums[i]);
    }
    for (size_t i = 0; i + firstLen <= nums.size(); ++i) {
        for (size_t j = 0; j + secondLen <= nums.size(); ++j) {
            if (i + firstLen <= j || j + secondLen <= i) {
                int sum1 = prefixSum[i + firstLen] - prefixSum[i];
                int sum2 = prefixSum[j + secondLen] - prefixSum[j];
                maxSum = std::max(maxSum, sum1 + sum2);
            }
        }
    }
    return maxSum;
}

