    std::string stream;
};

Checker StreamChecker(const std::vector<std::string>& words) {
    Checker c;
    c.trie = new TrieNode();
    for (const std::string& word : words) {
        TrieNode* node = c.trie;
        for (int i = (int)word.size() - 1; i >= 0; --i) {
            char ch = word[i];
            if (!node->children.count(ch)) node->children[ch] = new TrieNode();
            node = node->children[ch];
        }
        node->end = true;
    }
    c.stream = "";
    return c;
}

bool query(Checker& c, char letter) {
    c.stream += letter;
    TrieNode* node = c.trie;
    for (int i = (int)c.stream.size() - 1; i >= 0; --i) {
        if (!node->children.count(c.stream[i])) return false;
        node = node->children[c.stream[i]];
        if (node->end) return true;
    }
    return false;
}

