std::vector<std::vector<int>> colorBorder(std::vector<std::vector<int>> grid, int row, int col, int color) {
    int componentColor = grid[row][col];
    std::vector<std::pair<int, int>> directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    std::unordered_set<std::string> visited;
    std::unordered_set<std::string> border;
    std::function<void(int, int)> dfs = [&](int r, int c) {
        visited.insert(std::to_string(r) + "," + std::to_string(c));
        bool isBorder = (r == 0) || (r == static_cast<int>(grid.size()) - 1) || (c == 0) || (c == static_cast<int>(grid[0].size()) - 1);
        if (!isBorder) {
            for (const auto& d : directions) {
                int nr = r + d.first;
                int nc = c + d.second;
                if (nr < 0 || nr >= static_cast<int>(grid.size()) || nc < 0 || nc >= static_cast<int>(grid[0].size()) || grid[nr][nc] != componentColor) {
                    isBorder = true;
                    break;
                }
            }
        }
        if (isBorder) {
            border.insert(std::to_string(r) + "," + std::to_string(c));
        }
        for (const auto& d : directions) {
            int nr = r + d.first;
            int nc = c + d.second;
            if (nr >= 0 && nr < static_cast<int>(grid.size()) && nc >= 0 && nc < static_cast<int>(grid[0].size()) && grid[nr][nc] == componentColor) {
                std::string key = std::to_string(nr) + "," + std::to_string(nc);
                if (visited.find(key) == visited.end()) {
                    dfs(nr, nc);
                }
            }
        }
    };
    dfs(row, col);
    for (const std::string& coord : border) {
        size_t pos = coord.find(',');
        int r = std::stoi(coord.substr(0, pos));
        int c = std::stoi(coord.substr(pos + 1));
        grid[r][c] = color;
    }
    return grid;
}

