int maxUncrossedLines(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::unordered_map<std::string, int> memo;
    std::function<int(int, int)> dp = [&](int i, int j) -> int {
        std::string key = std::to_string(i) + "," + std::to_string(j);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        if (i == static_cast<int>(nums1.size()) || j == static_cast<int>(nums2.size())) return 0;
        if (nums1[i] == nums2[j]) {
            memo[key] = 1 + dp(i + 1, j + 1);
            return memo[key];
        }
        memo[key] = std::max(dp(i + 1, j), dp(i, j + 1));
        return memo[key];
    };
    return dp(0, 0);
}

