TreeNode* convertBST(TreeNode* root) {
    int sum = 0;
    std::function<void(TreeNode*)> reverseInorder = [&](TreeNode* node) {
        if (node == nullptr) return;
        reverseInorder(node->right);
        sum += node->val;
        node->val = sum;
        reverseInorder(node->left);
    };
    reverseInorder(root);
