    int maxMoves = std::max(
        stones[n - 1] - stones[1] - n + 2,
        stones[n - 2] - stones[0] - n + 2
    );
    int minMoves = n;
    int i = 0;
    for (int j = 0; j < n; ++j) {
        while (stones[j] - stones[i] + 1 > n) {
            ++i;
        }
        int cnt = j - i + 1;
        if (cnt == n - 1 && stones[j] - stones[i] + 1 == n - 1) {
            minMoves = std::min(minMoves, 2);
        } else {
            minMoves = std::min(minMoves, n - cnt);
        }
    }
    return {minMoves, maxMoves};
}

#include <bits/stdc++.h>

bool isEscapePossible(const std::vector<std::vector<int>>& blocked,
                      const std::vector<int>& source,
                      const std::vector<int>& target) {
    const int MAX = 1000000;
    std::unordered_set<long long> blockedSet;
    for (const auto& b : blocked) {
        long long key = (static_cast<long long>(b[0]) << 20) + b[1];
        blockedSet.insert(key);
    }

    auto bfs = [&](const std::vector<int>& start, const std::vector<int>& goal) -> bool {
        std::queue<std::pair<int, int>> q;
        std::unordered_set<long long> visited;
        q.emplace(start[0], start[1]);
        visited.insert((static_cast<long long>(start[0]) << 20) + start[1]);

        int limit = static_cast<int>(blocked.size()) * (static_cast<int>(blocked.size()) - 1) / 2;
        const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};

        while (!q.empty()) {
            std::pair<int, int> cur = q.front();
            q.pop();
            int x = cur.first;
            int y = cur.second;
            if (x == goal[0] && y == goal[1]) return true;
            if ((int)visited.size() > limit) return true;

            for (const auto& d : dirs) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx < 0 || ny < 0 || nx >= MAX || ny >= MAX) continue;
                long long nkey = (static_cast<long long>(nx) << 20) + ny;
                if (blockedSet.count(nkey) || visited.count(nkey)) continue;
                visited.insert(nkey);
                q.emplace(nx, ny);
            }
        }
        return false;
    };

    if (!bfs(source, target)) return false;
    if (!bfs(target, source)) return false;
    return true;
}

