int longestStrChain(std::vector<std::string> words) {
    std::sort(words.begin(), words.end(), [](const std::string& a, const std::string& b) {
        return a.length() < b.length();
    });
    std::unordered_map<std::string, int> dp;
    int maxLength = 1;
    for (const auto& word : words) {
        dp[word] = 1;
