std::string longestDupSubstring(const std::string& s) {
    int left = 1;
    int right = static_cast<int>(s.length());
    std::string longest = "";
    while (left <= right) {
        int mid = (left + right) / 2;
        std::unordered_set<std::string> set;
        bool found = false;
        for (int i = 0; i <= static_cast<int>(s.length()) - mid; ++i) {
            std::string substr = s.substr(i, mid);
            if (set.find(substr) != set.end()) {
                longest = substr;
                found = true;
                break;
            }
            set.insert(substr);
        }
        if (found) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return longest;
}

