int maxSatisfied(const std::vector<int>& customers, const std::vector<int>& grumpy, int minutes) {
    long long totalSatisfied = 0;
    long long currentGrumpy = 0;
    long long maxGrumpy = 0;
    size_t windowStart = 0;
    for (size_t windowEnd = 0; windowEnd < customers.size(); ++windowEnd) {
        if (grumpy[windowEnd] == 0) {
            totalSatisfied += customers[windowEnd];
        } else {
            currentGrumpy += customers[windowEnd];
        }
        if (windowEnd >= static_cast<size_t>(minutes) - 1) {
            maxGrumpy = std::max(maxGrumpy, currentGrumpy);
            if (grumpy[windowStart] == 1) {
                currentGrumpy -= customers[windowStart];
            }
            ++windowStart;
        }
    }
    return static_cast<int>(totalSatisfied + maxGrumpy);
}

