char find(std::unordered_map<char, char>& parent, char c) {
    if (parent[c] != c) {
        parent[c] = find(parent, parent[c]);
    }
    return parent[c];
}

void unionSets(std::unordered_map<char, char>& parent, char a, char b) {
    char rootA = find(parent, a);
    char rootB = find(parent, b);
    if (rootA == rootB) return;
    if (rootA < rootB) {
        parent[rootB] = rootA;
    } else {
        parent[rootA] = rootB;
    }
}

std::string smallestEquivalentString(const std::string& s1, const std::string& s2, const std::string& baseStr) {
    std::unordered_map<char, char> parent;
    for (int i = 0; i < 26; ++i) {
        char ch = 'a' + i;
        parent[ch] = ch;
    }
    for (size_t i = 0; i < s1.size(); ++i) {
        unionSets(parent, s1[i], s2[i]);
    }
    std::string result;
    result.reserve(baseStr.size());
    for (char c : baseStr) {
        result.push_back(find(parent, c));
    }
