std::vector<int> addNegabinary(const std::vector<int>& arr1, const std::vector<int>& arr2) {
    int i = static_cast<int>(arr1.size()) - 1;
    int j = static_cast<int>(arr2.size()) - 1;
    int carry = 0;
    std::vector<int> rev;
    while (i >= 0 || j >= 0 || carry != 0) {
        int a = (i >= 0) ? arr1[i] : 0;
        int b = (j >= 0) ? arr2[j] : 0;
        int sum = a + b + carry;
        int digit = sum & 1;
        rev.push_back(digit);
        carry = (sum - digit) / -2;
        --i;
        --j;
    }
    while (rev.size() > 1 && rev.back() == 0) {
        rev.pop_back();
    }
    std::reverse(rev.begin(), rev.end());
    return rev;
}

TreeNode* sufficientSubset(TreeNode* root, int limit) {
    if (!root) return nullptr;
    if (!root->left && !root->right) {
        return root->val < limit ? nullptr : root;
    }
    if (root->left) root->left = sufficientSubset(root->left, limit - root->val);
    if (root->right) root->right = sufficientSubset(root->right, limit - root->val);
    if (!root->left && !root->right) return nullptr;
    return root;
}

