long long numberOfSubmatricesThatSumToTarget(std::vector<std::vector<int>>& matrix, int target) {
    long long count = 0;
    std::size_t rows = matrix.size();
    std::size_t cols = matrix[0].size();
    for (std::size_t i = 0; i < rows; ++i) {
        for (std::size_t j = 1; j < cols; ++j) {
            matrix[i][j] += matrix[i][j - 1];
        }
    }
    for (std::size_t left = 0; left < cols; ++left) {
        for (std::size_t right = left; right < cols; ++right) {
            std::unordered_map<long long, int> sumMap;
            sumMap[0] = 1;
            long long currentSum = 0;
            for (std::size_t i = 0; i < rows; ++i) {
                long long rowSum = matrix[i][right];
                if (left > 0) {
                    rowSum -= matrix[i][left - 1];
                }
                currentSum += rowSum;
                auto it = sumMap.find(currentSum - target);
                if (it != sumMap.end()) {
                    count += it->second;
                }
                ++sumMap[currentSum];
            }
        }
    }
    return count;
}

