int numTilePossibilities(const std::string& tiles) {
    int count = 0;
    std::unordered_map<char, int> tileCounts;
    for (char tile : tiles) {
        ++tileCounts[tile];
    }
    std::function<void()> backtrack = [&]() {
        for (auto& kv : tileCounts) {
            if (kv.second > 0) {
                ++count;
                --kv.second;
                backtrack();
                ++kv.second;
            }
        }
    };
    backtrack();
    return count;
}

