int largestValsFromLabels(const std::vector<int>& values, const std::vector<int>& labels, int numWanted, int useLimit) {
    int n = values.size();
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) idx[i] = i;
    std::sort(idx.begin(), idx.end(), [&](int a, int b) {
        return values[a] > values[b];
    });
    std::unordered_map<int, int> cnt;
    long long sum = 0;
    int taken = 0;
    for (int i : idx) {
