std::string shortestCommonSupersequence(const std::string& str1, const std::string& str2) {
    int m = static_cast<int>(str1.length());
    int n = static_cast<int>(str2.length());
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (str1[i - 1] == str2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    std::string result;
    int i = m, j = n;
    while (i > 0 && j > 0) {
        if (str1[i - 1] == str2[j - 1]) {
            result = std::string(1, str1[i - 1]) + result;
            --i;
            --j;
        } else if (dp[i - 1][j] > dp[i][j - 1]) {
            result = std::string(1, str1[i - 1]) + result;
            --i;
        } else {
            result = std::string(1, str2[j - 1]) + result;
            --j;
        }
    }
    while (i > 0) {
        result = std::string(1, str1[i - 1]) + result;
        --i;
    }
    while (j > 0) {
        result = std::string(1, str2[j - 1]) + result;
        --j;
    }
    return result;
}

