std::vector<double> sampleStatistics(const std::vector<int>& count) {
    std::vector<int> numbers;
    numbers.reserve(std::accumulate(count.begin(), count.end(), 0LL));
    for (size_t i = 0; i < count.size(); ++i) {
        for (int j = 0; j < count[i]; ++j) {
            numbers.push_back(static_cast<int>(i));
        }
    }
    int minimum = *std::min_element(numbers.begin(), numbers.end());
    int maximum = *std::max_element(numbers.begin(), numbers.end());
    long long sum = 0;
    for (int num : numbers) {
        sum += num;
    }
    double mean = static_cast<double>(sum) / numbers.size();
    mean = std::round(mean * 100000.0) / 100000.0;
    std::sort(numbers.begin(), numbers.end());
    double median;
    size_t middleIndex = numbers.size() / 2;
    if (numbers.size() % 2 == 0) {
        median = (numbers[middleIndex - 1] + numbers[middleIndex]) / 2.0;
    } else {
        median = numbers[middleIndex];
    }
    median = std::round(median * 100000.0) / 100000.0;
    int mode = 0;
    int maxCount = 0;
    for (size_t i = 0; i < count.size(); ++i) {
        if (count[i] > maxCount) {
            maxCount = count[i];
            mode = static_cast<int>(i);
        }
    }
    return {static_cast<double>(minimum), static_cast<double>(maximum), mean, median, static_cast<double>(mode)};
}

