bool carPooling(const std::vector<std::vector<int>>& trips, int capacity) {
    std::vector<std::pair<int, int>> stops;
    for (size_t i = 0; i < trips.size(); ++i) {
        stops.emplace_back(trips[i][1], trips[i][0]);
        stops.emplace_back(trips[i][2], -trips[i][0]);
    }
    std::sort(stops.begin(), stops.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  return a.first < b.first;
              });
    int currentPassengers = 0;
    for (size_t i = 0; i < stops.size(); ++i) {
        currentPassengers += stops[i].second;
        if (currentPassengers > capacity) {
            return false;
        }
    }
    return true;
}

