static std::unordered_set<std::string> parseTerm(const std::string& s, size_t& i) {
    std::unordered_set<std::string> cur = parseExpression(s, i);
    while (i < s.size() && s[i] != ',' && s[i] != '}') {
        std::unordered_set<std::string> nxt = parseExpression(s, i);
        std::unordered_set<std::string> combined;
        for (const auto& a : cur) {
            for (const auto& b : nxt) {
                combined.insert(a + b);
            }
        }
        cur.swap(combined);
    }
    return cur;
}

static std::unordered_set<std::string> parseFactor(const std::string& s, size_t& i) {
    if (s[i] == '{') {
        ++i; // skip '{'
        std::unordered_set<std::string> inside = parseExpression(s, i);
        ++i; // skip '}'
        return inside;
    } else {
        std::unordered_set<std::string> single;
        single.insert(std::string(1, s[i]));
        ++i;
        return single;
    }
}

static std::unordered_set<std::string> parseExpression(const std::string& s, size_t& i) {
    std::unordered_set<std::string> result = parseFactor(s, i);
    while (i < s.size() && s[i] != ',' && s[i] != '}') {
        std::unordered_set<std::string> next = parseFactor(s, i);
        std::unordered_set<std::string> combined;
        for (const auto& a : result) {
            for (const auto& b : next) {
                combined.insert(a + b);
            }
        }
        result.swap(combined);
    }
    while (i < s.size() && s[i] == ',') {
        ++i; // skip ','
        std::unordered_set<std::string> next = parseFactor(s, i);
        while (i < s.size() && s[i] != ',' && s[i] != '}') {
            std::unordered_set<std::string> more = parseFactor(s, i);
            std::unordered_set<std::string> combined;
            for (const auto& a : next) {
                for (const auto& b : more) {
                    combined.insert(a + b);
                }
            }
            next.swap(combined);
        }
        result.insert(next.begin(), next.end());
    }
    return result;
}

