std::vector<int> pathInZigZagTree(int label) {
    std::vector<int> path;
    while (label >= 1) {
        path.push_back(label);
        if (label == 1) break;
        int level = 63 - __builtin_clzll(static_cast<long long>(label));
        long long left = 1LL << level;
        long long right = (1LL << (level + 1)) - 1;
        long long parent = (left + right - static_cast<long long>(label)) / 2;
        label = static_cast<int>(parent);
    }
    std::reverse(path.begin(), path.end());
    return path;
}

