bool parseBoolExpr(const std::string& expression) {
    if (expression.size() == 1) {
        return expression[0] == 't';
    }
    char op = expression[0];
    std::vector<std::string> operands;
    int depth = 0;
    std::string current;
    for (size_t i = 2; i < expression.size() - 1; ++i) {
        char c = expression[i];
        if (c == '(') {
            ++depth;
            current.push_back(c);
        } else if (c == ')') {
            --depth;
            current.push_back(c);
        } else if (c == ',' && depth == 0) {
            operands.push_back(current);
            current.clear();
        } else {
            current.push_back(c);
        }
    }
    operands.push_back(current);
    if (op == '!') {
        return !parseBoolExpr(operands[0]);
    } else if (op == '&') {
        for (const auto& sub : operands) {
            if (!parseBoolExpr(sub)) return false;
        }
        return true;
    } else if (op == '|') {
        for (const auto& sub : operands) {
            if (parseBoolExpr(sub)) return true;
        }
        return false;
    }
    return false;
}

