std::vector<TreeNode*> delNodes(TreeNode* root, const std::vector<int>& to_delete) {
    std::vector<TreeNode*> result;
    std::unordered_set<int> delSet(to_delete.begin(), to_delete.end());
    std::function<TreeNode*(TreeNode*)> dfs = [&](TreeNode* node) -> TreeNode* {
        if (!node) return nullptr;
        if (delSet.find(node->val) != delSet.end()) {
            TreeNode* left = dfs(node->left);
            TreeNode* right = dfs(node->right);
            if (left) result.push_back(left);
            if (right) result.push_back(right);
            return nullptr;
        } else {
            node->left = dfs(node->left);
            node->right = dfs(node->right);
            return node;
        }
    };
    TreeNode* newRoot = dfs(root);
    if (newRoot) result.push_back(newRoot);
    return result;
}

