    int maxDepth = -1;
    TreeNode* lca = nullptr;
    std::function<void(TreeNode*, int)> dfs = [&](TreeNode* node, int depth) {
        if (!node) return;
        if (!node->left && !node->right && depth > maxDepth) {
            maxDepth = depth;
            lca = node;
        }
        if (node->left) dfs(node->left, depth + 1);
        if (node->right) dfs(node->right, depth + 1);
        if (node->left && node->right && depth + 1 == maxDepth) {
            lca = node;
        }
    };
    dfs(root, 0);
    return lca;
}

