int longestWPI(const std::vector<int>& hours) {
    int n = static_cast<int>(hours.size());
    std::vector<int> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + (hours[i] > 8 ? 1 : -1);
    }
    std::vector<int> decStack;
    for (int i = 0; i <= n; ++i) {
        if (decStack.empty() || prefix[i] < prefix[decStack.back()]) {
            decStack.push_back(i);
        }
    }
    int maxLen = 0;
    for (int j = n; j >= 0; --j) {
        while (!decStack.empty() && prefix[j] > prefix[decStack.back()]) {
            maxLen = std::max(maxLen, j - decStack.back());
            decStack.pop_back();
        }
    }
    return maxLen;
}

