#include <unordered_map>
#include <limits>

std::vector<int> smallestSufficientTeam(const std::vector<std::string>& req_skills, const std::vector<std::vector<std::string>>& people) {
    int n = static_cast<int>(req_skills.size());
    int m = static_cast<int>(people.size());
    std::unordered_map<std::string, int> skillToIndex;
    for (int i = 0; i < n; ++i) {
        skillToIndex[req_skills[i]] = i;
    }

    std::vector<int> personSkillSet(m, 0);
    for (int i = 0; i < m; ++i) {
        int skillSet = 0;
        for (const auto& skill : people[i]) {
            auto it = skillToIndex.find(skill);
            if (it != skillToIndex.end()) {
                skillSet |= (1 << it->second);
            }
        }
        personSkillSet[i] = skillSet;
    }

    int totalMasks = 1 << n;
    std::vector<std::vector<std::vector<int>>> dp(totalMasks, std::vector<std::vector<int>>(m + 1));
    std::vector<std::vector<char>> has(totalMasks, std::vector<char>(m + 1, 0));

    for (int i = 0; i < m; ++i) {
        int skillSet = personSkillSet[i];
        dp[skillSet][i] = std::vector<int>{i};
        has[skillSet][i] = 1;
    }

    for (int mask = 0; mask < totalMasks; ++mask) {
        for (int i = 0; i < m; ++i) {
            if (!has[mask][i]) continue;
            for (int j = i + 1; j < m; ++j) {
                int newMask = mask | personSkillSet[j];
                if (!has[newMask][j + 1] || dp[newMask][j + 1].size() > dp[mask][i].size() + 1) {
                    dp[newMask][j + 1] = dp[mask][i];
                    dp[newMask][j + 1].push_back(j);
                    has[newMask][j + 1] = 1;
                }
            }
        }
    }

    int fullMask = totalMasks - 1;
    int minSize = std::numeric_limits<int>::max();
    std::vector<int> result;
    for (int i = 0; i <= m; ++i) {
        if (has[fullMask][i] && static_cast<int>(dp[fullMask][i].size()) < minSize) {
            minSize = static_cast<int>(dp[fullMask][i].size());
            result = dp[fullMask][i];
        }
    }
    return result;
}

