long long numEquivDominoPairs(const std::vector<std::vector<int>>& dominoes) {
    long long count = 0;
    std::unordered_map<std::string, int> dominoMap;
    for (size_t i = 0; i < dominoes.size(); ++i) {
        int a = dominoes[i][0];
