int mctFromLeafValues(const std::vector<int>& arr) {
    long long result = 0;
    std::vector<int> stack;
    stack.push_back(std::numeric_limits<int>::max());
    for (int num : arr) {
        while (stack.back() <= num) {
            int mid = stack.back();
            stack.pop_back();
            result += static_cast<long long>(mid) * std::min(stack.back(), num);
        }
        stack.push_back(num);
    }
    for (size_t i = 1; i + 1 < stack.size(); ++i) {
        result += static_cast<long long>(stack[i]) * stack[i + 1];
    }
    return static_cast<int>(result);
}

