        if (nextY < curY) result.append(curY - nextY, 'L');
        if (nextX > curX) result.append(nextX - curX, 'D');
        if (nextY > curY) result.append(nextY - curY, 'R');
        result.push_back('!');
        curX = nextX;
        curY = nextY;
    }
    return result;
}

