long long movesToMakeZigzag(const std::vector<int>& nums) {
    long long evenValley = 0, oddValley = 0;
    int n = static_cast<int>(nums.size());
    for (int i = 0; i < n; ++i) {
        int left = (i > 0) ? nums[i - 1] : INT_MAX;
        int right = (i < n - 1) ? nums[i + 1] : INT_MAX;
        int minNeighbor = std::min(left, right);
        int need = std::max(0, nums[i] - minNeighbor + 1);
        if (i % 2 == 0) {
            evenValley += need;
        } else {
            oddValley += need;
        }
    }
    return std::min(evenValley, oddValley);
}

