    for (size_t i = 1; i <= text1.size(); ++i) {
        for (size_t j = 1; j <= text2.size(); ++j) {
            if (text1[i - 1] == text2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
