int longestDecomposition(const std::string& text) {
    int n = static_cast<int>(text.size());
    int left = 0, right = n - 1;
    int count = 0;
    while (left < right) {
        bool matched = false;
        for (int len = 1; left + len - 1 < right; ++len) {
            if (text.compare(left, len, text, right - len + 1, len) == 0) {
                count += 2;
                left += len;
                right -= len;
                matched = true;
                break;
            }
        }
        if (!matched) {
            ++count;
            return count;
        }
    }
    if (left == right) ++count;
    return count;
}

bool btreeGameWinningMove(TreeNode* root, int n, int x) {
    TreeNode* target = nullptr;
    function<void(TreeNode*)> findTarget = [&](TreeNode* node) {
        if (!node) return;
        if (node->val == x) { target = node; return; }
        findTarget(node->left);
        findTarget(node->right);
    };
    findTarget(root);
    function<int(TreeNode*)> countSize = [&](TreeNode* node) -> int {
        if (!node) return 0;
        return 1 + countSize(node->left) + countSize(node->right);
    };
    int leftCount = countSize(target->left);
    int rightCount = countSize(target->right);
    int parentCount = n - leftCount - rightCount - 1;
    double half = n / 2.0;
    return leftCount > half || rightCount > half || parentCount > half;
}

