struct SnapshotArrayObj {
    int currentId;
    std::vector<std::vector<std::pair<int, int>>> snapshots;

    SnapshotArrayObj(int length) : currentId(0), snapshots(length) {}

    void set(int index, int val) {
        snapshots[index].push_back({currentId, val});
    }

    int snap() {
        ++currentId;
        return currentId - 1;
    }

    int get(int index, int snap_id) {
        const auto& values = snapshots[index];
        int left = 0;
        int right = static_cast<int>(values.size()) - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (values[mid].first <= snap_id) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return right >= 0 ? values[right].second : 0;
    }
};

SnapshotArrayObj SnapshotArray(int length) {
    return SnapshotArrayObj(length);
}

