int maxRepOpt1(const std::string& text) {
    int n = static_cast<int>(text.size());
    if (n == 0) return 0;
    std::unordered_map<char, int> total;
    for (char c : text) total[c]++;

    std::vector<int> run_len;
    std::vector<char> run_char;
    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && text[j] == text[i]) ++j;
        run_len.push_back(j - i);
        run_char.push_back(text[i]);
        i = j;
    }

    int ans = 0;
    int m = static_cast<int>(run_len.size());
    for (int idx = 0; idx < m; ++idx) {
        char c = run_char[idx];
        int len = run_len[idx];
        ans = std::max(ans, std::min(len + 1, total[c]));
        if (idx + 2 < m && run_char[idx] == run_char[idx + 2] && run_len[idx + 1] == 1) {
            int combined = run_len[idx] + run_len[idx + 2];
            if (total[c] > combined) combined += 1;
            ans = std::max(ans, combined);
        }
    }
    return ans;
}

