    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());
    int maxSideLength = std::min(rows, cols);
    int maxArea = 0;

    for (int sideLength = 1; sideLength <= maxSideLength; ++sideLength) {
        for (int i = 0; i <= rows - sideLength; ++i) {
            for (int j = 0; j <= cols - sideLength; ++j) {
                if (hasAllOnesOnBorder(grid, i, j, sideLength)) {
                    maxArea = std::max(maxArea, sideLength * sideLength);
                }
            }
        }
    }

    return maxArea;
}

