std::vector<std::string> invalidTransactions(const std::vector<std::string>& transactions) {
    std::vector<std::string> result;
    std::unordered_map<std::string, std::vector<TransactionInfo>> transactionMap;
    for (size_t i = 0; i < transactions.size(); ++i) {
        const std::string& t = transactions[i];
        size_t p1 = t.find(',');
        std::string name = t.substr(0, p1);
        size_t p2 = t.find(',', p1 + 1);
        int time = std::stoi(t.substr(p1 + 1, p2 - p1 - 1));
        size_t p3 = t.find(',', p2 + 1);
        int amount = std::stoi(t.substr(p2 + 1, p3 - p2 - 1));
        std::string city = t.substr(p3 + 1);
        transactionMap[name].push_back({time, amount, city, static_cast<int>(i)});
    }
    for (auto& pair : transactionMap) {
        const std::vector<TransactionInfo>& vec = pair.second;
        for (size_t i = 0; i < vec.size(); ++i) {
            const TransactionInfo& ti = vec[i];
            if (ti.amount > 1000) {
                result.push_back(transactions[ti.index]);
            }
            for (size_t j = 0; j < vec.size(); ++j) {
                if (i != j) {
                    const TransactionInfo& tj = vec[j];
                    if (std::abs(ti.time - tj.time) <= 60 && ti.city != tj.city) {
                        if (!contains(result, transactions[ti.index])) {
                            result.push_back(transactions[ti.index]);
                        }
                        if (!contains(result, transactions[tj.index])) {
                            result.push_back(transactions[tj.index]);
