int maxDistance(std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    std::vector<std::array<int, 2>> directions = {std::array<int, 2>{-1, 0}, std::array<int, 2>{1, 0}, std::array<int, 2>{0, -1}, std::array<int, 2>{0, 1}};
    std::queue<std::array<int, 3>> queue;
    bool hasWater = false;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                queue.push({i, j, 0});
            } else {
                hasWater = true;
            }
        }
    }

    if (queue.empty() || !hasWater) {
        return -1;
    }

    int maxDistance = 0;

    while (!queue.empty()) {
        std::array<int, 3> current = queue.front();
        queue.pop();
        int x = current[0];
        int y = current[1];
        int distance = current[2];
        maxDistance = std::max(maxDistance, distance);
        for (const auto& dir : directions) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] == 0) {
                grid[nx][ny] = -1;
                queue.push({nx, ny, distance + 1});
            }
        }
    }

    return maxDistance;
}

