bool isPaliPossible(const std::string& substring, int k) {
    std::unordered_map<char, int> charCount;
    for (char ch : substring) {
        if (charCount.find(ch) == charCount.end()) charCount[ch] = 0;
        charCount[ch]++;
    }
    int oddCount = 0;
    for (const auto& pair : charCount) {
        if (pair.second % 2 != 0) oddCount++;
    }
    // minimum replacements needed = oddCount / 2 (integer division)
    return oddCount / 2 <= k;
}

std::vector<bool> canMakePali(const std::string& s, const std::vector<std::vector<int>>& queries) {
    std::vector<bool> result;
    for (const auto& query : queries) {
        int left = query[0];
        int right = query[1];
        int k = query[2];
        std::string substring = s.substr(left, right - left + 1);
        result.push_back(isPaliPossible(substring, k));
    }
    return result;
}

