int numPrimeArrangements(int n) {
    auto isPrime = [](int num) -> bool {
        if (num <= 1) return false;
        for (int i = 2; i * i <= num; ++i) {
            if (num % i == 0) return false;
        }
        return true;
    };
    int primeCount = 0;
    for (int i = 1; i <= n; ++i) {
        if (isPrime(i)) ++primeCount;
    }
    const int64_t MOD = 1000000007LL;
    int64_t primePermutations = 1;
    int64_t nonPrimePermutations = 1;
    for (int i = 1; i <= primeCount; ++i) {
        primePermutations = (primePermutations * i) % MOD;
    }
    for (int i = 1; i <= n - primeCount; ++i) {
        nonPrimePermutations = (nonPrimePermutations * i) % MOD;
    }
    return static_cast<int>((primePermutations * nonPrimePermutations) % MOD);
}

