std::vector<int> findNumOfValidWords(const std::vector<std::string>& words, const std::vector<std::string>& puzzles) {
    std::vector<int> result(puzzles.size(), 0);
    std::unordered_map<int, int> wordMap;
    for (const std::string& word : words) {
        int bitmask = 0;
        for (char ch : word) {
            bitmask |= 1 << (ch - 'a');
        }
        ++wordMap[bitmask];
    }
    for (size_t i = 0; i < puzzles.size(); ++i) {
        int puzzleBitmask = 0;
        for (char ch : puzzles[i]) {
            puzzleBitmask |= 1 << (ch - 'a');
        }
        int submask = puzzleBitmask;
        int firstLetterMask = 1 << (puzzles[i][0] - 'a');
        while (submask > 0) {
            auto it = wordMap.find(submask);
            if (it != wordMap.end() && (submask & firstLetterMask) != 0) {
                result[i] += it->second;
            }
            submask = (submask - 1) & puzzleBitmask;
        }
    }
    return result;
}

