int distanceBetweenBusStops(const std::vector<int>& distance, int start, int destination) {
    if (start > destination) {
        std::swap(start, destination);
    }
    int clockwiseDistance = 0;
    for (int i = start; i < destination; ++i) {
        clockwiseDistance += distance[i];
    }
    int totalDistance = 0;
    for (size_t i = 0; i < distance.size(); ++i) {
        totalDistance += distance[i];
    }
    int counterclockwiseDistance = totalDistance - clockwiseDistance;
    return std::min(clockwiseDistance, counterclockwiseDistance);
}

