struct DinnerPlatesObj {
    int capacity;
    std::vector<std::vector<int>> stacks;
    std::priority_queue<int, std::vector<int>, std::greater<int>> available; // min-heap, lazy deletion

    DinnerPlatesObj(int cap) : capacity(cap) {}

    void push(int val) {
        while (!available.empty() && (available.top() >= (int)stacks.size() || (int)stacks[available.top()].size() >= capacity)) {
            available.pop();
        }
        if (available.empty()) {
            stacks.push_back(std::vector<int>{val});
            if (capacity > 1) available.push((int)stacks.size() - 1);
        } else {
            int idx = available.top();
            stacks[idx].push_back(val);
            if ((int)stacks[idx].size() >= capacity) available.pop();
        }
    }

    int pop() {
        while (!stacks.empty() && stacks.back().empty()) stacks.pop_back();
        if (stacks.empty()) return -1;
        return popAtStack((int)stacks.size() - 1);
    }

    int popAtStack(int index) {
        if (index < 0 || index >= (int)stacks.size() || stacks[index].empty()) return -1;
        bool wasFull = (int)stacks[index].size() == capacity;
        int val = stacks[index].back();
        stacks[index].pop_back();
        if (wasFull) available.push(index);
        while (!stacks.empty() && stacks.back().empty()) stacks.pop_back();
        return val;
    }
};

DinnerPlatesObj DinnerPlates(int capacity) {
    return DinnerPlatesObj(capacity);
}

