std::string reverseParentheses(const std::string& s) {
    std::vector<std::string> stack;
    stack.emplace_back();
    for (char ch : s) {
        if (ch == '(') {
            stack.emplace_back();
        } else if (ch == ')') {
            std::string cur = std::move(stack.back());
            stack.pop_back();
            std::reverse(cur.begin(), cur.end());
            stack.back() += cur;
        } else {
            stack.back().push_back(ch);
        }
    }
    return stack.back();
}

