int maximumSum(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    std::vector<int> forward(n), backward(n);
    int maxSum = arr[0];
    forward[0] = arr[0];
    for (int i = 1; i < n; ++i) {
        forward[i] = std::max(arr[i], forward[i - 1] + arr[i]);
        maxSum = std::max(maxSum, forward[i]);
    }
    backward[n - 1] = arr[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        backward[i] = std::max(arr[i], backward[i + 1] + arr[i]);
        maxSum = std::max(maxSum, backward[i]);
    }
    for (int i = 1; i < n - 1; ++i) {
        maxSum = std::max(maxSum, forward[i - 1] + backward[i + 1]);
    }
    return maxSum;
}

#include <bits/stdc++.h>

long long kConcatenationMaxSum(const std::vector<long long>& arr, long long k) {
    const long long MOD = 1000000007LL;
    long long total = 0;
    for (long long v : arr) total += v;

    long long maxSub = 0, cur = 0;
    for (long long v : arr) {
        cur = std::max(v, cur + v);
        maxSub = std::max(maxSub, cur);
    }

    long long maxPref = LLONG_MIN, pref = 0;
    for (long long v : arr) {
        pref += v;
        maxPref = std::max(maxPref, pref);
    }

    long long maxSuf = LLONG_MIN, suf = 0;
    for (auto it = arr.rbegin(); it != arr.rend(); ++it) {
        suf += *it;
        maxSuf = std::max(maxSuf, suf);
    }

    long long answer;
    if (k == 1) {
        answer = maxSub;
    } else {
        long long combined = maxSuf + maxPref;
        if (total > 0) {
            combined += (k - 2) * total;
        }
        answer = std::max(maxSub, combined);
    }

    answer %= MOD;
    if (answer < 0) answer += MOD;
    return answer;
}

