int makeArrayIncreasing(const std::vector<int>& arr1, const std::vector<int>& arr2) {
    std::vector<int> sorted2 = arr2;
    std::sort(sorted2.begin(), sorted2.end());
    sorted2.erase(std::unique(sorted2.begin(), sorted2.end()), sorted2.end());

    std::unordered_map<long long, int> dp;
    dp[LLONG_MIN] = 0;

    for (int a : arr1) {
        std::unordered_map<long long, int> ndp;
        for (const auto& entry : dp) {
            long long last = entry.first;
            int ops = entry.second;
            if (a > last) {
                auto it = ndp.find(a);
                if (it == ndp.end() || ops < it->second) ndp[a] = ops;
            }
            auto it = std::upper_bound(sorted2.begin(), sorted2.end(), static_cast<int>(last));
            if (it != sorted2.end()) {
                long long val = *it;
                int nops = ops + 1;
                auto it2 = ndp.find(val);
                if (it2 == ndp.end() || nops < it2->second) ndp[val] = nops;
            }
        }
        dp.swap(ndp);
        if (dp.empty()) return -1;
    }

    int ans = INT_MAX;
    for (const auto& p : dp) {
        ans = std::min(ans, p.second);
    }
    return ans == INT_MAX ? -1 : ans;
}

