std::vector<std::vector<int>> criticalConnections(int n, const std::vector<std::vector<int>>& connections) {
    std::vector<std::vector<int>> graph(n);
    for (const auto& edge : connections) {
        int u = edge[0];
        int v = edge[1];
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    std::vector<bool> visited(n, false);
    std::vector<int> low(n, INT_MAX);
    std::vector<int> disc(n, INT_MAX);
    std::vector<int> parent(n, -1);
    std::vector<std::vector<int>> critical;
    int time = 0;

    std::function<void(int)> dfs = [&](int u) {
        visited[u] = true;
        disc[u] = time;
        low[u] = time;
        ++time;

        for (int v : graph[u]) {
            if (!visited[v]) {
                parent[v] = u;
                dfs(v);
                low[u] = std::min(low[u], low[v]);
                if (low[v] > disc[u]) {
                    critical.push_back({u, v});
                }
            } else if (v != parent[u]) {
                low[u] = std::min(low[u], disc[v]);
            }
        }
    };

    dfs(0);
    return critical;
}

