long long nthUglyNumber(int n, int a, int b, int c) {
    auto gcd = [](long long x, long long y) {
        while (y) {
            long long t = x % y;
            x = y;
            y = t;
        }
        return x;
    };
    auto lcm = [&](long long x, long long y) {
        return x / gcd(x, y) * y;
    };
    long long ab = lcm(a, b);
    long long ac = lcm(a, c);
    long long bc = lcm(b, c);
    long long abc = lcm(ab, c);
    auto count = [&](long long x) {
        return x / a + x / b + x / c
               - x / ab - x / ac - x / bc
               + x / abc;
    };
    long long lo = 1, hi = 2000000000LL;
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (count(mid) >= n) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}

