std::string smallestStringWithSwaps(const std::string& s, const std::vector<std::vector<int>>& pairs) {
    int n = static_cast<int>(s.size());
    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;
    std::function<int(int)> find = [&](int x) -> int {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    };
    auto unite = [&](int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] < rank[rootY]) parent[rootX] = rootY;
            else if (rank[rootX] > rank[rootY]) parent[rootY] = rootX;
            else {
                parent[rootY] = rootX;
                ++rank[rootX];
            }
        }
    };
    for (const auto& p : pairs) unite(p[0], p[1]);
    std::unordered_map<int, std::vector<char>> groups;
    for (int i = 0; i < n; ++i) {
        int g = find(i);
        groups[g].push_back(s[i]);
    }
    for (auto& kv : groups) std::sort(kv.second.begin(), kv.second.end());
    std::unordered_map<int, size_t> idx;
    std::string result(n, ' ');
    for (int i = 0; i < n; ++i) {
        int g = find(i);
        size_t& pos = idx[g];
        result[i] = groups[g][pos++];
    }
    return result;
}

