struct Node {
    int value;
    std::vector<Node*> forward;
    Node(int v, int level) : value(v), forward(static_cast<std::size_t>(level), nullptr) {}
};

class Skiplist {
    int levels;
    int maxValue;
    Node* head;
public:
    Skiplist() {
        levels = 16;
        maxValue = 1 << 15;
        head = new Node(maxValue, levels);
    }
    int randomLevel() {
        int lvl = 1;
        while ((double)rand() / RAND_MAX < 0.5 && lvl < levels) lvl++;
        return lvl;
    }
    bool search(int target) {
        Node* curr = head;
        for (int i = levels - 1; i >= 0; i--) {
            while (curr->forward[i] && curr->forward[i]->value < target) curr = curr->forward[i];
        }
        return curr->forward[0] && curr->forward[0]->value == target;
    }
    void add(int num) {
        std::vector<Node*> update(levels, head);
        Node* curr = head;
        for (int i = levels - 1; i >= 0; i--) {
            while (curr->forward[i] && curr->forward[i]->value < num) curr = curr->forward[i];
            update[i] = curr;
        }
        Node* newNode = new Node(num, randomLevel());
        for (size_t i = 0; i < newNode->forward.size(); i++) {
            newNode->forward[i] = update[i]->forward[i];
            update[i]->forward[i] = newNode;
        }
    }
    bool erase(int num) {
        std::vector<Node*> update(levels, head);
        Node* curr = head;
        for (int i = levels - 1; i >= 0; i--) {
            while (curr->forward[i] && curr->forward[i]->value < num) curr = curr->forward[i];
            update[i] = curr;
        }
        if (curr->forward[0] && curr->forward[0]->value == num) {
            for (int i = 0; i < levels; i++) {
                if (update[i]->forward[i] && update[i]->forward[i]->value == num) {
                    update[i]->forward[i] = update[i]->forward[i]->forward[i];
                } else break;
            }
            return true;
        }
        return false;
    }
};

#include <bits/stdc++.h>
using namespace std;

vector<int> topo(vector<vector<int>>& adj, vector<int> indeg, int count) {
    queue<int> q;
    for (int i = 0; i < count; i++) if (indeg[i] == 0) q.push(i);
    vector<int> order;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        order.push_back(u);
        for (int v : adj[u]) {
            if (--indeg[v] == 0) q.push(v);
        }
    }
    if ((int)order.size() != count) return {};
    return order;
}

vector<int> sortItems(int n, int m, vector<int> group, vector<vector<int>>& beforeItems) {
    int nextGroupId = m;
    for (int i = 0; i < n; i++) {
        if (group[i] == -1) group[i] = nextGroupId++;
    }
    int totalGroups = nextGroupId;

    vector<vector<int>> itemAdj(n);
    vector<int> itemIndeg(n, 0);
    vector<vector<int>> groupAdj(totalGroups);
    vector<int> groupIndeg(totalGroups, 0);

    for (int i = 0; i < n; i++) {
        for (int b : beforeItems[i]) {
            itemAdj[b].push_back(i);
            itemIndeg[i]++;
            if (group[b] != group[i]) {
                groupAdj[group[b]].push_back(group[i]);
                groupIndeg[group[i]]++;
            }
        }
    }

    vector<int> itemOrder = topo(itemAdj, itemIndeg, n);
    if ((int)itemOrder.size() != n) return {};
    vector<int> groupOrder = topo(groupAdj, groupIndeg, totalGroups);
    if ((int)groupOrder.size() != totalGroups) return {};

    vector<vector<int>> itemsByGroup(totalGroups);
    for (int item : itemOrder) itemsByGroup[group[item]].push_back(item);

    vector<int> result;
    for (int g : groupOrder) {
        for (int item : itemsByGroup[g]) result.push_back(item);
    }
    return result;
}

bool isValid(int n, vector<int>& group, vector<vector<int>>& beforeItems, vector<int>& order) {
    if ((int)order.size() != n) return false;
    vector<int> pos(n);
    for (int i = 0; i < n; i++) pos[order[i]] = i;
    for (int i = 0; i < n; i++) {
        for (int b : beforeItems[i]) {
            if (pos[b] > pos[i]) return false;
        }
    }
    map<int, pair<int,int>> seen;
    for (int idx = 0; idx < n; idx++) {
        int g = group[order[idx]];
        if (g == -1) continue;
        if (!seen.count(g)) seen[g] = {idx, idx};
        else seen[g].second = idx;
    }
    for (auto& [g, range] : seen) {
        for (int idx = range.first; idx <= range.second; idx++) {
            if (group[order[idx]] != g) return false;
        }
    }
    return true;
}

int main() {
    {
        int n = 8, m = 2;
        vector<int> group = {-1,-1,1,0,0,1,0,-1};
        vector<vector<int>> before = {{},{6},{5},{6},{3,6},{},{},{}};
