int minimumMoves(std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    const int HORIZONTAL = 0;
    const int VERTICAL = 1;
    std::vector<std::vector<std::array<bool, 2>>> visited(n, std::vector<std::array<bool, 2>>(n, {false, false}));
    std::queue<std::tuple<int, int, int, int>> q;
    q.emplace(0, 0, HORIZONTAL, 0);
    visited[0][0][HORIZONTAL] = true;
    while (!q.empty()) {
        std::tuple<int, int, int, int> cur = q.front();
        q.pop();
        int r = std::get<0>(cur);
        int c = std::get<1>(cur);
        int dir = std::get<2>(cur);
        int steps = std::get<3>(cur);
        if (r == n - 1 && c == n - 2 && dir == HORIZONTAL) {
            return steps;
        }
        if (dir == HORIZONTAL) {
            if (c + 2 < n && grid[r][c + 2] == 0 && !visited[r][c + 1][HORIZONTAL]) {
                visited[r][c + 1][HORIZONTAL] = true;
                q.emplace(r, c + 1, HORIZONTAL, steps + 1);
            }
            if (r + 1 < n && grid[r + 1][c] == 0 && grid[r + 1][c + 1] == 0 && !visited[r + 1][c][HORIZONTAL]) {
                visited[r + 1][c][HORIZONTAL] = true;
                q.emplace(r + 1, c, HORIZONTAL, steps + 1);
            }
            if (r + 1 < n && grid[r + 1][c] == 0 && grid[r + 1][c + 1] == 0 && !visited[r][c][VERTICAL]) {
                visited[r][c][VERTICAL] = true;
                q.emplace(r, c, VERTICAL, steps + 1);
            }
        } else {
            if (r + 2 < n && grid[r + 2][c] == 0 && !visited[r + 1][c][VERTICAL]) {
                visited[r + 1][c][VERTICAL] = true;
                q.emplace(r + 1, c, VERTICAL, steps + 1);
            }
            if (c + 1 < n && grid[r][c + 1] == 0 && grid[r + 1][c + 1] == 0 && !visited[r][c + 1][VERTICAL]) {
                visited[r][c + 1][VERTICAL] = true;
                q.emplace(r, c + 1, VERTICAL, steps + 1);
            }
            if (c + 1 < n && grid[r][c + 1] == 0 && grid[r + 1][c + 1] == 0 && !visited[r][c][HORIZONTAL]) {
                visited[r][c][HORIZONTAL] = true;
                q.emplace(r, c, HORIZONTAL, steps + 1);
            }
        }
    }
    return -1;
}

