int longestSubsequence(const std::vector<int>& arr, int difference) {
    int maxLength = 0;
    std::unordered_map<int, int> sequenceLengths;
    for (size_t i = 0; i < arr.size(); ++i) {
        int previousElement = arr[i] - difference;
        int currentLength = (sequenceLengths.find(previousElement) != sequenceLengths.end() ? sequenceLengths[previousElement] : 0) + 1;
        sequenceLengths[arr[i]] = currentLength;
        maxLength = std::max(maxLength, currentLength);
    }
    return maxLength;
}

