int countVowelPermutation(int n) {
    const int MOD = 1000000007;
    std::vector<std::vector<int>> dp(5, std::vector<int>(n, 0));
    for (int i = 0; i < 5; ++i) {
        dp[i][0] = 1;
    }
    for (int i = 1; i < n; ++i) {
        dp[0][i] = (static_cast<long long>(dp[1][i - 1]) + dp[2][i - 1] + dp[4][i - 1]) % MOD;
        dp[1][i] = (static_cast<long long>(dp[0][i - 1]) + dp[2][i - 1]) % MOD;
        dp[2][i] = (static_cast<long long>(dp[1][i - 1]) + dp[3][i - 1]) % MOD;
        dp[3][i] = dp[2][i - 1] % MOD;
        dp[4][i] = (static_cast<long long>(dp[2][i - 1]) + dp[3][i - 1]) % MOD;
    }
    int total = 0;
    for (int i = 0; i < 5; ++i) {
        total = (total + dp[i][n - 1]) % MOD;
    }
    return total;
}

