bool checkStraightLine(const std::vector<std::vector<int>>& coordinates) {
    int x0 = coordinates[0][0];
    int y0 = coordinates[0][1];
    int x1 = coordinates[1][0];
    int y1 = coordinates[1][1];
    double slope = (x1 - x0 == 0) ? std::numeric_limits<double>::infinity()
                                 : static_cast<double>(y1 - y0) / static_cast<double>(x1 - x0);
    for (size_t i = 2; i < coordinates.size(); ++i) {
        int x = coordinates[i][0];
        int y = coordinates[i][1];
        double newSlope = (x - x0 == 0) ? std::numeric_limits<double>::infinity()
                                        : static_cast<double>(y - y0) / static_cast<double>(x - x0);
        if (newSlope != slope) {
            return false;
        }
    }
    return true;
}

