std::vector<int> circularPermutation(int n, int start) {
    int limit = 1 << n;
    std::vector<int> gray(limit);
    for (int i = 0; i < limit; ++i) {
        gray[i] = i ^ (i >> 1);
    }
    int idx = 0;
    while (idx < limit && gray[idx] != start) {
        ++idx;
    }
    std::vector<int> result;
    result.reserve(limit);
    for (int i = 0; i < limit; ++i) {
        result.push_back(gray[(idx + i) % limit]);
    }
    return result;
}

