int maxLength(const std::vector<std::string>& arr) {
    int maxLen = 0;
    std::function<void(int, const std::string&)> backtrack = [&](int start, const std::string& path) {
        if (isUnique(path)) {
            maxLen = std::max(maxLen, static_cast<int>(path.size()));
        }
        for (int i = start; i < static_cast<int>(arr.size()); ++i) {
            if (hasDuplicate(path + arr[i])) continue;
            backtrack(i + 1, path + arr[i]);
        }
    };
    backtrack(0, "");
    return maxLen;
}

