int balancedString(const std::string& s) {
    int n = static_cast<int>(s.length());
    int target = n / 4;
    auto idx = [](char c) -> int {
        if (c == 'Q') return 0;
        if (c == 'W') return 1;
        if (c == 'E') return 2;
        return 3; // 'R'
    };
    std::array<int, 4> total = {0, 0, 0, 0};
    for (char c : s) {
        ++total[idx(c)];
    }
    bool already = true;
    for (int i = 0; i < 4; ++i) {
        if (total[i] != target) {
            already = false;
            break;
        }
    }
    if (already) return 0;
    std::array<int, 4> window = {0, 0, 0, 0};
    auto condition = [&](const std::array<int,4>& w) -> bool {
        for (int i = 0; i < 4; ++i) {
            if (total[i] - w[i] > target) return false;
        }
        return true;
    };
    int left = 0;
    int minLen = n;
    for (int right = 0; right < n; ++right) {
        ++window[idx(s[right])];
        while (left <= right && condition(window)) {
            minLen = std::min(minLen, right - left + 1);
            --window[idx(s[left])];
            ++left;
        }
    }
    return minLen;
}

