struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

std::unordered_set<int> FindElements(TreeNode* root) {
    std::unordered_set<int> values;
    if (!root) return values;
    struct Item { TreeNode* node; int val; };
    std::vector<Item> stack;
    stack.push_back({root, 0});
    while (!stack.empty()) {
        Item cur = stack.back();
        stack.pop_back();
        TreeNode* node = cur.node;
        int val = cur.val;
        node->val = val;
        values.insert(val);
        if (node->left)  stack.push_back({node->left, 2 * val + 1});
        if (node->right) stack.push_back({node->right, 2 * val + 2});
    }
    return values;
}

