long long maxSumDivisibleByThree(const std::vector<int>& nums) {
    const long long NEG_INF = LLONG_MIN / 4;
    long long dp[3] = {0, NEG_INF, NEG_INF};

    for (size_t i = 0; i < nums.size(); ++i) {
        long long cur = nums[i];
        int mod = ((cur % 3) + 3) % 3;
        long long next[3] = {dp[0], dp[1], dp[2]};

        for (int r = 0; r < 3; ++r) {
            int newR = (r + mod) % 3;
            long long candidate = dp[r] + cur;
            if (candidate > next[newR]) {
                next[newR] = candidate;
            }
        }

        dp[0] = next[0];
        dp[1] = next[1];
        dp[2] = next[2];
    }

    return dp[0];
}

