int numWays(int steps, int arrLen) {
    const int MOD = 1000000007;
    int maxPos = std::min(arrLen - 1, steps);
    std::vector<int> dp(maxPos + 1, 0);
    dp[0] = 1;
    for (int step = 1; step <= steps; ++step) {
        std::vector<int> next(maxPos + 1, 0);
        for (int pos = 0; pos <= maxPos; ++pos) {
            int ways = dp[pos];
            if (pos > 0) {
                ways = (ways + dp[pos - 1]) % MOD;
            }
            if (pos < maxPos) {
                ways = (ways + dp[pos + 1]) % MOD;
            }
            next[pos] = ways;
        }
        dp = std::move(next);
    }
    return dp[0];
}

