struct State {
    int bx, by, px, py;
    bool operator==(const State& other) const {
        return bx == other.bx && by == other.by && px == other.px && py == other.py;
    }
};

struct StateHash {
    std::size_t operator()(const State& s) const noexcept {
        return ((std::size_t)s.bx * 31 + s.by) * 31 * 31 + ((std::size_t)s.px * 31 + s.py);
    }
};

static bool canReach(int sx, int sy, int tx, int ty, int bx, int by, const std::vector<std::string>& grid) {
    if (sx == tx && sy == ty) return true;
    int m = grid.size(), n = grid[0].size();
    std::vector<std::vector<char>> vis(m, std::vector<char>(n, 0));
    std::queue<std::pair<int, int>> q;
    q.emplace(sx, sy);
    vis[sx][sy] = 1;
    const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (const auto& d : dirs) {
            int nx = x + d[0], ny = y + d[1];
            if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
            if (vis[nx][ny]) continue;
            if (grid[nx][ny] == '#') continue;
            if (nx == bx && ny == by) continue;
            if (nx == tx && ny == ty) return true;
            vis[nx][ny] = 1;
            q.emplace(nx, ny);
        }
    }
    return false;
}

int minPushBox(std::vector<std::string>& grid) {
    int m = grid.size(), n = grid[0].size();
    int sx = -1, sy = -1, bx = -1, by = -1, tx = -1, ty = -1;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'S') { sx = i; sy = j; }
            else if (grid[i][j] == 'B') { bx = i; by = j; }
            else if (grid[i][j] == 'T') { tx = i; ty = j; }
        }
    }
    if (bx == tx && by == ty) return 0;
    std::queue<std::pair<State, int>> q;
    State start{bx, by, sx, sy};
    q.emplace(start, 0);
    std::unordered_set<State, StateHash> visited;
    visited.insert(start);
    const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        State st = cur.first;
        int pushes = cur.second;
        if (st.bx == tx && st.by == ty) return pushes;
        for (const auto& d : dirs) {
            int nbx = st.bx + d[0];
            int nby = st.by + d[1];
            int reqPx = st.bx - d[0];
            int reqPy = st.by - d[1];
            if (nbx < 0 || nbx >= m || nby < 0 || nby >= n) continue;
            if (reqPx < 0 || reqPx >= m || reqPy < 0 || reqPy >= n) continue;
            if (grid[nbx][nby] == '#') continue;
            if (grid[reqPx][reqPy] == '#') continue;
            if (!canReach(st.px, st.py, reqPx, reqPy, st.bx, st.by, grid)) continue;
            State nxt{nbx, nby, st.bx, st.by};
            if (visited.find(nxt) == visited.end()) {
                visited.insert(nxt);
                q.emplace(nxt, pushes + 1);
            }
        }
    }
    return -1;
}

