std::string tictactoe(const std::vector<std::vector<int>>& moves) {
    const int n = 3;
    int rows[3] = {0, 0, 0};
    int cols[3] = {0, 0, 0};
    int diag = 0, antiDiag = 0;
    for (size_t i = 0; i < moves.size(); ++i) {
        int r = moves[i][0];
        int c = moves[i][1];
        int player = (i % 2 == 0) ? 1 : -1;
        rows[r] += player;
        cols[c] += player;
        if (r == c) diag += player;
        if (r + c == n - 1) antiDiag += player;
        if (std::abs(rows[r]) == n ||
            std::abs(cols[c]) == n ||
            std::abs(diag) == n ||
            std::abs(antiDiag) == n) {
            return player == 1 ? "A" : "B";
        }
    }
    return moves.size() == static_cast<size_t>(n * n) ? "Draw" : "Pending";
}

