int palindromePartition(const std::string& s, int k) {
    int n = static_cast<int>(s.size());
    const int INF = 1000000000;

    std::vector<std::vector<int>> cost(n, std::vector<int>(n, 0));
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            if (len == 2) {
                cost[i][j] = (s[i] == s[j]) ? 0 : 1;
            } else {
                cost[i][j] = cost[i + 1][j - 1] + ((s[i] == s[j]) ? 0 : 1);
            }
        }
    }

    std::vector<std::vector<int>> dp(k + 1, std::vector<int>(n + 1, INF));
    dp[0][0] = 0;

    for (int p = 1; p <= k; ++p) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < i; ++j) {
                int cand = dp[p - 1][j] + cost[j][i - 1];
                if (cand < dp[p][i]) dp[p][i] = cand;
            }
        }
    }

    return dp[k][n];
}

