long long subtractProductAndSum(long long n) {
    long long product = 1;
    long long sum = 0;
    long long num = std::llabs(n);
    if (num == 0) return 0;
    while (num > 0) {
        long long digit = num % 10;
        product *= digit;
        sum += digit;
        num /= 10;
    }
    return product - sum;
}

