int smallestDivisor(const std::vector<int>& nums, int threshold) {
    int left = 1;
    int right = *std::max_element(nums.begin(), nums.end());
    while (left < right) {
        int mid = left + (right - left) / 2;
        int total = 0;
        for (int num : nums) {
            total += (num + mid - 1) / mid;
            if (total > threshold) break;
        }
        if (total <= threshold) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return left;
}

