class CombinationIterator {
    // FIXED: original returned a struct of std::function lambdas that captured
    // `allCombos` and `pos` (local stack variables of the free function) BY
    // REFERENCE via `[&, pos]`/`[&]`. Once the function returned, those locals
    // were destroyed, leaving both closures with dangling references - calling
    // next()/hasNext() afterward was undefined behavior (confirmed: crashed with
    // std::length_error / heap corruption). Fixed by storing the data as proper
    // member variables that live as long as the object does.
    std::vector<std::string> allCombos;
    size_t pos = 0;
public:
    CombinationIterator(const std::string& characters, int combinationLength) {
        std::string combo;
        int n = static_cast<int>(characters.size());
        std::function<void(int)> backtrack = [&](int start) {
            if (static_cast<int>(combo.size()) == combinationLength) {
                allCombos.push_back(combo);
                return;
            }
            for (int i = start; i < n; ++i) {
                combo.push_back(characters[i]);
                backtrack(i + 1);
                combo.pop_back();
            }
        };
        backtrack(0);
    }
    std::string next() {
        return allCombos[pos++];
    }
    bool hasNext() {
        return pos < allCombos.size();
    }
};

