long long minFallingPathSum(const std::vector<std::vector<int>>& grid) {
    std::size_t n = grid.size();
    if (n == 0) return 0;
    std::vector<long long> prev(grid[0].begin(), grid[0].end());

    for (std::size_t i = 1; i < n; ++i) {
        long long min1 = std::numeric_limits<long long>::max();
        long long min2 = std::numeric_limits<long long>::max();
        std::size_t idxMin1 = static_cast<std::size_t>(-1);
        for (std::size_t j = 0; j < n; ++j) {
            long long val = prev[j];
            if (val < min1) {
                min2 = min1;
                min1 = val;
                idxMin1 = j;
            } else if (val < min2) {
                min2 = val;
            }
        }

        std::vector<long long> cur(n);
        for (std::size_t j = 0; j < n; ++j) {
            long long bestPrev = (j == idxMin1) ? min2 : min1;
            cur[j] = static_cast<long long>(grid[i][j]) + bestPrev;
        }
        prev = std::move(cur);
    }

    return *std::min_element(prev.begin(), prev.end());
}

