int minFlips(const std::vector<std::vector<int>>& mat) {
    int m = static_cast<int>(mat.size());
    int n = static_cast<int>(mat[0].size());

    int start = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] == 1) {
                start |= 1 << (i * n + j);
            }
        }
    }

    std::vector<int> flipMasks;
    flipMasks.reserve(m * n);
    const int dirs[5][2] = {{0,0},{1,0},{-1,0},{0,1},{0,-1}};
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int mask = 0;
            for (const auto& d : dirs) {
                int x = i + d[0];
                int y = j + d[1];
                if (x >= 0 && x < m && y >= 0 && y < n) {
                    mask |= 1 << (x * n + y);
                }
            }
            flipMasks.push_back(mask);
        }
    }

    std::queue<int> q;
    q.push(start);
    std::unordered_map<int, int> dist;
    dist[start] = 0;

    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        int steps = dist[cur];
        if (cur == 0) {
            return steps;
        }
        for (int mask : flipMasks) {
            int nxt = cur ^ mask;
            if (dist.find(nxt) == dist.end()) {
                dist[nxt] = steps + 1;
                q.push(nxt);
            }
        }
    }
    return -1;
}

