int maxSideLength(const std::vector<std::vector<int>>& mat, int threshold) {
    int rows = static_cast<int>(mat.size());
    int cols = static_cast<int>(mat[0].size());
    std::vector<std::vector<long long>> prefix(rows + 1, std::vector<long long>(cols + 1, 0));
    for (int r = 1; r <= rows; ++r) {
        for (int c = 1; c <= cols; ++c) {
            prefix[r][c] = mat[r - 1][c - 1] + prefix[r - 1][c] + prefix[r][c - 1] - prefix[r - 1][c - 1];
        }
    }
    auto canFit = [&](int size) -> bool {
        for (int r = 0; r + size <= rows; ++r) {
            for (int c = 0; c + size <= cols; ++c) {
                long long sum = prefix[r + size][c + size] - prefix[r][c + size] - prefix[r + size][c] + prefix[r][c];
                if (sum <= threshold) return true;
            }
        }
        return false;
    };
    int low = 0, high = std::min(rows, cols);
    while (low < high) {
        int mid = (low + high + 1) / 2;
        if (canFit(mid)) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

