int shortestPath(const std::vector<std::vector<int>>& grid, int k) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());

    if (m == 1 && n == 1) return 0;
    if (k >= m + n - 2) return m + n - 2;

    const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    std::vector<std::vector<int>> visited(m, std::vector<int>(n, -1));
    visited[0][0] = k;

    struct State { int r; int c; int left; };
    std::vector<State> queue;
    queue.push_back({0, 0, k});
    size_t head = 0;
    int steps = 0;

    while (head < queue.size()) {
        int levelSize = static_cast<int>(queue.size() - head);
        ++steps;
        for (int i = 0; i < levelSize; ++i) {
            State cur = queue[head++];
            for (int d = 0; d < 4; ++d) {
                int nr = cur.r + dirs[d][0];
                int nc = cur.c + dirs[d][1];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                if (nr == m - 1 && nc == n - 1) return steps;
                int cell = grid[nr][nc];
                int newLeft = (cell == 1) ? cur.left - 1 : cur.left;
                if (newLeft < 0) continue;
                if (visited[nr][nc] >= newLeft) continue;
                visited[nr][nc] = newLeft;
                queue.push_back({nr, nc, newLeft});
            }
        }
    }

    return -1;
}

