bool canDivideArray(const std::vector<int>& nums, int k) {
    if (nums.size() % k != 0) return false;
    std::unordered_map<int, int> freq;
    for (int num : nums) {
        ++freq[num];
    }
    std::vector<int> sorted;
    sorted.reserve(freq.size());
    for (const auto& p : freq) {
        sorted.push_back(p.first);
    }
    std::sort(sorted.begin(), sorted.end());
    for (int start : sorted) {
        int count = freq[start];
        if (count > 0) {
            for (int i = 0; i < k; ++i) {
                int cur = start + i;
                int curCount = freq.count(cur) ? freq[cur] : 0;
                if (curCount < count) return false;
                freq[cur] = curCount - count;
            }
        }
    }
    return true;
}

