int maxFreq(const std::string& s, int maxLetters, int minSize, int maxSize) {
    if (s.length() < static_cast<size_t>(minSize)) return 0;
    std::unordered_map<std::string, int> freqMap;
    std::vector<int> charCount(26, 0);
    int distinct = 0;
    int best = 0;
    for (int i = 0; i < minSize; ++i) {
        int idx = s[i] - 'a';
        if (charCount[idx] == 0) ++distinct;
        ++charCount[idx];
    }
    for (size_t start = 0; start + minSize <= s.length(); ++start) {
        if (distinct <= maxLetters) {
            std::string sub = s.substr(start, minSize);
            int newCount = freqMap[sub] + 1;
            freqMap[sub] = newCount;
            if (newCount > best) best = newCount;
        }
        if (start + minSize < s.length()) {
            int leftIdx = s[start] - 'a';
            int rightIdx = s[start + minSize] - 'a';
            --charCount[leftIdx];
            if (charCount[leftIdx] == 0) --distinct;
            if (charCount[rightIdx] == 0) ++distinct;
            ++charCount[rightIdx];
        }
    }
    return best;
}

