int findBestValue(std::vector<int>& arr, int target) {
    std::sort(arr.begin(), arr.end());
    int n = arr.size();
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + arr[i];
    int low = 0, high = arr.back();
    auto calcSum = [&](int v) -> long long {
        int idx = std::upper_bound(arr.begin(), arr.end(), v) - arr.begin();
        return pref[idx] + static_cast<long long>(n - idx) * v;
    };
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (calcSum(mid) < target) low = mid + 1;
        else high = mid;
    }
    int best = low;
    long long bestDiff = std::llabs(calcSum(best) - target);
    if (low > 0) {
        long long diffPrev = std::llabs(calcSum(low - 1) - target);
        if (diffPrev < bestDiff || (diffPrev == bestDiff && low - 1 < best)) {
            best = low - 1;
            bestDiff = diffPrev;
        }
    }
    return best;
}

