std::vector<int> maxScorePaths(const std::vector<std::string>& board) {
    const int MOD = 1000000007;
    int n = board.size();
    const long long NEG = LLONG_MIN / 4;
    std::vector<std::vector<long long>> dp(n, std::vector<long long>(n, NEG));
    std::vector<std::vector<int>> ways(n, std::vector<int>(n, 0));
    for (int i = n - 1; i >= 0; --i) {
        for (int j = n - 1; j >= 0; --j) {
            char c = board[i][j];
            if (c == 'X') continue;
            if (c == 'S') {
                dp[i][j] = 0;
                ways[i][j] = 1;
                continue;
            }
            long long bestPrev = NEG;
            int cnt = 0;
            const int di[3] = {1, 0, 1};
            const int dj[3] = {0, 1, 1};
            for (int k = 0; k < 3; ++k) {
                int ni = i + di[k];
                int nj = j + dj[k];
                if (ni >= n || nj >= n) continue;
                if (dp[ni][nj] == NEG) continue;
                if (dp[ni][nj] > bestPrev) {
                    bestPrev = dp[ni][nj];
                    cnt = ways[ni][nj];
                } else if (dp[ni][nj] == bestPrev) {
                    cnt += ways[ni][nj];
                    if (cnt >= MOD) cnt -= MOD;
                }
            }
            if (bestPrev == NEG) continue;
            long long add = 0;
            if (c >= '1' && c <= '9') add = c - '0';
            dp[i][j] = bestPrev + add;
            ways[i][j] = cnt;
        }
    }
    if (dp[0][0] == NEG) return {0, 0};
    return {static_cast<int>(dp[0][0]), ways[0][0]};
}

