int maxCandies(std::vector<int>& status, std::vector<int>& candies,
               std::vector<std::vector<int>>& keys,
               std::vector<std::vector<int>>& containedBoxes,
               std::vector<int>& initialBoxes) {
    int n = status.size();
    std::vector<char> haveBox(n, 0), haveKey(n, 0), opened(n, 0);
    std::queue<int> q;
    for (int b : initialBoxes) {
        if (!haveBox[b]) {
            haveBox[b] = 1;
            if (status[b] == 1) {
                q.push(b);
            }
        }
    }
    long long total = 0;
    while (!q.empty()) {
        int i = q.front();
        q.pop();
        if (opened[i]) continue;
        opened[i] = 1;
        total += candies[i];
        for (int k : keys[i]) {
            if (!haveKey[k]) {
                haveKey[k] = 1;
                if (haveBox[k] && !opened[k]) {
                    q.push(k);
                }
            }
        }
        for (int b : containedBoxes[i]) {
            if (!haveBox[b]) {
                haveBox[b] = 1;
                if (haveKey[b] || status[b] == 1) {
                    if (!opened[b]) q.push(b);
                }
            }
        }
    }
    return static_cast<int>(total);
}

