    while (i >= 0) {
        int num;
        if (s[i] == '#') {
            num = (s[i - 2] - '0') * 10 + (s[i - 1] - '0');
            i -= 3;
        } else {
            num = s[i] - '0';
            i -= 1;
        }
        char letter = static_cast<char>('a' + num - 1);
        decoded.push_back(letter);
    }
    std::reverse(decoded.begin(), decoded.end());
    return std::string(decoded.begin(), decoded.end());
}

