bool canReach(const std::vector<int>& arr, int start) {
    std::size_t n = arr.size();
    std::vector<bool> visited(n, false);
    std::queue<int> queue;

    queue.push(start);
    visited[start] = true;

    while (!queue.empty()) {
        int idx = queue.front();
        queue.pop();

        if (arr[idx] == 0) return true;

        int jump = arr[idx];
        int forward = idx + jump;
        int backward = idx - jump;

        if (forward < static_cast<int>(n) && !visited[forward]) {
            visited[forward] = true;
            queue.push(forward);
        }
        if (backward >= 0 && !visited[backward]) {
            visited[backward] = true;
            queue.push(backward);
        }
    }

    return false;
}

