    // collect unique letters
    std::unordered_set<char> uniq;
    for (const auto& w : words) for (char c : w) uniq.insert(c);
    for (char c : result) uniq.insert(c);
    if (uniq.size() > 10) return false;

    // reverse words for column-wise processing
    std::vector<std::string> revWords;
    revWords.reserve(words.size());
    for (const auto& w : words) {
        revWords.emplace_back(std::string(w.rbegin(), w.rend()));
    }
    std::string revResult(result.rbegin(), result.rend());

    // lengths for leading zero checks
    std::vector<int> wordLen;
    for (const auto& w : words) wordLen.push_back((int)w.size());
    int resultLen = (int)result.size();

    int maxLen = resultLen;
    for (int l : wordLen) if (l > maxLen) maxLen = l;

    std::function<bool(int,int,int,int)> dfs = [&](int col, int idx, int carry, int sum) -> bool {
        if (col == maxLen) {
            return carry == 0;
        }
        if (idx < (int)revWords.size()) {
            if (col >= (int)revWords[idx].size())
                return dfs(col, idx + 1, carry, sum);
            char ch = revWords[idx][col];
            int ci = ch - 'A';
            if (assign[ci] != -1) {
                return dfs(col, idx + 1, carry, sum + assign[ci]);
            } else {
                for (int d = 0; d <= 9; ++d) {
                    if (used[d]) continue;
                    // leading zero check
                    if (d == 0 && col == wordLen[idx] - 1 && wordLen[idx] > 1) continue;
                    assign[ci] = d;
                    used[d] = true;
                    if (dfs(col, idx + 1, carry, sum + d)) return true;
                    assign[ci] = -1;
                    used[d] = false;
                }
                return false;
            }
        } else {
            // handle result character
            if (col >= (int)revResult.size()) {
                // no result character, digit must be zero
                if ((sum + carry) % 10 != 0) return false;
                return dfs(col + 1, 0, (sum + carry) / 10, 0);
            }
            char ch = revResult[col];
            int ci = ch - 'A';
            int total = sum + carry;
            int digit = total % 10;
            int newCarry = total / 10;
            if (assign[ci] != -1) {
                if (assign[ci] != digit) return false;
                return dfs(col + 1, 0, newCarry, 0);
            } else {
                if (used[digit]) return false;
                if (digit == 0 && col == resultLen - 1 && resultLen > 1) return false;
                assign[ci] = digit;
                used[digit] = true;
                if (dfs(col + 1, 0, newCarry, 0)) return true;
                assign[ci] = -1;
                used[digit] = false;
                return false;
            }
        }
    };

    return dfs(0, 0, 0, 0);
}

