std::vector<std::string> getWatchedVideosByFriends(const std::vector<std::vector<std::string>>& watchedVideos,
                                                   const std::vector<std::vector<int>>& friends,
                                                   int id,
                                                   int level) {
    int n = static_cast<int>(watchedVideos.size());
    std::vector<bool> visited(n, false);
    std::deque<int> queue;

    visited[id] = true;
    queue.push_back(id);
    int currentLevel = 0;

    while (!queue.empty() && currentLevel < level) {
        int size = static_cast<int>(queue.size());
        for (int i = 0; i < size; ++i) {
            int person = queue.front();
            queue.pop_front();
            for (int nb : friends[person]) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.push_back(nb);
                }
            }
        }
        ++currentLevel;
    }

    std::unordered_map<std::string, int> freq;
    for (int person : queue) {
        for (const std::string& video : watchedVideos[person]) {
            ++freq[video];
        }
    }

    std::vector<std::string> result;
    result.reserve(freq.size());
    for (const auto& p : freq) {
        result.push_back(p.first);
    }

    std::sort(result.begin(), result.end(),
              [&freq](const std::string& a, const std::string& b) {
                  if (freq[a] != freq[b]) return freq[a] < freq[b];
                  return a < b;
              });

    return result;
}

