int minInsertions(const std::string& s) {
    int n = static_cast<int>(s.size());
    if (n == 0) return 0;

    std::string rev = s;
    std::reverse(rev.begin(), rev.end());

    std::vector<int> dpPrev(n + 1, 0);
    std::vector<int> dpCurr(n + 1, 0);

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (s[i - 1] == rev[j - 1]) {
                dpCurr[j] = dpPrev[j - 1] + 1;
            } else {
                dpCurr[j] = std::max(dpPrev[j], dpCurr[j - 1]);
            }
        }
        std::swap(dpPrev, dpCurr);
    }

    int lpsLength = dpPrev[n];
    return n - lpsLength;
}

