#include <string>
#include <vector>
#include <unordered_set>

int distinctEchoSubstrings(const std::string& text) {
    const int n = static_cast<int>(text.size());
    const long long base = 91138233LL;
    const long long mod1 = 1000000007LL;
    const long long mod2 = 1000000009LL;

    std::vector<long long> pref1(n + 1, 0);
    std::vector<long long> pref2(n + 1, 0);
    std::vector<long long> pow1(n + 1, 1);
    std::vector<long long> pow2(n + 1, 1);

    for (int i = 0; i < n; ++i) {
        int code = static_cast<int>(text[i]);
        pref1[i + 1] = (pref1[i] * base + code) % mod1;
        pref2[i + 1] = (pref2[i] * base + code) % mod2;
        pow1[i + 1] = (pow1[i] * base) % mod1;
        pow2[i + 1] = (pow2[i] * base) % mod2;
    }

    auto getHash = [&](int l, int r) -> std::pair<long long, long long> {
        long long h1 = (pref1[r] - (pref1[l] * pow1[r - l]) % mod1 + mod1) % mod1;
        long long h2 = (pref2[r] - (pref2[l] * pow2[r - l]) % mod2 + mod2) % mod2;
        return {h1, h2};
    };

    std::unordered_set<std::string> seen;

    for (int len = 2; len <= n; len += 2) {
        int half = len >> 1;
        for (int i = 0; i + len <= n; ++i) {
            auto left = getHash(i, i + half);
            auto right = getHash(i + half, i + len);
            if (left.first == right.first && left.second == right.second) {
                auto whole = getHash(i, i + len);
                seen.insert(std::to_string(whole.first) + "#" + std::to_string(whole.second));
            }
        }
    }

    return static_cast<int>(seen.size());
}

