std::vector<std::vector<int>> matrixBlockSum(const std::vector<std::vector<int>>& mat, int k) {
    int rows = static_cast<int>(mat.size());
    int cols = static_cast<int>(mat[0].size());

    std::vector<std::vector<int>> prefix(rows + 1, std::vector<int>(cols + 1, 0));
    for (int i = 0; i < rows; ++i) {
        int rowSum = 0;
        for (int j = 0; j < cols; ++j) {
            rowSum += mat[i][j];
            prefix[i + 1][j + 1] = prefix[i][j + 1] + rowSum;
        }
    }

    std::vector<std::vector<int>> answer(rows, std::vector<int>(cols, 0));

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            int r1 = std::max(0, i - k);
            int c1 = std::max(0, j - k);
            int r2 = std::min(rows - 1, i + k);
            int c2 = std::min(cols - 1, j + k);

            answer[i][j] = 
                prefix[r2 + 1][c2 + 1] -
                prefix[r1][c2 + 1] -
                prefix[r2 + 1][c1] +
                prefix[r1][c1];
        }
    }

    return answer;
}

