long long minFlips(long long a, long long b, long long c) {
    long long flips = 0;
    while (a > 0 || b > 0 || c > 0) {
        long long bitA = a & 1LL;
        long long bitB = b & 1LL;
        long long bitC = c & 1LL;
        if (bitC == 0) {
            flips += bitA + bitB;
        } else {
            if (bitA == 0 && bitB == 0) flips += 1;
        }
        a >>= 1;
        b >>= 1;
        c >>= 1;
    }
    return flips;
}

