int minimumDistance(const std::string& word) {
    auto dist = [&](int a, int b) {
        int ra = a / 6, ca = a % 6;
        int rb = b / 6, cb = b % 6;
        return std::abs(ra - rb) + std::abs(ca - cb);
    };
    int n = static_cast<int>(word.size());
    if (n <= 1) return 0;
    const int INF = 1e9;
    std::vector<int> dp(27, INF);
    dp[26] = 0; // other finger not placed yet
    for (int i = 1; i < n; ++i) {
        int cur = word[i] - 'A';
        int prev = word[i - 1] - 'A';
        std::vector<int> ndp(27, INF);
        for (int j = 0; j <= 26; ++j) {
            if (dp[j] == INF) continue;
            // use the finger that typed prev
            int costSame = dp[j] + dist(prev, cur);
            ndp[j] = std::min(ndp[j], costSame);
            // use the other finger (at j)
            int move = (j == 26) ? 0 : dist(j, cur);
            int costOther = dp[j] + move;
            ndp[prev] = std::min(ndp[prev], costOther);
        }
        dp.swap(ndp);
    }
    int ans = INF;
    for (int v : dp) ans = std::min(ans, v);
    return ans;
}

