int makeConnected(int n, const std::vector<std::vector<int>>& connections) {
    if (connections.size() < static_cast<size_t>(n - 1)) return -1;

    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return false;
        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            ++rank[ra];
        }
        return true;
    };

    int components = n;
    for (const auto& conn : connections) {
        int a = conn[0];
        int b = conn[1];
        if (unite(a, b)) --components;
    }

    return components - 1;
}

