int maxArrayValueAfterReverse(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n < 2) return 0;
    long long base = 0;
    for (int i = 0; i < n - 1; ++i) {
        base += std::llabs(static_cast<long long>(nums[i]) - nums[i + 1]);
    }
    long long bestGain = 0;
    for (int l = 0; l < n; ++l) {
        for (int r = l; r < n; ++r) {
            long long gain = 0;
            if (l > 0) {
                long long old = std::llabs(static_cast<long long>(nums[l - 1]) - nums[l]);
                long long neu = std::llabs(static_cast<long long>(nums[l - 1]) - nums[r]);
                gain += neu - old;
            }
            if (r < n - 1) {
                long long old = std::llabs(static_cast<long long>(nums[r]) - nums[r + 1]);
                long long neu = std::llabs(static_cast<long long>(nums[l]) - nums[r + 1]);
                gain += neu - old;
            }
            if (gain > bestGain) bestGain = gain;
        }
    }
    return static_cast<int>(base + bestGain);
}

