int minTaps(int n, const std::vector<int>& ranges) {
    if (n == 0) return 0;
    std::vector<int> maxRight(n + 1, 0);
    for (int i = 0; i <= n; ++i) {
        int left = std::max(0, i - ranges[i]);
        int right = std::min(n, i + ranges[i]);
        if (right > maxRight[left]) maxRight[left] = right;
    }
    int taps = 0;
    int currentEnd = 0;
    int farthest = 0;
    int pos = 0;
    while (currentEnd < n) {
        while (pos <= currentEnd) {
            if (maxRight[pos] > farthest) farthest = maxRight[pos];
            ++pos;
        }
        if (farthest <= currentEnd) return -1;
        ++taps;
        currentEnd = farthest;
    }
    return taps;
}

