std::vector<std::vector<int>> diagonalSort(std::vector<std::vector<int>>& mat) {
    int rows = static_cast<int>(mat.size());
    int cols = static_cast<int>(mat[0].size());

    auto sortDiagonal = [&](int r, int c) {
        int i = r, j = c;
        std::vector<int> elems;
        while (i < rows && j < cols) {
            elems.push_back(mat[i][j]);
            ++i;
            ++j;
        }
        std::sort(elems.begin(), elems.end());
        i = r;
        j = c;
        std::size_t idx = 0;
        while (i < rows && j < cols) {
            mat[i][j] = elems[idx++];
            ++i;
            ++j;
        }
    };

    for (int col = 0; col < cols; ++col) {
        sortDiagonal(0, col);
    }
    for (int row = 1; row < rows; ++row) {
        sortDiagonal(row, 0);
    }

    return mat;
}

