int findTheCity(int n, std::vector<std::vector<int>>& edges, int distanceThreshold) {
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<std::vector<long long>> dist(n, std::vector<long long>(n, INF));
    for (int i = 0; i < n; ++i) {
        dist[i][i] = 0;
    }
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int w = e[2];
        dist[u][v] = w;
        dist[v][u] = w;
    }
    for (int k = 0; k < n; ++k) {
        for (int i = 0; i < n; ++i) {
            if (dist[i][k] == INF) continue;
            for (int j = 0; j < n; ++j) {
                if (dist[k][j] == INF) continue;
                long long nd = dist[i][k] + dist[k][j];
                if (nd < dist[i][j]) {
                    dist[i][j] = nd;
                }
            }
        }
    }
    int answer = -1;
    int bestCount = n + 1;
    for (int i = 0; i < n; ++i) {
        int cnt = 0;
        for (int j = 0; j < n; ++j) {
            if (dist[i][j] <= distanceThreshold) {
                ++cnt;
            }
        }
        if (cnt < bestCount || (cnt == bestCount && i > answer)) {
            bestCount = cnt;
            answer = i;
        }
    }
    return answer;
}

