    sortedUnique.erase(std::unique(sortedUnique.begin(), sortedUnique.end()), sortedUnique.end());

    std::unordered_map<int, int> rankMap;
    rankMap.reserve(sortedUnique.size());
    for (size_t i = 0; i < sortedUnique.size(); ++i) {
        rankMap[sortedUnique[i]] = static_cast<int>(i) + 1;
