std::vector<int> kWeakestRows(const std::vector<std::vector<int>>& mat, int k) {
    auto countSoldiers = [](const std::vector<int>& row) -> int {
        int left = 0, right = static_cast<int>(row.size());
        while (left < right) {
            int mid = (left + right) >> 1;
            if (row[mid] == 1) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    };

    std::vector<std::pair<int, int>> rows;
    rows.reserve(mat.size());
    for (int i = 0; i < static_cast<int>(mat.size()); ++i) {
        rows.emplace_back(countSoldiers(mat[i]), i);
    }

    std::sort(rows.begin(), rows.end(), [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second < b.second;
    });

    std::vector<int> answer;
    answer.reserve(k);
    for (int i = 0; i < k; ++i) {
        answer.push_back(rows[i].second);
    }
    return answer;
}

