struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode* left, TreeNode* right) : val(x), left(left), right(right) {}
};

static long long dfs(TreeNode* node, std::vector<long long>& sums) {
    if (!node) return 0;
    long long left = dfs(node->left, sums);
    long long right = dfs(node->right, sums);
    long long cur = static_cast<long long>(node->val) + left + right;
    sums.push_back(cur);
    return cur;
}

int maxProduct(TreeNode* root) {
    const long long MOD = 1000000007LL;
    std::vector<long long> subtreeSums;
    long long total = dfs(root, subtreeSums);
    long long best = 0;
    for (long long s : subtreeSums) {
        long long product = s * (total - s);
        if (product > best) best = product;
    }
    return static_cast<int>(best % MOD);
}

