int minSetSize(const std::vector<int>& arr) {
    std::unordered_map<int, int> freqMap;
    for (int num : arr) {
        ++freqMap[num];
    }
    std::vector<int> frequencies;
    frequencies.reserve(freqMap.size());
    for (const auto& kv : freqMap) {
        frequencies.push_back(kv.second);
    }
    std::sort(frequencies.begin(), frequencies.end(), std::greater<int>());
    int half = (static_cast<int>(arr.size()) + 1) / 2;
    int removed = 0;
    int setSize = 0;
    for (int freq : frequencies) {
        removed += freq;
        ++setSize;
        if (removed >= half) break;
    }
    return setSize;
}

