int numOfSubarrays(const std::vector<int>& arr, int k, int threshold) {
    long long requiredSum = static_cast<long long>(k) * threshold;
    long long windowSum = 0;
    int count = 0;
    for (size_t i = 0; i < arr.size(); ++i) {
        windowSum += arr[i];
        if (i >= static_cast<size_t>(k)) {
            windowSum -= arr[i - k];
        }
        if (i >= static_cast<size_t>(k - 1) && windowSum >= requiredSum) {
            ++count;
        }
    }
    return count;
}

