bool checkIfExist(const std::vector<int>& arr) {
    std::unordered_set<int> seen;
    int zeroCount = 0;
    for (int x : arr) {
        if (x == 0) {
            ++zeroCount;
            if (zeroCount >= 2) return true;
        } else {
            if (seen.count(x * 2) || (x % 2 == 0 && seen.count(x / 2))) {
                return true;
            }
        }
        seen.insert(x);
    }
    return false;
}

