double clockAngle(int hour, int minutes) {
    hour = hour % 12;
    double minuteAngle = minutes * 6.0;
    double hourAngle = hour * 30.0 + minutes * 0.5;
    double diff = std::abs(hourAngle - minuteAngle);
    return std::min(diff, 360.0 - diff);
}

#include <bits/stdc++.h>
