int minJumps(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    if (n <= 1) return 0;

    std::unordered_map<int, std::vector<int>> valueIndices;
    valueIndices.reserve(n * 2);
    for (int i = 0; i < n; ++i) {
        valueIndices[arr[i]].push_back(i);
    }

    std::vector<char> visited(n, 0);
    std::deque<int> queue;
    queue.push_back(0);
    visited[0] = 1;
    int steps = 0;

    while (!queue.empty()) {
        int size = static_cast<int>(queue.size());
        for (int s = 0; s < size; ++s) {
            int idx = queue.front();
            queue.pop_front();
            if (idx == n - 1) return steps;

            std::vector<int> next;
            if (idx - 1 >= 0) next.push_back(idx - 1);
            if (idx + 1 < n) next.push_back(idx + 1);

            auto it = valueIndices.find(arr[idx]);
            if (it != valueIndices.end()) {
                for (int j : it->second) {
                    next.push_back(j);
                }
                it->second.clear();
            }

            for (int nb : next) {
                if (!visited[nb]) {
                    visited[nb] = 1;
                    queue.push_back(nb);
                }
            }
        }
        ++steps;
    }
    return -1;
}

