int minSteps(const std::string& s, const std::string& t) {
    std::unordered_map<char, int> cntS;
    for (size_t i = 0; i < s.size(); ++i) {
        char ch = s[i];
        cntS[ch] = cntS[ch] + 1;
    }

    std::unordered_map<char, int> cntT;
    for (size_t i = 0; i < t.size(); ++i) {
        char ch = t[i];
        cntT[ch] = cntT[ch] + 1;
    }

    int steps = 0;
    for (const auto& kv : cntT) {
        char ch = kv.first;
        int surplus = kv.second - (cntS.find(ch) != cntS.end() ? cntS[ch] : 0);
        if (surplus > 0) {
            steps += surplus;
        }
    }

    return steps;
}

