struct TweetCountsObj {
    std::unordered_map<std::string, std::vector<int>> data;

    static size_t lowerBound(const std::vector<int>& arr, int target) {
        size_t lo = 0, hi = arr.size();
        while (lo < hi) {
            size_t mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static size_t upperBound(const std::vector<int>& arr, int target) {
        size_t lo = 0, hi = arr.size();
        while (lo < hi) {
            size_t mid = (lo + hi) >> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    void recordTweet(const std::string& tweetName, int time) {
        auto& arr = data[tweetName];
        size_t idx = lowerBound(arr, time);
        arr.insert(arr.begin() + idx, time);
    }

    std::vector<int> getTweetCountsPerFrequency(const std::string& freq, const std::string& tweetName, int startTime, int endTime) {
        int bucketSize = (freq == "minute") ? 60 : (freq == "hour") ? 3600 : 86400;
        int bucketCount = (endTime - startTime) / bucketSize + 1;
        std::vector<int> counts(bucketCount, 0);
        auto it = data.find(tweetName);
        if (it == data.end()) return counts;
        const std::vector<int>& arr = it->second;
        size_t left = lowerBound(arr, startTime);
        size_t right = upperBound(arr, endTime);
        for (size_t i = left; i < right; ++i) {
            int bucket = (arr[i] - startTime) / bucketSize;
            ++counts[bucket];
        }
        return counts;
    }
};

TweetCountsObj TweetCounts() {
    return TweetCountsObj();
}

#include <bits/stdc++.h>
int maxStudents(std::vector<std::vector<char>>& seats) {
    int m = seats.size();
    int n = seats[0].size();
    std::vector<int> brokenMask(m, 0);
    for (int i = 0; i < m; ++i) {
        int mask = 0;
        for (int j = 0; j < n; ++j) {
            if (seats[i][j] == '#') mask |= (1 << j);
        }
        brokenMask[i] = mask;
    }
    std::vector<std::vector<int>> validMasks(m);
    int totalMask = 1 << n;
    for (int i = 0; i < m; ++i) {
        for (int mask = 0; mask < totalMask; ++mask) {
            if (mask & brokenMask[i]) continue;                 // seat is broken
            if (mask & (mask << 1)) continue;                  // adjacent in same row
            validMasks[i].push_back(mask);
        }
    }
    const int NEG = -1000000;
    std::vector<int> dp(totalMask, NEG);
    for (int mask : validMasks[0]) {
        dp[mask] = __builtin_popcount(mask);
    }
    for (int i = 1; i < m; ++i) {
        std::vector<int> ndp(totalMask, NEG);
        for (int cur : validMasks[i]) {
            int curCnt = __builtin_popcount(cur);
            for (int prev : validMasks[i - 1]) {
                if (dp[prev] == NEG) continue;
                if (cur & (prev << 1)) continue;   // upper-left conflict
                if (cur & (prev >> 1)) continue;   // upper-right conflict
                ndp[cur] = std::max(ndp[cur], dp[prev] + curCnt);
            }
        }
        dp.swap(ndp);
    }
    int ans = 0;
    for (int val : dp) ans = std::max(ans, val);
    return ans;
}

