struct ProductOps {
    std::function<void(long long)> add;
    std::function<long long(int)> getProduct;
};

ProductOps createProductOfNumbers() {
    auto prefix = std::make_shared<std::vector<long long>>(1, 1);
    return ProductOps{
        [prefix](long long num) {
            if (num == 0) {
                prefix->assign(1, 1);
            } else {
                prefix->push_back((*prefix)[prefix->size() - 1] * num);
            }
        },
        [prefix](int k) -> long long {
            if (k >= static_cast<int>(prefix->size())) return 0;
            return (*prefix)[prefix->size() - 1] / (*prefix)[prefix->size() - 1 - k];
        }
    };
}

