bool isPossible(std::vector<int>& target) {
    if (target.size() == 1) {
        return target[0] == 1;
    }
    std::priority_queue<std::int64_t> pq;
    std::int64_t total = 0;
    for (int v : target) {
        total += v;
        pq.push(v);
    }
    while (true) {
        std::int64_t mx = pq.top();
        pq.pop();
        std::int64_t rest = total - mx;
        if (mx == 1 || rest == 1) {
            return true;
        }
        if (rest == 0 || mx < rest) {
            return false;
        }
        std::int64_t prev = mx % rest;
        if (prev == 0) {
            prev = rest;
        }
        if (prev < 1) {
            return false;
        }
        total = rest + prev;
        pq.push(prev);
    }
    return false;
}

