int countNegatives(const std::vector<std::vector<int>>& grid) {
    int rows = static_cast<int>(grid.size());
    if (rows == 0) return 0;
    int cols = static_cast<int>(grid[0].size());
    int r = rows - 1;
    int c = 0;
    int count = 0;
    while (r >= 0 && c < cols) {
        if (grid[r][c] < 0) {
            count += cols - c;
            --r;
        } else {
            ++c;
        }
    }
    return count;
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>

int maxEvents(std::vector<std::vector<int>>& events) {
    std::sort(events.begin(), events.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        return a[0] < b[0];
    });
    std::vector<int> heap;
    auto push = [&](int val) {
        heap.push_back(val);
        int i = static_cast<int>(heap.size()) - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
    };
    auto pop = [&]() -> int {
        if (heap.empty()) return -1;
        int top = heap[0];
        int last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            int i = 0;
            while (true) {
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                int smallest = i;
                if (l < static_cast<int>(heap.size()) && heap[l] < heap[smallest]) smallest = l;
                if (r < static_cast<int>(heap.size()) && heap[r] < heap[smallest]) smallest = r;
                if (smallest == i) break;
                std::swap(heap[i], heap[smallest]);
                i = smallest;
            }
        }
        return top;
    };
    auto peek = [&]() -> int {
        return heap.empty() ? -1 : heap[0];
    };
    size_t i = 0;
    int day = 0;
    int attended = 0;
    int n = static_cast<int>(events.size());
    while (i < static_cast<size_t>(n) || !heap.empty()) {
        if (heap.empty()) day = events[i][0];
        while (i < static_cast<size_t>(n) && events[i][0] <= day) {
            push(events[i][1]);
            ++i;
        }
        while (!heap.empty() && peek() < day) {
            pop();
        }
        if (!heap.empty()) {
            pop();
            ++attended;
            ++day;
        } else {
            ++day;
        }
    }
    return attended;
}

