std::vector<int> sortByBits(std::vector<int> arr) {
    std::unordered_map<int, int> bitCount;
    auto countBits = [](int x) {
        int cnt = 0;
        while (x) {
            x &= x - 1;
            ++cnt;
        }
        return cnt;
    };
    for (int v : arr) {
        bitCount[v] = countBits(v);
    }
    std::sort(arr.begin(), arr.end(), [&](int a, int b) {
        int ca = bitCount[a];
        int cb = bitCount[b];
        if (ca != cb) return ca < cb;
        return a < b;
    });
    return arr;
}

