auto Cashier(int n, int discount, const std::vector<int>& products, const std::vector<int>& prices) {
    std::unordered_map<int, int> priceMap;
    for (size_t i = 0; i < products.size(); ++i) {
        priceMap[products[i]] = prices[i];
    }
    int orderCount = 0;
    return [=](const std::vector<int>& product, const std::vector<int>& amount) mutable -> double {
        ++orderCount;
        double total = 0;
        for (size_t i = 0; i < product.size(); ++i) {
            total += amount[i] * priceMap.at(product[i]);
        }
        if (orderCount % n == 0) {
            total = total * (100 - discount) / 100.0;
        }
        return total;
    };
}

