int countValidSequences(int n) {
    const int MOD = 1000000007;
    long long ans = 1;
    for (int i = 1; i <= n; ++i) {
        ans = ans * (2LL * i - 1) % MOD;
        ans = ans * i % MOD;
    }
    return static_cast<int>(ans);
}

