bool validateBinaryTreeNodes(int n, const std::vector<int>& leftChild, const std::vector<int>& rightChild) {
    std::vector<int> indegree(n, 0);
    for (int i = 0; i < n; ++i) {
        int l = leftChild[i];
        int r = rightChild[i];
        if (l != -1) indegree[l]++;
        if (r != -1) indegree[r]++;
    }

    int root = -1;
    for (int i = 0; i < n; ++i) {
        if (indegree[i] == 0) {
            if (root != -1) return false;
            root = i;
        }
    }
    if (root == -1) return false;

    std::vector<char> visited(n, false);
    std::vector<int> stack;
    stack.push_back(root);
    while (!stack.empty()) {
        int node = stack.back();
        stack.pop_back();
        if (visited[node]) return false;
        visited[node] = true;
        int l = leftChild[node];
        int r = rightChild[node];
        if (l != -1) stack.push_back(l);
        if (r != -1) stack.push_back(r);
    }

    for (int i = 0; i < n; ++i) {
        if (!visited[i]) return false;
    }
    return true;
}

