static std::vector<int> parseDate(const std::string& s) {
    std::vector<int> parts;
    size_t start = 0;
    while (true) {
        size_t pos = s.find('-', start);
        if (pos == std::string::npos) {
            parts.push_back(std::stoi(s.substr(start)));
            break;
        } else {
            parts.push_back(std::stoi(s.substr(start, pos - start)));
            start = pos + 1;
        }
    }
    return parts;
}

// Days since 1970-01-01 (Unix epoch)
static long long daysFromCivil(int y, unsigned m, unsigned d) {
    y -= (m <= 2);
    const int era = (y >= 0 ? y : y - 399) / 400;
    const unsigned yoe = static_cast<unsigned>(y - era * 400);
    const unsigned mp = m > 2 ? m - 3 : m + 9;
    const unsigned doy = (153 * mp + 2) / 5 + d - 1;
    const unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097LL + static_cast<long long>(doe) - 719468LL;
}

double daysBetween(const std::string& date1, const std::string& date2) {
    std::vector<int> p1 = parseDate(date1);
    std::vector<int> p2 = parseDate(date2);
    long long d1 = daysFromCivil(p1[0], static_cast<unsigned>(p1[1]), static_cast<unsigned>(p1[2]));
    long long d2 = daysFromCivil(p2[0], static_cast<unsigned>(p2[1]), static_cast<unsigned>(p2[2]));
    long long diff = std::llabs(d1 - d2);
    return static_cast<double>(diff);
}

