std::vector<int> closestDivisors(int num) {
    long long bestDiff = std::numeric_limits<long long>::max();
    std::vector<int> bestPair;
    for (int product : {num + 1, num + 2}) {
        int limit = static_cast<int>(std::floor(std::sqrt(product)));
        for (int i = limit; i >= 1; --i) {
            if (product % i == 0) {
                int j = product / i;
                long long diff = std::abs(static_cast<long long>(i) - static_cast<long long>(j));
                if (diff < bestDiff) {
                    bestDiff = diff;
                    bestPair = {i, j};
                }
                break;
            }
        }
    }
    return bestPair;
}

