}

#include <bits/stdc++.h>
#include <vector>
#include <string>

std::string largestMultipleOfThree(std::vector<int>& digits) {
    int cnt[10] = {0};
    int sum = 0;
    for (int d : digits) {
        cnt[d]++;
        sum += d;
    }
    int rem = sum % 3;
    auto remove_one = [&](int target_rem) -> bool {
        for (int d = 0; d <= 9; ++d) {
            if (d % 3 == target_rem && cnt[d] > 0) {
                cnt[d]--;
                return true;
            }
        }
        return false;
    };
    auto remove_two = [&](int target_rem) -> bool {
        int removed = 0;
        for (int d = 0; d <= 9 && removed < 2; ++d) {
            while (cnt[d] > 0 && d % 3 == target_rem && removed < 2) {
                cnt[d]--;
                ++removed;
            }
        }
        return removed == 2;
    };
    if (rem == 1) {
        if (!remove_one(1)) {
            if (!remove_two(2)) return "";
        }
    } else if (rem == 2) {
        if (!remove_one(2)) {
            if (!remove_two(1)) return "";
        }
    }
    std::string result;
    for (int d = 9; d >= 0; --d) {
        result.append(cnt[d], char('0' + d));
    }
    if (result.empty()) return "";
    if (result[0] == '0') return "0";
    return result;
}

