static bool match(ListNode* listNode, TreeNode* treeNode) {
    if (!listNode) return true;
    if (!treeNode) return false;
    if (listNode->val != treeNode->val) return false;
    return match(listNode->next, treeNode->left) || match(listNode->next, treeNode->right);
}

static bool dfs(TreeNode* node, ListNode* head) {
    if (!node) return false;
    if (match(head, node)) return true;
    return dfs(node->left, head) || dfs(node->right, head);
}

bool isSubPath(ListNode* head, TreeNode* root) {
    if (!head) return true;
    return dfs(root, head);
}

