int minCost(const std::vector<std::vector<int>>& grid) {
    const int m = static_cast<int>(grid.size());
    const int n = static_cast<int>(grid[0].size());
    const int INF = 1000000000;
    std::vector<std::vector<int>> dist(m, std::vector<int>(n, INF));

    std::vector<std::array<int, 3>> heap;
    auto push = [&](int c, int i, int j) {
        heap.push_back({c, i, j});
        std::size_t idx = heap.size() - 1;
        while (idx > 0) {
            std::size_t p = (idx - 1) >> 1;
            if (heap[p][0] <= heap[idx][0]) break;
            std::swap(heap[p], heap[idx]);
            idx = p;
        }
    };
    auto pop = [&]() -> std::array<int, 3> {
        std::array<int, 3> top = heap[0];
        std::array<int, 3> last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            std::size_t idx = 0;
            while (true) {
                std::size_t l = idx * 2 + 1;
                std::size_t r = idx * 2 + 2;
                std::size_t smallest = idx;
                if (l < heap.size() && heap[l][0] < heap[smallest][0]) smallest = l;
                if (r < heap.size() && heap[r][0] < heap[smallest][0]) smallest = r;
                if (smallest == idx) break;
                std::swap(heap[smallest], heap[idx]);
                idx = smallest;
            }
        }
        return top;
    };

    dist[0][0] = 0;
    push(0, 0, 0);

    const int dirs[4][3] = {
        {0, 1, 1},
        {0, -1, 2},
        {1, 0, 3},
        {-1, 0, 4}
    };

    while (!heap.empty()) {
        std::array<int, 3> cur = pop();
        int cost = cur[0];
        int i = cur[1];
        int j = cur[2];
        if (cost != dist[i][j]) continue;
        if (i == m - 1 && j == n - 1) return cost;

        for (const auto& d : dirs) {
            int ni = i + d[0];
            int nj = j + d[1];
            if (ni < 0 || nj < 0 || ni >= m || nj >= n) continue;
            int newCost = cost + (grid[i][j] == d[2] ? 0 : 1);
            if (newCost < dist[ni][nj]) {
                dist[ni][nj] = newCost;
                push(newCost, ni, nj);
            }
        }
    }
    return dist[m - 1][n - 1];
}

