std::string rankTeams(const std::vector<std::string>& votes) {
    int n = votes[0].size();
    std::unordered_map<char, std::vector<int>> counts;
    for (char ch : votes[0]) {
        counts[ch] = std::vector<int>(n, 0);
    }
    for (const std::string& vote : votes) {
        for (int i = 0; i < n; ++i) {
            char team = vote[i];
            counts[team][i] += 1;
        }
    }
    std::vector<char> teams;
    teams.reserve(counts.size());
    for (const auto& kv : counts) {
        teams.push_back(kv.first);
    }
    std::sort(teams.begin(), teams.end(), [&](char a, char b) {
        for (int i = 0; i < n; ++i) {
            if (counts[a][i] != counts[b][i]) {
                return counts[a][i] > counts[b][i];
            }
        }
        return a < b;
    });
    std::string result;
    result.reserve(teams.size());
    for (char c : teams) {
        result.push_back(c);
    }
    return result;
}

