    std::pair<int, int> leftChild = dfs(node->left, best);
    std::pair<int, int> rightChild = dfs(node->right, best);
    int leftZig = node->left ? 1 + leftChild.second : 0;
    int rightZig = node->right ? 1 + rightChild.first : 0;
    best = std::max({best, leftZig, rightZig});
    return {leftZig, rightZig};
}

