int longestEvenVowelSubstring(const std::string& s) {
    std::vector<int> firstPos(32, -2);
    firstPos[0] = -1;

    int mask = 0;
    int maxLen = 0;

    for (size_t i = 0; i < s.size(); ++i) {
        char ch = s[i];
        switch (ch) {
            case 'a': mask ^= 1 << 0; break;
            case 'e': mask ^= 1 << 1; break;
            case 'i': mask ^= 1 << 2; break;
            case 'o': mask ^= 1 << 3; break;
            case 'u': mask ^= 1 << 4; break;
            default: break;
        }

        if (firstPos[mask] != -2) {
            int len = static_cast<int>(i) - firstPos[mask];
            if (len > maxLen) maxLen = len;
        } else {
            firstPos[mask] = static_cast<int>(i);
        }
    }

    return maxLen;
}

