long long maxSumBST(TreeNode* root) {
    long long maxSum = 0;
    std::function<std::tuple<bool, long long, int, int>(TreeNode*)> dfs = [&](TreeNode* node) -> std::tuple<bool, long long, int, int> {
        if (node == nullptr) {
            return {true, 0LL, INT_MAX, INT_MIN};
        }
        auto left = dfs(node->left);
        auto right = dfs(node->right);
        bool isBST = std::get<0>(left) && std::get<0>(right) &&
                     node->val > std::get<3>(left) && node->val < std::get<2>(right);
        if (isBST) {
            long long curSum = node->val + std::get<1>(left) + std::get<1>(right);
            maxSum = std::max(maxSum, curSum);
            int curMin = std::min(node->val, std::get<2>(left));
            int curMax = std::max(node->val, std::get<3>(right));
            return {true, curSum, curMin, curMax};
        } else {
            return {false, 0LL, 0, 0};
        }
    };
    dfs(root);
    return maxSum;
}

