int numOfMinutes(int n, int headID, const std::vector<int>& manager, const std::vector<int>& informTime) {
    std::vector<std::vector<int>> subordinates(n);
    for (int i = 0; i < n; ++i) {
        int m = manager[i];
        if (m != -1) {
            subordinates[m].push_back(i);
        }
    }
    std::function<int(int)> dfs = [&](int emp) -> int {
        if (subordinates[emp].empty()) return 0;
        int maxChildTime = 0;
        for (int sub : subordinates[emp]) {
            int childTime = dfs(sub);
            if (childTime > maxChildTime) maxChildTime = childTime;
        }
        return informTime[emp] + maxChildTime;
    };
    return dfs(headID);
}

