double frogPosition(int n, const std::vector<std::vector<int>>& edges, int t, int target) {
    std::vector<std::vector<int>> graph(n + 1);
    for (const auto& e : edges) {
        int a = e[0];
        int b = e[1];
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    std::vector<bool> visited(n + 1, false);
    double result = 0.0;
    std::function<void(int, int, double)> dfs = [&](int node, int time, double prob) {
        visited[node] = true;
        if (time == t) {
            if (node == target) result += prob;
            visited[node] = false;
            return;
        }
        std::vector<int> unvisitedNeighbors;
        for (int v : graph[node]) {
            if (!visited[v]) unvisitedNeighbors.push_back(v);
        }
        if (unvisitedNeighbors.empty()) {
            if (node == target) result += prob;
            visited[node] = false;
            return;
        }
        double nextProb = prob / unvisitedNeighbors.size();
        for (int next : unvisitedNeighbors) {
            dfs(next, time + 1, nextProb);
        }
        visited[node] = false;
    };
    dfs(1, 0, 1.0);
    return result;
}

