struct CustomStackResult {
    std::vector<int> stack;
    std::vector<long long> inc;
    int maxSize;
    CustomStackResult(int maxSize) : maxSize(maxSize), inc(maxSize, 0) {}
    void push(int x) {
        if (static_cast<int>(stack.size()) < maxSize) {
            stack.push_back(x);
        }
    }
    int pop() {
        if (stack.empty()) return -1;
        int i = static_cast<int>(stack.size()) - 1;
        long long val = static_cast<long long>(stack.back()) + inc[i];
        stack.pop_back();
        if (i > 0) inc[i - 1] += inc[i];
        inc[i] = 0;
        return static_cast<int>(val);
    }
    void increment(int k, int val) {
        int idx = std::min(k, static_cast<int>(stack.size())) - 1;
        if (idx >= 0) inc[idx] += val;
    }
};

CustomStackResult CustomStack(int maxSize) {
    return CustomStackResult(maxSize);
