std::vector<int> luckyNumbers(const std::vector<std::vector<int>>& matrix) {
    size_t rowCount = matrix.size();
    if (rowCount == 0) {
        return {};
    }
    size_t colCount = matrix[0].size();

    std::vector<int> rowMins(rowCount, std::numeric_limits<int>::max());
    std::vector<int> colMaxes(colCount, std::numeric_limits<int>::min());

    for (size_t i = 0; i < rowCount; ++i) {
        for (size_t j = 0; j < colCount; ++j) {
            int val = matrix[i][j];
            if (val < rowMins[i]) rowMins[i] = val;
            if (val > colMaxes[j]) colMaxes[j] = val;
        }
