    std::vector<int> result;
    for (size_t i = 0; i < rowCount; ++i) {
        for (size_t j = 0; j < colCount; ++j) {
            int val = matrix[i][j];
            if (val == rowMins[i] && val == colMaxes[j]) {
                result.push_back(val);
            }
        }
    }

    return result;
}

