int maxPerformance(int n, std::vector<int> speed, std::vector<int> efficiency, int k) {
    const int64_t MOD = 1000000007LL;
    std::vector<std::pair<int, int>> engineers;
    engineers.reserve(n);
    for (int i = 0; i < n; ++i) {
        engineers.emplace_back(efficiency[i], speed[i]);
    }
    std::sort(engineers.begin(), engineers.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  return a.first > b.first;
              });
    std::priority_queue<int64_t, std::vector<int64_t>, std::greater<int64_t>> heap;
    int64_t speedSum = 0;
    int64_t best = 0;
    for (const auto& es : engineers) {
        int eff = es.first;
        int spd = es.second;
        heap.push(spd);
        speedSum += spd;
        if (static_cast<int>(heap.size()) > k) {
            speedSum -= heap.top();
            heap.pop();
        }
        int64_t performance = speedSum * static_cast<int64_t>(eff);
        if (performance > best) best = performance;
    }
    return static_cast<int>(best % MOD);
}

