int maxNumberOfFamilies(int n, const std::vector<std::vector<int>>& reservedSeats) {
    std::unordered_map<int, int> rowMask;
    for (const auto& seat : reservedSeats) {
        int r = seat[0];
        int s = seat[1];
        int mask = rowMask[r] | (1 << s);
        rowMask[r] = mask;
    }

    int families = (n - static_cast<int>(rowMask.size())) * 2;

    const int leftMask   = (1 << 2) | (1 << 3) | (1 << 4) | (1 << 5);
    const int rightMask  = (1 << 6) | (1 << 7) | (1 << 8) | (1 << 9);
    const int middleMask = (1 << 4) | (1 << 5) | (1 << 6) | (1 << 7);

    for (const auto& kv : rowMask) {
        int mask = kv.second;
        bool leftFree   = (mask & leftMask)   == 0;
        bool rightFree  = (mask & rightMask)  == 0;
        bool middleFree = (mask & middleMask) == 0;

        if (leftFree && rightFree) {
            families += 2;
        } else if (middleFree) {
            families += 1;
        } else if (leftFree || rightFree) {
            families += 1;
        }
    }
    return families;
}

