int getKth(int lo, int hi, int k) {
    std::unordered_map<long long, int> memo;
    memo[1] = 0;

    std::function<int(long long)> power = [&](long long x) -> int {
        auto it = memo.find(x);
        if (it != memo.end()) return it->second;
        long long next = (x % 2 == 0) ? x / 2 : 3 * x + 1;
        int p = 1 + power(next);
        memo[x] = p;
        return p;
    };

    struct Item { int num; int pow; };
    std::vector<Item> list;
    list.reserve(hi - lo + 1);
    for (int i = lo; i <= hi; ++i) {
        list.push_back({i, power(i)});
    }

    std::sort(list.begin(), list.end(), [](const Item& a, const Item& b) {
        return a.pow == b.pow ? a.num < b.num : a.pow < b.pow;
    });

    return list[k - 1].num;
}

