int findDistanceValue(const std::vector<int>& arr1, std::vector<int> arr2, int d) {
    std::sort(arr2.begin(), arr2.end());
    int distanceCount = 0;
    for (size_t i = 0; i < arr1.size(); ++i) {
        int val = arr1[i];
        int left = 0;
        int right = static_cast<int>(arr2.size()) - 1;
        while (left <= right) {
            int mid = (left + right) >> 1;
            if (arr2[mid] < val) left = mid + 1;
            else right = mid - 1;
        }
        bool ok = true;
        if (left < static_cast<int>(arr2.size()) && std::abs(arr2[left] - val) <= d) ok = false;
        if (right >= 0 && std::abs(arr2[right] - val) <= d) ok = false;
        if (ok) ++distanceCount;
    }
    return distanceCount;
}

