bool hasValidPath(const std::vector<std::vector<int>>& grid) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};
    const int opposite[4] = {1, 0, 3, 2};

    std::vector<std::vector<int>> allowed(7);
    allowed[1] = {2, 3};
    allowed[2] = {0, 1};
    allowed[3] = {2, 1};
    allowed[4] = {3, 1};
    allowed[5] = {2, 0};
    allowed[6] = {3, 0};

    std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));
    std::queue<std::pair<int, int>> q;
    q.emplace(0, 0);
    visited[0][0] = true;

    while (!q.empty()) {
        int r = q.front().first;
        int c = q.front().second;
        q.pop();
        if (r == m - 1 && c == n - 1) {
            return true;
        }
        for (int dir : allowed[grid[r][c]]) {
            int nr = r + dr[dir];
            int nc = c + dc[dir];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {
                const std::vector<int>& neigh = allowed[grid[nr][nc]];
                if (std::find(neigh.begin(), neigh.end(), opposite[dir]) != neigh.end()) {
                    visited[nr][nc] = true;
                    q.emplace(nr, nc);
                }
            }
        }
    }
    return false;
}

