int solveLinear(const std::vector<int>& arr, int picks) {
    int m = static_cast<int>(arr.size());
    std::vector<std::vector<int>> dp(m, std::vector<int>(picks + 1, 0));
    if (m == 0 || picks == 0) return 0;
    dp[0][1] = arr[0];
    for (int i = 1; i < m; ++i) {
        dp[i][0] = 0;
        for (int j = 1; j <= picks; ++j) {
            int notTake = dp[i - 1][j];
            int take = arr[i];
            if (i >= 2) take += dp[i - 2][j - 1];
            else if (j == 1) take = arr[i]; // i == 1 and j == 1
            else take = 0;
            dp[i][j] = std::max(notTake, take);
        }
    }
    return dp[m - 1][picks];
}

int maxSizeSlices(std::vector<int>& slices) {
    int m = static_cast<int>(slices.size());
    int picks = m / 3;
    std::vector<int> withoutFirst(slices.begin() + 1, slices.end());
    std::vector<int> withoutLast(slices.begin(), slices.end() - 1);
    int ans1 = solveLinear(withoutFirst, picks);
    int ans2 = solveLinear(withoutLast, picks);
    return std::max(ans1, ans2);
}

#include <bits/stdc++.h>
