long long sumFourDivisors(const std::vector<int>& nums) {
    long long total = 0;
    for (int n : nums) {
        int divisorCount = 0;
        long long divisorSum = 0;
        for (int i = 1; i * i <= n; ++i) {
            if (n % i == 0) {
                ++divisorCount;
                divisorSum += i;
                int other = n / i;
                if (other != i) {
                    ++divisorCount;
                    divisorSum += other;
                }
                if (divisorCount > 4) {
                    break;
                }
            }
        }
        if (divisorCount == 4) {
            total += divisorSum;
        }
    }
