struct UndergroundSystemObj {
    std::unordered_map<int, std::pair<std::string, int>> active;
    std::unordered_map<std::string, std::pair<long long, int>> stats;

    void checkIn(int id, const std::string& stationName, int t) {
        active[id] = {stationName, t};
    }

    void checkOut(int id, const std::string& stationName, int t) {
        auto it = active.find(id);
        if (it != active.end()) {
            const auto& info = it->second;
            long long travelTime = static_cast<long long>(t) - info.second;
            std::string routeKey = info.first + "|" + stationName;
            auto statIt = stats.find(routeKey);
            if (statIt != stats.end()) {
                statIt->second.first += travelTime;
                statIt->second.second += 1;
            } else {
                stats.emplace(routeKey, std::make_pair(travelTime, 1));
            }
            active.erase(it);
        }
    }

    double getAverageTime(const std::string& startStation, const std::string& endStation) {
        std::string key = startStation + "|" + endStation;
        const auto& data = stats.at(key);
        return static_cast<double>(data.first) / data.second;
    }
};

