long long countTeams(const std::vector<int>& rating) {
    const std::size_t n = rating.size();
    long long total = 0;

    for (std::size_t j = 0; j < n; ++j) {
        int leftLess = 0, leftGreater = 0;
        for (std::size_t i = 0; i < j; ++i) {
            if (rating[i] < rating[j]) {
                ++leftLess;
            } else if (rating[i] > rating[j]) {
                ++leftGreater;
            }
        }

        int rightGreater = 0, rightLess = 0;
        for (std::size_t k = j + 1; k < n; ++k) {
            if (rating[k] > rating[j]) {
                ++rightGreater;
            } else if (rating[k] < rating[j]) {
                ++rightLess;
            }
        }

        total += static_cast<long long>(leftLess) * rightGreater + static_cast<long long>(leftGreater) * rightLess;
    }

    return total;
}

#include <bits/stdc++.h>
int findGoodStrings(int n, std::string s1, std::string s2, std::string evil) {
    const int MOD = 1000000007;
    int m = evil.size();
    // compute prefix function for KMP
    std::vector<int> pi(m, 0);
    for (int i = 1; i < m; ++i) {
        int j = pi[i - 1];
        while (j > 0 && evil[i] != evil[j]) j = pi[j - 1];
        if (evil[i] == evil[j]) ++j;
        pi[i] = j;
    }
    // next state automaton
    std::vector<std::vector<int>> nxt(m + 1, std::vector<int>(26, 0));
    for (int k = 0; k <= m; ++k) {
        for (int c = 0; c < 26; ++c) {
            if (k == m) {
                nxt[k][c] = m;
                continue;
            }
            int t = k;
            char ch = 'a' + c;
            while (t > 0 && evil[t] != ch) t = pi[t - 1];
            if (evil[t] == ch) ++t;
            nxt[k][c] = t;
        }
    }
    // dp[pos][matched][tightLow][tightHigh]
    std::vector<std::vector<std::vector<std::vector<int>>>> dp(
        n + 1,
        std::vector<std::vector<std::vector<int>>>(
            m,
            std::vector<std::vector<int>>(2, std::vector<int>(2, 0))));
    dp[0][0][1][1] = 1;
    for (int pos = 0; pos < n; ++pos) {
        for (int matched = 0; matched < m; ++matched) {
            for (int lowFlag = 0; lowFlag <= 1; ++lowFlag) {
                for (int highFlag = 0; highFlag <= 1; ++highFlag) {
                    int cur = dp[pos][matched][lowFlag][highFlag];
                    if (cur == 0) continue;
                    char lowChar = lowFlag ? s1[pos] : 'a';
                    char highChar = highFlag ? s2[pos] : 'z';
                    for (char ch = lowChar; ch <= highChar; ++ch) {
                        int nextMatched = nxt[matched][ch - 'a'];
                        if (nextMatched == m) continue; // contains evil
                        int nextLow = lowFlag && (ch == s1[pos]);
                        int nextHigh = highFlag && (ch == s2[pos]);
                        int &ref = dp[pos + 1][nextMatched][nextLow][nextHigh];
                        ref += cur;
                        if (ref >= MOD) ref -= MOD;
                    }
                }
            }
        }
    }
    long long ans = 0;
    for (int matched = 0; matched < m; ++matched) {
        for (int lowFlag = 0; lowFlag <= 1; ++lowFlag) {
            for (int highFlag = 0; highFlag <= 1; ++highFlag) {
                ans += dp[n][matched][lowFlag][highFlag];
                if (ans >= MOD) ans -= MOD;
            }
        }
    }
    return static_cast<int>(ans % MOD);
}

