int countLargestGroup(int n) {
    std::unordered_map<int, int> freq;
    auto digitSum = [](int x) {
        int s = 0;
        while (x > 0) {
            s += x % 10;
            x /= 10;
        }
        return s;
    };
    for (int i = 1; i <= n; ++i) {
        int sum = digitSum(i);
        ++freq[sum];
    }
    int maxSize = 0;
    for (const auto& kv : freq) {
        if (kv.second > maxSize) maxSize = kv.second;
    }
    int answer = 0;
    for (const auto& kv : freq) {
        if (kv.second == maxSize) ++answer;
    }
    return answer;
}

