bool checkOverlap(double radius, double xCenter, double yCenter, double x1, double y1, double x2, double y2) {
    double closestX = std::max(x1, std::min(xCenter, x2));
    double closestY = std::max(y1, std::min(yCenter, y2));
    double dx = xCenter - closestX;
    double dy = yCenter - closestY;
    return dx * dx + dy * dy <= radius * radius;
}

