std::vector<int> processQueries(std::vector<int>& queries, int m) {
    std::vector<int> perm(m);
    for (int i = 0; i < m; ++i) perm[i] = i + 1;
    std::vector<int> ans;
    ans.reserve(queries.size());
    for (int q : queries) {
        int idx = 0;
        while (perm[idx] != q) ++idx;
        ans.push_back(idx);
        perm.erase(perm.begin() + idx);
        perm.insert(perm.begin(), q);
    }
    return ans;
}

