std::string longestDiverseString(int a, int b, int c) {
    std::vector<std::pair<int, char>> v = {{a, 'a'}, {b, 'b'}, {c, 'c'}};
    std::string ans;
    while (true) {
        std::sort(v.begin(), v.end(),
                  [](const std::pair<int, char>& p1, const std::pair<int, char>& p2) {
                      return p1.first > p2.first;
                  });
        bool added = false;
        for (int i = 0; i < 3; ++i) {
            if (v[i].first == 0) continue;
            int n = ans.size();
            if (n >= 2 && ans[n - 1] == ans[n - 2] && ans[n - 1] == v[i].second) {
                continue;
