std::string entityParser(const std::string& text) {
    static const std::unordered_map<std::string, char> entityMap = {
        {"&quot;", '"'},
        {"&apos;", '\''},
        {"&amp;", '&'},
        {"&gt;", '>'},
        {"&lt;", '<'},
        {"&frasl;", '/'}
    };
    std::string result;
    result.reserve(text.size());
    std::size_t i = 0;
    while (i < text.size()) {
        if (text[i] == '&') {
            bool matched = false;
            for (const auto& kv : entityMap) {
                const std::string& entity = kv.first;
                char ch = kv.second;
                if (i + entity.size() <= text.size() && text.compare(i, entity.size(), entity) == 0) {
                    result.push_back(ch);
                    i += entity.size();
                    matched = true;
                    break;
                }
            }
            if (!matched) {
                result.push_back('&');
                ++i;
            }
        } else {
            result.push_back(text[i]);
            ++i;
        }
    }
    return result;
}

