int findMinFibonacciNumbers(long long k) {
    std::vector<long long> fib = {1, 1};
    while (fib.back() < k) {
        fib.push_back(fib.back() + fib[fib.size() - 2]);
    }
    int count = 0;
    long long remaining = k;
    while (remaining > 0) {
        int left = 0;
        int right = static_cast<int>(fib.size()) - 1;
        while (left < right) {
            int mid = (left + right + 1) / 2;
            if (fib[mid] <= remaining) left = mid;
            else right = mid - 1;
        }
        remaining -= fib[left];
        ++count;
    }
    return count;
}

