int restoreArray(const std::string& s, long long k) {
    const int MOD = 1000000007;
    int n = static_cast<int>(s.size());
    int maxLen = static_cast<int>(std::to_string(k).size());
    std::vector<int> dp(n + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int len = 1; len <= maxLen; ++len) {
            if (i - len < 0) break;
            if (s[i - len] == '0') continue;
            std::string sub = s.substr(i - len, len);
            long long val = std::stoll(sub);
            if (val > k) break;
            dp[i] = (dp[i] + dp[i - len]) % MOD;
        }
    }
    return dp[n];
}

