int numOfWays(int n) {
    const long long MOD = 1000000007LL;
    long long same = 6;
    long long diff = 6;
    for (int i = 2; i <= n; ++i) {
        long long newSame = (same * 3 + diff * 2) % MOD;
        long long newDiff = (same * 2 + diff * 2) % MOD;
        same = newSame;
        diff = newDiff;
    }
    return static_cast<int>((same + diff) % MOD);
}

