std::string getHappyString(int n, int k) {
    long long total = 3LL << (n - 1);
    if (k > total) return "";
    std::string res;
    long long block = 1LL << (n - 1);
    int idx = (k - 1) / block;
    char first = 'a' + idx;
    res.push_back(first);
    k = (k - 1) % block + 1;
    char prev = first;
    for (int i = 2; i <= n; ++i) {
        block = 1LL << (n - i);
        std::vector<char> opts;
        for (char c = 'a'; c <= 'c'; ++c) {
            if (c != prev) opts.push_back(c);
        }
        if (k <= block) {
            res.push_back(opts[0]);
        } else {
            res.push_back(opts[1]);
            k -= block;
        }
        prev = res.back();
    }
    return res;
}

