int minNumberOfFrogs(const std::string& croakOfFrogs) {
    std::unordered_map<char, int> map = {{'c', 0}, {'r', 1}, {'o', 2}, {'a', 3}, {'k', 4}};
    std::vector<int> cnt(5, 0);
    int frogs = 0;
    int maxFrogs = 0;
    for (char ch : croakOfFrogs) {
        auto it = map.find(ch);
        if (it == map.end()) {
            return -1;
        }
        int idx = it->second;
        cnt[idx]++;
        if (idx > 0 && cnt[idx] > cnt[idx - 1]) {
            return -1;
        }
        if (idx == 0) {
            ++frogs;
            if (frogs > maxFrogs) {
                maxFrogs = frogs;
            }
        }
        if (idx == 4) {
            --frogs;
            for (int i = 0; i < 5; ++i) {
                --cnt[i];
            }
        }
    }
    if (frogs != 0) {
        return -1;
    }
    return maxFrogs;
}

#include <bits/stdc++.h>
#include <vector>

int numOfArrays(int n, int m, int k) {
    const int MOD = 1000000007;
    if (k == 0) return 0;
    std::vector<std::vector<std::vector<int>>> dp(n + 1,
        std::vector<std::vector<int>>(m + 1, std::vector<int>(k + 1, 0)));
    for (int v = 1; v <= m; ++v) {
        if (k >= 1) dp[1][v][1] = 1;
    }
    for (int i = 1; i < n; ++i) {
        for (int cur = 1; cur <= m; ++cur) {
            for (int cnt = 1; cnt <= k; ++cnt) {
                int ways = dp[i][cur][cnt];
                if (!ways) continue;
                long long add = 1LL * ways * cur % MOD;
                dp[i + 1][cur][cnt] = (dp[i + 1][cur][cnt] + static_cast<int>(add)) % MOD;
                if (cnt + 1 <= k) {
                    for (int nxt = cur + 1; nxt <= m; ++nxt) {
                        dp[i + 1][nxt][cnt + 1] += ways;
                        if (dp[i + 1][nxt][cnt + 1] >= MOD) dp[i + 1][nxt][cnt + 1] -= MOD;
                    }
                }
            }
        }
    }
    int ans = 0;
    for (int cur = 1; cur <= m; ++cur) {
        ans += dp[n][cur][k];
        if (ans >= MOD) ans -= MOD;
    }
    return ans;
}

