int maxScore(const std::string& s) {
    int n = static_cast<int>(s.size());
    int totalOnes = 0;
    for (int i = 0; i < n; ++i) {
        if (s[i] == '1') ++totalOnes;
    }

    int zerosLeft = 0;
    int onesSeen = 0;
    int maxScore = 0;

    for (int i = 0; i < n - 1; ++i) {
        if (s[i] == '0') ++zerosLeft;
        else ++onesSeen;
        int score = zerosLeft + (totalOnes - onesSeen);
        if (score > maxScore) maxScore = score;
    }
    return maxScore;
}

