std::vector<int> findDiagonalOrder(const std::vector<std::vector<int>>& nums) {
    std::vector<std::vector<int>> buckets;
    for (size_t i = 0; i < nums.size(); ++i) {
        const std::vector<int>& row = nums[i];
        for (size_t j = 0; j < row.size(); ++j) {
            size_t d = i + j;
            if (buckets.size() <= d) {
                buckets.resize(d + 1);
            }
            buckets[d].push_back(row[j]);
        }
    }
    std::vector<int> result;
    for (size_t d = 0; d < buckets.size(); ++d) {
        const std::vector<int>& diag = buckets[d];
        if (diag.empty()) continue;
        for (size_t k = diag.size(); k-- > 0;) {
            result.push_back(diag[k]);
        }
    }
    return result;
}

