int constrainedSubsequenceSum(const std::vector<int>& nums, int k) {
    if (nums.empty()) return 0;
    size_t n = nums.size();
    std::vector<int> dp(n);
    std::deque<int> dq;
    dp[0] = nums[0];
    int answer = dp[0];
    dq.push_back(0);
    for (size_t i = 1; i < n; ++i) {
        while (!dq.empty() && dq.front() < static_cast<int>(i) - k) dq.pop_front();
        int bestPrev = dp[dq.front()] > 0 ? dp[dq.front()] : 0;
        dp[i] = nums[i] + bestPrev;
        if (dp[i] > answer) answer = dp[i];
        while (!dq.empty() && dp[dq.back()] <= dp[i]) dq.pop_back();
        dq.push_back(i);
    }
    return answer;
}

