long long maxScore(const std::vector<int>& cardPoints, int k) {
    size_t n = cardPoints.size();
    long long total = 0;
    for (int v : cardPoints) total += v;
    size_t windowSize = n - static_cast<size_t>(k);
    if (windowSize == 0) return total;
    long long windowSum = 0;
    for (size_t i = 0; i < windowSize; ++i) windowSum += cardPoints[i];
    long long minWindowSum = windowSum;
    for (size_t i = windowSize; i < n; ++i) {
        windowSum += cardPoints[i] - cardPoints[i - windowSize];
        if (windowSum < minWindowSum) minWindowSum = windowSum;
    }
    return total - minWindowSum;
}

