int maxDiff(int num) {
    std::string s = std::to_string(num);
    // Compute maximal possible number
    char firstNot9 = 0;
    for (char c : s) {
        if (c != '9') {
            firstNot9 = c;
            break;
        }
    }
    std::string maxStr = s;
    if (firstNot9) {
        for (char &c : maxStr) {
            if (c == firstNot9) c = '9';
        }
    }
    long long maxVal = std::stoll(maxStr);
    // Compute minimal possible number
    std::string minStr = s;
    if (s[0] != '1') {
        char d = s[0];
        for (char &c : minStr) {
            if (c == d) c = '1';
        }
    } else {
        char target = 0;
        for (size_t i = 1; i < s.size(); ++i) {
            if (s[i] != '0' && s[i] != s[0]) {
                target = s[i];
                break;
            }
        }
        if (target) {
            for (char &c : minStr) {
                if (c == target) c = '0';
            }
        }
    }
    long long minVal = std::stoll(minStr);
    return static_cast<int>(maxVal - minVal);
}

