int numberWays(const std::vector<std::vector<int>>& hats) {
    const int MOD = 1000000007;
    int n = static_cast<int>(hats.size());
    int totalMask = 1 << n;

    std::vector<std::vector<int>> peopleForHat(41);
    for (int person = 0; person < n; ++person) {
        for (int h : hats[person]) {
            peopleForHat[h].push_back(person);
        }
    }

    std::vector<int> dp(totalMask, 0);
    dp[0] = 1;

    for (int hat = 1; hat <= 40; ++hat) {
        const std::vector<int>& candidates = peopleForHat[hat];
        if (candidates.empty()) continue;

        for (int mask = totalMask - 1; mask >= 0; --mask) {
            int curWays = dp[mask];
            if (curWays == 0) continue;

            for (int p : candidates) {
                if ((mask & (1 << p)) == 0) {
                    int newMask = mask | (1 << p);
                    dp[newMask] = (dp[newMask] + curWays) % MOD;
                }
            }
        }
    }

    return dp[totalMask - 1];
}

