int kthSmallestSum(const std::vector<std::vector<int>>& mat, int k) {
    struct Node {
        long long total;
        size_t i;
        size_t j;
    };
    struct Cmp {
        bool operator()(const Node& a, const Node& b) const {
            return a.total > b.total;
        }
    };
    std::vector<int> sums = mat[0];
    for (size_t rowIdx = 1; rowIdx < mat.size(); ++rowIdx) {
        const std::vector<int>& row = mat[rowIdx];
        std::priority_queue<Node, std::vector<Node>, Cmp> heap;
        size_t limit = std::min(static_cast<size_t>(k), sums.size());
        for (size_t i = 0; i < limit; ++i) {
            heap.push(Node{static_cast<long long>(sums[i]) + row[0], i, 0});
        }
        std::vector<int> newSums;
        newSums.reserve(k);
        while (newSums.size() < static_cast<size_t>(k) && !heap.empty()) {
            Node cur = heap.top();
            heap.pop();
            newSums.push_back(static_cast<int>(cur.total));
            if (cur.j + 1 < row.size()) {
                heap.push(Node{static_cast<long long>(sums[cur.i]) + row[cur.j + 1], cur.i, cur.j + 1});
            }
        }
        sums.swap(newSums);
    }
    return sums[k - 1];
}

