long long countTriplets(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    std::vector<int> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] ^ arr[i];
    }
    std::unordered_map<int, std::pair<long long, long long>> mp;
    long long ans = 0;
    for (int idx = 0; idx <= n; ++idx) {
        int val = pref[idx];
        auto it = mp.find(val);
        if (it != mp.end()) {
            long long cnt = it->second.first;
            long long sumPos = it->second.second;
            ans += cnt * (static_cast<long long>(idx) - 1) - sumPos;
        }
        mp[val].first += 1;
        mp[val].second += idx;
    }
    return ans;
}

