int minTime(int n, const std::vector<std::vector<int>>& edges, const std::vector<bool>& hasApple) {
    std::vector<std::vector<int>> graph(n);
    for (const auto& e : edges) {
        int a = e[0];
        int b = e[1];
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    std::function<int(int, int)> dfs = [&](int node, int parent) -> int {
        int timeNeeded = 0;
        for (int neigh : graph[node]) {
            if (neigh == parent) continue;
            int childTime = dfs(neigh, node);
            if (childTime > 0 || hasApple[neigh]) {
                timeNeeded += childTime + 2;
            }
        }
        return timeNeeded;
    };
    return dfs(0, -1);
}

#include <bits/stdc++.h>
int ways(std::vector<std::string> pizza, int k) {
    const int MOD = 1000000007;
    int rows = pizza.size();
    int cols = pizza[0].size();
    std::vector<std::vector<int>> pref(rows + 1, std::vector<int>(cols + 1, 0));
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            pref[i + 1][j + 1] = pref[i][j + 1] + pref[i + 1][j] - pref[i][j] + (pizza[i][j] == 'A' ? 1 : 0);
        }
    }
    auto hasApple = [&](int r1, int c1, int r2, int c2) -> bool {
        int sum = pref[r2 + 1][c2 + 1] - pref[r1][c2 + 1] - pref[r2 + 1][c1] + pref[r1][c1];
        return sum > 0;
    };
    std::vector<std::vector<std::vector<int>>> dp(rows, std::vector<std::vector<int>>(cols, std::vector<int>(k + 1, -1)));
    std::function<int(int,int,int)> dfs = [&](int r, int c, int cuts) -> int {
        if (dp[r][c][cuts] != -1) return dp[r][c][cuts];
        if (!hasApple(r, c, rows - 1, cols - 1)) return dp[r][c][cuts] = 0;
        if (cuts == 1) return dp[r][c][cuts] = 1;
        long long ans = 0;
        for (int nr = r + 1; nr < rows; ++nr) {
            if (hasApple(r, c, nr - 1, cols - 1)) {
                ans += dfs(nr, c, cuts - 1);
                if (ans >= MOD) ans -= MOD;
            }
        }
        for (int nc = c + 1; nc < cols; ++nc) {
            if (hasApple(r, c, rows - 1, nc - 1)) {
                ans += dfs(r, nc, cuts - 1);
                if (ans >= MOD) ans -= MOD;
            }
        }
        return dp[r][c][cuts] = (int)(ans % MOD);
    };
    return dfs(0, 0, k);
}

