std::string rearrangeWords(const std::string& text) {
    std::vector<std::string> originalWords;
    std::string token;
    std::istringstream iss(text);
    while (std::getline(iss, token, ' ')) {
        originalWords.push_back(token);
    }

    std::vector<std::string> lowerWords;
    lowerWords.reserve(originalWords.size());
    for (const auto& w : originalWords) {
        std::string lw = w;
        for (char& ch : lw) {
            ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        }
        lowerWords.push_back(std::move(lw));
    }

    struct Item {
        std::string word;
        std::size_t idx;
    };
    std::vector<Item> indexed;
    indexed.reserve(lowerWords.size());
    for (std::size_t i = 0; i < lowerWords.size(); ++i) {
        indexed.push_back({lowerWords[i], i});
    }

    std::sort(indexed.begin(), indexed.end(),
        [](const Item& a, const Item& b) {
            if (a.word.size() != b.word.size()) {
                return a.word.size() < b.word.size();
            }
            return a.idx < b.idx;
        });

    std::vector<std::string> sorted;
    sorted.reserve(indexed.size());
    for (const auto& obj : indexed) {
        sorted.push_back(obj.word);
    }

    if (!sorted.empty() && !sorted[0].empty()) {
        sorted[0][0] = static_cast<char>(std::toupper(static_cast<unsigned char>(sorted[0][0])));
    }

    std::string result;
    for (std::size_t i = 0; i < sorted.size(); ++i) {
        if (i) result.push_back(' ');
        result += sorted[i];
    }
    return result;
}

