std::string largestNumber(const std::vector<int>& cost, int target) {
    std::vector<int> dpLen(target + 1, -1);
    dpLen[0] = 0;
    for (int i = 1; i <= target; ++i) {
        for (int d = 1; d <= 9; ++d) {
            int c = cost[d - 1];
            if (i >= c && dpLen[i - c] != -1) {
                if (dpLen[i] < dpLen[i - c] + 1) {
                    dpLen[i] = dpLen[i - c] + 1;
                }
            }
        }
    }
    if (dpLen[target] == -1) return "0";
    int remaining = target;
    int length = dpLen[target];
    std::string result;
    for (int d = 9; d >= 1; --d) {
        int c = cost[d - 1];
        while (remaining >= c && dpLen[remaining - c] == length - 1) {
            result.push_back('0' + d);
            remaining -= c;
            --length;
        }
    }
    return result;
}

