#include <bits/stdc++.h>
#include <vector>
#include <cmath>
#include <algorithm>

int maxDarts(const std::vector<std::vector<double>>& darts, double r) {
    const int n = static_cast<int>(darts.size());
    if (n == 0) return 0;
    const double TWO_PI = std::acos(-1.0) * 2.0;
    const double EPS = 1e-9;
    int best = 1;

    for (int i = 0; i < n; ++i) {
        std::vector<std::pair<double, int>> events;

        for (int j = 0; j < n; ++j) {
            if (i == j) continue;
            double dx = darts[j][0] - darts[i][0];
            double dy = darts[j][1] - darts[i][1];
            double d = std::hypot(dx, dy);
            if (d > 2.0 * r + EPS) continue;

            double theta = std::atan2(dy, dx);
            double delta = std::acos(d / (2.0 * r));

            double start = theta - delta;
            double end = theta + delta;

            if (start < 0.0) start += TWO_PI;
            if (end < 0.0) end += TWO_PI;
            if (start >= TWO_PI) start -= TWO_PI;
            if (end >= TWO_PI) end -= TWO_PI;

            if (start > end) {
                events.emplace_back(start, 1);
                events.emplace_back(TWO_PI, -1);
                events.emplace_back(0.0, 1);
                events.emplace_back(end, -1);
            } else {
                events.emplace_back(start, 1);
                events.emplace_back(end, -1);
            }
        }

        std::sort(events.begin(), events.end(),
            [EPS](const std::pair<double, int>& a, const std::pair<double, int>& b) {
                if (std::fabs(a.first - b.first) > EPS) return a.first < b.first;
                return a.second > b.second;
            });

        int cur = 0;
        for (const auto& ev : events) {
            cur += ev.second;
            if (cur + 1 > best) best = cur + 1;
        }
    }

    return best;
}

