std::vector<bool> checkIfPrerequisite(int numCourses, const std::vector<std::vector<int>>& prerequisites, const std::vector<std::vector<int>>& queries) {
    std::vector<std::vector<bool>> reach(numCourses, std::vector<bool>(numCourses, false));
    for (const auto& edge : prerequisites) {
        int a = edge[0];
        int b = edge[1];
        reach[a][b] = true;
    }
    for (int k = 0; k < numCourses; ++k) {
        for (int i = 0; i < numCourses; ++i) {
            if (reach[i][k]) {
                for (int j = 0; j < numCourses; ++j) {
                    if (reach[k][j]) {
                        reach[i][j] = true;
                    }
                }
            }
        }
    }
    std::vector<bool> answer;
    answer.reserve(queries.size());
    for (const auto& q : queries) {
        int u = q[0];
        int v = q[1];
        answer.push_back(reach[u][v]);
    }
    return answer;
}

