double maxDotProduct(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::size_t m = nums1.size();
    std::size_t n = nums2.size();
    std::vector<std::vector<double>> dp(m + 1, std::vector<double>(n + 1, -std::numeric_limits<double>::infinity()));
    for (std::size_t i = 1; i <= m; ++i) {
        for (std::size_t j = 1; j <= n; ++j) {
            double prod = static_cast<double>(nums1[i - 1]) * static_cast<double>(nums2[j - 1]);
            dp[i][j] = std::max({dp[i - 1][j - 1] + prod, prod, dp[i - 1][j], dp[i][j - 1]});
        }
    }
    return dp[m][n];
}

