long long maxArea(int h, int w, std::vector<int> horizontalCuts, std::vector<int> verticalCuts) {
    const long long MOD = 1000000007LL;
    std::sort(horizontalCuts.begin(), horizontalCuts.end());
    std::sort(verticalCuts.begin(), verticalCuts.end());

    long long maxHeight = std::max<long long>(horizontalCuts[0], h - horizontalCuts.back());
    for (size_t i = 1; i < horizontalCuts.size(); ++i) {
        long long gap = static_cast<long long>(horizontalCuts[i]) - horizontalCuts[i - 1];
        if (gap > maxHeight) maxHeight = gap;
    }

    long long maxWidth = std::max<long long>(verticalCuts[0], w - verticalCuts.back());
    for (size_t i = 1; i < verticalCuts.size(); ++i) {
        long long gap = static_cast<long long>(verticalCuts[i]) - verticalCuts[i - 1];
        if (gap > maxWidth) maxWidth = gap;
    }

    return (maxHeight % MOD) * (maxWidth % MOD) % MOD;
}

