int cherryPickup(std::vector<std::vector<int>>& grid) {
    int rows = grid.size();
    int cols = grid[0].size();
    const int NEG = -1000000000;
    std::vector<std::vector<int>> dp(cols, std::vector<int>(cols, NEG));
    dp[0][cols - 1] = grid[0][0] + (cols == 1 ? 0 : grid[0][cols - 1]);
    for (int i = 1; i < rows; ++i) {
        std::vector<std::vector<int>> ndp(cols, std::vector<int>(cols, NEG));
        for (int c1 = 0; c1 < cols; ++c1) {
            for (int c2 = 0; c2 < cols; ++c2) {
                if (dp[c1][c2] == NEG) continue;
                for (int d1 = -1; d1 <= 1; ++d1) {
                    int nc1 = c1 + d1;
                    if (nc1 < 0 || nc1 >= cols) continue;
                    for (int d2 = -1; d2 <= 1; ++d2) {
                        int nc2 = c2 + d2;
                        if (nc2 < 0 || nc2 >= cols) continue;
                        int val = dp[c1][c2] + grid[i][nc1];
                        if (nc1 != nc2) val += grid[i][nc2];
                        ndp[nc1][nc2] = std::max(ndp[nc1][nc2], val);
                    }
                }
            }
        }
        dp.swap(ndp);
    }
    int ans = 0;
    for (int c1 = 0; c1 < cols; ++c1)
        for (int c2 = 0; c2 < cols; ++c2)
            ans = std::max(ans, dp[c1][c2]);
    return ans;
}

