using std::vector;

static unsigned long long C[61][61];

static void initComb() {
    for (int i = 0; i <= 60; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j) C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
    }
}

double getProbability(vector<int> balls) {
    initComb();
    int k = static_cast<int>(balls.size());
    int total = 0;
    for (int v : balls) total += v;
    int n = total / 2;
    unsigned long long numerator = 0, denominator = 0;
    std::function<void(int,int,int,int,unsigned long long)> dfs = [&](int idx, int taken, int d1, int d2, unsigned long long ways) {
        if (idx == k) {
            if (taken == n) {
                denominator += ways;
                if (d1 == d2) numerator += ways;
            }
            return;
        }
        int cnt = balls[idx];
        for (int x = 0; x <= cnt; ++x) {
            int ntaken = taken + x;
            if (ntaken > n) continue;
            int nd1 = d1 + (x > 0);
            int nd2 = d2 + ((cnt - x) > 0);
            unsigned long long nways = ways * C[cnt][x];
            dfs(idx + 1, ntaken, nd1, nd2, nways);
        }
    };
    dfs(0, 0, 0, 0, 1ULL);
    double prob = static_cast<double>(numerator) / static_cast<double>(denominator);
    return std::round(prob * 1e5) / 1e5;
}

