bool hasAllCodes(const std::string& s, int k) {
    if (s.size() < static_cast<size_t>(k)) return false;
    int totalCodes = 1 << k;
    std::unordered_set<int> seen;
    int mask = totalCodes - 1;
    int hash = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        hash = ((hash << 1) & mask) | (s[i] - '0');
        if (i >= static_cast<size_t>(k - 1)) {
            seen.insert(hash);
            if (seen.size() == static_cast<size_t>(totalCodes)) return true;
        }
    }
    return seen.size() == static_cast<size_t>(totalCodes);
}

