int maxProduct(const std::vector<int>& nums) {
    int firstMax = std::numeric_limits<int>::min();
    int secondMax = std::numeric_limits<int>::min();
    for (size_t i = 0; i < nums.size(); ++i) {
        int val = nums[i];
        if (val > firstMax) {
            secondMax = firstMax;
            firstMax = val;
        } else if (val > secondMax) {
            secondMax = val;
        }
    }
    return (firstMax - 1) * (secondMax - 1);
}

