int minReorder(int n, const std::vector<std::vector<int>>& connections) {
    std::unordered_set<std::string> directed;
    for (const auto& edge : connections) {
        int a = edge[0];
        int b = edge[1];
        directed.insert(std::to_string(a) + "->" + std::to_string(b));
    }

    std::vector<std::vector<int>> adj(n);
    for (const auto& edge : connections) {
        int a = edge[0];
        int b = edge[1];
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    std::vector<bool> visited(n, false);
    std::vector<int> stack;
    stack.push_back(0);
    visited[0] = true;
    int reversals = 0;

    while (!stack.empty()) {
        int u = stack.back();
        stack.pop_back();
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                if (directed.find(std::to_string(u) + "->" + std::to_string(v)) != directed.end()) {
                    ++reversals;
                }
                stack.push_back(v);
            }
        }
    }

    return reversals;
}

