long long minCost(const std::vector<int>& houses, const std::vector<std::vector<int>>& cost, int m, int n, int target) {
    const long long INF = 1000000000000000LL;
    std::vector<std::vector<long long>> dp(target + 1, std::vector<long long>(n + 1, INF));

    if (houses[0] != 0) {
        dp[1][houses[0]] = 0;
    } else {
        for (int c = 1; c <= n; ++c) {
            dp[1][c] = cost[0][c - 1];
        }
    }

    for (int i = 1; i < m; ++i) {
        std::vector<std::vector<long long>> newDp(target + 1, std::vector<long long>(n + 1, INF));
        std::vector<int> possibleColors;
        if (houses[i] != 0) {
            possibleColors.push_back(houses[i]);
        } else {
            possibleColors.reserve(n);
            for (int c = 1; c <= n; ++c) possibleColors.push_back(c);
        }

        for (int prevT = 1; prevT <= target; ++prevT) {
            for (int prevC = 1; prevC <= n; ++prevC) {
                long long prevCost = dp[prevT][prevC];
                if (prevCost == INF) continue;
                for (int curC : possibleColors) {
                    long long addCost = (houses[i] == 0) ? cost[i][curC - 1] : 0;
                    int curT = (curC == prevC) ? prevT : prevT + 1;
                    if (curT > target) continue;
                    long long total = prevCost + addCost;
                    if (total < newDp[curT][curC]) newDp[curT][curC] = total;
                }
            }
        }
        dp.swap(newDp);
    }

    long long answer = INF;
    for (int c = 1; c <= n; ++c) {
        answer = std::min(answer, dp[target][c]);
    }
    return answer == INF ? -1 : answer;
}

