std::vector<int> strongestValues(const std::vector<int>& arr, int k) {
    std::vector<int> sorted = arr;
    std::sort(sorted.begin(), sorted.end());
    int n = static_cast<int>(sorted.size());
    int centre = sorted[(n - 1) / 2];

    int left = 0;
    int right = n - 1;
    std::vector<int> result;
    result.reserve(k);

    while (static_cast<int>(result.size()) < k) {
        int leftDiff = std::abs(sorted[left] - centre);
        int rightDiff = std::abs(sorted[right] - centre);

        if (rightDiff > leftDiff || (rightDiff == leftDiff && sorted[right] > sorted[left])) {
            result.push_back(sorted[right]);
            --right;
        } else {
            result.push_back(sorted[left]);
            ++left;
        }
    }

    return result;
}

