int findLeastNumOfUniqueInts(std::vector<int>& arr, int k) {
    std::unordered_map<int, int> freq;
    for (int v : arr) {
        ++freq[v];
    }
    std::vector<int> counts;
    counts.reserve(freq.size());
    for (const auto& p : freq) {
        counts.push_back(p.second);
    }
    std::sort(counts.begin(), counts.end());
    int unique = static_cast<int>(counts.size());
    for (int cnt : counts) {
        if (k >= cnt) {
            k -= cnt;
            --unique;
        } else {
            break;
        }
    }
    return unique;
}

#include <bits/stdc++.h>
int minSumOfLengths(std::vector<int>& arr, int target) {
    const int INF = 1e9;
    int n = arr.size();
    std::vector<int> leftIdx(n, -1);
    std::vector<int> lenAtRight(n, INF);
    long long sum = 0;
    int left = 0;
    for (int right = 0; right < n; ++right) {
        sum += arr[right];
        while (sum > target && left <= right) {
            sum -= arr[left];
            ++left;
        }
        if (sum == target) {
            leftIdx[right] = left;
            lenAtRight[right] = right - left + 1;
        }
    }
    std::vector<int> bestPrefix(n, INF);
    int best = INF;
    for (int i = 0; i < n; ++i) {
        if (lenAtRight[i] < INF) best = std::min(best, lenAtRight[i]);
        bestPrefix[i] = best;
    }
    int answer = INF;
    for (int i = 0; i < n; ++i) {
        if (leftIdx[i] != -1) {
            int l = leftIdx[i];
            if (l > 0 && bestPrefix[l - 1] < INF) {
                answer = std::min(answer, (i - l + 1) + bestPrefix[l - 1]);
            }
        }
    }
    return answer == INF ? -1 : answer;
}

