long long allocateMailboxes(std::vector<int> houses, int k) {
    std::sort(houses.begin(), houses.end());
    int n = houses.size();
    if (k >= n) return 0;
    std::vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + houses[i];
    }
    std::vector<std::vector<long long>> cost(n, std::vector<long long>(n, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = i; j < n; ++j) {
            int mid = (i + j) / 2;
            long long left = (long long)houses[mid] * (mid - i) - (prefix[mid] - prefix[i]);
            long long right = (prefix[j + 1] - prefix[mid + 1]) - (long long)houses[mid] * (j - mid);
            cost[i][j] = left + right;
        }
    }
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<std::vector<long long>> dp(k + 1, std::vector<long long>(n, INF));
    for (int i = 0; i < n; ++i) dp[1][i] = cost[0][i];
    for (int m = 2; m <= k; ++m) {
        for (int i = m - 1; i < n; ++i) {
            long long best = INF;
            for (int p = m - 2; p < i; ++p) {
                long long cur = dp[m - 1][p] + cost[p + 1][i];
                if (cur < best) best = cur;
            }
            dp[m][i] = best;
        }
    }
    return dp[k][n - 1];
}

