std::vector<std::string> getFolderNames(const std::vector<std::string>& names) {
    std::unordered_map<std::string, int> nextSuffix;
    std::vector<std::string> result;
    result.reserve(names.size());

    for (size_t i = 0; i < names.size(); ++i) {
        const std::string& original = names[i];
        if (nextSuffix.find(original) == nextSuffix.end()) {
            result.push_back(original);
            nextSuffix[original] = 1;
        } else {
            int k = nextSuffix[original];
            std::string candidate = original + '(' + std::to_string(k) + ')';
            while (nextSuffix.find(candidate) != nextSuffix.end()) {
                ++k;
                candidate = original + '(' + std::to_string(k) + ')';
            }
            result.push_back(candidate);
            nextSuffix[original] = k + 1;
            nextSuffix[candidate] = 1;
        }
    }

    return result;
}

