int minDays(const std::vector<int>& bloomDay, int m, int k) {
    if (static_cast<long long>(m) * k > static_cast<long long>(bloomDay.size())) return -1;
    int low = *std::min_element(bloomDay.begin(), bloomDay.end());
    int high = *std::max_element(bloomDay.begin(), bloomDay.end());
    auto canMake = [&](int day) {
        int bouquets = 0, consecutive = 0;
        for (int bd : bloomDay) {
            if (bd <= day) {
                ++consecutive;
                if (consecutive == k) {
                    ++bouquets;
                    consecutive = 0;
                    if (bouquets >= m) return true;
                }
            } else {
                consecutive = 0;
            }
        }
        return false;
    };
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (canMake(mid)) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

