bool isPathCrossing(const std::string& path) {
    int x = 0, y = 0;
    std::unordered_set<std::string> visited;
    visited.insert("0,0");
    for (size_t i = 0; i < path.size(); ++i) {
        char dir = path[i];
        if (dir == 'N') ++y;
        else if (dir == 'S') --y;
        else if (dir == 'E') ++x;
        else if (dir == 'W') --x;
        std::string key = std::to_string(x) + "," + std::to_string(y);
        if (visited.find(key) != visited.end()) return true;
        visited.insert(key);
    }
    return false;
}

