int kthAncestor(const std::vector<int>& parent, int node, int k) {
    int n = static_cast<int>(parent.size());

    int maxPower = 0;
    while ((1 << maxPower) <= n) ++maxPower;

    std::vector<std::vector<int>> up(maxPower, std::vector<int>(n, -1));

    for (int v = 0; v < n; ++v) up[0][v] = parent[v];

    for (int p = 1; p < maxPower; ++p) {
        for (int v = 0; v < n; ++v) {
            int mid = up[p - 1][v];
            up[p][v] = (mid == -1) ? -1 : up[p - 1][mid];
        }
    }

    int cur = node;
    int bit = 0;
    while (k > 0 && cur != -1) {
        if (k & 1) cur = up[bit][cur];
        k >>= 1;
        ++bit;
    }
    return cur;
}

