int numSubseq(std::vector<int> nums, int target) {
    const int MOD = 1000000007;
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::sort(nums.begin(), nums.end());
    std::vector<int> pow2(n);
    pow2[0] = 1;
    for (int i = 1; i < n; ++i) {
        pow2[i] = static_cast<int>((static_cast<long long>(pow2[i - 1]) * 2) % MOD);
    }
    int left = 0;
    int right = n - 1;
    int ans = 0;
    while (left <= right) {
        if (static_cast<long long>(nums[left]) + nums[right] <= target) {
            ans = (ans + pow2[right - left]) % MOD;
            ++left;
        } else {
            --right;
        }
    }
    return ans;
}

#include <bits/stdc++.h>
std::vector<int> avoidFlood(const std::vector<int>& rains) {
    int n = rains.size();
    std::vector<int> ans(n, 1);
    std::unordered_map<int, int> lastRain;
    std::set<int> dryDays;
    for (int i = 0; i < n; ++i) {
        int lake = rains[i];
        if (lake == 0) {
            dryDays.insert(i);
            ans[i] = 1; // placeholder
        } else {
            if (lastRain.find(lake) != lastRain.end()) {
                int prevDay = lastRain[lake];
                auto it = dryDays.lower_bound(prevDay + 1);
                if (it == dryDays.end()) {
                    return {};
                }
                int dryIdx = *it;
                ans[dryIdx] = lake;
                dryDays.erase(it);
            }
            ans[i] = -1;
            lastRain[lake] = i;
        }
    }
    // remaining dry days can stay as 1 (any lake number)
    return ans;
}

