class DSU {
public:
    DSU(int n) : parent(n), rank(n, 0) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    bool unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return false;
        if (rank[rx] < rank[ry]) std::swap(rx, ry);
        parent[ry] = rx;
        if (rank[rx] == rank[ry]) ++rank[rx];
        return true;
    }
private:
    std::vector<int> parent;
    std::vector<int> rank;
};

struct Edge {
    int u, v, w, idx;
};

int mstWeight(int n, const std::vector<Edge>& edgesSorted, int skipIdx, int forceIdx) {
    DSU dsu(n);
    int total = 0;
    int used = 0;
    if (forceIdx != -1) {
        const Edge& e = edgesSorted[forceIdx];
        if (dsu.unite(e.u, e.v)) {
            total += e.w;
            ++used;
        }
    }
    for (size_t i = 0; i < edgesSorted.size(); ++i) {
        if ((int)i == skipIdx) continue;
        const Edge& e = edgesSorted[i];
        if (dsu.unite(e.u, e.v)) {
            total += e.w;
            ++used;
            if (used == n - 1) break;
        }
    }
    return (used == n - 1) ? total : INT_MAX;
}

std::vector<std::vector<int>> findCriticalAndPseudoCriticalEdges(int n, std::vector<std::vector<int>>& edges) {
    std::vector<Edge> edgesList;
    edgesList.reserve(edges.size());
    for (size_t i = 0; i < edges.size(); ++i) {
        edgesList.push_back({edges[i][0], edges[i][1], edges[i][2], (int)i});
    }
    std::vector<Edge> edgesSorted = edgesList;
    std::sort(edgesSorted.begin(), edgesSorted.end(), [](const Edge& a, const Edge& b) {
        return a.w < b.w;
    });
    // Map original index to position in sorted array
    std::vector<int> posInSorted(edges.size());
    for (size_t i = 0; i < edgesSorted.size(); ++i) {
        posInSorted[edgesSorted[i].idx] = (int)i;
    }
    int originalWeight = mstWeight(n, edgesSorted, -1, -1);
    std::vector<int> critical, pseudo;
    for (size_t i = 0; i < edgesList.size(); ++i) {
        int sortedIdx = posInSorted[i];
        // Critical test: skip this edge
        int wSkip = mstWeight(n, edgesSorted, sortedIdx, -1);
        if (wSkip > originalWeight) {
            critical.push_back((int)i);
        } else {
            // Pseudo‑critical test: force this edge
            int wForce = mstWeight(n, edgesSorted, -1, sortedIdx);
            if (wForce == originalWeight) {
                pseudo.push_back((int)i);
            }
        }
    }
    return {critical, pseudo};
}

