bool canPair(const std::vector<int>& arr, int k) {
    std::unordered_map<int, int> remainderCount;
    for (int val : arr) {
        int r = ((val % k) + k) % k;
        ++remainderCount[r];
    }
    for (const auto& kv : remainderCount) {
        int r = kv.first;
        int cnt = kv.second;
        if (r == 0) {
            if (cnt % 2 != 0) return false;
        } else if (k % 2 == 0 && r == k / 2) {
            if (cnt % 2 != 0) return false;
        } else {
            int complement = (k - r) % k;
            int complementCnt = 0;
            auto it = remainderCount.find(complement);
            if (it != remainderCount.end()) complementCnt = it->second;
            if (cnt != complementCnt) return false;
        }
    }
    return true;
}

