long long maxValueOfEquation(const std::vector<std::vector<int>>& points, int k) {
    int n = static_cast<int>(points.size());
    long long best = LLONG_MIN;
    std::deque<int> dq; // stores indices, decreasing (yi - xi)

    for (int j = 0; j < n; ++j) {
        int xj = points[j][0];
        int yj = points[j][1];

        while (!dq.empty() && xj - points[dq.front()][0] > k) {
            dq.pop_front();
        }

        if (!dq.empty()) {
            int i = dq.front();
            long long candidate = static_cast<long long>(points[i][1] - points[i][0]) + yj + xj;
            if (candidate > best) best = candidate;
        }

        long long curVal = static_cast<long long>(yj) - xj;
        while (!dq.empty() && static_cast<long long>(points[dq.back()][1] - points[dq.back()][0]) <= curVal) {
            dq.pop_back();
        }
        dq.push_back(j);
    }
    return best;
}

