std::vector<int> countSubTrees(int n, const std::vector<std::vector<int>>& edges, const std::string& labels) {
    std::vector<std::vector<int>> graph(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        graph[u].push_back(v);
        graph[v].push_back(u);
    }
    std::vector<int> answer(n, 0);
    std::function<std::array<int, 26>(int, int)> dfs = [&](int node, int parent) -> std::array<int, 26> {
        std::array<int, 26> freq{};
        freq.fill(0);
        for (int nxt : graph[node]) {
            if (nxt == parent) continue;
            std::array<int, 26> childFreq = dfs(nxt, node);
            for (int i = 0; i < 26; ++i) {
                freq[i] += childFreq[i];
            }
        }
        int idx = labels[node] - 'a';
        freq[idx] += 1;
        answer[node] = freq[idx];
        return freq;
    };
    dfs(0, -1);
    return answer;
}

