double bestPositionSum(const std::vector<std::vector<double>>& positions) {
    std::size_t n = positions.size();
    if (n == 0) return 0.0;

    double cx = 0.0, cy = 0.0;
    for (std::size_t i = 0; i < n; ++i) {
        cx += positions[i][0];
        cy += positions[i][1];
    }
    cx /= static_cast<double>(n);
    cy /= static_cast<double>(n);

    const double EPS = 1e-7;
    while (true) {
        double numX = 0.0, numY = 0.0, denom = 0.0;
        bool coincident = false;

        for (std::size_t i = 0; i < n; ++i) {
            double dx = cx - positions[i][0];
            double dy = cy - positions[i][1];
            double dist = std::hypot(dx, dy);
            if (dist == 0.0) {
                coincident = true;
                break;
            }
            double w = 1.0 / dist;
            numX += positions[i][0] * w;
            numY += positions[i][1] * w;
            denom += w;
        }

        if (coincident) break;

        double nextX = numX / denom;
        double nextY = numY / denom;

        if (std::hypot(nextX - cx, nextY - cy) < EPS) break;

        cx = nextX;
        cy = nextY;
    }

    double total = 0.0;
    for (std::size_t i = 0; i < n; ++i) {
        total += std::hypot(cx - positions[i][0], cy - positions[i][1]);
    }
    total = std::round(total * 1e5) / 1e5;
    return total;
}

