std::vector<std::string> maxNumOfSubstrings(const std::string& s) {
    int n = static_cast<int>(s.size());
    int left[26];
    int right[26];
    for (int i = 0; i < 26; ++i) {
        left[i] = -1;
        right[i] = -1;
    }
    for (int i = 0; i < n; ++i) {
        int idx = s[i] - 'a';
        if (left[idx] == -1) left[idx] = i;
        right[idx] = i;
    }
    std::vector<std::pair<int, int>> intervals;
    for (int i = 0; i < n; ++i) {
        int idx = s[i] - 'a';
        if (i != left[idx]) continue;
        int start = i;
        int end = right[idx];
        bool ok = true;
        for (int j = start; j <= end; ++j) {
            int curIdx = s[j] - 'a';
            if (left[curIdx] < start) {
                ok = false;
                break;
            }
            if (right[curIdx] > end) {
                end = right[curIdx];
            }
        }
        if (ok) intervals.emplace_back(start, end);
    }
    std::sort(intervals.begin(), intervals.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  return a.second < b.second;
              });
    std::vector<std::pair<int, int>> chosen;
    int lastEnd = -1;
    for (const auto& p : intervals) {
        if (p.first > lastEnd) {
            chosen.push_back(p);
            lastEnd = p.second;
        }
    }
    std::sort(chosen.begin(), chosen.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  int lenA = a.second - a.first;
                  int lenB = b.second - b.first;
                  if (lenA != lenB) return lenA < lenB;
                  return a.first < b.first;
              });
    std::vector<std::string> result;
    for (const auto& p : chosen) {
        result.push_back(s.substr(p.first, p.second - p.first + 1));
    }
    return result;
}

