    std::vector<bool> seenLeft(26, false);
    int distinctLeft = 0;

    for (std::size_t i = 0; i < n; ++i) {
        int idx = s[i] - 'a';
        if (!seenLeft[idx]) {
            seenLeft[idx] = true;
            ++distinctLeft;
