    std::vector<bool> seenRight(26, false);
    int distinctRight = 0;

    for (std::size_t i = n; i-- > 0;) {
        int idx = s[i] - 'a';
        if (!seenRight[idx]) {
            seenRight[idx] = true;
            ++distinctRight;
        }
        suffix[i] = distinctRight;
    }

    int goodSplits = 0;
    for (std::size_t i = 1; i < n; ++i) {
        if (prefix[i - 1] == suffix[i]) {
            ++goodSplits;
        }
    }
    return goodSplits;
}

