int minSwaps(const std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    std::vector<int> rightOne(n);
    for (int i = 0; i < n; ++i) {
        int pos = -1;
        for (int j = n - 1; j >= 0; --j) {
            if (grid[i][j] == 1) {
                pos = j;
                break;
            }
        }
        rightOne[i] = pos;
    }

    int steps = 0;
    for (int i = 0; i < n; ++i) {
        if (rightOne[i] <= i) continue;
        int j = i + 1;
        while (j < n && rightOne[j] > i) ++j;
        if (j == n) return -1;
        while (j > i) {
            std::swap(rightOne[j], rightOne[j - 1]);
            ++steps;
            --j;
        }
    }
    return steps;
}

