    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int countPairs(TreeNode* root, int distance) {
    int goodPairs = 0;
    std::function<std::vector<int>(TreeNode*)> dfs = [&](TreeNode* node) -> std::vector<int> {
        if (!node) return std::vector<int>{};
        if (!node->left && !node->right) return std::vector<int>{1};
        std::vector<int> leftDist = dfs(node->left);
        std::vector<int> rightDist = dfs(node->right);
        for (int l : leftDist) {
            for (int r : rightDist) {
                if (l + r <= distance) ++goodPairs;
            }
        }
        std::vector<int> up;
        up.reserve(leftDist.size() + rightDist.size());
        for (int d : leftDist) {
            if (d + 1 <= distance) up.push_back(d + 1);
        }
        for (int d : rightDist) {
            if (d + 1 <= distance) up.push_back(d + 1);
        }
        return up;
    };
    dfs(root);
    return goodPairs;
}

#include <bits/stdc++.h>
int getLengthOfOptimalCompression(std::string s, int k) {
    int n = static_cast<int>(s.size());
    const int INF = 1e9;
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(k + 1, INF));
    for (int j = 0; j <= k; ++j) dp[0][j] = 0;
    auto digitLen = [&](int cnt) {
        if (cnt == 1) return 0;
        if (cnt < 10) return 1;
        if (cnt < 100) return 2;
        return 3;
    };
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= k; ++j) {
            if (j > 0) dp[i][j] = std::min(dp[i][j], dp[i - 1][j - 1]);
            int cnt = 0, del = 0;
            for (int p = i - 1; p >= 0; --p) {
                if (s[p] == s[i - 1]) ++cnt;
                else ++del;
                if (del > j) break;
                int prev = dp[p][j - del];
                if (prev != INF) {
                    dp[i][j] = std::min(dp[i][j], prev + 1 + digitLen(cnt));
                }
            }
        }
    }
    int ans = INF;
    for (int j = 0; j <= k; ++j) ans = std::min(ans, dp[n][j]);
    return ans;
}

