bool canConvertStringInKMoves(const std::string& s, const std::string& t, int k) {
    std::vector<int> need(26, 0);
    for (size_t i = 0; i < s.size(); ++i) {
        int a = s[i] - 'a';
        int b = t[i] - 'a';
        if (a == b) continue;
        int diff = (b - a + 26) % 26;
        need[diff]++;
