int findWinner(const std::vector<int>& arr, int k) {
    if (k >= static_cast<int>(arr.size()) - 1) {
        int max = arr[0];
        for (size_t i = 1; i < arr.size(); ++i) {
            if (arr[i] > max) {
                max = arr[i];
            }
        }
        return max;
    }
    std::deque<int> queue(arr.begin(), arr.end());
    int cur = queue.front();
    queue.pop_front();
    int win = 0;
    while (win < k) {
        int next = queue.front();
        queue.pop_front();
        if (cur > next) {
            ++win;
            queue.push_back(next);
        } else {
            queue.push_back(cur);
            cur = next;
            win = 1;
        }
    }
    return cur;
}

