long long maxScore(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    const long long MOD = 1000000007LL;
    size_t i = 0, j = 0;
    long long sum1 = 0, sum2 = 0;
    long long answer = 0;

    while (i < nums1.size() && j < nums2.size()) {
        if (nums1[i] < nums2[j]) {
            sum1 += nums1[i];
            ++i;
        } else if (nums1[i] > nums2[j]) {
            sum2 += nums2[j];
            ++j;
        } else {
            answer = (answer + std::max(sum1, sum2) + nums1[i]) % MOD;
            sum1 = 0;
            sum2 = 0;
            ++i;
            ++j;
        }
    }

    while (i < nums1.size()) {
        sum1 += nums1[i];
        ++i;
    }
    while (j < nums2.size()) {
        sum2 += nums2[j];
        ++j;
    }

    answer = (answer + std::max(sum1, sum2)) % MOD;
    return answer;
}

