int findKthMissing(const std::vector<int>& arr, int k) {
    auto missingCount = [&](int i) {
        return arr[i] - (i + 1);
    };

    int left = 0;
    int right = static_cast<int>(arr.size()) - 1;

    while (left <= right) {
        int mid = (left + right) / 2;
        if (missingCount(mid) < k) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    int prevMissing = left > 0 ? missingCount(left - 1) : 0;
    int prevValue = left > 0 ? arr[left - 1] : 0;
    return prevValue + (k - prevMissing);
}

