    int mask = 0;
    int best = 0;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        int digit = s[i] - '0';
        mask ^= (1 << digit);
        best = std::max(best, i - first[mask]);
        for (int d = 0; d < 10; ++d) {
            int cand = mask ^ (1 << d);
            best = std::max(best, i - first[cand]);
        }
        if (first[mask] == INF) first[mask] = i;
    }
    return best;
}

