long long minCost(int n, const std::vector<int>& cuts) {
    std::vector<int> pos;
    pos.reserve(cuts.size() + 2);
    pos.push_back(0);
    std::vector<int> sortedCuts = cuts;
    std::sort(sortedCuts.begin(), sortedCuts.end());
    pos.insert(pos.end(), sortedCuts.begin(), sortedCuts.end());
    pos.push_back(n);
    int m = static_cast<int>(pos.size());
    std::vector<std::vector<long long>> dp(m, std::vector<long long>(m, 0));
    for (int len = 2; len < m; ++len) {
        for (int i = 0; i + len < m; ++i) {
            int j = i + len;
            long long best = LLONG_MAX;
            for (int k = i + 1; k < j; ++k) {
                long long cost = dp[i][k] + dp[k][j] + static_cast<long long>(pos[j] - pos[i]);
                if (cost < best) best = cost;
            }
            dp[i][j] = best;
        }
    }
    return dp[0][m - 1];
}

