    std::function<long long(long long)> dfs = [&](long long x) -> long long {
        if (x <= 1) return x;
        auto it = memo.find(x);
        if (it != memo.end()) return it->second;
        long long daysVia2 = x % 2 + dfs(x / 2);
        long long daysVia3 = x % 3 + dfs(x / 3);
