int stoneGameV(std::vector<int>& stoneValue) {
    int n = stoneValue.size();
    if (n <= 1) return 0;
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + stoneValue[i];
    std::vector<std::vector<long long>> dp(n, std::vector<long long>(n, 0));
    for (int len = 2; len <= n; ++len) {
        for (int l = 0; l + len - 1 < n; ++l) {
            int r = l + len - 1;
            long long best = 0;
            for (int k = l; k < r; ++k) {
                long long leftSum = pref[k + 1] - pref[l];
                long long rightSum = pref[r + 1] - pref[k + 1];
                long long cand = 0;
                if (leftSum < rightSum) {
                    cand = leftSum + dp[l][k];
                } else if (leftSum > rightSum) {
                    cand = rightSum + dp[k + 1][r];
                } else {
                    cand = leftSum + std::max(dp[l][k], dp[k + 1][r]);
                }
                if (cand > best) best = cand;
            }
            dp[l][r] = best;
        }
    }
    return static_cast<int>(dp[0][n - 1]);
}

