bool detectCycle(const std::vector<std::vector<char>>& grid) {
    int m = static_cast<int>(grid.size());
    if (m == 0) return false;
    int n = static_cast<int>(grid[0].size());
    std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));
    const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    std::function<bool(int, int, int, int, char)> dfs = [&](int x, int y, int px, int py, char ch) -> bool {
        visited[x][y] = true;
        for (const auto& d : dirs) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
            if (grid[nx][ny] != ch) continue;
            if (!visited[nx][ny]) {
                if (dfs(nx, ny, x, y, ch)) return true;
            } else if (nx != px || ny != py) {
                return true;
            }
        }
        return false;
    };
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (!visited[i][j]) {
                if (dfs(i, j, -1, -1, grid[i][j])) return true;
            }
        }
    }
    return false;
}

