struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

static const long long MOD = 1000000007LL;

static long long modPow(long long a, long long e) {
    long long res = 1;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

static void insertNode(TreeNode*& root, int val) {
    if (!root) {
        root = new TreeNode(val);
        return;
    }
    if (val < root->val) insertNode(root->left, val);
    else insertNode(root->right, val);
}

static std::vector<long long> fact, invFact;

static long long comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
}

static std::pair<int, long long> dfs(TreeNode* node) {
    if (!node) return {0, 1};
    auto left = dfs(node->left);
    auto right = dfs(node->right);
    int L = left.first, R = right.first;
    long long ways = left.second * right.second % MOD;
    ways = ways * comb(L + R, L) % MOD;
    return {L + R + 1, ways};
}

int numberOfWays(std::vector<int>& nums) {
    int n = nums.size();
    fact.resize(n + 1);
    invFact.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[n] = modPow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;

    TreeNode* root = nullptr;
    for (int v : nums) insertNode(root, v);
    auto result = dfs(root);
    long long ans = (result.second - 1 + MOD) % MOD;
    return static_cast<int>(ans);
}

