    if (static_cast<std::size_t>(m) * static_cast<std::size_t>(k) > n) return false;
    if (k == 1) return static_cast<std::size_t>(m) <= n;
    for (std::size_t i = 0; i <= n - static_cast<std::size_t>(m) * static_cast<std::size_t>(k); ++i) {
        int repeats = 1;
        while (repeats < k) {
