long long numberOfWays(const std::string& s) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(s.size());
    int totalOnes = 0;
    for (int i = 0; i < n; ++i) {
        if (s[i] == '1') ++totalOnes;
    }

    if (totalOnes % 3 != 0) return 0;

    if (totalOnes == 0) {
        long long ways = ((static_cast<long long>(n - 1) * (n - 2)) / 2) % MOD;
        return ways;
    }

    int target = totalOnes / 3;
    int onesSeen = 0;
    long long zerosAfterFirst = 0;
    long long zerosAfterSecond = 0;
    int i = 0;

    while (i < n) {
        if (s[i] == '1') ++onesSeen;
        if (onesSeen == target) {
            ++i;
            while (i < n && s[i] == '0') {
                ++zerosAfterFirst;
                ++i;
            }
            break;
        }
        ++i;
    }

    while (i < n) {
        if (s[i] == '1') ++onesSeen;
        if (onesSeen == 2 * target) {
            ++i;
            while (i < n && s[i] == '0') {
                ++zerosAfterSecond;
                ++i;
            }
            break;
        }
        ++i;
    }

    long long ways = ((zerosAfterFirst + 1) % MOD) * ((zerosAfterSecond + 1) % MOD) % MOD;
    return ways;
}

