int shortestSubarrayToRemove(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    if (n == 0) return 0;
    int prefixEnd = 0;
    while (prefixEnd + 1 < n && arr[prefixEnd] <= arr[prefixEnd + 1]) {
        ++prefixEnd;
    }
    if (prefixEnd == n - 1) return 0;
    int suffixStart = n - 1;
    while (suffixStart - 1 >= 0 && arr[suffixStart - 1] <= arr[suffixStart]) {
        --suffixStart;
    }
    int minRemove = std::min(n - prefixEnd - 1, suffixStart);
    int i = 0, j = suffixStart;
    while (i <= prefixEnd && j < n) {
        while (j < n && arr[j] < arr[i]) {
            ++j;
        }
        if (j < n) {
            minRemove = std::min(minRemove, j - i - 1);
        }
        ++i;
    }
    return minRemove;
}

