struct DSU {
    std::vector<int> parent;
    std::vector<int> rank;
    DSU(int size) : parent(size + 1), rank(size + 1, 0) {
        for (int i = 1; i <= size; ++i) parent[i] = i;
    }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return false;
        if (rank[ra] < rank[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) ++rank[ra];
        return true;
    }
};

int maxNumEdgesToRemove(int n, const std::vector<std::vector<int>>& edges) {
    DSU alice(n);
    DSU bob(n);
    int used = 0;
    for (const auto& e : edges) {
        int type = e[0], u = e[1], v = e[2];
        if (type == 3) {
            bool a = alice.unite(u, v);
            bool b = bob.unite(u, v);
            if (a || b) ++used;
        }
    }
    for (const auto& e : edges) {
        int type = e[0], u = e[1], v = e[2];
        if (type == 1) {
            if (alice.unite(u, v)) ++used;
        } else if (type == 2) {
            if (bob.unite(u, v)) ++used;
        }
    }
    auto compCount = [&](DSU& ds) {
        int cnt = 0;
        for (int i = 1; i <= n; ++i) {
            if (ds.find(i) == i) ++cnt;
        }
        return cnt;
    };
    if (compCount(alice) != 1 || compCount(bob) != 1) return -1;
    return static_cast<int>(edges.size()) - used;
}

