        long long sumInBlock = neededTime[i];
        std::size_t j = i + 1;
        while (j < colors.size() && colors[j] == colors[i]) {
            sumInBlock += neededTime[j];
            if (neededTime[j] > maxInBlock) {
                maxInBlock = neededTime[j];
            }
            ++j;
        }
        totalTime += sumInBlock - maxInBlock;
        i = j;
    }
    return totalTime;
}

