long long numberOfTriplets(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::unordered_map<long long, int> prodCount1;
    for (size_t i = 0; i < nums1.size(); ++i) {
        for (size_t j = i + 1; j < nums1.size(); ++j) {
            long long p = static_cast<long long>(nums1[i]) * nums1[j];
            ++prodCount1[p];
        }
    }
    std::unordered_map<long long, int> prodCount2;
    for (size_t i = 0; i < nums2.size(); ++i) {
        for (size_t j = i + 1; j < nums2.size(); ++j) {
            long long p = static_cast<long long>(nums2[i]) * nums2[j];
            ++prodCount2[p];
        }
    }
    long long ans = 0;
    for (int x : nums1) {
        long long sq = static_cast<long long>(x) * x;
        auto it = prodCount2.find(sq);
        if (it != prodCount2.end()) ans += it->second;
    }
    for (int x : nums2) {
        long long sq = static_cast<long long>(x) * x;
        auto it = prodCount1.find(sq);
        if (it != prodCount1.end()) ans += it->second;
    }
    return ans;
}

