int minCostConnectPoints(const std::vector<std::vector<int>>& points) {
    size_t n = points.size();
    std::vector<bool> visited(n, false);
    const long long INF = LLONG_MAX;
    std::vector<long long> minDist(n, INF);
    minDist[0] = 0;
    long long totalCost = 0;
    for (size_t i = 0; i < n; ++i) {
        int u = -1;
        long long best = INF;
        for (size_t j = 0; j < n; ++j) {
            if (!visited[j] && minDist[j] < best) {
                best = minDist[j];
                u = static_cast<int>(j);
            }
        }
        visited[u] = true;
        totalCost += best;
        for (size_t v = 0; v < n; ++v) {
            if (!visited[v]) {
                long long dist = static_cast<long long>(std::abs(points[u][0] - points[v][0])) +
                                 static_cast<long long>(std::abs(points[u][1] - points[v][1]));
                if (dist < minDist[v]) {
                    minDist[v] = dist;
                }
            }
        }
    }
    return static_cast<int>(totalCost);
}

