bool isTransformable(const std::string& s, const std::string& t) {
    std::size_t n = s.length();
    std::vector<std::deque<std::size_t>> pos(10);
    for (std::size_t i = 0; i < n; ++i) {
        int d = s[i] - '0';
        pos[d].push_back(i);
    }
    for (std::size_t i = 0; i < n; ++i) {
        int need = t[i] - '0';
        if (pos[need].empty()) {
            return false;
        }
        std::size_t idx = pos[need].front();
        pos[need].pop_front();
        for (int d = 0; d < need; ++d) {
            if (!pos[d].empty() && pos[d].front() < idx) {
                return false;
            }
        }
    }
    return true;
}

