long long sumOddLengthSubarrays(const std::vector<int>& arr) {
    std::size_t n = arr.size();
    long long total = 0;
    for (std::size_t i = 0; i < n; ++i) {
        long long left = static_cast<long long>(i) + 1;
        long long right = static_cast<long long>(n) - static_cast<long long>(i);
        long long oddSubarrays = (left * right + (left % 2) * (right % 2)) / 2;
        total += static_cast<long long>(arr[i]) * oddSubarrays;
    }
    return total;
}

#include <bits/stdc++.h>
int minSubarray(std::vector<int>& nums, int p) {
    long long total = 0;
    for (int x : nums) total += x;
    int need = total % p;
    if (need == 0) return 0;
    std::unordered_map<int, int> last;
    last.reserve(nums.size() * 2);
    last[0] = -1;
    int cur = 0;
    int ans = nums.size() + 1;
    for (int i = 0; i < (int)nums.size(); ++i) {
        cur = (cur + nums[i]) % p;
        int target = (cur - need + p) % p;
        auto it = last.find(target);
        if (it != last.end()) {
            int len = i - it->second;
            if (len < ans) ans = len;
        }
        last[cur] = i;
    }
    if (ans == nums.size() + 1) return -1;
    return ans;
}

