std::string reorderSpaces(const std::string& text) {
    int totalSpaces = 0;
    for (char ch : text) {
        if (ch == ' ') ++totalSpaces;
    }
    std::vector<std::string> words;
    std::istringstream iss(text);
    std::string w;
    while (iss >> w) {
        words.push_back(w);
    }
    int wordCount = static_cast<int>(words.size());
    if (wordCount == 1) {
        return words[0] + std::string(totalSpaces, ' ');
    }
    int spacesBetween = totalSpaces / (wordCount - 1);
    int extraSpaces = totalSpaces - spacesBetween * (wordCount - 1);
    std::string middle(spacesBetween, ' ');
    std::string result;
    for (int i = 0; i < wordCount; ++i) {
        result += words[i];
        if (i != wordCount - 1) {
            result += middle;
        }
    }
    result.append(extraSpaces, ' ');
    return result;
}

