int maxUniqueSplit(const std::string& s) {
    std::unordered_set<std::string> used;
    int best = 0;
    std::function<void(int, int)> dfs = [&](int start, int count) {
        if (start == static_cast<int>(s.size())) {
            if (count > best) best = count;
            return;
        }
        for (int end = start + 1; end <= static_cast<int>(s.size()); ++end) {
            std::string sub = s.substr(start, end - start);
            if (used.find(sub) == used.end()) {
                used.insert(sub);
                dfs(end, count + 1);
                used.erase(sub);
            }
        }
    };
    dfs(0, 0);
    return best;
}

