bool isPrintable(const std::vector<std::vector<int>>& targetGrid) {
    int m = targetGrid.size();
    if (m == 0) return true;
    int n = targetGrid[0].size();

    std::unordered_map<int, std::array<int, 4>> rect;
    for (int r = 0; r < m; ++r) {
        for (int c = 0; c < n; ++c) {
            int col = targetGrid[r][c];
            auto it = rect.find(col);
            if (it == rect.end()) {
                rect[col] = {r, r, c, c};
            } else {
                auto& cur = it->second;
                cur[0] = std::min(cur[0], r);
                cur[1] = std::max(cur[1], r);
                cur[2] = std::min(cur[2], c);
                cur[3] = std::max(cur[3], c);
            }
        }
    }

    std::vector<int> colors;
    colors.reserve(rect.size());
    for (const auto& p : rect) colors.push_back(p.first);

    std::unordered_map<int, int> indegree;
    std::unordered_map<int, std::unordered_set<int>> graph;
    for (int col : colors) {
        indegree[col] = 0;
        graph[col] = {};
    }

    for (int col : colors) {
        const auto& bounds = rect[col];
        int minR = bounds[0];
        int maxR = bounds[1];
        int minC = bounds[2];
        int maxC = bounds[3];
        for (int r = minR; r <= maxR; ++r) {
            for (int c = minC; c <= maxC; ++c) {
                int inner = targetGrid[r][c];
                if (inner != col) {
                    auto& adj = graph[col];
                    if (adj.find(inner) == adj.end()) {
                        adj.insert(inner);
                        indegree[inner] += 1;
                    }
                }
            }
        }
    }

    std::queue<int> q;
    for (int col : colors) {
        if (indegree[col] == 0) q.push(col);
    }

    int visited = 0;
    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        ++visited;
        for (int nxt : graph[cur]) {
            indegree[nxt] -= 1;
            if (indegree[nxt] == 0) q.push(nxt);
        }
    }

    return visited == static_cast<int>(colors.size());
}

#include <bits/stdc++.h>

int maxProductPath(std::vector<std::vector<int>>& grid) {
    const long long MOD = 1000000007LL;
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<long long>> maxDP(m, std::vector<long long>(n, LLONG_MIN));
    std::vector<std::vector<long long>> minDP(m, std::vector<long long>(n, LLONG_MAX));
    maxDP[0][0] = minDP[0][0] = grid[0][0];
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == 0 && j == 0) continue;
            long long cur = grid[i][j];
            long long candidatesMax = LLONG_MIN;
            long long candidatesMin = LLONG_MAX;
            if (i > 0) {
                long long a = maxDP[i-1][j];
                long long b = minDP[i-1][j];
                if (a != LLONG_MIN) {
                    long long prod = a * cur;
                    candidatesMax = std::max(candidatesMax, prod);
                    candidatesMin = std::min(candidatesMin, prod);
                }
                if (b != LLONG_MAX) {
                    long long prod = b * cur;
                    candidatesMax = std::max(candidatesMax, prod);
                    candidatesMin = std::min(candidatesMin, prod);
                }
            }
            if (j > 0) {
                long long a = maxDP[i][j-1];
                long long b = minDP[i][j-1];
                if (a != LLONG_MIN) {
                    long long prod = a * cur;
                    candidatesMax = std::max(candidatesMax, prod);
                    candidatesMin = std::min(candidatesMin, prod);
                }
                if (b != LLONG_MAX) {
                    long long prod = b * cur;
                    candidatesMax = std::max(candidatesMax, prod);
                    candidatesMin = std::min(candidatesMin, prod);
                }
            }
            maxDP[i][j] = candidatesMax;
            minDP[i][j] = candidatesMin;
        }
    }
    long long result = maxDP[m-1][n-1];
    if (result < 0) return -1;
    return static_cast<int>(result % MOD);
}

