long long maxSumRangeQuery(std::vector<int> nums, const std::vector<std::vector<int>>& requests) {
    const int64_t MOD = 1000000007LL;
    int n = static_cast<int>(nums.size());
    std::vector<int64_t> diff(n + 1, 0);
    for (const auto& req : requests) {
        int l = req[0];
        int r = req[1];
        diff[l] += 1;
        if (r + 1 < n) diff[r + 1] -= 1;
    }
    std::vector<int64_t> freq(n);
    int64_t cur = 0;
    for (int i = 0; i < n; ++i) {
        cur += diff[i];
        freq[i] = cur;
    }
    std::sort(nums.begin(), nums.end(), std::greater<int>());
    std::sort(freq.begin(), freq.end(), std::greater<int64_t>());
    int64_t ans = 0;
    for (int i = 0; i < n; ++i) {
        ans = (ans + (static_cast<int64_t>(nums[i]) * freq[i]) % MOD) % MOD;
    }
    return ans;
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>
#include <climits>

int minimumCost(std::vector<std::vector<int>>& cost) {
    int n = static_cast<int>(cost.size());
    int m = static_cast<int>(cost[0].size());
    const int INF = 1e9;
    std::vector<int> minSecond(m, INF);
    for (int j = 0; j < m; ++j) {
        for (int i = 0; i < n; ++i) {
            minSecond[j] = std::min(minSecond[j], cost[i][j]);
        }
    }
    int fullMask = 1 << m;
    std::vector<int> dp(fullMask, INF), ndp(fullMask, INF);
    dp[0] = 0;
    for (int i = 0; i < n; ++i) {
        std::fill(ndp.begin(), ndp.end(), INF);
        for (int mask = 0; mask < fullMask; ++mask) {
            if (dp[mask] == INF) continue;
            for (int j = 0; j < m; ++j) {
                int nmask = mask | (1 << j);
                ndp[nmask] = std::min(ndp[nmask], dp[mask] + cost[i][j]);
            }
        }
        dp.swap(ndp);
    }
    int answer = INF;
    for (int mask = 0; mask < fullMask; ++mask) {
        if (dp[mask] == INF) continue;
        int total = dp[mask];
        for (int j = 0; j < m; ++j) {
            if ((mask & (1 << j)) == 0) {
                total += minSecond[j];
            }
        }
        answer = std::min(answer, total);
    }
    return answer;
}

