int maximumRequests(int n, const std::vector<std::vector<int>>& requests) {
    int m = static_cast<int>(requests.size());
    int best = 0;
    for (int mask = 0; mask < (1 << m); ++mask) {
        std::vector<int> balance(n, 0);
        int used = 0;
        for (int i = 0; i < m; ++i) {
            if (mask & (1 << i)) {
                int from = requests[i][0];
                int to = requests[i][1];
                balance[from]--;
                balance[to]++;
                ++used;
            }
        }
        bool ok = true;
        for (int b = 0; b < n; ++b) {
            if (balance[b] != 0) {
                ok = false;
                break;
            }
        }
        if (ok && used > best) {
            best = used;
        }
    }
    return best;
}

