int maxProfit(const std::vector<int>& customers, int boardingCost, int runningCost) {
    int waiting = 0;
    long long profit = 0;
    long long maxProfit = 0;
    int bestRot = -1;
    int rotations = 0;
    for (size_t i = 0; i < customers.size() || waiting > 0; ++i) {
        if (i < customers.size()) waiting += customers[i];
        int board = std::min(4, waiting);
        waiting -= board;
        ++rotations;
        profit += static_cast<long long>(board) * boardingCost - runningCost;
        if (profit > maxProfit) {
            maxProfit = profit;
            bestRot = rotations;
        }
    }
    return maxProfit > 0 ? bestRot : -1;
}

