struct ThroneInheritanceResult {
    std::unordered_map<std::string, std::vector<std::string>> children;
    std::unordered_set<std::string> dead;
    std::string kingName;
    ThroneInheritanceResult(const std::string& king) : kingName(king) {
        children[kingName] = {};
    }
    void birth(const std::string& parentName, const std::string& childName) {
        if (children.find(parentName) == children.end()) {
            children[parentName] = {};
        }
        children[parentName].push_back(childName);
        children[childName] = {};
    }
    void death(const std::string& name) {
        dead.insert(name);
    }
    std::vector<std::string> getInheritanceOrder() {
        std::vector<std::string> order;
        std::function<void(const std::string&)> dfs = [&](const std::string& person) {
            if (dead.find(person) == dead.end()) {
                order.push_back(person);
            }
            auto it = children.find(person);
            if (it != children.end()) {
                for (const auto& child : it->second) {
                    dfs(child);
                }
            }
        };
        dfs(kingName);
        return order;
    }
};

