std::vector<int> busiestServers(int k, const std::vector<int>& arrival, const std::vector<int>& load) {
    std::vector<int> handled(k, 0);
    std::set<int> freeServers;
    for (int i = 0; i < k; ++i) freeServers.insert(i);
    using Busy = std::pair<long long, int>; // finish time, server id
    struct Compare {
        bool operator()(const Busy& a, const Busy& b) const {
            return a.first > b.first;
        }
    };
    std::priority_queue<Busy, std::vector<Busy>, Compare> busyHeap;
    const std::size_t n = arrival.size();
    for (std::size_t i = 0; i < n; ++i) {
        long long curTime = static_cast<long long>(arrival[i]);
        // Release servers that have finished by curTime
        while (!busyHeap.empty() && busyHeap.top().first <= curTime) {
            int sid = busyHeap.top().second;
            busyHeap.pop();
            freeServers.insert(sid);
        }
        if (freeServers.empty()) continue; // drop request
        int start = static_cast<int>(i % k);
        auto it = freeServers.lower_bound(start);
        if (it == freeServers.end()) it = freeServers.begin();
        int server = *it;
        freeServers.erase(it);
        ++handled[server];
        long long finishTime = curTime + static_cast<long long>(load[i]);
        busyHeap.emplace(finishTime, server);
    }
    int maxHandled = 0;
    for (int cnt : handled) if (cnt > maxHandled) maxHandled = cnt;
    std::vector<int> result;
    for (int i = 0; i < k; ++i) {
        if (handled[i] == maxHandled) result.push_back(i);
    }
    return result;
}

