std::vector<std::string> alertNames(const std::vector<std::string>& keyName, const std::vector<std::string>& keyTime) {
    std::unordered_map<std::string, std::vector<int>> minutesMap;
    for (size_t i = 0; i < keyName.size(); ++i) {
        const std::string& name = keyName[i];
        const std::string& timeStr = keyTime[i];
        size_t colonPos = timeStr.find(':');
        int h = std::stoi(timeStr.substr(0, colonPos));
        int m = std::stoi(timeStr.substr(colonPos + 1));
        int minutes = h * 60 + m;
        minutesMap[name].push_back(minutes);
    }

    std::unordered_set<std::string> alerted;
    for (auto& entry : minutesMap) {
        std::vector<int>& times = entry.second;
        std::sort(times.begin(), times.end());
        for (size_t i = 0; i + 2 < times.size(); ++i) {
            if (times[i + 2] - times[i] <= 60) {
                alerted.insert(entry.first);
                break;
            }
        }
    }

    std::vector<std::string> result(alerted.begin(), alerted.end());
    std::sort(result.begin(), result.end());
    return result;
}

#include <bits/stdc++.h>

std::vector<std::vector<int>> restoreMatrix(std::vector<int> rowSum, std::vector<int> colSum) {
    std::size_t rows = rowSum.size();
    std::size_t cols = colSum.size();
    std::vector<std::vector<int>> matrix(rows, std::vector<int>(cols, 0));
    using P = std::pair<int, std::size_t>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
    for (std::size_t j = 0; j < cols; ++j) {
        if (colSum[j] > 0) {
            pq.emplace(colSum[j], j);
        }
    }
    for (std::size_t i = 0; i < rows; ++i) {
        while (rowSum[i] > 0) {
            P top = pq.top();
            pq.pop();
            int take = std::min(rowSum[i], top.first);
            matrix[i][top.second] = take;
            rowSum[i] -= take;
            colSum[top.second] -= take;
            if (colSum[top.second] > 0) {
                pq.emplace(colSum[top.second], top.second);
            }
        }
    }
    return matrix;
}

