int maxVisiblePoints(const std::vector<std::vector<int>>& points, int angle, const std::vector<int>& location) {
    int sameLocation = 0;
    for (const auto& p : points) {
        if (p[0] == location[0] && p[1] == location[1]) {
            ++sameLocation;
        }
    }

    std::vector<double> angles;
    const double PI = std::acos(-1.0);
    for (const auto& p : points) {
        if (p[0] == location[0] && p[1] == location[1]) continue;
        double deg = std::atan2(p[1] - location[1], p[0] - location[0]) * 180.0 / PI;
        if (deg < 0) deg += 360.0;
        angles.push_back(deg);
    }

    if (angle >= 360) return static_cast<int>(points.size());

    std::sort(angles.begin(), angles.end());
    std::vector<double> extended = angles;
    for (double v : angles) {
        extended.push_back(v + 360.0);
    }

    int maxInWindow = 0;
    std::size_t left = 0;
    for (std::size_t right = 0; right < extended.size(); ++right) {
        while (extended[right] - extended[left] > angle) {
            ++left;
        }
        int windowSize = static_cast<int>(right - left + 1);
        if (windowSize > maxInWindow) maxInWindow = windowSize;
    }

    return maxInWindow + sameLocation;
}

