static bool isPal(const std::string& s, int l, int r) {
    while (l < r && s[l] == s[r]) {
        ++l;
        --r;
    }
    return l >= r;
}

static bool check(const std::string& s1, const std::string& s2) {
    int i = 0;
    int j = static_cast<int>(s1.size()) - 1;
    while (i < j && s1[i] == s2[j]) {
        ++i;
        --j;
    }
    if (i >= j) return true;
    return isPal(s1, i, j) || isPal(s2, i, j);
}

bool checkPalindromeFormation(const std::string& a, const std::string& b) {
    return check(a, b) || check(b, a);
}

