#include <algorithm>

std::vector<int> countSubgraphsForEachDiameter(int n, std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0] - 1;
        int v = e[1] - 1;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<int> ans(n - 1, 0);
    int totalMasks = 1 << n;
    for (int mask = 1; mask < totalMasks; ++mask) {
        int sz = __builtin_popcount(mask);
        if (sz < 2) continue; // diameter would be 0
        int start = __builtin_ctz(mask); // first set bit
        // BFS to check connectivity and get farthest node
        std::vector<int> dist(n, -1);
        std::queue<int> q;
        dist[start] = 0;
        q.push(start);
        int visited = 0;
        int farNode = start;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            ++visited;
            if (dist[u] > dist[farNode]) farNode = u;
            for (int v : adj[u]) {
                if (((mask >> v) & 1) && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        if (visited != sz) continue; // not connected
        // Second BFS from farNode to find diameter
        std::fill(dist.begin(), dist.end(), -1);
        dist[farNode] = 0;
        q.push(farNode);
        int diameter = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                if (((mask >> v) & 1) && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    diameter = std::max(diameter, dist[v]);
                    q.push(v);
                }
            }
        }
        ans[diameter - 1] += 1;
    }
    return ans;
}

