double meanOfArray(std::vector<double> arr) {
    std::size_t n = arr.size();
    std::size_t removeCount = static_cast<std::size_t>(std::floor(n * 0.05));
    std::sort(arr.begin(), arr.end());
    double sum = 0.0;
