int maximalNetworkRank(int n, const std::vector<std::vector<int>>& roads) {
    std::vector<int> degree(n, 0);
    std::vector<std::unordered_set<int>> adjacent(n);
    for (const auto& road : roads) {
        int a = road[0];
        int b = road[1];
        degree[a]++; 
        degree[b]++;
        adjacent[a].insert(b);
        adjacent[b].insert(a);
    }
    int best = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int rank = degree[i] + degree[j];
            if (adjacent[i].find(j) != adjacent[i].end()) {
                --rank;
            }
            if (rank > best) {
                best = rank;
            }
        }
    }
    return best;
}

