std::vector<int> bestCoordinate(const std::vector<std::vector<int>>& towers, int radius) {
    int minX = std::numeric_limits<int>::max();
    int maxX = std::numeric_limits<int>::min();
    int minY = std::numeric_limits<int>::max();
    int maxY = std::numeric_limits<int>::min();
    for (const auto& t : towers) {
        int x = t[0];
        int y = t[1];
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
    }
    minX -= radius;
    maxX += radius;
    minY -= radius;
    maxY += radius;

    int bestX = 0, bestY = 0, bestQuality = -1;

    for (int cx = minX; cx <= maxX; ++cx) {
        for (int cy = minY; cy <= maxY; ++cy) {
            int total = 0;
            for (const auto& t : towers) {
                int tx = t[0];
                int ty = t[1];
                int q = t[2];
                int dx = tx - cx;
                int dy = ty - cy;
                double dist = std::sqrt(static_cast<double>(dx) * dx + static_cast<double>(dy) * dy);
                if (dist <= radius) {
                    total += static_cast<int>(std::floor(q / (1.0 + dist)));
                }
            }
            if (total > bestQuality || (total == bestQuality && (cx < bestX || (cx == bestX && cy < bestY)))) {
                bestQuality = total;
                bestX = cx;
                bestY = cy;
            }
        }
    }
    return {bestX, bestY};
}

