int largestSubstringBetweenEqualChars(const std::string& s) {
    std::unordered_map<char, int> firstPos;
    std::unordered_map<char, int> lastPos;
    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        char ch = s[i];
        if (firstPos.find(ch) == firstPos.end()) {
            firstPos[ch] = i;
        }
        lastPos[ch] = i;
    }
    int maxLen = -1;
    for (const auto& kv : firstPos) {
        char ch = kv.first;
        int first = kv.second;
        int last = lastPos[ch];
        if (last > first) {
            int curLen = last - first - 1;
            if (curLen > maxLen) {
                maxLen = curLen;
            }
        }
    }
    return maxLen;
}

#include <bits/stdc++.h>
int numberOfSets(int n, int k) {
    const long long MOD = 1000000007LL;
    if (k == 0) return 1;
    std::vector<std::vector<long long>> dp(n, std::vector<long long>(k + 1, 0));
    std::vector<std::vector<long long>> pref(n, std::vector<long long>(k + 1, 0));
    // i = 0 initialization
    dp[0][0] = 1;
    pref[0][0] = 1;
    for (int j = 1; j <= k; ++j) {
        dp[0][j] = 0;
        pref[0][j] = 0;
    }
    for (int i = 1; i < n; ++i) {
        dp[i][0] = 1;
        for (int j = 1; j <= k; ++j) {
            long long val = dp[i - 1][j];
            val += pref[i - 1][j - 1];
            if (val >= MOD) val -= MOD;
            dp[i][j] = val % MOD;
        }
        for (int j = 0; j <= k; ++j) {
            long long sum = pref[i - 1][j] + dp[i][j];
            if (sum >= MOD) sum -= MOD;
            pref[i][j] = sum % MOD;
        }
    }
    return static_cast<int>(dp[n - 1][k] % MOD);
}

