int bestTeamScore(const std::vector<int>& scores, const std::vector<int>& ages) {
    size_t n = scores.size();
    struct Player {int age; int score;};
    std::vector<Player> players(n);
    for (size_t i = 0; i < n; ++i) {
        players[i] = {ages[i], scores[i]};
    }
    std::sort(players.begin(), players.end(), [](const Player& p1, const Player& p2) {
        if (p1.age != p2.age) return p1.age < p2.age;
        return p1.score < p2.score;
    });
    std::vector<long long> dp(n, 0);
    long long best = 0;
    for (size_t i = 0; i < n; ++i) {
        dp[i] = players[i].score;
        for (size_t j = 0; j < i; ++j) {
            if (players[j].score <= players[i].score) {
                dp[i] = std::max(dp[i], dp[j] + players[i].score);
            }
        }
        best = std::max(best, dp[i]);
    }
    return static_cast<int>(best);
}

