#include <vector>
#include <cstdint>

struct FancySequence {
    static const int64_t MOD = 1000000007LL;
    std::vector<int64_t> values;
    std::vector<int64_t> mulAt;
    std::vector<int64_t> addAt;
    int64_t curMul = 1;
    int64_t curAdd = 0;

    static int64_t modPow(int64_t base, int64_t exp) {
        int64_t result = 1;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    void append(int val) {
        values.push_back(static_cast<int64_t>(val));
        mulAt.push_back(curMul);
        addAt.push_back(curAdd);
    }

    void addAll(int inc) {
        curAdd = (curAdd + static_cast<int64_t>(inc)) % MOD;
    }

    void multAll(int m) {
        curMul = (curMul * static_cast<int64_t>(m)) % MOD;
        curAdd = (curAdd * static_cast<int64_t>(m)) % MOD;
    }

    int getIndex(int idx) {
        if (idx < 0 || static_cast<size_t>(idx) >= values.size()) return -1;
        int64_t v = values[idx];
        int64_t m0 = mulAt[idx];
        int64_t a0 = addAt[idx];
        int64_t inv = modPow(m0, MOD - 2);
        int64_t factor = (curMul * inv) % MOD;
        // FIXED: must subtract a0*factor (not a0*inv) - see js_algo fix note.
        int64_t add = ((curAdd - (a0 * factor) % MOD) % MOD + MOD) % MOD;
        int64_t res = (v * factor + add) % MOD;
        return static_cast<int>(res);
    }
};

FancySequence createFancySequence() {
    return FancySequence();
}

