int minimumEffortPath(const std::vector<std::vector<int>>& heights) {
    int rows = static_cast<int>(heights.size());
    int cols = static_cast<int>(heights[0].size());
    if (rows == 1 && cols == 1) return 0;

    auto canReach = [&](int limit) -> bool {
        std::vector<std::vector<char>> visited(rows, std::vector<char>(cols, 0));
        std::queue<std::pair<int, int>> q;
        q.emplace(0, 0);
        visited[0][0] = 1;
        const int dr[4] = {-1, 1, 0, 0};
        const int dc[4] = {0, 0, -1, 1};

        while (!q.empty()) {
            auto rc = q.front();
            q.pop();
            int r = rc.first;
            int c = rc.second;
            if (r == rows - 1 && c == cols - 1) return true;
            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (visited[nr][nc]) continue;
                int diff = std::abs(heights[nr][nc] - heights[r][c]);
                if (diff <= limit) {
                    visited[nr][nc] = 1;
                    q.emplace(nr, nc);
                }
            }
        }
        return false;
    };

    int low = 0;
    int high = 1000000; // maximum possible height difference
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (canReach(mid))
            high = mid;
        else
            low = mid + 1;
    }
    return low;
}

class Solution {
public:
    vector<int> parent;
    int find(int x){ return parent[x]==x?x:parent[x]=find(parent[x]); }
    void unite(int a,int b){ a=find(a); b=find(b); if(a!=b) parent[a]=b; }
    vector<bool> areConnected(int n, int threshold, vector<vector<int>>& queries) {
        parent.resize(n+1);
        iota(parent.begin(), parent.end(), 0);
        for (int d = threshold+1; d <= n; d++) {
            for (int m = 2*d; m <= n; m += d) {
                unite(d, m);
            }
        }
        vector<bool> res;
        for (auto& q : queries) res.push_back(find(q[0])==find(q[1]));
        return res;
    }
};

