std::string findLexSmallestString(const std::string& s, int a, int b) {
    int n = static_cast<int>(s.size());
    std::queue<std::string> q;
    std::unordered_set<std::string> visited;
    q.push(s);
    visited.insert(s);
    std::string best = s;
    while (!q.empty()) {
        std::string cur = q.front();
        q.pop();
        if (cur < best) best = cur;
        std::string add = cur;
        for (int i = 1; i < n; i += 2) {
            int d = (add[i] - '0' + a) % 10;
            add[i] = static_cast<char>('0' + d);
        }
        if (visited.insert(add).second) q.push(add);
        std::string rot(n, '0');
        for (int i = 0; i < n; ++i) {
            rot[(i + b) % n] = cur[i];
        }
        if (visited.insert(rot).second) q.push(rot);
    }
    return best;
}

