#include <vector>

std::vector<bool> checkArithmeticSubarrays(const std::vector<int>& nums, const std::vector<int>& l, const std::vector<int>& r) {
    int m = static_cast<int>(l.size());
    std::vector<bool> answer(m);
    for (int i = 0; i < m; ++i) {
        int start = l[i];
        int end = r[i];
        int len = end - start + 1;

        if (len <= 2) {
            answer[i] = true;
            continue;
        }

        int minVal = nums[start];
        int maxVal = nums[start];

        for (int j = start + 1; j <= end; ++j) {
            int v = nums[j];
            if (v < minVal) minVal = v;
            if (v > maxVal) maxVal = v;
        }

        if ((maxVal - minVal) % (len - 1) != 0) {
            answer[i] = false;
            continue;
        }

        int diff = (maxVal - minVal) / (len - 1);
        if (diff == 0) {
            answer[i] = true;
            continue;
        }

        std::vector<char> seen(len, 0);
        bool ok = true;

        for (int j = start; j <= end && ok; ++j) {
            int v = nums[j];
            if ((v - minVal) % diff != 0) {
                ok = false;
                break;
            }
            int idx = (v - minVal) / diff;
            if (idx < 0 || idx >= len || seen[idx]) {
                ok = false;
                break;
            }
            seen[idx] = 1;
        }

        answer[i] = ok;
    }
    return answer;
}

