struct Cell {
    int val;
    int row;
    int col;
};

struct DSU {
    std::unordered_map<int, int> parent;
    int find(int x) {
        auto it = parent.find(x);
        if (it == parent.end()) {
            parent[x] = x;
            return x;
        }
        if (parent[x] == x) return x;
        parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra != rb) parent[ra] = rb;
    }
};

std::vector<std::vector<int>> matrixRankTransform(const std::vector<std::vector<int>>& matrix) {
    int m = static_cast<int>(matrix.size());
    int n = static_cast<int>(matrix[0].size());

    std::vector<Cell> cells;
    cells.reserve(m * n);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            cells.push_back({matrix[i][j], i, j});
        }
    }

    std::sort(cells.begin(), cells.end(), [](const Cell& a, const Cell& b) {
        return a.val < b.val;
    });

    std::vector<std::vector<int>> answer(m, std::vector<int>(n));
    std::vector<int> rank(m + n, 0);

    std::size_t idx = 0;
    while (idx < cells.size()) {
        std::vector<Cell> sameVal;
        int curVal = cells[idx].val;
        while (idx < cells.size() && cells[idx].val == curVal) {
            sameVal.push_back(cells[idx]);
            ++idx;
        }

        DSU dsu;
        for (const Cell& cell : sameVal) {
            dsu.unite(cell.row, m + cell.col);
        }

        std::unordered_map<int, int> compMax;
        for (const Cell& cell : sameVal) {
            int root = dsu.find(cell.row);
            int curMax = std::max(rank[cell.row], rank[m + cell.col]);
            auto it = compMax.find(root);
            if (it == compMax.end() || curMax > it->second) {
                compMax[root] = curMax;
            }
        }

        for (const Cell& cell : sameVal) {
            int root = dsu.find(cell.row);
            int newRank = compMax[root] + 1;
            answer[cell.row][cell.col] = newRank;
            rank[cell.row] = newRank;
            rank[m + cell.col] = newRank;
        }
    }

    return answer;
}

