int numWays(const std::vector<std::string>& words, const std::string& target) {
    const long long MOD = 1000000007LL;
    int m = static_cast<int>(words[0].size());
    int n = static_cast<int>(target.size());
    std::vector<std::vector<int>> count(26, std::vector<int>(m, 0));
    for (const std::string& w : words) {
        for (int pos = 0; pos < m; ++pos) {
            int idx = w[pos] - 'a';
            ++count[idx][pos];
        }
    }
    std::vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    for (int pos = 0; pos < m; ++pos) {
        int limit = std::min(n, pos + 1);
        for (int i = limit; i >= 1; --i) {
            int charIdx = target[i - 1] - 'a';
            int ways = count[charIdx][pos];
            if (ways) {
                dp[i] = (dp[i] + dp[i - 1] * ways) % MOD;
            }
        }
    }
    return static_cast<int>(dp[n]);
}

