long long countSubstrings(const std::string& s, const std::string& t) {
    int n = static_cast<int>(s.size());
    int m = static_cast<int>(t.size());
    std::vector<std::vector<int>> pref(n + 1, std::vector<int>(m + 1, 0));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (s[i - 1] == t[j - 1]) {
                pref[i][j] = pref[i - 1][j - 1] + 1;
            }
        }
    }
    std::vector<std::vector<int>> suff(n + 1, std::vector<int>(m + 1, 0));
    for (int i = n - 1; i >= 0; --i) {
        for (int j = m - 1; j >= 0; --j) {
            if (s[i] == t[j]) {
                suff[i][j] = suff[i + 1][j + 1] + 1;
            }
        }
    }
    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (s[i] != t[j]) {
                int left = pref[i][j];
                int right = suff[i + 1][j + 1];
                ans += static_cast<long long>(left + 1) * (right + 1);
            }
        }
    }
    return ans;
}

