std::string kthSmallestPath(const std::vector<int>& destination, int k) {
    int v = destination[0];
    int h = destination[1];
    const int MAX = 31;
    unsigned long long C[MAX][MAX] = {};
    for (int i = 0; i < MAX; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
    }
    std::string result;
    unsigned long long kk = static_cast<unsigned long long>(k);
    while (h > 0 || v > 0) {
        if (h == 0) {
            result.push_back('V');
            --v;
            continue;
        }
        if (v == 0) {
            result.push_back('H');
            --h;
            continue;
        }
        unsigned long long cnt = C[h - 1 + v][v];
        if (kk <= cnt) {
            result.push_back('H');
            --h;
        } else {
            result.push_back('V');
            kk -= cnt;
            --v;
        }
    }
    return result;
}

