int furthestBuilding(const std::vector<int>& heights, int bricks, int ladders) {
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;
    for (size_t i = 0; i + 1 < heights.size(); ++i) {
        int climb = heights[i + 1] - heights[i];
        if (climb <= 0) continue;
        minHeap.push(climb);
        if (static_cast<int>(minHeap.size()) > ladders) {
            int smallestClimb = minHeap.top();
            minHeap.pop();
            bricks -= smallestClimb;
            if (bricks < 0) return static_cast<int>(i);
        }
    }
    return static_cast<int>(heights.size() - 1);
}

