#include <bits/stdc++.h>

int createSortedArray(const std::vector<int>& instructions) {
    const int MOD = 1000000007;
    int maxVal = 0;
    for (int v : instructions) if (v > maxVal) maxVal = v;
    std::vector<int> bit(maxVal + 2, 0);
    auto add = [&](int idx, int delta) {
        for (; idx < (int)bit.size(); idx += idx & -idx) {
            bit[idx] += delta;
        }
    };
    auto sum = [&](int idx) {
        int res = 0;
        for (; idx > 0; idx -= idx & -idx) {
            res += bit[idx];
        }
        return res;
    };
    long long ans = 0;
    for (size_t i = 0; i < instructions.size(); ++i) {
        int val = instructions[i];
        int smaller = sum(val - 1);
        int notGreater = sum(val);
        int greater = (int)i - notGreater;
        ans += std::min(smaller, greater);
        if (ans >= MOD) ans %= MOD;
        add(val, 1);
    }
    return (int)(ans % MOD);
}

#include <bits/stdc++.h>

int maxProfit(std::vector<int>& inventory, int orders) {
    const long long MOD = 1000000007LL;
    std::sort(inventory.begin(), inventory.end(), std::greater<int>());
    long long result = 0;
    int n = static_cast<int>(inventory.size());
    long long remaining = orders;
    for (int i = 0; i < n; ++i) {
        long long cur = inventory[i];
        long long next = (i + 1 < n) ? inventory[i + 1] : 0;
        long long cnt = i + 1;
        long long diff = cur - next;
        if (diff == 0) continue;
        long long totalBalls = diff * cnt;
        if (remaining >= totalBalls) {
            long long high = cur;
            long long low = next + 1;
            long long sum = (high + low) * diff / 2;
            result = (result + (sum % MOD) * (cnt % MOD)) % MOD;
            remaining -= totalBalls;
        } else {
            long long full = remaining / cnt;
            long long remainder = remaining % cnt;
            long long high = cur;
            long long low = cur - full + 1;
            long long sumFull = (high + low) * full / 2;
            result = (result + (sumFull % MOD) * (cnt % MOD)) % MOD;
            long long valueRemain = cur - full;
            result = (result + (valueRemain % MOD) * (remainder % MOD)) % MOD;
            break;
        }
    }
    return static_cast<int>(result);
}

