bool canDistribute(const std::vector<int>& nums, std::vector<int> quantity) {
    std::unordered_map<int, int> freqMap;
    for (int v : nums) ++freqMap[v];
    std::vector<int> freqs;
    freqs.reserve(freqMap.size());
    for (const auto& p : freqMap) freqs.push_back(p.second);
    int m = quantity.size();
    int fullMask = (1 << m) - 1;
    std::sort(quantity.begin(), quantity.end(), std::greater<int>());
    std::vector<int> subsetSum(1 << m, 0);
    for (int mask = 1; mask < (1 << m); ++mask) {
        int lsb = mask & -mask;
        int idx = __builtin_ctz(lsb);
        subsetSum[mask] = subsetSum[mask ^ lsb] + quantity[idx];
    }
    std::unordered_map<std::string, bool> memo;
    std::function<bool(int, int)> dfs = [&](int mask, int i) -> bool {
        if (mask == 0) return true;
        if (i == (int)freqs.size()) return false;
        std::string key = std::to_string(mask) + ',' + std::to_string(i);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        if (dfs(mask, i + 1)) {
            memo[key] = true;
            return true;
        }
        for (int sub = mask; sub; sub = (sub - 1) & mask) {
            if (subsetSum[sub] <= freqs[i]) {
                if (dfs(mask ^ sub, i + 1)) {
                    memo[key] = true;
                    return true;
                }
            }
        }
        memo[key] = false;
        return false;
    };
    return dfs(fullMask, 0);
}

