std::vector<int> decrypt(const std::vector<int>& code, int k) {
    int n = static_cast<int>(code.size());
    std::vector<int> result(n, 0);
    if (k == 0) return result;
    int steps = std::abs(k);
    int window = 0;
    if (k > 0) {
        for (int i = 1; i <= steps; ++i) {
            window += code[i % n];
        }
        for (int i = 0; i < n; ++i) {
            result[i] = window;
            window -= code[(i + 1) % n];
            window += code[(i + steps + 1) % n];
        }
    } else {
        for (int i = 0; i < steps; ++i) {
            window += code[(n - 1 - i + n) % n];
        }
        for (int i = 0; i < n; ++i) {
            result[i] = window;
            window -= code[(i - steps + n) % n];
            window += code[i];
        }
    }
    return result;
}

