int minimumJumps(const std::vector<int>& forbidden, int a, int b, int x) {
    std::unordered_set<int> forbiddenSet(forbidden.begin(), forbidden.end());
    int maxForbidden = 0;
    if (!forbidden.empty()) {
        maxForbidden = *std::max_element(forbidden.begin(), forbidden.end());
    }
    int limit = std::max(maxForbidden, x) + a + b;

    std::unordered_set<std::string> visited;
    std::queue<std::tuple<int, bool, int>> q;
    q.emplace(0, false, 0);
    visited.insert("0,false");

    while (!q.empty()) {
        int pos, steps;
        bool prevBack;
        std::tie(pos, prevBack, steps) = q.front();
        q.pop();
        if (pos == x) {
            return steps;
        }

        int forward = pos + a;
        if (forward <= limit && forbiddenSet.find(forward) == forbiddenSet.end()) {
            std::string key = std::to_string(forward) + ",false";
            if (visited.find(key) == visited.end()) {
                visited.insert(key);
                q.emplace(forward, false, steps + 1);
            }
        }

        if (!prevBack) {
            int backward = pos - b;
            if (backward >= 0 && forbiddenSet.find(backward) == forbiddenSet.end()) {
                std::string key = std::to_string(backward) + ",true";
                if (visited.find(key) == visited.end()) {
                    visited.insert(key);
                    q.emplace(backward, true, steps + 1);
                }
            }
        }
    }
    return -1;
}

