int waysToMakeFair(const std::vector<int>& nums) {
    long long totalEven = 0, totalOdd = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (i % 2 == 0) totalEven += nums[i];
        else totalOdd += nums[i];
    }
    long long leftEven = 0, leftOdd = 0;
    int answer = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        long long rightEven, rightOdd;
        if (i % 2 == 0) {
            rightEven = totalEven - leftEven - nums[i];
            rightOdd = totalOdd - leftOdd;
        } else {
            rightEven = totalEven - leftEven;
            rightOdd = totalOdd - leftOdd - nums[i];
        }
        if (leftEven + rightOdd == leftOdd + rightEven) {
            ++answer;
        }
        if (i % 2 == 0) leftEven += nums[i];
        else leftOdd += nums[i];
    }
    return answer;
}

