int maxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
    int totalCells = m * n;
    std::vector<int> grid(totalCells, 0);
    std::unordered_map<int, int> base{{1, 120}, {2, 40}};
    std::unordered_map<int, std::unordered_map<int, int>> adjDelta{
        {1, {{1, -60}, {2, -10}}},
        {2, {{1, -10}, {2, 40}}}
    };
    int best = 0;

    std::function<void(int, int, int, int)> dfs = [&](int pos, int introLeft, int extroLeft, int current) {
        if (pos == totalCells) {
            if (current > best) best = current;
            return;
        }
        if (introLeft == 0 && extroLeft == 0) {
            if (current > best) best = current;
            return;
        }

        dfs(pos + 1, introLeft, extroLeft, current);

        int row = pos / n;
        int col = pos % n;
        int left = (col > 0) ? grid[pos - 1] : 0;
        int up = (row > 0) ? grid[pos - n] : 0;

        if (introLeft > 0) {
            int add = base[1];
            if (left) add += adjDelta[1][left];
            if (up) add += adjDelta[1][up];
            grid[pos] = 1;
            dfs(pos + 1, introLeft - 1, extroLeft, current + add);
            grid[pos] = 0;
        }

        if (extroLeft > 0) {
            int add = base[2];
            if (left) add += adjDelta[2][left];
            if (up) add += adjDelta[2][up];
            grid[pos] = 2;
            dfs(pos + 1, introLeft, extroLeft - 1, current + add);
            grid[pos] = 0;
        }
    };

    dfs(0, introvertsCount, extrovertsCount, 0);
    return best;
}

