    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* mergeInBetween(ListNode* list1, int a, int b, ListNode* list2) {
    ListNode* prevA = nullptr;
    ListNode* cur = list1;
    for (int i = 0; i < a; ++i) {
        prevA = cur;
        cur = cur->next;
    }
    ListNode* postB = cur;
    for (int i = a; i <= b; ++i) {
        postB = postB->next;
    }

    ListNode* tail2 = list2;
    while (tail2->next != nullptr) {
        tail2 = tail2->next;
    }

    if (prevA != nullptr) {
        prevA->next = list2;
    } else {
        list1 = list2;
    }
    tail2->next = postB;

    return list1;
}

