int minimumDeviation(std::vector<int>& nums) {
    std::priority_queue<int> heap;
    int currentMin = INT_MAX;
    for (int x : nums) {
        if (x % 2 == 1) x *= 2;
        heap.push(x);
        if (x < currentMin) currentMin = x;
    }
    int best = heap.top() - currentMin;
    while (heap.top() % 2 == 0) {
        int maxVal = heap.top();
        heap.pop();
        int reduced = maxVal / 2;
        heap.push(reduced);
        if (reduced < currentMin) currentMin = reduced;
        int deviation = heap.top() - currentMin;
        if (deviation < best) best = deviation;
    }
    return best;
}

