int concatenatedBinary(int n) {
    constexpr long long MOD = 1000000007LL;
    long long result = 0;
    int bits = 0;
    std::vector<long long> pow2(32);
    pow2[0] = 1;
    for (int i = 1; i < 32; ++i) {
        pow2[i] = (pow2[i - 1] * 2) % MOD;
    }
    for (int i = 1; i <= n; ++i) {
        if ((i & (i - 1)) == 0) {
            ++bits;
        }
        result = (result * pow2[bits] + i) % MOD;
    }
    return static_cast<int>(result);
}

