int minMoves(std::vector<int>& nums, int limit) {
    int n = nums.size();
    int pairs = n / 2;
    int maxSum = 2 * limit;
    std::vector<int> diff(maxSum + 2, 0);
    std::vector<int> cnt(maxSum + 2, 0);
    for (int i = 0; i < pairs; ++i) {
        int a = nums[i];
        int b = nums[n - 1 - i];
        int low = std::min(a, b) + 1;
        int high = std::max(a, b) + limit;
        diff[low] -= 1;
        diff[high + 1] += 1;
        cnt[a + b] += 1;
    }
    int cur = 0;
    int answer = INT_MAX;
    for (int t = 2; t <= maxSum; ++t) {
        cur += diff[t];
        int moves = 2 * pairs + cur - cnt[t];
        if (moves < answer) answer = moves;
    }
    return answer;
}

