std::vector<long long> sumOfAbsoluteDifferences(const std::vector<long long>& nums) {
    size_t n = nums.size();
    std::vector<long long> prefix(n);
    long long sum = 0;
    for (size_t i = 0; i < n; ++i) {
        sum += nums[i];
        prefix[i] = sum;
    }
    long long total = sum;
    std::vector<long long> result(n);
    for (size_t i = 0; i < n; ++i) {
        long long leftCount = i;
        long long rightCount = n - i - 1;
        long long leftSum = leftCount > 0 ? prefix[i - 1] : 0;
        long long rightSum = total - prefix[i];
        result[i] = nums[i] * leftCount - leftSum + rightSum - nums[i] * rightCount;
    }
    return result;
}

