#include <bits/stdc++.h>

int boxDelivering(std::vector<std::vector<int>>& boxes, int portsCount, int maxBoxes, int maxWeight) {
    int n = boxes.size();
    std::vector<int> port(n + 1);
    std::vector<int> weight(n + 1);
    for (int i = 1; i <= n; ++i) {
        port[i] = boxes[i - 1][0];
        weight[i] = boxes[i - 1][1];
    }

    // prefix sums for weight
    std::vector<long long> prefWeight(n + 1, 0);
    for (int i = 1; i <= n; ++i) prefWeight[i] = prefWeight[i - 1] + weight[i];

    // prefix sums for port changes
    std::vector<int> prefDiff(n + 1, 0);
    for (int i = 2; i <= n; ++i) {
        prefDiff[i] = prefDiff[i - 1] + (port[i] != port[i - 1] ? 1 : 0);
    }

    const int INF = 1e9;
    std::vector<int> dp(n + 1, INF);
    dp[0] = 0;

    std::deque<int> q;          // stores candidate start indices j
    q.push_back(1);             // j = 1 is initially possible

    int left = 1;               // leftmost index allowed in current window

    for (int i = 1; i <= n; ++i) {
        // shrink window to satisfy constraints
        while (i - left + 1 > maxBoxes || prefWeight[i] - prefWeight[left - 1] > maxWeight) {
            ++left;
        }
        // remove indices that are out of window
        while (!q.empty() && q.front() < left) q.pop_front();

        // compute dp[i] using best candidate
        long long best = (long long)dp[q.front() - 1] - prefDiff[q.front()];
        dp[i] = (int)(best + prefDiff[i] + 2); // +2 accounts for first port visit and return

        // prepare index i+1 as a future start candidate
        int nxt = i + 1;
        if (nxt <= n) {
            long long curVal = (long long)dp[nxt - 1] - prefDiff[nxt];
            while (!q.empty()) {
                long long backVal = (long long)dp[q.back() - 1] - prefDiff[q.back()];
                if (backVal <= curVal) break;
                q.pop_back();
            }
            q.push_back(nxt);
        }
    }
    return dp[n];
}

#include <bits/stdc++.h>
int minimumIncompatibility(std::vector<int> nums, int k) {
    int n = nums.size();
    if (n % k != 0) return -1;
    int sz = n / k;
    const int INF = 1e9;
    std::vector<int> freq(17, 0);
    for (int v : nums) {
        if (v >= (int)freq.size()) freq.resize(v + 1, 0);
        ++freq[v];
        if (freq[v] > k) return -1;
    }
    int fullMask = (1 << n) - 1;
    std::vector<int> compat(1 << n, INF);
    for (int mask = 0; mask <= fullMask; ++mask) {
        if (__builtin_popcount(mask) != sz) continue;
        bool seen[17] = {false};
        int mn = 100, mx = 0;
        bool dup = false;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                int val = nums[i];
                if (seen[val]) { dup = true; break; }
                seen[val] = true;
                mn = std::min(mn, val);
                mx = std::max(mx, val);
            }
        }
        if (!dup) compat[mask] = mx - mn;
    }
    std::vector<int> dp(1 << n, INF);
    dp[0] = 0;
    for (int mask = 1; mask <= fullMask; ++mask) {
        int bits = __builtin_popcount(mask);
        if (bits % sz != 0) continue;
        for (int sub = mask; sub; sub = (sub - 1) & mask) {
            if (compat[sub] == INF) continue;
            int prev = dp[mask ^ sub];
            if (prev == INF) continue;
            dp[mask] = std::min(dp[mask], prev + compat[sub]);
        }
    }
    return dp[fullMask] == INF ? -1 : dp[fullMask];
}

