std::string reformatNumber(const std::string& number) {
    std::string digits;
    for (char ch : number) {
        if (ch != ' ' && ch != '-') {
            digits += ch;
        }
    }

    std::vector<std::string> groups;
    std::size_t i = 0;
    while (digits.size() - i > 4) {
        groups.push_back(digits.substr(i, 3));
        i += 3;
    }

    std::size_t remaining = digits.size() - i;
    if (remaining == 4) {
        groups.push_back(digits.substr(i, 2));
        groups.push_back(digits.substr(i + 2, 2));
    } else {
        groups.push_back(digits.substr(i));
    }

    std::string result;
    for (std::size_t idx = 0; idx < groups.size(); ++idx) {
        if (idx > 0) {
            result += '-';
        }
        result += groups[idx];
    }
    return result;
}

