int stoneGameVII(const std::vector<int>& stones) {
    int n = static_cast<int>(stones.size());
    if (n == 1) return 0;
    std::vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + stones[i];
    }
    auto rangeSum = [&](int l, int r) -> long long {
        return prefix[r + 1] - prefix[l];
    };
    std::vector<std::vector<long long>> dp(n, std::vector<long long>(n, 0));
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            long long total = rangeSum(i, j);
            long long removeLeft = total - stones[i] - dp[i + 1][j];
            long long removeRight = total - stones[j] - dp[i][j - 1];
            dp[i][j] = std::max(removeLeft, removeRight);
        }
    }
    return static_cast<int>(dp[0][n - 1]);
}

