std::vector<bool> distanceLimitedPathsExist(int n, std::vector<std::vector<int>> edgeList, std::vector<std::vector<int>> queries) {
    std::sort(edgeList.begin(), edgeList.end(),
        [](const std::vector<int>& a, const std::vector<int>& b) { return a[2] < b[2]; });

    std::vector<std::array<int, 4>> indexedQueries;
    indexedQueries.reserve(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        indexedQueries.push_back({queries[i][0], queries[i][1], queries[i][2], static_cast<int>(i)});
    }
    std::sort(indexedQueries.begin(), indexedQueries.end(),
        [](const std::array<int, 4>& a, const std::array<int, 4>& b) { return a[2] < b[2]; });

    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) -> int {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]) parent[rx] = ry;
        else if (rank[rx] > rank[ry]) parent[ry] = rx;
        else { parent[ry] = rx; rank[rx]++; }
    };

    std::vector<bool> answer(queries.size());
    size_t e = 0;

    for (const auto& q : indexedQueries) {
        int p = q[0];
        int qq = q[1];
        int limit = q[2];
        int idx = q[3];
        while (e < edgeList.size() && edgeList[e][2] < limit) {
            unite(edgeList[e][0], edgeList[e][1]);
            ++e;
        }
        answer[idx] = (find(p) == find(qq));
    }
    return answer;
}

