int minMoves(std::vector<int>& nums, int k) {
    std::vector<long long> pos;
    for (int i = 0; i < (int)nums.size(); ++i) {
        if (nums[i] == 1) pos.push_back(i);
    }
    int m = pos.size();
    if (k <= 1) return 0;
    std::vector<long long> pref(m + 1, 0);
    for (int i = 0; i < m; ++i) pref[i + 1] = pref[i] + pos[i];
    long long ans = LLONG_MAX;
    for (int i = 0; i + k - 1 < m; ++i) {
        int j = i + k - 1;
        int mid = i + k / 2;
        long long median = pos[mid];
        long long left = median * (mid - i) - (pref[mid] - pref[i]);
        long long right = (pref[j + 1] - pref[mid + 1]) - median * (j - mid);
        long long total = left + right;
        long long leftAdj = (long long)(mid - i) * (mid - i + 1) / 2;
        long long rightAdj = (long long)(j - mid) * (j - mid + 1) / 2;
        long long moves = total - leftAdj - rightAdj;
        if (moves < ans) ans = moves;
    }
    return (int)ans;
}

