int maxEatenApples(const std::vector<int>& apples, const std::vector<int>& days) {
    struct Node { int expire; int count; };
    std::vector<Node> heap;
    int n = static_cast<int>(apples.size());
    int day = 0;
    int eaten = 0;

    auto siftUp = [&](int idx) {
        while (idx > 0) {
            int parent = (idx - 1) >> 1;
            if (heap[parent].expire <= heap[idx].expire) break;
            std::swap(heap[parent], heap[idx]);
            idx = parent;
        }
    };

    auto siftDown = [&](int idx) {
        int len = static_cast<int>(heap.size());
        while (true) {
            int smallest = idx;
            int left = idx * 2 + 1;
            int right = left + 1;
            if (left < len && heap[left].expire < heap[smallest].expire) smallest = left;
            if (right < len && heap[right].expire < heap[smallest].expire) smallest = right;
            if (smallest == idx) break;
            std::swap(heap[idx], heap[smallest]);
            idx = smallest;
        }
    };

    auto push = [&](const Node& node) {
        heap.push_back(node);
        siftUp(static_cast<int>(heap.size()) - 1);
    };

    auto pop = [&]() -> Node {
        Node top = heap[0];
        Node last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            siftDown(0);
        }
        return top;
    };

    while (day < n || !heap.empty()) {
        if (day < n && apples[day] > 0) {
            push(Node{day + days[day], apples[day]});
        }
        while (!heap.empty() && (heap[0].expire <= day || heap[0].count == 0)) {
            pop();
        }
        if (!heap.empty()) {
            heap[0].count--;
            eaten++;
            if (heap[0].count == 0) pop();
        }
        day++;
    }
    return eaten;
}

#include <bits/stdc++.h>
std::vector<int> maximizeXor(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
    struct Node {
        int child[2];
        Node() { child[0] = child[1] = -1; }
    };
    std::vector<Node> trie(1);
    auto insert = [&](int val) {
        int node = 0;
        for (int i = 30; i >= 0; --i) {
            int b = (val >> i) & 1;
            if (trie[node].child[b] == -1) {
                trie[node].child[b] = static_cast<int>(trie.size());
                trie.emplace_back();
            }
            node = trie[node].child[b];
        }
    };
    auto queryMaxXor = [&](int val) -> int {
        int node = 0;
        int ans = 0;
        for (int i = 30; i >= 0; --i) {
            int b = (val >> i) & 1;
            int want = b ^ 1;
            if (trie[node].child[want] != -1) {
                ans |= (1 << i);
                node = trie[node].child[want];
            } else {
                node = trie[node].child[b];
            }
        }
        return ans;
    };
    std::vector<std::tuple<int,int,int>> q; // mi, xi, idx
    q.reserve(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        q.emplace_back(queries[i][1], queries[i][0], static_cast<int>(i));
    }
    std::sort(q.begin(), q.end(), [](const auto& a, const auto& b){
        return std::get<0>(a) < std::get<0>(b);
    });
    std::sort(nums.begin(), nums.end());
    std::vector<int> ans(queries.size(), -1);
    size_t pos = 0;
    int insertedCount = 0;
    for (const auto& tup : q) {
        int mi = std::get<0>(tup);
        int xi = std::get<1>(tup);
        int idx = std::get<2>(tup);
        while (pos < nums.size() && nums[pos] <= mi) {
            insert(nums[pos]);
            ++insertedCount;
            ++pos;
        }
        if (insertedCount == 0) {
            ans[idx] = -1;
        } else {
            ans[idx] = queryMaxXor(xi);
        }
    }
    return ans;
}

