int countGoodMeals(const std::vector<int>& deliciousness) {
    const int MOD = 1000000007;
    std::unordered_map<int, long long> freq;
    long long result = 0;

    int maxVal = 0;
    for (int v : deliciousness) {
        if (v > maxVal) maxVal = v;
    }
    int limit = 1;
    while (limit <= maxVal * 2) {
        limit <<= 1;
    }

    for (int cur : deliciousness) {
        for (int p = 1; p <= limit; p <<= 1) {
            int need = p - cur;
            auto it = freq.find(need);
            if (it != freq.end()) {
                result = (result + it->second) % MOD;
            }
        }
        freq[cur] = freq[cur] + 1;
    }
    return static_cast<int>(result);
}

