int waysToSplit(std::vector<int>& nums) {
    const long long MOD = 1000000007LL;
    std::size_t n = nums.size();
    std::vector<long long> pref(n + 1, 0);
    for (std::size_t i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + nums[i];
    }
    long long total = pref[n];
    long long ans = 0;
    std::size_t low = 1, high = 1;
    for (std::size_t i = 1; i + 1 < n; ++i) {
        if (low < i + 1) low = i + 1;
        if (high < i + 1) high = i + 1;
        while (low < n && pref[low] - pref[i] < pref[i]) ++low;
        while (high < n && pref[high] - pref[i] <= total - pref[high]) ++high;
        if (high > low) {
            ans += static_cast<long long>(high - low);
            if (ans >= MOD) ans %= MOD;
        }
    }
    return static_cast<int>(ans % MOD);
}

