int maximumUnits(std::vector<std::vector<int>> boxTypes, int truckSize) {
    std::sort(boxTypes.begin(), boxTypes.end(),
        [](const std::vector<int>& a, const std::vector<int>& b) {
            return a[1] > b[1];
        });
    int totalUnits = 0;
    int remaining = truckSize;
    for (size_t i = 0; i < boxTypes.size() && remaining > 0; ++i) {
        int boxCount = boxTypes[i][0];
        int unitsPerBox = boxTypes[i][1];
        int take = std::min(boxCount, remaining);
        totalUnits += take * unitsPerBox;
        remaining -= take;
    }
    return totalUnits;
}

