int minOperations(const std::vector<int>& target, const std::vector<int>& arr) {
    std::unordered_map<int, int> pos;
    for (size_t i = 0; i < target.size(); ++i) {
        pos[target[i]] = static_cast<int>(i);
    }

    std::vector<int> indices;
    indices.reserve(arr.size());
    for (int v : arr) {
        auto it = pos.find(v);
        if (it != pos.end()) {
            indices.push_back(it->second);
        }
    }

    std::vector<int> tails;
    for (int x : indices) {
        size_t lo = 0, hi = tails.size();
        while (lo < hi) {
            size_t mid = (lo + hi) >> 1;
            if (tails[mid] < x) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo == tails.size()) {
            tails.push_back(x);
        } else {
            tails[lo] = x;
        }
    }

    return static_cast<int>(target.size() - tails.size());
}

#include <bits/stdc++.h>

std::vector<int> constructLargestValidSequence(int n) {
    int len = 2 * n - 1;
    std::vector<int> seq(len, 0);
    std::vector<bool> used(n + 1, false);
    std::function<bool()> dfs = [&]() -> bool {
        int pos = -1;
        for (int i = 0; i < len; ++i) {
            if (seq[i] == 0) {
                pos = i;
                break;
            }
        }
        if (pos == -1) return true;
        for (int num = n; num >= 1; --num) {
            if (used[num]) continue;
            if (num == 1) {
                seq[pos] = 1;
                used[1] = true;
                if (dfs()) return true;
                used[1] = false;
                seq[pos] = 0;
            } else {
                int j = pos + num;
                if (j < len && seq[j] == 0) {
                    seq[pos] = num;
                    seq[j] = num;
                    used[num] = true;
                    if (dfs()) return true;
                    used[num] = false;
                    seq[pos] = 0;
                    seq[j] = 0;
                }
            }
        }
        return false;
    };
    dfs();
    return seq;
}

