#include <unordered_map>

int minimumHammingDistance(const std::vector<int>& source, const std::vector<int>& target, const std::vector<std::vector<int>>& allowedSwaps) {
    int n = static_cast<int>(source.size());
    std::vector<int> parent(n);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra != rb) parent[ra] = rb;
    };

    for (const auto& edge : allowedSwaps) {
        unite(edge[0], edge[1]);
    }

    std::unordered_map<int, std::vector<int>> groups;
    for (int i = 0; i < n; ++i) {
        int root = find(i);
        groups[root].push_back(i);
    }

    int mismatches = 0;
    for (auto& kv : groups) {
        const std::vector<int>& indices = kv.second;
        std::unordered_map<int, int> srcCount;
        for (int idx : indices) {
            ++srcCount[source[idx]];
        }
        for (int idx : indices) {
            int val = target[idx];
            auto it = srcCount.find(val);
            if (it != srcCount.end() && it->second > 0) {
                --it->second;
            } else {
                ++mismatches;
            }
        }
    }

    return mismatches;
}

