#include <bits/stdc++.h>
int checkWays(const std::vector<std::vector<int>>& pairs) {
    std::unordered_map<int, std::unordered_set<int>> adj;
    for (const auto& p : pairs) {
        int x = p[0], y = p[1];
        adj[x].insert(y);
        adj[y].insert(x);
    }
    int n = adj.size();
    int root = -1;
    for (const auto& kv : adj) {
        if ((int)kv.second.size() == n - 1) {
            root = kv.first;
            break;
        }
    }
    if (root == -1) return 0;
    int answer = 1;
    for (const auto& kv : adj) {
        int node = kv.first;
        if (node == root) continue;
        int minDeg = INT_MAX;
        int cnt = 0;
        for (int nb : kv.second) {
            // candidate parent must be neighbor
            const auto& candSet = adj[nb];
            if (candSet.size() < kv.second.size()) continue;
            bool ok = true;
            for (int v : kv.second) {
                if (v == nb) continue;
                if (candSet.find(v) == candSet.end()) {
                    ok = false;
                    break;
                }
            }
            if (!ok) continue;
            int deg = candSet.size();
            if (deg < minDeg) {
                minDeg = deg;
                cnt = 1;
            } else if (deg == minDeg) {
                ++cnt;
            }
        }
        if (cnt == 0) return 0;
        if (cnt > 1) answer = 2;
    }
    return answer;
}

