int minimumTimeRequired(std::vector<int>& jobs, int k) {
    int n = jobs.size();
    std::sort(jobs.begin(), jobs.end(), std::greater<int>());
    long long low = 0, high = 0;
    for (int t : jobs) {
        low = std::max<long long>(low, t);
        high += t;
    }
    std::vector<long long> load(k, 0);
    std::function<bool(int, long long)> dfs = [&](int idx, long long limit) -> bool {
        if (idx == n) return true;
        int cur = jobs[idx];
        std::unordered_set<long long> seen;
        for (int i = 0; i < k; ++i) {
            if (load[i] + cur > limit) continue;
            if (seen.find(load[i]) != seen.end()) continue;
            seen.insert(load[i]);
            load[i] += cur;
            if (dfs(idx + 1, limit)) return true;
            load[i] -= cur;
            if (load[i] == 0) break;
        }
        return false;
    };
    while (low < high) {
        long long mid = (low + high) / 2;
        std::fill(load.begin(), load.end(), 0);
        if (dfs(0, mid)) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return static_cast<int>(low);
}

#include <bits/stdc++.h>
