int minimumTeachings(int n, const std::vector<std::vector<int>>& languages, const std::vector<std::vector<int>>& friendships) {
    std::vector<std::unordered_set<int>> userLangSets;
    userLangSets.reserve(languages.size());
    for (const auto& arr : languages) {
        userLangSets.emplace_back(arr.begin(), arr.end());
    }

    std::unordered_set<int> candidates;
    for (const auto& pair : friendships) {
        int u = pair[0];
        int v = pair[1];
        const auto& setU = userLangSets[u - 1];
        const auto& setV = userLangSets[v - 1];
        bool canTalk = false;
        for (int lang : setU) {
            if (setV.find(lang) != setV.end()) {
                canTalk = true;
                break;
            }
        }
        if (!canTalk) {
            candidates.insert(u);
            candidates.insert(v);
        }
    }

    if (candidates.empty()) return 0;

    int answer = std::numeric_limits<int>::max();
    for (int lang = 1; lang <= n; ++lang) {
        int teach = 0;
        for (int user : candidates) {
            if (userLangSets[user - 1].find(lang) == userLangSets[user - 1].end()) {
                ++teach;
            }
        }
        if (teach < answer) answer = teach;
    }
    return answer;
}

