std::vector<int> decodeXorPermutation(const std::vector<int>& encoded) {
    int n = static_cast<int>(encoded.size()) + 1;
    int totalXor = 0;
    for (int i = 1; i <= n; ++i) totalXor ^= i;
    int xorExceptFirst = 0;
    for (int i = 1; i < static_cast<int>(encoded.size()); i += 2) xorExceptFirst ^= encoded[i];
    std::vector<int> perm(n);
    perm[0] = totalXor ^ xorExceptFirst;
    for (int i = 0; i < static_cast<int>(encoded.size()); ++i) {
        perm[i + 1] = perm[i] ^ encoded[i];
    }
    return perm;
}

