}

#include <bits/stdc++.h>

bool canMouseWin(std::vector<std::string>& grid, int catJump, int mouseJump) {
    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());
    int total = rows * cols;
    int mouseStart = -1, catStart = -1, foodPos = -1;
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            char ch = grid[r][c];
            int idx = r * cols + c;
            if (ch == 'M') mouseStart = idx;
            else if (ch == 'C') catStart = idx;
            else if (ch == 'F') foodPos = idx;
        }
    }

    auto inBounds = [&](int r, int c) -> bool {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
    };

    std::vector<std::vector<int>> mouseMoves(total), catMoves(total);
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (grid[r][c] == '#') continue;
            int pos = r * cols + c;
            // mouse moves
            mouseMoves[pos].push_back(pos); // stay
            for (int d = 0; d < 4; ++d) {
                int nr = r, nc = c;
                for (int step = 1; step <= mouseJump; ++step) {
                    nr += dr[d];
                    nc += dc[d];
                    if (!inBounds(nr, nc)) break;
                    mouseMoves[pos].push_back(nr * cols + nc);
                }
            }
            // cat moves
            catMoves[pos].push_back(pos); // stay
            for (int d = 0; d < 4; ++d) {
                int nr = r, nc = c;
                for (int step = 1; step <= catJump; ++step) {
                    nr += dr[d];
                    nc += dc[d];
                    if (!inBounds(nr, nc)) break;
                    catMoves[pos].push_back(nr * cols + nc);
                }
            }
        }
    }

    // reverse adjacency
    std::vector<std::vector<int>> mousePrev(total), catPrev(total);
    for (int i = 0; i < total; ++i) {
        for (int nxt : mouseMoves[i]) mousePrev[nxt].push_back(i);
        for (int nxt : catMoves[i]) catPrev[nxt].push_back(i);
    }

    const char UNKNOWN = 0, MOUSE_WIN = 1, CAT_WIN = 2;
    int stateCount = total * total * 2;
    std::vector<char> result(stateCount, UNKNOWN);
    std::vector<int> degree(stateCount, 0);
    std::queue<int> q;

    auto encode = [&](int m, int c, int turn) -> int {
        return ((m * total + c) << 1) | turn;
    };

    // initialize degrees and terminal states
    for (int m = 0; m < total; ++m) {
        if (grid[m / cols][m % cols] == '#') continue;
        for (int c = 0; c < total; ++c) {
            if (grid[c / cols][c % cols] == '#') continue;
            for (int turn = 0; turn < 2; ++turn) {
                int id = encode(m, c, turn);
                if (m == foodPos) {
                    result[id] = MOUSE_WIN;
                    q.push(id);
                } else if (c == foodPos || m == c) {
                    result[id] = CAT_WIN;
                    q.push(id);
                } else {
                    degree[id] = (turn == 0 ? static_cast<int>(mouseMoves[m].size())
                                            : static_cast<int>(catMoves[c].size()));
                }
            }
        }
    }

    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        int turn = cur & 1;
        int tmp = cur >> 1;
        int catPos = tmp % total;
        int mousePos = tmp / total;
        char curRes = result[cur];
        int prevTurn = 1 - turn;

        if (prevTurn == 0) { // previous was mouse's turn
            for (int prevMouse : mousePrev[mousePos]) {
                int prevId = encode(prevMouse, catPos, prevTurn);
                if (result[prevId] != UNKNOWN) continue;
                if (curRes == MOUSE_WIN) {
                    result[prevId] = MOUSE_WIN;
                    q.push(prevId);
                } else {
                    if (--degree[prevId] == 0) {
                        result[prevId] = CAT_WIN;
                        q.push(prevId);
                    }
                }
            }
        } else { // previous was cat's turn
            for (int prevCat : catPrev[catPos]) {
                int prevId = encode(mousePos, prevCat, prevTurn);
                if (result[prevId] != UNKNOWN) continue;
                if (curRes == CAT_WIN) {
                    result[prevId] = CAT_WIN;
                    q.push(prevId);
                } else {
                    if (--degree[prevId] == 0) {
                        result[prevId] = MOUSE_WIN;
                        q.push(prevId);
                    }
                }
            }
        }
    }

    int startId = encode(mouseStart, catStart, 0);
    return result[startId] == MOUSE_WIN;
}

#include <bits/stdc++.h>
#include <string>
#include <vector>
#include <algorithm>

int minCharacters(const std::string& a, const std::string& b) {
    std::vector<int> cntA(26, 0), cntB(26, 0);
    for (char ch : a) cntA[ch - 'a']++;
    for (char ch : b) cntB[ch - 'a']++;
    int totalA = a.size();
    int totalB = b.size();

    // Prefix sums
    std::vector<int> prefA(26, 0), prefB(26, 0);
    prefA[0] = cntA[0];
    prefB[0] = cntB[0];
    for (int i = 1; i < 26; ++i) {
        prefA[i] = prefA[i - 1] + cntA[i];
        prefB[i] = prefB[i - 1] + cntB[i];
    }

    int answer = std::numeric_limits<int>::max();

    // Condition 3: both strings become the same single character
    for (int c = 0; c < 26; ++c) {
        int changes = (totalA - cntA[c]) + (totalB - cntB[c]);
        answer = std::min(answer, changes);
    }

    // Conditions 1 and 2: split point k (0..24)
    for (int k = 0; k < 25; ++k) {
        // Condition 1: max a < min b
        int changes1 = (totalA - prefA[k]) + prefB[k];
        answer = std::min(answer, changes1);
        // Condition 2: max b < min a
        int changes2 = (totalB - prefB[k]) + prefA[k];
        answer = std::min(answer, changes2);
    }

    return answer;
}

