int kthLargestXorCoordinate(const std::vector<std::vector<int>>& matrix, int k) {
    int m = static_cast<int>(matrix.size());
    int n = static_cast<int>(matrix[0].size());
    std::vector<std::vector<int>> pref(m, std::vector<int>(n, 0));
    std::vector<int> vals;
    vals.reserve(m * n);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int top = (i > 0) ? pref[i - 1][j] : 0;
            int left = (j > 0) ? pref[i][j - 1] : 0;
            int diag = (i > 0 && j > 0) ? pref[i - 1][j - 1] : 0;
            pref[i][j] = top ^ left ^ diag ^ matrix[i][j];
            vals.push_back(pref[i][j]);
        }
    }
    std::sort(vals.begin(), vals.end(), std::greater<int>());
    return vals[k - 1];
}

