int countBalls(int lowLimit, int highLimit) {
    std::unordered_map<int, int> boxCounts;
    int maxBalls = 0;
    for (int num = lowLimit; num <= highLimit; ++num) {
        int sum = 0;
        int x = num;
        while (x > 0) {
            sum += x % 10;
            x /= 10;
        }
        int newCount = ++boxCounts[sum];
        if (newCount > maxBalls) {
            maxBalls = newCount;
        }
    }
    return maxBalls;
}

