static const long long MOD = 1000000007LL;

static long long modPow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

vector<int> countWays(vector<vector<int>>& queries) {
    int maxN = 0;
    for (auto &q : queries) {
        maxN = max(maxN, q[0]);
    }
    int limit = maxN + 30; // enough for exponent additions
    vector<long long> fact(limit + 1), invFact(limit + 1);
    fact[0] = 1;
    for (int i = 1; i <= limit; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[limit] = modPow(fact[limit], MOD - 2);
    for (int i = limit; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;

    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    };

    vector<int> answer;
    answer.reserve(queries.size());

    for (auto &q : queries) {
        int n = q[0];
        int k = q[1];
        long long ways = 1;
        int temp = k;
        for (int p = 2; p * p <= temp; ++p) {
            if (temp % p == 0) {
                int cnt = 0;
                while (temp % p == 0) {
                    temp /= p;
                    ++cnt;
                }
                ways = ways * C(cnt + n - 1, n - 1) % MOD;
            }
        }
        if (temp > 1) { // remaining prime factor
            ways = ways * C(1 + n - 1, n - 1) % MOD;
        }
        answer.push_back((int)ways);
    }
    return answer;
}

