long long maxAbsoluteSum(const std::vector<long long>& nums) {
    if (nums.empty()) return 0;
    long long curMax = nums[0], bestMax = nums[0];
    long long curMin = nums[0], bestMin = nums[0];
    for (size_t i = 1; i < nums.size(); ++i) {
        long long x = nums[i];
        curMax = std::max(x, curMax + x);
        bestMax = std::max(bestMax, curMax);
        curMin = std::min(x, curMin + x);
        bestMin = std::min(bestMin, curMin);
    }
    return std::max(bestMax, -bestMin);
}

