std::vector<int> restoreArray(const std::vector<std::vector<int>>& adjacentPairs) {
    std::unordered_map<int, std::vector<int>> adj;
    for (const auto& pair : adjacentPairs) {
        int u = pair[0];
        int v = pair[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    int a = adjacentPairs[0][0];
    int b = adjacentPairs[0][1];
    int start = (adj[a].size() == 1) ? a : b;

    int n = static_cast<int>(adjacentPairs.size()) + 1;
    std::vector<int> result(n);
    result[0] = start;
    result[1] = adj[start][0];

    int prev = start;
    int cur = result[1];
    for (int i = 2; i < n; ++i) {
        const std::vector<int>& neighbors = adj[cur];
        int next = (neighbors[0] == prev) ? neighbors[1] : neighbors[0];
        result[i] = next;
        prev = cur;
        cur = next;
    }
    return result;
}

