static std::vector<long long> genSums(const std::vector<long long>& arr) {
    size_t m = arr.size();
    size_t total = 1ULL << m;
    std::vector<long long> sums(total);
    for (size_t mask = 0; mask < total; ++mask) {
        long long s = 0;
        for (size_t i = 0; i < m; ++i) {
            if (mask & (1ULL << i)) s += arr[i];
        }
        sums[mask] = s;
    }
    return sums;
}

static size_t lowerBound(const std::vector<long long>& arr, long long target) {
    size_t lo = 0, hi = arr.size();
    while (lo < hi) {
        size_t mid = (lo + hi) >> 1;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

long long minAbsDifference(const std::vector<long long>& nums, long long goal) {
    size_t n = nums.size();
    size_t mid = n / 2;
    std::vector<long long> left(nums.begin(), nums.begin() + mid);
    std::vector<long long> right(nums.begin() + mid, nums.end());

    std::vector<long long> leftSums = genSums(left);
    std::vector<long long> rightSums = genSums(right);
    std::sort(rightSums.begin(), rightSums.end());

    long long best = LLONG_MAX;

    for (const long long& s1 : leftSums) {
        long long need = goal - s1;
        size_t idx = lowerBound(rightSums, need);

        if (idx < rightSums.size()) {
            long long cur = std::llabs(s1 + rightSums[idx] - goal);
            if (cur < best) best = cur;
        }
        if (idx > 0) {
            long long cur = std::llabs(s1 + rightSums[idx - 1] - goal);
            if (cur < best) best = cur;
        }
        if (best == 0) return 0;
    }

    return best;
}

