int minimumLength(const std::string& s) {
    int l = 0;
    int r = static_cast<int>(s.size()) - 1;
    while (l < r && s[l] == s[r]) {
        char ch = s[l];
        while (l <= r && s[l] == ch) ++l;
        while (r >= l && s[r] == ch) --r;
    }
    return (l > r) ? 0 : (r - l + 1);
}

