bool canChoose(const std::vector<std::vector<int>>& groups, const std::vector<int>& nums) {
    std::size_t pos = 0;
    for (const auto& g : groups) {
        bool found = false;
        while (pos + g.size() <= nums.size()) {
            bool match = true;
            for (std::size_t i = 0; i < g.size(); ++i) {
                if (nums[pos + i] != g[i]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                pos += g.size();
                found = true;
                break;
            }
            ++pos;
        }
        if (!found) return false;
    }
    return true;
}

