static std::string helper(const std::string& s, int l, int r) {
    if (l >= r) return "";
    int lowerMask = 0, upperMask = 0;
    for (int i = l; i <= r; ++i) {
        char c = s[i];
        if (c >= 'a' && c <= 'z')
            lowerMask |= 1 << (c - 'a');
        else
            upperMask |= 1 << (c - 'A');
    }
    int bothMask = lowerMask & upperMask;
    if (lowerMask == bothMask && upperMask == bothMask) {
        return s.substr(l, r - l + 1);
    }
    for (int i = l; i <= r; ++i) {
        char c = s[i];
        int bit = (c >= 'a' && c <= 'z') ? (c - 'a') : (c - 'A');
        bool hasLower = (lowerMask >> bit) & 1;
        bool hasUpper = (upperMask >> bit) & 1;
        if ((c >= 'a' && c <= 'z' && !hasUpper) || (c >= 'A' && c <= 'Z' && !hasLower)) {
            std::string left = helper(s, l, i - 1);
            std::string right = helper(s, i + 1, r);
            if (left.size() >= right.size())
                return left;
            else
                return right;
        }
    }
    return "";
}

std::string longestNiceSubstring(const std::string& s) {
    return helper(s, 0, static_cast<int>(s.size()) - 1);
}

