std::string largestMerge(const std::string& word1, const std::string& word2) {
    size_t i = 0, j = 0;
    std::string merge;
    auto suffixGreater = [&](size_t p, size_t q) -> bool {
        while (p < word1.size() && q < word2.size()) {
            if (word1[p] != word2[q]) {
                return word1[p] > word2[q];
            }
            ++p;
            ++q;
        }
        return p < word1.size();
    };
    while (i < word1.size() || j < word2.size()) {
        if (i == word1.size()) {
            merge += word2.substr(j);
            break;
        }
        if (j == word2.size()) {
            merge += word1.substr(i);
            break;
        }
        if (suffixGreater(i, j)) {
            merge.push_back(word1[i]);
            ++i;
        } else {
            merge.push_back(word2[j]);
            ++j;
        }
    }
    return merge;
}

#include <bits/stdc++.h>

static int gcdInt(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

std::vector<int> getCoprimes(std::vector<int>& nums, std::vector<std::vector<int>>& edges) {
    int n = nums.size();
    std::vector<std::vector<int>> g(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        g[u].push_back(v);
        g[v].push_back(u);
    }
    bool cop[51][51];
    for (int i = 1; i <= 50; ++i) {
        for (int j = 1; j <= 50; ++j) {
            cop[i][j] = gcdInt(i, j) == 1;
        }
    }
    std::vector<int> ans(n, -1);
    std::vector<int> depth(n, 0);
    std::vector<int> last(51, -1);
    struct Frame {
        int node;
        int parent;
        int stage; // 0 = enter, 1 = exit
        int prev;
    };
    std::vector<Frame> st;
    st.reserve(2 * n);
    st.push_back({0, -1, 0, -1});
    while (!st.empty()) {
        Frame cur = st.back();
        st.pop_back();
        int u = cur.node;
        int val = nums[u];
        if (cur.stage == 0) {
            int bestNode = -1;
            int bestDepth = -1;
            for (int w = 1; w <= 50; ++w) {
                if (cop[val][w] && last[w] != -1) {
                    if (depth[last[w]] > bestDepth) {
                        bestDepth = depth[last[w]];
                        bestNode = last[w];
                    }
                }
            }
            ans[u] = bestNode;
            int prev = last[val];
            last[val] = u;
            st.push_back({u, cur.parent, 1, prev});
            for (int v : g[u]) {
                if (v == cur.parent) continue;
                depth[v] = depth[u] + 1;
                st.push_back({v, u, 0, -1});
            }
        } else {
            last[val] = cur.prev;
        }
    }
    return ans;
}

#include <bits/stdc++.h>

int longestPalindromeFromSubsequences(const std::string& word1, const std::string& word2) {
    size_t n = word1.size();
    size_t m = word2.size();
    std::string rev2(word2.rbegin(), word2.rend());
    std::vector<int> prev(m + 1, 0), cur(m + 1, 0);
    for (size_t i = 1; i <= n; ++i) {
        cur[0] = 0;
        char c1 = word1[i - 1];
        for (size_t j = 1; j <= m; ++j) {
            if (c1 == rev2[j - 1]) {
                cur[j] = prev[j - 1] + 1;
            } else {
                cur[j] = std::max(prev[j], cur[j - 1]);
            }
        }
        std::swap(prev, cur);
    }
    int k = prev[m];
    int ans = 2 * k;
    bool common = false;
    std::array<bool, 256> has1{}, has2{};
    for (unsigned char ch : word1) has1[ch] = true;
    for (unsigned char ch : word2) has2[ch] = true;
    for (int i = 0; i < 256; ++i) {
        if (has1[i] && has2[i]) {
            common = true;
            break;
        }
    }
    if (common) {
        ans = std::max(ans, 2 * k + 1);
    }
    return ans;
}

