std::vector<std::vector<int>> highestPeak(const std::vector<std::vector<int>>& isWater) {
    std::size_t m = isWater.size();
    std::size_t n = isWater[0].size();
    std::vector<std::vector<int>> height(m, std::vector<int>(n, -1));
    std::vector<std::pair<int, int>> queue;
    for (std::size_t i = 0; i < m; ++i) {
        for (std::size_t j = 0; j < n; ++j) {
            if (isWater[i][j] == 1) {
                height[i][j] = 0;
                queue.emplace_back(static_cast<int>(i), static_cast<int>(j));
            }
        }
    }
    const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    std::size_t head = 0;
    while (head < queue.size()) {
        int x = queue[head].first;
        int y = queue[head].second;
        ++head;
        for (const auto& d : dirs) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx < 0 || nx >= static_cast<int>(m) || ny < 0 || ny >= static_cast<int>(n) || height[nx][ny] != -1) continue;
            height[nx][ny] = height[x][y] + 1;
            queue.emplace_back(nx, ny);
        }
    }
    return height;
}

