int closestDessertCost(const std::vector<int>& baseCosts, const std::vector<int>& toppingCosts, int target) {
    std::vector<int> toppingSums;
    std::function<void(int, int)> dfs = [&](int i, int cur) {
        if (i == static_cast<int>(toppingCosts.size())) {
            toppingSums.push_back(cur);
            return;
        }
        for (int cnt = 0; cnt < 3; ++cnt) {
            dfs(i + 1, cur + cnt * toppingCosts[i]);
        }
    };
    dfs(0, 0);
    long long best = LLONG_MAX;
    for (int base : baseCosts) {
        for (int top : toppingSums) {
            int total = base + top;
            long long diff = std::abs(static_cast<long long>(total) - target);
            long long bestDiff = std::abs(best - target);
            if (diff < bestDiff || (diff == bestDiff && total < best)) {
                best = total;
            }
        }
    }
    return static_cast<int>(best);
}

