#include <vector>

std::vector<double> carFleetII(const std::vector<std::vector<int>>& cars) {
    int n = static_cast<int>(cars.size());
    std::vector<double> answer(n, -1.0);
    std::vector<int> stack;
    for (int i = n - 1; i >= 0; --i) {
        int posI = cars[i][0];
        int speedI = cars[i][1];
        while (!stack.empty()) {
            int j = stack.back();
            int posJ = cars[j][0];
            int speedJ = cars[j][1];
            if (speedI <= speedJ) {
                stack.pop_back();
                continue;
            }
            double collideTime = static_cast<double>(posJ - posI) / static_cast<double>(speedI - speedJ);
            if (answer[j] < 0.0 || collideTime <= answer[j]) {
                break;
            }
            stack.pop_back();
        }
        if (!stack.empty()) {
            int j = stack.back();
            int posJ = cars[j][0];
            int speedJ = cars[j][1];
            answer[i] = static_cast<double>(posJ - posI) / static_cast<double>(speedI - speedJ);
        }
        stack.push_back(i);
    }
    return answer;
}

