int minOperations(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    long long sum1 = 0, sum2 = 0;
    for (int v : nums1) sum1 += v;
    for (int v : nums2) sum2 += v;
    if (sum1 == sum2) return 0;
    const std::vector<int>* a = &nums1;
    const std::vector<int>* b = &nums2;
    if (sum1 > sum2) {
        std::swap(a, b);
        std::swap(sum1, sum2);
    }
    long long diff = sum2 - sum1;
    int cnt[6] = {0};
    for (int v : *a) cnt[6 - v]++;
    for (int v : *b) cnt[v - 1]++;
    int ops = 0;
    for (int g = 5; g >= 1 && diff > 0; --g) {
        if (cnt[g] == 0) continue;
        long long need = (diff + g - 1) / g;
        int use = static_cast<int>(std::min<long long>(cnt[g], need));
        diff -= static_cast<long long>(use) * g;
        ops += use;
    }
    return diff > 0 ? -1 : ops;
}

