int minOperations(const std::vector<int>& nums, int k) {
    const int MAX_VAL = 1024; // nums[i] <= 1023
    const int INF = 1e9;
    int n = static_cast<int>(nums.size());
    int period = k; // correct period
    std::vector<std::unordered_map<int, int>> freqMaps(period);
    std::vector<int> sizes(period, 0);
    for (int i = 0; i < n; ++i) {
        int r = i % period;
        ++sizes[r];
        ++freqMaps[r][nums[i]];
    }
    std::vector<int> dp(MAX_VAL, INF);
    dp[0] = 0;
    for (int r = 0; r < period; ++r) {
        int sz = sizes[r];
        if (sz == 0) continue;
        std::vector<int> ndp(MAX_VAL, INF);
        for (const auto& kv : freqMaps[r]) {
            int v = kv.first;
            int cnt = kv.second;
            int cost = sz - cnt;
            for (int prev = 0; prev < MAX_VAL; ++prev) {
                if (dp[prev] == INF) continue;
                int nx = prev ^ v;
                ndp[nx] = std::min(ndp[nx], dp[prev] + cost);
            }
        }
        int minPrev = INF;
        for (int prev = 0; prev < MAX_VAL; ++prev) {
            minPrev = std::min(minPrev, dp[prev]);
        }
        for (int x = 0; x < MAX_VAL; ++x) {
            ndp[x] = std::min(ndp[x], minPrev + sz);
        }
        dp.swap(ndp);
    }
    return dp[0];
}

