static double gain(int p, int t) {
    return static_cast<double>(p + 1) / (t + 1) - static_cast<double>(p) / t;
}

double maxAverageRatio(const std::vector<std::vector<int>>& classes, int extraStudents) {
    struct Node {
        double gain;
        int p;
        int t;
        bool operator<(const Node& other) const {
            return gain < other.gain;
        }
    };
    std::priority_queue<Node> heap;
    for (const auto& ct : classes) {
        int p = ct[0];
        int t = ct[1];
        heap.push({gain(p, t), p, t});
    }
    while (extraStudents-- > 0) {
        Node cur = heap.top();
        heap.pop();
        int newP = cur.p + 1;
        int newT = cur.t + 1;
        heap.push({gain(newP, newT), newP, newT});
    }
    double sum = 0.0;
    while (!heap.empty()) {
        Node cur = heap.top();
        heap.pop();
        sum += static_cast<double>(cur.p) / cur.t;
    }
    double avg = sum / static_cast<double>(classes.size());
    double rounded = std::round(avg * 1e5) / 1e5;
    return rounded;
}

