int maximumScore(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    int left = k, right = k;
    int curMin = nums[k];
    long long best = curMin;
    while (left > 0 || right < n - 1) {
        if (right == n - 1) {
            --left;
            curMin = std::min(curMin, nums[left]);
        } else if (left == 0) {
            ++right;
            curMin = std::min(curMin, nums[right]);
        } else {
            if (nums[left - 1] > nums[right + 1]) {
                --left;
                curMin = std::min(curMin, nums[left]);
            } else {
                ++right;
                curMin = std::min(curMin, nums[right]);
            }
        }
        long long length = right - left + 1;
        best = std::max(best, curMin * length);
    }
    return static_cast<int>(best);
}

#include <bits/stdc++.h>
#include <vector>
#include <numeric>
#include <functional>

int maxScore(std::vector<int>& nums) {
    int m = nums.size();
    int n = m / 2;
    int totalMask = 1 << m;
    std::vector<int> memo(totalMask, -1);
    auto gcd = [](int a, int b) {
        while (b) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    std::function<int(int)> dfs = [&](int mask) -> int {
        if (mask == totalMask - 1) return 0;
        int &res = memo[mask];
        if (res != -1) return res;
        int used = __builtin_popcount(mask);
        int op = used / 2 + 1;
        res = 0;
        int i = 0;
        while (i < m && (mask >> i & 1)) ++i;
        for (int j = i + 1; j < m; ++j) {
            if (mask >> j & 1) continue;
            int newMask = mask | (1 << i) | (1 << j);
            int cur = op * gcd(nums[i], nums[j]) + dfs(newMask);
            if (cur > res) res = cur;
        }
        return res;
    };
    return dfs(0);
}

