struct Node {
    int price;
    int amount;
};

static void heapPush(std::vector<Node>& heap, const Node& node, const std::function<bool(const Node&, const Node&)>& cmp) {
    heap.push_back(node);
    int i = static_cast<int>(heap.size()) - 1;
    while (i > 0) {
        int p = (i - 1) >> 1;
        if (cmp(heap[p], heap[i])) break;
        std::swap(heap[p], heap[i]);
        i = p;
    }
}

static Node heapPop(std::vector<Node>& heap, const std::function<bool(const Node&, const Node&)>& cmp) {
    Node top = heap[0];
    Node last = heap.back();
    heap.pop_back();
    if (!heap.empty()) {
        heap[0] = last;
        int i = 0;
        while (true) {
            int l = i * 2 + 1;
            int r = i * 2 + 2;
            int best = i;
            if (l < static_cast<int>(heap.size()) && !cmp(heap[best], heap[l])) best = l;
            if (r < static_cast<int>(heap.size()) && !cmp(heap[best], heap[r])) best = r;
            if (best == i) break;
            std::swap(heap[i], heap[best]);
            i = best;
        }
    }
    return top;
}

static Node& heapPeek(std::vector<Node>& heap) {
    return heap[0];
}

static std::size_t heapSize(const std::vector<Node>& heap) {
    return heap.size();
}

int getNumberOfBacklogOrders(const std::vector<std::vector<int>>& orders) {
    const long long MOD = 1000000007LL;
    std::vector<Node> buyHeap;
    std::vector<Node> sellHeap;
    auto buyCmp = [](const Node& a, const Node& b) { return a.price >= b.price; };
    auto sellCmp = [](const Node& a, const Node& b) { return a.price <= b.price; };

    for (const auto& ord : orders) {
        int price = ord[0];
        int amount = ord[1];
        int type = ord[2];
        if (type == 0) { // BUY
            while (amount > 0 && heapSize(sellHeap) && heapPeek(sellHeap).price <= price) {
                Node& sell = heapPeek(sellHeap);
                int matched = std::min(amount, sell.amount);
                amount -= matched;
                sell.amount -= matched;
                if (sell.amount == 0) {
                    heapPop(sellHeap, sellCmp);
                }
            }
            if (amount > 0) {
                heapPush(buyHeap, Node{price, amount}, buyCmp);
            }
        } else { // SELL
            while (amount > 0 && heapSize(buyHeap) && heapPeek(buyHeap).price >= price) {
                Node& buy = heapPeek(buyHeap);
                int matched = std::min(amount, buy.amount);
                amount -= matched;
                buy.amount -= matched;
                if (buy.amount == 0) {
                    heapPop(buyHeap, buyCmp);
                }
            }
            if (amount > 0) {
                heapPush(sellHeap, Node{price, amount}, sellCmp);
            }
        }
    }

    long long total = 0;
    for (const Node& node : buyHeap) total = (total + node.amount) % MOD;
    for (const Node& node : sellHeap) total = (total + node.amount) % MOD;
    return static_cast<int>(total);
}

#include <bits/stdc++.h>
int maxValue(int n, int index, int maxSum) {
    auto sideSum = [&](long long len, long long peak) -> long long {
        if (len <= peak) {
            return len * (2 * peak - len + 1) / 2;
        } else {
            long long sumPeak = peak * (peak + 1) / 2;
            return sumPeak + (len - peak);
        }
    };
    long long low = 1, high = maxSum;
    while (low < high) {
        long long mid = (low + high + 1) / 2;
        long long left = sideSum(index + 1, mid);
        long long right = sideSum(n - index, mid);
        long long total = left + right - mid;
        if (total <= maxSum) low = mid;
        else high = mid - 1;
    }
    return static_cast<int>(low);
}

