struct TrieNode {
    int cnt;
    TrieNode* child[2];
    TrieNode() : cnt(0) { child[0] = child[1] = nullptr; }
};

long long countPairs(const std::vector<int>& nums, int low, int high) {
    int maxVal = high;
    if (!nums.empty()) {
        maxVal = std::max(maxVal, *std::max_element(nums.begin(), nums.end()));
    }
    int maxBit = 0;
    while ((1LL << maxBit) <= maxVal) ++maxBit;
    --maxBit;

    TrieNode* root = new TrieNode();

    auto insert = [&](int num) {
        TrieNode* node = root;
        for (int i = maxBit; i >= 0; --i) {
            int bit = (num >> i) & 1;
            if (!node->child[bit]) node->child[bit] = new TrieNode();
            node = node->child[bit];
            ++node->cnt;
        }
    };

    auto query = [&](int num, int K) -> long long {
        if (K < 0) return 0;
        TrieNode* node = root;
        long long total = 0;
        for (int i = maxBit; i >= 0; --i) {
            if (!node) break;
            int bitNum = (num >> i) & 1;
            int bitK = (K >> i) & 1;
            if (bitK == 1) {
                if (node->child[bitNum]) total += node->child[bitNum]->cnt;
                node = node->child[1 - bitNum];
            } else {
                node = node->child[bitNum];
            }
        }
        if (node) total += node->cnt; // exact-match path: xor == K exactly, still <= K
        return total;
    };

    auto countLessOrEqual = [&](int bound) -> long long {
        long long ans = 0;
        for (int num : nums) {
            ans += query(num, bound);
            insert(num);
        }
        return ans;
    };
    long long r1 = countLessOrEqual(high);
    // reset trie for second pass since it can't be reused with same inserted elements
    root = new TrieNode();
    long long r2 = countLessOrEqual(low - 1);
    return r1 - r2;
}

