static const int MOD = 1000000007;

static long long modPow(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long maxNiceDivisors(int primeFactors) {
    if (primeFactors <= 3) return primeFactors;
    long long groups = primeFactors / 3;
    int rem = primeFactors % 3;
    long long ans;
    if (rem == 0) {
        ans = modPow(3, groups);
    } else if (rem == 1) {
        ans = modPow(3, groups - 1);
        ans = ans * 4 % MOD;
    } else { // rem == 2
        ans = modPow(3, groups);
        ans = ans * 2 % MOD;
    }
    return ans;
}

