bool areSentencesSimilar(const std::string& sentence1, const std::string& sentence2) {
    std::vector<std::string> words1;
    std::vector<std::string> words2;
    {
        std::istringstream iss(sentence1);
        std::string w;
        while (iss >> w) {
            words1.push_back(w);
