int maxHappyGroups(int batchSize, std::vector<int>& groups) {
    if (batchSize == 1) return static_cast<int>(groups.size());

    std::vector<int> cnt(batchSize, 0);
    int happy = 0;
    for (int g : groups) {
        int r = g % batchSize;
        if (r == 0) ++happy;
        else ++cnt[r];
    }

    auto encode = [&](const std::vector<int>& c, int cur) -> int64_t {
        int64_t key = cur;
        for (int r = 1; r < batchSize; ++r) {
            key |= (static_cast<int64_t>(c[r]) << (4 + (r - 1) * 5));
        }
        return key;
    };

    std::unordered_map<int64_t, int> memo;

    std::function<int(int64_t)> dfs = [&](int64_t key) -> int {
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;

        int cur = static_cast<int>(key & 15LL);
        int64_t countsPart = key >> 4;
        if (countsPart == 0) return memo[key] = 0;

        int best = 0;
        for (int r = 1; r < batchSize; ++r) {
            int shift = 4 + (r - 1) * 5;
            int cntR = static_cast<int>((key >> shift) & 31LL);
            if (cntR == 0) continue;

            int64_t newKey = key - (1LL << shift);
            int newCur = (cur + r) % batchSize;
            newKey = (newKey & (~15LL)) | newCur;

            int add = (cur == 0) ? 1 : 0;
            int cand = add + dfs(newKey);
            if (cand > best) best = cand;
        }
        memo[key] = best;
        return best;
    };

    int64_t startKey = encode(cnt, 0);
    happy += dfs(startKey);
    return happy;
}

