int minimumAbsoluteSumDifference(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    const int64_t MOD = 1000000007LL;
    std::size_t n = nums1.size();

    std::vector<int> sortedVals(nums1);
    std::sort(sortedVals.begin(), sortedVals.end());

    int64_t originalSum = 0;
    int64_t maxGain = 0;

    auto lowerBound = [&](const std::vector<int>& arr, int target) -> std::size_t {
        std::size_t left = 0, right = arr.size();
        while (left < right) {
            std::size_t mid = (left + right) >> 1;
            if (arr[mid] < target) left = mid + 1;
            else right = mid;
        }
        return left;
    };

    for (std::size_t i = 0; i < n; ++i) {
        int64_t diff = std::llabs(static_cast<int64_t>(nums1[i]) - static_cast<int64_t>(nums2[i]));
        originalSum = (originalSum + diff) % MOD;

        std::size_t pos = lowerBound(sortedVals, nums2[i]);

        int64_t best = diff;
        if (pos < n) {
            int64_t cand = std::llabs(static_cast<int64_t>(sortedVals[pos]) - static_cast<int64_t>(nums2[i]));
            if (cand < best) best = cand;
        }
        if (pos > 0) {
            int64_t cand = std::llabs(static_cast<int64_t>(sortedVals[pos - 1]) - static_cast<int64_t>(nums2[i]));
            if (cand < best) best = cand;
        }

        int64_t gain = diff - best;
        if (gain > maxGain) maxGain = gain;
    }

    return static_cast<int>((originalSum - maxGain + MOD) % MOD);
}

