long long countNicePairs(const std::vector<int>& nums) {
    const long long MOD = 1000000007LL;
    auto rev = [](long long x) -> long long {
        std::string s = std::to_string(x);
        std::reverse(s.begin(), s.end());
        return std::stoll(s);
    };
    std::unordered_map<long long, long long> freq;
    for (size_t i = 0; i < nums.size(); ++i) {
        long long diff = static_cast<long long>(nums[i]) - rev(nums[i]);
        ++freq[diff];
    }
    long long ans = 0;
    for (const auto& kv : freq) {
        long long cnt = kv.second;
        if (cnt > 1) {
            ans = (ans + (cnt * (cnt - 1) / 2) % MOD) % MOD;
        }
    }
    return ans;
}

