int minSideJumps(const std::vector<int>& obstacles) {
    const int INF = 1000000000;
    int dp[3] = {1, 0, 1};
    int n = static_cast<int>(obstacles.size());
    for (int i = 1; i < n; ++i) {
        for (int lane = 0; lane < 3; ++lane) {
            if (obstacles[i] == lane + 1) {
                dp[lane] = INF;
            }
        }
        for (int lane = 0; lane < 3; ++lane) {
            if (obstacles[i] == lane + 1) continue;
            int best = INF;
            for (int other = 0; other < 3; ++other) {
                if (other == lane) continue;
                best = std::min(best, dp[other]);
            }
            dp[lane] = std::min(dp[lane], 1 + best);
        }
    }
    return std::min({dp[0], dp[1], dp[2]});
}

