static int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int countDifferentSubsequenceGCDs(std::vector<int>& nums) {
    int maxVal = 0;
    for (int x : nums) if (x > maxVal) maxVal = x;
    std::vector<int> freq(maxVal + 1, 0);
    for (int x : nums) ++freq[x];
    int answer = 0;
    for (int g = 1; g <= maxVal; ++g) {
        int cur = 0;
        for (int m = g; m <= maxVal; m += g) {
            if (freq[m] == 0) continue;
            if (cur == 0) cur = m;
            else cur = gcd_int(cur, m);
            if (cur == g) break;
        }
        if (cur == g) ++answer;
    }
    return answer;
}

