std::vector<int> countPoints(const std::vector<std::vector<int>>& points, const std::vector<std::vector<int>>& queries) {
    const int MAXC = 500;
    std::vector<std::vector<int>> grid(MAXC + 1, std::vector<int>(MAXC + 1, 0));
    for (const auto& p : points) {
        int x = p[0];
        int y = p[1];
        if (x >= 0 && x <= MAXC && y >= 0 && y <= MAXC) {
            ++grid[x][y];
        }
    }
    std::vector<std::vector<int>> rowPref(MAXC + 1, std::vector<int>(MAXC + 1, 0));
    for (int y = 0; y <= MAXC; ++y) {
        int running = 0;
        for (int x = 0; x <= MAXC; ++x) {
            running += grid[x][y];
            rowPref[y][x] = running;
        }
    }
    std::vector<int> answer;
    answer.reserve(queries.size());
    for (const auto& q : queries) {
        int cx = q[0];
        int cy = q[1];
        int r = q[2];
        long long r2 = 1LL * r * r;
        int cnt = 0;
        int yStart = std::max(0, cy - r);
        int yEnd = std::min(MAXC, cy + r);
        for (int y = yStart; y <= yEnd; ++y) {
            long long dy = y - cy;
            long long remain = r2 - dy * dy;
            if (remain < 0) continue;
            int dx = static_cast<int>(std::sqrt(static_cast<double>(remain)));
            while (1LL * (dx + 1) * (dx + 1) <= remain) ++dx;
            while (1LL * dx * dx > remain) --dx;
            int xLeft = std::max(0, cx - dx);
            int xRight = std::min(MAXC, cx + dx);
            int rowSum = rowPref[y][xRight];
            if (xLeft > 0) rowSum -= rowPref[y][xLeft - 1];
            cnt += rowSum;
        }
        answer.push_back(cnt);
    }
    return answer;
}

#include <bits/stdc++.h>
int minOperations(std::string s) {
    const int MOD = 1000000007;
    int n = (int)s.size();
    std::vector<long long> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
    auto modpow = [&](long long a, long long e) {
        long long res = 1;
        while (e) {
            if (e & 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    };
    invFact[n] = modpow(fact[n], MOD - 2);
    for (int i = n; i >= 1; --i) invFact[i - 1] = invFact[i] * i % MOD;
    std::vector<int> cnt(26, 0);
    for (char ch : s) cnt[ch - 'a']++;
    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        int cur = s[i] - 'a';
        for (int c = 0; c < cur; ++c) {
            if (cnt[c] == 0) continue;
            cnt[c]--;
            int rem = n - i - 1;
            long long ways = fact[rem];
            for (int k = 0; k < 26; ++k) ways = ways * invFact[cnt[k]] % MOD;
            ans = (ans + ways) % MOD;
            cnt[c]++;
        }
        cnt[cur]--;
    }
    return (int)ans;
}

#include <bits/stdc++.h>

class MKAverage {
private:
    int m, k;
    long long sumMid;
    std::queue<int> q;
    std::multiset<int> low, mid, high;

    void rebalance() {
        while ((int)low.size() < k && !mid.empty()) {
            auto it = mid.begin();
            int val = *it;
            mid.erase(it);
            sumMid -= val;
            low.insert(val);
        }
        while ((int)high.size() < k && !mid.empty()) {
            auto it = std::prev(mid.end());
            int val = *it;
            mid.erase(it);
            sumMid -= val;
            high.insert(val);
        }
        while ((int)low.size() > k) {
            auto it = std::prev(low.end());
            int val = *it;
            low.erase(it);
            mid.insert(val);
            sumMid += val;
        }
        while ((int)high.size() > k) {
            auto it = high.begin();
            int val = *it;
            high.erase(it);
            mid.insert(val);
            sumMid += val;
        }
        // FIXED: the two cross-checks below (low-vs-mid and high-vs-mid) must keep
        // repeating together until BOTH are simultaneously satisfied. The original
        // code ran each one only once in sequence, so a swap made by the second
        // check (high vs mid) could re-violate the first check's invariant
        // (low vs mid) without it ever being re-examined - confirmed by a concrete
        // trace where a stale small value got stuck in "low" while a smaller value
        // ended up in "mid", making calculateMKAverage() return the wrong sum.
        bool changed = true;
        while (changed) {
            changed = false;
            while (!low.empty() && !mid.empty() && *std::prev(low.end()) > *mid.begin()) {
                int lowMax = *std::prev(low.end());
                int midMin = *mid.begin();
                low.erase(std::prev(low.end()));
                mid.erase(mid.begin());
                low.insert(midMin);
                mid.insert(lowMax);
                sumMid += lowMax - midMin;
                changed = true;
            }
            while (!high.empty() && !mid.empty() && *high.begin() < *std::prev(mid.end())) {
                int highMin = *high.begin();
                int midMax = *std::prev(mid.end());
                high.erase(high.begin());
                mid.erase(std::prev(mid.end()));
                high.insert(midMax);
                mid.insert(highMin);
                sumMid += highMin - midMax;
                changed = true;
            }
        }
    }

public:
    MKAverage(int m_, int k_) : m(m_), k(k_), sumMid(0) {}

    void addElement(int num) {
        q.push(num);
        mid.insert(num);
        sumMid += num;
        rebalance();

        if ((int)q.size() > m) {
            int old = q.front();
            q.pop();
            if (low.find(old) != low.end()) {
                low.erase(low.find(old));
            } else if (high.find(old) != high.end()) {
                high.erase(high.find(old));
            } else {
                auto it = mid.find(old);
                if (it != mid.end()) {
                    sumMid -= old;
                    mid.erase(it);
                }
            }
            rebalance();
        }
    }

    int calculateMKAverage() {
        if ((int)q.size() < m) return -1;
        return static_cast<int>(sumMid / (m - 2 * k));
    }
};

