int maxIceCream(const std::vector<int>& costs, int coins) {
    int maxCost = 0;
    for (int c : costs) {
        if (c > maxCost) maxCost = c;
    }

    std::vector<int> freq(maxCost + 1, 0);
    for (int c : costs) {
        ++freq[c];
    }

    int bought = 0;
    int remaining = coins;

    for (int price = 1; price <= maxCost && remaining >= price; ++price) {
        if (freq[price] == 0) continue;
        int affordable = remaining / price;
        int take = std::min(freq[price], affordable);
        bought += take;
        remaining -= take * price;
    }

    return bought;
}

