std::vector<int> getOrder(const std::vector<std::vector<int>>& tasks) {
    std::vector<std::array<int, 3>> tasksWithIdx;
    tasksWithIdx.reserve(tasks.size());
    for (size_t i = 0; i < tasks.size(); ++i) {
        tasksWithIdx.push_back({tasks[i][0], tasks[i][1], static_cast<int>(i)});
    }
    std::sort(tasksWithIdx.begin(), tasksWithIdx.end(),
        [](const std::array<int, 3>& a, const std::array<int, 3>& b) {
            return a[0] < b[0];
        });
    struct Compare {
        bool operator()(const std::array<int, 2>& a, const std::array<int, 2>& b) const {
            if (a[0] != b[0]) return a[0] > b[0];
            return a[1] > b[1];
        }
    };
    std::priority_queue<std::array<int, 2>, std::vector<std::array<int, 2>>, Compare> heap;
    std::vector<int> result;
    result.reserve(tasks.size());
    long long time = 0;
    size_t i = 0;
    size_t n = tasksWithIdx.size();
    while (result.size() < n) {
        while (i < n && tasksWithIdx[i][0] <= time) {
            heap.push({tasksWithIdx[i][1], tasksWithIdx[i][2]});
            ++i;
        }
        if (!heap.empty()) {
            auto top = heap.top();
            heap.pop();
            int proc = top[0];
            int idx = top[1];
            time += proc;
            result.push_back(idx);
        } else {
            time = tasksWithIdx[i][0];
        }
    }
    return result;
}

