int maximumBuildingHeight(int n, std::vector<std::vector<int>> restrictions) {
    restrictions.push_back({1, 0});
    std::sort(restrictions.begin(), restrictions.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[0] < b[0];
              });

    for (size_t i = 1; i < restrictions.size(); ++i) {
        int dist = restrictions[i][0] - restrictions[i - 1][0];
        int allowed = restrictions[i - 1][1] + dist;
        if (restrictions[i][1] > allowed) {
            restrictions[i][1] = allowed;
        }
    }

    for (int i = static_cast<int>(restrictions.size()) - 2; i >= 0; --i) {
        int dist = restrictions[i + 1][0] - restrictions[i][0];
        int allowed = restrictions[i + 1][1] + dist;
        if (restrictions[i][1] > allowed) {
            restrictions[i][1] = allowed;
        }
    }

    int answer = 0;

    for (size_t i = 0; i + 1 < restrictions.size(); ++i) {
        int leftIdx = restrictions[i][0];
        int leftH = restrictions[i][1];
        int rightIdx = restrictions[i + 1][0];
        int rightH = restrictions[i + 1][1];
        int d = rightIdx - leftIdx;
        int diff = std::abs(leftH - rightH);
        int localMax = std::max(leftH, rightH) + (d - diff) / 2;
        if (localMax > answer) answer = localMax;
    }

    int lastIdx = restrictions.back()[0];
    int lastH = restrictions.back()[1];
    int tailMax = lastH + (n - lastIdx);
    if (tailMax > answer) answer = tailMax;

    return answer;
}

