struct SeatManagerObj {
    std::vector<int> heap;
    SeatManagerObj(int n) {
        heap.reserve(n);
        for (int i = 1; i <= n; ++i) heapPush(i);
    }
    void heapPush(int val) {
        heap.push_back(val);
        int i = heap.size() - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
    }
    int heapPop() {
        int min = heap[0];
        int last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            int i = 0;
            while (true) {
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                int smallest = i;
                if (l < (int)heap.size() && heap[l] < heap[smallest]) smallest = l;
                if (r < (int)heap.size() && heap[r] < heap[smallest]) smallest = r;
                if (smallest == i) break;
                std::swap(heap[i], heap[smallest]);
                i = smallest;
            }
        }
        return min;
    }
    int reserve() {
        return heapPop();
    }
    void release(int seatNumber) {
        heapPush(seatNumber);
    }
};

SeatManagerObj SeatManager(int n) {
    return SeatManagerObj(n);
}

