std::vector<int> closestRoom(const std::vector<std::vector<int>>& rooms,
                             const std::vector<std::vector<int>>& queries) {
    // Prepare rooms sorted by size descending
    std::vector<std::pair<int, int>> roomList;
    roomList.reserve(rooms.size());
    for (const auto& r : rooms) {
        roomList.emplace_back(r[1], r[0]); // (size, id)
    }
    std::sort(roomList.begin(), roomList.end(),
              [](const auto& a, const auto& b) { return a.first > b.first; });

    // Prepare queries with original indices
    struct Q {
        int preferred;
        int minSize;
        int idx;
    };
    std::vector<Q> qlist;
    qlist.reserve(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        qlist.push_back({queries[i][0], queries[i][1], static_cast<int>(i)});
    }
    std::sort(qlist.begin(), qlist.end(),
              [](const Q& a, const Q& b) { return a.minSize > b.minSize; });

    std::vector<int> answer(queries.size(), -1);
    std::set<int> ids; // eligible room ids
    size_t rp = 0; // pointer in roomList

    for (const auto& q : qlist) {
        // Add all rooms whose size >= current query's minSize
        while (rp < roomList.size() && roomList[rp].first >= q.minSize) {
            ids.insert(roomList[rp].second);
            ++rp;
        }

        if (ids.empty()) {
            answer[q.idx] = -1;
            continue;
        }

        auto it = ids.lower_bound(q.preferred);
        int bestId = -1;
        int bestDiff = INT_MAX;

        if (it != ids.end()) {
            int cand = *it;
            int diff = std::abs(cand - q.preferred);
            if (diff < bestDiff || (diff == bestDiff && cand < bestId)) {
                bestDiff = diff;
                bestId = cand;
            }
        }
        if (it != ids.begin()) {
            --it;
            int cand = *it;
            int diff = std::abs(cand - q.preferred);
            if (diff < bestDiff || (diff == bestDiff && cand < bestId)) {
                bestDiff = diff;
                bestId = cand;
            }
        }

        answer[q.idx] = bestId;
    }

    return answer;
}

