int maximumPopulation(const std::vector<std::vector<int>>& logs) {
    std::unordered_map<int, int> diff;
    for (size_t i = 0; i < logs.size(); ++i) {
        int birth = logs[i][0];
        int death = logs[i][1];
        diff[birth] = diff.count(birth) ? diff[birth] + 1 : 1;
        diff[death] = diff.count(death) ? diff[death] - 1 : -1;
    }

    std::vector<int> years;
    years.reserve(diff.size());
    for (const auto& kv : diff) {
        years.push_back(kv.first);
    }
    std::sort(years.begin(), years.end());

    int cur = 0;
    int max = 0;
    int answer = 0;
    for (size_t i = 0; i < years.size(); ++i) {
        int year = years[i];
        cur += diff[year];
        if (cur > max) {
            max = cur;
            answer = year;
        }
    }
    return answer;
}

