static std::string trimLeadingZeros(const std::string& s) {
    std::size_t pos = s.find_first_not_of('0');
    if (pos == std::string::npos) return "0";
    return s.substr(pos);
}

static int compareNumeric(const std::string& a, const std::string& b) {
    std::string ta = trimLeadingZeros(a);
    std::string tb = trimLeadingZeros(b);
    if (ta.size() != tb.size()) return ta.size() < tb.size() ? -1 : 1;
    if (ta == tb) return 0;
    return ta < tb ? -1 : 1;
}

static std::string decrementString(const std::string& num) {
    if (num.empty() || trimLeadingZeros(num) == "0") return "";
    std::string res = num;
    int i = static_cast<int>(res.size()) - 1;
    while (i >= 0) {
        if (res[i] > '0') {
            res[i]--;
            break;
        } else {
            res[i] = '9';
            --i;
        }
    }
    return trimLeadingZeros(res);
}

static bool dfs(const std::string& s, std::size_t idx, const std::string& prev) {
    if (idx == s.size()) return true;
    std::string next = decrementString(prev);
    if (next.empty()) return false;
    for (std::size_t i = idx + 1; i <= s.size(); ++i) {
        std::string cur = s.substr(idx, i - idx);
        int cmp = compareNumeric(cur, next);
        if (cmp == 0) {
            if (dfs(s, i, next)) return true;
        } else if (cmp > 0) {
            break;
        }
    }
    return false;
}

bool splitString(const std::string& s) {
    std::size_t n = s.size();
    for (std::size_t i = 1; i < n; ++i) {
        std::string first = s.substr(0, i);
        if (dfs(s, i, first)) return true;
    }
    return false;
}

#include <bits/stdc++.h>
int getMinSwaps(std::string num, int k) {
    std::string target = num;
    for (int i = 0; i < k; ++i) {
        std::next_permutation(target.begin(), target.end());
    }
    std::vector<char> cur(num.begin(), num.end());
    int swaps = 0;
    int n = cur.size();
    for (int i = 0; i < n; ++i) {
        if (cur[i] == target[i]) continue;
        int j = i + 1;
        while (j < n && cur[j] != target[i]) ++j;
        while (j > i) {
            std::swap(cur[j], cur[j - 1]);
            ++swaps;
            --j;
        }
    }
    return swaps;
}

