std::vector<int> minInterval(std::vector<std::vector<int>>& intervals, std::vector<int>& queries) {
    std::sort(intervals.begin(), intervals.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) { return a[0] < b[0]; });

    std::vector<std::pair<int, int>> qs;
    qs.reserve(queries.size());
    for (int i = 0; i < (int)queries.size(); ++i) {
        qs.emplace_back(queries[i], i);
    }
    std::sort(qs.begin(), qs.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) { return a.first < b.first; });

    std::vector<int> res(queries.size(), -1);

    struct Node {
        int size;
        int right;
    };
    auto comp = [](const Node& a, const Node& b) { return a.size > b.size; };
    std::priority_queue<Node, std::vector<Node>, decltype(comp)> heap(comp);

    size_t i = 0;
    for (const auto& qr : qs) {
        int q = qr.first;
        int idx = qr.second;

        while (i < intervals.size() && intervals[i][0] <= q) {
            int left = intervals[i][0];
            int right = intervals[i][1];
            heap.emplace(Node{right - left + 1, right});
            ++i;
        }
        while (!heap.empty() && heap.top().right < q) {
            heap.pop();
        }
        if (!heap.empty()) {
            res[idx] = heap.top().size;
        }
    }
    return res;
}

#include <bits/stdc++.h>

int largestPathValue(const std::string& colors, const std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(colors.size());
    std::vector<std::vector<int>> adj(n);
    std::vector<int> indeg(n, 0);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        ++indeg[v];
    }
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) q.push(i);
    }
    std::vector<std::array<int, 26>> dp(n);
    for (int i = 0; i < n; ++i) dp[i].fill(0);
    int processed = 0;
    int answer = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        ++processed;
        int col = colors[u] - 'a';
        ++dp[u][col];
        if (dp[u][col] > answer) answer = dp[u][col];
        for (int v : adj[u]) {
            for (int c = 0; c < 26; ++c) {
                if (dp[u][c] > dp[v][c]) dp[v][c] = dp[u][c];
            }
            if (--indeg[v] == 0) q.push(v);
        }
    }
    if (processed != n) return -1;
    return answer;
}

