#if defined(__SIZEOF_INT128__)
using int128 = __int128;
#else
using int128 = long long;
#endif

long long maxSumMinProduct(const std::vector<int>& nums) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(nums.size());
    std::vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + static_cast<long long>(nums[i]);
    }

    std::vector<int> left(n), right(n);
    std::vector<int> st;
    st.reserve(n);

    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[st.back()] >= nums[i]) {
            st.pop_back();
        }
        left[i] = st.empty() ? -1 : st.back();
        st.push_back(i);
    }

    st.clear();

    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && nums[st.back()] >= nums[i]) {
            st.pop_back();
        }
        right[i] = st.empty() ? n : st.back();
        st.push_back(i);
    }

    int128 maxProd = 0;
    for (int i = 0; i < n; ++i) {
        int l = left[i];
        int r = right[i];
        long long subSum = prefix[r] - prefix[l + 1];
        int128 prod = static_cast<int128>(nums[i]) * subSum;
        if (prod > maxProd) {
            maxProd = prod;
        }
    }

    return static_cast<long long>(maxProd % MOD);
}

