std::vector<long long> incrementalMemoryLeak(long long memory1, long long memory2) {
    long long time = 1;
    while (true) {
        bool useFirst = memory1 >= memory2;
        if (useFirst ? memory1 < time : memory2 < time) break;
        if (useFirst) {
            memory1 -= time;
        } else {
            memory2 -= time;
        }
        ++time;
    }
    return {time, memory1, memory2};
}

