struct FindSumPairsObj {
    std::vector<int>* nums1;
    std::vector<int>* nums2;
    std::unordered_map<int, int> freq;

    FindSumPairsObj(std::vector<int>& n1, std::vector<int>& n2) : nums1(&n1), nums2(&n2) {
        for (int v : n2) {
            ++freq[v];
        }
    }

    void add(int index, int val) {
        int oldVal = (*nums2)[index];
        int newVal = oldVal + val;

        auto itOld = freq.find(oldVal);
        if (itOld != freq.end()) {
            if (itOld->second == 1) {
                freq.erase(itOld);
            } else {
                itOld->second -= 1;
            }
        }

        ++freq[newVal];
        (*nums2)[index] = newVal;
    }

    int count(int tot) const {
        long long totalPairs = 0;
        for (int x : *nums1) {
            auto it = freq.find(tot - x);
            if (it != freq.end()) {
                totalPairs += it->second;
            }
        }
        return static_cast<int>(totalPairs);
    }
};

FindSumPairsObj FindSumPairs(std::vector<int>& nums1, std::vector<int>& nums2) {
    return FindSumPairsObj(nums1, nums2);
}

