std::vector<std::vector<char>> rotateTheBox(std::vector<std::vector<char>> boxGrid) {
    int m = boxGrid.size();
    int n = boxGrid[0].size();

    for (int i = 0; i < m; ++i) {
        int emptyPos = n - 1;
        for (int j = n - 1; j >= 0; --j) {
            char cell = boxGrid[i][j];
            if (cell == '*') {
                emptyPos = j - 1;
            } else if (cell == '#') {
                if (emptyPos != j) {
                    boxGrid[i][emptyPos] = '#';
                    boxGrid[i][j] = '.';
                }
                --emptyPos;
            }
        }
    }

    std::vector<std::vector<char>> rotated(n, std::vector<char>(m));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            rotated[j][m - 1 - i] = boxGrid[i][j];
        }
    }
    return rotated;
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>

long long sumOfFlooredPairs(const std::vector<int>& nums) {
    int maxVal = 0;
    for (int v : nums) {
        if (v > maxVal) maxVal = v;
    }

    std::vector<int> cnt(maxVal + 1, 0);
    for (int v : nums) {
        ++cnt[v];
    }

    std::vector<int> pref(maxVal + 1, 0);
    for (int i = 1; i <= maxVal; ++i) {
        pref[i] = pref[i - 1] + cnt[i];
    }

    unsigned long long answer = 0ULL;
    for (int d = 1; d <= maxVal; ++d) {
        if (cnt[d] == 0) continue;
        unsigned long long freqDen = static_cast<unsigned long long>(cnt[d]);

        for (int k = 1; k * d <= maxVal; ++k) {
            int left = k * d;
            int right = std::min((k + 1) * d - 1, maxVal);
            int rangeCount = pref[right] - pref[left - 1];
            if (rangeCount == 0) continue;

            unsigned long long contrib = freqDen * static_cast<unsigned long long>(k) *
                                         static_cast<unsigned long long>(rangeCount);
            answer += contrib;
        }
    }

    return static_cast<long long>(answer);
}

