long long subsetXORSum(const std::vector<int>& nums) {
    long long sum = 0;
    std::function<void(int, int)> dfs = [&](int idx, int curXor) {
        if (idx == static_cast<int>(nums.size())) {
            sum += curXor;
            return;
        }
        dfs(idx + 1, curXor);
        dfs(idx + 1, curXor ^ nums[idx]);
    };
    dfs(0, 0);
    return sum;
}

