int minSwapsAlternating(const std::string& s) {
    std::size_t n = s.length();
    int zeros = 0, ones = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (s[i] == '0') ++zeros;
        else ++ones;
    }

    if (std::abs(zeros - ones) > 1) return -1;
    if (n % 2 == 0 && zeros != ones) return -1;

    int mismatchesStart0 = 0;
    int mismatchesStart1 = 0;

    for (std::size_t i = 0; i < n; ++i) {
        char expected0 = (i % 2 == 0) ? '0' : '1';
        char expected1 = (i % 2 == 0) ? '1' : '0';
        if (s[i] != expected0) ++mismatchesStart0;
        if (s[i] != expected1) ++mismatchesStart1;
    }

    if (n % 2 == 0) {
        return std::min(mismatchesStart0, mismatchesStart1) / 2;
    } else {
        if (zeros > ones) return mismatchesStart0 / 2;
        else return mismatchesStart1 / 2;
    }
}

