bool longerOnesThanZeros(const std::string& s) {
    int maxOnes = 0;
    int maxZeros = 0;
    char currentChar = '\0';
    int currentLen = 0;

    for (size_t i = 0; i < s.size(); ++i) {
        char ch = s[i];
        if (ch == currentChar) {
            ++currentLen;
        } else {
            if (currentChar == '1') maxOnes = std::max(maxOnes, currentLen);
            else if (currentChar == '0') maxZeros = std::max(maxZeros, currentLen);
            currentChar = ch;
            currentLen = 1;
        }
    }

    if (currentChar == '1') maxOnes = std::max(maxOnes, currentLen);
    else if (currentChar == '0') maxZeros = std::max(maxZeros, currentLen);

    return maxOnes > maxZeros;
}

