long long rearrangeSticks(int n, int k) {
    const long long MOD = 1000000007LL;
    if (k > n) return 0;
    std::vector<long long> dp(k + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= n; ++i) {
        std::vector<long long> ndp(k + 1, 0);
        int limit = std::min(i, k);
        for (int j = 1; j <= limit; ++j) {
            ndp[j] = (dp[j - 1] + static_cast<long long>(i - 1) * dp[j]) % MOD;
        }
        dp.swap(ndp);
    }
    return dp[k];
}

