int minSpeedOnTime(const std::vector<int>& dist, double hour) {
    int n = static_cast<int>(dist.size());
    if (hour <= n - 1) return -1;
    const int MAX_SPEED = 10000000;
    int low = 1, high = MAX_SPEED;
    auto isFeasible = [&](int v) {
        double total = 0;
        for (int i = 0; i < n - 1; ++i) {
            total += std::ceil(static_cast<double>(dist[i]) / v);
        }
        total += static_cast<double>(dist[n - 1]) / v;
        return total <= hour;
    };
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (isFeasible(mid)) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return isFeasible(low) ? low : -1;
}

