bool canReach(const std::string& s, int minJump, int maxJump) {
    int n = static_cast<int>(s.size());
    if (n == 0) return false;
    if (s[0] != '0' || s[n - 1] != '0') return false;
    std::vector<bool> reachable(n, false);
    reachable[0] = true;
    int windowSum = 0;
    for (int i = 1; i < n; ++i) {
        if (i - minJump >= 0 && reachable[i - minJump]) {
            ++windowSum;
        }
        if (i - maxJump - 1 >= 0 && reachable[i - maxJump - 1]) {
            --windowSum;
        }
        if (s[i] == '0' && windowSum > 0) {
            reachable[i] = true;
        }
    }
    return reachable[n - 1];
}

