#include <vector>
#include <algorithm>
#include <unordered_set>

std::vector<int> getBiggestThree(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<long long>> diag1(m, std::vector<long long>(n, 0));
    std::vector<std::vector<long long>> diag2(m, std::vector<long long>(n, 0));

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            diag1[i][j] = grid[i][j];
            if (i > 0 && j > 0) diag1[i][j] += diag1[i - 1][j - 1];
            diag2[i][j] = grid[i][j];
            if (i > 0 && j + 1 < n) diag2[i][j] += diag2[i - 1][j + 1];
        }
    }

    auto getDiag1Sum = [&](int x1, int y1, int x2, int y2) -> long long {
        long long res = diag1[x2][y2];
        if (x1 > 0 && y1 > 0) res -= diag1[x1 - 1][y1 - 1];
        return res;
    };
    auto getDiag2Sum = [&](int x1, int y1, int x2, int y2) -> long long {
        long long res = diag2[x2][y2];
        if (x1 > 0 && y1 + 1 < n) res -= diag2[x1 - 1][y1 + 1];
        return res;
    };

    std::unordered_set<long long> uniq;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            uniq.insert(grid[i][j]); // k = 0
            for (int k = 1; i + 2 * k < m && j - k >= 0 && j + k < n; ++k) {
                long long edge1 = getDiag1Sum(i, j, i + k, j + k);
                long long edge2 = getDiag2Sum(i + k, j + k, i + 2 * k, j);
                long long edge3 = getDiag1Sum(i + k, j - k, i + 2 * k, j);
                long long edge4 = getDiag2Sum(i, j, i + k, j - k);
                long long border = edge1 + edge2 + edge3 + edge4
                                 - grid[i][j] - grid[i + k][j + k]
                                 - grid[i + 2 * k][j] - grid[i + k][j - k];
                uniq.insert(border);
            }
        }
    }

    std::vector<int> result;
    result.reserve(uniq.size());
    for (long long v : uniq) result.push_back(static_cast<int>(v));
    std::sort(result.begin(), result.end(), std::greater<int>());
    if (result.size() > 3) result.resize(3);
    return result;
}

