int stoneGameVIII(std::vector<int>& stones) {
    std::size_t n = stones.size();
    std::vector<long long> pref(n);
    pref[0] = stones[0];
    for (std::size_t i = 1; i < n; ++i) {
        pref[i] = pref[i - 1] + stones[i];
    }
    long long best = pref[n - 1]; // dp[n-1] = 0, so pref[n-1] - 0
    long long dp_i = 0;
    for (std::size_t idx = n - 2; idx < n; --idx) {
        dp_i = best;
        long long candidate = pref[idx] - dp_i;
        if (candidate > best) best = candidate;
        if (idx == 0) break; // prevent underflow since size_t is unsigned
    }
    return static_cast<int>(dp_i);
}

