std::string maxValue(const std::string& n, int x) {
    char xc = static_cast<char>('0' + x);
    if (!n.empty() && n[0] == '-') {
        // Negative number: insert before first digit greater than x
        std::size_t i = 1;
        while (i < n.size() && n[i] <= xc) {
            ++i;
        }
        return n.substr(0, i) + xc + n.substr(i);
    } else {
        // Positive number: insert before first digit smaller than x
        std::size_t i = 0;
        while (i < n.size() && n[i] >= xc) {
            ++i;
        }
        return n.substr(0, i) + xc + n.substr(i);
    }
}

