        ++left;
        --right;
    }
    return maxSum;
}

#include <bits/stdc++.h>
std::vector<int> assignTasks(std::vector<int>& servers, std::vector<int>& tasks) {
    int n = servers.size();
    int m = tasks.size();
    std::vector<int> ans(m);
    using FreePair = std::pair<int,int>; // (weight, index)
    using BusyTuple = std::tuple<long long,int,int>; // (free_time, weight, index)

    std::priority_queue<FreePair, std::vector<FreePair>, std::greater<FreePair>> freePQ;
    for (int i = 0; i < n; ++i) freePQ.emplace(servers[i], i);

    std::priority_queue<BusyTuple, std::vector<BusyTuple>, std::greater<BusyTuple>> busyPQ;
    std::queue<int> waiting;
    long long curTime = 0;

    for (int i = 0; i < m; ++i) {
        curTime = std::max<long long>(curTime, i);
        waiting.push(i);

        while (true) {
            while (!busyPQ.empty() && std::get<0>(busyPQ.top()) <= curTime) {
                auto top = busyPQ.top();
                busyPQ.pop();
                long long ft = std::get<0>(top);
                int w = std::get<1>(top);
                int idx = std::get<2>(top);
                freePQ.emplace(w, idx);
            }
            if (freePQ.empty()) {
                curTime = std::get<0>(busyPQ.top());
                continue;
            }
            while (!freePQ.empty() && !waiting.empty()) {
                int taskIdx = waiting.front();
                waiting.pop();
                auto freeTop = freePQ.top();
                freePQ.pop();
                int w = freeTop.first;
                int idx = freeTop.second;
                ans[taskIdx] = idx;
                long long finish = curTime + tasks[taskIdx];
                busyPQ.emplace(finish, w, idx);
            }
            if (waiting.empty()) break;
            curTime = std::get<0>(busyPQ.top());
        }
    }
    return ans;
}

#include <bits/stdc++.h>
int minSkips(std::vector<int>& dist, int speed, int hoursBefore) {
    const double INF = 1e18;
    int n = dist.size();
    std::vector<double> dp(n + 1, INF);
    dp[0] = 0.0;
    for (int i = 0; i < n - 1; ++i) {
        double travel = static_cast<double>(dist[i]) / speed;
        std::vector<double> ndp(n + 1, INF);
        for (int k = 0; k <= n; ++k) {
            if (dp[k] >= INF) continue;
            // not skip: wait until next integer hour
            double t = std::ceil(dp[k] + travel - 1e-9);
            if (t < ndp[k]) ndp[k] = t;
            // skip: no waiting
            if (k + 1 <= n) {
                double tskip = dp[k] + travel;
                if (tskip < ndp[k + 1]) ndp[k + 1] = tskip;
            }
        }
        dp.swap(ndp);
    }
    // last road, no waiting after it
    double lastTravel = static_cast<double>(dist.back()) / speed;
    for (int k = 0; k <= n; ++k) {
        if (dp[k] < INF) dp[k] += lastTravel;
    }
    for (int k = 0; k <= n; ++k) {
        if (dp[k] <= hoursBefore + 1e-9) return k;
    }
    return -1;
}

#include <bits/stdc++.h>
#include <vector>
#include <climits>

int minimumXORSum(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    int n = static_cast<int>(nums1.size());
    int totalMask = 1 << n;
    const int INF = INT_MAX;
    std::vector<int> dp(totalMask, INF);
    dp[0] = 0;

    auto popcount = [](int x) {
        int cnt = 0;
        while (x) {
            x &= x - 1;
            ++cnt;
        }
        return cnt;
    };

    for (int mask = 1; mask < totalMask; ++mask) {
        int i = popcount(mask) - 1;
        for (int j = 0; j < n; ++j) {
            if (mask & (1 << j)) {
                int prev = mask ^ (1 << j);
                int candidate = dp[prev] + (nums1[i] ^ nums2[j]);
                if (candidate < dp[mask]) dp[mask] = candidate;
            }
        }
    }
    return dp[totalMask - 1];
}

