int minFlips(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::string t = s + s;
    int answer = n;

    // Pattern starting with '0'
    int mismatches = 0;
    for (int i = 0; i < n; ++i) {
        char expected = (i % 2 == 0) ? '0' : '1';
        if (t[i] != expected) ++mismatches;
    }
    answer = std::min(answer, mismatches);
    for (int i = n; i < 2 * n; ++i) {
        int outIdx = i - n;
        char expectedOut = (outIdx % 2 == 0) ? '0' : '1';
        if (t[outIdx] != expectedOut) --mismatches;
        char expectedIn = (i % 2 == 0) ? '0' : '1';
        if (t[i] != expectedIn) ++mismatches;
        answer = std::min(answer, mismatches);
    }

    // Pattern starting with '1'
    mismatches = 0;
    for (int i = 0; i < n; ++i) {
        char expected = (i % 2 == 0) ? '1' : '0';
        if (t[i] != expected) ++mismatches;
    }
    answer = std::min(answer, mismatches);
    for (int i = n; i < 2 * n; ++i) {
        int outIdx = i - n;
        char expectedOut = (outIdx % 2 == 0) ? '1' : '0';
        if (t[outIdx] != expectedOut) --mismatches;
        char expectedIn = (i % 2 == 0) ? '1' : '0';
        if (t[i] != expectedIn) ++mismatches;
        answer = std::min(answer, mismatches);
    }

    return answer;
}

