long long minWastedSpace(std::vector<int> packages, std::vector<std::vector<int>> boxes) {
    const long long MOD = 1000000007LL;

    std::sort(packages.begin(), packages.end());
    int n = static_cast<int>(packages.size());
    std::vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + packages[i];
    }

    long long best = std::numeric_limits<long long>::max();

    for (auto& supplier : boxes) {
        std::sort(supplier.begin(), supplier.end());
        if (supplier.empty() || supplier.back() < packages.back()) continue;

        long long waste = 0;
        int prevIdx = 0;

        for (int size : supplier) {
            int idx = static_cast<int>(std::upper_bound(packages.begin(), packages.end(), size) - packages.begin());
            int cnt = idx - prevIdx;
            if (cnt > 0) {
                waste += static_cast<long long>(size) * cnt - (prefix[idx] - prefix[prevIdx]);
            }
            prevIdx = idx;
            if (prevIdx == n) break;
        }

        if (prevIdx == n) {
            if (waste < best) best = waste;
        }
    }

    if (best == std::numeric_limits<long long>::max()) return -1;
    return best % MOD;
}

