bool canBeRotated(const std::vector<std::vector<int>>& mat, const std::vector<std::vector<int>>& target) {
    size_t n = mat.size();
    auto equal = [&](const std::vector<std::vector<int>>& a, const std::vector<std::vector<int>>& b) -> bool {
        for (size_t i = 0; i < n; ++i) {
            for (size_t j = 0; j < n; ++j) {
                if (a[i][j] != b[i][j]) return false;
            }
        }
        return true;
    };
    auto rotate = [&](const std::vector<std::vector<int>>& a) -> std::vector<std::vector<int>> {
        std::vector<std::vector<int>> res(n, std::vector<int>(n));
        for (size_t i = 0; i < n; ++i) {
            for (size_t j = 0; j < n; ++j) {
                res[j][n - 1 - i] = a[i][j];
            }
        }
        return res;
    };
    std::vector<std::vector<int>> cur = mat;
    for (int k = 0; k < 4; ++k) {
        if (equal(cur, target)) return true;
        cur = rotate(cur);
    }
    return false;
}

