bool isCovered(const std::vector<std::vector<int>>& ranges, int left, int right) {
    int maxCoord = right;
    for (const auto& pair : ranges) {
        int e = pair[1];
        if (e > maxCoord) maxCoord = e;
    }

    std::vector<int> diff(maxCoord + 2, 0);
    for (const auto& pair : ranges) {
        int s = pair[0];
        int e = pair[1];
        diff[s] += 1;
        diff[e + 1] -= 1;
    }

    int cur = 0;
    for (int i = 0; i <= maxCoord; ++i) {
        cur += diff[i];
        if (i >= left && i <= right && cur == 0) {
            return false;
        }
    }
    return true;
}

