int findStudent(const std::vector<int>& chalk, long long k) {
    int n = static_cast<int>(chalk.size());
    std::vector<long long> prefix(n);
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        total += chalk[i];
        prefix[i] = total;
    }
    k = k % total;
    int left = 0, right = n - 1;
    while (left < right) {
        int mid = (left + right) / 2;
        if (prefix[mid] > k) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return left;
}

#include <bits/stdc++.h>
#include <vector>

int largestMagicSquare(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    // row prefix sums
    std::vector<std::vector<long long>> rowPref(m, std::vector<long long>(n + 1, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            rowPref[i][j + 1] = rowPref[i][j] + grid[i][j];
        }
    }
    // column prefix sums
    std::vector<std::vector<long long>> colPref(m + 1, std::vector<long long>(n, 0));
    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < m; ++i) {
            colPref[i + 1][j] = colPref[i][j] + grid[i][j];
        }
    }
    // main diagonal prefix sums
    std::vector<std::vector<long long>> diag1(m + 1, std::vector<long long>(n + 1, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            diag1[i + 1][j + 1] = diag1[i][j] + grid[i][j];
        }
    }
    // anti-diagonal prefix sums
    std::vector<std::vector<long long>> diag2(m + 1, std::vector<long long>(n + 1, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = n - 1; j >= 0; --j) {
            diag2[i + 1][j] = diag2[i][j + 1] + grid[i][j];
        }
    }

    int maxK = std::min(m, n);
    for (int k = maxK; k >= 1; --k) {
        for (int r = 0; r + k <= m; ++r) {
            for (int c = 0; c + k <= n; ++c) {
                long long target = rowPref[r][c + k] - rowPref[r][c];
                bool ok = true;
                // check rows
                for (int i = r; i < r + k && ok; ++i) {
                    long long sum = rowPref[i][c + k] - rowPref[i][c];
                    if (sum != target) ok = false;
                }
                // check columns
                for (int j = c; j < c + k && ok; ++j) {
                    long long sum = colPref[r + k][j] - colPref[r][j];
                    if (sum != target) ok = false;
                }
                // main diagonal
                if (ok) {
                    long long d1 = diag1[r + k][c + k] - diag1[r][c];
                    if (d1 != target) ok = false;
                }
                // anti diagonal
                if (ok) {
                    long long d2 = diag2[r + k][c] - diag2[r][c + k];
                    if (d2 != target) ok = false;
                }
                if (ok) return k;
            }
        }
    }
    return 1;
}

