bool mergeTriplets(const std::vector<std::vector<int>>& triplets, const std::vector<int>& target) {
    int x = target[0];
    int y = target[1];
    int z = target[2];
    bool haveX = false, haveY = false, haveZ = false;

    for (const auto& t : triplets) {
        int a = t[0];
        int b = t[1];
        int c = t[2];
        if (a <= x && b <= y && c <= z) {
            if (a == x) haveX = true;
            if (b == y) haveY = true;
            if (c == z) haveZ = true;
        }
    }
    return haveX && haveY && haveZ;
}

