int maximumRemovals(const std::string& s, const std::string& p, const std::vector<int>& removable) {
    int n = static_cast<int>(s.size());

    auto canRemove = [&](int k) -> bool {
        std::vector<bool> deleted(n, false);
        for (int i = 0; i < k; ++i) {
            deleted[removable[i]] = true;
        }
        int j = 0;
        for (int i = 0; i < n && j < static_cast<int>(p.size()); ++i) {
            if (!deleted[i] && s[i] == p[j]) {
                ++j;
            }
        }
        return j == static_cast<int>(p.size());
    };

    int low = 0;
    int high = static_cast<int>(removable.size());
    int ans = 0;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (canRemove(mid)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
}

#include <bits/stdc++.h>
int minCostToFlip(const std::string& expression) {
    const int INF = 1e9;
    std::stack<std::pair<int,int>> vals; // {cost0, cost1}
    std::stack<char> ops;

    auto apply = [&](char op) {
        auto right = vals.top(); vals.pop();
        auto left = vals.top(); vals.pop();
        int l0 = left.first, l1 = left.second;
        int r0 = right.first, r1 = right.second;
        int cost0 = INF, cost1 = INF;
        if (op == '&') {
            // keep '&'
            cost0 = std::min({l0 + r0, l0 + r1, l1 + r0});
            cost1 = l1 + r1;
            // flip to '|'
            int flip0 = 1 + l0 + r0; // result 0 for '|'
            int flip1 = 1 + std::min({l1 + r1, l0 + r1, l1 + r0});
            cost0 = std::min(cost0, flip0);
            cost1 = std::min(cost1, flip1);
        } else { // op == '|'
            // keep '|'
            cost1 = std::min({l1 + r1, l0 + r1, l1 + r0});
            cost0 = l0 + r0;
            // flip to '&'
            int flip0 = 1 + std::min({l0 + r0, l0 + r1, l1 + r0});
            int flip1 = 1 + l1 + r1;
            cost0 = std::min(cost0, flip0);
            cost1 = std::min(cost1, flip1);
        }
        vals.push({cost0, cost1});
    };

    for (char ch : expression) {
        if (ch == '0' || ch == '1') {
            int cost0 = (ch == '0') ? 0 : 1;
            int cost1 = (ch == '1') ? 0 : 1;
            vals.push({cost0, cost1});
        } else if (ch == '(') {
            ops.push(ch);
        } else if (ch == '&' || ch == '|') {
            while (!ops.empty() && ops.top() != '(') {
                char op = ops.top(); ops.pop();
                apply(op);
            }
            ops.push(ch);
        } else if (ch == ')') {
            while (!ops.empty() && ops.top() != '(') {
                char op = ops.top(); ops.pop();
                apply(op);
            }
            if (!ops.empty() && ops.top() == '(') ops.pop(); // remove '('
        }
    }
    while (!ops.empty()) {
        char op = ops.top(); ops.pop();
        apply(op);
    }
    auto finalCost = vals.top();
    // original value has zero cost
    if (finalCost.first == 0) return finalCost.second;
    else return finalCost.first;
}

