int numberOfFullRounds(const std::string& loginTime, const std::string& logoutTime) {
    auto toMinutes = [](const std::string& t) -> int {
        std::size_t colon = t.find(':');
        int h = std::stoi(t.substr(0, colon));
        int m = std::stoi(t.substr(colon + 1));
        return h * 60 + m;
    };
    int start = toMinutes(loginTime);
    int end = toMinutes(logoutTime);
    if (end < start) end += 24 * 60;
    int roundStart = ((start + 14) / 15) * 15;
    int roundEnd = (end / 15) * 15;
    if (roundStart >= roundEnd) return 0;
    return (roundEnd - roundStart) / 15;
}

