std::vector<int> minimumAbsoluteDifferenceQueries(const std::vector<int>& nums, const std::vector<std::vector<int>>& queries) {
    std::vector<int> result(queries.size());
    for (size_t qi = 0; qi < queries.size(); ++qi) {
        int l = queries[qi][0];
        int r = queries[qi][1];
        std::vector<int> sub(nums.begin() + l, nums.begin() + r + 1);
        std::sort(sub.begin(), sub.end());
        int minDiff = std::numeric_limits<int>::max();
        bool hasDiff = false;
        for (size_t i = 1; i < sub.size(); ++i) {
            if (sub[i] == sub[i - 1]) {
                continue;
            }
            int diff = sub[i] - sub[i - 1];
            if (diff < minDiff) {
                minDiff = diff;
            }
            hasDiff = true;
        }
        result[qi] = hasDiff ? minDiff : -1;
    }
    return result;
}

#include <bits/stdc++.h>
using std::vector;
using std::uint32_t;

int global_n;
int fp, sp;
int earliestRound;
int latestRound;

void explore(uint32_t mask, int round) {
    // collect remaining players in order
    vector<int> players;
    players.reserve(global_n);
    for (int i = 0; i < global_n; ++i) {
        if (mask & (1u << i)) players.push_back(i + 1);
    }
    int sz = (int)players.size();
    if (sz <= 1) return; // no further matches possible

    int pairs = sz / 2;
    bool odd = (sz % 2 == 1);
    int middlePlayer = -1;
    if (odd) middlePlayer = players[sz / 2];

    // recursive generation of possible next masks
    std::function<void(int, uint32_t)> rec = [&](int idx, uint32_t nextMask) {
        if (idx == pairs) {
            if (odd) nextMask |= (1u << (middlePlayer - 1));
            explore(nextMask, round + 1);
            return;
        }
        int a = players[idx];
        int b = players[sz - 1 - idx];

        // check if they meet this round
        if ((a == fp && b == sp) || (a == sp && b == fp)) {
            if (round < earliestRound) earliestRound = round;
            if (round > latestRound)   latestRound = round;
            return;
        }

        bool aSpecial = (a == fp || a == sp);
        bool bSpecial = (b == fp || b == sp);

        if (aSpecial && !bSpecial) {
            rec(idx + 1, nextMask | (1u << (a - 1)));
        } else if (!aSpecial && bSpecial) {
            rec(idx + 1, nextMask | (1u << (b - 1)));
        } else { // both non‑special
            rec(idx + 1, nextMask | (1u << (a - 1)));
            rec(idx + 1, nextMask | (1u << (b - 1)));
        }
    };

    rec(0, 0u);
}

vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
    global_n = n;
    fp = firstPlayer;
    sp = secondPlayer;
    earliestRound = INT_MAX;
    latestRound = -1;

    uint32_t fullMask = (n == 32) ? 0xFFFFFFFFu : ((1u << n) - 1);
    explore(fullMask, 1);
    return {earliestRound, latestRound};
}

