            int cur = mat[i][j];
            bool isPeak = true;
            if (i > 0 && mat[i - 1][j] >= cur) isPeak = false;
            if (i + 1 < m && mat[i + 1][j] >= cur) isPeak = false;
            if (j > 0 && mat[i][j - 1] >= cur) isPeak = false;
            if (j + 1 < n && mat[i][j + 1] >= cur) isPeak = false;
            if (isPeak) return {i, j};
        }
    }
    return {0, 0};
}

