long long maxAlternatingSum(const std::vector<int>& nums) {
    long long bestPos = 0;
    long long bestNeg = std::numeric_limits<long long>::min();
    for (int v : nums) {
        long long curPos = std::max(bestPos, bestNeg == std::numeric_limits<long long>::min() ? std::numeric_limits<long long>::min() : bestNeg + v);
        curPos = std::max(curPos, static_cast<long long>(v));
        long long curNeg = std::max(bestNeg, bestPos - v);
        bestPos = curPos;
        bestNeg = curNeg;
    }
    return bestPos;
}

