int countSubIslands(std::vector<std::vector<int>>& grid1, std::vector<std::vector<int>>& grid2) {
    int rows = grid1.size();
    int cols = grid1[0].size();
    int subIslandCount = 0;
    std::function<bool(int, int)> dfs = [&](int r, int c) -> bool {
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid2[r][c] == 0) return true;
        grid2[r][c] = 0;
        bool isSub = (grid1[r][c] == 1);
        bool up = dfs(r - 1, c);
        bool down = dfs(r + 1, c);
        bool left = dfs(r, c - 1);
        bool right = dfs(r, c + 1);
        return isSub && up && down && left && right;
    };
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (grid2[r][c] == 1) {
                if (dfs(r, c)) ++subIslandCount;
            }
        }
    }
    return subIslandCount;
}

