std::string removeOccurrences(const std::string& s, const std::string& part) {
    std::vector<char> stack;
    size_t m = part.size();

    for (size_t i = 0; i < s.size(); ++i) {
        stack.push_back(s[i]);

        if (stack.size() >= m) {
            bool match = true;
            for (size_t j = 0; j < m; ++j) {
                if (stack[stack.size() - m + j] != part[j]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                for (size_t j = 0; j < m; ++j) {
                    stack.pop_back();
                }
            }
        }
    }
    return std::string(stack.begin(), stack.end());
}

