bool canBeIncreasing(const std::vector<int>& nums) {
    int violationIdx = -1;
    for (int i = 1; i < static_cast<int>(nums.size()); ++i) {
        if (nums[i] <= nums[i - 1]) {
            if (violationIdx != -1) return false;
            violationIdx = i;
        }
    }
    if (violationIdx == -1) return true;
    int i = violationIdx;
    bool canRemovePrev = (i == 1) || (nums[i] > nums[i - 2]);
    bool canRemoveCurr = (i == static_cast<int>(nums.size()) - 1) || (nums[i + 1] > nums[i - 1]);
    return canRemovePrev || canRemoveCurr;
}

