std::vector<std::vector<int>> rotateGrid(std::vector<std::vector<int>> grid, int k) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    int layers = std::min(m, n) / 2;

    for (int layer = 0; layer < layers; ++layer) {
        int top = layer;
        int bottom = m - 1 - layer;
        int left = layer;
        int right = n - 1 - layer;

        std::vector<int> elems;

        for (int c = left; c <= right; ++c) elems.push_back(grid[top][c]);

        for (int r = top + 1; r <= bottom; ++r) elems.push_back(grid[r][right]);

        for (int c = right - 1; c >= left; --c) elems.push_back(grid[bottom][c]);

        for (int r = bottom - 1; r > top; --r) elems.push_back(grid[r][left]);

        int len = static_cast<int>(elems.size());
        int rot = k % len;

        std::vector<int> rotated;
        rotated.insert(rotated.end(), elems.begin() + rot, elems.end());
        rotated.insert(rotated.end(), elems.begin(), elems.begin() + rot);

        int idx = 0;
        for (int c = left; c <= right; ++c) grid[top][c] = rotated[idx++];
        for (int r = top + 1; r <= bottom; ++r) grid[r][right] = rotated[idx++];
        for (int c = right - 1; c >= left; --c) grid[bottom][c] = rotated[idx++];
        for (int r = bottom - 1; r > top; --r) grid[r][left] = rotated[idx++];
    }

    return grid;
}

#include <bits/stdc++.h>
class MovieRentingSystem {
    std::unordered_map<int, std::set<std::pair<int,int>>> available; // movie -> set of (price, shop)
    std::set<std::tuple<int,int,int>> rented; // (price, shop, movie)
    std::unordered_map<long long, int> priceMap; // (shop,movie) -> price
public:
    MovieRentingSystem(int n, std::vector<std::vector<int>>& entries) {
        for (const auto& e : entries) {
            int shop = e[0];
            int movie = e[1];
            int price = e[2];
            available[movie].insert({price, shop});
            long long key = (static_cast<long long>(shop) << 32) | static_cast<unsigned int>(movie);
            priceMap[key] = price;
        }
    }

    std::vector<int> search(int movie) {
        std::vector<int> res;
        auto it = available.find(movie);
        if (it != available.end()) {
            for (const auto& p : it->second) {
                res.push_back(p.second);
                if (res.size() == 5) break;
            }
        }
        return res;
    }

    void rent(int shop, int movie) {
        long long key = (static_cast<long long>(shop) << 32) | static_cast<unsigned int>(movie);
        int price = priceMap[key];
        auto& avSet = available[movie];
        avSet.erase({price, shop});
        rented.insert({price, shop, movie});
    }

    void drop(int shop, int movie) {
        long long key = (static_cast<long long>(shop) << 32) | static_cast<unsigned int>(movie);
        int price = priceMap[key];
        rented.erase({price, shop, movie});
        available[movie].insert({price, shop});
    }

    std::vector<std::vector<int>> report() {
        std::vector<std::vector<int>> res;
        for (const auto& t : rented) {
            int price, shop, movie;
            std::tie(price, shop, movie) = t;
            res.push_back({shop, movie});
            if (res.size() == 5) break;
        }
        return res;
    }
};

