int eliminateMaximum(const std::vector<int>& dist, const std::vector<int>& speed) {
    std::size_t n = dist.size();
    std::vector<long long> deadline(n);
    for (std::size_t i = 0; i < n; ++i) {
        deadline[i] = (static_cast<long long>(dist[i]) + static_cast<long long>(speed[i]) - 1) / static_cast<long long>(speed[i]);
    }
    std::sort(deadline.begin(), deadline.end());
    std::size_t killed = 0;
    while (killed < n && static_cast<long long>(killed) < deadline[killed]) {
        ++killed;
    }
    return static_cast<int>(killed);
}

