static const long long MOD = 1000000007LL;

static long long modPow(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1LL) {
            res = res * base % MOD;
        }
        base = base * base % MOD;
        exp >>= 1LL;
    }
    return res;
}

int countOrders(const std::vector<int>& prevRoom) {
    int n = static_cast<int>(prevRoom.size());
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) {
        int p = prevRoom[i];
        children[p].push_back(i);
    }

    std::vector<long long> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    invFact[n] = modPow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) {
        invFact[i - 1] = invFact[i] * i % MOD;
    }

    std::vector<int> order(n);
    int idx = 0;
    std::stack<int> st;
    st.push(0);
    while (!st.empty()) {
        int u = st.top();
        st.pop();
        order[idx++] = u;
        for (int v : children[u]) {
            st.push(v);
        }
    }

    std::vector<int> size(n);
    std::vector<long long> ways(n);
    for (int i = n - 1; i >= 0; --i) {
        int u = order[i];
        int total = 0;
        long long w = 1;
        for (int v : children[u]) {
            total += size[v];
            w = w * ways[v] % MOD;
        }
        w = w * fact[total] % MOD;
        for (int v : children[u]) {
            w = w * invFact[size[v]] % MOD;
        }
        size[u] = total + 1;
        ways[u] = w;
    }
    return static_cast<int>(ways[0]);
}

