#include <bits/stdc++.h>
int longestCommonSubpath(int n, std::vector<std::vector<int>>& paths) {
    const long long mod1 = 1000000007LL;
    const long long mod2 = 1000000009LL;
    const long long base = 100007LL;

    int m = paths.size();
    int minLen = INT_MAX;
    int maxLen = 0;
    for (const auto& p : paths) {
        int sz = p.size();
        minLen = std::min(minLen, sz);
        maxLen = std::max(maxLen, sz);
    }

    std::vector<long long> pow1(maxLen + 1), pow2(maxLen + 1);
    pow1[0] = pow2[0] = 1;
    for (int i = 1; i <= maxLen; ++i) {
        pow1[i] = (pow1[i - 1] * base) % mod1;
        pow2[i] = (pow2[i - 1] * base) % mod2;
    }

    auto check = [&](int L) -> bool {
        if (L == 0) return true;
        std::unordered_set<unsigned long long> common;
        bool first = true;
        for (const auto& p : paths) {
            if ((int)p.size() < L) return false;
            std::vector<long long> pref1(p.size() + 1, 0), pref2(p.size() + 1, 0);
            for (size_t i = 0; i < p.size(); ++i) {
                pref1[i + 1] = (pref1[i] * base + p[i]) % mod1;
                pref2[i + 1] = (pref2[i] * base + p[i]) % mod2;
            }
            std::unordered_set<unsigned long long> cur;
            for (size_t i = 0; i + L <= p.size(); ++i) {
                long long h1 = (pref1[i + L] - pref1[i] * pow1[L]) % mod1;
                if (h1 < 0) h1 += mod1;
                long long h2 = (pref2[i + L] - pref2[i] * pow2[L]) % mod2;
                if (h2 < 0) h2 += mod2;
                unsigned long long key = (static_cast<unsigned long long>(h1) << 32) ^ static_cast<unsigned long long>(h2);
                cur.insert(key);
            }
            if (first) {
                common.swap(cur);
                first = false;
            } else {
                for (auto it = common.begin(); it != common.end(); ) {
                    if (cur.find(*it) == cur.end())
                        it = common.erase(it);
                    else
                        ++it;
                }
                if (common.empty()) return false;
            }
        }
        return !common.empty();
    };

    int low = 0, high = minLen;
    while (low < high) {
        int mid = (low + high + 1) / 2;
        if (check(mid))
            low = mid;
        else
            high = mid - 1;
    }
    return low;
}

