long long countSquareSumTriples(int n) {
    long long count = 0;
    for (int c = 1; c <= n; ++c) {
        long long c2 = 1LL * c * c;
        for (int a = 1; a <= n; ++a) {
            long long a2 = 1LL * a * a;
            if (a2 >= c2) break;
            long long b2 = c2 - a2;
            long long b = static_cast<long long>(std::floor(std::sqrt(static_cast<double>(b2))));
            if (b * b == b2 && b >= 1 && b <= n) {
                ++count;
            }
        }
    }
    return count;
}

