bool sumGame(const std::string& num) {
    int n = static_cast<int>(num.size());
    int half = n / 2;
    long long sumL = 0, sumR = 0;
    int cntL = 0, cntR = 0;
    for (int i = 0; i < half; ++i) {
        if (num[i] == '?') ++cntL;
        else sumL += num[i] - '0';
    }
    for (int i = half; i < n; ++i) {
        if (num[i] == '?') ++cntR;
        else sumR += num[i] - '0';
    }
    if (cntL == cntR) {
        return sumL != sumR;
    }
    int diffCnt = cntL - cntR;
    if (diffCnt % 2 != 0) {
        return true;
    }
    long long diffSum = sumL - sumR;
    long long need = std::llabs(diffCnt / 2) * 9LL;
    return std::llabs(diffSum) != need;
}

