long long countGoodNumbers(long long n) {
    const long long MOD = 1000000007LL;
    long long evenCnt = (n + 1) / 2;
    long long oddCnt = n / 2;
    std::function<long long(long long, long long)> powMod = [&](long long base, long long exp) -> long long {
        if (exp == 0) return 1;
        long long half = powMod(base, exp / 2);
        long long res = (half * half) % MOD;
        if (exp % 2 == 1) {
            res = (res * base) % MOD;
        }
        return res;
    };
    long long pow5 = powMod(5, evenCnt);
    long long pow4 = powMod(4, oddCnt);
    long long ans = (pow5 * pow4) % MOD;
    return ans;
}

