int nearestExit(const std::vector<std::vector<char>>& maze, const std::vector<int>& entrance) {
    int rows = static_cast<int>(maze.size());
    int cols = static_cast<int>(maze[0].size());
    int startRow = entrance[0];
    int startCol = entrance[1];

    std::vector<std::vector<bool>> visited(rows, std::vector<bool>(cols, false));
    std::queue<std::array<int, 3>> q;
    q.push({startRow, startCol, 0});
    visited[startRow][startCol] = true;

    const std::array<std::array<int, 2>, 4> directions = {{
        {{-1, 0}}, // up
        {{1, 0}},  // down
        {{0, -1}}, // left
        {{0, 1}}   // right
    }};

    while (!q.empty()) {
        auto cur = q.front();
        q.pop();
        int r = cur[0];
        int c = cur[1];
        int dist = cur[2];

        if ((r == 0 || r == rows - 1 || c == 0 || c == cols - 1) && !(r == startRow && c == startCol)) {
            return dist;
        }

        for (const auto& dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                maze[nr][nc] == '.' && !visited[nr][nc]) {
                visited[nr][nc] = true;
                q.push({nr, nc, dist + 1});
            }
        }
    }

    return -1;
}

