struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

TreeNode* canMerge(std::vector<TreeNode*>& trees) {
    std::unordered_map<int, TreeNode*> rootMap;
    std::unordered_set<int> leafVals;
    for (TreeNode* r : trees) {
        rootMap[r->val] = r;
        if (r->left) leafVals.insert(r->left->val);
        if (r->right) leafVals.insert(r->right->val);
    }

    int overallRootVal = 0;
    int cnt = 0;
    for (auto& p : rootMap) {
        if (leafVals.find(p.first) == leafVals.end()) {
            overallRootVal = p.first;
            ++cnt;
        }
    }
    if (cnt != 1) return nullptr;

    TreeNode* root = rootMap[overallRootVal];
    rootMap.erase(overallRootVal);

    std::function<TreeNode*(TreeNode*, long long, long long, bool&)> dfs =
        [&](TreeNode* node, long long low, long long high, bool& ok) -> TreeNode* {
            if (!node) return nullptr;
            if (node->val <= low || node->val >= high) { ok = false; return nullptr; }

            if (!node->left && !node->right) {
                auto it = rootMap.find(node->val);
                if (it != rootMap.end()) {
                    node = it->second;
                    rootMap.erase(it);
                }
            }

            node->left = dfs(node->left, low, node->val, ok);
            node->right = dfs(node->right, node->val, high, ok);
            return node;
        };

    bool ok = true;
    root = dfs(root, LLONG_MIN, LLONG_MAX, ok);
    if (!ok || !rootMap.empty()) return nullptr;
    return root;
}

