long long minCost(int maxTime, const std::vector<std::vector<int>>& edges, const std::vector<int>& passingFees) {
    int n = passingFees.size();
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1], t = e[2];
        adj[u].push_back({v, t});
        adj[v].push_back({u, t});
    }
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<std::vector<long long>> best(n, std::vector<long long>(maxTime + 1, INF));
    best[0][0] = passingFees[0];
    struct Node {
        long long cost;
        int city;
        int time;
        bool operator<(Node const& other) const {
            return cost > other.cost;
        }
    };
    std::priority_queue<Node> heap;
    heap.push({passingFees[0], 0, 0});
    while (!heap.empty()) {
        Node cur = heap.top(); heap.pop();
        long long cost = cur.cost;
        int city = cur.city;
        int time = cur.time;
        if (cost != best[city][time]) continue;
        if (city == n - 1) return cost;
        for (const auto& nb : adj[city]) {
            int next = nb.first;
            int roadTime = nb.second;
            int newTime = time + roadTime;
            if (newTime > maxTime) continue;
            long long newCost = cost + passingFees[next];
            if (newCost < best[next][newTime]) {
                best[next][newTime] = newCost;
                heap.push({newCost, next, newTime});
            }
        }
    }
    long long answer = INF;
    for (int t = 0; t <= maxTime; ++t) {
        if (best[n - 1][t] < answer) answer = best[n - 1][t];
    }
    return answer == INF ? -1 : answer;
}

