int countPalindromicSubsequence(const std::string& s) {
    int n = static_cast<int>(s.size());
    if (n < 3) return 0;
    std::vector<int> leftMask(n), rightMask(n);
    int mask = 0;
    for (int i = 0; i < n; ++i) {
        leftMask[i] = mask;
        mask |= 1 << (s[i] - 'a');
    }
    mask = 0;
    for (int i = n - 1; i >= 0; --i) {
        rightMask[i] = mask;
        mask |= 1 << (s[i] - 'a');
    }
    bool seen[26][26] = {};
    for (int i = 0; i < n; ++i) {
        int common = leftMask[i] & rightMask[i];
        int mid = s[i] - 'a';
        while (common) {
            int outer = __builtin_ctz(common);
            seen[outer][mid] = true;
            common &= common - 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 26; ++i)
        for (int j = 0; j < 26; ++j)
            if (seen[i][j]) ++result;
    return result;
}

#include <bits/stdc++.h>
int colorTheGrid(int m, int n) {
    const long long MOD = 1000000007LL;
    std::vector<int> pow3(m + 1, 1);
    for (int i = 1; i <= m; ++i) pow3[i] = pow3[i - 1] * 3;
    int total = pow3[m];
    std::vector<int> valid;
    for (int mask = 0; mask < total; ++mask) {
        bool ok = true;
        for (int i = 0; i < m - 1; ++i) {
            int c1 = (mask / pow3[i]) % 3;
            int c2 = (mask / pow3[i + 1]) % 3;
            if (c1 == c2) { ok = false; break; }
        }
        if (ok) valid.push_back(mask);
    }
    int sz = valid.size();
    std::vector<std::vector<int>> compat(sz);
    for (int i = 0; i < sz; ++i) {
        for (int j = 0; j < sz; ++j) {
            bool ok = true;
            for (int row = 0; row < m; ++row) {
                int c1 = (valid[i] / pow3[row]) % 3;
                int c2 = (valid[j] / pow3[row]) % 3;
                if (c1 == c2) { ok = false; break; }
            }
            if (ok) compat[i].push_back(j);
        }
    }
    std::vector<long long> dp(sz, 1), ndp(sz);
    for (int col = 1; col < n; ++col) {
        std::fill(ndp.begin(), ndp.end(), 0);
        for (int i = 0; i < sz; ++i) {
            long long cur = dp[i];
            if (cur == 0) continue;
            for (int j : compat[i]) {
                ndp[j] += cur;
                if (ndp[j] >= MOD) ndp[j] -= MOD;
            }
        }
        dp.swap(ndp);
    }
    long long ans = 0;
    for (long long v : dp) {
        ans += v;
        if (ans >= MOD) ans -= MOD;
    }
    return static_cast<int>(ans % MOD);
}

