int addMinimumRungs(const std::vector<int>& rungs, int dist) {
    int added = 0;
    int prev = 0;
    for (size_t i = 0; i < rungs.size(); ++i) {
        int gap = rungs[i] - prev;
        if (gap > dist) {
            added += (gap - 1) / dist;
        }
        prev = rungs[i];
    }
    return added;
}

