long long maxPoints(const std::vector<std::vector<long long>>& points) {
    size_t m = points.size();
    size_t n = points[0].size();
    std::vector<long long> dp = points[0];
    for (size_t i = 1; i < m; ++i) {
        std::vector<long long> left(n), right(n);
        left[0] = dp[0];
        for (size_t j = 1; j < n; ++j) {
            left[j] = std::max(dp[j], left[j - 1] - 1);
        }
        right[n - 1] = dp[n - 1];
        for (int j = static_cast<int>(n) - 2; j >= 0; --j) {
            right[j] = std::max(dp[j], right[j + 1] - 1);
        }
        std::vector<long long> newDp(n);
        for (size_t j = 0; j < n; ++j) {
            newDp[j] = points[i][j] + std::max(left[j], right[j]);
        }
        dp.swap(newDp);
    }
    long long ans = dp[0];
    for (long long v : dp) {
        if (v > ans) ans = v;
    }
    return ans;
}

