struct TrieNode {
    int child[2];
    int cnt;
    TrieNode() {
        child[0] = child[1] = -1;
        cnt = 0;
    }
};

const int MAX_BIT = 20; // enough for values up to 2*10^5

static void trieInsert(vector<TrieNode>& trie, int num) {
    int node = 0;
    for (int b = MAX_BIT; b >= 0; --b) {
        int bit = (num >> b) & 1;
        if (trie[node].child[bit] == -1) {
            trie[node].child[bit] = (int)trie.size();
            trie.emplace_back();
        }
        node = trie[node].child[bit];
        ++trie[node].cnt;
    }
}

static void trieRemove(vector<TrieNode>& trie, int num) {
    int node = 0;
    for (int b = MAX_BIT; b >= 0; --b) {
        int bit = (num >> b) & 1;
        node = trie[node].child[bit];
        --trie[node].cnt;
    }
}

static int trieQuery(const vector<TrieNode>& trie, int num) {
    int node = 0;
    int res = 0;
    for (int b = MAX_BIT; b >= 0; --b) {
        int bit = (num >> b) & 1;
        int want = bit ^ 1;
        int nxt = trie[node].child[want];
        if (nxt != -1 && trie[nxt].cnt > 0) {
            res |= (1 << b);
            node = nxt;
        } else {
            node = trie[node].child[bit];
        }
    }
    return res;
}

vector<int> maxGeneticDifference(vector<int>& parents, vector<vector<int>>& queries) {
    int n = (int)parents.size();
    vector<vector<int>> children(n);
    int root = -1;
    for (int i = 0; i < n; ++i) {
        if (parents[i] == -1) {
            root = i;
        } else {
            children[parents[i]].push_back(i);
        }
    }

    vector<vector<pair<int,int>>> qAtNode(n);
    for (int i = 0; i < (int)queries.size(); ++i) {
        int node = queries[i][0];
        int val = queries[i][1];
        qAtNode[node].push_back({i, val});
    }

    vector<int> ans(queries.size());
    vector<TrieNode> trie(1); // root of trie

    stack<pair<int,int>> st;
    st.push({root, 0}); // 0 = enter, 1 = exit

    while (!st.empty()) {
        int u = st.top().first;
        int state = st.top().second;
        st.pop();
        if (state == 0) {
            trieInsert(trie, u);
            for (auto &p : qAtNode[u]) {
                ans[p.first] = trieQuery(trie, p.second);
            }
            st.push({u, 1});
            for (int v : children[u]) {
                st.push({v, 0});
            }
        } else {
            trieRemove(trie, u);
        }
    }

    return ans;
}

