int smallestChair(const std::vector<std::vector<int>>& times, int targetFriend) {
    int n = static_cast<int>(times.size());
    std::vector<std::tuple<int, int, int>> events;
    events.reserve(2 * n);
    for (int i = 0; i < n; ++i) {
        events.emplace_back(times[i][0], 0, i); // arrival
        events.emplace_back(times[i][1], 1, i); // leave
    }
    std::sort(events.begin(), events.end(),
        [](const std::tuple<int, int, int>& a, const std::tuple<int, int, int>& b) {
            if (std::get<0>(a) != std::get<0>(b))
                return std::get<0>(a) < std::get<0>(b);
            return std::get<1>(a) < std::get<1>(b); // leave before arrival if same time
        });
    std::priority_queue<int, std::vector<int>, std::greater<int>> freeChairs;
    for (int i = 0; i < n; ++i) {
        freeChairs.push(i);
    }
    std::unordered_map<int, int> occupied;
    for (const auto& e : events) {
        int time = std::get<0>(e);
        int type = std::get<1>(e);
        int idx = std::get<2>(e);
        if (type == 0) { // arrival
            int chair = freeChairs.top();
            freeChairs.pop();
            occupied[idx] = chair;
            if (idx == targetFriend) {
                return chair;
            }
        } else { // leave
            int chair = occupied[idx];
            freeChairs.push(chair);
        }
    }
    return -1;
}

