long long sumOfDigitsAfterConvert(const std::string& s, int k) {
    long long total = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        int val = s[i] - 'a' + 1;
        if (val >= 10) {
            total += val / 10 + (val % 10);
        } else {
            total += val;
        }
    }
    for (int repeat = 1; repeat < k; ++repeat) {
        long long sum = 0;
        while (total > 0) {
            sum += total % 10;
            total /= 10;
        }
        total = sum;
    }
    return total;
}

