int maximumCompatibilitySum(const std::vector<std::vector<int>>& students, const std::vector<std::vector<int>>& mentors) {
    int m = students.size();
    int n = students[0].size();
    std::vector<std::vector<int>> score(m, std::vector<int>(m, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < m; ++j) {
            int same = 0;
            for (int k = 0; k < n; ++k) {
                if (students[i][k] == mentors[j][k]) ++same;
            }
            score[i][j] = same;
        }
    }
    int totalMasks = 1 << m;
    std::vector<int> dp(totalMasks, INT_MIN);
    dp[0] = 0;
    for (int mask = 0; mask < totalMasks; ++mask) {
        int studentIdx = __builtin_popcount(mask);
        if (studentIdx >= m) continue;
        for (int mentor = 0; mentor < m; ++mentor) {
            if ((mask & (1 << mentor)) == 0) {
                int newMask = mask | (1 << mentor);
                int cand = dp[mask] + score[studentIdx][mentor];
                if (cand > dp[newMask]) dp[newMask] = cand;
            }
        }
    }
    return dp[totalMasks - 1];
}

