struct Node {
    std::string name;
    std::unordered_map<std::string, Node*> children;
    std::string ser;
    Node(const std::string& n = "") : name(n) {}
};
std::string dfsSerialize(Node* node, std::unordered_map<std::string, int>& cnt) {
    std::vector<std::string> parts;
    for (auto& kv : node->children) {
        Node* child = kv.second;
        std::string childSer = dfsSerialize(child, cnt);
        parts.push_back(child->name + childSer);
    }
    std::sort(parts.begin(), parts.end());
    std::string s = "(";
    for (const std::string& p : parts) s += p;
    s += ")";
    node->ser = s;
    ++cnt[s];
    return s;
}
void dfsCollect(Node* node, const std::unordered_map<std::string, int>& cnt,
                std::vector<std::string>& cur, std::vector<std::vector<std::string>>& ans) {
    if (!node->children.empty() && cnt.at(node->ser) > 1) return;
    if (!node->name.empty()) ans.push_back(cur);
    for (auto& kv : node->children) {
        Node* child = kv.second;
        cur.push_back(child->name);
        dfsCollect(child, cnt, cur, ans);
        cur.pop_back();
    }
}
std::vector<std::vector<std::string>> deleteDuplicateFolder(std::vector<std::vector<std::string>>& paths) {
    Node* root = new Node();
    for (const auto& p : paths) {
        Node* cur = root;
        for (const std::string& name : p) {
            if (!cur->children.count(name)) cur->children[name] = new Node(name);
            cur = cur->children[name];
        }
    }
    std::unordered_map<std::string, int> cnt;
    dfsSerialize(root, cnt);
    std::vector<std::vector<std::string>> ans;
    std::vector<std::string> cur;
    for (auto& kv : root->children) {
        cur.push_back(kv.second->name);
        dfsCollect(kv.second, cnt, cur, ans);
        cur.pop_back();
    }
    return ans;
}

