std::vector<std::vector<long long>> splitPainting(const std::vector<std::vector<int>>& segments) {
    std::map<int, long long> diff;
    for (const auto& seg : segments) {
        int l = seg[0];
        int r = seg[1];
        long long c = seg[2];
        diff[l] += c;
        diff[r] -= c;
    }
    std::vector<std::vector<long long>> result;
    long long cur = 0;
    int prev = -1;
    for (const auto& kv : diff) {
        int pos = kv.first;
        long long delta = kv.second;
        if (prev != -1 && cur != 0 && prev < pos) {
            result.push_back({static_cast<long long>(prev), static_cast<long long>(pos), cur});
        }
        cur += delta;
        prev = pos;
    }
    return result;
}

