    for (int v : piles) {
        total += v;
    }
    for (int i = 0; i < k; ++i) {
        int x = pq.top();
        pq.pop();
        int newPile = (x + 1) / 2;
        total -= (x - newPile);
        pq.push(newPile);
    }
    return static_cast<int>(total);
}

