#include <bits/stdc++.h>

long long maxProduct(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::vector<int> d1(n);
    int l = 0, r = -1;
    for (int i = 0; i < n; ++i) {
        int k = (i > r) ? 1 : std::min(d1[l + r - i], r - i + 1);
        while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) ++k;
        d1[i] = k;
        if (i + k - 1 > r) {
            l = i - k + 1;
            r = i + k - 1;
        }
    }

    std::vector<int> leftMax(n, 0), rightMax(n, 0);
    for (int i = 0; i < n; ++i) {
        int len = 2 * d1[i] - 1;
        int endPos = i + d1[i] - 1;
        leftMax[endPos] = std::max(leftMax[endPos], len);
        int startPos = i - d1[i] + 1;
        rightMax[startPos] = std::max(rightMax[startPos], len);
    }

    for (int i = 1; i < n; ++i) {
        leftMax[i] = std::max(leftMax[i], leftMax[i - 1]);
    }
    for (int i = n - 2; i >= 0; --i) {
        rightMax[i] = std::max(rightMax[i], rightMax[i + 1]);
    }

    long long best = 0;
    for (int i = 0; i < n - 1; ++i) {
        long long prod = 1LL * leftMax[i] * rightMax[i + 1];
        if (prod > best) best = prod;
    }
    return best;
}

#include <bits/stdc++.h>

long long minimumNonZeroProduct(int p) {
    const long long MOD = 1000000007LL;
    long long pow2p_mod = 1;
    long long base2 = 2 % MOD;
    int exp = p;
    while (exp > 0) {
        if (exp & 1) {
            pow2p_mod = (pow2p_mod * base2) % MOD;
        }
        base2 = (base2 * base2) % MOD;
        exp >>= 1;
    }
    long long maxNum_mod = (pow2p_mod - 1 + MOD) % MOD;
    long long base_mod = (pow2p_mod - 2 + MOD) % MOD;

    long long result = 1;
    long long b = base_mod;
    for (int i = 0; i < p - 1; ++i) {
        result = (result * b) % MOD;
        b = (b * b) % MOD;
    }

    long long answer = (maxNum_mod * result) % MOD;
    return answer;
}

