int latestDayToCross(int row, int col, const std::vector<std::vector<int>>& cells) {
    int left = 0, right = static_cast<int>(cells.size()), answer = 0;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        std::vector<std::vector<int>> grid(row, std::vector<int>(col, 0));
        for (int i = 0; i < mid; ++i) {
            int r = cells[i][0] - 1;
            int c = cells[i][1] - 1;
            grid[r][c] = 1;
        }

        std::queue<std::pair<int, int>> q;
        std::vector<std::vector<bool>> visited(row, std::vector<bool>(col, false));
        for (int c = 0; c < col; ++c) {
            if (grid[0][c] == 0) {
                q.emplace(0, c);
                visited[0][c] = true;
            }
        }

        bool canCross = false;
        const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!q.empty()) {
            int r = q.front().first;
            int c = q.front().second;
            q.pop();
            if (r == row - 1) {
                canCross = true;
                break;
            }
            for (const auto& d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (nr >= 0 && nr < row && nc >= 0 && nc < col &&
                    !visited[nr][nc] && grid[nr][nc] == 0) {
                    visited[nr][nc] = true;
                    q.emplace(nr, nc);
                }
            }
        }

        if (canCross) {
            answer = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return answer;
}

