long long maximumMatrixSum(const std::vector<std::vector<long long>>& matrix) {
    size_t n = matrix.size();
    long long sumAbs = 0;
    int negCount = 0;
    long long minAbs = std::numeric_limits<long long>::max();

    for (size_t i = 0; i < n; ++i) {
        const std::vector<long long>& row = matrix[i];
        for (size_t j = 0; j < n; ++j) {
            long long val = row[j];
            long long a = std::llabs(val);
            sumAbs += a;
            if (val < 0) ++negCount;
            if (a < minAbs) minAbs = a;
        }
    }

    long long adjustment = ((n % 2 == 1) && (negCount % 2 == 1)) ? 2 * minAbs : 0;
    return sumAbs - adjustment;
}

