const long long MOD = 1000000007LL;

void heapPush(std::vector<std::pair<long long, int>>& heap, const std::pair<long long, int>& item) {
    heap.push_back(item);
    int i = static_cast<int>(heap.size()) - 1;
    while (i > 0) {
        int p = (i - 1) >> 1;
        if (heap[p].first <= heap[i].first) break;
        std::swap(heap[p], heap[i]);
        i = p;
    }
}

std::pair<long long, int> heapPop(std::vector<std::pair<long long, int>>& heap) {
    if (heap.empty()) return std::make_pair(-1LL, -1);
    std::pair<long long, int> top = heap[0];
    std::pair<long long, int> last = heap.back();
    heap.pop_back();
    if (!heap.empty()) {
        heap[0] = last;
        int i = 0;
        while (true) {
            int l = i * 2 + 1;
            int r = i * 2 + 2;
            int smallest = i;
            if (l < static_cast<int>(heap.size()) && heap[l].first < heap[smallest].first) smallest = l;
            if (r < static_cast<int>(heap.size()) && heap[r].first < heap[smallest].first) smallest = r;
            if (smallest == i) break;
            std::swap(heap[i], heap[smallest]);
            i = smallest;
        }
    }
    return top;
}

int numberOfWays(int n, const std::vector<std::vector<int>>& roads) {
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (const auto& road : roads) {
        int u = road[0];
        int v = road[1];
        int w = road[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    std::vector<long long> dist(n, LLONG_MAX);
    std::vector<long long> ways(n, 0);
    dist[0] = 0;
    ways[0] = 1;

    std::vector<std::pair<long long, int>> heap;
    heapPush(heap, {0LL, 0});

    while (!heap.empty()) {
        std::pair<long long, int> top = heapPop(heap);
        long long d = top.first;
        int u = top.second;
        if (d != dist[u]) continue;
        for (const auto& vw : adj[u]) {
            int v = vw.first;
            int w = vw.second;
            long long nd = d + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                ways[v] = ways[u];
                heapPush(heap, {nd, v});
            } else if (nd == dist[v]) {
                ways[v] = (ways[v] + ways[u]) % MOD;
            }
        }
    }

    return static_cast<int>(ways[n - 1] % MOD);
}

