int numberOfWays(std::string num) {
    const int MOD = 1000000007;
    int n = static_cast<int>(num.size());
    std::vector<std::vector<int>> lcp(n + 1, std::vector<int>(n + 1, 0));
    for (int i = n - 1; i >= 0; --i) {
        for (int j = n - 1; j >= 0; --j) {
            if (num[i] == num[j]) {
                lcp[i][j] = 1 + lcp[i + 1][j + 1];
            }
        }
    }
    std::vector<std::vector<int>> pref(n, std::vector<int>(n + 1, 0));
    auto getPref = [&](int pos, int len) -> int {
        if (pos < 0) return 0;
        int maxLen = pos + 1;
        if (len > maxLen) len = maxLen;
        return pref[pos][len];
    };
    auto getDP = [&](int pos, int len) -> int {
        if (pos < 0) return 0;
        if (len > pos + 1) return 0;
        int val = pref[pos][len] - pref[pos][len - 1];
        if (val < 0) val += MOD;
        return val;
    };
    for (int i = 0; i < n; ++i) {
        std::vector<int> cur(i + 2, 0);
        for (int L = 1; L <= i + 1; ++L) {
            int start = i - L + 1;
            if (num[start] == '0') continue;
            int ways = 0;
            if (start == 0) {
                ways = 1;
            } else {
                ways = getPref(start - 1, L - 1);
                if (start - L >= 0) {
                    int a = start - L;
                    int b = start;
                    int common = lcp[a][b];
                    bool le;
                    if (common >= L) {
                        le = true;
                    } else {
                        le = num[a + common] < num[b + common];
                    }
                    if (le) {
                        ways += getDP(start - 1, L);
                        if (ways >= MOD) ways -= MOD;
                    }
                }
            }
            cur[L] = ways;
        }
        for (int L = 1; L <= i + 1; ++L) {
            int sum = pref[i][L - 1] + cur[L];
            if (sum >= MOD) sum -= MOD;
            pref[i][L] = sum;
        }
    }
    return pref[n - 1][n];
}

