std::string findUniqueBinaryString(const std::vector<std::string>& nums) {
    std::size_t n = nums.size();
    std::unordered_set<std::string> present(nums.begin(), nums.end());

    std::string xorStr;
    xorStr.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        int cnt = 0;
        for (const std::string& s : nums) {
            if (s[i] == '1') ++cnt;
        }
        xorStr.push_back((cnt % 2) ? '1' : '0');
    }

    if (present.find(xorStr) == present.end()) {
        return xorStr;
    }

    std::string flipped = xorStr;
    flipped[0] = (xorStr[0] == '0') ? '1' : '0';
    if (present.find(flipped) == present.end()) {
        return flipped;
    }

    std::string diagonal;
    diagonal.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        diagonal.push_back(nums[i][i] == '0' ? '1' : '0');
    }
    return diagonal;
}

