int minSessions(const std::vector<int>& tasks, int sessionTime) {
    int n = static_cast<int>(tasks.size());
    int totalMask = 1 << n;
    std::vector<std::pair<int, int>> dp(totalMask, {INT_MAX, INT_MAX});
    dp[0] = {1, 0};
    for (int mask = 0; mask < totalMask; ++mask) {
        int sessions = dp[mask].first;
        int cur = dp[mask].second;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) continue;
            int newMask = mask | (1 << i);
            int newSessions = sessions;
            int newCur = cur + tasks[i];
            if (newCur > sessionTime) {
                ++newSessions;
                newCur = tasks[i];
            }
            if (newSessions < dp[newMask].first ||
                (newSessions == dp[newMask].first && newCur < dp[newMask].second)) {
                dp[newMask] = {newSessions, newCur};
            }
        }
    }
    return dp[totalMask - 1].first;
}

