static long long distinctCount(const std::string& s) {
    long long dp = 1;
    long long last[2] = {0, 0};
    for (size_t i = 0; i < s.size(); ++i) {
        int ch = s[i] - '0';
        long long newDp = (dp * 2) % MOD;
        newDp = (newDp - last[ch] + MOD) % MOD;
        last[ch] = dp;
        dp = newDp;
    }
    return dp;
}

int numberOfUniqueGoodSubsequences(const std::string& binary) {
    long long totalDistinct = distinctCount(binary);
    size_t firstZero = binary.find('0');
    long long ans;
    if (firstZero == std::string::npos) {
        ans = (totalDistinct - 1 + MOD) % MOD;
    } else {
        std::string suffix = binary.substr(firstZero + 1);
        long long suffixDistinct = distinctCount(suffix);
        ans = (totalDistinct - suffixDistinct + MOD) % MOD;
    }
    return static_cast<int>(ans);
}

