struct LockingTreeObj {
    std::vector<int> parent;
    std::vector<std::vector<int>> children;
    std::vector<int> lockedBy;
    bool lock(int node, int user) {
        if (lockedBy[node] != -1) return false;
        lockedBy[node] = user;
        return true;
    }
    bool unlock(int node, int user) {
        if (lockedBy[node] != user) return false;
        lockedBy[node] = -1;
        return true;
    }
    bool upgrade(int node, int user) {
        if (lockedBy[node] != -1) return false;
        for (int cur = parent[node]; cur != -1; cur = parent[cur]) {
            if (lockedBy[cur] != -1) return false;
        }
        std::vector<int> stack;
        stack.push_back(node);
        std::vector<int> lockedDescendants;
        while (!stack.empty()) {
            int cur = stack.back();
            stack.pop_back();
            for (int child : children[cur]) {
                if (lockedBy[child] != -1) lockedDescendants.push_back(child);
                stack.push_back(child);
            }
        }
        if (lockedDescendants.empty()) return false;
        for (int d : lockedDescendants) lockedBy[d] = -1;
        lockedBy[node] = user;
        return true;
    }
};

LockingTreeObj LockingTree(const std::vector<int>& parent) {
    int n = parent.size();
    LockingTreeObj obj;
    obj.parent = parent;
    obj.children.assign(n, std::vector<int>());
    for (int i = 1; i < n; ++i) {
        obj.children[parent[i]].push_back(i);
    }
    obj.lockedBy.assign(n, -1);
    return obj;
}

