class DSU {
    std::vector<int> parent, rank_;
public:
    DSU(int n) : parent(n), rank_(n, 0) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (rank_[a] < rank_[b]) std::swap(a, b);
        parent[b] = a;
        if (rank_[a] == rank_[b]) ++rank_[a];
    }
};

std::vector<int> smallestPrimeFactor(int limit) {
    std::vector<int> spf(limit + 1);
    for (int i = 2; i <= limit; ++i) {
        if (spf[i] == 0) {
            for (int j = i; j <= limit; j += i) {
                if (spf[j] == 0) spf[j] = i;
            }
        }
    }
    return spf;
}

bool gcdSort(std::vector<int> nums) {
    int n = static_cast<int>(nums.size());
    if (n <= 1) return true;
    std::vector<int> sorted = nums;
    std::sort(sorted.begin(), sorted.end());

    int maxVal = *std::max_element(nums.begin(), nums.end());
    std::vector<int> spf = smallestPrimeFactor(maxVal);

    DSU dsu(n);
    std::unordered_map<int, int> primeRep;

    for (int i = 0; i < n; ++i) {
        int x = nums[i];
        std::unordered_set<int> primes;
        while (x > 1) {
            int p = spf[x];
            primes.insert(p);
            while (x % p == 0) x /= p;
        }
        for (int p : primes) {
            auto it = primeRep.find(p);
            if (it == primeRep.end()) {
                primeRep[p] = i;
            } else {
                dsu.unite(i, it->second);
            }
        }
    }

    std::unordered_map<int, std::vector<int>> groups;
    for (int i = 0; i < n; ++i) {
        int root = dsu.find(i);
        groups[root].push_back(i);
    }

    for (const auto &kv : groups) {
        const std::vector<int> &indices = kv.second;
        std::vector<int> origVals, targetVals;
        origVals.reserve(indices.size());
        targetVals.reserve(indices.size());
        for (int idx : indices) {
            origVals.push_back(nums[idx]);
            targetVals.push_back(sorted[idx]);
        }
        std::sort(origVals.begin(), origVals.end());
        std::sort(targetVals.begin(), targetVals.end());
        if (origVals != targetVals) return false;
    }
    return true;
}

