#include <bits/stdc++.h>

std::vector<int> smallestMissingValueSubtree(const std::vector<int>& parents, const std::vector<int>& nums) {
    int n = (int)parents.size();
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) {
        children[parents[i]].push_back(i);
    }

    std::vector<int> ans(n, 1);
    int nodeWithOne = -1;
    for (int i = 0; i < n; ++i) {
        if (nums[i] == 1) {
            nodeWithOne = i;
            break;
        }
    }
    if (nodeWithOne == -1) {
        return ans; // all answers are 1
    }

    const int MAXV = 100000;
    std::vector<char> seen(MAXV + 2, 0);
    std::vector<char> visitedNode(n, 0);
    int mex = 1;
    int cur = nodeWithOne;
    while (cur != -1) {
        // DFS to add all values in the subtree of cur that are not yet visited
        std::stack<int> st;
        st.push(cur);
        while (!st.empty()) {
            int u = st.top(); st.pop();
            if (visitedNode[u]) continue;
            visitedNode[u] = 1;
            int val = nums[u];
            if (val <= MAXV + 1) seen[val] = 1;
            for (int v : children[u]) {
                if (!visitedNode[v]) st.push(v);
            }
        }
        while (seen[mex]) ++mex;
        ans[cur] = mex;
        cur = parents[cur];
    }
    return ans;
}

