long long countQuadruplets(const std::vector<int>& nums) {
    int n = nums.size();
    long long answer = 0;
    std::unordered_map<int, int> sumFreq;
    for (int k = 2; k < n - 1; ++k) {
        for (int i = 0; i < k - 1; ++i) {
            int s = nums[i] + nums[k - 1];
            ++sumFreq[s];
        }
        for (int l = k + 1; l < n; ++l) {
            int needed = nums[l] - nums[k];
            auto it = sumFreq.find(needed);
            if (it != sumFreq.end()) {
                answer += it->second;
            }
        }
    }
    return answer;
}

