std::string reversePrefix(const std::string& word, char ch) {
    size_t idx = word.find(ch);
    if (idx == std::string::npos) return word;
    std::string arr = word;
    size_t left = 0, right = idx;
    while (left < right) {
        char tmp = arr[left];
        arr[left] = arr[right];
        arr[right] = tmp;
        ++left;
        --right;
    }
    return arr;
