long long firstDayWhereAllRoomsVisited(const std::vector<int>& nextVisit) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(nextVisit.size());
    std::vector<long long> dp(n, 0);
    dp[0] = 0; // already in room 0 on day 0
    for (int i = 1; i < n; ++i) {
        long long val = (2LL * dp[i - 1]) % MOD;
        val = (val - dp[nextVisit[i - 1]] + MOD) % MOD;
        val = (val + 2) % MOD;
        dp[i] = val;
    }
    return dp[n - 1];
}

