static int compute_gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long interchangeableRectangles(std::vector<std::vector<int>>& rectangles) {
    std::unordered_map<unsigned long long, long long> freq;
    long long ans = 0;
    for (const auto& rect : rectangles) {
        int w = rect[0];
        int h = rect[1];
        int g = compute_gcd(w, h);
        w /= g;
        h /= g;
        unsigned long long key = (static_cast<unsigned long long>(w) << 32) | static_cast<unsigned int>(h);
        ans += freq[key];
        ++freq[key];
    }
    return ans;
}

