int maxProduct(const std::string& s) {
    int n = static_cast<int>(s.size());
    int total = 1 << n;
    std::vector<int> palLen(total, 0);
    for (int mask = 1; mask < total; ++mask) {
        std::string t;
        t.reserve(n);
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                t.push_back(s[i]);
            }
        }
        bool ok = true;
        int m = static_cast<int>(t.size());
        for (int i = 0; i < m / 2; ++i) {
            if (t[i] != t[m - 1 - i]) {
                ok = false;
                break;
            }
        }
        if (ok) {
            palLen[mask] = m;
        }
    }
    int ans = 0;
    for (int mask1 = 1; mask1 < total; ++mask1) {
        if (palLen[mask1] == 0) continue;
        for (int mask2 = mask1 + 1; mask2 < total; ++mask2) {
            if ((mask1 & mask2) != 0) continue;
            if (palLen[mask2] == 0) continue;
            int prod = palLen[mask1] * palLen[mask2];
            if (prod > ans) ans = prod;
        }
    }
    return ans;
}

