long long countPairs(const std::vector<int>& nums, int k) {
    std::unordered_map<long long, long long> freq;
    for (int num : nums) {
        ++freq[static_cast<long long>(num)];
    }

    long long pairCount = 0;

    if (k == 0) {
        for (const auto& entry : freq) {
            long long f = entry.second;
            pairCount += f * (f - 1) / 2;
        }
    } else {
        for (const auto& entry : freq) {
            long long key = entry.first;
            long long target = key + static_cast<long long>(k);
            auto it = freq.find(target);
            if (it != freq.end()) {
                pairCount += entry.second * it->second;
            }
        }
    }

    return pairCount;
}

