std::vector<int> findOriginalArray(const std::vector<int>& changed) {
    if (changed.size() % 2 != 0) {
        return {};
    }
    std::unordered_map<int, int> freq;
    for (int v : changed) {
        freq[v] = freq[v] + 1;
    }
    std::vector<int> sorted = changed;
    std::sort(sorted.begin(), sorted.end());
    std::vector<int> original;
    for (int v : sorted) {
        int cnt = freq[v];
        if (cnt == 0) continue;
        if (v == 0) {
            if (cnt % 2 != 0) {
                return {};
            }
            for (int i = 0; i < cnt / 2; ++i) {
                original.push_back(0);
            }
            freq[0] = 0;
            continue;
        }
        int doublev = v * 2;
        int doubleCnt = freq.count(doublev) ? freq[doublev] : 0;
        if (doubleCnt < cnt) {
            return {};
        }
        for (int i = 0; i < cnt; ++i) {
            original.push_back(v);
        }
        freq[v] = 0;
        freq[doublev] = doubleCnt - cnt;
    }
    return original;
}

