long long maxTaxiEarnings(int n, std::vector<std::vector<int>>& rides) {
    std::sort(rides.begin(), rides.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        if (a[0] != b[0]) return a[0] < b[0];
        return a[1] < b[1];
    });

    std::size_t m = rides.size();
    std::vector<int> starts(m);
    for (std::size_t i = 0; i < m; ++i) {
        starts[i] = rides[i][0];
    }

    std::vector<long long> dp(m + 1, 0);

    for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(m) - 1; i >= 0; --i) {
        long long profit = static_cast<long long>(rides[i][1] - rides[i][0] + rides[i][2]);

        std::size_t lo = i + 1, hi = m;
        while (lo < hi) {
            std::size_t mid = (lo + hi) >> 1;
            if (starts[mid] >= rides[i][1]) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        std::size_t nextIdx = lo;

        dp[i] = std::max(dp[i + 1], profit + dp[nextIdx]);
    }

    return dp[0];
}

