bool canForm(const std::string& seq, const std::string& s, int k) {
    if (seq.empty()) return true;
    int pos = 0;
    int repeats = 0;
    for (char ch : s) {
        if (ch == seq[pos]) {
            ++pos;
            if (pos == (int)seq.size()) {
                pos = 0;
                ++repeats;
                if (repeats >= k) return true;
            }
        }
    }
    return repeats >= k;
}

std::string longestSubsequenceRepeatedK(const std::string& s, int k) {
    std::vector<std::string> cur{""};
    std::string best;
    while (true) {
        std::vector<std::string> nxt;
        for (const std::string& pref : cur) {
            for (char c = 'z'; c >= 'a'; --c) {
                std::string cand = pref;
                cand.push_back(c);
                if (canForm(cand, s, k)) {
                    nxt.push_back(std::move(cand));
                }
            }
        }
        if (nxt.empty()) break;
        best = nxt[0];
        for (size_t i = 1; i < nxt.size(); ++i) {
            if (nxt[i] > best) best = nxt[i];
        }
        cur.swap(nxt);
    }
    return best;
}

