int minOperations(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::unordered_set<int> seen(nums.begin(), nums.end());
    std::vector<int> uniq;
    uniq.reserve(seen.size());
    for (int v : seen) {
        uniq.push_back(v);
    }
    std::sort(uniq.begin(), uniq.end());
    int maxKeep = 0;
    int left = 0;
    for (int right = 0; right < static_cast<int>(uniq.size()); ++right) {
        while (uniq[right] - uniq[left] >= n) {
            ++left;
        }
        int cur = right - left + 1;
        if (cur > maxKeep) {
            maxKeep = cur;
        }
    }
    return n - maxKeep;
}

