struct DetectSquaresResult {
    std::function<void(const std::pair<int, int>&)> add;
    std::function<int(const std::pair<int, int>&)> count;
};

DetectSquaresResult DetectSquares() {
    // shared_ptr keeps the map alive for as long as the returned closures exist,
    // rather than a reference to a local that is destroyed when this function returns
    auto points = std::make_shared<std::unordered_map<int, std::unordered_map<int, int>>>();
    auto add = [points](const std::pair<int, int>& point) {
        int x = point.first;
        int y = point.second;
        auto& col = (*points)[x];
        col[y] = col[y] + 1;
    };
    auto count = [points](const std::pair<int, int>& point) -> int {
        int x = point.first;
        int y = point.second;
        auto itX = points->find(x);
        if (itX == points->end()) return 0;
        long long total = 0;
        const auto& col = itX->second;
        for (const auto& kv : col) {
            int y2 = kv.first;
            int cntY2 = kv.second;
            if (y2 == y) continue;
            int d = std::abs(y2 - y);
            for (int dir : {-1, 1}) {
                int x2 = x + dir * d;
                auto itX2 = points->find(x2);
                if (itX2 == points->end()) continue;
                const auto& colX2 = itX2->second;
                int cnt1 = 0; auto itCnt1 = colX2.find(y); if (itCnt1 != colX2.end()) cnt1 = itCnt1->second;
                int cnt2 = 0; auto itCnt2 = colX2.find(y2); if (itCnt2 != colX2.end()) cnt2 = itCnt2->second;
                total += static_cast<long long>(cntY2) * cnt1 * cnt2;
            }
        }
        return static_cast<int>(total);
    };
    return {add, count};
}

