long long gridGame(const std::vector<std::vector<long long>>& grid) {
    const std::size_t n = grid[0].size();
    const std::vector<long long>& top = grid[0];
    const std::vector<long long>& bottom = grid[1];

    std::vector<long long> suffixTop(n + 1, 0);
    for (std::size_t i = n; i-- > 0;) {
        suffixTop[i] = suffixTop[i + 1] + top[i];
    }

    std::vector<long long> prefixBottom(n, 0);
    prefixBottom[0] = bottom[0];
    for (std::size_t i = 1; i < n; ++i) {
        prefixBottom[i] = prefixBottom[i - 1] + bottom[i];
    }

    long long answer = std::numeric_limits<long long>::max();
    for (std::size_t i = 0; i < n; ++i) {
        long long topRemain = suffixTop[i + 1];
        long long bottomRemain = (i > 0) ? prefixBottom[i - 1] : 0;
        long long worst = std::max(topRemain, bottomRemain);
        if (worst < answer) answer = worst;
    }
    return answer;
}

#include <bits/stdc++.h>
#include <vector>
#include <string>

bool placeWordInCrossword(const std::vector<std::string>& board, const std::string& word) {
    int m = static_cast<int>(board.size());
    int n = static_cast<int>(board[0].size());
    int L = static_cast<int>(word.size());
    const std::pair<int, int> dirs[] = { {0, 1}, {0, -1}, {1, 0}, {-1, 0} };

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (board[i][j] == '#') continue;
            for (const auto& dir : dirs) {
                int dx = dir.first;
                int dy = dir.second;

                int prevX = i - dx;
                int prevY = j - dy;
                if (prevX >= 0 && prevX < m && prevY >= 0 && prevY < n && board[prevX][prevY] != '#') continue;

                int afterX = i + dx * L;
                int afterY = j + dy * L;
                if (afterX >= 0 && afterX < m && afterY >= 0 && afterY < n && board[afterX][afterY] != '#') continue;

                bool ok = true;
                for (int k = 0; k < L; ++k) {
                    int x = i + dx * k;
                    int y = j + dy * k;
                    char cell = board[x][y];
                    char expected = (dx == -1 || dy == -1) ? word[L - 1 - k] : word[k];
                    if (cell != ' ' && cell != expected) {
                        ok = false;
                        break;
                    }
                }
                if (ok) return true;
            }
        }
    }
    return false;
}

