int gradeStudents(const std::string& s, const std::vector<int>& answers) {
    int correct = 0;
    int product = 1;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '+') {
            correct += product;
            product = 1;
        } else if (c == '*') {
            // do nothing
        } else {
            product *= (c - '0');
        }
    }
    correct += product;

    int leftToRight = s[0] - '0';
    for (size_t i = 1; i + 1 < s.size(); i += 2) {
        char op = s[i];
        int val = s[i + 1] - '0';
        if (op == '+')
            leftToRight += val;
        else
            leftToRight *= val;
    }

    int totalPoints = 0;
    for (int ans : answers) {
        if (ans == correct)
            totalPoints += 5;
        else if (ans == leftToRight)
            totalPoints += 2;
    }
    return totalPoints;
}

