    int best = -1;
    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] > minSoFar) {
            int diff = nums[i] - minSoFar;
            if (diff > best) best = diff;
        }
        if (nums[i] < minSoFar) minSoFar = nums[i];
    }
    return best;
}

#include <bits/stdc++.h>

int waysToPartition(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    long long total = 0;
    for (int v : nums) total += v;

    std::vector<long long> pref(n);
    long long cur = 0;
    for (int i = 0; i < n; ++i) {
        cur += nums[i];
        pref[i] = cur;
    }

    std::unordered_map<long long, int> leftCount;
    std::unordered_map<long long, int> rightCount;
    for (int i = 0; i < n - 1; ++i) {
        ++rightCount[pref[i]];
    }

    int maxWays = 0;
    // baseline without any change
    for (int i = 0; i < n - 1; ++i) {
        if (2 * pref[i] == total) ++maxWays;
    }

    for (int j = 0; j < n; ++j) {
        long long delta = static_cast<long long>(k) - nums[j];
        long long ways = 0;

        long long target1 = total + delta;
        if (target1 % 2 == 0) {
            long long need = target1 / 2;
            auto it = leftCount.find(need);
            if (it != leftCount.end()) ways += it->second;
        }

        long long target2 = total - delta;
        if (target2 % 2 == 0) {
            long long need = target2 / 2;
            auto it = rightCount.find(need);
            if (it != rightCount.end()) ways += it->second;
        }

        if (ways > maxWays) maxWays = static_cast<int>(ways);

        if (j <= n - 2) {
            long long p = pref[j];
            auto itR = rightCount.find(p);
            if (itR != rightCount.end()) {
                if (itR->second == 1) rightCount.erase(itR);
                else --itR->second;
            }
            ++leftCount[p];
        }
    }

    return maxWays;
}

