int maxConsecutiveAnswers(const std::string& answerKey, int k) {
    const std::size_t n = answerKey.size();
    auto longest = [&](char target) -> int {
        int left = 0;
        int maxLen = 0;
        int changes = 0;
        for (int right = 0; right < static_cast<int>(n); ++right) {
            if (answerKey[right] != target) ++changes;
            while (changes > k) {
                if (answerKey[left] != target) --changes;
                ++left;
            }
            maxLen = std::max(maxLen, right - left + 1);
        }
        return maxLen;
    };
    return std::max(longest('T'), longest('F'));
}

