std::vector<int> findMissingObservations(const std::vector<int>& rolls, int mean, int n) {
    int m = static_cast<int>(rolls.size());
    long long totalNeeded = static_cast<long long>(mean) * (n + m);
    long long knownSum = std::accumulate(rolls.begin(), rolls.end(), 0LL);
    long long missingSum = totalNeeded - knownSum;
    if (missingSum < n || missingSum > 6LL * n) {
        return {};
    }
    long long base = missingSum / n;
    long long rem = missingSum % n;
    if (base < 1 || base > 6) {
        return {};
    }
    if (base == 6 && rem > 0) {
        return {};
    }
    std::vector<int> result(n, static_cast<int>(base));
    for (int i = 0; i < static_cast<int>(rem); ++i) {
        result[i + 1] += 1;
    }
    return result;
}

