bool stoneGameIX(const std::vector<int>& stones) {
    int c0 = 0, c1 = 0, c2 = 0;
    for (int v : stones) {
        int r = v % 3;
        if (r == 0) {
            ++c0;
        } else if (r == 1) {
            ++c1;
        } else {
            ++c2;
        }
    }
    if (c1 == 0 && c2 == 0) return false;
    if (c0 % 2 == 0) {
        return c1 > 0 && c2 > 0;
    } else {
        return c1 > 2 || c2 > 2;
    }
}

