#include <utility>

struct StockPriceObj {
    std::unordered_map<int, int> priceMap;
    int latestTimestamp = 0;
    std::vector<std::pair<int, int>> maxHeap;
    std::vector<std::pair<int, int>> minHeap;

    void heapPush(std::vector<std::pair<int, int>>& heap, const std::pair<int, int>& item, bool (*better)(const std::pair<int, int>&, const std::pair<int, int>&)) {
        heap.push_back(item);
        int i = static_cast<int>(heap.size()) - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (better(heap[p], heap[i])) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
    }

    std::pair<int, int> heapPop(std::vector<std::pair<int, int>>& heap, bool (*better)(const std::pair<int, int>&, const std::pair<int, int>&)) {
        std::pair<int, int> top = heap[0];
        std::pair<int, int> last = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = last;
            heapifyDown(heap, 0, better);
        }
        return top;
    }

    void heapifyDown(std::vector<std::pair<int, int>>& heap, int i, bool (*better)(const std::pair<int, int>&, const std::pair<int, int>&)) {
        int n = static_cast<int>(heap.size());
        while (true) {
            int left = i * 2 + 1;
            int right = i * 2 + 2;
            int best = i;
            if (left < n && !better(heap[best], heap[left])) best = left;
            if (right < n && !better(heap[best], heap[right])) best = right;
            if (best == i) break;
            std::swap(heap[i], heap[best]);
            i = best;
        }
    }

    void clean(std::vector<std::pair<int, int>>& heap, bool (*better)(const std::pair<int, int>&, const std::pair<int, int>&)) {
        while (!heap.empty()) {
            const auto& top = heap[0];
            int price = top.first;
            int ts = top.second;
            auto it = priceMap.find(ts);
            if (it == priceMap.end() || it->second != price) {
                heapPop(heap, better);
            } else {
                break;
            }
        }
    }

    void update(int timestamp, int price) {
        priceMap[timestamp] = price;
        if (timestamp >= latestTimestamp) latestTimestamp = timestamp;
        heapPush(maxHeap, {price, timestamp}, [](const std::pair<int, int>& a, const std::pair<int, int>& b){ return a.first > b.first; });
        heapPush(minHeap, {price, timestamp}, [](const std::pair<int, int>& a, const std::pair<int, int>& b){ return a.first < b.first; });
    }

    int current() {
        return priceMap[latestTimestamp];
    }

    int maximum() {
        clean(maxHeap, [](const std::pair<int, int>& a, const std::pair<int, int>& b){ return a.first > b.first; });
        return maxHeap[0].first;
    }

    int minimum() {
        clean(minHeap, [](const std::pair<int, int>& a, const std::pair<int, int>& b){ return a.first < b.first; });
        return minHeap[0].first;
    }
};

StockPriceObj StockPrice() {
    return StockPriceObj();
}

