#include <bits/stdc++.h>

std::string smallestSubsequence(const std::string& s, int k, char letter, int repetition) {
    int n = static_cast<int>(s.size());
    int totalLetter = 0;
    for (char ch : s) if (ch == letter) ++totalLetter;

    int selectedLetter = 0;          // number of 'letter' already in the stack
    int lettersSeen = 0;             // number of 'letter' processed before current index
    std::vector<char> st;            // monotonic stack storing the answer characters

    for (int i = 0; i < n; ++i) {
        char c = s[i];
        int remaining = n - i - 1;                       // characters after current position
        int lettersLeft = totalLetter - lettersSeen;     // 'letter' still available (including current if it is 'letter')

        // Try to remove larger previous characters while keeping feasibility
        while (!st.empty() && st.back() > c) {
            // After popping, we would have (st.size() - 1) characters selected,
            // and (remaining + 1) characters still unseen (including current).
            if ((int)st.size() - 1 + (remaining + 1) < k) break; // not enough characters to reach length k

            if (st.back() == letter) {
                // Ensure we can still meet the required repetitions after removing this 'letter'
                if (selectedLetter - 1 + lettersLeft < repetition) break;
            }
            if (st.back() == letter) --selectedLetter;
            st.pop_back();
        }

        // Decide whether to take the current character
        if ((int)st.size() < k) {
            int newSelectedLetter = selectedLetter + (c == letter);
            int stillNeedLetter = std::max(0, repetition - newSelectedLetter);
            int lettersRemainingAfter = totalLetter - (lettersSeen + (c == letter));
            // Check that enough required letters remain after taking this character
            if (stillNeedLetter <= lettersRemainingAfter) {
                // Also ensure we can still fill the remaining slots after taking it
                if (remaining >= k - ((int)st.size() + 1)) {
                    st.push_back(c);
                    if (c == letter) ++selectedLetter;
                }
            }
        }

        if (c == letter) ++lettersSeen;
    }

    // If we somehow have more than k characters, truncate the excess
    while ((int)st.size() > k) st.pop_back();

    return std::string(st.begin(), st.end());
}

