#include <bits/stdc++.h>
long long minimumDifference(std::vector<int>& nums) {
    int totalLen = nums.size();
    int n = totalLen / 2;
    std::vector<int> left(nums.begin(), nums.begin() + n);
    std::vector<int> right(nums.begin() + n, nums.end());

    std::vector<std::vector<long long>> leftSums(n + 1), rightSums(n + 1);

    int leftMaskLimit = 1 << n;
    for (int mask = 0; mask < leftMaskLimit; ++mask) {
        int cnt = __builtin_popcount(mask);
        long long sum = 0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) sum += left[i];
        }
        leftSums[cnt].push_back(sum);
    }

    int rightMaskLimit = 1 << n;
    for (int mask = 0; mask < rightMaskLimit; ++mask) {
        int cnt = __builtin_popcount(mask);
        long long sum = 0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) sum += right[i];
        }
        rightSums[cnt].push_back(sum);
    }

    long long totalSum = 0;
    for (int v : nums) totalSum += v;
    long long target = totalSum / 2;

    long long answer = LLONG_MAX;
    for (int k = 0; k <= n; ++k) {
        std::vector<long long>& L = leftSums[k];
        std::vector<long long>& R = rightSums[n - k];
        std::sort(R.begin(), R.end());
        for (long long sumL : L) {
            long long need = target - sumL;
            auto it = std::lower_bound(R.begin(), R.end(), need);
            if (it != R.end()) {
                long long sumA = sumL + *it;
                long long diff = std::llabs(2 * sumA - totalSum);
                if (diff < answer) answer = diff;
            }
            if (it != R.begin()) {
                --it;
                long long sumA = sumL + *it;
                long long diff = std::llabs(2 * sumA - totalSum);
                if (diff < answer) answer = diff;
            }
        }
    }
    return answer;
}

#include <bits/stdc++.h>

long long kthSmallestProduct(const std::vector<int>& nums1, const std::vector<int>& nums2, long long k) {
    int n = static_cast<int>(nums1.size());
    int m = static_cast<int>(nums2.size());

    auto floorDiv = [](long long a, long long b) -> long long {
        long long q = a / b;
        long long r = a % b;
        if (r != 0 && ((r > 0) != (b > 0))) --q;
        return q;
    };
    auto ceilDiv = [](long long a, long long b) -> long long {
        long long q = a / b;
        long long r = a % b;
        if (r != 0 && ((r > 0) == (b > 0))) ++q;
        return q;
    };

    auto countLE = [&](long long x) -> long long {
        long long cnt = 0;
        for (int i = 0; i < n; ++i) {
            long long a = nums1[i];
            if (a > 0) {
                long long limit = floorDiv(x, a);
                cnt += std::upper_bound(nums2.begin(), nums2.end(), limit) - nums2.begin();
            } else if (a < 0) {
                long long limit = ceilDiv(x, a);
                cnt += nums2.end() - std::lower_bound(nums2.begin(), nums2.end(), limit);
            } else { // a == 0
                if (x >= 0) cnt += m;
            }
            if (cnt >= k) return cnt;
        }
        return cnt;
    };

    long long low = -100000LL * 100000LL - 5;
    long long high = 100000LL * 100000LL + 5;
    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (countLE(mid) >= k) high = mid;
        else low = mid + 1;
    }
    return low;
}

