std::vector<bool> simpleBank(std::vector<long long>& balance, const std::vector<std::vector<std::string>>& transactions) {
    int n = static_cast<int>(balance.size());
    std::vector<bool> answer;
    answer.reserve(transactions.size());
    for (const auto& t : transactions) {
        const std::string& type = t[0];
        if (type == "transfer") {
            int a = std::stoi(t[1]);
            int b = std::stoi(t[2]);
            long long money = std::stoll(t[3]);
            if (a < 1 || a > n || b < 1 || b > n || balance[a - 1] < money) {
                answer.push_back(false);
                continue;
            }
            balance[a - 1] -= money;
            balance[b - 1] += money;
            answer.push_back(true);
        } else if (type == "deposit") {
            int a = std::stoi(t[1]);
            long long money = std::stoll(t[2]);
            if (a < 1 || a > n) {
                answer.push_back(false);
                continue;
            }
            balance[a - 1] += money;
            answer.push_back(true);
        } else if (type == "withdraw") {
            int a = std::stoi(t[1]);
            long long money = std::stoll(t[2]);
            if (a < 1 || a > n || balance[a - 1] < money) {
                answer.push_back(false);
                continue;
            }
            balance[a - 1] -= money;
            answer.push_back(true);
        }
    }
    return answer;
}

