int secondMinimum(int n, std::vector<std::vector<int>>& edges, int time, int change) {
    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    const int INF = 1e9;
    std::vector<std::array<int, 2>> dist(n + 1, {INF, INF});
    std::queue<std::pair<int, int>> q;
    dist[1][0] = 0;
    q.emplace(1, 0);
    while (!q.empty()) {
        std::pair<int, int> cur = q.front();
        q.pop();
        int node = cur.first;
        int d = cur.second;
        for (int nb : adj[node]) {
            int nd = d + 1;
            if (nd < dist[nb][0]) {
                dist[nb][1] = dist[nb][0];
                dist[nb][0] = nd;
                q.emplace(nb, nd);
            } else if (nd > dist[nb][0] && nd < dist[nb][1]) {
                dist[nb][1] = nd;
                q.emplace(nb, nd);
            }
        }
    }
    int steps = dist[n][1];
    long long cur = 0;
    for (int i = 0; i < steps; ++i) {
        if ((cur / change) % 2 == 1) {
            cur = ((cur / change) + 1) * change;
        }
        cur += time;
    }
    return static_cast<int>(cur);
}

#include <bits/stdc++.h>
int networkBecomesIdle(std::vector<std::vector<int>>& edges, std::vector<int>& patience) {
    int n = patience.size();
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<int> dist(n, -1);
    std::queue<int> q;
    dist[0] = 0;
    q.push(0);
    while (!q.empty()) {
        int cur = q.front(); q.pop();
        for (int nb : adj[cur]) {
            if (dist[nb] == -1) {
                dist[nb] = dist[cur] + 1;
                q.push(nb);
            }
        }
    }
    long long ans = 0;
    for (int i = 1; i < n; ++i) {
        long long roundTrip = 2LL * dist[i];
        long long p = patience[i];
        long long lastSent = ((roundTrip - 1) / p) * p;
        ans = std::max(ans, lastSent + roundTrip);
    }
    return static_cast<int>(ans + 1);
}

