#include <bits/stdc++.h>

int countHighestScoreNodes(std::vector<int>& parents) {
    int n = parents.size();
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) {
        children[parents[i]].push_back(i);
    }

    std::vector<int> subSize(n, 1);
    std::vector<std::pair<int, int>> stack;
    stack.reserve(2 * n);
    stack.emplace_back(0, 0); // node, state 0=first visit, 1=post visit

    while (!stack.empty()) {
        int node = stack.back().first;
        int state = stack.back().second;
        stack.pop_back();
        if (state == 0) {
            stack.emplace_back(node, 1);
            for (int child : children[node]) {
                stack.emplace_back(child, 0);
            }
        } else {
            int total = 1;
            for (int child : children[node]) {
                total += subSize[child];
            }
            subSize[node] = total;
        }
    }

    unsigned long long maxScore = 0;
    int count = 0;
    for (int i = 0; i < n; ++i) {
        unsigned long long score = 1;
        for (int child : children[i]) {
            score *= static_cast<unsigned long long>(subSize[child]);
        }
        int above = n - subSize[i];
        if (above > 0) {
            score *= static_cast<unsigned long long>(above);
        }
        if (score > maxScore) {
            maxScore = score;
            count = 1;
        } else if (score == maxScore) {
            ++count;
        }
    }
    return count;
}

#include <bits/stdc++.h>
