int minimumTime(int n, const std::vector<std::vector<int>>& relations, const std::vector<int>& time) {
    std::vector<std::vector<int>> adj(n);
    std::vector<int> indeg(n, 0);
    for (const auto& rel : relations) {
        int u = rel[0] - 1;
        int v = rel[1] - 1;
        adj[u].push_back(v);
        indeg[v]++;
    }

    std::vector<int> finish(n);
    std::queue<int> q;

    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) {
            finish[i] = time[i];
            q.push(i);
        } else {
            finish[i] = 0;
        }
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            int candidate = finish[u] + time[v];
            if (candidate > finish[v]) finish[v] = candidate;
            if (--indeg[v] == 0) q.push(v);
        }
    }

    int answer = 0;
    for (int i = 0; i < n; ++i) {
        if (finish[i] > answer) answer = finish[i];
    }
    return answer;
}

