int countValidWords(const std::string& sentence) {
    auto isValid = [](const std::string& token) -> bool {
        if (token.empty()) return false;
        bool hyphenUsed = false;
        bool punctUsed = false;
        for (size_t i = 0; i < token.size(); ++i) {
            char c = token[i];
            if (std::isdigit(static_cast<unsigned char>(c))) {
                return false;
            } else if (c == '-') {
                if (hyphenUsed) return false;
                if (i == 0 || i + 1 == token.size()) return false;
                if (!std::isalpha(static_cast<unsigned char>(token[i - 1])) ||
                    !std::isalpha(static_cast<unsigned char>(token[i + 1]))) return false;
                hyphenUsed = true;
            } else if (c == '!' || c == '.' || c == ',') {
                if (punctUsed) return false;
                if (i != token.size() - 1) return false;
                punctUsed = true;
            } else if (!std::isalpha(static_cast<unsigned char>(c))) {
                return false;
            }
        }
        return true;
    };

    int count = 0;
    size_t i = 0, n = sentence.size();
    while (i < n) {
        while (i < n && sentence[i] == ' ') ++i;
        size_t start = i;
        while (i < n && sentence[i] != ' ') ++i;
        if (start < i) {
            std::string token = sentence.substr(start, i - start);
            if (isValid(token)) ++count;
        }
    }
    return count;
}

