std::vector<int> platesBetweenCandles(const std::string& s, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(s.size());
    std::vector<int> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + (s[i] == '*' ? 1 : 0);
    }

    std::vector<int> leftCandle(n, -1);
    int last = -1;
    for (int i = 0; i < n; ++i) {
        if (s[i] == '|') last = i;
        leftCandle[i] = last;
    }

    std::vector<int> rightCandle(n, -1);
    int next = -1;
    for (int i = n - 1; i >= 0; --i) {
        if (s[i] == '|') next = i;
        rightCandle[i] = next;
    }

    std::vector<int> ans(queries.size());
    for (size_t q = 0; q < queries.size(); ++q) {
        int l = queries[q][0];
        int r = queries[q][1];
        int left = rightCandle[l];
        int right = leftCandle[r];
        ans[q] = (left != -1 && right != -1 && left < right) ? pref[right] - pref[left + 1] : 0;
    }
    return ans;
}

