int maxTwoEvents(std::vector<std::vector<int>>& events) {
    if (events.empty()) return 0;

    std::sort(events.begin(), events.end(),
        [](const std::vector<int>& a, const std::vector<int>& b) {
            return a[1] < b[1];
        });

    int n = static_cast<int>(events.size());
    std::vector<int> ends(n);
    std::vector<int> prefixMax(n);

    for (int i = 0; i < n; ++i) {
        ends[i] = events[i][1];
        int val = events[i][2];
        prefixMax[i] = (i == 0) ? val : std::max(prefixMax[i - 1], val);
    }

    int best = 0;

    for (int i = 0; i < n; ++i) {
        int start = events[i][0];
        int value = events[i][2];
        best = std::max(best, value);

        int lo = 0, hi = i - 1, idx = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (ends[mid] < start) {
                idx = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        if (idx != -1) {
            best = std::max(best, value + prefixMax[idx]);
        }
    }

    return best;
}

