int countValidMoveCombinations(const std::vector<std::string>& pieces, const std::vector<std::vector<int>>& positions) {
    int n = static_cast<int>(pieces.size());
    std::vector<std::vector<std::pair<int, int>>> destLists;
    destLists.reserve(n);
    for (int i = 0; i < n; ++i) {
        const std::string& type = pieces[i];
        int r0 = positions[i][0];
        int c0 = positions[i][1];
        std::vector<std::pair<int, int>> list;
        for (int r = 1; r <= 8; ++r) {
            for (int c = 1; c <= 8; ++c) {
                int dr = r - r0;
                int dc = c - c0;
                int absDr = std::abs(dr);
                int absDc = std::abs(dc);
                bool ok = false;
                if (type == "rook") {
                    ok = (r == r0 || c == c0);
                } else if (type == "bishop") {
                    ok = (absDr == absDc);
                } else { // queen
                    ok = (r == r0 || c == c0 || absDr == absDc);
                }
                if (ok) {
                    list.emplace_back(r, c);
                }
            }
        }
        destLists.push_back(std::move(list));
    }

    int count = 0;
    std::vector<std::pair<int, int>> chosen(n);

    auto sign = [](int x) -> int {
        return (x > 0) - (x < 0);
    };

    auto isValid = [&](const std::vector<std::pair<int, int>>& destinations) -> bool {
        std::vector<std::vector<std::pair<int, int>>> paths(n);
        size_t maxLen = 0;
        for (int i = 0; i < n; ++i) {
            int startR = positions[i][0];
            int startC = positions[i][1];
            int destR = destinations[i].first;
            int destC = destinations[i].second;
            int dr = sign(destR - startR);
            int dc = sign(destC - startC);
            std::vector<std::pair<int, int>> path;
            int r = startR, c = startC;
            path.emplace_back(r, c);
            while (r != destR || c != destC) {
                r += dr;
                c += dc;
                path.emplace_back(r, c);
            }
            paths[i] = std::move(path);
            if (paths[i].size() > maxLen) maxLen = paths[i].size();
        }
        for (size_t t = 0; t < maxLen; ++t) {
            std::unordered_set<int> seen;
            for (int i = 0; i < n; ++i) {
                const auto& p = paths[i];
                const std::pair<int, int>& pos = (t < p.size()) ? p[t] : p.back();
                int key = pos.first * 8 + pos.second;
                if (seen.find(key) != seen.end()) return false;
                seen.insert(key);
            }
        }
        return true;
    };

    std::function<void(int)> dfs = [&](int idx) {
        if (idx == n) {
            if (isValid(chosen)) ++count;
            return;
        }
        for (const auto& dest : destLists[idx]) {
            chosen[idx] = dest;
            dfs(idx + 1);
        }
    };

    dfs(0);
    return count;
}

