using std::string;
using std::unordered_set;

struct State {
    int i, j, diff;
    bool operator==(const State& other) const noexcept {
        return i == other.i && j == other.j && diff == other.diff;
    }
};

struct StateHash {
    std::size_t operator()(const State& s) const noexcept {
        return ((std::size_t)s.i * 1315423911u) ^ ((std::size_t)s.j * 2654435761u) ^ (std::size_t)(s.diff + 1000);
    }
};

bool dfs(const string& s1, const string& s2, int i, int j, int diff, unordered_set<State, StateHash>& memo) {
    int n1 = s1.size(), n2 = s2.size();
    if (i == n1 && j == n2) return diff == 0;
    State cur{i, j, diff};
    if (memo.find(cur) != memo.end()) return false;

    // Process number token(s) in s1 (try all possible splits)
    if (i < n1 && std::isdigit(s1[i])) {
        long long val = 0;
        for (int ii = i; ii < n1 && std::isdigit(s1[ii]); ++ii) {
            val = val * 10 + (s1[ii] - '0');
            if (dfs(s1, s2, ii + 1, j, diff + (int)val, memo)) {
                return true;
            }
        }
    }

    // Process number token(s) in s2 (try all possible splits)
    if (j < n2 && std::isdigit(s2[j])) {
        long long val = 0;
        for (int jj = j; jj < n2 && std::isdigit(s2[jj]); ++jj) {
            val = val * 10 + (s2[jj] - '0');
            if (dfs(s1, s2, i, jj + 1, diff - (int)val, memo)) {
                return true;
            }
        }
    }

    // Consume letters according to diff
    if (diff > 0) {
        if (j < n2 && !std::isdigit(s2[j])) {
            if (dfs(s1, s2, i, j + 1, diff - 1, memo)) return true;
        }
    } else if (diff < 0) {
        if (i < n1 && !std::isdigit(s1[i])) {
            if (dfs(s1, s2, i + 1, j, diff + 1, memo)) return true;
        }
    } else { // diff == 0
        if (i < n1 && j < n2 && !std::isdigit(s1[i]) && !std::isdigit(s2[j]) && s1[i] == s2[j]) {
            if (dfs(s1, s2, i + 1, j + 1, 0, memo)) return true;
        }
    }

    memo.insert(cur);
    return false;
}

bool possiblyEquals(string s1, string s2) {
    unordered_set<State, StateHash> memo;
    return dfs(s1, s2, 0, 0, 0, memo);
}

