struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

std::vector<int> nodesBetweenCriticalPoints(ListNode* head) {
    int firstIdx = -1;
    int prevIdx = -1;
    int lastIdx = -1;
    int minDist = INT_MAX;

    ListNode* prev = nullptr;
    ListNode* curr = head;
    int idx = 0;

    while (curr != nullptr) {
        ListNode* next = curr->next;

        if (prev != nullptr && next != nullptr) {
            bool isMax = curr->val > prev->val && curr->val > next->val;
            bool isMin = curr->val < prev->val && curr->val < next->val;
            if (isMax || isMin) {
                if (firstIdx == -1) {
                    firstIdx = idx;
                } else {
                    minDist = std::min(minDist, idx - prevIdx);
                }
                prevIdx = idx;
                lastIdx = idx;
            }
        }

        prev = curr;
        curr = next;
        ++idx;
    }

    if (firstIdx == -1 || firstIdx == lastIdx) {
        return std::vector<int>{-1, -1};
    }

    int maxDist = lastIdx - firstIdx;
    return std::vector<int>{minDist, maxDist};
}

