int maxPathQuality(const std::vector<int>& values, const std::vector<std::vector<int>>& edges, int maxTime) {
    int n = static_cast<int>(values.size());
    std::vector<std::vector<std::pair<int, int>>> graph(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int t = e[2];
        graph[u].push_back({v, t});
        graph[v].push_back({u, t});
    }

    std::vector<bool> visited(n, false);
    int best = 0;

    std::function<void(int, int, int)> dfs = [&](int node, int timeLeft, int quality) {
        if (node == 0) {
            best = std::max(best, quality);
        }
        for (const auto& nxt : graph[node]) {
            int next = nxt.first;
            int cost = nxt.second;
            if (cost > timeLeft) continue;
            if (!visited[next]) {
                visited[next] = true;
                dfs(next, timeLeft - cost, quality + values[next]);
                visited[next] = false;
            } else {
                dfs(next, timeLeft - cost, quality);
            }
        }
    };

    visited[0] = true;
    dfs(0, maxTime, values[0]);
    return best;
}

