int minimumOperations(const std::vector<int>& nums, int start, int goal) {
    const int LIMIT = 1000;
    std::vector<bool> visited(LIMIT + 1, false);
    std::queue<std::pair<int, int>> q; // {current value, steps}
    q.emplace(start, 0);
    if (0 <= start && start <= LIMIT) {
        visited[start] = true;
    }

    while (!q.empty()) {
        auto frontPair = q.front();
        q.pop();
        int x = frontPair.first;
        int steps = frontPair.second;

        for (int v : nums) {
            int y = x + v;
            if (y == goal) return steps + 1;
            if (0 <= y && y <= LIMIT && !visited[y]) {
                visited[y] = true;
                q.emplace(y, steps + 1);
            }

            int z = x - v;
            if (z == goal) return steps + 1;
            if (0 <= z && z <= LIMIT && !visited[z]) {
                visited[z] = true;
                q.emplace(z, steps + 1);
            }
        }
    }
    return -1;
}

