int maxTaskAssign(const std::vector<int>& tasks, const std::vector<int>& workers, int pills, int strength) {
    std::vector<int> sortedTasks = tasks;
    std::vector<int> sortedWorkers = workers;
    std::sort(sortedTasks.begin(), sortedTasks.end());
    std::sort(sortedWorkers.begin(), sortedWorkers.end());

    int n = static_cast<int>(sortedTasks.size());
    int m = static_cast<int>(sortedWorkers.size());

    auto canAssign = [&](int k) -> bool {
        std::multiset<int> available(sortedWorkers.begin(), sortedWorkers.end());
        int remainingPills = pills;
        for (int i = k - 1; i >= 0; --i) {
            int task = sortedTasks[i];
            auto it = available.lower_bound(task);
            if (it != available.end()) {
                available.erase(it);
            } else if (remainingPills > 0) {
                int needed = task - strength;
                if (needed < 0) needed = 0;
                auto it2 = available.lower_bound(needed);
                if (it2 != available.end()) {
                    available.erase(it2);
                    --remainingPills;
                } else {
                    return false;
                }
            } else {
                return false;
            }
        }
        return true;
    };

    int low = 0;
    int high = std::min(n, m);
    while (low < high) {
        int mid = (low + high + 1) / 2;
        if (canAssign(mid)) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

