class RobotSimulation {
    int width, height;
    int x = 0, y = 0;
    int dirIdx = 0; // 0:East,1:North,2:West,3:South
    int dx[4] = {1, 0, -1, 0};
    int dy[4] = {0, 1, 0, -1};
public:
    RobotSimulation(int width, int height) : width(width), height(height) {}
    void move(int num) {
        for (int i = 0; i < num; i++) {
            int nx = x + dx[dirIdx];
            int ny = y + dy[dirIdx];
            if (nx < 0 || nx >= width || ny < 0 || ny >= height) {
                dirIdx = (dirIdx + 1) % 4;
                nx = x + dx[dirIdx];
                ny = y + dy[dirIdx];
            }
            x = nx;
            y = ny;
        }
    }
    std::vector<int> getPos() { return {x, y}; }
    std::string getDir() {
        static const std::string names[4] = {"East", "North", "West", "South"};
        return names[dirIdx];
    }
};

RobotSimulation robotSimulation(int width, int height) {
    return RobotSimulation(width, height);
}

