std::vector<int> mostBeautifulItem(std::vector<std::vector<int>>& items, const std::vector<int>& queries) {
    std::sort(items.begin(), items.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        return a[0] < b[0];
    });

    std::vector<int> prices;
    std::vector<int> prefBeauty;
    int maxBeauty = 0;

    for (const auto& pair : items) {
        int price = pair[0];
        int beauty = pair[1];
        if (beauty > maxBeauty) maxBeauty = beauty;
        prices.push_back(price);
        prefBeauty.push_back(maxBeauty);
    }

    auto upperBound = [](const std::vector<int>& arr, int target) -> std::size_t {
        std::size_t lo = 0, hi = arr.size();
        while (lo < hi) {
            std::size_t mid = (lo + hi) >> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    };

    std::vector<int> answers;
    answers.reserve(queries.size());

    for (int q : queries) {
        int idx = static_cast<int>(upperBound(prices, q)) - 1;
        answers.push_back(idx >= 0 ? prefBeauty[idx] : 0);
    }

    return answers;
}

