int minimizedMaximum(int n, const std::vector<int>& quantities) {
    int low = 1;
    int high = *std::max_element(quantities.begin(), quantities.end());
    while (low < high) {
        int mid = low + (high - low) / 2;
        long long required = 0;
        for (int q : quantities) {
            required += (q + mid - 1) / mid;
        }
        if (required <= n) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

