struct ListNode {
    int val;
    ListNode* next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode* next) : val(x), next(next) {}
};

ListNode* reverseEvenLengthGroups(ListNode* head) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* prevGroupTail = &dummy;
    ListNode* cur = head;
    int groupSize = 1;

    while (cur) {
        int count = 0;
        ListNode* lastNode = nullptr;
        ListNode* runner = cur;
        while (count < groupSize && runner) {
            lastNode = runner;
            runner = runner->next;
            ++count;
        }
        ListNode* nextGroupHead = runner;

        if (count % 2 == 0) {
            ListNode* prev = nextGroupHead;
            ListNode* node = cur;
            for (int i = 0; i < count; ++i) {
                ListNode* nxt = node->next;
                node->next = prev;
                prev = node;
                node = nxt;
            }
            prevGroupTail->next = prev;
            prevGroupTail = cur;
        } else {
            prevGroupTail = lastNode;
        }

        cur = nextGroupHead;
        ++groupSize;
    }

    return dummy.next;
}

