std::string decodeSlantedCipher(const std::string& encodedText, int rows) {
    std::size_t n = encodedText.size();
    int cols = static_cast<int>(n / rows);
    std::vector<std::vector<char>> matrix(rows, std::vector<char>(cols));
    std::size_t idx = 0;
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            matrix[i][j] = encodedText[idx++];
        }
    }
    std::vector<char> result;
    for (int d = 0; d < cols; ++d) {
        for (int i = 0; i < rows; ++i) {
            int j = i + d;
            if (j < cols) {
                result.push_back(matrix[i][j]);
            }
        }
    }
    while (!result.empty() && result.back() == ' ') {
        result.pop_back();
    }
    return std::string(result.begin(), result.end());
}

