long long wateringPlants(const std::vector<int>& plants, int capacity) {
    long long steps = 0;
    int position = -1;
    int water = capacity;
    for (size_t i = 0; i < plants.size(); ++i) {
        if (water < plants[i]) {
            steps += position + 1;
            position = -1;
            water = capacity;
        }
        steps += static_cast<long long>(i) - position;
        position = static_cast<int>(i);
        water -= plants[i];
    }
    return steps;
}

