#include <vector>
#include <functional>

std::vector<bool> processFriendRequests(int n, const std::vector<std::vector<int>>& restrictions, const std::vector<std::vector<int>>& requests) {
    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    std::function<int(int)> find = [&](int x) -> int {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    };

    auto unite = [&](int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]) parent[rx] = ry;
        else if (rank[rx] > rank[ry]) parent[ry] = rx;
        else { parent[ry] = rx; ++rank[rx]; }
    };

    std::vector<bool> answer;

    for (const auto& req : requests) {
        int u = req[0];
        int v = req[1];
        int ru = find(u);
        int rv = find(v);

        if (ru == rv) {
            answer.push_back(true);
            continue;
        }

        bool ok = true;
        for (const auto& restr : restrictions) {
            int x = restr[0];
            int y = restr[1];
            int rx = find(x);
            int ry = find(y);
            if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                ok = false;
                break;
            }
        }

        if (ok) {
            unite(ru, rv);
            answer.push_back(true);
        } else {
            answer.push_back(false);
        }
    }

    return answer;
}

