static bool isPalindromeBase(unsigned long long x, int k) {
    vector<int> d;
    while (x > 0) {
        d.push_back(x % k);
        x /= k;
    }
    int i = 0, j = (int)d.size() - 1;
    while (i < j) {
        if (d[i] != d[j]) return false;
        ++i;
        --j;
    }
    return true;
}

static unsigned long long makePalindrome(int left, bool odd) {
    string s = to_string(left);
    string rev = s;
    if (odd) rev.pop_back();
    reverse(rev.begin(), rev.end());
    string pal = s + rev;
    return stoull(pal);
}

static int pow10int(int e) {
    int r = 1;
    while (e--) r *= 10;
    return r;
}

long long sumOfKMirror(int k, int n) {
    long long sum = 0;
    int cnt = 0;
    for (int len = 1; ; ++len) {
        bool odd = (len % 2 == 1);
        int half = (len + 1) / 2;
        int start = (half == 1) ? 1 : pow10int(half - 1);
        int end = pow10int(half) - 1;
        for (int left = start; left <= end; ++left) {
            unsigned long long pal = makePalindrome(left, odd);
            if (isPalindromeBase(pal, k)) {
                sum += (long long)pal;
                ++cnt;
                if (cnt == n) return sum;
            }
        }
    }
    return sum;
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>

int maxDistanceDifferentColors(const std::vector<int>& colors) {
    std::size_t n = colors.size();
    if (n == 0) return 0;

    int leftColor = colors[0];
    int rightColor = colors[n - 1];

    if (leftColor != rightColor) return static_cast<int>(n - 1);

    int maxDist = 0;

    for (std::size_t i = 0; i < n; ++i) {
        if (colors[i] != rightColor) {
            maxDist = std::max(maxDist, static_cast<int>(n - 1 - i));
            break;
        }
    }

    for (std::size_t i = n; i-- > 0;) {
        if (colors[i] != leftColor) {
            maxDist = std::max(maxDist, static_cast<int>(i));
            break;
        }
    }

    return maxDist;
}

#include <bits/stdc++.h>
