#include <unordered_map>

struct RangeFreqQueryObj {
    std::unordered_map<int, std::vector<int>> positions;
    explicit RangeFreqQueryObj(std::unordered_map<int, std::vector<int>>&& pos) : positions(std::move(pos)) {}
    int lowerBound(const std::vector<int>& arr, int target) const {
        int lo = 0, hi = static_cast<int>(arr.size());
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
    int upperBound(const std::vector<int>& arr, int target) const {
        int lo = 0, hi = static_cast<int>(arr.size());
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
    int query(int left, int right, int value) const {
        auto it = positions.find(value);
        if (it == positions.end()) return 0;
        const std::vector<int>& list = it->second;
        int l = lowerBound(list, left);
        int r = upperBound(list, right);
        return r - l;
    }
};

RangeFreqQueryObj RangeFreqQuery(const std::vector<int>& nums) {
    std::unordered_map<int, std::vector<int>> pos;
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        int v = nums[i];
        pos[v].push_back(i);
    }
    return RangeFreqQueryObj(std::move(pos));
}

