int minimumBuckets(std::string hamsters) {
    int n = hamsters.size();
    std::vector<bool> bucket(n, false);
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        if (hamsters[i] != 'H') continue;
        bool fed = false;
        if (i > 0 && bucket[i - 1]) fed = true;
        if (i + 1 < n && bucket[i + 1]) fed = true;
        if (fed) continue;
        // try to place bucket on the right
        if (i + 1 < n && hamsters[i + 1] == '.') {
            bucket[i + 1] = true;
            ++ans;
        } else if (i - 1 >= 0 && hamsters[i - 1] == '.') {
            bucket[i - 1] = true;
            ++ans;
        } else {
            return -1;
        }
    }
    return ans;
}

#include <bits/stdc++.h>
long long countPyramids(const std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<int>> dp(m, std::vector<int>(n, 0));
    long long total = 0;
    // pyramids pointing up
    for (int i = m - 1; i >= 0; --i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 0) {
                dp[i][j] = 0;
            } else {
                if (i + 1 < m && j - 1 >= 0 && j + 1 < n) {
                    dp[i][j] = 1 + std::min({dp[i + 1][j - 1], dp[i + 1][j], dp[i + 1][j + 1]});
                } else {
                    dp[i][j] = 1;
                }
                if (dp[i][j] > 1) total += dp[i][j] - 1;
            }
        }
    }
    // pyramids pointing down (inverse)
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 0) {
                dp[i][j] = 0;
            } else {
                if (i - 1 >= 0 && j - 1 >= 0 && j + 1 < n) {
                    dp[i][j] = 1 + std::min({dp[i - 1][j - 1], dp[i - 1][j], dp[i - 1][j + 1]});
                } else {
                    dp[i][j] = 1;
                }
                if (dp[i][j] > 1) total += dp[i][j] - 1;
            }
        }
    }
    return total;
}

#include <bits/stdc++.h>
#include <vector>

std::vector<int> getAverages(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<int> result(n, -1);
    int windowSize = 2 * k + 1;
    if (windowSize > n) return result;
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        sum += nums[i];
        if (i >= windowSize) {
            sum -= nums[i - windowSize];
        }
        if (i >= windowSize - 1) {
            int center = i - k;
            result[center] = static_cast<int>(sum / windowSize);
        }
    }
    return result;
}

