int countWords(const std::vector<std::string>& words1, const std::vector<std::string>& words2) {
    std::unordered_map<std::string, int> freq1;
    for (const auto& w : words1) {
        ++freq1[w];
    }

    std::unordered_map<std::string, int> freq2;
    for (const auto& w : words2) {
        ++freq2[w];
    }

    int commonOnce = 0;
    for (const auto& kv : freq1) {
        if (kv.second == 1) {
            auto it = freq2.find(kv.first);
            if (it != freq2.end() && it->second == 1) {
                ++commonOnce;
            }
        }
    }
    return commonOnce;
}

