std::vector<int> findEvenNumbers(const std::vector<int>& digits) {
    std::unordered_map<int, int> freq;
    for (int d : digits) {
        ++freq[d];
    }

    std::unordered_set<int> results;

    std::function<void(int, int)> backtrack = [&](int pos, int current) {
        if (pos == 3) {
            int lastDigit = current % 10;
            if (lastDigit % 2 == 0) {
                results.insert(current);
            }
            return;
        }
        for (auto& kv : freq) {
            int digit = kv.first;
            if (kv.second == 0) continue;
            if (pos == 0 && digit == 0) continue;
            --kv.second;
            backtrack(pos + 1, current * 10 + digit);
            ++kv.second;
        }
    };

    backtrack(0, 0);
    std::vector<int> ans(results.begin(), results.end());
    std::sort(ans.begin(), ans.end());
    return ans;
}

