int minimumDeletions(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    int minIdx = 0, maxIdx = 0;
    for (int i = 1; i < n; ++i) {
        if (nums[i] < nums[minIdx]) minIdx = i;
        if (nums[i] > nums[maxIdx]) maxIdx = i;
    }
    int frontOnly = std::max(minIdx, maxIdx) + 1;
    int backOnly = std::max(n - minIdx, n - maxIdx);
    int frontThenBack = std::min(minIdx, maxIdx) + 1 + (n - std::max(minIdx, maxIdx));
    int backThenFront = frontThenBack;
    return std::min({frontOnly, backOnly, frontThenBack, backThenFront});
}

