long long minCost(const std::vector<int>& startPos, const std::vector<int>& homePos, const std::vector<int>& rowCosts, const std::vector<int>& colCosts) {
    int sr = startPos[0];
    int sc = startPos[1];
    int hr = homePos[0];
    int hc = homePos[1];
    long long total = 0;
    if (sr < hr) {
        for (int r = sr + 1; r <= hr; ++r) {
            total += rowCosts[r];
        }
    } else {
        for (int r = sr - 1; r >= hr; --r) {
            total += rowCosts[r];
        }
    }
    if (sc < hc) {
        for (int c = sc + 1; c <= hc; ++c) {
            total += colCosts[c];
        }
    } else {
        for (int c = sc - 1; c >= hc; --c) {
            total += colCosts[c];
        }
    }
    return total;
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>
#include <unordered_set>
#include <unordered_map>

std::vector<int> findAllPeople(int n, std::vector<std::vector<int>>& meetings, int firstPerson) {
    std::vector<bool> knows(n, false);
    knows[0] = true;
    knows[firstPerson] = true;

    std::sort(meetings.begin(), meetings.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[2] < b[2];
              });

    std::size_t i = 0;
    while (i < meetings.size()) {
        int curTime = meetings[i][2];
        std::vector<std::pair<int, int>> group;
        std::unordered_set<int> persons;

        while (i < meetings.size() && meetings[i][2] == curTime) {
            int x = meetings[i][0];
            int y = meetings[i][1];
            group.emplace_back(x, y);
            persons.insert(x);
            persons.insert(y);
            ++i;
        }

        std::unordered_map<int, std::vector<int>> adj;
        for (int p : persons) {
            adj[p] = std::vector<int>();
        }
        for (const auto& pr : group) {
            int x = pr.first;
            int y = pr.second;
            adj[x].push_back(y);
            adj[y].push_back(x);
        }

        std::unordered_set<int> visited;
        for (int start : persons) {
            if (visited.find(start) != visited.end()) continue;

            std::vector<int> stack;
            std::vector<int> component;
            bool hasSecret = false;
            visited.insert(start);
            stack.push_back(start);

            while (!stack.empty()) {
                int cur = stack.back();
                stack.pop_back();
                component.push_back(cur);
                if (knows[cur]) hasSecret = true;

                for (int nb : adj[cur]) {
                    if (visited.find(nb) == visited.end()) {
                        visited.insert(nb);
                        stack.push_back(nb);
                    }
                }
            }

            if (hasSecret) {
                for (int node : component) {
                    knows[node] = true;
                }
            }
        }
    }

    std::vector<int> result;
    for (int idx = 0; idx < n; ++idx) {
        if (knows[idx]) result.push_back(idx);
    }
    return result;
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>

std::vector<int> maxSubsequence(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<std::pair<int, int>> pairs;
    pairs.reserve(n);
    for (int i = 0; i < n; ++i) {
        pairs.emplace_back(nums[i], i);
    }
    std::sort(pairs.begin(), pairs.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            return a.first > b.first;
        });
    std::vector<std::pair<int, int>> selected(pairs.begin(), pairs.begin() + k);
    std::sort(selected.begin(), selected.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            return a.second < b.second;
        });
    std::vector<int> result;
    result.reserve(k);
    for (int i = 0; i < k; ++i) {
        result.push_back(selected[i].first);
    }
    return result;
}

#include <bits/stdc++.h>
#include <vector>

std::vector<int> findGoodDays(const std::vector<int>& security, int time) {
    int n = static_cast<int>(security.size());
    std::vector<int> left(n, 0);
    std::vector<int> right(n, 0);
    for (int i = 1; i < n; ++i) {
        if (security[i - 1] >= security[i]) {
            left[i] = left[i - 1] + 1;
        }
    }
    for (int i = n - 2; i >= 0; --i) {
        if (security[i] <= security[i + 1]) {
            right[i] = right[i + 1] + 1;
        }
    }
    std::vector<int> result;
    for (int i = time; i < n - time; ++i) {
        if (left[i] >= time && right[i] >= time) {
            result.push_back(i);
        }
    }
    return result;
}

#include <bits/stdc++.h>
#include <string>

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

bool dfsFind(TreeNode* node, int target, std::string& curPath, std::string& result) {
    if (!node) return false;
    if (node->val == target) {
        result = curPath;
        return true;
    }
    curPath.push_back('L');
    if (dfsFind(node->left, target, curPath, result)) {
        curPath.pop_back();
        return true;
    }
    curPath.back() = 'R';
    if (dfsFind(node->right, target, curPath, result)) {
        curPath.pop_back();
        return true;
    }
    curPath.pop_back();
    return false;
}

std::string getDirections(TreeNode* root, int startValue, int destValue) {
    std::string pathToStart, pathToDest, curPath;
    dfsFind(root, startValue, curPath, pathToStart);
    curPath.clear();
    dfsFind(root, destValue, curPath, pathToDest);

    size_t i = 0;
    while (i < pathToStart.size() && i < pathToDest.size() && pathToStart[i] == pathToDest[i]) {
        ++i;
    }

    std::string upMoves(pathToStart.size() - i, 'U');
    std::string downMoves = pathToDest.substr(i);
    return upMoves + downMoves;
}

#include <bits/stdc++.h>
std::vector<std::vector<int>> validArrangement(std::vector<std::vector<int>>& pairs) {
    using ll = long long;
    std::unordered_map<ll, std::vector<int>> adj;
    std::unordered_map<ll, int> outDeg, inDeg;
    int n = pairs.size();
    for (int i = 0; i < n; ++i) {
        ll u = pairs[i][0];
        ll v = pairs[i][1];
        adj[u].push_back(i);
        ++outDeg[u];
        ++inDeg[v];
    }
    ll start = pairs[0][0];
    for (const auto& kv : outDeg) {
        ll node = kv.first;
        int diff = outDeg[node] - inDeg[node];
        if (diff == 1) {
            start = node;
            break;
        }
    }
    struct Frame { ll node; int edgeIdx; };
    std::vector<Frame> st;
    st.push_back({start, -1});
    std::vector<int> revResult;
    while (!st.empty()) {
        ll v = st.back().node;
        auto& vec = adj[v];
        if (!vec.empty()) {
            int e = vec.back();
            vec.pop_back();
            ll to = pairs[e][1];
            st.push_back({to, e});
        } else {
            int e = st.back().edgeIdx;
            st.pop_back();
            if (e != -1) revResult.push_back(e);
        }
    }
    std::reverse(revResult.begin(), revResult.end());
    std::vector<std::vector<int>> ans;
    ans.reserve(n);
    for (int idx : revResult) ans.push_back(pairs[idx]);
    return ans;
}

#include <bits/stdc++.h>
#include <vector>
#include <stack>
#include <cstdint>

long long sumSubarrayRanges(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::vector<int> leftGreater(n), rightGreater(n);
    std::vector<int> leftSmaller(n), rightSmaller(n);
    std::stack<int> st;

    // previous greater (strict)
    while (!st.empty()) st.pop();
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[st.top()] <= nums[i]) st.pop();
        leftGreater[i] = i - (st.empty() ? -1 : st.top());
        st.push(i);
    }

    // next greater or equal
    while (!st.empty()) st.pop();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && nums[st.top()] < nums[i]) st.pop();
        rightGreater[i] = (st.empty() ? n : st.top()) - i;
        st.push(i);
    }

    // previous smaller (strict)
    while (!st.empty()) st.pop();
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[st.top()] >= nums[i]) st.pop();
        leftSmaller[i] = i - (st.empty() ? -1 : st.top());
        st.push(i);
    }

    // next smaller or equal
    while (!st.empty()) st.pop();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && nums[st.top()] > nums[i]) st.pop();
        rightSmaller[i] = (st.empty() ? n : st.top()) - i;
        st.push(i);
    }

    long long sumMax = 0, sumMin = 0;
    for (int i = 0; i < n; ++i) {
        sumMax += static_cast<long long>(nums[i]) * leftGreater[i] * rightGreater[i];
        sumMin += static_cast<long long>(nums[i]) * leftSmaller[i] * rightSmaller[i];
    }
    return sumMax - sumMin;
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>

int maxTotalFruits(std::vector<std::vector<int>>& fruits, int startPos, int k) {
    int n = static_cast<int>(fruits.size());
    int left = 0;
    long long curSum = 0;
    int answer = 0;

    auto feasible = [&](int L, int R) -> bool {
        long long leftDist = startPos > L ? static_cast<long long>(startPos - L) : 0LL;
        long long rightDist = R > startPos ? static_cast<long long>(R - startPos) : 0LL;
        long long minSteps = std::min(2 * leftDist + rightDist, 2 * rightDist + leftDist);
        return minSteps <= k;
    };

    for (int right = 0; right < n; ++right) {
        curSum += fruits[right][1];
        while (left <= right && !feasible(fruits[left][0], fruits[right][0])) {
            curSum -= fruits[left][1];
            ++left;
        }
        answer = std::max(answer, static_cast<int>(curSum));
    }
    return answer;
}

#include <bits/stdc++.h>
#include <vector>
#include <deque>

int maximumDetonation(const std::vector<std::vector<int>>& bombs) {
    int n = static_cast<int>(bombs.size());
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n; ++i) {
        int xi = bombs[i][0];
        int yi = bombs[i][1];
        int ri = bombs[i][2];
        long long ri2 = static_cast<long long>(ri) * ri;
        for (int j = 0; j < n; ++j) {
            if (i == j) continue;
            int xj = bombs[j][0];
            int yj = bombs[j][1];
            long long dx = static_cast<long long>(xi) - xj;
            long long dy = static_cast<long long>(yi) - yj;
            if (dx * dx + dy * dy <= ri2) {
                adj[i].push_back(j);
            }
        }
    }

    int best = 0;
    for (int start = 0; start < n; ++start) {
        std::vector<bool> visited(n, false);
        std::deque<int> queue;
        queue.push_back(start);
        visited[start] = true;
        int count = 0;
        while (!queue.empty()) {
            int cur = queue.front();
            queue.pop_front();
            ++count;
            for (int nxt : adj[cur]) {
                if (!visited[nxt]) {
                    visited[nxt] = true;
                    queue.push_back(nxt);
                }
            }
        }
        if (count > best) best = count;
    }

    return best;
}

#include <bits/stdc++.h>
#include <string>
#include <queue>
#include <vector>

struct Location {
    std::string name;
    int score;
    // "worse" ordering used so operator< makes the WORST item compare as "largest"
    // (std::priority_queue is a max-heap, so the "largest" per operator< sits on top)
    bool operator<(const Location& other) const {
        if (score != other.score) return score > other.score; // lower score = "worse" = larger
        return name < other.name; // alphabetically later = "worse" = larger
    }
};

struct BetterFirst {
    bool operator()(const Location& a, const Location& b) const {
        if (a.score != b.score) return a.score < b.score; // higher score = "better" = larger (max-heap wants better on top... )
        return a.name > b.name;
    }
};

class SORTracker {
    // best: holds the currently-revealed top-k, worst of those k on top (so it can be evicted)
    std::priority_queue<Location> best;
    // rest: holds everything else, BEST of the rest on top
    std::priority_queue<Location, std::vector<Location>, BetterFirst> rest;
    int k = 0;
public:
    SORTracker() {}
    void add(const std::string& name, int score) {
        Location item{name, score};
        best.push(item);
        if ((int)best.size() > k) {
            Location moved = best.top();
            best.pop();
            rest.push(moved);
        }
    }
    std::string get() {
        k++;
        if (!rest.empty()) {
            Location moved = rest.top();
            rest.pop();
            best.push(moved);
        }
        return best.top().name;
    }
};

