#include <vector>

int waterPlants(const std::vector<int>& plants, int capacityA, int capacityB) {
    int i = 0;
    int j = static_cast<int>(plants.size()) - 1;
    int waterA = capacityA;
    int waterB = capacityB;
    int refills = 0;

    while (i <= j) {
        if (i == j) {
            if (waterA >= waterB) {
                if (waterA < plants[i]) {
                    ++refills;
                    waterA = capacityA;
                }
                waterA -= plants[i];
            } else {
                if (waterB < plants[j]) {
                    ++refills;
                    waterB = capacityB;
                }
                waterB -= plants[j];
            }
            break;
        }

        if (waterA < plants[i]) {
            ++refills;
            waterA = capacityA;
        }
        waterA -= plants[i];

        if (waterB < plants[j]) {
            ++refills;
            waterB = capacityB;
        }
        waterB -= plants[j];

        ++i;
        --j;
    }

    return refills;
}

