int minOperations(const std::vector<int>& arr, int k) {
    int operations = 0;
    for (int offset = 0; offset < k; ++offset) {
        std::vector<int> subsequence;
        for (size_t i = offset; i < arr.size(); i += k) {
            subsequence.push_back(arr[i]);
        }
        std::vector<int> tails;
        for (int value : subsequence) {
            auto it = std::upper_bound(tails.begin(), tails.end(), value);
            if (it == tails.end()) {
                tails.push_back(value);
            } else {
                *it = value;
            }
        }
        operations += static_cast<int>(subsequence.size() - tails.size());
    }
    return operations;
}

