std::vector<std::string> findAllRecipes(const std::vector<std::string>& recipes, const std::vector<std::vector<std::string>>& ingredients, const std::vector<std::string>& supplies) {
    std::unordered_map<std::string, std::vector<std::string>> adj;
    std::unordered_map<std::string, int> indegree;
    for (size_t i = 0; i < recipes.size(); ++i) {
        indegree[recipes[i]] = static_cast<int>(ingredients[i].size());
        for (const std::string& ing : ingredients[i]) {
            adj[ing].push_back(recipes[i]);
        }
    }
    std::deque<std::string> queue;
    for (const std::string& s : supplies) {
        queue.push_back(s);
    }
    std::vector<std::string> result;
    while (!queue.empty()) {
        std::string cur = std::move(queue.front());
        queue.pop_front();
        auto it = adj.find(cur);
        if (it == adj.end()) continue;
        for (const std::string& rec : it->second) {
            indegree[rec]--;
            if (indegree[rec] == 0) {
                result.push_back(rec);
                queue.push_back(rec);
            }
        }
    }
    return result;
}

