bool canBeValid(const std::string& s, const std::string& locked) {
    int n = s.size();
    if (n % 2 == 1) return false;
    int low = 0, high = 0;
    for (int i = 0; i < n; ++i) {
        if (locked[i] == '1') {
            if (s[i] == '(') {
                ++low;
                ++high;
            } else {
                --low;
                --high;
            }
        } else {
            // unlocked: can be '(' or ')'
            --low;      // treat as ')'
            ++high;     // treat as '('
        }
        if (high < 0) return false;
        low = std::max(low, 0);
    }
    return low == 0;
}

