#include <bits/stdc++.h>

std::string abbreviateProduct(int left, int right) {
    long double sumLog = 0.0L;
    for (int i = left; i <= right; ++i) {
        sumLog += std::log10(static_cast<long double>(i));
    }
    long long trailingZeros = 0;
    {
        unsigned long long prod = 1;
        bool overflow = false;
        for (int i = left; i <= right; ++i) {
            if (prod > ULLONG_MAX / static_cast<unsigned long long>(i)) {
                overflow = true;
                break;
            }
            prod *= static_cast<unsigned long long>(i);
        }
        if (!overflow) {
            while (prod % 10ULL == 0ULL) {
                prod /= 10ULL;
                ++trailingZeros;
            }
            std::string s = std::to_string(prod);
            return s + "e" + std::to_string(trailingZeros);
        }
    }
    long long cnt2 = 0, cnt5 = 0;
    const long long MOD = 1000000000000LL; // 1e12
    long long cur = 1;
    for (int i = left; i <= right; ++i) {
        int x = i;
        while ((x & 1) == 0) { x >>= 1; ++cnt2; }
        while (x % 5 == 0) { x /= 5; ++cnt5; }
        cur = (cur * (x % MOD)) % MOD;
    }
    long long diff = cnt2 - cnt5;
    if (diff > 0) {
        for (long long k = 0; k < diff; ++k) cur = (cur * 2) % MOD;
    } else if (diff < 0) {
        for (long long k = 0; k < -diff; ++k) cur = (cur * 5) % MOD;
    }
    trailingZeros = std::min(cnt2, cnt5);
    sumLog -= static_cast<long double>(trailingZeros);
    long long totalDigits = static_cast<long long>(std::floor(sumLog)) + 1;
    long double frac = sumLog - std::floor(sumLog);
    long double leadingVal = std::pow(10.0L, frac + 4);
    int first5 = static_cast<int>(leadingVal);
    long long last5 = cur % 100000LL;
    std::string firstStr = std::to_string(first5);
    std::string lastStr = std::to_string(last5);
    while (lastStr.size() < 5) lastStr = "0" + lastStr;
    if (totalDigits <= 10) {
        // fallback: compute exact value using big integer via string multiplication
        std::string exact = "1";
        for (int i = left; i <= right; ++i) {
            int carry = 0;
            for (int pos = static_cast<int>(exact.size()) - 1; pos >= 0; --pos) {
                int digit = (exact[pos] - '0') * i + carry;
                exact[pos] = static_cast<char>('0' + digit % 10);
                carry = digit / 10;
            }
            while (carry) {
                exact.insert(exact.begin(), static_cast<char>('0' + carry % 10));
                carry /= 10;
            }
        }
        while (!exact.empty() && exact.back() == '0') {
            exact.pop_back();
            ++trailingZeros;
        }
        return exact + "e" + std::to_string(trailingZeros);
    }
    return firstStr + "..." + lastStr + "e" + std::to_string(trailingZeros);
}

