static long long reverseNumber(long long n) {
    bool negative = n < 0;
    unsigned long long x = negative ? -static_cast<unsigned long long>(n) : static_cast<unsigned long long>(n);
    unsigned long long rev = 0;
    while (x > 0) {
        rev = rev * 10 + (x % 10);
        x /= 10;
    }
    return negative ? -static_cast<long long>(rev) : static_cast<long long>(rev);
}

bool isDoubleReversalEqual(long long num) {
    long long firstReverse = reverseNumber(num);
    long long secondReverse = reverseNumber(firstReverse);
    return secondReverse == num;
}

