std::vector<long long> sumIntervals(const std::vector<int>& arr) {
    size_t n = arr.size();
    std::vector<long long> answer(n, 0);
    std::unordered_map<int, std::vector<size_t>> groups;
    for (size_t i = 0; i < n; ++i) {
        int val = arr[i];
        groups[val].push_back(i);
    }
    for (auto& pair : groups) {
        const std::vector<size_t>& indices = pair.second;
        size_t k = indices.size();
        if (k == 1) continue;
        std::vector<long long> prefix(k);
        prefix[0] = static_cast<long long>(indices[0]);
        for (size_t i = 1; i < k; ++i) {
            prefix[i] = prefix[i - 1] + static_cast<long long>(indices[i]);
        }
        long long total = prefix[k - 1];
        for (size_t i = 0; i < k; ++i) {
            size_t idx = indices[i];
            long long leftCount = static_cast<long long>(i);
            long long rightCount = static_cast<long long>(k - 1 - i);
            long long leftSum = i > 0 ? prefix[i - 1] : 0;
            long long rightSum = total - prefix[i];
            answer[idx] = static_cast<long long>(idx) * leftCount - leftSum + rightSum - static_cast<long long>(idx) * rightCount;
        }
    }
    return answer;
}

#include <bits/stdc++.h>
std::vector<int> recoverArray(std::vector<int> nums) {
    std::sort(nums.begin(), nums.end());
    int m = nums.size();
    int n = m / 2;
    for (int i = 1; i < m; ++i) {
        long long diff = (long long)nums[i] - nums[0];
        if (diff <= 0 || diff % 2 != 0) continue;
        long long k = diff / 2;
        if (k == 0) continue;
        std::unordered_map<long long, int> freq;
        freq.reserve(m * 2);
        for (int v : nums) ++freq[v];
        std::vector<int> arr;
        bool ok = true;
        for (int v : nums) {
            if (freq[v] == 0) continue;
            long long partner = v + 2 * k;
            if (freq[partner] == 0) { ok = false; break; }
            --freq[v];
            --freq[partner];
            long long original = v + k;
            arr.push_back(static_cast<int>(original));
        }
        if (ok && (int)arr.size() == n) return arr;
    }
    return {};
}

