struct ListNode {
    int val;
    ListNode* next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode* nxt) : val(x), next(nxt) {}
};

int maxTwinSum(ListNode* head) {
    if (!head) return 0;

    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        fast = fast->next->next;
        slow = slow->next;
    }

    ListNode* prev = nullptr;
    ListNode* curr = slow;
    while (curr) {
        ListNode* nxt = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nxt;
    }

    int maxSum = 0;
    ListNode* p1 = head;
    ListNode* p2 = prev;
    while (p2) {
        int sum = p1->val + p2->val;
        if (sum > maxSum) maxSum = sum;
        p1 = p1->next;
        p2 = p2->next;
    }

    curr = prev;
    prev = nullptr;
    while (curr) {
        ListNode* nxt = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nxt;
    }

    return maxSum;
}

