std::string capitalizeTitle(const std::string& title) {
    std::vector<std::string> words;
    size_t start = 0;
    while (true) {
        size_t pos = title.find(' ', start);
        if (pos == std::string::npos) {
            words.push_back(title.substr(start));
            break;
        } else {
            words.push_back(title.substr(start, pos - start));
            start = pos + 1;
        }
    }
    for (auto& word : words) {
        if (word.size() < 3) {
            for (char& c : word) {
                c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
            }
        } else {
            if (!word.empty()) {
                word[0] = static_cast<char>(std::toupper(static_cast<unsigned char>(word[0])));
            }
            for (size_t i = 1; i < word.size(); ++i) {
                word[i] = static_cast<char>(std::tolower(static_cast<unsigned char>(word[i])));
            }
        }
    }
    std::string result;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i) result.push_back(' ');
        result += words[i];
    }
    return result;
}

#include <bits/stdc++.h>

int maximumInvitations(std::vector<int>& favorite) {
    int n = static_cast<int>(favorite.size());
    std::vector<std::vector<int>> rev(n);
    for (int i = 0; i < n; ++i) {
        rev[favorite[i]].push_back(i);
    }

    std::vector<int> visited(n, 0);
    std::vector<int> idx(n, -1);
    std::vector<int> inCycle(n, 0);
    int maxCycle = 0;

    for (int i = 0; i < n; ++i) {
        if (visited[i]) continue;
        int cur = i;
        std::vector<int> path;
        while (!visited[cur]) {
            visited[cur] = 1;
            idx[cur] = static_cast<int>(path.size());
            path.push_back(cur);
            cur = favorite[cur];
        }
        if (idx[cur] != -1) {
            int cycle_len = static_cast<int>(path.size()) - idx[cur];
            maxCycle = std::max(maxCycle, cycle_len);
            for (int k = idx[cur]; k < (int)path.size(); ++k) {
                inCycle[path[k]] = 1;
            }
        }
        for (int node : path) idx[node] = -1;
    }

    std::vector<int> memo(n, -1);
    std::function<int(int)> dfs = [&](int u) -> int {
        if (memo[u] != -1) return memo[u];
        int best = 0;
        for (int v : rev[u]) {
            if (inCycle[v]) continue;
            best = std::max(best, 1 + dfs(v));
        }
        memo[u] = best;
        return best;
    };

    long long pairSum = 0;
    for (int i = 0; i < n; ++i) {
        int j = favorite[i];
        if (i < j && favorite[j] == i) {
            int chain_i = dfs(i);
            int chain_j = dfs(j);
            pairSum += 2 + chain_i + chain_j;
        }
    }

    return std::max(maxCycle, static_cast<int>(pairSum));
}

