#include <bits/stdc++.h>
#include <vector>

int minSwaps(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    int totalOnes = 0;
    for (int i = 0; i < n; ++i) totalOnes += nums[i];
    if (totalOnes <= 1) return 0;
    int windowOnes = 0;
    for (int i = 0; i < totalOnes; ++i) windowOnes += nums[i];
    int minZeros = totalOnes - windowOnes;
    for (int start = 1; start < n; ++start) {
        windowOnes -= nums[start - 1];
        int enteringIdx = (start + totalOnes - 1) % n;
        windowOnes += nums[enteringIdx];
        int zeros = totalOnes - windowOnes;
        if (zeros < minZeros) minZeros = zeros;
    }
    return minZeros;
}

#include <bits/stdc++.h>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

int longestPalindrome(const std::vector<std::string>& words) {
    std::unordered_map<std::string, int> freq;
    for (const auto& w : words) {
        ++freq[w];
    }

    int length = 0;
    bool hasCenter = false;

    for (auto& kv : freq) {
        const std::string& word = kv.first;
        int cnt = kv.second;
        if (cnt == 0) continue;

        std::string rev;
        rev.push_back(word[1]);
        rev.push_back(word[0]);

        if (word == rev) {
            int pairs = cnt / 2;
            length += pairs * 4;
            if (cnt % 2 == 1) hasCenter = true;
        } else {
            int revCnt = 0;
            auto it = freq.find(rev);
            if (it != freq.end()) revCnt = it->second;
            int pairCnt = std::min(cnt, revCnt);
            length += pairCnt * 4;
            kv.second = cnt - pairCnt;
            if (it != freq.end()) it->second = revCnt - pairCnt;
        }
    }

    if (hasCenter) length += 2;
    return length;
}

