long long earliestFullBloom(const std::vector<int>& plantTime, const std::vector<int>& growTime) {
    std::size_t n = plantTime.size();
    std::vector<std::pair<int, int>> seeds;
    seeds.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        seeds.emplace_back(plantTime[i], growTime[i]);
    }
    std::sort(seeds.begin(), seeds.end(),
        [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            return a.second > b.second;
        });
    long long currentDay = 0;
    long long earliestAllBloom = 0;
    for (const auto& seed : seeds) {
        currentDay += seed.first;
        earliestAllBloom = std::max(earliestAllBloom, currentDay + seed.second);
    }
    return earliestAllBloom;
}

#include <bits/stdc++.h>
#include <vector>

bool possibleToStamp(const std::vector<std::vector<int>>& grid, int stampHeight, int stampWidth) {
    int m = static_cast<int>(grid.size());
    if (m == 0) return true;
    int n = static_cast<int>(grid[0].size());

    // Prefix sum of original grid (count of ones)
    std::vector<std::vector<int>> pref(m + 1, std::vector<int>(n + 1, 0));
    for (int i = 0; i < m; ++i) {
        int rowSum = 0;
        for (int j = 0; j < n; ++j) {
            rowSum += grid[i][j];
            pref[i + 1][j + 1] = pref[i][j + 1] + rowSum;
        }
    }

    // Difference array for coverage of stamps
    std::vector<std::vector<int>> diff(m + 1, std::vector<int>(n + 1, 0));

    for (int i = 0; i + stampHeight <= m; ++i) {
        for (int j = 0; j + stampWidth <= n; ++j) {
            int i2 = i + stampHeight;
            int j2 = j + stampWidth;
            int ones = pref[i2][j2] - pref[i][j2] - pref[i2][j] + pref[i][j];
            if (ones == 0) {
                diff[i][j] += 1;
                diff[i2][j] -= 1;
                diff[i][j2] -= 1;
                diff[i2][j2] += 1;
            }
        }
    }

    // Build coverage from diff
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i > 0) diff[i][j] += diff[i - 1][j];
            if (j > 0) diff[i][j] += diff[i][j - 1];
            if (i > 0 && j > 0) diff[i][j] -= diff[i - 1][j - 1];
        }
    }

    // Verify every zero cell is covered
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 0 && diff[i][j] == 0) {
                return false;
            }
        }
    }
    return true;
}

