std::vector<std::string> divideString(const std::string& s, int k, const std::string& fill) {
    std::vector<std::string> groups;
    for (std::size_t i = 0; i < s.size(); i += static_cast<std::size_t>(k)) {
        std::string chunk = s.substr(i, static_cast<std::size_t>(k));
        if (chunk.size() < static_cast<std::size_t>(k)) {
            std::size_t needed = static_cast<std::size_t>(k) - chunk.size();
