int maxPoints(const std::vector<std::vector<int>>& questions) {
    int n = static_cast<int>(questions.size());
    std::vector<int> dp(n + 1, 0);
    for (int i = n - 1; i >= 0; --i) {
        int points = questions[i][0];
        int brain = questions[i][1];
        int take = points + ((i + brain + 1 <= n) ? dp[i + brain + 1] : 0);
        int skip = dp[i + 1];
        dp[i] = std::max(take, skip);
    }
    return dp[0];
}

