long long maxRunTime(int n, const std::vector<long long>& batteries) {
    if (batteries.size() < static_cast<std::size_t>(n)) return 0;
    long long total = std::accumulate(batteries.begin(), batteries.end(), 0LL);
    long long low = 0;
    long long high = total / n;
    while (low < high) {
        long long mid = (low + high + 1) / 2;
        long long possible = 0;
        for (std::size_t i = 0; i < batteries.size(); ++i) {
            possible += std::min(batteries[i], mid);
        }
        if (possible >= static_cast<long long>(n) * mid) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

