long long numberOfWays(const std::string& corridor) {
    const long long MOD = 1000000007LL;
    std::vector<int> seatPos;
    for (int i = 0; i < (int)corridor.size(); ++i) {
        if (corridor[i] == 'S') seatPos.push_back(i);
    }
    int m = seatPos.size();
    if (m == 0 || (m & 1)) return 0;
    long long ans = 1;
    for (int i = 1; i < m / 2; ++i) {
        int left = seatPos[2 * i - 1];
        int right = seatPos[2 * i];
        long long ways = (right - left);
        ans = (ans * ways) % MOD;
    }
    return ans;
}

