std::vector<std::vector<int>> highestRankedKItems(std::vector<std::vector<int>>& grid, std::vector<int>& pricing, std::vector<int>& start, int k) {
    int low = pricing[0];
    int high = pricing[1];
    int sr = start[0];
    int sc = start[1];
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());

    std::vector<std::vector<int>> visited(m, std::vector<int>(n, 0));
    std::queue<std::tuple<int, int, int>> q;
    q.emplace(sr, sc, 0);
    visited[sr][sc] = 1;

    std::vector<std::array<int, 4>> candidates;
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    while (!q.empty()) {
        auto tup = q.front();
        q.pop();
        int r = std::get<0>(tup);
        int c = std::get<1>(tup);
        int d = std::get<2>(tup);

        int price = grid[r][c];
        if (price >= low && price <= high) {
            candidates.push_back({d, price, r, c});
        }

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] > 0) {
                visited[nr][nc] = 1;
                q.emplace(nr, nc, d + 1);
            }
        }
    }

    std::sort(candidates.begin(), candidates.end(),
              [](const std::array<int, 4>& a, const std::array<int, 4>& b) {
                  if (a[0] != b[0]) return a[0] < b[0];
                  if (a[1] != b[1]) return a[1] < b[1];
                  if (a[2] != b[2]) return a[2] < b[2];
                  return a[3] < b[3];
              });

    std::vector<std::vector<int>> result;
    int limit = std::min(k, static_cast<int>(candidates.size()));
    for (int i = 0; i < limit; ++i) {
        result.push_back({candidates[i][2], candidates[i][3]});
    }
    return result;
}

