std::string subStrHash(const std::string& s, int power, int modulo, int k, int hashValue) {
    int n = static_cast<int>(s.size());
    long long mod = static_cast<long long>(modulo);
    long long pw = static_cast<long long>(power);
    long long power_k = 1;
    for (int i = 0; i < k; ++i) {
        power_k = (power_k * pw) % mod;
    }

    long long cur = 0;
    long long mult = 1;
    for (int i = n - k; i < n; ++i) {
        cur = (cur + (static_cast<long long>(s[i] - 'a' + 1) * mult) ) % mod;
        mult = (mult * pw) % mod;
    }

    std::string answer;
    if (cur == hashValue) {
        answer = s.substr(n - k, k);
    }

    for (int i = n - k - 1; i >= 0; --i) {
        long long leftChar = static_cast<long long>(s[i] - 'a' + 1);
        long long rightChar = static_cast<long long>(s[i + k] - 'a' + 1);
        cur = (leftChar + pw * cur - rightChar * power_k) % mod;
        if (cur < 0) cur += mod;
        if (cur == hashValue) {
            answer = s.substr(i, k);
        }
    }
    return answer;
}

