int maximumGood(const std::vector<std::vector<int>>& statements) {
    int n = static_cast<int>(statements.size());
    int best = 0;
    int totalMasks = 1 << n;
    for (int mask = 0; mask < totalMasks; ++mask) {
        int goodCount = __builtin_popcount(mask);
        if (goodCount <= best) continue;
        bool ok = true;
        for (int i = 0; i < n && ok; ++i) {
            if (mask & (1 << i)) {
                for (int j = 0; j < n; ++j) {
                    int stmt = statements[i][j];
                    if (stmt == 2) continue;
                    bool jIsGood = (mask & (1 << j)) != 0;
                    if (stmt == 1 && !jIsGood) { ok = false; break; }
                    if (stmt == 0 && jIsGood) { ok = false; break; }
                }
            }
        }
        if (ok) best = goodCount;
    }
    return best;
}

