struct DSU {
    vector<int> parent, sz;
    DSU(int n) : parent(n), sz(n, 1) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
    }
};

vector<int> groupStrings(vector<string>& words) {
    int n = words.size();
    vector<int> masks(n);
    unordered_map<int, int> idx;
    idx.reserve(n * 2);
    for (int i = 0; i < n; ++i) {
        int m = 0;
        for (char c : words[i]) m |= 1 << (c - 'a');
        masks[i] = m;
        idx[m] = i;
    }
    DSU dsu(n);
    for (int i = 0; i < n; ++i) {
        int m = masks[i];
        // add or delete a single letter
        for (int b = 0; b < 26; ++b) {
            int nb;
            if (m & (1 << b)) {
                nb = m ^ (1 << b);               // delete
            } else {
                nb = m | (1 << b);               // add
            }
            auto it = idx.find(nb);
            if (it != idx.end()) dsu.unite(i, it->second);
        }
        // replace one letter by another
        for (int a = 0; a < 26; ++a) if (m & (1 << a)) {
            for (int b = 0; b < 26; ++b) if ((m & (1 << b)) == 0) {
                int nb = (m ^ (1 << a)) | (1 << b);
                auto it = idx.find(nb);
                if (it != idx.end()) dsu.unite(i, it->second);
            }
        }
    }
    vector<int> compCount(n, 0);
    int groups = 0, maxSize = 0;
    for (int i = 0; i < n; ++i) {
        int r = dsu.find(i);
        ++compCount[r];
    }
    for (int i = 0; i < n; ++i) {
        if (compCount[i] > 0) {
            ++groups;
            if (compCount[i] > maxSize) maxSize = compCount[i];
        }
    }
    return {groups, maxSize};
}

