std::vector<int> maxScoreDivisions(const std::vector<int>& nums) {
    std::size_t n = nums.size();
    int totalOnes = 0;
    for (int v : nums) totalOnes += v;

    int zerosLeft = 0;
    int onesSeen = 0;
    int maxScore = -1;
    std::vector<int> result;

    for (std::size_t i = 0; i <= n; ++i) {
        int onesRight = totalOnes - onesSeen;
        int score = zerosLeft + onesRight;

        if (score > maxScore) {
            maxScore = score;
            result.clear();
            result.push_back(static_cast<int>(i));
        } else if (score == maxScore) {
            result.push_back(static_cast<int>(i));
        }

        if (i < n) {
            if (nums[i] == 0) ++zerosLeft;
            else ++onesSeen;
        }
    }
    return result;
}

