int minCostSetTime(int startAt, int moveCost, int pushCost, int targetSeconds) {
    const int INF = 1e9;
    int best = INF;
    for (int minutes = 0; minutes <= 99; ++minutes) {
        int seconds = targetSeconds - minutes * 60;
        if (seconds < 0 || seconds > 99) continue;
        int m1 = minutes / 10;
        int m2 = minutes % 10;
        int s1 = seconds / 10;
        int s2 = seconds % 10;
        std::string code;
        code.push_back('0' + m1);
        code.push_back('0' + m2);
        code.push_back('0' + s1);
        code.push_back('0' + s2);
        int leadingZeros = 0;
        while (leadingZeros < 4 && code[leadingZeros] == '0') ++leadingZeros;
        for (int drop = 0; drop <= leadingZeros; ++drop) {
            std::string typed = code.substr(drop);
            if (typed.empty()) continue;
            int cur = startAt;
            int cost = 0;
            for (char ch : typed) {
                int d = ch - '0';
                if (cur != d) {
                    cost += moveCost;
                    cur = d;
                }
                cost += pushCost;
            }
            best = std::min(best, cost);
        }
    }
    return best;
}

#include <bits/stdc++.h>

long long minimumDifference(std::vector<int>& nums) {
    int m = static_cast<int>(nums.size());
    int n = m / 3;
    std::vector<long long> left(m, 0), right(m, 0);
    std::priority_queue<int> maxHeap;
    long long sum = 0;
    for (int i = 0; i < m; ++i) {
        sum += nums[i];
        maxHeap.push(nums[i]);
        if (static_cast<int>(maxHeap.size()) > n) {
            sum -= maxHeap.top();
            maxHeap.pop();
        }
        if (static_cast<int>(maxHeap.size()) == n) {
            left[i] = sum;
        }
    }
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;
    sum = 0;
    for (int i = m - 1; i >= 0; --i) {
        sum += nums[i];
        minHeap.push(nums[i]);
        if (static_cast<int>(minHeap.size()) > n) {
            sum -= minHeap.top();
            minHeap.pop();
        }
        if (static_cast<int>(minHeap.size()) == n) {
            right[i] = sum;
        }
    }
    long long ans = LLONG_MAX;
    for (int i = n - 1; i <= 2 * n - 1; ++i) {
        long long diff = left[i] - right[i + 1];
        if (diff < ans) ans = diff;
    }
    return ans;
}

