long long smallestRearrangedNumber(long long num) {
    if (num == 0) return 0;
    long long sign = (num > 0) - (num < 0);
    std::string s = std::to_string(std::llabs(num));
    std::vector<char> digits(s.begin(), s.end());
    if (sign >= 0) {
        std::sort(digits.begin(), digits.end(), [](char a, char b) { return a < b; });
        if (!digits.empty() && digits[0] == '0') {
            auto it = std::find_if(digits.begin(), digits.end(), [](char d) { return d != '0'; });
            if (it != digits.end()) {
                std::swap(digits[0], *it);
            }
        }
        std::string result(digits.begin(), digits.end());
        return std::stoll(result);
    } else {
        std::sort(digits.begin(), digits.end(), [](char a, char b) { return a > b; });
        std::string result(digits.begin(), digits.end());
        std::string neg = "-" + result;
        return std::stoll(neg);
    }
}

