struct BitsetObj {
    std::vector<std::uint8_t> bits;
    bool flipped;
    int onesCount;
    int size;
    BitsetObj(int n) : bits(n, 0), flipped(false), onesCount(0), size(n) {}
    void fix(int idx) {
        if ((bits[idx] ^ (flipped ? 1 : 0)) == 0) {
            bits[idx] = flipped ? 0 : 1;
            ++onesCount;
        }
    }
    void unfix(int idx) {
        if ((bits[idx] ^ (flipped ? 1 : 0)) == 1) {
            bits[idx] = flipped ? 1 : 0;
            --onesCount;
        }
    }
    void flip() {
        flipped = !flipped;
        onesCount = size - onesCount;
    }
    int all() const {
        return onesCount == size ? 1 : 0;
    }
    int one() const {
        return onesCount > 0 ? 1 : 0;
    }
    int count() const {
        return onesCount;
    }
    std::string toString() const {
        std::string result;
        result.reserve(size);
        for (int i = 0; i < size; ++i) {
            result.push_back('0' + (bits[i] ^ (flipped ? 1 : 0)));
        }
        return result;
    }
};

