int minOperations(std::vector<int>& nums) {
    int n = nums.size();
    std::unordered_map<int, int> evenCount, oddCount;
    for (int i = 0; i < n; ++i) {
        if (i % 2 == 0) ++evenCount[nums[i]];
        else ++oddCount[nums[i]];
    }

    // Find top two frequencies for even positions
    int evenTopVal = -1, evenTopFreq = 0;
    int evenSecondFreq = 0;
    for (const auto& p : evenCount) {
        if (p.second > evenTopFreq) {
            evenSecondFreq = evenTopFreq;
            evenTopFreq = p.second;
            evenTopVal = p.first;
        } else if (p.second > evenSecondFreq) {
            evenSecondFreq = p.second;
        }
    }

    // Find top two frequencies for odd positions
    int oddTopVal = -1, oddTopFreq = 0;
    int oddSecondFreq = 0;
    for (const auto& p : oddCount) {
        if (p.second > oddTopFreq) {
            oddSecondFreq = oddTopFreq;
            oddTopFreq = p.second;
            oddTopVal = p.first;
        } else if (p.second > oddSecondFreq) {
            oddSecondFreq = p.second;
        }
    }

    if (evenTopVal != oddTopVal) {
        return n - (evenTopFreq + oddTopFreq);
    } else {
        int keep1 = evenTopFreq + oddSecondFreq;   // keep even top, odd second
        int keep2 = evenSecondFreq + oddTopFreq;   // keep odd top, even second
        int maxKeep = std::max(keep1, keep2);
        return n - maxKeep;
    }
}

