#include <bits/stdc++.h>
int maximumANDSum(std::vector<int>& nums, int numSlots) {
    int n = nums.size();
    int totalPos = 2 * numSlots;
    int maxMask = 1 << totalPos;
    const int NEG_INF = -1e9;
    std::vector<int> dp(maxMask, NEG_INF);
    dp[0] = 0;
    int answer = 0;
    for (int mask = 0; mask < maxMask; ++mask) {
        int used = __builtin_popcount(mask);
        if (used > n) continue;
        if (dp[mask] == NEG_INF) continue;
        if (used == n) {
            answer = std::max(answer, dp[mask]);
            continue;
        }
        int val = nums[used];
        for (int pos = 0; pos < totalPos; ++pos) {
            if (!(mask & (1 << pos))) {
                int slot = pos / 2 + 1;
                int newMask = mask | (1 << pos);
                dp[newMask] = std::max(dp[newMask], dp[mask] + (val & slot));
            }
        }
    }
    return answer;
}

