ListNode* mergeNodes(ListNode* head) {
    ListNode dummy(0);
    ListNode* tail = &dummy;
    ListNode* current = head ? head->next : nullptr;
    int segmentSum = 0;
    while (current) {
        if (current->val == 0) {
            tail->next = new ListNode(segmentSum);
            tail = tail->next;
            segmentSum = 0;
        } else {
            segmentSum += current->val;
        }
        current = current->next;
    }
    return dummy.next;
}

