class FenwickTree {
public:
    FenwickTree(std::size_t n) : bit(n + 1, 0) {}

    void add(std::size_t idx, int val) {
        for (++idx; idx < bit.size(); idx += idx & -idx) {
            bit[idx] += val;
        }
    }

    int sum(std::size_t idx) const {
        int res = 0;
        for (++idx; idx > 0; idx -= idx & -idx) {
            res += bit[idx];
        }
        return res;
    }

private:
    std::vector<int> bit;
};

long long countGoodTriplets(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::size_t n = nums1.size();
    std::vector<std::size_t> posIn2(n);
    for (std::size_t i = 0; i < n; ++i) {
        posIn2[static_cast<std::size_t>(nums2[i])] = i;
    }

    std::vector<std::size_t> p(n);
    for (std::size_t i = 0; i < n; ++i) {
        p[i] = posIn2[static_cast<std::size_t>(nums1[i])];
    }

    std::vector<long long> leftLess(n), rightGreater(n);
    FenwickTree ftLeft(n);
    for (std::size_t i = 0; i < n; ++i) {
        leftLess[i] = ftLeft.sum(p[i] - 1);
        ftLeft.add(p[i], 1);
    }

    FenwickTree ftRight(n);
    long long seen = 0;
    for (std::size_t i = n; i-- > 0;) {
        long long smallerOrEqual = ftRight.sum(p[i]);
        rightGreater[i] = seen - smallerOrEqual;
        ftRight.add(p[i], 1);
        ++seen;
    }

    long long answer = 0;
    for (std::size_t i = 0; i < n; ++i) {
        answer += leftLess[i] * rightGreater[i];
    }
    return answer;
}

