std::vector<int> sortJumbled(const std::vector<int>& mapping, const std::vector<int>& nums) {
    struct Item {
        int orig;
        int mapped;
        int idx;
    };
    std::vector<Item> items;
    items.reserve(nums.size());
    for (size_t i = 0; i < nums.size(); ++i) {
        int num = nums[i];
        std::string s = std::to_string(num);
        std::string mappedStr;
        mappedStr.reserve(s.size());
        for (char ch : s) {
            int digit = ch - '0';
            int mappedDigit = mapping[digit];
            mappedStr.push_back('0' + mappedDigit);
        }
        int mappedVal = std::stoi(mappedStr);
        items.push_back({num, mappedVal, static_cast<int>(i)});
    }
    std::sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
        if (a.mapped != b.mapped) return a.mapped < b.mapped;
        return a.idx < b.idx;
    });
    std::vector<int> result;
    result.reserve(items.size());
    for (const auto& item : items) {
        result.push_back(item.orig);
    }
    return result;
}

