std::vector<std::vector<int>> getAncestors(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    std::vector<int> indeg(n, 0);
    for (const auto& e : edges) {
        int from = e[0];
        int to = e[1];
        adj[from].push_back(to);
        ++indeg[to];
    }

    std::vector<std::unordered_set<int>> ancestors(n);
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) q.push(i);
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v : adj[u]) {
            ancestors[v].insert(u);
            for (int anc : ancestors[u]) {
                ancestors[v].insert(anc);
            }
            if (--indeg[v] == 0) q.push(v);
        }
    }

    std::vector<std::vector<int>> result(n);
    for (int i = 0; i < n; ++i) {
        result[i].assign(ancestors[i].begin(), ancestors[i].end());
        std::sort(result[i].begin(), result[i].end());
    }
    return result;
}

