long long minimumTime(const std::vector<int>& time, long long totalTrips) {
    long long left = 1;
    long long right = static_cast<long long>(*std::min_element(time.begin(), time.end())) * totalTrips;
    while (left < right) {
        long long mid = (left + right) / 2;
        long long trips = 0;
        for (int t : time) {
            trips += mid / t;
            if (trips >= totalTrips) break;
        }
        if (trips >= totalTrips) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return left;
}

#include <bits/stdc++.h>
int minimumFinishTime(std::vector<std::vector<int>>& tires, int changeTime, int numLaps) {
    const long long INF = (1LL << 60);
    std::vector<long long> best(numLaps + 1, INF);
    for (const auto& t : tires) {
        long long f = t[0];
        long long r = t[1];
        long long cur = f;
        long long sum = 0;
        for (int lap = 1; lap <= numLaps; ++lap) {
            if (cur > (long long)changeTime + f) break;
            sum += cur;
            if (sum < best[lap]) best[lap] = sum;
            if (cur > INF / r) break;
            cur = cur * r;
        }
    }
    std::vector<long long> dp(numLaps + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= numLaps; ++i) {
        for (int k = 1; k <= i; ++k) {
            if (best[k] == INF) continue;
            long long cand = dp[i - k] + best[k];
            if (i != k) cand += changeTime;
            if (cand < dp[i]) dp[i] = cand;
        }
    }
    return (int)dp[numLaps];
}

