std::vector<int> replaceNonCoprime(std::vector<int>& nums) {
    std::vector<long long> st;
    for (int v : nums) {
        long long cur = v;
        while (!st.empty()) {
            long long top = st.back();
            long long g = my_gcd(top, cur);
            if (g > 1) {
                cur = (top / g) * cur;
                st.pop_back();
            } else {
                break;
            }
        }
        st.push_back(cur);
    }
    std::vector<int> result;
    result.reserve(st.size());
    for (long long x : st) result.push_back(static_cast<int>(x));
    return result;
}

