int minMovesToMakePalindrome(const std::string& s) {
    std::vector<char> arr(s.begin(), s.end());
    int i = 0;
    int j = static_cast<int>(arr.size()) - 1;
    int moves = 0;
    while (i < j) {
        if (arr[i] == arr[j]) {
            ++i;
            --j;
            continue;
        }
        int k = j;
        while (k > i && arr[k] != arr[i]) {
            --k;
        }
        if (k == i) {
            std::swap(arr[i], arr[i + 1]);
            ++moves;
        } else {
            while (k < j) {
                std::swap(arr[k], arr[k + 1]);
                ++moves;
                ++k;
            }
            ++i;
            --j;
        }
    }
    return moves;
}

