int maximumTop(std::vector<int>& nums, int k) {
    long long kk = k;
    int n = static_cast<int>(nums.size());
    if (kk == 0) return nums[0];
    if (n == 1) {
        return (kk % 2 == 0) ? nums[0] : -1;
    }
    if (kk > n) {
        return *std::max_element(nums.begin(), nums.end());
    }
    int maxPrev = INT_MIN;
    long long limit = kk - 1;
    for (int i = 0; i < limit; ++i) {
        if (i >= n) break;
        if (nums[i] > maxPrev) maxPrev = nums[i];
    }
    int ans = maxPrev;
    if (kk < n) {
        if (nums[kk] > ans) ans = nums[kk];
    }
    return ans;
}

