int countArtifacts(int n, const std::vector<std::vector<int>>& artifacts, const std::vector<std::vector<int>>& dig) {
    std::unordered_set<std::string> dugSet;
    for (const auto& pair : dig) {
        int r = pair[0];
        int c = pair[1];
        dugSet.insert(std::to_string(r) + ',' + std::to_string(c));
    }

    std::unordered_map<std::string, int> cellToArtifact;
    for (size_t i = 0; i < artifacts.size(); ++i) {
        int r1 = artifacts[i][0];
        int c1 = artifacts[i][1];
        int r2 = artifacts[i][2];
        int c2 = artifacts[i][3];
        for (int r = r1; r <= r2; ++r) {
            for (int c = c1; c <= c2; ++c) {
                cellToArtifact[std::to_string(r) + ',' + std::to_string(c)] = static_cast<int>(i);
            }
        }
    }

    int answer = 0;
    for (const auto& art : artifacts) {
        int r1 = art[0];
        int c1 = art[1];
        int r2 = art[2];
        int c2 = art[3];
        bool fullyDug = true;
        for (int r = r1; r <= r2 && fullyDug; ++r) {
            for (int c = c1; c <= c2; ++c) {
                if (dugSet.find(std::to_string(r) + ',' + std::to_string(c)) == dugSet.end()) {
                    fullyDug = false;
                    break;
                }
            }
        }
        if (fullyDug) {
            ++answer;
        }
    }
    return answer;
}

