long long minimumWeight(int n, std::vector<std::vector<int>>& edges, int src1, int src2, int dest) {
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<std::vector<std::pair<int,int>>> adj(n), revAdj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1], w = e[2];
        adj[u].emplace_back(v, w);
        revAdj[v].emplace_back(u, w);
    }
    auto dijkstra = [&](int start, const std::vector<std::vector<std::pair<int,int>>>& graph) {
        std::vector<long long> dist(n, INF);
        using Node = std::pair<long long,int>;
        std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;
        dist[start] = 0;
        pq.emplace(0, start);
        while (!pq.empty()) {
            Node top = pq.top(); pq.pop();
            long long d = top.first;
            int u = top.second;
            if (d != dist[u]) continue;
            for (const auto& edge : graph[u]) {
                int v = edge.first;
                int w = edge.second;
                long long nd = d + w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.emplace(nd, v);
                }
            }
        }
        return dist;
    };
    std::vector<long long> d1 = dijkstra(src1, adj);
    std::vector<long long> d2 = dijkstra(src2, adj);
    std::vector<long long> dDest = dijkstra(dest, revAdj);
    long long ans = INF;
    for (int v = 0; v < n; ++v) {
        if (d1[v] == INF || d2[v] == INF || dDest[v] == INF) continue;
        long long total = d1[v] + d2[v] + dDest[v];
        if (total < ans) ans = total;
    }
    return ans == INF ? -1 : ans;
}

#include <bits/stdc++.h>
#include <vector>
#include <cstddef>
#include <utility>

int minOperations(const std::vector<int>& nums) {
    double total = 0;
    for (int v : nums) total += v;
    double target = total / 2.0;

    auto heapPush = [](std::vector<double>& heap, double val) {
        heap.push_back(val);
        std::size_t i = heap.size() - 1;
        while (i > 0) {
            std::size_t p = (i - 1) >> 1;
            if (heap[p] >= heap[i]) break;
            std::swap(heap[p], heap[i]);
            i = p;
        }
    };

    auto heapPop = [](std::vector<double>& heap) -> double {
        double max = heap[0];
        double end = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = end;
            std::size_t i = 0;
            while (true) {
                std::size_t l = i * 2 + 1;
                std::size_t r = i * 2 + 2;
                std::size_t largest = i;
                if (l < heap.size() && heap[l] > heap[largest]) largest = l;
                if (r < heap.size() && heap[r] > heap[largest]) largest = r;
                if (largest == i) break;
                std::swap(heap[i], heap[largest]);
                i = largest;
            }
        }
        return max;
    };

    std::vector<double> heap;
    heap.reserve(nums.size());
    for (int v : nums) heapPush(heap, static_cast<double>(v));

    double saved = 0;
    int ops = 0;
    while (saved < target) {
        double cur = heapPop(heap);
        double half = cur / 2.0;
        saved += half;
        heapPush(heap, half);
        ++ops;
    }
    return ops;
}

#include <bits/stdc++.h>

long long maxSubsequenceCount(const std::string& text, const std::string& pattern) {
    char a = pattern[0];
    char b = pattern[1];
    int n = static_cast<int>(text.size());

    long long baseline = 0;
    long long cntA = 0;
    for (char ch : text) {
        if (ch == a) {
            if (a == b) {
                baseline += cntA;
            }
            ++cntA;
        } else if (ch == b) {
            baseline += cntA;
        }
    }

    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + (text[i] == a ? 1 : 0);
    }

    std::vector<long long> suff(n + 1, 0);
    for (int i = n - 1; i >= 0; --i) {
        suff[i] = suff[i + 1] + (text[i] == b ? 1 : 0);
    }

    long long maxAdd = 0;
    for (int pos = 0; pos <= n; ++pos) {
        long long addIfA = suff[pos];
        long long addIfB = pref[pos];
        maxAdd = std::max(maxAdd, std::max(addIfA, addIfB));
    }

    return baseline + maxAdd;
}

#include <bits/stdc++.h>

int minimumWhiteTiles(const std::string& floor, int numCarpets, int carpetLen) {
    int n = static_cast<int>(floor.size());
    const int INF = 1e9;
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(numCarpets + 1, INF));
    for (int k = 0; k <= numCarpets; ++k) dp[0][k] = 0;
    for (int i = 1; i <= n; ++i) {
        int isWhite = (floor[i - 1] == '1') ? 1 : 0;
        for (int k = 0; k <= numCarpets; ++k) {
            dp[i][k] = dp[i - 1][k] + isWhite;
            if (k > 0) {
                int prev = i - carpetLen;
                if (prev < 0) prev = 0;
                dp[i][k] = std::min(dp[i][k], dp[prev][k - 1]);
            }
        }
    }
    int ans = INF;
    for (int k = 0; k <= numCarpets; ++k) ans = std::min(ans, dp[n][k]);
    return ans;
}

