int countHillValley(const std::vector<int>& nums) {
    std::vector<int> compressed;
    compressed.reserve(nums.size());
    for (size_t i = 0; i < nums.size(); ++i) {
        if (i == 0 || nums[i] != nums[i - 1]) {
            compressed.push_back(nums[i]);
        }
    }
    int result = 0;
    for (size_t i = 1; i + 1 < compressed.size(); ++i) {
        if (compressed[i] > compressed[i - 1] && compressed[i] > compressed[i + 1]) {
            ++result;
        } else if (compressed[i] < compressed[i - 1] && compressed[i] < compressed[i + 1]) {
            ++result;
        }
    }
    return result;
}

#include <bits/stdc++.h>
#include <vector>

std::vector<int> maximumBobPoints(int numArrows, std::vector<int>& aliceArrows) {
    const int n = 12;
    int bestMask = 0;
    int bestScore = -1;
    int bestNeeded = 0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        int needed = 0;
        int score = 0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                needed += aliceArrows[i] + 1;
                score += i;
            }
        }
        if (needed <= numArrows && score > bestScore) {
            bestScore = score;
            bestMask = mask;
            bestNeeded = needed;
        }
    }
    std::vector<int> bobArrows(n, 0);
    for (int i = 0; i < n; ++i) {
        if (bestMask & (1 << i)) {
            bobArrows[i] = aliceArrows[i] + 1;
        }
    }
    int leftover = numArrows - bestNeeded;
    bobArrows[0] += leftover;
    return bobArrows;
}

#include <bits/stdc++.h>
int countCollisions(std::string directions) {
    int n = directions.size();
    int left = 0;
    while (left < n && directions[left] == 'L') ++left;
    int right = n - 1;
    while (right >= 0 && directions[right] == 'R') --right;
    if (left > right) return 0;
    int collisions = 0;
    for (int i = left; i <= right; ++i) {
        if (directions[i] != 'S') ++collisions;
    }
    return collisions;
}

#include <bits/stdc++.h>
using std::vector;
using std::string;
using std::map;
using std::multiset;

vector<int> longestRepeatingSubstringAfterQueries(string s, const string& queryCharacters, const vector<int>& queryIndices) {
    struct Node {
        int r;
        char c;
    };
    map<int, Node> seg;
    multiset<int> lens;
    int n = s.size();
    // build initial intervals
    for (int i = 0; i < n; ) {
        int j = i;
        while (j + 1 < n && s[j + 1] == s[i]) ++j;
        seg[i] = {j, s[i]};
        lens.insert(j - i + 1);
        i = j + 1;
    }
    auto addInterval = [&](int l, int r, char c) {
        seg[l] = {r, c};
        lens.insert(r - l + 1);
    };
    auto eraseInterval = [&](map<int, Node>::iterator it) {
        lens.erase(lens.find(it->second.r - it->first + 1));
        seg.erase(it);
    };
    vector<int> ans;
    ans.reserve(queryIndices.size());
    for (size_t qi = 0; qi < queryIndices.size(); ++qi) {
        int pos = queryIndices[qi];
        char newc = queryCharacters[qi];
        if (s[pos] == newc) {
            ans.push_back(*lens.rbegin());
            continue;
        }
        // locate interval containing pos
        auto it = seg.upper_bound(pos);
        --it;
        int l = it->first;
        int r = it->second.r;
        char curc = it->second.c;
        // remove old interval
        eraseInterval(it);
        // left part
        if (l <= pos - 1) addInterval(l, pos - 1, curc);
        // right part
        if (pos + 1 <= r) addInterval(pos + 1, r, curc);
        // prepare new interval bounds
        int newL = pos, newR = pos;
        // merge with left neighbor if same char
        auto leftIt = seg.lower_bound(pos);
        if (leftIt != seg.begin()) {
            auto prevIt = std::prev(leftIt);
            if (prevIt->second.r == pos - 1 && prevIt->second.c == newc) {
                newL = prevIt->first;
                eraseInterval(prevIt);
            }
        }
        // merge with right neighbor if same char
        auto rightIt = seg.lower_bound(pos + 1);
        if (rightIt != seg.end() && rightIt->first == pos + 1 && rightIt->second.c == newc) {
            newR = rightIt->second.r;
            eraseInterval(rightIt);
        }
        // insert merged interval
        addInterval(newL, newR, newc);
        s[pos] = newc;
        ans.push_back(*lens.rbegin());
    }
    return ans;
}

