std::vector<std::vector<int>> findDifference(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::unordered_set<int> set1(nums1.begin(), nums1.end());
    std::unordered_set<int> set2(nums2.begin(), nums2.end());

    std::vector<int> onlyInFirst;
    std::vector<int> onlyInSecond;

    for (int val : set1) {
        if (set2.find(val) == set2.end()) {
            onlyInFirst.push_back(val);
        }
    }

    for (int val : set2) {
        if (set1.find(val) == set1.end()) {
            onlyInSecond.push_back(val);
        }
    }

    std::sort(onlyInFirst.begin(), onlyInFirst.end());
    std::sort(onlyInSecond.begin(), onlyInSecond.end());

    return {onlyInFirst, onlyInSecond};
}

