int minDeletion(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    int pairs = 0;
    bool haveFirst = false;
    int firstVal = 0;
    for (int x : nums) {
        if (!haveFirst) {
            firstVal = x;
            haveFirst = true;
        } else {
            if (x > firstVal) {
                ++pairs;
                haveFirst = false;
            }
        }
    }
    return n - 2 * pairs;
}

