#include <climits>

long long maxValueOfCoins(const std::vector<std::vector<int>>& piles, int k) {
    const long long NEG_INF = LLONG_MIN / 4;
    std::vector<std::vector<long long>> pref;
    pref.reserve(piles.size());
    for (const auto& p : piles) {
        std::vector<long long> pre;
        pre.reserve(p.size() + 1);
        pre.push_back(0);
        for (int v : p) {
            pre.push_back(pre.back() + v);
        }
        pref.push_back(std::move(pre));
    }

    std::vector<long long> dp(k + 1, NEG_INF);
    dp[0] = 0;

    for (size_t i = 0; i < piles.size(); ++i) {
        const std::vector<long long>& curPref = pref[i];
        int sz = static_cast<int>(curPref.size()) - 1;
        std::vector<long long> next(k + 1, NEG_INF);

        for (int taken = 0; taken <= k; ++taken) {
            int maxX = std::min(sz, taken);
            for (int x = 0; x <= maxX; ++x) {
                if (dp[taken - x] == NEG_INF) continue;
                long long candidate = dp[taken - x] + curPref[x];
                if (candidate > next[taken]) {
                    next[taken] = candidate;
                }
            }
        }
        dp.swap(next);
    }

    return dp[k];
}

