#include <algorithm>

std::vector<long long> kthPalindrome(const std::vector<long long>& queries, int intLength) {
    std::vector<long long> answer;
    int halfLen = (intLength + 1) / 2;               // ceil(intLength/2)
    long long start = 1;
    for (int i = 1; i < halfLen; ++i) start *= 10;   // 10^(halfLen-1)
    long long total = 9 * start;                    // total palindromes of this length

    for (long long k : queries) {
        if (k > total) {
            answer.push_back(-1);
            continue;
        }
        long long left = start + (k - 1);
        std::string s = std::to_string(left);
        std::string rev = s;
        if (intLength % 2 == 1) rev.pop_back();      // remove middle digit for odd length
        std::reverse(rev.begin(), rev.end());
        std::string palStr = s + rev;
        answer.push_back(std::stoll(palStr));
    }
    return answer;
}

