int minOperations(const std::string& current, const std::string& correct) {
    int cur = std::stoi(current.substr(0, 2)) * 60 + std::stoi(current.substr(3));
    int cor = std::stoi(correct.substr(0, 2)) * 60 + std::stoi(correct.substr(3));
    int diff = cor - cur;
    if (diff < 0) diff += 24 * 60;
    const std::array<int, 4> inc = {60, 15, 5, 1};
    int ops = 0;
    for (int d : inc) {
        ops += diff / d;
        diff %= d;
    }
    return ops;
}

