std::vector<std::vector<int>> findWinners(const std::vector<std::vector<int>>& matches) {
    std::unordered_map<int, int> lossCount;
    std::unordered_set<int> players;
    for (const auto& match : matches) {
        int winner = match[0];
        int loser = match[1];
        players.insert(winner);
        players.insert(loser);
        lossCount[loser] = lossCount[loser] + 1;
    }
    std::vector<int> zeroLoss;
    std::vector<int> oneLoss;
    for (int p : players) {
        int cnt = lossCount.count(p) ? lossCount[p] : 0;
        if (cnt == 0) {
            zeroLoss.push_back(p);
        } else if (cnt == 1) {
            oneLoss.push_back(p);
        }
    }
    std::sort(zeroLoss.begin(), zeroLoss.end());
    std::sort(oneLoss.begin(), oneLoss.end());
    return {zeroLoss, oneLoss};
}

