long long maximumCandies(const std::vector<long long>& candies, long long k) {
    long long maxPile = 0;
    for (long long v : candies) {
        if (v > maxPile) maxPile = v;
    }
    long long low = 1, high = maxPile, best = 0;
    while (low <= high) {
        long long mid = (low + high) / 2;
        long long total = 0;
        for (long long v : candies) {
            total += v / mid;
            if (total >= k) break;
        }
        if (total >= k) {
            best = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return best;
}

