struct EncrypterResult {
    std::function<std::string(const std::string&)> encrypt;
    std::function<int(const std::string&)> decrypt;
};

EncrypterResult Encrypter(const std::vector<char>& keys, const std::vector<std::string>& values, const std::vector<std::string>& dictionary) {
    std::unordered_map<char, std::string> encMap;
    for (size_t i = 0; i < keys.size(); ++i) {
        encMap[keys[i]] = values[i];
    }

    std::unordered_map<std::string, int> dictCount;
    for (const std::string& word : dictionary) {
        std::string enc;
        bool possible = true;
        for (char ch : word) {
            auto it = encMap.find(ch);
            if (it == encMap.end()) {
                possible = false;
                break;
            }
            enc += it->second;
        }
        if (possible) {
            ++dictCount[enc];
        }
    }

    EncrypterResult result;
    result.encrypt = [encMap](const std::string& word) -> std::string {
        std::string enc;
        for (char ch : word) {
            auto it = encMap.find(ch);
            if (it == encMap.end()) {
                return "";
            }
            enc += it->second;
        }
        return enc;
    };
    result.decrypt = [dictCount](const std::string& code) -> int {
        auto it = dictCount.find(code);
        return it != dictCount.end() ? it->second : 0;
    };
    return result;
}

