long long largestNumberAfterParitySwaps(long long num) {
    std::string s = std::to_string(num);
    std::vector<int> odd;
    std::vector<int> even;
    for (char ch : s) {
        int d = ch - '0';
        if (d % 2) odd.push_back(d);
        else even.push_back(d);
    }
    std::sort(odd.begin(), odd.end(), std::greater<int>());
    std::sort(even.begin(), even.end(), std::greater<int>());
    std::size_t oi = 0, ei = 0;
    std::string result;
    result.reserve(s.size());
    for (char ch : s) {
        int d = ch - '0';
        if (d % 2) result.push_back('0' + odd[oi++]);
        else result.push_back('0' + even[ei++]);
    }
    return std::stoll(result);
}

#include <bits/stdc++.h>
long long maxProductAfterKIncrements(std::vector<int>& nums, int k) {
    const long long MOD = 1000000007LL;
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> pq;
    for (int v : nums) pq.push(static_cast<long long>(v));
    for (int i = 0; i < k; ++i) {
        long long x = pq.top(); pq.pop();
        ++x;
        pq.push(x);
    }
    long long result = 1;
    while (!pq.empty()) {
        result = (result * (pq.top() % MOD)) % MOD;
        pq.pop();
    }
    return result;
}

