std::string minimizeResult(const std::string& expression) {
    int n = static_cast<int>(expression.size());
    int plusPos = static_cast<int>(expression.find('+'));
    long long bestValue = LLONG_MAX;
    std::string bestExpr;
    for (int i = 0; i < plusPos; ++i) {
        std::string leftOutside = expression.substr(0, i);
        std::string leftInside = expression.substr(i, plusPos - i);
        for (int j = plusPos + 1; j < n; ++j) {
            std::string rightInside = expression.substr(plusPos + 1, j - plusPos);
            std::string rightOutside = expression.substr(j + 1);
            long long leftMul = leftOutside.empty() ? 1 : std::stoll(leftOutside);
            long long rightMul = rightOutside.empty() ? 1 : std::stoll(rightOutside);
            long long insideSum = std::stoll(leftInside) + std::stoll(rightInside);
            long long value = leftMul * insideSum * rightMul;
            if (value < bestValue) {
                bestValue = value;
                bestExpr = leftOutside + '(' + leftInside + '+' + rightInside + ')' + rightOutside;
            }
        }
    }
    return bestExpr;
}

#include <bits/stdc++.h>
long long maximumBeauty(std::vector<int> flowers, long long newFlowers, int target, int full, int partial) {
    int n = (int)flowers.size();
    std::sort(flowers.begin(), flowers.end());
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + flowers[i];
    std::vector<long long> suffixCost(n + 1, 0);
    for (int i = n - 1; i >= 0; --i) {
        long long need = target - (long long)flowers[i];
        if (need < 0) need = 0;
        suffixCost[i] = suffixCost[i + 1] + need;
    }
    long long best = 0;
    for (int k = 0; k <= n; ++k) { // k gardens will be complete
        long long need = suffixCost[n - k];
        if (need > newFlowers) continue;
        long long remaining = newFlowers - need;
        if (k == n) {
            best = std::max(best, (long long)full * n);
            continue;
        }
        int m = n - k; // number of incomplete gardens
        long long low = 0, high = target - 1;
        while (low < high) {
            long long mid = (low + high + 1) / 2;
            int pos = std::upper_bound(flowers.begin(), flowers.begin() + m, (int)mid) - flowers.begin();
            long long cost = mid * pos - pref[pos];
            if (cost <= remaining) low = mid;
            else high = mid - 1;
        }
        long long cur = (long long)full * k + (long long)partial * low;
        best = std::max(best, cur);
    }
    return best;
}

