int findClosestNumber(const std::vector<int>& nums) {
    int best = nums[0];
    int bestAbs = std::abs(best);
    for (size_t i = 1; i < nums.size(); ++i) {
        int cur = nums[i];
        int curAbs = std::abs(cur);
        if (curAbs < bestAbs) {
            best = cur;
            bestAbs = curAbs;
        } else if (curAbs == bestAbs && cur > best) {
            best = cur;
        }
    }
    return best;
}

