struct ATM {
    std::function<void(const std::vector<int>&)> deposit;
    std::function<std::vector<int>(int)> withdraw;
};

ATM createATM() {
    const std::vector<int> values = {20, 50, 100, 200, 500};
    // shared_ptr keeps stock alive for as long as the returned closures exist,
    // rather than a reference to a local destroyed when this function returns
    auto stock = std::make_shared<std::vector<int>>(5, 0);
    ATM atm;
    atm.deposit = [stock](const std::vector<int>& notes) {
        for (int i = 0; i < 5; ++i) {
            (*stock)[i] += notes[i];
        }
    };
    atm.withdraw = [stock, values](int amount) -> std::vector<int> {
        std::vector<int> used(5, 0);
        for (int i = 4; i >= 0; --i) {
            int maxTake = std::min(amount / values[i], (*stock)[i]);
            used[i] = maxTake;
            amount -= maxTake * values[i];
        }
        if (amount != 0) {
            return std::vector<int>{-1};
        }
        for (int i = 0; i < 5; ++i) {
            (*stock)[i] -= used[i];
        }
        return used;
    };
    return atm;
}

