int maximumScore(std::vector<int>& scores, std::vector<std::vector<int>>& edges) {
    int n = scores.size();
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // For each node keep up to three neighbours with highest scores
    std::vector<std::vector<int>> top(n);
    for (int i = 0; i < n; ++i) {
        for (int nb : adj[i]) {
            // insert nb into top[i] keeping descending order by scores
            int pos = top[i].size();
            for (int k = 0; k < (int)top[i].size(); ++k) {
                if (scores[nb] > scores[top[i][k]]) {
                    pos = k;
                    break;
                }
            }
            if (pos == (int)top[i].size()) {
                if (top[i].size() < 3) top[i].push_back(nb);
            } else {
                top[i].insert(top[i].begin() + pos, nb);
                if (top[i].size() > 3) top[i].pop_back();
            }
        }
    }

    long long best = -1;
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        for (int a : top[u]) {
            if (a == v) continue;
            for (int d : top[v]) {
                if (d == u) continue;
                if (a == d) continue;
                long long cur = (long long)scores[u] + scores[v] + scores[a] + scores[d];
                if (cur > best) best = cur;
            }
        }
    }

    return (int)best;
}

