int minimumRounds(const std::vector<int>& tasks) {
    std::unordered_map<int, int> freq;
    for (size_t i = 0; i < tasks.size(); ++i) {
        int d = tasks[i];
        ++freq[d];
    }

    int total = 0;
    for (const auto& kv : freq) {
        int cnt = kv.second;
        if (cnt == 1) return -1;
        if (cnt % 3 == 0) {
            total += cnt / 3;
        } else if (cnt % 3 == 2) {
            total += cnt / 3 + 1;
        } else {
            total += (cnt - 4) / 3 + 2;
        }
    }
    return total;
}

