std::string calculateDigitSum(std::string s, int k) {
    while (s.size() > static_cast<std::size_t>(k)) {
        std::vector<std::string> newParts;
        newParts.reserve((s.size() + k - 1) / k);
        for (std::size_t i = 0; i < s.size(); i += k) {
            int sum = 0;
            for (std::size_t j = i; j < i + static_cast<std::size_t>(k) && j < s.size(); ++j) {
                sum += s[j] - '0';
            }
            newParts.push_back(std::to_string(sum));
        }
        s.clear();
        for (const auto& part : newParts) {
            s += part;
        }
    }
    return s;
}

