int maxTrailingZeros(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<int>> cnt2(m, std::vector<int>(n));
    std::vector<std::vector<int>> cnt5(m, std::vector<int>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int x = grid[i][j];
            int c2 = 0, c5 = 0;
            while (x % 2 == 0) { ++c2; x /= 2; }
            while (x % 5 == 0) { ++c5; x /= 5; }
            cnt2[i][j] = c2;
            cnt5[i][j] = c5;
        }
    }
    std::vector<std::vector<int>> preRow2(m, std::vector<int>(n + 1, 0));
    std::vector<std::vector<int>> preRow5(m, std::vector<int>(n + 1, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            preRow2[i][j + 1] = preRow2[i][j] + cnt2[i][j];
            preRow5[i][j + 1] = preRow5[i][j] + cnt5[i][j];
        }
    }
    std::vector<std::vector<int>> preCol2(m + 1, std::vector<int>(n, 0));
    std::vector<std::vector<int>> preCol5(m + 1, std::vector<int>(n, 0));
    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < m; ++i) {
            preCol2[i + 1][j] = preCol2[i][j] + cnt2[i][j];
            preCol5[i + 1][j] = preCol5[i][j] + cnt5[i][j];
        }
    }
    int ans = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int up2 = preCol2[i + 1][j];
            int up5 = preCol5[i + 1][j];
            int down2 = preCol2[m][j] - preCol2[i][j];
            int down5 = preCol5[m][j] - preCol5[i][j];
            int left2 = preRow2[i][j + 1];
            int left5 = preRow5[i][j + 1];
            int right2 = preRow2[i][n] - preRow2[i][j];
            int right5 = preRow5[i][n] - preRow5[i][j];
            int c2 = cnt2[i][j];
            int c5 = cnt5[i][j];
            auto upd = [&](int twos, int fives) {
                ans = std::max(ans, std::min(twos, fives));
            };
            upd(up2, up5);
            upd(down2, down5);
            upd(left2, left5);
            upd(right2, right5);
            upd(up2 + left2 - c2, up5 + left5 - c5);
            upd(up2 + right2 - c2, up5 + right5 - c5);
            upd(down2 + left2 - c2, down5 + left5 - c5);
            upd(down2 + right2 - c2, down5 + right5 - c5);
        }
    }
    return ans;
}

