std::vector<int> intersectionMultiple(const std::vector<std::vector<int>>& nums) {
    std::size_t arrayCount = nums.size();
    std::unordered_map<int, int> freqMap;
    for (const auto& arr : nums) {
        std::unordered_set<int> seen;
        for (int num : arr) {
            if (seen.find(num) == seen.end()) {
                seen.insert(num);
                ++freqMap[num];
            }
        }
    }
    std::vector<int> result;
    for (const auto& pair : freqMap) {
        if (pair.second == static_cast<int>(arrayCount)) {
            result.push_back(pair.first);
        }
    }
    std::sort(result.begin(), result.end());
    return result;
}

#include <bits/stdc++.h>

std::vector<int> countRectangles(const std::vector<std::vector<int>>& rectangles,
                                 const std::vector<std::vector<int>>& points) {
    // Copy rectangles and sort by length descending
    std::vector<std::pair<int,int>> rects;
    rects.reserve(rectangles.size());
    for (const auto& r : rectangles) {
        rects.emplace_back(r[0], r[1]); // (li, hi)
    }
    std::sort(rects.begin(), rects.end(),
              [](const std::pair<int,int>& a, const std::pair<int,int>& b) {
                  return a.first > b.first;
              });

    // Prepare points with original indices and sort by x descending
    struct Pt {int x, y, idx;};
    std::vector<Pt> pts;
    pts.reserve(points.size());
    for (size_t i = 0; i < points.size(); ++i) {
        pts.push_back({points[i][0], points[i][1], static_cast<int>(i)});
    }
    std::sort(pts.begin(), pts.end(),
              [](const Pt& a, const Pt& b) { return a.x > b.x; });

    // Fenwick tree for heights 1..100
    const int MAXH = 100;
    std::vector<int> bit(MAXH + 2, 0);
    auto bitAdd = [&](int idx, int delta) {
        for (; idx <= MAXH; idx += idx & -idx) bit[idx] += delta;
    };
    auto bitSum = [&](int idx) {
        int s = 0;
        for (; idx > 0; idx -= idx & -idx) s += bit[idx];
        return s;
    };

    std::vector<int> answer(points.size(), 0);
    size_t rIdx = 0;
    for (const Pt& p : pts) {
        while (rIdx < rects.size() && rects[rIdx].first >= p.x) {
            int h = rects[rIdx].second;
            bitAdd(h, 1);
            ++rIdx;
        }
        int total = bitSum(MAXH);
        int below = (p.y > 1) ? bitSum(p.y - 1) : 0;
        answer[p.idx] = total - below;
    }
    return answer;
}

