int longestPath(const std::vector<int>& parent, const std::string& s) {
    int n = parent.size();
    std::vector<std::vector<int>> graph(n);
    for (int i = 1; i < n; ++i) {
        int p = parent[i];
        graph[p].push_back(i);
        graph[i].push_back(p);
    }
    int answer = 1;
    std::function<int(int, int)> dfs = [&](int node, int prev) -> int {
        int best1 = 0, best2 = 0;
        for (int nxt : graph[node]) {
            if (nxt == prev) continue;
            int childLen = dfs(nxt, node);
            if (s[nxt] == s[node]) continue;
            if (childLen > best1) {
                best2 = best1;
                best1 = childLen;
            } else if (childLen > best2) {
                best2 = childLen;
            }
        }
        answer = std::max(answer, best1 + best2 + 1);
        return best1 + 1;
    };
    dfs(0, -1);
    return answer;
}

