int countLatticePoints(std::vector<std::vector<int>>& circles) {
    std::unordered_set<long long> points;
    for (const auto& c : circles) {
        int cx = c[0];
        int cy = c[1];
        int r = c[2];
        int r2 = r * r;
        for (int x = cx - r; x <= cx + r; ++x) {
            int dx = x - cx;
            int remain = r2 - dx * dx;
            if (remain < 0) continue;
            int dy = static_cast<int>(std::sqrt(remain));
            for (int y = cy - dy; y <= cy + dy; ++y) {
                long long key = (static_cast<long long>(x) << 32) ^ static_cast<unsigned int>(y);
                points.insert(key);
            }
        }
    }
    return static_cast<int>(points.size());
}

