int upperBound(const std::vector<int>& arr, int target) {
    int lo = 0, hi = static_cast<int>(arr.size());
    while (lo < hi) {
        int mid = (lo + hi) >> 1;
        if (arr[mid] <= target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

int lowerBound(const std::vector<int>& arr, int target) {
    int lo = 0, hi = static_cast<int>(arr.size());
    while (lo < hi) {
        int mid = (lo + hi) >> 1;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

std::vector<int> fullBloomFlowers(const std::vector<std::vector<int>>& flowers, const std::vector<int>& people) {
    std::vector<int> starts;
    std::vector<int> ends;
    starts.reserve(flowers.size());
    ends.reserve(flowers.size());
    for (const auto& f : flowers) {
        starts.push_back(f[0]);
        ends.push_back(f[1]);
    }
    std::sort(starts.begin(), starts.end());
    std::sort(ends.begin(), ends.end());

    std::vector<int> result(people.size());
    for (size_t i = 0; i < people.size(); ++i) {
        int t = people[i];
        int started = upperBound(starts, t);
        int finished = lowerBound(ends, t);
        result[i] = started - finished;
    }
    return result;
}

