std::string removeDigit(const std::string& number, char digit) {
    std::size_t len = number.size();
    int removeIdx = -1;
    for (std::size_t i = 0; i + 1 < len; ++i) {
        if (number[i] == digit && number[i] < number[i + 1]) {
            removeIdx = static_cast<int>(i);
            break;
        }
    }
    if (removeIdx == -1) {
        for (int i = static_cast<int>(len) - 1; i >= 0; --i) {
            if (number[i] == digit) {
                removeIdx = i;
                break;
            }
        }
    }
    return number.substr(0, removeIdx) + number.substr(removeIdx + 1);
}

