int countKDivisibleSubarrays(const std::vector<int>& nums, int k, int p) {
    const long long MOD1 = 1000000007LL;
    const long long MOD2 = 1000000009LL;
    const long long BASE = 100007LL;
    int n = static_cast<int>(nums.size());
    std::unordered_set<std::string> seen;
    for (int i = 0; i < n; ++i) {
        int divCnt = 0;
        long long h1 = 0;
        long long h2 = 0;
        for (int j = i; j < n; ++j) {
            if (nums[j] % p == 0) ++divCnt;
            if (divCnt > k) break;
            h1 = (h1 * BASE + nums[j]) % MOD1;
            h2 = (h2 * BASE + nums[j]) % MOD2;
            std::string key = std::to_string(h1) + ',' + std::to_string(h2);
            seen.insert(key);
        }
    }
    return static_cast<int>(seen.size());
}

