long long totalAppeal(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::unordered_map<char, int> lastPos;
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        char ch = s[i];
        int prev = -1;
        auto it = lastPos.find(ch);
        if (it != lastPos.end()) {
            prev = it->second;
        }
        total += static_cast<long long>(i - prev) * (n - i);
        lastPos[ch] = i;
    }
    return total;
}

