int minimumCardPickup(const std::vector<int>& cards) {
    std::unordered_map<int, int> lastPos;
    int best = std::numeric_limits<int>::max();
    for (int i = 0; i < static_cast<int>(cards.size()); ++i) {
        int val = cards[i];
        auto it = lastPos.find(val);
        if (it != lastPos.end()) {
            int length = i - it->second + 1;
            if (length < best) best = length;
        }
        lastPos[val] = i;
    }
    return best == std::numeric_limits<int>::max() ? -1 : best;
}

