struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int countNodesEqualToAverage(TreeNode* root) {
    int answer = 0;
    std::function<std::pair<long long, int>(TreeNode*)> dfs = [&](TreeNode* node) -> std::pair<long long, int> {
        if (!node) return {0, 0};
        auto left = dfs(node->left);
        auto right = dfs(node->right);
        long long sum = left.first + right.first + node->val;
        int count = left.second + right.second + 1;
        long long avg = sum / count;
        if (node->val == avg) ++answer;
        return {sum, count};
    };
    dfs(root);
    return answer;
}

#include <bits/stdc++.h>
int countTexts(const std::string& pressedKeys) {
    const long long MOD = 1000000007LL;
    long long result = 1;
    int n = pressedKeys.size();
    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && pressedKeys[j] == pressedKeys[i]) ++j;
        int len = j - i;
        int maxPress = (pressedKeys[i] == '7' || pressedKeys[i] == '9') ? 4 : 3;
        std::vector<long long> dp(len + 1, 0);
        dp[0] = 1;
        for (int k = 1; k <= len; ++k) {
            long long sum = 0;
            for (int t = 1; t <= maxPress && t <= k; ++t) {
                sum += dp[k - t];
                if (sum >= MOD) sum -= MOD;
            }
            dp[k] = sum;
        }
        result = (result * dp[len]) % MOD;
        i = j;
    }
    return static_cast<int>(result);
}

#include <bits/stdc++.h>
#include <vector>
#include <bitset>

bool hasValidPath(const std::vector<std::vector<char>>& grid) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    const int MAX_LEN = 200; // m + n <= 200
    std::vector<std::vector<std::bitset<MAX_LEN + 1>>> dp(m, std::vector<std::bitset<MAX_LEN + 1>>(n));
    if (grid[0][0] == '(') {
        dp[0][0].set(1);
    } else {
        return false;
    }
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (dp[i][j].none()) continue;
            // move down
            if (i + 1 < m) {
                std::bitset<MAX_LEN + 1> nxt;
                if (grid[i + 1][j] == '(') {
                    nxt = dp[i][j] << 1;
                } else {
                    nxt = dp[i][j] >> 1;
                }
                dp[i + 1][j] |= nxt;
            }
            // move right
            if (j + 1 < n) {
                std::bitset<MAX_LEN + 1> nxt;
                if (grid[i][j + 1] == '(') {
                    nxt = dp[i][j] << 1;
                } else {
                    nxt = dp[i][j] >> 1;
                }
                dp[i][j + 1] |= nxt;
            }
        }
    }
    return dp[m - 1][n - 1].test(0);
}

