int kBeauty(long long num, int k) {
    std::string s = std::to_string(num);
    int n = static_cast<int>(s.size());
    if (k > n) return 0;

    long long power = 1;
    for (int i = 1; i < k; ++i) power *= 10;

    long long cur = 0;
    for (int i = 0; i < k; ++i) cur = cur * 10 + (s[i] - '0');

    int ans = 0;
    if (cur > 0 && num % cur == 0) ++ans;

    for (int i = k; i < n; ++i) {
        int outDigit = s[i - k] - '0';
        int inDigit = s[i] - '0';
        cur = (cur - outDigit * power) * 10 + inDigit;
        if (cur > 0 && num % cur == 0) ++ans;
    }

    return ans;
}

