long long numberOfWays(const std::vector<int>& nums) {
    long long total = 0;
    for (int v : nums) total += v;
    long long count = 0;
    long long prefix = 0;
    for (size_t i = 0; i + 1 < nums.size(); ++i) {
        prefix += nums[i];
        if (prefix * 2 >= total) ++count;
    }
    return count;
}

#include <bits/stdc++.h>

long long maximumWhiteTiles(const std::vector<std::vector<int>>& tiles, int carpetLen) {
    if (tiles.empty()) {
        return 0;
    }
    std::vector<std::vector<int>> t = tiles;
    std::sort(t.begin(), t.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        return a[0] < b[0];
    });
    std::size_t n = t.size();
    std::size_t left = 0, right = 0;
    long long cur = 0, ans = 0;
    while (left < n) {
        long long carpetEnd = static_cast<long long>(t[left][0]) + carpetLen - 1;
        while (right < n && static_cast<long long>(t[right][1]) <= carpetEnd) {
            cur += static_cast<long long>(t[right][1]) - t[right][0] + 1;
            ++right;
        }
        long long extra = 0;
        if (right < n && static_cast<long long>(t[right][0]) <= carpetEnd) {
            extra = carpetEnd - t[right][0] + 1;
        }
        ans = std::max(ans, cur + extra);
        cur -= static_cast<long long>(t[left][1]) - t[left][0] + 1;
        ++left;
        if (right < left) {
            right = left;
        }
    }
    return ans;
}

