std::vector<std::string> findResultantArray(const std::vector<std::string>& words) {
    auto areAnagrams = [](const std::string& a, const std::string& b) -> bool {
        if (a.size() != b.size()) return false;
        std::string sa = a;
        std::string sb = b;
        std::sort(sa.begin(), sa.end());
        std::sort(sb.begin(), sb.end());
        return sa == sb;
    };
    std::vector<std::string> result;
    result.reserve(words.size());
    for (size_t i = 0; i < words.size(); ++i) {
        if (!result.empty() && areAnagrams(result.back(), words[i])) {
            continue;
        }
        result.push_back(words[i]);
    }
    return result;
}

