int largestVariance(const std::string& s) {
    int ans = 0;
    int n = static_cast<int>(s.size());
    for (char a = 'a'; a <= 'z'; ++a) {
        for (char b = 'a'; b <= 'z'; ++b) {
            if (a == b) continue;
            int cur = 0;
            bool haveB = false;
            for (int i = 0; i < n; ++i) {
                if (s[i] == a) {
                    ++cur;
                } else if (s[i] == b) {
                    --cur;
                    haveB = true;
                }
                if (haveB) {
                    ans = std::max(ans, cur);
                }
                if (cur < 0) {
                    cur = 0;
                    haveB = false;
                }
            }
        }
    }
    return ans;
}

