int maximumBags(const std::vector<int>& capacity, const std::vector<int>& rocks, int additionalRocks) {
    std::size_t n = capacity.size();
    std::vector<int> need(n);
    for (std::size_t i = 0; i < n; ++i) {
        need[i] = capacity[i] - rocks[i];
    }
    std::sort(need.begin(), need.end());
    int fullBags = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (additionalRocks >= need[i]) {
            additionalRocks -= need[i];
            ++fullBags;
        } else {
            break;
        }
    }
    return fullBags;
}

