int largestCombination(const std::vector<int>& candidates) {
    int bitCounts[32] = {0};
    for (size_t i = 0; i < candidates.size(); ++i) {
        uint32_t num = static_cast<uint32_t>(candidates[i]);
        for (int b = 0; b < 32; ++b) {
            if ((num >> b) & 1u) ++bitCounts[b];
        }
    }
    int maxSize = 0;
    for (int b = 0; b < 32; ++b) {
        if (bitCounts[b] > maxSize) maxSize = bitCounts[b];
    }
    return maxSize;
}

