struct CountIntervalsObj {
    std::vector<std::pair<long long, long long>> intervals;
    long long total = 0;
    void add(long long left, long long right) {
        size_t lo = 0, hi = intervals.size();
        while (lo < hi) {
            size_t mid = (lo + hi) >> 1;
            if (intervals[mid].first < left) lo = mid + 1;
            else hi = mid;
        }
        size_t idx = lo;
        if (idx > 0 && intervals[idx - 1].second + 1 >= left) idx--;
        long long newL = left, newR = right;
        while (idx < intervals.size() && intervals[idx].first <= right + 1) {
            long long l = intervals[idx].first;
            long long r = intervals[idx].second;
            newL = std::min(newL, l);
            newR = std::max(newR, r);
            total -= (r - l + 1);
            intervals.erase(intervals.begin() + idx);
        }
        intervals.insert(intervals.begin() + idx, {newL, newR});
        total += (newR - newL + 1);
    }
    long long count() const {
        return total;
    }
};

CountIntervalsObj CountIntervals() {
    return CountIntervalsObj();
}

