#include <bits/stdc++.h>
using std::vector;
using std::stack;
using std::int64_t;

int64_t totalStrength(const vector<int>& strength) {
    const int64_t MOD = 1000000007LL;
    int n = strength.size();
    vector<int64_t> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = (pref[i] + strength[i]) % MOD;
    }
    vector<int64_t> pref2(n + 2, 0);
    for (int i = 0; i <= n; ++i) {
        pref2[i + 1] = (pref2[i] + pref[i]) % MOD;
    }

    vector<int> left(n), right(n);
    stack<int> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && strength[st.top()] > strength[i]) st.pop();
        left[i] = st.empty() ? -1 : st.top();
        st.push(i);
    }
    while (!st.empty()) st.pop();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && strength[st.top()] >= strength[i]) st.pop();
        right[i] = st.empty() ? n : st.top();
        st.push(i);
    }

    int64_t ans = 0;
    for (int i = 0; i < n; ++i) {
        int64_t L = i - left[i];
        int64_t R = right[i] - i;

        int64_t sumRight = (pref2[right[i] + 1] - pref2[i + 1] + MOD) % MOD;
        int64_t sumLeft = (pref2[i + 1] - pref2[left[i] + 1] + MOD) % MOD;

        int64_t term1 = (L % MOD) * sumRight % MOD;
        int64_t term2 = (R % MOD) * sumLeft % MOD;
        int64_t contrib = (term1 - term2 + MOD) % MOD;
        contrib = contrib * (strength[i] % MOD) % MOD;

        ans = (ans + contrib) % MOD;
    }
    return ans;
}

