std::string largestWordCount(const std::vector<std::string>& messages, const std::vector<std::string>& senders) {
    std::unordered_map<std::string, long long> countMap;
    for (size_t i = 0; i < messages.size(); ++i) {
        const std::string& sender = senders[i];
        long long words = 1 + std::count(messages[i].begin(), messages[i].end(), ' ');
        countMap[sender] = countMap[sender] + words;
    }
    std::string bestSender = "";
    long long maxWords = -1;
    for (const auto& kv : countMap) {
        const std::string& sender = kv.first;
        long long total = kv.second;
        if (total > maxWords || (total == maxWords && sender > bestSender)) {
            maxWords = total;
            bestSender = sender;
        }
    }
    return bestSender;
}

