int minLines(std::vector<std::vector<long long>> stockPrices) {
    if (stockPrices.size() < 2) return 0;
    std::sort(stockPrices.begin(), stockPrices.end(),
        [](const std::vector<long long>& a, const std::vector<long long>& b) {
            return a[0] < b[0];
        });
    int count = 0;
    bool hasPrev = false;
    long long prevDy = 0, prevDx = 0;
    auto gcd = [](long long a, long long b) {
        while (b != 0) {
            long long t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    for (size_t i = 1; i < stockPrices.size(); ++i) {
        long long dy = stockPrices[i][1] - stockPrices[i - 1][1];
        long long dx = stockPrices[i][0] - stockPrices[i - 1][0];
        long long g = gcd(std::abs(dy), std::abs(dx));
        dy /= g;
        dx /= g;
        if (dx < 0) {
            dy = -dy;
            dx = -dx;
        }
        if (!hasPrev || dy != prevDy || dx != prevDx) {
            ++count;
            prevDy = dy;
            prevDx = dx;
            hasPrev = true;
        }
    }
    return count;
}

