long long maximumImportance(int n, const std::vector<std::vector<int>>& roads) {
    std::vector<int> degree(n, 0);
    for (const auto& edge : roads) {
        int u = edge[0];
        int v = edge[1];
        degree[u]++;
        degree[v]++;
    }
    std::vector<int> sortedDegrees = degree;
    std::sort(sortedDegrees.begin(), sortedDegrees.end(), std::greater<int>());
    long long totalImportance = 0;
    int currentValue = n;
    for (int deg : sortedDegrees) {
        totalImportance += static_cast<long long>(deg) * currentValue;
        currentValue--;
    }
    return totalImportance;
}

