int maxCopies(const std::string& s, const std::string& target) {
    std::unordered_map<char, int> sCount;
    for (size_t i = 0; i < s.size(); ++i) {
        char ch = s[i];
        ++sCount[ch];
    }

    std::unordered_map<char, int> tCount;
    for (size_t i = 0; i < target.size(); ++i) {
        char ch = target[i];
        ++tCount[ch];
    }

    int copies = INT_MAX;
    for (const auto& kv : tCount) {
        char ch = kv.first;
        int need = kv.second;
        auto it = sCount.find(ch);
        if (it == sCount.end()) {
            return 0;
        }
        copies = std::min(copies, it->second / need);
    }
    return copies == INT_MAX ? 0 : copies;
}

