std::string discountPrices(const std::string& sentence, int discount) {
    std::vector<std::string> words;
    size_t start = 0;
    while (true) {
        size_t pos = sentence.find(' ', start);
        if (pos == std::string::npos) {
            words.push_back(sentence.substr(start));
            break;
        } else {
            words.push_back(sentence.substr(start, pos - start));
            start = pos + 1;
        }
    }
    for (size_t i = 0; i < words.size(); ++i) {
        const std::string& w = words[i];
        if (w.size() > 1 && w[0] == '$' && std::all_of(w.begin() + 1, w.end(),
            [](char c) { return std::isdigit(static_cast<unsigned char>(c)); })) {
            double original = std::stod(w.substr(1));
            double discounted = original * (100 - discount) / 100.0;
            std::ostringstream oss;
            oss << std::fixed << std::setprecision(2) << discounted;
            words[i] = "$" + oss.str();
        }
    }
    std::string result;
    for (size_t i = 0; i < words.size(); ++i) {
        if (i) result.push_back(' ');
        result += words[i];
    }
    return result;
}

