int stepsToMakeArrayNonDecreasing(const std::vector<int>& nums) {
    std::vector<std::pair<int, int>> st;
    int ans = 0;
    for (int x : nums) {
        int days = 0;
        while (!st.empty() && st.back().first <= x) {
            days = std::max(days, st.back().second);
            st.pop_back();
        }
        if (!st.empty()) {
            ++days;
        }
        ans = std::max(ans, days);
        st.emplace_back(x, days);
    }
    return ans;
}

#include <bits/stdc++.h>
using namespace std;

struct BookMyShowImpl {
    int n, m;
    vector<int> rem;
    vector<long long> sum;
    vector<int> mx;

    BookMyShowImpl(int n_, int m_) : n(n_), m(m_), rem(n_, m_), sum(4*n_, 0), mx(4*n_, 0) {
        build(1, 0, n - 1);
    }
    void build(int node, int l, int r) {
        if (l == r) { sum[node] = m; mx[node] = m; return; }
        int mid = (l + r) >> 1;
        build(node*2, l, mid); build(node*2+1, mid+1, r);
        pull(node);
    }
    void pull(int node) {
        sum[node] = sum[node*2] + sum[node*2+1];
        mx[node] = max(mx[node*2], mx[node*2+1]);
    }
    void update(int node, int l, int r, int idx, int val) {
        if (l == r) { sum[node] = val; mx[node] = val; return; }
        int mid = (l + r) >> 1;
        if (idx <= mid) update(node*2, l, mid, idx, val);
        else update(node*2+1, mid+1, r, idx, val);
        pull(node);
    }
    long long querySum(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return 0LL;
        if (ql <= l && r <= qr) return sum[node];
        int mid = (l + r) >> 1;
        return querySum(node*2, l, mid, ql, qr) + querySum(node*2+1, mid+1, r, ql, qr);
    }
    int queryMax(int node, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return INT_MIN;
        if (ql <= l && r <= qr) return mx[node];
        int mid = (l + r) >> 1;
        return max(queryMax(node*2, l, mid, ql, qr), queryMax(node*2+1, mid+1, r, ql, qr));
    }
    int findFirst(int node, int l, int r, int qr, int need) {
        if (l > qr || mx[node] < need) return -1;
        if (l == r) return l;
        int mid = (l + r) >> 1;
        int left = findFirst(node*2, l, mid, qr, need);
        if (left != -1) return left;
        return findFirst(node*2+1, mid+1, r, qr, need);
    }
    vector<int> gather(int k, int maxRow) {
        if (queryMax(1, 0, n-1, 0, maxRow) < k) return {};
        int row = findFirst(1, 0, n-1, maxRow, k);
        int start = m - rem[row];
        rem[row] -= k;
        update(1, 0, n-1, row, rem[row]);
        return {row, start};
    }
    bool scatter(int k, int maxRow) {
        if (querySum(1, 0, n-1, 0, maxRow) < k) return false;
        while (k > 0) {
            int row = findFirst(1, 0, n-1, maxRow, 1);
            int take = min(rem[row], k);
            rem[row] -= take;
            update(1, 0, n-1, row, rem[row]);
            k -= take;
        }
        return true;
    }
};

