int minMaxGame(std::vector<int> nums) {
    while (nums.size() > 1) {
        std::vector<int> next;
        next.reserve(nums.size() / 2);
        for (size_t i = 0; i < nums.size(); i += 2) {
            size_t pairIdx = i / 2;
            if (pairIdx % 2 == 0) {
                next.push_back(std::min(nums[i], nums[i + 1]));
            } else {
                next.push_back(std::max(nums[i], nums[i + 1]));
            }
        }
        nums = std::move(next);
    }
    return nums[0];
}

