std::vector<int> successfulPairs(const std::vector<int>& spells, std::vector<int> potions, long long success) {
    std::sort(potions.begin(), potions.end());
    int m = static_cast<int>(potions.size());
    std::vector<int> result;
    result.reserve(spells.size());

    auto lowerBound = [&](const std::vector<int>& arr, long long target) {
        int left = 0, right = static_cast<int>(arr.size());
        while (left < right) {
            int mid = left + ((right - left) >> 1);
            if (arr[mid] < target) left = mid + 1;
            else right = mid;
        }
        return left;
    };

    for (int spell : spells) {
        long long need = (success + spell - 1) / spell;
        int idx = lowerBound(potions, need);
        result.push_back(m - idx);
    }
    return result;
}

