bool strongPasswordCheckerII(const std::string& password) {
    if (password.size() < 8) return false;
    const std::string specials = "!@#$%^&*()-+";
    bool hasLower = false, hasUpper = false, hasDigit = false, hasSpecial = false;
    for (size_t i = 0; i < password.size(); ++i) {
        char ch = password[i];
        if (i > 0 && ch == password[i - 1]) return false;
        if (!hasLower && ch >= 'a' && ch <= 'z') hasLower = true;
        else if (!hasUpper && ch >= 'A' && ch <= 'Z') hasUpper = true;
        else if (!hasDigit && ch >= '0' && ch <= '9') hasDigit = true;
        else if (!hasSpecial && specials.find(ch) != std::string::npos) hasSpecial = true;
    }
    return hasLower && hasUpper && hasDigit && hasSpecial;
}

