bool matchSubstringAfterReplacement(const std::string& s, const std::string& sub, const std::vector<std::pair<char, char>>& mappings) {
    std::unordered_map<char, std::unordered_set<char>> replaceMap;
    for (size_t k = 0; k < mappings.size(); ++k) {
        char oldChar = mappings[k].first;
        char newChar = mappings[k].second;
        replaceMap[oldChar].insert(newChar);
    }

    size_t n = s.size(), m = sub.size();
    if (m > n) return false;

    for (size_t i = 0; i <= n - m; ++i) {
        bool ok = true;
        for (size_t j = 0; j < m; ++j) {
            char a = sub[j];
            char b = s[i + j];
            if (a == b) continue;
            auto it = replaceMap.find(a);
            if (it != replaceMap.end() && it->second.find(b) != it->second.end()) continue;
            ok = false;
            break;
        }
        if (ok) return true;
    }
    return false;
}

