double calculateTax(const std::vector<std::vector<int>>& brackets, int income) {
    double taxPaid = 0.0;
    int previousUpper = 0;
    for (const auto& bracket : brackets) {
        int upper = bracket[0];
        int percent = bracket[1];
        int taxable = std::min(income, upper) - previousUpper;
        if (taxable > 0) {
            taxPaid += taxable * percent / 100.0;
