int distributeCookies(std::vector<int> cookies, int k) {
    std::sort(cookies.begin(), cookies.end(), std::greater<int>());
    int total = std::accumulate(cookies.begin(), cookies.end(), 0);
    int maxBag = cookies.empty() ? 0 : cookies[0];
    int low = maxBag, high = total;
    auto canFit = [&](int limit) -> bool {
        std::vector<int> load(k, 0);
        std::function<bool(int)> dfs = [&](int idx) -> bool {
            if (idx == static_cast<int>(cookies.size())) return true;
            int cur = cookies[idx];
            for (int i = 0; i < k; ++i) {
                if (load[i] + cur <= limit) {
                    load[i] += cur;
                    if (dfs(idx + 1)) return true;
                    load[i] -= cur;
                }
                if (load[i] == 0) break;
            }
            return false;
        };
        return dfs(0);
    };
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (canFit(mid)) high = mid;
        else low = mid + 1;
    }
    return low;
}

