int maxProfit(int m, int n, const std::vector<std::array<int, 3>>& prices) {
    std::unordered_map<std::string, int> priceMap;
    for (const auto& triple : prices) {
        int h = triple[0];
        int w = triple[1];
        int p = triple[2];
        std::string key = std::to_string(h) + "," + std::to_string(w);
        int cur = 0;
        auto it = priceMap.find(key);
        if (it != priceMap.end()) cur = it->second;
        if (p > cur) priceMap[key] = p;
    }

    std::vector<std::vector<int>> memo(m + 1, std::vector<int>(n + 1, -1));

    std::function<int(int, int)> dfs = [&](int h, int w) -> int {
        if (memo[h][w] != -1) return memo[h][w];

        std::string key = std::to_string(h) + "," + std::to_string(w);
        int best = 0;
        auto it = priceMap.find(key);
        if (it != priceMap.end()) best = it->second;

        for (int cut = 1; cut < w; ++cut) {
            int left = dfs(h, cut);
            int right = dfs(h, w - cut);
            int combined = left + right;
            if (combined > best) best = combined;
        }

        for (int cut = 1; cut < h; ++cut) {
            int top = dfs(cut, w);
            int bottom = dfs(h - cut, w);
            int combined = top + bottom;
            if (combined > best) best = combined;
        }

        memo[h][w] = best;
        return best;
    };

    return dfs(m, n);
}

