long long distinctNames(const std::vector<std::string>& ideas) {
    std::vector<std::unordered_set<std::string>> groups(26);
    for (const std::string& w : ideas) {
        int first = w[0] - 'a';
        std::string suffix = w.substr(1);
        groups[first].insert(suffix);
    }

    long long answer = 0;

    for (int i = 0; i < 26; ++i) {
        if (groups[i].empty()) continue;
        for (int j = i + 1; j < 26; ++j) {
            if (groups[j].empty()) continue;

            const std::unordered_set<std::string>& setI = groups[i];
            const std::unordered_set<std::string>& setJ = groups[j];

            const std::unordered_set<std::string>* smaller = &setI;
            const std::unordered_set<std::string>* larger = &setJ;
            if (setI.size() > setJ.size()) {
                smaller = &setJ;
                larger = &setI;
            }

            long long common = 0;
            for (const std::string& s : *smaller) {
                if (larger->find(s) != larger->end()) {
                    ++common;
                }
            }

            long long cntI = static_cast<long long>(setI.size());
            long long cntJ = static_cast<long long>(setJ.size());
            answer += (cntI - common) * (cntJ - common) * 2;
        }
    }

    return answer;
}

#include <bits/stdc++.h>
