long long countUnreachablePairs(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<int> parent(n);
    std::vector<int> sz(n, 1);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
    };

    for (const auto& e : edges) {
        unite(e[0], e[1]);
    }

    std::unordered_map<int, int> compSize;
    for (int i = 0; i < n; ++i) {
        int root = find(i);
        ++compSize[root];
    }

    long long result = 0;
    long long remaining = n;
    for (const auto& kv : compSize) {
        long long s = kv.second;
        remaining -= s;
        result += s * remaining;
    }
    return result;
}

#include <bits/stdc++.h>
using namespace std;

int countDistinctRollSequences(int n) {
    const long long MOD = 1000000007;
    auto gcd = [](int a, int b) {
        while (b) { int t = b; b = a % b; a = t; }
        return a;
    };
    if (n == 1) return 6;
    map<pair<int,int>, long long> dp;
    for (int a = 1; a <= 6; a++) {
        for (int b = 1; b <= 6; b++) {
            if (a == b || gcd(a, b) != 1) continue;
            dp[{b, a}] += 1;
        }
    }
    for (int len = 3; len <= n; len++) {
        map<pair<int,int>, long long> ndp;
        for (auto& [key, cnt] : dp) {
            int prev = key.first, prevprev = key.second;
            for (int v = 1; v <= 6; v++) {
                if (v == prev || v == prevprev || gcd(v, prev) != 1) continue;
                ndp[{v, prev}] = (ndp[{v, prev}] + cnt) % MOD;
            }
        }
        dp = ndp;
    }
    long long total = 0;
    for (auto& [key, cnt] : dp) total = (total + cnt) % MOD;
    return (int)total;
}

