struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

std::vector<std::vector<int>> spiralMatrix(int m, int n, ListNode* head) {
    std::vector<std::vector<int>> matrix(m, std::vector<int>(n, -1));

    int top = 0;
    int bottom = m - 1;
    int left = 0;
    int right = n - 1;
    ListNode* node = head;

    while (top <= bottom && left <= right) {
        for (int col = left; col <= right; ++col) {
            if (node) {
                matrix[top][col] = node->val;
                node = node->next;
            }
        }
        ++top;

        for (int row = top; row <= bottom; ++row) {
            if (node) {
                matrix[row][right] = node->val;
                node = node->next;
            }
        }
        --right;

        if (top <= bottom) {
            for (int col = right; col >= left; --col) {
                if (node) {
                    matrix[bottom][col] = node->val;
                    node = node->next;
                }
            }
            --bottom;
        }

        if (left <= right) {
            for (int row = bottom; row >= top; --row) {
                if (node) {
                    matrix[row][left] = node->val;
                    node = node->next;
                }
            }
            ++left;
        }
    }

    return matrix;
}

