    for (size_t i = 0; i < nums1.size(); ++i) {
        sum1 += nums1[i];
        sum2 += nums2[i];
    }
    long long bestDiff = 0, curDiff = 0;
    long long bestNeg = 0, curNeg = 0;
    for (size_t i = 0; i < nums1.size(); ++i) {
        long long diff = static_cast<long long>(nums2[i]) - nums1[i];
        curDiff = std::max(diff, curDiff + diff);
