int minimumScore(std::vector<int>& nums, std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(nums.size());
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int a = e[0], b = e[1];
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    std::vector<int> parent(n, -1), depth(n, 0), tin(n), tout(n), subXor(n);
    int timer = 0;
    std::function<void(int, int)> dfs = [&](int u, int p) {
        parent[u] = p;
        subXor[u] = nums[u];
        tin[u] = timer++;
        for (int v : adj[u]) {
            if (v == p) continue;
            depth[v] = depth[u] + 1;
            dfs(v, u);
            subXor[u] ^= subXor[v];
        }
        tout[u] = timer++;
    };
    dfs(0, -1);

    int totalXor = subXor[0];
    int answer = INT_MAX;

    std::vector<int> childs;
    for (int i = 1; i < n; ++i) childs.push_back(i);
    int m = static_cast<int>(childs.size());

    for (int i = 0; i < m; ++i) {
        int a = childs[i];
        for (int j = i + 1; j < m; ++j) {
            int b = childs[j];
            int xorA = subXor[a];
            int xorB = subXor[b];
            int score;
            bool aAncB = (tin[a] <= tin[b] && tout[b] <= tout[a]);
            bool bAncA = (tin[b] <= tin[a] && tout[a] <= tout[b]);

            if (aAncB) {
                int xorRest = totalXor ^ xorA;
                int xorAminusB = xorA ^ xorB;
                int mx = std::max({xorB, xorAminusB, xorRest});
                int mn = std::min({xorB, xorAminusB, xorRest});
                score = mx - mn;
            } else if (bAncA) {
                int xorRest = totalXor ^ xorB;
                int xorBminusA = xorB ^ xorA;
                int mx = std::max({xorA, xorBminusA, xorRest});
                int mn = std::min({xorA, xorBminusA, xorRest});
                score = mx - mn;
            } else {
                int xorRest = totalXor ^ xorA ^ xorB;
                int mx = std::max({xorA, xorB, xorRest});
                int mn = std::min({xorA, xorB, xorRest});
                score = mx - mn;
            }
            answer = std::min(answer, score);
        }
    }
    return answer;
}

