#include <unordered_map>

std::string decodeMessage(const std::string& key, const std::string& message) {
    std::unordered_map<char, char> cipherToPlain;
    int nextPlainCode = 97;
    for (size_t i = 0; i < key.size(); ++i) {
        char ch = key[i];
        if (ch == ' ') continue;
        if (cipherToPlain.find(ch) == cipherToPlain.end()) {
            cipherToPlain[ch] = static_cast<char>(nextPlainCode);
            ++nextPlainCode;
        }
    }
    std::string decoded;
    decoded.reserve(message.size());
    for (size_t i = 0; i < message.size(); ++i) {
        char ch = message[i];
        decoded.push_back(ch == ' ' ? ' ' : cipherToPlain[ch]);
    }
    return decoded;
}

