int latestTimeCatchTheBus(std::vector<int> buses, std::vector<int> passengers, int capacity) {
    std::sort(buses.begin(), buses.end());
    std::sort(passengers.begin(), passengers.end());

    std::unordered_set<int> passengerSet(passengers.begin(), passengers.end());
    std::size_t pIdx = 0;
    int answer = -1;

    for (int bus : buses) {
        int boarded = 0;
        while (pIdx < passengers.size() && passengers[pIdx] <= bus && boarded < capacity) {
            ++boarded;
            ++pIdx;
        }

        int candidate;
        if (boarded < capacity) {
            candidate = bus;
        } else {
            candidate = passengers[pIdx - 1] - 1;
        }

        while (passengerSet.find(candidate) != passengerSet.end()) {
            --candidate;
        }

        if (candidate > answer) {
            answer = candidate;
        }
    }

    return answer;
}

