int countPaths(std::vector<std::vector<int>>& grid) {
    const int MOD = 1000000007;
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::tuple<int,int,int>> cells;
    cells.reserve(m * n);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            cells.emplace_back(grid[i][j], i, j);
        }
    }
    std::sort(cells.begin(), cells.end(),
              [](const std::tuple<int,int,int>& a, const std::tuple<int,int,int>& b) {
                  return std::get<0>(a) < std::get<0>(b);
              });
    std::vector<std::vector<int>> dp(m, std::vector<int>(n, 1));
    long long ans = 0;
    const int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
    for (const auto& cell : cells) {
        int val = std::get<0>(cell);
        int i = std::get<1>(cell);
        int j = std::get<2>(cell);
        for (int d = 0; d < 4; ++d) {
            int ni = i + dirs[d][0];
            int nj = j + dirs[d][1];
            if (ni >= 0 && ni < m && nj >= 0 && nj < n && grid[ni][nj] < val) {
                dp[i][j] += dp[ni][nj];
                if (dp[i][j] >= MOD) dp[i][j] -= MOD;
            }
        }
        ans += dp[i][j];
        if (ans >= MOD) ans -= MOD;
    }
    return static_cast<int>(ans);
}

