struct SmallestInfiniteSetResult {
    std::function<int()> popSmallest;
    std::function<void(int)> addBack;
};

struct State {
    std::vector<int> heap;
    std::unordered_set<int> inHeap;
    int next = 1;
};

SmallestInfiniteSetResult SmallestInfiniteSet() {
    // shared_ptr keeps the state alive for as long as the returned closures exist,
    // rather than references to locals destroyed when this function returns
    auto st = std::make_shared<State>();

    auto heapPush = [st](int val) {
        st->heap.push_back(val);
        int i = static_cast<int>(st->heap.size()) - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (st->heap[p] <= st->heap[i]) break;
            std::swap(st->heap[p], st->heap[i]);
            i = p;
        }
    };

    auto heapPop = [st]() -> int {
        int min = st->heap[0];
        int last = st->heap.back();
        st->heap.pop_back();
        if (!st->heap.empty()) {
            st->heap[0] = last;
            int i = 0;
            while (true) {
                int l = i * 2 + 1;
                int r = i * 2 + 2;
                int smallest = i;
                if (l < static_cast<int>(st->heap.size()) && st->heap[l] < st->heap[smallest]) smallest = l;
                if (r < static_cast<int>(st->heap.size()) && st->heap[r] < st->heap[smallest]) smallest = r;
                if (smallest == i) break;
                std::swap(st->heap[i], st->heap[smallest]);
                i = smallest;
            }
        }
        return min;
    };

    SmallestInfiniteSetResult result;
    result.popSmallest = [st, heapPop]() -> int {
        if (!st->heap.empty()) {
            int val = heapPop();
            st->inHeap.erase(val);
            return val;
        }
        return st->next++;
    };
    result.addBack = [st, heapPush](int num) {
        if (num < st->next && st->inHeap.find(num) == st->inHeap.end()) {
            heapPush(num);
            st->inHeap.insert(num);
        }
    };
    return result;
}

#include <bits/stdc++.h>
int idealArrays(int n, int maxValue) {
    const int MOD = 1000000007;
    std::vector<std::vector<int>> divisors(maxValue + 1);
    for (int i = 1; i <= maxValue; ++i) {
        for (int j = i; j <= maxValue; j += i) {
            divisors[j].push_back(i);
        }
    }
    std::vector<int> dpPrev(maxValue + 1, 1), dpCurr(maxValue + 1, 0);
    for (int len = 2; len <= n; ++len) {
        std::fill(dpCurr.begin(), dpCurr.end(), 0);
        for (int v = 1; v <= maxValue; ++v) {
            long long sum = 0;
            for (int d : divisors[v]) {
                sum += dpPrev[d];
                if (sum >= (1LL << 62)) sum %= MOD; // prevent overflow
            }
            dpCurr[v] = static_cast<int>(sum % MOD);
        }
        dpPrev.swap(dpCurr);
    }
    long long ans = 0;
    for (int v = 1; v <= maxValue; ++v) {
        ans += dpPrev[v];
    }
    return static_cast<int>(ans % MOD);
}

#include <bits/stdc++.h>

int validSubarraySize(std::vector<int>& nums, int threshold) {
    int n = static_cast<int>(nums.size());
    std::vector<int> left(n), right(n);
    std::stack<int> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[st.top()] >= nums[i]) st.pop();
        left[i] = st.empty() ? -1 : st.top();
        st.push(i);
    }
    while (!st.empty()) st.pop();
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && nums[st.top()] >= nums[i]) st.pop();
        right[i] = st.empty() ? n : st.top();
        st.push(i);
    }
    int answer = INT_MAX;
    for (int i = 0; i < n; ++i) {
        long long need = static_cast<long long>(threshold) / nums[i] + 1;
        long long maxLen = static_cast<long long>(right[i] - left[i] - 1);
        if (need <= maxLen) {
            answer = std::min(answer, static_cast<int>(need));
        }
    }
    return answer == INT_MAX ? -1 : answer;
}

#include <bits/stdc++.h>
long long minSumSquareDiff(std::vector<int>& nums1, std::vector<int>& nums2, int k1, int k2) {
    long long ops = (long long)k1 + k2;
    int n = nums1.size();
    int maxDiff = 0;
    std::vector<int> diffs(n);
    for (int i = 0; i < n; ++i) {
        int d = std::abs(nums1[i] - nums2[i]);
        diffs[i] = d;
        if (d > maxDiff) maxDiff = d;
    }
    std::vector<long long> freq(maxDiff + 1, 0);
    for (int d : diffs) {
        ++freq[d];
    }
    for (int d = maxDiff; d > 0 && ops > 0; --d) {
        if (freq[d] == 0) continue;
        long long move = std::min<long long>(freq[d], ops);
        freq[d] -= move;
        freq[d - 1] += move;
        ops -= move;
    }
    if (ops > 0 && (ops % 2 == 1)) {
        // all diffs are zero, one remaining operation makes a diff of 1
        if (freq.size() < 2) freq.resize(2, 0);
        freq[1] = 1;
    }
    long long ans = 0;
    for (size_t i = 0; i < freq.size(); ++i) {
        if (freq[i] == 0) continue;
        ans += (long long)i * i * freq[i];
    }
    return ans;
}

