std::vector<int> smallestTrimmedNumbers(const std::vector<std::string>& nums, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(nums.size());
    std::vector<int> answers(queries.size());

    for (size_t q = 0; q < queries.size(); ++q) {
        int k = queries[q][0];
        int trim = queries[q][1];

        struct Item { int idx; int val; };
        std::vector<Item> items(n);
        for (int i = 0; i < n; ++i) {
            const std::string& s = nums[i];
            int len = static_cast<int>(s.size());
            int start = (len > trim) ? (len - trim) : 0;
            std::string trimmed = s.substr(start);
            int val = std::stoi(trimmed);
            items[i] = { i, val };
        }

        std::sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
            if (a.val != b.val) return a.val < b.val;
            return a.idx < b.idx;
        });

        answers[q] = items[k - 1].idx;
    }

    return answers;
}

