int minDeletion(std::vector<int> nums, std::vector<int> numsDivide) {
    auto gcd = [](int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    int common = numsDivide[0];
    for (size_t i = 1; i < numsDivide.size(); ++i) {
        common = gcd(common, numsDivide[i]);
    }
    std::sort(nums.begin(), nums.end());
    for (size_t i = 0; i < nums.size(); ++i) {
        if (common % nums[i] == 0) {
            return static_cast<int>(i);
        }
    }
    return -1;
}

