int maxSumPair(const std::vector<int>& nums) {
    auto digitSum = [](int n) {
        int s = 0;
        while (n > 0) {
            s += n % 10;
            n /= 10;
        }
        return s;
    };
    std::unordered_map<int, std::pair<int, int>> top;
    int best = -1;
    for (int value : nums) {
        int d = digitSum(value);
        auto it = top.find(d);
        if (it == top.end()) {
            top.emplace(d, std::make_pair(value, std::numeric_limits<int>::min()));
        } else {
            int max1 = it->second.first;
            int max2 = it->second.second;
            best = std::max(best, max1 + value);
            if (value > max1) {
                it->second.second = max1;
                it->second.first = value;
            } else if (value > max2) {
                it->second.second = value;
            }
        }
    }
    return best;
}

