#include <bits/stdc++.h>

int shortestSequence(const std::vector<int>& rolls, int k) {
    int n = (int)rolls.size();
    std::vector<std::vector<int>> pos(k + 1);
    for (int i = 0; i < n; ++i) pos[rolls[i]].push_back(i);

    // length 1 check
    struct Node {
        std::vector<int> seq;
        int lastPos;
    };
    std::vector<Node> curr;
    for (int v = 1; v <= k; ++v) {
        if (pos[v].empty()) return 1;
        curr.push_back({std::vector<int>{v}, pos[v][0]});
    }

    int length = 1;
    while (true) {
        ++length;
        std::vector<Node> next;
        for (const Node& node : curr) {
            for (int v = 1; v <= k; ++v) {
                const auto& vec = pos[v];
                auto it = std::upper_bound(vec.begin(), vec.end(), node.lastPos);
                if (it == vec.end()) {
                    return length;
                } else {
                    Node nxt;
                    nxt.seq = node.seq;
                    nxt.seq.push_back(v);
                    nxt.lastPos = *it;
                    next.push_back(std::move(nxt));
                }
            }
        }
        curr.swap(next);
    }
}

