struct MinHeap {
    std::vector<int> arr;
    int peek() const { return arr[0]; }
    void push(int val) {
        arr.push_back(val);
        int i = (int)arr.size() - 1;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (arr[p] <= arr[i]) break;
            std::swap(arr[p], arr[i]);
            i = p;
        }
    }
    int pop() {
        if (arr.empty()) return -1;
        int root = arr[0];
        int last = arr.back();
        arr.pop_back();
        if (!arr.empty()) {
            arr[0] = last;
            int i = 0;
            while (true) {
                int l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                if (l < (int)arr.size() && arr[l] < arr[smallest]) smallest = l;
                if (r < (int)arr.size() && arr[r] < arr[smallest]) smallest = r;
                if (smallest == i) break;
                std::swap(arr[i], arr[smallest]);
                i = smallest;
            }
        }
        return root;
    }
    int size() const { return (int)arr.size(); }
};

struct NumberContainerSystem {
    std::unordered_map<int, int> indexToNum;
    std::unordered_map<int, MinHeap> numToHeap;
    void add(int number, int index) {
        // FIXED: original special-cased number==0 as a delete signal - see js_algo fix note.
        indexToNum[index] = number;
        numToHeap[number].push(index);
    }
    int query(int number) {
        auto it = numToHeap.find(number);
        if (it == numToHeap.end()) return -1;
        MinHeap &heap = it->second;
        while (heap.size()) {
            int idx = heap.peek();
            auto it2 = indexToNum.find(idx);
            if (it2 != indexToNum.end() && it2->second == number) break;
            heap.pop();
        }
        return heap.size() ? heap.peek() : -1;
    }
};

NumberContainerSystem NumberContainers() {
    return NumberContainerSystem();
}

