std::string bestHand(const std::vector<int>& ranks, const std::vector<char>& suits) {
    // Check for Flush: all suits identical
    bool isFlush = true;
    for (size_t i = 1; i < suits.size(); ++i) {
        if (suits[i] != suits[0]) {
            isFlush = false;
            break;
        }
    }
    if (isFlush) {
        return "Flush";
    }

    // Count occurrences of each rank
    std::unordered_map<int, int> freq;
    int maxCount = 0;
    for (int r : ranks) {
        int cnt = ++freq[r];
        if (cnt > maxCount) {
            maxCount = cnt;
        }
    }

    if (maxCount >= 3) {
        return "Three of a Kind";
    }
    if (maxCount == 2) {
        return "Pair";
    }
    return "High Card";
}

