long long countExcellentPairs(const std::vector<int>& nums, int k) {
    std::unordered_set<int> uniq(nums.begin(), nums.end());
    const int MAX_BITS = 60;
    std::vector<int> cnt(MAX_BITS + 1, 0);
    for (int x : uniq) {
        int pc = __builtin_popcount(x);
        cnt[pc]++;
    }
    long long ans = 0;
    for (int i = 0; i <= MAX_BITS; ++i) {
        if (cnt[i] == 0) continue;
        for (int j = 0; j <= MAX_BITS; ++j) {
            if (cnt[j] == 0) continue;
            if (i + j >= k) {
                ans += static_cast<long long>(cnt[i]) * cnt[j];
            }
        }
    }
    return ans;
}

