int equalPairs(const std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    std::unordered_map<std::string, int> rowMap;
    for (int i = 0; i < n; ++i) {
        const std::vector<int>& row = grid[i];
        std::string key;
        for (int j = 0; j < n; ++j) {
            key += std::to_string(row[j]);
            if (j < n - 1) key.push_back(',');
        }
        ++rowMap[key];
    }
    int result = 0;
    for (int j = 0; j < n; ++j) {
        std::string key;
        for (int i = 0; i < n; ++i) {
            key += std::to_string(grid[i][j]);
            if (i < n - 1) key.push_back(',');
        }
        auto it = rowMap.find(key);
        if (it != rowMap.end()) result += it->second;
    }
    return result;
}

