class FoodRatings {
public:
    FoodRatings(const std::vector<std::string>& foods,
                const std::vector<std::string>& cuisines,
                const std::vector<int>& ratings) {
        for (size_t i = 0; i < foods.size(); ++i) {
            const std::string& food = foods[i];
            const std::string& cuisine = cuisines[i];
            int rating = ratings[i];
            foodToCuisine[food] = cuisine;
            foodToRating[food] = rating;
            cuisineHeap[cuisine].push({rating, food});
        }
    }

    void changeRating(const std::string& food, int newRating) {
        const std::string& cuisine = foodToCuisine[food];
        foodToRating[food] = newRating;
        cuisineHeap[cuisine].push({newRating, food});
    }

    std::string highestRated(const std::string& cuisine) {
        auto& heap = cuisineHeap[cuisine];
        while (true) {
            const auto& top = heap.top();
            int currentRating = foodToRating[top.second];
            if (currentRating == top.first) {
                return top.second;
            }
            heap.pop();
        }
    }

private:
    struct Compare {
        bool operator()(const std::pair<int, std::string>& a,
                        const std::pair<int, std::string>& b) const {
            if (a.first != b.first) return a.first < b.first;
