int closestMeetingNode(const std::vector<int>& edges, int node1, int node2) {
    int n = static_cast<int>(edges.size());
    std::vector<int> dist1(n, -1);
    std::vector<int> dist2(n, -1);

    int cur = node1;
    int step = 0;
    while (cur != -1 && dist1[cur] == -1) {
        dist1[cur] = step++;
        cur = edges[cur];
    }

    cur = node2;
    step = 0;
    while (cur != -1 && dist2[cur] == -1) {
        dist2[cur] = step++;
        cur = edges[cur];
    }

    int bestNode = -1;
    int bestDist = std::numeric_limits<int>::max();

    for (int i = 0; i < n; ++i) {
        if (dist1[i] != -1 && dist2[i] != -1) {
            int curMax = dist1[i] > dist2[i] ? dist1[i] : dist2[i];
            if (curMax < bestDist || (curMax == bestDist && i < bestNode)) {
                bestDist = curMax;
                bestNode = i;
            }
        }
    }
    return bestNode;
}

