    int curSize = 0;
    int needSize = 1;
    int groups = 0;
    for (int g : grades) {
        curSum += g;
        ++curSize;
        if (curSize >= needSize && curSum > prevSum) {
            ++groups;
            prevSum = curSum;
            ++needSize;
            curSum = 0;
