long long taskSchedulerII(const std::vector<int>& tasks, int space) {
    if (tasks.empty()) {
        return 0;
    }
    std::unordered_map<int, long long> lastDay;
    long long day = -1;
    for (int t : tasks) {
        long long earliest = day + 1;
        auto it = lastDay.find(t);
        if (it != lastDay.end()) {
            earliest = std::max(earliest, it->second + static_cast<long long>(space) + 1);
        }
        day = earliest;
        lastDay[t] = day;
    }
    return day + 1;
}

