int longestCycle(const std::vector<int>& edges) {
    int n = static_cast<int>(edges.size());
    std::vector<bool> visited(n, false);
    int maxLen = -1;
    for (int start = 0; start < n; ++start) {
        if (visited[start]) continue;
        std::unordered_map<int, int> stepMap;
        int cur = start;
        int step = 0;
        while (cur != -1) {
            auto it = stepMap.find(cur);
            if (it != stepMap.end()) {
                int cycleLen = step - it->second;
                if (cycleLen > maxLen) maxLen = cycleLen;
                break;
            }
            if (visited[cur]) {
                break;
            }
            stepMap[cur] = step;
            visited[cur] = true;
            cur = edges[cur];
            ++step;
        }
    }
    return maxLen;
}

