long long minimumReplacement(const std::vector<int>& nums) {
    long long operations = 0;
    long long limit = nums.back();
    for (int i = static_cast<int>(nums.size()) - 2; i >= 0; --i) {
        if (nums[i] <= limit) {
            limit = nums[i];
        } else {
            long long parts = (static_cast<long long>(nums[i]) + limit - 1) / limit;
            operations += parts - 1;
            limit = static_cast<long long>(nums[i]) / parts;
        }
    }
    return operations;
}

