    for (int i = 2; i <= n; ++i) {
        if (dp[i - 2] && nums[i - 2] == nums[i - 1]) {
            dp[i] = true;
        }
        if (!dp[i] && i >= 3 && dp[i - 3] &&
            nums[i - 3] == nums[i - 2] && nums[i - 2] == nums[i - 1]) {
            dp[i] = true;
        }
        if (!dp[i] && i >= 3 && dp[i - 3] &&
            nums[i - 3] + 1 == nums[i - 2] && nums[i - 2] + 1 == nums[i - 1]) {
            dp[i] = true;
        }
    }
    return dp[n];
}

