int reachableNodes(int n, const std::vector<std::vector<int>>& edges, const std::vector<int>& restricted) {
    std::vector<std::vector<int>> graph(n);
    for (const auto& e : edges) {
        int a = e[0];
        int b = e[1];
        graph[a].push_back(b);
        graph[b].push_back(a);
