    for (int l = 1; l < len; ++l) {
        long long cur = 9;
        int avail = 9;
        for (int i = 0; i < l - 1; ++i) {
            cur *= avail;
            --avail;
        }
        ans += cur;
    }
    std::vector<bool> used(10, false);
    for (int i = 0; i < len; ++i) {
        int curDigit = s[i] - '0';
        for (int d = (i == 0 ? 1 : 0); d < curDigit; ++d) {
            if (used[d]) continue;
            int remaining = len - i - 1;
            int avail = 10 - (i + 1);
            long long add = 1;
            for (int k = 0; k < remaining; ++k) {
                add *= (avail - k);
            }
            ans += add;
        }
        if (used[curDigit]) {
            return static_cast<int>(ans);
        }
        used[curDigit] = true;
    }
    ans += 1;
    return static_cast<int>(ans);
}

