std::string shiftingLettersII(const std::string& s, const std::vector<std::vector<int>>& shifts) {
    int n = static_cast<int>(s.length());
    std::vector<int> diff(n + 1, 0);
    for (size_t i = 0; i < shifts.size(); ++i) {
        int l = shifts[i][0];
        int r = shifts[i][1];
        int dir = shifts[i][2];
        int delta = (dir == 1) ? 1 : -1;
        diff[l] += delta;
        diff[r + 1] -= delta;
    }
    int cur = 0;
    std::string result(n, ' ');
    for (int i = 0; i < n; ++i) {
        cur += diff[i];
        int shift = ((cur % 26) + 26) % 26;
        int originalCode = s[i] - 'a';
        int newCode = (originalCode + shift) % 26;
        result[i] = static_cast<char>(newCode + 'a');
    }
    return result;
}

