long long kthLargestSum(std::vector<int>& nums, int k) {
    long long base = 0;
    std::vector<long long> absVals;
    absVals.reserve(nums.size());
    for (int x : nums) {
        if (x >= 0) {
            base += x;
            absVals.push_back(x);
        } else {
            absVals.push_back(-static_cast<long long>(x));
        }
    }
    std::sort(absVals.begin(), absVals.end());
    std::vector<long long> smallest;
    smallest.reserve(k);
    smallest.push_back(0);
    struct Node { long long sum; int idx; };
    struct Cmp {
        bool operator()(const Node& a, const Node& b) const {
            return a.sum > b.sum;
        }
    };
    std::priority_queue<Node, std::vector<Node>, Cmp> pq;
    std::set<std::pair<int, long long>> visited;
    if (!absVals.empty()) {
        pq.push({absVals[0], 0});
        visited.insert({0, absVals[0]});
    }
    while ((int)smallest.size() < k && !pq.empty()) {
        Node cur = pq.top(); pq.pop();
        smallest.push_back(cur.sum);
        int i = cur.idx;
        if (i + 1 < (int)absVals.size()) {
            long long sum1 = cur.sum - absVals[i] + absVals[i + 1];
            std::pair<int, long long> p1 = {i + 1, sum1};
            if (!visited.count(p1)) {
                visited.insert(p1);
                pq.push({sum1, i + 1});
            }
            long long sum2 = cur.sum + absVals[i + 1];
            std::pair<int, long long> p2 = {i + 1, sum2};
            if (!visited.count(p2)) {
                visited.insert(p2);
                pq.push({sum2, i + 1});
            }
        }
    }
    long long cost = smallest[k - 1];
    return base - cost;
}

