struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

void dfs(TreeNode* node, TreeNode* parent, std::unordered_map<int, std::vector<int>>& adj) {
    if (!node) return;
    if (adj.find(node->val) == adj.end()) adj[node->val] = std::vector<int>();
    if (parent) {
        if (adj.find(parent->val) == adj.end()) adj[parent->val] = std::vector<int>();
        adj[node->val].push_back(parent->val);
        adj[parent->val].push_back(node->val);
    }
    dfs(node->left, node, adj);
    dfs(node->right, node, adj);
}

int amountOfTime(TreeNode* root, int start) {
    std::unordered_map<int, std::vector<int>> adj;
    dfs(root, nullptr, adj);
    std::unordered_set<int> visited;
    std::queue<int> q;
    q.push(start);
    visited.insert(start);
    int minutes = -1;
    while (!q.empty()) {
        int size = q.size();
        for (int i = 0; i < size; ++i) {
            int cur = q.front();
            q.pop();
            auto it = adj.find(cur);
            if (it != adj.end()) {
                for (int nb : it->second) {
                    if (visited.find(nb) == visited.end()) {
                        visited.insert(nb);
                        q.push(nb);
                    }
                }
            }
        }
        ++minutes;
    }
    return minutes;
}

