std::vector<int> longestSubsequenceWithLimitedSum(const std::vector<int>& nums, const std::vector<int>& queries) {
    std::vector<int> sorted(nums);
    std::sort(sorted.begin(), sorted.end());

    std::vector<long long> prefix(sorted.size());
    long long running = 0;
    for (size_t i = 0; i < sorted.size(); ++i) {
        running += sorted[i];
        prefix[i] = running;
    }

    std::vector<int> answers(queries.size());
    for (size_t q = 0; q < queries.size(); ++q) {
        int limit = queries[q];
        int lo = 0;
        int hi = static_cast<int>(sorted.size()) - 1;
        int best = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (prefix[mid] <= limit) {
                best = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        answers[q] = best + 1;
    }
    return answers;
}

