std::vector<std::vector<int>> buildMatrix(int k, const std::vector<std::vector<int>>& rowConditions, const std::vector<std::vector<int>>& colConditions) {
    auto topologicalSort = [&](const std::vector<std::vector<int>>& conditions) -> std::vector<int> {
        std::vector<std::vector<int>> adj(k + 1);
        std::vector<int> indeg(k + 1, 0);
        for (const auto& p : conditions) {
            int u = p[0];
            int v = p[1];
            adj[u].push_back(v);
            ++indeg[v];
        }
        std::queue<int> q;
        for (int i = k; i >= 1; --i) {
            if (indeg[i] == 0) {
                q.push(i);
            }
        }
        std::vector<int> order;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            order.push_back(u);
            for (int v : adj[u]) {
                if (--indeg[v] == 0) {
                    q.push(v);
                }
            }
        }
        if ((int)order.size() != k) {
            return {};
        }
        return order;
    };

    std::vector<int> rowOrder = topologicalSort(rowConditions);
    std::vector<int> colOrder = topologicalSort(colConditions);
    if (rowOrder.empty() || colOrder.empty()) {
        return {};
    }

    std::vector<int> rowPos(k + 1), colPos(k + 1);
    for (int i = 0; i < k; ++i) {
        rowPos[rowOrder[i]] = i;
        colPos[colOrder[i]] = i;
    }

    std::vector<std::vector<int>> matrix(k, std::vector<int>(k, 0));
    for (int num = 1; num <= k; ++num) {
        matrix[rowPos[num]][colPos[num]] = num;
    }
    return matrix;
}

