int maxRowsCovered(const std::vector<std::vector<int>>& matrix, int numSelect) {
    int m = static_cast<int>(matrix.size());
    int n = static_cast<int>(matrix[0].size());
    std::vector<unsigned int> rowMasks(m);
    for (int i = 0; i < m; ++i) {
        unsigned int mask = 0;
        for (int j = 0; j < n; ++j) {
            if (matrix[i][j] == 1) mask |= (1u << j);
        }
        rowMasks[i] = mask;
    }
    int best = 0;
    std::function<void(int, unsigned int, int)> dfs = [&](int start, unsigned int chosenMask, int chosenCnt) {
        if (chosenCnt == numSelect) {
            int covered = 0;
            for (int i = 0; i < m; ++i) {
                if ((rowMasks[i] & ~chosenMask) == 0) ++covered;
            }
            if (covered > best) best = covered;
            return;
        }
        for (int col = start; col < n; ++col) {
            dfs(col + 1, chosenMask | (1u << col), chosenCnt + 1);
        }
    };
    dfs(0, 0u, 0);
    return best;
}

