int maxRobots(const std::vector<long long>& chargeTimes, const std::vector<long long>& runningCosts, long long budget) {
    int n = static_cast<int>(chargeTimes.size());
    int left = 0;
    long long sumRunning = 0;
    int best = 0;
    std::deque<int> maxDeque;
    for (int right = 0; right < n; ++right) {
        sumRunning += runningCosts[right];
        while (!maxDeque.empty() && chargeTimes[maxDeque.back()] <= chargeTimes[right]) {
            maxDeque.pop_back();
        }
        maxDeque.push_back(right);
        while (left <= right) {
            long long currentMax = chargeTimes[maxDeque.front()];
            long long totalCost = currentMax + static_cast<long long>(right - left + 1) * sumRunning;
            if (totalCost <= budget) break;
            if (maxDeque.front() == left) {
                maxDeque.pop_front();
            }
            sumRunning -= runningCosts[left];
            ++left;
        }
        best = std::max(best, right - left + 1);
    }
    return best;
}

