const int MOD = 1000000007;

long long modPow(long long a, long long e) {
    long long res = 1;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

int numberOfWays(int startPos, int endPos, int k) {
    int dist = std::abs(endPos - startPos);
    if (dist > k) return 0;
    if ((k - dist) % 2 != 0) return 0;
    int r = (k + dist) / 2; // number of right moves
    std::vector<long long> fact(k + 1), invFact(k + 1);
    fact[0] = 1;
    for (int i = 1; i <= k; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[k] = modPow(fact[k], MOD - 2);
    for (int i = k; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;
    long long ans = fact[k] * invFact[r] % MOD * invFact[k - r] % MOD;
    return static_cast<int>(ans);
}

