int longestNiceSubarray(const std::vector<int>& nums) {
    std::size_t left = 0;
    long long mask = 0;
    int best = 0;
    for (std::size_t right = 0; right < nums.size(); ++right) {
        long long cur = nums[right];
        while ((mask & cur) != 0) {
            mask ^= nums[left];
            ++left;
        }
        mask |= cur;
        int len = static_cast<int>(right - left + 1);
        if (len > best) best = len;
    }
    return best;
}

