int mostBooked(int n, std::vector<std::vector<int>>& meetings) {
    std::sort(meetings.begin(), meetings.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[0] < b[0];
              });

    std::priority_queue<int, std::vector<int>, std::greater<int>> freeRooms;
    for (int i = 0; i < n; ++i) {
        freeRooms.push(i);
    }

    struct Busy {
        long long end;
        int room;
    };
    struct BusyCmp {
        bool operator()(const Busy& a, const Busy& b) const {
            if (a.end != b.end) return a.end > b.end;
            return a.room > b.room;
        }
    };
    std::priority_queue<Busy, std::vector<Busy>, BusyCmp> busyRooms;

    std::vector<int> count(n, 0);

    for (const auto& meeting : meetings) {
        long long start = meeting[0];
        long long end = meeting[1];

        while (!busyRooms.empty() && busyRooms.top().end <= start) {
            int freedRoom = busyRooms.top().room;
            busyRooms.pop();
            freeRooms.push(freedRoom);
        }

        if (!freeRooms.empty()) {
            int room = freeRooms.top();
            freeRooms.pop();
            ++count[room];
            busyRooms.push({end, room});
        } else {
            Busy earliest = busyRooms.top();
            busyRooms.pop();
            long long duration = end - start;
            long long newEnd = earliest.end + duration;
            ++count[earliest.room];
            busyRooms.push({newEnd, earliest.room});
        }
    }

    int bestRoom = 0;
    for (int i = 1; i < n; ++i) {
        if (count[i] > count[bestRoom]) {
            bestRoom = i;
        }
    }
    return bestRoom;
}

