int minimumSwap(const std::string& s1, const std::string& s2) {
    int xy = 0, yx = 0;
    for (std::size_t i = 0; i < s1.size(); ++i) {
        if (s1[i] == s2[i]) continue;
        if (s1[i] == 'x' && s2[i] == 'y') ++xy;
        else ++yx; // s1[i]=='y' && s2[i]=='x'
    }
    if ((xy + yx) % 2 != 0) return -1;
    return xy / 2 + yx / 2 + (xy % 2) * 2;
}

