std::string minRemoveToMakeValid(const std::string& s) {
    std::vector<std::size_t> stack;
    std::unordered_set<std::size_t> toRemove;
    for (std::size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '(') {
            stack.push_back(i);
        } else if (s[i] == ')') {
            if (stack.empty()) {
                toRemove.insert(i);
            } else {
                stack.pop_back();
            }
        }
    }
    while (!stack.empty()) {
        toRemove.insert(stack.back());
        stack.pop_back();
    }
    std::string result;
    result.reserve(s.size());
    for (std::size_t i = 0; i < s.size(); ++i) {
        if (toRemove.find(i) == toRemove.end()) {
            result.push_back(s[i]);
        }
    }
    return result;
}

