int tilingRectangle(int n, int m) {
    if (n > m) std::swap(n, m);
    int best = INT_MAX;
    std::vector<int> height(m, 0);
    std::function<void(int)> dfs = [&](int used) {
        if (used >= best) return;
        int minH = INT_MAX, idx = -1;
        for (int i = 0; i < m; ++i) {
            if (height[i] < minH) {
                minH = height[i];
                idx = i;
            }
        }
        if (minH == n) {
            best = used;
            return;
        }
        int curH = height[idx];
        int maxWidth = 0;
        for (int j = idx; j < m && height[j] == curH; ++j) ++maxWidth;
        int maxSize = std::min({maxWidth, n - curH});
        for (int size = maxSize; size >= 1; --size) {
            for (int k = idx; k < idx + size; ++k) height[k] += size;
            dfs(used + 1);
            for (int k = idx; k < idx + size; ++k) height[k] -= size;
        }
    };
    dfs(0);
    return best;
}

