int jobScheduling(const std::vector<int>& startTime, const std::vector<int>& endTime, const std::vector<int>& profit) {
    std::size_t n = startTime.size();
    if (n == 0) return 0;
    std::vector<std::array<int, 3>> jobs;
    jobs.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        jobs.push_back({startTime[i], endTime[i], profit[i]});
    }
    std::sort(jobs.begin(), jobs.end(), [](const std::array<int, 3>& a, const std::array<int, 3>& b) {
        return a[1] < b[1];
    });
    std::vector<int> dp(n, 0);
    dp[0] = jobs[0][2];
    for (std::size_t i = 1; i < n; ++i) {
        int maxProfit = jobs[i][2];
        for (std::size_t j = i; j-- > 0;) {
            if (jobs[j][1] <= jobs[i][0]) {
                maxProfit += dp[j];
                break;
            }
        }
        dp[i] = std::max(maxProfit, dp[i - 1]);
    }
    return dp[n - 1];
}

