void dfs(std::vector<std::vector<int>>& grid, int i, int j) {
    if (i < 0 || i >= static_cast<int>(grid.size()) || j < 0 || j >= static_cast<int>(grid[0].size())) return;
    if (grid[i][j] != 0) return;
    grid[i][j] = 1;
    dfs(grid, i - 1, j);
    dfs(grid, i + 1, j);
    dfs(grid, i, j - 1);
    dfs(grid, i, j + 1);
}

int closedIsland(std::vector<std::vector<int>>& grid) {
    for (int i = 0; i < static_cast<int>(grid.size()); ++i) {
        dfs(grid, i, 0);
        dfs(grid, i, static_cast<int>(grid[0].size()) - 1);
    }
    for (int j = 0; j < static_cast<int>(grid[0].size()); ++j) {
        dfs(grid, 0, j);
        dfs(grid, static_cast<int>(grid.size()) - 1, j);
    }
    int count = 0;
    for (int i = 1; i < static_cast<int>(grid.size()) - 1; ++i) {
        for (int j = 1; j < static_cast<int>(grid[0].size()) - 1; ++j) {
            if (grid[i][j] == 0) {
                ++count;
                dfs(grid, i, j);
            }
        }
    }
    return count;
}

