int maxScoreWords(const std::vector<std::string>& words, const std::vector<char>& letters, const std::vector<int>& score) {
    std::unordered_map<char, int> letterCount;
    for (char letter : letters) {
        ++letterCount[letter];
    }
    int maxScore = 0;
    std::function<void(int, int, const std::unordered_map<char, int>&)> backtrack;
    backtrack = [&](int index, int currentScore, const std::unordered_map<char, int>& currentLetterCount) {
        if (currentScore > maxScore) {
            maxScore = currentScore;
        }
        for (int i = index; i < static_cast<int>(words.size()); ++i) {
            const std::string& word = words[i];
            int wordScore = 0;
            std::unordered_map<char, int> wordLetterCount;
            for (char ch : word) {
                ++wordLetterCount[ch];
                wordScore += score[ch - 'a'];
            }
            bool isValid = true;
            for (const auto& kv : wordLetterCount) {
                char letter = kv.first;
                int needed = kv.second;
                auto it = currentLetterCount.find(letter);
                if (it == currentLetterCount.end() || needed > it->second) {
                    isValid = false;
                    break;
                }
            }
            if (isValid) {
                std::unordered_map<char, int> newLetterCount = currentLetterCount;
                for (const auto& kv : wordLetterCount) {
                    newLetterCount[kv.first] -= kv.second;
                }
                backtrack(i + 1, currentScore + wordScore, newLetterCount);
            }
        }
    };
    backtrack(0, 0, letterCount);
    return maxScore;
}

