int mostFrequentEvenElement(const std::vector<int>& nums) {
    std::unordered_map<int, int> frequency;
    for (int num : nums) {
        if (frequency.find(num) != frequency.end()) {
            frequency[num]++;
        } else {
            frequency[num] = 1;
        }
    }
    int maxFrequency = 0;
    int result = -1;
    for (const auto& pair : frequency) {
        int num = pair.first;
        int freq = pair.second;
        if (num % 2 == 0 && freq > maxFrequency) {
            maxFrequency = freq;
            result = num;
        } else if (num % 2 == 0 && freq == maxFrequency) {
            result = std::min(result, num);
        }
    }
    return result;
}

