std::vector<int> smallestSubarraysWithMaximumBitwiseOR(const std::vector<int>& nums) {
    std::vector<int> result(nums.size());
    for (size_t i = 0; i < nums.size(); ++i) {
        int maxOr = 0;
        for (size_t j = i; j < nums.size(); ++j) {
            int orVal = 0;
            for (size_t k = i; k <= j; ++k) {
                orVal |= nums[k];
            }
            if (orVal > maxOr) {
                maxOr = orVal;
                result[i] = static_cast<int>(j - i + 1);
            } else if (orVal == maxOr) {
                int current = result[i];
                if (current == 0) current = INT_MAX;
                result[i] = std::min(current, static_cast<int>(j - i + 1));
            }
        }
    }
    return result;
}

