TreeNode* reverseOddLevels(TreeNode* root) {
    if (!root) return nullptr;
    vector<TreeNode*> queue = {root};
    int level = 0;
    while (!queue.empty()) {
        vector<TreeNode*> nextQueue;
        if (level % 2 == 1) {
            int i = 0, j = (int)queue.size() - 1;
            while (i < j) {
                swap(queue[i]->val, queue[j]->val);
                i++; j--;
            }
        }
        for (auto node : queue) {
            if (node->left) nextQueue.push_back(node->left);
            if (node->right) nextQueue.push_back(node->right);
        }
        queue = nextQueue;
        level++;
    }
    return root;
}

