int countDaysTogether(const std::string& arriveAlice, const std::string& leaveAlice,
                      const std::string& arriveBob, const std::string& leaveBob) {
    static const int daysInMonth[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    auto dateToDay = [&](const std::string& date) -> int {
        size_t dash = date.find('-');
        int month = std::stoi(date.substr(0, dash));
        int day = std::stoi(date.substr(dash + 1));
        int totalDays = 0;
        for (int i = 0; i < month - 1; ++i) {
            totalDays += daysInMonth[i];
        }
        return totalDays + day;
    };
    int startAlice = dateToDay(arriveAlice);
    int endAlice = dateToDay(leaveAlice);
    int startBob = dateToDay(arriveBob);
    int endBob = dateToDay(leaveBob);
    int overlapStart = std::max(startAlice, startBob);
    int overlapEnd = std::min(endAlice, endBob);
    if (overlapStart > overlapEnd) {
        return 0;
    }
    return overlapEnd - overlapStart + 1;
}

