int minGroups(std::vector<std::vector<int>>& intervals) {
    if (intervals.empty()) return 0;
    std::vector<int> starts, ends;
    starts.reserve(intervals.size());
    ends.reserve(intervals.size());
    for (const auto& iv : intervals) {
        starts.push_back(iv[0]);
        ends.push_back(iv[1]);
    }
    std::sort(starts.begin(), starts.end());
    std::sort(ends.begin(), ends.end());
    int i = 0, j = 0, cur = 0, ans = 0;
    while (i < static_cast<int>(starts.size())) {
        if (starts[i] > ends[j]) {
            --cur;
            ++j;
        } else {
            ++cur;
            ans = std::max(ans, cur);
            ++i;
        }
    }
    return ans;
}

#include <bits/stdc++.h>

int findLengthOfLCIS(const std::vector<int>& nums, int k) {
    if (nums.empty()) return 0;
    std::vector<int> vals = nums;
    std::sort(vals.begin(), vals.end());
    vals.erase(std::unique(vals.begin(), vals.end()), vals.end());
    int m = static_cast<int>(vals.size());
    std::vector<int> seg(2 * m, 0);
    auto segUpdate = [&](int pos, int value) {
        pos += m;
        seg[pos] = std::max(seg[pos], value);
        for (pos >>= 1; pos; pos >>= 1) {
            seg[pos] = std::max(seg[pos << 1], seg[(pos << 1) | 1]);
        }
    };
    auto segQuery = [&](int l, int r) {
        int res = 0;
        l += m;
        r += m;
        while (l <= r) {
            if (l & 1) res = std::max(res, seg[l++]);
            if (!(r & 1)) res = std::max(res, seg[r--]);
            l >>= 1;
            r >>= 1;
        }
        return res;
    };
    int answer = 0;
    for (int num : nums) {
        int leftVal = num - k;
        int rightVal = num - 1;
        int lIdx = static_cast<int>(std::lower_bound(vals.begin(), vals.end(), leftVal) - vals.begin());
        int rIdx = static_cast<int>(std::upper_bound(vals.begin(), vals.end(), rightVal) - vals.begin()) - 1;
        int best = 0;
        if (lIdx <= rIdx && lIdx < m && rIdx >= 0) {
            best = segQuery(lIdx, rIdx);
        }
        int cur = best + 1;
        int pos = static_cast<int>(std::lower_bound(vals.begin(), vals.end(), num) - vals.begin());
        segUpdate(pos, cur);
        answer = std::max(answer, cur);
    }
    return answer;
}

