std::vector<int> sumPrefixScores(const std::vector<std::string>& words) {
    std::vector<int> answer(words.size(), 0);
    std::unordered_map<std::string, int> prefixCount;
    for (const std::string& word : words) {
        for (size_t i = 1; i <= word.size(); ++i) {
            std::string prefix = word.substr(0, i);
            ++prefixCount[prefix];
        }
    }
    for (size_t i = 0; i < words.size(); ++i) {
        const std::string& word = words[i];
        for (size_t j = 1; j <= word.size(); ++j) {
            std::string prefix = word.substr(0, j);
            answer[i] += prefixCount[prefix];
        }
    }
    return answer;
}

