std::vector<long long> maximumSegmentSum(const std::vector<int>& nums, const std::vector<int>& removeQueries) {
    int n = static_cast<int>(nums.size());
    std::vector<int> parent(n);
    std::vector<long long> segSum(n);
    std::vector<char> active(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto unite = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        parent[rb] = ra;
        segSum[ra] += segSum[rb];
    };

    std::vector<long long> answer(n);
    long long maxSum = 0;

    for (int i = n - 1; i >= 0; --i) {
        answer[i] = maxSum;
        int idx = removeQueries[i];
        active[idx] = 1;
        parent[idx] = idx;
        segSum[idx] = nums[idx];

        if (idx > 0 && active[idx - 1]) unite(idx, idx - 1);
        if (idx < n - 1 && active[idx + 1]) unite(idx, idx + 1);

        int root = find(idx);
        if (segSum[root] > maxSum) maxSum = segSum[root];
    }

    return answer;
}

