int minimizeXor(int num1, int num2) {
    int k = __builtin_popcount(num2);
    int x = 0;
    // First, set bits where num1 has 1
    for (int i = 0; i < 31; ++i) {
        if (k == 0) break;
        if ((num1 >> i) & 1) {
            x |= (1 << i);
            --k;
        }
    }
    // Then, set remaining bits where num1 has 0, preferring lower positions
    for (int i = 0; i < 31 && k > 0; ++i) {
        if (!((num1 >> i) & 1)) {
            x |= (1 << i);
            --k;
        }
    }
    return x;
}

