    std::vector<std::vector<int>> lcp(n + 1, std::vector<int>(n + 1, 0));
    for (int i = n - 1; i >= 0; --i) {
        for (int j = n - 1; j >= 0; --j) {
            if (s[i] == s[j]) {
                lcp[i][j] = 1 + lcp[i + 1][j + 1];
            }
        }
    }
    std::vector<int> dp(n + 1, 0);
    dp[n] = 0;
    for (int i = n - 1; i >= 0; --i) {
        dp[i] = 1; // delete the whole remaining suffix in one operation
        for (int len = 1; i + 2 * len <= n; ++len) {
            if (lcp[i][i + len] >= len) {
                dp[i] = std::max(dp[i], 1 + dp[i + len]);
            }
        }
    }
    return dp[0];
}

