static const long long MOD = 1000000007LL;

static long long modPow(long long base, long long exp) {
    long long result = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1LL) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1LL;
    }
    return result;
}

std::vector<long long> productQueries(long long n, const std::vector<std::vector<int>>& queries) {
    std::vector<long long> powers;
    while (n > 0) {
        long long lsb = n & -n;
        powers.push_back(lsb);
        n -= lsb;
    }
    std::vector<long long> prefix(powers.size() + 1, 1);
    for (std::size_t i = 0; i < powers.size(); ++i) {
        prefix[i + 1] = (prefix[i] * (powers[i] % MOD)) % MOD;
    }
    std::vector<long long> result;
    result.reserve(queries.size());
    for (const auto& q : queries) {
        int left = q[0];
        int right = q[1];
        long long prod = prefix[right + 1];
        long long inv = modPow(prefix[left], MOD - 2);
        prod = (prod * inv) % MOD;
        result.push_back(prod);
    }
    return result;
}

