int componentValue(const std::vector<int>& nums, const std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(nums.size());
    if (n == 1) return 0;
    long long totalSum = 0;
    for (int v : nums) totalSum += v;
    std::vector<std::vector<int>> graph(n);
    for (const auto& e : edges) {
        graph[e[0]].push_back(e[1]);
        graph[e[1]].push_back(e[0]);
    }
    int answer = -1;
    for (int k = n; k >= 1; --k) {
        if (totalSum % k != 0) continue;
        long long target = totalSum / k;
        int components = 0;
        std::function<long long(int,int)> dfs = [&](int u, int parent) -> long long {
            long long sum = nums[u];
            for (int v : graph[u]) {
                if (v == parent) continue;
                sum += dfs(v, u);
            }
            if (sum == target) {
                ++components;
                return 0;
            }
            return sum;
        };
        long long rootSum = dfs(0, -1);
        if (rootSum == 0 && components == k) {
            answer = std::max(answer, k - 1);
        }
    }
    return answer;
}

