const int MOD = 1000000007;

int numberOfPaths(std::vector<std::vector<int>>& grid, int k) {
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<std::vector<int>>> dp(m, std::vector<std::vector<int>>(n, std::vector<int>(k, 0)));
    dp[0][0][grid[0][0] % k] = 1;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            for (int r = 0; r < k; ++r) {
                int cur = dp[i][j][r];
                if (!cur) continue;
                if (i + 1 < m) {
                    int nr = (r + grid[i + 1][j]) % k;
                    dp[i + 1][j][nr] += cur;
                    if (dp[i + 1][j][nr] >= MOD) dp[i + 1][j][nr] -= MOD;
                }
                if (j + 1 < n) {
                    int nr = (r + grid[i][j + 1]) % k;
                    dp[i][j + 1][nr] += cur;
                    if (dp[i][j + 1][nr] >= MOD) dp[i][j + 1][nr] -= MOD;
                }
            }
        }
    }
    return dp[m - 1][n - 1][0];
