    std::vector<char> minSuf(n);
    minSuf[n - 1] = s[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        minSuf[i] = std::min(s[i], minSuf[i + 1]);
    }
    std::string ans;
    ans.reserve(n);
    std::vector<char> stack;
    stack.reserve(n);
    for (int i = 0; i < n; ++i) {
        stack.push_back(s[i]);
        while (!stack.empty() && (i == n - 1 || stack.back() <= minSuf[i + 1])) {
            ans.push_back(stack.back());
            stack.pop_back();
        }
    }
    return ans;
}

