std::vector<std::vector<std::string>> mostPopularCreator(const std::vector<std::string>& creators, const std::vector<std::string>& ids, const std::vector<int>& views) {
    struct Info {
        long long totalViews;
        int maxViews;
        std::string maxViewId;
    };
    std::unordered_map<std::string, Info> creatorPopularity;
    for (size_t i = 0; i < creators.size(); ++i) {
        const std::string& creator = creators[i];
        const std::string& vid = ids[i];
        int viewCount = views[i];
        auto it = creatorPopularity.find(creator);
        if (it != creatorPopularity.end()) {
            it->second.totalViews += viewCount;
            if (viewCount > it->second.maxViews || (viewCount == it->second.maxViews && vid < it->second.maxViewId)) {
                it->second.maxViews = viewCount;
                it->second.maxViewId = vid;
            }
        } else {
            creatorPopularity.emplace(creator, Info{viewCount, viewCount, vid});
        }
    }

    long long maxPopularity = 0;
    for (const auto& kv : creatorPopularity) {
        maxPopularity = std::max(maxPopularity, kv.second.totalViews);
    }

    std::vector<std::vector<std::string>> result;
    for (const auto& kv : creatorPopularity) {
        if (kv.second.totalViews == maxPopularity) {
            result.push_back({kv.first, kv.second.maxViewId});
        }
    }
    std::sort(result.begin(), result.end(), [](const std::vector<std::string>& a, const std::vector<std::string>& b) {
        return a[0] < b[0];
    });
    return result;
}

