std::vector<int> secondGreaterElement(const std::vector<int>& nums) {
    std::vector<int> result(nums.size(), -1);
    std::vector<int> firstStack;
    std::vector<int> secondStack;
    for (size_t i = 0; i < nums.size(); ++i) {
        while (!secondStack.empty() && nums[secondStack.back()] < nums[i]) {
            result[secondStack.back()] = static_cast<int>(nums[i]);
            secondStack.pop_back();
        }
        while (!firstStack.empty() && nums[firstStack.back()] < nums[i]) {
            secondStack.push_back(firstStack.back());
            firstStack.pop_back();
        }
        firstStack.push_back(static_cast<int>(i));
    }
    return result;
}

