int maximumSum(const std::vector<int>& nums, int k) {
    int maxSum = 0;
    int n = static_cast<int>(nums.size());
    for (int i = 0; i <= n - k; ++i) {
        int currentSum = 0;
        std::unordered_set<int> uniqueElements;
        for (int j = i; j < i + k; ++j) {
            currentSum += nums[j];
            uniqueElements.insert(nums[j]);
        }
        if (static_cast<int>(uniqueElements.size()) == k) {
            maxSum = std::max(maxSum, currentSum);
        }
    }
    return maxSum;
}

