std::vector<int> applyOperations(std::vector<int> nums) {
    size_t n = nums.size();
    for (size_t i = 0; i + 1 < n; ++i) {
        if (nums[i] == nums[i + 1]) {
            nums[i] *= 2;
            nums[i + 1] = 0;
        }
    }
    size_t left = 0, right = 0;
    while (right < n) {
        if (nums[right] != 0) {
            std::swap(nums[left], nums[right]);
            ++left;
        }
        ++right;
    }
    return nums;
}

