long long destroyTargets(const std::vector<long long>& nums, long long space) {
    std::unordered_map<long long, std::vector<long long>> countMap;
    for (long long num : nums) {
        long long remainder = num % space;
        countMap[remainder].push_back(num);
    }
    long long maxCount = 0;
    long long minSeed = std::numeric_limits<long long>::max();
    for (auto& entry : countMap) {
        long long count = entry.second.size();
        if (count > maxCount) {
            maxCount = count;
            minSeed = *std::min_element(entry.second.begin(), entry.second.end());
        } else if (count == maxCount) {
            long long candidate = *std::min_element(entry.second.begin(), entry.second.end());
            if (candidate < minSeed) {
                minSeed = candidate;
            }
        }
    }
    return minSeed;
}

