long long mostProfitablePath(const std::vector<std::vector<int>>& edges, int bob, const std::vector<int>& amount) {
    int n = static_cast<int>(amount.size());
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::vector<int> depthRoot(n, -1);
    std::vector<int> parent(n, -1);
    std::stack<int> st;
    st.push(0);
    depthRoot[0] = 0;
    while (!st.empty()) {
        int u = st.top(); st.pop();
        for (int v : adj[u]) {
            if (v == parent[u]) continue;
            parent[v] = u;
            depthRoot[v] = depthRoot[u] + 1;
            st.push(v);
        }
    }

    const int INF = 1e9;
    std::vector<int> depthBob(n, INF);
    int cur = bob;
    int d = 0;
    while (true) {
        depthBob[cur] = d;
        if (cur == 0) break;
        cur = parent[cur];
        ++d;
    }

    std::vector<long long> contrib(n, 0);
    for (int i = 0; i < n; ++i) {
        if (depthRoot[i] < depthBob[i]) {
            contrib[i] = amount[i];
        } else if (depthRoot[i] == depthBob[i]) {
            contrib[i] = amount[i] / 2;
        } else {
            contrib[i] = 0;
        }
    }

    long long best = LLONG_MIN;
    std::stack<std::pair<int, long long>> dfs;
    dfs.emplace(0, contrib[0]);
    while (!dfs.empty()) {
        std::pair<int, long long> curPair = dfs.top(); dfs.pop();
        int u = curPair.first;
        long long sum = curPair.second;
        bool isLeaf = (u != 0 && adj[u].size() == 1);
        if (isLeaf) {
            if (sum > best) best = sum;
        }
        for (int v : adj[u]) {
            if (v == parent[u]) continue;
            dfs.emplace(v, sum + contrib[v]);
        }
    }
    return best;
}

