int countSubarraysWithMedianK(const std::vector<int>& nums, int k) {
    std::size_t n = nums.size();
    std::size_t kPos = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (nums[i] == k) {
            kPos = i;
            break;
        }
    }
    std::unordered_map<long long, int> leftFreq;
    long long sum = 0;
    leftFreq[0] = 1;
    for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(kPos) - 1; i >= 0; --i) {
        sum += (nums[i] > k) ? 1 : -1;
        ++leftFreq[sum];
    }
    long long result = 0;
    sum = 0;
    for (std::size_t i = kPos; i < n; ++i) {
        if (nums[i] > k) {
            sum += 1;
        } else if (nums[i] < k) {
            sum -= 1;
        }
        result += leftFreq[-sum];
        result += leftFreq[1 - sum];
    }
    return static_cast<int>(result);
}

