struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* removeNodes(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* cur = head;
    while (cur) {
        ListNode* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    ListNode* revHead = prev;

    int maxSeen = std::numeric_limits<int>::min();
    ListNode dummy(0);
    ListNode* tail = &dummy;
    cur = revHead;
    while (cur) {
        if (cur->val >= maxSeen) {
            maxSeen = cur->val;
            tail->next = cur;
            tail = cur;
        }
        cur = cur->next;
    }
    tail->next = nullptr;

    prev = nullptr;
    cur = dummy.next;
    while (cur) {
        ListNode* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    return prev;
}

