int subarrayLCM(const std::vector<int>& nums, int k) {
    int count = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        long long currentLcm = nums[i];
        for (size_t j = i; j < nums.size(); ++j) {
            currentLcm = lcm_ll(currentLcm, static_cast<long long>(nums[j]));
            if (currentLcm == k) ++count;
            if (currentLcm > k) break;
        }
    }
    return count;
}

