int magnificentSets(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::vector<bool> visited(n + 1, false);
    std::vector<int> color(n + 1, -1);
    int totalGroups = 0;

    for (int i = 1; i <= n; ++i) {
        if (visited[i]) continue;

        std::vector<int> comp;
        std::vector<int> queue;
        queue.push_back(i);
        visited[i] = true;
        color[i] = 0;
        comp.push_back(i);
        bool bipartite = true;
        for (size_t qIdx = 0; qIdx < queue.size(); ++qIdx) {
            int u = queue[qIdx];
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    color[v] = color[u] ^ 1;
                    queue.push_back(v);
                    comp.push_back(v);
                } else if (color[v] == color[u]) {
                    bipartite = false;
                }
            }
        }
        if (!bipartite) return -1;

        int diameter = 0;
        for (int start : comp) {
            std::vector<int> dist(n + 1, -1);
            std::vector<int> q;
            q.push_back(start);
            dist[start] = 0;
            for (size_t idx = 0; idx < q.size(); ++idx) {
                int u = q[idx];
                for (int v : adj[u]) {
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        q.push_back(v);
                    }
                }
            }
            for (int node : comp) {
                if (dist[node] > diameter) diameter = dist[node];
            }
        }

        totalGroups += diameter + 1;
    }

    return totalGroups;
}

