int longestSquareStreak(std::vector<int>& nums) {
    std::sort(nums.begin(), nums.end());
    std::unordered_map<int, int> dp;
    int best = 0;
    for (int x : nums) {
        long long r = static_cast<long long>(std::sqrt(x));
        while (r * r > x) --r;
        while ((r + 1) * (r + 1) <= x) ++r;
        int cur = 1;
        if (r * r == x) {
            auto it = dp.find(static_cast<int>(r));
            if (it != dp.end()) cur = it->second + 1;
        }
        auto it = dp.find(x);
        if (it == dp.end() || cur > it->second) dp[x] = cur;
        if (cur > best) best = cur;
    }
    return best >= 2 ? best : -1;
}

