long long totalCost(const std::vector<int>& costs, int k, int candidates) {
    int n = static_cast<int>(costs.size());
    long long total = 0;
    int left = 0, right = n - 1;
    using P = std::pair<int, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> leftHeap, rightHeap;

    for (int i = 0; i < candidates && left <= right; ++i) {
        leftHeap.emplace(costs[left], left);
        ++left;
    }
    for (int i = 0; i < candidates && left <= right; ++i) {
        rightHeap.emplace(costs[right], right);
        --right;
    }

    for (int hired = 0; hired < k; ++hired) {
        bool takeLeft = false;
        if (rightHeap.empty()) {
            takeLeft = true;
        } else if (!leftHeap.empty()) {
            const P& l = leftHeap.top();
            const P& r = rightHeap.top();
            if (l.first < r.first || (l.first == r.first && l.second < r.second)) {
                takeLeft = true;
            }
        }

        if (takeLeft) {
            P p = leftHeap.top();
            leftHeap.pop();
            total += p.first;
            if (left <= right) {
                leftHeap.emplace(costs[left], left);
                ++left;
            }
        } else {
            P p = rightHeap.top();
            rightHeap.pop();
            total += p.first;
            if (left <= right) {
                rightHeap.emplace(costs[right], right);
                --right;
            }
        }
    }
    return total;
}

