int minScore(int n, const std::vector<std::vector<int>>& roads) {
    std::vector<std::vector<std::pair<int, int>>> adj(n + 1);
    for (const auto& road : roads) {
        int u = road[0];
        int v = road[1];
        int w = road[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    std::vector<bool> visited(n + 1, false);
    std::vector<int> stack;
    stack.push_back(1);
    visited[1] = true;
    int minScore = std::numeric_limits<int>::max();

    while (!stack.empty()) {
        int node = stack.back();
        stack.pop_back();
        for (const auto& nbr_pair : adj[node]) {
            int nbr = nbr_pair.first;
            int w = nbr_pair.second;
            if (w < minScore) {
                minScore = w;
            }
            if (!visited[nbr]) {
                visited[nbr] = true;
                stack.push_back(nbr);
            }
        }
    }
    return minScore;
}

