            for (int j = 1; j <= n; ++j) {
                if (used[j]) continue;
                long long cur = cost[i0 - 1][j - 1] - u[i0] - v[j];
                if (cur < minv[j]) {
                    minv[j] = cur;
                    way[j] = j0;
                }
                if (minv[j] < delta) {
                    delta = minv[j];
                    j1 = j;
                }
            }
            for (int j = 0; j <= n; ++j) {
                if (used[j]) {
                    u[p_match[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p_match[j0] != 0);
        do {
            int j1 = way[j0];
            p_match[j0] = p_match[j1];
            j0 = j1;
        } while (j0);
    }

    std::vector<int> assignment(n, -1);
    for (int j = 1; j <= n; ++j) {
        if (p_match[j] != 0) {
            assignment[p_match[j] - 1] = j - 1;
        }
    }

    long long total = 0;
    for (int i = 0; i < n; ++i) {
        long long c = cost[i][assignment[i]];
        if (c >= INF / 2) return -1;
        total += c;
    }
    return total / 2;
}

