struct Interval { int start; int end; };

struct MemoryAllocatorHandle {
    std::shared_ptr<std::vector<Interval>> intervals;
    std::shared_ptr<std::unordered_map<int, std::vector<std::pair<int,int>>>> allocations; // mID -> (start, size)
    std::function<int(int,int)> allocate;
    std::function<int(int)> freeMemory;
};

MemoryAllocatorHandle MemoryAllocator(int n) {
    MemoryAllocatorHandle h;
    h.intervals = std::make_shared<std::vector<Interval>>(std::vector<Interval>{ {0, n - 1} });
    h.allocations = std::make_shared<std::unordered_map<int, std::vector<std::pair<int,int>>>>();
    auto intervals = h.intervals;
    auto allocations = h.allocations;

    auto freeInterval = [intervals](int start, int size) {
        int newStart = start;
        int newEnd = start + size - 1;
        size_t i = 0;
        while (i < intervals->size() && (*intervals)[i].end < newStart - 1) ++i;
        if (i > 0 && (*intervals)[i - 1].end + 1 >= newStart) {
            newStart = (*intervals)[i - 1].start;
            newEnd = std::max(newEnd, (*intervals)[i - 1].end);
            intervals->erase(intervals->begin() + (i - 1));
            --i;
        }
        while (i < intervals->size() && (*intervals)[i].start <= newEnd + 1) {
            newStart = std::min(newStart, (*intervals)[i].start);
            newEnd = std::max(newEnd, (*intervals)[i].end);
            intervals->erase(intervals->begin() + i);
        }
        intervals->insert(intervals->begin() + i, Interval{newStart, newEnd});
    };

    h.allocate = [intervals, allocations](int size, int mID) -> int {
        for (size_t i = 0; i < intervals->size(); ++i) {
            Interval &interval = (*intervals)[i];
            int length = interval.end - interval.start + 1;
            if (length >= size) {
                int allocStart = interval.start;
                if (length == size) intervals->erase(intervals->begin() + i);
                else interval.start += size;
                (*allocations)[mID].push_back({allocStart, size});
                return allocStart;
            }
        }
        return -1;
    };
    h.freeMemory = [allocations, freeInterval](int mID) -> int {
        auto it = allocations->find(mID);
        if (it == allocations->end()) return 0;
        int freed = 0;
        for (auto& kv : it->second) { freeInterval(kv.first, kv.second); freed += kv.second; }
        allocations->erase(it);
        return freed;
    };
    return h;
}

