bool isPossible(int n, std::vector<std::vector<int>>& edges) {
    std::vector<int> degree(n + 1, 0);
    std::vector<std::unordered_set<int>> adj(n + 1);
    for (const auto& e : edges) {
        int a = e[0];
        int b = e[1];
        degree[a]++;
        degree[b]++;
        adj[a].insert(b);
        adj[b].insert(a);
    }
    std::vector<int> odd;
    for (int i = 1; i <= n; ++i) {
        if (degree[i] % 2 == 1) odd.push_back(i);
    }
    if (odd.size() == 0) return true;
    if (odd.size() > 4) return false;
    if (odd.size() == 2) {
        int a = odd[0], b = odd[1];
        if (adj[a].find(b) == adj[a].end()) return true;
        for (int c = 1; c <= n; ++c) {
            if (c == a || c == b) continue;
            if (adj[a].find(c) == adj[a].end() && adj[b].find(c) == adj[b].end())
                return true;
        }
        return false;
    }
    // odd.size() == 4
    int o0 = odd[0], o1 = odd[1], o2 = odd[2], o3 = odd[3];
    auto notEdge = [&](int x, int y) {
        return adj[x].find(y) == adj[x].end();
    };
    if (notEdge(o0, o1) && notEdge(o2, o3)) return true;
    if (notEdge(o0, o2) && notEdge(o1, o3)) return true;
    if (notEdge(o0, o3) && notEdge(o1, o2)) return true;
    return false;
}

