}
int smallestValue(int n) {
    if (n <= 1) return n;
    int limit = n;
    std::vector<int> spf(limit + 1);
    for (int i = 0; i <= limit; ++i) spf[i] = i;
    for (int i = 2; i * i <= limit; ++i) {
        if (spf[i] == i) {
            for (int j = i * i; j <= limit; j += i) {
                if (spf[j] == j) spf[j] = i;
            }
        }
    }
    int ans = n;
    while (true) {
        int sum = sumPrimeFactors(n, spf);
        if (sum == n) break;
        n = sum;
        if (n < ans) ans = n;
    }
    return ans;
}

