        if (forts[i] != 0) {
            if (prevIdx != -1 && forts[i] != forts[prevIdx]) {
                int captured = i - prevIdx - 1;
                if (captured > maxCaptured) {
                    maxCaptured = captured;
                }
            }
            prevIdx = i;
        }
    }
    return maxCaptured;
}

