std::vector<int> topStudents(const std::vector<std::string>& positive_feedback,
                             const std::vector<std::string>& negative_feedback,
                             const std::vector<std::string>& report,
                             const std::vector<int>& student_id,
                             int k) {
    std::unordered_set<std::string> posSet(positive_feedback.begin(), positive_feedback.end());
    std::unordered_set<std::string> negSet(negative_feedback.begin(), negative_feedback.end());

    std::unordered_map<int, long long> points;

    for (size_t i = 0; i < report.size(); ++i) {
        int id = student_id[i];
        std::istringstream iss(report[i]);
        std::string w;
        long long score = 0;
        while (iss >> w) {
            if (posSet.find(w) != posSet.end()) {
                score += 3;
            } else if (negSet.find(w) != negSet.end()) {
                score -= 1;
            }
        }
        points[id] += score;
    }

    struct Student {
        int id;
        long long pt;
    };
    std::vector<Student> students;
    students.reserve(points.size());
    for (const auto& kv : points) {
        students.push_back({kv.first, kv.second});
    }

    std::sort(students.begin(), students.end(), [](const Student& a, const Student& b) {
        if (a.pt != b.pt) return a.pt > b.pt;
        return a.id < b.id;
    });

    std::vector<int> result;
    result.reserve(k);
    for (int i = 0; i < k && i < static_cast<int>(students.size()); ++i) {
        result.push_back(students[i].id);
    }
    return result;
}

