int maximumTastiness(std::vector<int> price, int k) {
    std::sort(price.begin(), price.end());
    auto canPlace = [&](int dist) -> bool {
        int count = 1;
        int last = price[0];
        for (size_t i = 1; i < price.size(); ++i) {
            if (price[i] - last >= dist) {
                ++count;
                last = price[i];
                if (count == k) return true;
            }
        }
        return false;
    };
    int low = 0;
    int high = price.back() - price.front();
    while (low < high) {
        int mid = (low + high + 1) / 2;
        if (canPlace(mid)) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

