int takeCharacters(std::string s, int k) {
    int n = s.size();
    int totalA = 0, totalB = 0, totalC = 0;
    for (char ch : s) {
        if (ch == 'a') ++totalA;
        else if (ch == 'b') ++totalB;
        else ++totalC;
    }
    if (totalA < k || totalB < k || totalC < k) return -1;
    int allowedA = totalA - k;
    int allowedB = totalB - k;
    int allowedC = totalC - k;
    int cntA = 0, cntB = 0, cntC = 0;
    int left = 0, maxLen = 0;
    for (int right = 0; right < n; ++right) {
        char ch = s[right];
        if (ch == 'a') ++cntA;
        else if (ch == 'b') ++cntB;
        else ++cntC;
        while (cntA > allowedA || cntB > allowedB || cntC > allowedC) {
            char cl = s[left];
            if (cl == 'a') --cntA;
            else if (cl == 'b') --cntB;
            else --cntC;
            ++left;
        }
        int curLen = right - left + 1;
        if (curLen > maxLen) maxLen = curLen;
    }
    return n - maxLen;
}

#include <bits/stdc++.h>
using int64 = long long;
const int64 MOD = 1000000007LL;

int64 modPow(int64 a, int64 e) {
    int64 res = 1;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

int countAnagrams(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::vector<int64> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[n] = modPow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;

    int64 answer = 1;
    int i = 0;
    while (i < n) {
        // process one word
        int len = 0;
        int cnt[26] = {0};
        while (i < n && s[i] != ' ') {
            ++len;
            ++cnt[s[i] - 'a'];
            ++i;
        }
        int64 ways = fact[len];
        for (int c = 0; c < 26; ++c) {
            if (cnt[c] > 1) ways = ways * invFact[cnt[c]] % MOD;
        }
        answer = answer * ways % MOD;
        // skip space
        while (i < n && s[i] == ' ') ++i;
    }
    return static_cast<int>(answer);
}

