std::size_t distinctPrimeFactors(const std::vector<long long>& nums) {
    std::unordered_set<long long> primeSet;
    for (long long value : nums) {
        long long n = value;
        if (n < 2) continue;
        while (n % 2 == 0) {
            primeSet.insert(2);
            n /= 2;
        }
        for (long long f = 3; f * f <= n; f += 2) {
            while (n % f == 0) {
                primeSet.insert(f);
                n /= f;
            }
        }
        if (n > 1) primeSet.insert(n);
    }
    return primeSet.size();
}

