int shortestDistance(const std::vector<std::string>& words, const std::string& target, int startIndex) {
    int n = static_cast<int>(words.size());
    if (n == 0) return -1;
    int minDist = INT_MAX;
    for (int i = 0; i < n; ++i) {
        if (words[i] != target) continue;
        int clockwise = (i - startIndex + n) % n;
        int counter = (startIndex - i + n) % n;
        int dist = std::min(clockwise, counter);
        if (dist < minDist) minDist = dist;
    }
    return minDist == INT_MAX ? -1 : minDist;
}

