#include <numeric>

static long long my_gcd(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long minimizeMaximum(int divisor1, int divisor2, int uniqueCnt1, int uniqueCnt2) {
    using int64 = long long;
    int64 d1 = divisor1, d2 = divisor2;
    int64 cnt1 = uniqueCnt1, cnt2 = uniqueCnt2;
    int64 g = my_gcd(d1, d2);
    int64 lcm = d1 / g * d2;

    auto feasible = [&](int64 M) -> bool {
        int64 only1 = M / d2 - M / lcm;
        int64 only2 = M / d1 - M / lcm;
        int64 both  = M - M / d1 - M / d2 + M / lcm;

        int64 need1 = cnt1 > only1 ? cnt1 - only1 : 0;
        int64 need2 = cnt2 > only2 ? cnt2 - only2 : 0;
        return need1 + need2 <= both;
    };

    int64 low = 1, high = 1;
    while (!feasible(high)) {
        high <<= 1;
    }
    while (low < high) {
        int64 mid = low + (high - low) / 2;
        if (feasible(mid)) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

#include <bits/stdc++.h>
#include <vector>

int numberOfGreatPartitions(const std::vector<int>& nums, int k) {
    const int MOD = 1000000007;
    long long totalLL = 0;
    for (int x : nums) {
        totalLL += x;
    }
    if (totalLL < 2LL * k) return 0;
    int total = static_cast<int>(totalLL);
    std::vector<int> dp(total + 1, 0);
    dp[0] = 1;
    for (int x : nums) {
        for (int s = total; s >= x; --s) {
            dp[s] += dp[s - x];
            if (dp[s] >= MOD) dp[s] -= MOD;
        }
    }
    long long ans = 0;
    for (int s = k; s <= total - k; ++s) {
        ans += dp[s];
        if (ans >= MOD) ans -= MOD;
    }
    return static_cast<int>(ans % MOD);
}

