#include <bits/stdc++.h>

long long maxPower(const std::vector<int>& stations, int r, int k) {
    int n = stations.size();
    long long K = k;
    // compute initial power for each city
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + stations[i];
    std::vector<long long> initPower(n);
    for (int i = 0; i < n; ++i) {
        int left = std::max(0, i - r);
        int right = std::min(n - 1, i + r);
        initPower[i] = pref[right + 1] - pref[left];
    }

    auto feasible = [&](long long target) -> bool {
        std::vector<long long> diff(n + 2, 0); // difference array for added effect
        long long curAdd = 0; // current added stations affecting city i
        long long used = 0;   // total stations added so far

        for (int i = 0; i < n; ++i) {
            curAdd += diff[i];
            long long curPower = initPower[i] + curAdd;
            if (curPower < target) {
                long long need = target - curPower;
                used += need;
                if (used > K) return false;
                int pos = std::min(i + r, n - 1);
                int end = std::min(pos + r, n - 1);
                // effect starts at i, ends at 'end'
                curAdd += need;
                diff[end + 1] -= need;
            }
        }
        return true;
    };

    long long low = 0;
    long long high = *std::max_element(initPower.begin(), initPower.end()) + K;
    while (low < high) {
        long long mid = (low + high + 1) / 2;
        if (feasible(mid))
            low = mid;
        else
            high = mid - 1;
    }
    return low;
}

#include <bits/stdc++.h>
