struct DataStreamResult {
    std::function<void(int)> next;
    std::function<bool(int, int)> consecutive;
};

struct State {
    bool hasLast = false;
    int lastValue = 0;
    int runLength = 0;
};

DataStreamResult DataStream() {
    State* state = new State();
    DataStreamResult obj;
    obj.next = [state](int val) {
        if (state->hasLast && val == state->lastValue) {
            ++state->runLength;
        } else {
            state->hasLast = true;
            state->lastValue = val;
            state->runLength = 1;
        }
    };
    obj.consecutive = [state](int k, int value) -> bool {
        return state->hasLast && value == state->lastValue && state->runLength >= k;
    };
    return obj;
}

