int maxCount(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (nums[mid] < 0) lo = mid + 1;
        else hi = mid;
    }
    int firstNonNeg = lo;
    lo = 0; hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (nums[mid] <= 0) lo = mid + 1;
        else hi = mid;
    }
    int firstPos = lo;
    int negCount = firstNonNeg;
    int posCount = n - firstPos;
    return std::max(negCount, posCount);
}

