long long differenceOfSum(const std::vector<int>& nums) {
    long long elementSum = 0;
    long long digitSum = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        int val = nums[i];
        elementSum += val;
        int temp = val;
        while (temp > 0) {
            digitSum += temp % 10;
            temp = temp / 10;
        }
    }
    return std::abs(elementSum - digitSum);
