long long countGoodSubarrays(const std::vector<int>& nums, long long k) {
    std::size_t n = nums.size();
    if (k == 0) return static_cast<long long>(n) * (n + 1) / 2;

    std::unordered_map<int, long long> freq;
    std::size_t left = 0;
    long long pairs = 0;
    long long answer = 0;

    for (std::size_t right = 0; right < n; ++right) {
        int val = nums[right];
        long long cnt = 0;
        auto it = freq.find(val);
        if (it != freq.end()) cnt = it->second;
        pairs += cnt;
        freq[val] = cnt + 1;

        while (pairs >= k) {
            answer += static_cast<long long>(n - right);
            int leftVal = nums[left];
            long long leftCnt = freq[leftVal];
            pairs -= leftCnt - 1;
            freq[leftVal] = leftCnt - 1;
            ++left;
        }
    }
    return answer;
}

