bool isCircularSentence(const std::string& sentence) {
    std::vector<std::string> words;
    size_t start = 0;
    while (true) {
        size_t pos = sentence.find(' ', start);
        if (pos == std::string::npos) {
            words.push_back(sentence.substr(start));
            break;
        } else {
            words.push_back(sentence.substr(start, pos - start));
            start = pos + 1;
        }
    }
    if (words.empty()) {
        return false;
    }
    for (size_t i = 0; i + 1 < words.size(); ++i) {
        const std::string& cur = words[i];
        const std::string& nxt = words[i + 1];
        if (cur.empty() || nxt.empty() || cur.back() != nxt.front()) {
            return false;
        }
    }
    const std::string& last = words.back();
    const std::string& first = words.front();
    if (last.empty() || first.empty() || last.back() != first.front()) {
        return false;
    }
    return true;
}

