std::vector<std::vector<int>> closestNodes(TreeNode* root, const std::vector<int>& queries) {
    std::vector<int> sortedValues;
    std::function<void(TreeNode*)> inOrder = [&](TreeNode* node) {
        if (node) {
            inOrder(node->left);
            sortedValues.push_back(node->val);
            inOrder(node->right);
        }
    };
    inOrder(root);

    std::vector<std::vector<int>> result;
    for (int query : queries) {
        int mini = -1;
        for (int i = static_cast<int>(sortedValues.size()) - 1; i >= 0; --i) {
            if (sortedValues[i] <= query) {
                mini = sortedValues[i];
                break;
            }
        }
        int maxi = -1;
        for (size_t i = 0; i < sortedValues.size(); ++i) {
            if (sortedValues[i] >= query) {
                maxi = sortedValues[i];
                break;
            }
        }
        result.push_back({mini, maxi});
    }
    return result;
}

