}

int maxNonOverlappingPalindromeSubstrings(const std::string& s, int k) {
    int count = 0;
    size_t left = 0;
    while (left < s.length()) {
        bool found = false;
        for (size_t right = left + static_cast<size_t>(k); right <= s.length(); ++right) {
            std::string substring = s.substr(left, right - left);
            if (isPalindrome(substring)) {
                ++count;
                left = right;
                found = true;
                break;
            }
        }
        if (!found) {
            ++left;
        }
    }
    return count;
}

