long long countPalindromicSubsequence(const std::string& s) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(s.size());
    long long count = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            for (int k = j + 1; k < n; ++k) {
                for (int l = k + 1; l < n; ++l) {
                    for (int m = l + 1; m < n; ++m) {
                        std::string subsequence;
                        subsequence.push_back(s[i]);
                        subsequence.push_back(s[j]);
                        subsequence.push_back(s[k]);
                        subsequence.push_back(s[l]);
                        subsequence.push_back(s[m]);
                        bool isPalindrome = true;
                        for (int p = 0; p < 2; ++p) {
                            if (subsequence[p] != subsequence[4 - p]) {
                                isPalindrome = false;
                                break;
                            }
                        }
                        if (isPalindrome) {
                            count = (count + 1) % MOD;
                        }
                    }
                }
            }
        }
    }
    return count;
}

#include <bits/stdc++.h>

std::vector<std::string> splitMessage(const std::string& message, int limit) {
    if (message.empty()) {
        return {};
    }
    auto numDigits = [](long long x) -> int {
        if (x == 0) return 1;
        int cnt = 0;
        while (x) {
            ++cnt;
            x /= 10;
        }
        return cnt;
    };
    long long msgLen = static_cast<long long>(message.size());
    for (long long total = 1; total <= msgLen; ++total) {
        int digitsTotal = numDigits(total);
        long long idx = 0;
        bool ok = true;
        std::vector<std::string> parts;
        for (long long i = 1; i <= total; ++i) {
            int digitsIdx = numDigits(i);
            int suffixLen = digitsIdx + digitsTotal + 3; // "<i/total>"
            int contentLen = limit - suffixLen;
            if (contentLen <= 0) {
                ok = false;
                break;
            }
            long long take = std::min<long long>(contentLen, msgLen - idx);
            std::string suffix = "<" + std::to_string(i) + "/" + std::to_string(total) + ">";
            parts.push_back(message.substr(static_cast<size_t>(idx), static_cast<size_t>(take)) + suffix);
            idx += take;
            if (idx >= msgLen) {
                break;
            }
        }
        if (ok && idx == msgLen) {
            return parts;
        }
    }
    return {};
}

#include <bits/stdc++.h>

std::vector<int> maxPoints(const std::vector<std::vector<int>>& grid, const std::vector<int>& queries) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    std::vector<int> answer;
    answer.reserve(queries.size());

    const int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};

    for (int q : queries) {
        if (grid[0][0] >= q) {
            answer.push_back(0);
            continue;
        }

        std::vector<char> visited(m * n, 0);
        std::queue<std::pair<int,int>> bfs;
        bfs.emplace(0, 0);
        visited[0] = 1;
        int cnt = 0;

        while (!bfs.empty()) {
            std::pair<int,int> cell = bfs.front();
            bfs.pop();
            int x = cell.first;
            int y = cell.second;
            ++cnt;

            for (const auto& d : dirs) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                int idx = nx * n + ny;
                if (visited[idx]) continue;
                if (grid[nx][ny] >= q) continue;
                visited[idx] = 1;
                bfs.emplace(nx, ny);
            }
        }

        answer.push_back(cnt);
    }

    return answer;
}

