struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int minimumOperations(TreeNode* root) {
    if (!root) return 0;
    int result = 0;
    std::queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        int levelSize = static_cast<int>(q.size());
        std::vector<int> levelValues;
        levelValues.reserve(levelSize);
        for (int i = 0; i < levelSize; ++i) {
            TreeNode* node = q.front();
            q.pop();
            levelValues.push_back(node->val);
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        std::vector<int> sortedLevelValues = levelValues;
        std::sort(sortedLevelValues.begin(), sortedLevelValues.end());
        std::unordered_map<int, int> indexMapping;
        indexMapping.reserve(levelValues.size());
        for (int i = 0; i < static_cast<int>(levelValues.size()); ++i) {
            indexMapping[levelValues[i]] = i;
        }
        std::vector<bool> visited(levelSize, false);
        for (int i = 0; i < levelSize; ++i) {
            if (visited[i] || levelValues[i] == sortedLevelValues[i]) continue;
            int cycleSize = 0;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                j = indexMapping[sortedLevelValues[j]];
                ++cycleSize;
            }
            result += (cycleSize - 1);
        }
    }
    return result;
}

#include <bits/stdc++.h>

int beautifulPartitions(const std::string& s, int k, int minLength) {
    const int MOD = 1000000007;
    int n = static_cast<int>(s.size());
    if (n < k * minLength) return 0;
    auto isPrimeDigit = [](char c) -> bool {
        return c == '2' || c == '3' || c == '5' || c == '7';
    };
    auto isNonPrimeDigit = [&](char c) -> bool {
        return !isPrimeDigit(c);
    };
    std::vector<int> dpPrev(n, 0), dpCur(n, 0);
    if (!isPrimeDigit(s[0])) return 0;
    for (int i = minLength - 1; i < n; ++i) {
        if (isNonPrimeDigit(s[i])) dpPrev[i] = 1;
    }
    for (int part = 2; part <= k; ++part) {
        std::vector<int> prefix(n, 0);
        long long sum = 0;
        for (int idx = 0; idx < n; ++idx) {
            if (idx + 1 < n && isPrimeDigit(s[idx + 1])) {
                sum += dpPrev[idx];
                if (sum >= MOD) sum -= MOD;
            }
            prefix[idx] = static_cast<int>(sum);
        }
        std::fill(dpCur.begin(), dpCur.end(), 0);
        for (int cur = 0; cur < n; ++cur) {
            if (!isNonPrimeDigit(s[cur])) continue;
            int limit = cur - minLength;
            if (limit >= 0) dpCur[cur] = prefix[limit];
        }
        dpPrev.swap(dpCur);
    }
    return dpPrev[n - 1];
}

#include <bits/stdc++.h>

std::vector<long long> cycleLengthQueries(long long n, const std::vector<std::vector<long long>>& queries) {
    auto findDepth = [&](long long node) -> long long {
        return 63 - __builtin_clzll(node);
    };
    auto findLCA = [&](long long a, long long b) -> long long {
        long long depthA = findDepth(a);
        long long depthB = findDepth(b);
        while (depthA > depthB) {
            a >>= 1;
            --depthA;
        }
        while (depthB > depthA) {
            b >>= 1;
            --depthB;
        }
        while (a != b) {
            a >>= 1;
            b >>= 1;
        }
        return a;
    };
    std::vector<long long> answer;
    answer.reserve(queries.size());
    for (const auto& q : queries) {
        long long a = q[0];
        long long b = q[1];
        long long lca = findLCA(a, b);
        long long distance = findDepth(a) + findDepth(b) - 2 * findDepth(lca);
        answer.push_back(distance + 1);
    }
    return answer;
}

