#include <bits/stdc++.h>

long long maxCost(int n, const std::vector<std::vector<int>>& edges, const std::vector<int>& price) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<long long> down(n, 0), up(n, 0);
    std::vector<long long> p(n);
    for (int i = 0; i < n; ++i) p[i] = price[i];

    // first dfs: compute down values
    std::function<void(int,int)> dfs1 = [&](int u, int parent) {
        down[u] = p[u];
        for (int v : adj[u]) if (v != parent) {
            dfs1(v, u);
            down[u] = std::max(down[u], p[u] + down[v]);
        }
    };
    dfs1(0, -1);

    // second dfs: compute up values using rerooting
    std::function<void(int,int,long long)> dfs2 = [&](int u, int parent, long long upValue) {
        up[u] = upValue;
        // find top two contributions from children (price[u] + down[child])
        long long max1 = -1, max2 = -1;
        for (int v : adj[u]) if (v != parent) {
            long long contrib = p[u] + down[v];
            if (contrib > max1) {
                max2 = max1;
                max1 = contrib;
            } else if (contrib > max2) {
                max2 = contrib;
            }
        }
        for (int v : adj[u]) if (v != parent) {
            long long contrib = p[u] + down[v];
            long long siblingBest = (contrib == max1) ? max2 : max1;
            long long candidate = upValue;
            if (siblingBest > candidate) candidate = siblingBest;
            long long childUp = p[v] + candidate;
            dfs2(v, u, childUp);
        }
    };
    dfs2(0, -1, p[0]);

    long long answer = 0;
    for (int i = 0; i < n; ++i) {
        long long best = std::max(down[i], up[i]);
        long long cost = best - p[i];
        if (cost > answer) answer = cost;
    }
    return answer;
}

