long long countQuadruplets(const std::vector<int>& nums) {
    long long count = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        for (size_t j = i + 1; j < nums.size(); ++j) {
            for (size_t k = j + 1; k < nums.size(); ++k) {
                for (size_t l = k + 1; l < nums.size(); ++l) {
