std::size_t distinctNumbers(int n) {
    std::unordered_set<int> distinctNums;
    std::deque<int> queue;
    distinctNums.insert(n);
    queue.push_back(n);
    while (!queue.empty()) {
        int num = queue.front();
        queue.pop_front();
        for (int i = 2; i <= num; ++i) {
            if (num % i == 1) {
                if (distinctNums.find(i) == distinctNums.end()) {
                    distinctNums.insert(i);
                    queue.push_back(i);
                }
            }
        }
    }
    return distinctNums.size();
}

