long long countCollisions(long long n) {
    const long long MOD = 1000000007LL;
    long long result = 1;
    long long base = 2;
    long long exp = n;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    result = (result - 2) % MOD;
    if (result < 0) result += MOD;
    return result;
}

