long long maximumScore(const std::vector<int>& nums1, const std::vector<int>& nums2, int k) {
    std::size_t n = nums1.size();
    std::vector<std::pair<int, int>> pairs;
    pairs.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        pairs.emplace_back(nums2[i], nums1[i]); // (nums2, nums1)
    }
    std::sort(pairs.begin(), pairs.end(),
              [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                  return a.first > b.first; // descending by nums2
              });

    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;
    long long sum = 0;
    long long best = 0;

    for (const auto& p : pairs) {
        int curNums2 = p.first;
        int curNums1 = p.second;

        sum += curNums1;
        minHeap.push(curNums1);
        if (static_cast<int>(minHeap.size()) > k) {
            sum -= minHeap.top();
            minHeap.pop();
        }
        if (static_cast<int>(minHeap.size()) == k) {
            long long candidate = sum * static_cast<long long>(curNums2);
            if (candidate > best) best = candidate;
        }
    }
    return best;
}

