std::vector<std::vector<int>> incrementSubmatrices(int n, const std::vector<std::vector<int>>& queries) {
    std::vector<std::vector<int>> diff(n + 1, std::vector<int>(n + 1, 0));
    for (const auto& q : queries) {
        int r1 = q[0];
        int c1 = q[1];
        int r2 = q[2];
        int c2 = q[3];
        diff[r1][c1] += 1;
        diff[r1][c2 + 1] -= 1;
        diff[r2 + 1][c1] -= 1;
        diff[r2 + 1][c2 + 1] += 1;
    }
    std::vector<std::vector<int>> result(n, std::vector<int>(n, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int val = diff[i][j];
            if (i > 0) val += result[i - 1][j];
            if (j > 0) val += result[i][j - 1];
            if (i > 0 && j > 0) val -= result[i - 1][j - 1];
            result[i][j] = val;
        }
    }
    return result;
}

