bool isPossibleToDisconnect(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<char>> fromStart(m, std::vector<char>(n, 0));
    std::vector<std::vector<char>> toEnd(m, std::vector<char>(n, 0));

    // reachable from (0,0)
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 0) continue;
            if (i == 0 && j == 0) {
                fromStart[i][j] = 1;
            } else {
                if (i > 0 && fromStart[i - 1][j]) fromStart[i][j] = 1;
                if (j > 0 && fromStart[i][j - 1]) fromStart[i][j] = 1;
            }
        }
    }

    // reachable to (m-1,n-1)
    for (int i = m - 1; i >= 0; --i) {
        for (int j = n - 1; j >= 0; --j) {
            if (grid[i][j] == 0) continue;
            if (i == m - 1 && j == n - 1) {
                toEnd[i][j] = 1;
            } else {
                if (i + 1 < m && toEnd[i + 1][j]) toEnd[i][j] = 1;
                if (j + 1 < n && toEnd[i][j + 1]) toEnd[i][j] = 1;
            }
        }
    }

    // already disconnected
    if (!fromStart[m - 1][n - 1]) return true;

    int diagCount = m + n - 1;
    std::vector<int> cnt(diagCount, 0);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == 0 && j == 0) continue;
            if (i == m - 1 && j == n - 1) continue;
            if (fromStart[i][j] && toEnd[i][j]) {
                ++cnt[i + j];
            }
        }
    }

    for (int k = 0; k < diagCount; ++k) {
        if (cnt[k] == 1) return true;
    }
    return false;
}

