long long minimumImpossibleOR(const std::vector<long long>& nums) {
    long long maxOr = 0;
    for (long long v : nums) {
        maxOr |= v;
    }
    for (long long x = 1; x <= maxOr + 1; ++x) {
        long long union_ = 0;
        for (long long v : nums) {
            if ((v | x) == x) {
                union_ |= v;
            }
        }
        if (union_ != x) {
            return x;
        }
    }
    return maxOr + 1;
}

