long long countWays(std::vector<std::vector<int>>& ranges) {
    const long long MOD = 1000000007LL;
    std::sort(ranges.begin(), ranges.end(), [](const std::vector<int>& a, const std::vector<int>& b) {
        if (a[0] != b[0]) return a[0] < b[0];
        return a[1] < b[1];
    });
    long long components = 0;
    long long curMaxEnd = LLONG_MIN;
    for (size_t i = 0; i < ranges.size(); ++i) {
        long long s = ranges[i][0];
        long long e = ranges[i][1];
        if (s > curMaxEnd) {
            ++components;
            curMaxEnd = e;
        } else {
            if (e > curMaxEnd) curMaxEnd = e;
        }
    }
    long long result = 1;
    long long base = 2;
    long long exp = components;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

#include <bits/stdc++.h>
std::string findString(const std::vector<std::vector<int>>& lcp) {
    int n = (int)lcp.size();
    if (n == 0) return "";
    for (int i = 0; i < n; ++i) {
        if ((int)lcp[i].size() != n) return "";
    }
    // basic validation
    for (int i = 0; i < n; ++i) {
        if (lcp[i][i] != n - i) return "";
        for (int j = i + 1; j < n; ++j) {
            if (lcp[i][j] != lcp[j][i]) return "";
            if (lcp[i][j] > std::min(n - i, n - j) || lcp[i][j] < 0) return "";
        }
    }
    // DSU
    struct DSU {
        std::vector<int> p, sz;
        DSU(int n): p(n), sz(n,1) { std::iota(p.begin(), p.end(), 0); }
        int find(int x){ return p[x]==x?x:p[x]=find(p[x]); }
        void unite(int a,int b){
            a=find(a); b=find(b);
            if(a==b) return;
            if(sz[a]<sz[b]) std::swap(a,b);
            p[b]=a; sz[a]+=sz[b];
        }
    } dsu(n);
    // equality constraints
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int k = lcp[i][j];
            for (int t = 0; t < k; ++t) {
                dsu.unite(i + t, j + t);
            }
        }
    }
    // inequality constraints
    std::unordered_map<int, std::unordered_set<int>> adjMap;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int k = lcp[i][j];
            int maxLen = std::min(n - i, n - j);
            if (k < maxLen) {
                int a = dsu.find(i + k);
                int b = dsu.find(j + k);
                if (a == b) return "";
                adjMap[a].insert(b);
                adjMap[b].insert(a);
            }
        }
    }
    // collect components
    std::vector<int> compId(n);
    std::unordered_map<int, int> rootToIdx;
    int idx = 0;
    for (int i = 0; i < n; ++i) {
        int r = dsu.find(i);
        if (!rootToIdx.count(r)) rootToIdx[r] = idx++;
        compId[i] = rootToIdx[r];
    }
    int m = idx;
    std::vector<std::vector<int>> adj(m);
    for (auto &p : adjMap) {
        int u = rootToIdx[p.first];
        for (int vRoot : p.second) {
            int v = rootToIdx[vRoot];
            adj[u].push_back(v);
        }
    }
    // coloring with at most 26 letters
    std::vector<int> color(m, -1);
    std::string result(n, 'a');
    for (int i = 0; i < n; ++i) {
        int c = compId[i];
        if (color[c] == -1) {
            bool used[26] = {false};
            for (int nb : adj[c]) {
                if (color[nb] != -1) used[color[nb]] = true;
            }
            int assign = -1;
            for (int d = 0; d < 26; ++d) if (!used[d]) { assign = d; break; }
            if (assign == -1) return "";
            color[c] = assign;
        }
        result[i] = char('a' + color[c]);
    }
    // verify matrix
    for (int i = 0; i < n; ++i) {
        for (int j = i; j < n; ++j) {
            int cnt = 0;
            while (i + cnt < n && j + cnt < n && result[i + cnt] == result[j + cnt]) ++cnt;
            if (cnt != lcp[i][j]) return "";
        }
    }
    return result;
}

#include <bits/stdc++.h>
int rootCount(const std::vector<std::vector<int>>& edges, const std::vector<std::vector<int>>& guesses, int k) {
    int n = edges.size() + 1;
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::unordered_set<long long> guessSet;
    guessSet.reserve(guesses.size() * 2 + 1);
    for (const auto& g : guesses) {
        long long key = static_cast<long long>(g[0]) * n + g[1];
        guessSet.insert(key);
    }
    int initialCorrect = 0;
    std::function<void(int,int)> dfsInit = [&](int node, int parent) {
        for (int nb : adj[node]) {
            if (nb == parent) continue;
            long long key = static_cast<long long>(node) * n + nb;
            if (guessSet.find(key) != guessSet.end()) ++initialCorrect;
            dfsInit(nb, node);
        }
    };
    dfsInit(0, -1);
    int answer = 0;
    std::function<void(int,int,int)> dfsReroot = [&](int node, int parent, int curCorrect) {
        if (curCorrect >= k) ++answer;
        for (int nb : adj[node]) {
            if (nb == parent) continue;
            int nextCorrect = curCorrect;
            long long keyForward = static_cast<long long>(node) * n + nb;
            long long keyBackward = static_cast<long long>(nb) * n + node;
            if (guessSet.find(keyForward) != guessSet.end()) --nextCorrect;
            if (guessSet.find(keyBackward) != guessSet.end()) ++nextCorrect;
            dfsReroot(nb, node, nextCorrect);
        }
    };
    dfsReroot(0, -1, initialCorrect);
    return answer;
}

