int waysToReachTarget(int target, std::vector<std::vector<int>>& types) {
    const int MOD = 1000000007;
    std::vector<int> dp(target + 1, 0);
    dp[0] = 1;
    for (const auto& t : types) {
        int cnt = t[0];
        int marks = t[1];
        std::vector<int> ndp(target + 1, 0);
        for (int s = 0; s <= target; ++s) {
            if (dp[s] == 0) continue;
            for (int k = 0; k <= cnt && s + k * marks <= target; ++k) {
                ndp[s + k * marks] = (ndp[s + k * marks] + dp[s]) % MOD;
            }
        }
        dp.swap(ndp);
    }
    return dp[target];
}

