int minimumTime(std::vector<std::vector<int>>& tasks) {
    if (tasks.empty()) return 0;
    int maxEnd = 0;
    for (const auto& t : tasks) {
        maxEnd = std::max(maxEnd, t[1]);
    }
    std::vector<int> on(maxEnd + 2, 0);
    std::sort(tasks.begin(), tasks.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  if (a[1] != b[1]) return a[1] < b[1];
                  return a[0] < b[0];
              });
    for (const auto& task : tasks) {
        int start = task[0];
        int end = task[1];
        int dur = task[2];
        int already = 0;
        for (int t = start; t <= end; ++t) {
            already += on[t];
        }
        int need = dur - already;
        for (int t = end; need > 0 && t >= start; --t) {
            if (!on[t]) {
                on[t] = 1;
                --need;
            }
        }
    }
    int total = 0;
    for (int i = 0; i <= maxEnd; ++i) total += on[i];
    return total;
}

