long long beautifulSubsets(std::vector<long long> nums, long long k) {
    std::sort(nums.begin(), nums.end());
    std::unordered_map<long long, int> cnt;
    for (long long x : nums) {
        cnt[x] = cnt[x] + 1;
    }
    std::vector<long long> values;
    values.reserve(cnt.size());
    for (const auto& p : cnt) {
        values.push_back(p.first);
    }
    std::sort(values.begin(), values.end());
    size_t m = values.size();
    long long totalWays = 1;
    size_t i = 0;
    while (i < m) {
        long long dpPrevPrev = 1;
        long long w0 = static_cast<long long>(std::pow(2.0, cnt[values[i]])) - 1;
        long long dpPrev = 1 + w0;
        ++i;
        while (i < m && values[i] - values[i - 1] == k) {
            long long w = static_cast<long long>(std::pow(2.0, cnt[values[i]])) - 1;
            long long cur = dpPrev + dpPrevPrev * w;
            dpPrevPrev = dpPrev;
            dpPrev = cur;
            ++i;
        }
        totalWays *= dpPrev;
    }
    return totalWays - 1;
}

