int maximumMex(std::vector<int>& nums, int value) {
    int n = nums.size();
    std::vector<long long> cnt(value, 0);
    for (int x : nums) {
        int r = x % value;
        if (r < 0) r += value;
        ++cnt[r];
    }
    auto can = [&](int k) -> bool {
        for (int r = 0; r < value; ++r) {
            if (k <= r) continue;
            long long needed = (static_cast<long long>(k) - r + value - 1) / value;
            if (cnt[r] < needed) return false;
        }
        return true;
    };
    int low = 0, high = n + 1;
    while (low < high) {
        int mid = low + (high - low + 1) / 2;
        if (can(mid)) low = mid;
        else high = mid - 1;
    }
    return low;
}

