int kthLargestLevelSum(TreeNode* root, int k) {
    if (!root) return -1;

    std::vector<TreeNode*> queue;
    queue.push_back(root);
    size_t head = 0;
    std::vector<int> levelSums;

    while (head < queue.size()) {
        int levelSize = static_cast<int>(queue.size() - head);
        int sum = 0;
        for (int i = 0; i < levelSize; ++i) {
            TreeNode* node = queue[head++];
            sum += node->val;
            if (node->left) queue.push_back(node->left);
            if (node->right) queue.push_back(node->right);
        }
        levelSums.push_back(sum);
    }

    std::sort(levelSums.begin(), levelSums.end(), std::greater<int>());
    return (k <= static_cast<int>(levelSums.size())) ? levelSums[k - 1] : -1;
}

