bool isPrime(int x) {
    if (x < 2) return false;
    if (x % 2 == 0) return x == 2;
    for (int i = 3; i * i <= x; i += 2) {
        if (x % i == 0) return false;
    }
    return true;
}

bool primeSubOperation(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    for (int i = n - 2; i >= 0; --i) {
        if (nums[i] < nums[i + 1]) continue;
        int need = nums[i] - nums[i + 1] + 1;
        int maxp = nums[i] - 1;
        if (need < 2) need = 2;
        if (need > maxp) return false;
        bool found = false;
        for (int p = need; p <= maxp; ++p) {
            if (isPrime(p)) {
                nums[i] -= p;
                found = true;
                break;
            }
        }
        if (!found) return false;
    }
    return true;
}

