std::vector<long long> minOperations(const std::vector<long long>& nums, const std::vector<long long>& queries) {
    std::size_t n = nums.size();
    std::vector<long long> sorted = nums;
    std::sort(sorted.begin(), sorted.end());

    std::vector<long long> pref(n + 1);
    pref[0] = 0;
    for (std::size_t i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + sorted[i];
    }
    long long totalSum = pref[n];

    std::vector<long long> answers;
    answers.reserve(queries.size());

    for (long long q : queries) {
        std::size_t lo = 0, hi = n;
        while (lo < hi) {
            std::size_t mid = (lo + hi) >> 1;
            if (sorted[mid] <= q) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        std::size_t k = lo;

        long long leftCost = q * static_cast<long long>(k) - pref[k];
        long long rightCost = (totalSum - pref[k]) - q * static_cast<long long>(n - k);

        answers.push_back(leftCost + rightCost);
    }

    return answers;
}

