int collectCoinsInTree(const std::vector<int>& coins, const std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(coins.size());
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int a = e[0];
        int b = e[1];
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    std::vector<int> degree(n);
    for (int i = 0; i < n; ++i) degree[i] = static_cast<int>(adj[i].size());
    std::vector<char> removed(n, 0);
    std::vector<int> queue;
    for (int i = 0; i < n; ++i) {
        if (degree[i] == 1 && coins[i] == 0) queue.push_back(i);
    }
    size_t qIdx = 0;
    while (qIdx < queue.size()) {
        int u = queue[qIdx++];
        if (removed[u]) continue;
        removed[u] = 1;
        degree[u] = 0;
        for (int v : adj[u]) {
            if (removed[v]) continue;
            degree[v]--;
            if (degree[v] == 1 && coins[v] == 0) queue.push_back(v);
        }
    }
    std::vector<int> leaves;
    for (int i = 0; i < n; ++i) {
        if (!removed[i] && degree[i] == 1) leaves.push_back(i);
    }
    for (int round = 0; round < 2; ++round) {
        std::vector<int> next;
        for (int u : leaves) {
            if (removed[u]) continue;
            removed[u] = 1;
            degree[u] = 0;
            for (int v : adj[u]) {
                if (removed[v]) continue;
                degree[v]--;
                if (degree[v] == 1) next.push_back(v);
            }
        }
        leaves.swap(next);
    }
    long long remainingEdges = 0;
    for (int i = 0; i < n; ++i) {
        if (!removed[i]) remainingEdges += degree[i];
    }
    remainingEdges /= 2;
    return static_cast<int>(remainingEdges * 2);
}

