static int my_gcd(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long makeKSubarraySumsEqual(std::vector<int> arr, int k) {
    int n = static_cast<int>(arr.size());
    int g = my_gcd(n, k);
    long long ans = 0;
    int cycleLen = n / g;
    for (int start = 0; start < g; ++start) {
        std::vector<int> vals;
        vals.reserve(cycleLen);
        int idx = start;
        for (int cnt = 0; cnt < cycleLen; ++cnt) {
            vals.push_back(arr[idx]);
            idx = (idx + k) % n;
        }
        std::sort(vals.begin(), vals.end());
        int median = vals[vals.size() / 2];
        for (int v : vals) {
            ans += std::llabs(static_cast<long long>(v) - median);
        }
    }
    return ans;
}

