int longestBalancedSubstring(const std::string& s) {
    int maxLen = 0;
    char prevRunChar = '\0';
    int prevRunLen = 0;
    int curRunLen = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (i == 0 || c == s[i - 1]) {
            ++curRunLen;
        } else {
            if (prevRunChar == '0' && c == '1') {
                int candidate = 2 * std::min(prevRunLen, curRunLen);
                if (candidate > maxLen) maxLen = candidate;
            }
            prevRunChar = s[i - 1];
            prevRunLen = curRunLen;
            curRunLen = 1;
        }
    }
    if (!s.empty() && prevRunChar == '0' && s.back() == '1') {
        int candidate = 2 * std::min(prevRunLen, curRunLen);
        if (candidate > maxLen) maxLen = candidate;
    }
    return maxLen;
}

