std::vector<int> minimumReverseOperations(int n, int p, const std::vector<int>& banned, int k) {
    std::vector<int> answer(n, -1);
    std::vector<int> nxt(n + 2);
    for (int i = 0; i <= n + 1; ++i) nxt[i] = i;

    std::function<int(int)> find = [&](int i) -> int {
        if (i >= n) return n;
        if (nxt[i] == i) return i;
        return nxt[i] = find(nxt[i]);
    };

    auto remove = [&](int i) {
        nxt[i] = find(i + 2);
    };

    for (int b : banned) {
        remove(b);
    }

    answer[p] = 0;
    remove(p);
    std::vector<int> queue;
    queue.push_back(p);
    std::size_t head = 0;

    while (head < queue.size()) {
        int x = queue[head++];
        int dMin = std::max(0, x - (n - k));
        int dMax = std::min(k - 1, x);
        int L = x + (k - 1) - 2 * dMax;
        int R = x + (k - 1) - 2 * dMin;
        if (L < 0) L = 0;
        if (R >= n) R = n - 1;
        if (L > R) continue;

        int cur = find(L);
        while (cur <= R) {
            answer[cur] = answer[x] + 1;
            queue.push_back(cur);
            int next = find(cur + 2);
            nxt[cur] = next;
            cur = next;
        }
    }

    return answer;
}

