int maxSum(int numOnes, int numZeros, int numNegOnes, int k) {
    int onesPicked = std::min(numOnes, k);
    int remaining = k - onesPicked;
    int zerosPicked = std::min(numZeros, remaining);
    remaining -= zerosPicked;
    int negOnesPicked = std::min(numNegOnes, remaining);
    int sum = onesPicked - negOnesPicked;
    return sum;
}

#include <bits/stdc++.h>
int minimumVisitedCells(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    if (m == 1 && n == 1) return 1;
    std::vector<std::set<int>> rowUnvisited(m);
    std::vector<std::set<int>> colUnvisited(n);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            rowUnvisited[i].insert(j);
            colUnvisited[j].insert(i);
        }
    }
    std::vector<std::vector<int>> dist(m, std::vector<int>(n, -1));
    std::queue<std::pair<int,int>> q;
    dist[0][0] = 1;
    q.emplace(0,0);
    rowUnvisited[0].erase(0);
    colUnvisited[0].erase(0);
    while (!q.empty()) {
        std::pair<int,int> cur = q.front(); q.pop();
        int i = cur.first;
        int j = cur.second;
        int d = grid[i][j];
        // move right in the same row
        auto &rowSet = rowUnvisited[i];
        auto it = rowSet.lower_bound(j + 1);
        while (it != rowSet.end() && *it <= j + d) {
            int c = *it;
            auto itNext = std::next(it);
            dist[i][c] = dist[i][j] + 1;
            q.emplace(i, c);
            colUnvisited[c].erase(i);
            rowSet.erase(it);
            it = itNext;
        }
        // move down in the same column
        auto &colSet = colUnvisited[j];
        it = colSet.lower_bound(i + 1);
        while (it != colSet.end() && *it <= i + d) {
            int r = *it;
            auto itNext = std::next(it);
            dist[r][j] = dist[i][j] + 1;
            q.emplace(r, j);
            rowUnvisited[r].erase(j);
            colSet.erase(it);
            it = itNext;
        }
        if (dist[m-1][n-1] != -1) return dist[m-1][n-1];
    }
    return -1;
}

