bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

int primeInDiagonal(const std::vector<std::vector<int>>& nums) {
    if (nums.empty()) return 0;
    std::size_t rows = nums.size();
    std::size_t cols = nums[0].size();
    int maxPrime = 0;
    for (std::size_t i = 0; i < rows; ++i) {
        if (i < cols) {
            int val = nums[i][i];
            if (isPrime(val) && val > maxPrime) maxPrime = val;
        }
        int antiCol = static_cast<int>(cols) - 1 - static_cast<int>(i);
        if (antiCol >= 0 && static_cast<std::size_t>(antiCol) < cols) {
            if (static_cast<int>(i) != antiCol) {
                int val = nums[i][antiCol];
                if (isPrime(val) && val > maxPrime) maxPrime = val;
            }
        }
    }
    return maxPrime;
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>

int minimizeMaxDifference(const std::vector<int>& nums, int p) {
    std::size_t n = nums.size();
    if (p == 0) return 0;
    std::vector<int> a(nums);
    std::sort(a.begin(), a.end());
    int low = 0;
    int high = a.back() - a.front();
    auto canForm = [&](int limit) {
        int cnt = 0;
        for (std::size_t i = 0; i + 1 < n; ) {
            if (a[i + 1] - a[i] <= limit) {
                ++cnt;
                i += 2;
            } else {
                ++i;
            }
        }
        return cnt;
    };
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (canForm(mid) >= p) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

