std::vector<std::string> cacheWithTimeLimit(const std::vector<std::string>& actions,
                                            const std::vector<std::vector<int>>& values,
                                            const std::vector<int>& timeDelays) {
    std::vector<std::string> result;
    std::unordered_map<int, std::pair<int, long long>> store; // key -> (value, expireTime)

    for (size_t i = 0; i < actions.size(); ++i) {
        // the given time array holds ABSOLUTE timestamps for each call, not
        // per-step deltas that should be accumulated
        long long currentTime = timeDelays[i];
        const std::string& act = actions[i];

        if (act == "TimeLimitedCache") {
            store.clear();
            result.push_back("null");
        } else if (act == "set") {
            int key = values[i][0];
            int val = values[i][1];
            int dur = values[i][2];
            bool existed = false;
            auto it = store.find(key);
            if (it != store.end() && it->second.second > currentTime) {
                existed = true;
            }
            store[key] = {val, currentTime + dur};
            result.push_back(existed ? "true" : "false");
        } else if (act == "get") {
            int key = values[i][0];
            auto it = store.find(key);
            if (it != store.end() && it->second.second > currentTime) {
                result.push_back(std::to_string(it->second.first));
            } else {
                if (it != store.end()) store.erase(it);
                result.push_back("-1");
            }
        } else if (act == "count") {
            int cnt = 0;
            std::vector<int> toErase;
            for (const auto& p : store) {
                if (p.second.second > currentTime) {
                    ++cnt;
                } else {
                    toErase.push_back(p.first);
                }
            }
            for (int k : toErase) store.erase(k);
            result.push_back(std::to_string(cnt));
        }
    }
    return result;
}

#include <bits/stdc++.h>
#include <vector>
#include <unordered_map>

std::vector<long long> sumOfDistances(const std::vector<int>& nums) {
    std::size_t n = nums.size();
    std::vector<long long> ans(n, 0);
    std::unordered_map<int, std::vector<std::size_t>> groups;

    for (std::size_t i = 0; i < n; ++i) {
        int v = nums[i];
        groups[v].push_back(i);
    }

    for (auto& kv : groups) {
        const std::vector<std::size_t>& idxList = kv.second;
        std::size_t m = idxList.size();
        if (m <= 1) continue;

        std::vector<long long> pref(m);
        pref[0] = static_cast<long long>(idxList[0]);
        for (std::size_t k = 1; k < m; ++k) {
            pref[k] = pref[k - 1] + static_cast<long long>(idxList[k]);
        }
        long long totalSum = pref[m - 1];

        for (std::size_t p = 0; p < m; ++p) {
            std::size_t i = idxList[p];
            long long leftCount = static_cast<long long>(p);
            long long leftSum = (p > 0) ? pref[p - 1] : 0;
            long long rightCount = static_cast<long long>(m - p - 1);
            long long rightSum = totalSum - leftSum - static_cast<long long>(i);
            ans[i] = static_cast<long long>(i) * leftCount - leftSum + rightSum - static_cast<long long>(i) * rightCount;
        }
    }

    return ans;
}

