template <typename Func>
struct Memoized {
    Func fn_;
    std::unordered_map<std::string, std::shared_ptr<void>> cache_;
    std::size_t callCount_ = 0;

    explicit Memoized(Func f) : fn_(std::move(f)) {}

    template <typename... Args>
    auto operator()(Args... args) -> decltype(fn_(args...)) {
        std::ostringstream oss;
        ((oss << args << '|'), ...);
        std::string key = oss.str();
        auto it = cache_.find(key);
        using ReturnType = decltype(fn_(args...));
        if (it != cache_.end()) {
            return *std::static_pointer_cast<ReturnType>(it->second);
        }
        ReturnType result = fn_(args...);
        cache_.emplace(std::move(key), std::make_shared<ReturnType>(result));
        ++callCount_;
        return result;
    }

    std::size_t getCallCount() const {
        return callCount_;
    }
};

template <typename Func>
auto memoize(Func fn) {
    return Memoized<Func>{std::move(fn)};
}

