std::vector<std::vector<int>> snailTraversal(const std::vector<int>& input, int rowsCount, int colsCount) {
    // validate dimensions before allocating/filling - a mismatched or
    // non-positive size means no valid traversal exists, and filling
    // without this check reads/writes out of bounds (undefined behavior)
    if (rowsCount <= 0 || colsCount <= 0 ||
        static_cast<long long>(rowsCount) * colsCount != static_cast<long long>(input.size())) {
        return {};
    }
    std::vector<std::vector<int>> result(rowsCount, std::vector<int>(colsCount));
    int idx = 0;
    for (int col = 0; col < colsCount; ++col) {
        if (col % 2 == 0) {
            for (int row = 0; row < rowsCount; ++row) {
                result[row][col] = input[idx++];
            }
        } else {
            for (int row = rowsCount - 1; row >= 0; --row) {
                result[row][col] = input[idx++];
            }
        }
    }
    return result;
}

