struct Call {
    int t;
    std::vector<int> inputs;
};

std::vector<Call> debounce(int t, const std::vector<Call>& calls) {
    std::vector<Call> result;
    if (calls.empty()) return result;
    bool hasPending = false;
    Call pending;
    int pendingExec = 0;
    for (const Call& c : calls) {
        if (!hasPending) {
            pending = c;
            pendingExec = c.t + t;
            hasPending = true;
        } else {
            if (c.t >= pendingExec) {
                Call exec = pending;
                exec.t = pendingExec;
                result.push_back(exec);
                pending = c;
                pendingExec = c.t + t;
            } else {
                pending = c;
                pendingExec = c.t + t;
            }
        }
    }
    if (hasPending) {
        Call exec = pending;
        exec.t = pendingExec;
        result.push_back(exec);
    }
    return result;
}

