struct NestedArray {
    bool isInt;
    int value;
    std::vector<NestedArray> children;

    NestedArray() : isInt(true), value(0) {}
    NestedArray(int v) : isInt(true), value(v) {}
    NestedArray(const std::vector<NestedArray>& v) : isInt(false), children(v) {}
    NestedArray(std::vector<NestedArray>&& v) : isInt(false), children(std::move(v)) {}
};

std::vector<NestedArray> flatten(const std::vector<NestedArray>& arr, int n) {
    std::vector<NestedArray> result;
    std::function<void(const NestedArray&, int)> dfs = [&](const NestedArray& node, int depth) {
        if (node.isInt) {
            result.push_back(node);
        } else {
            if (depth < n) {
                for (const auto& child : node.children) {
                    dfs(child, depth + 1);
                }
            } else {
                result.push_back(node);
            }
        }
    };
    for (const auto& elem : arr) {
        dfs(elem, 0);
    }
    return result;
}

