// A minimal dynamically-typed value, since the real problem's arrays are
// JS-style heterogeneous arrays (numbers, null, objects, strings, ... all mixed).
struct Value {
    enum class Type { Null, Bool, Number, String, Object, Array } type;
    bool boolVal = false;
    double numVal = 0.0;
    std::string strVal;
    std::shared_ptr<std::vector<Value>> arrVal;
    std::shared_ptr<std::map<std::string, Value>> objVal;

    Value() : type(Type::Null) {}
    static Value Null() { return Value(); }
    static Value Num(double d) { Value v; v.type = Type::Number; v.numVal = d; return v; }
    static Value Bool_(bool b) { Value v; v.type = Type::Bool; v.boolVal = b; return v; }
    static Value Str(std::string s) { Value v; v.type = Type::String; v.strVal = std::move(s); return v; }
    static Value Obj(std::map<std::string, Value> m = {}) {
        Value v; v.type = Type::Object; v.objVal = std::make_shared<std::map<std::string, Value>>(std::move(m)); return v;
    }
    static Value Arr(std::vector<Value> a = {}) {
        Value v; v.type = Type::Array; v.arrVal = std::make_shared<std::vector<Value>>(std::move(a)); return v;
    }

    std::string toString() const {
        switch (type) {
            case Type::Null: return "null";
            case Type::Bool: return boolVal ? "true" : "false";
            case Type::Number: {
                if (numVal == (long long)numVal) return std::to_string((long long)numVal);
                std::ostringstream oss; oss << numVal; return oss.str();
            }
            case Type::String: return "\"" + strVal + "\"";
            case Type::Object: {
                std::string s = "{"; bool first = true;
                for (auto& kv : *objVal) { if (!first) s += ","; first = false; s += "\"" + kv.first + "\":" + kv.second.toString(); }
                return s + "}";
            }
            case Type::Array: {
                std::string s = "["; for (size_t i = 0; i < arrVal->size(); i++) { s += (*arrVal)[i].toString(); if (i+1 < arrVal->size()) s += ","; }
                return s + "]";
            }
        }
        return "";
    }
};

// arrayLast(nums): returns the last element of a heterogeneous array, or -1 (as a
// Value::Number) if the array is empty - matching the real JS Array.prototype.last().
Value arrayLast(const std::vector<Value>& nums) {
    if (nums.empty()) return Value::Num(-1);
    return nums.back();
}

