struct Node {
    std::unordered_map<std::size_t, std::shared_ptr<Node>> next;
    std::shared_ptr<void> result;
    bool hasResult = false;
};

template <typename F>
auto memoize(F fn) {
    auto root = std::make_shared<Node>();
    return [root, fn](auto&&... args) mutable -> decltype(fn(args...)) {
        std::shared_ptr<Node> node = root;
        auto process = [&](auto&& arg) {
            using ArgT = std::decay_t<decltype(arg)>;
            std::size_t key = std::hash<ArgT>{}(arg);
            auto it = node->next.find(key);
            if (it == node->next.end()) {
                auto newNode = std::make_shared<Node>();
                node->next[key] = newNode;
                node = newNode;
            } else {
                node = it->second;
            }
        };
        (process(std::forward<decltype(args)>(args)), ...);
        if (node->hasResult) {
            using RetT = std::decay_t<decltype(fn(args...))>;
            return *static_cast<RetT*>(node->result.get());
        }
        auto value = fn(args...);
        using RetT = std::decay_t<decltype(fn(args...))>;
        node->result = std::make_shared<RetT>(value);
        node->hasResult = true;
        return value;
    };
}

