template<class T>
struct future_traits;

template<class R>
struct future_traits<std::future<R>> { using type = R; };

template <typename Fn>
auto timeLimit(Fn fn, std::chrono::milliseconds t) {
    return [fn, t](auto&&... args) {
        using Future = decltype(fn(std::forward<decltype(args)>(args)...));
        using R = typename future_traits<Future>::type;
        std::promise<R> p;
        std::future<R> result = p.get_future();
        Future original = fn(std::forward<decltype(args)>(args)...);
        std::async(std::launch::async, [orig = std::move(original), p = std::move(p), t]() mutable {
            if (orig.wait_for(t) == std::future_status::ready) {
                try {
                    p.set_value(orig.get());
                } catch (...) {
                    p.set_exception(std::current_exception());
                }
            } else {
                p.set_exception(std::make_exception_ptr(std::runtime_error("Time Limit Exceeded")));
            }
        });
        return result;
    };
}

