struct GraphObj {
    std::vector<std::vector<std::pair<int, long long>>> adj;

    void addEdge(const std::array<long long,3>& edge) {
        int u = (int)edge[0], v = (int)edge[1]; long long w = edge[2];
        adj[u].push_back({v, w});
    }

    long long shortestPath(int src, int dst) {
        if (src == dst) return 0;
        const long long INF = std::numeric_limits<long long>::max() / 4;
        std::vector<long long> dist(adj.size(), INF);
        dist[src] = 0;
        std::vector<std::pair<long long,int>> heap;
        auto heapPush = [&](std::pair<long long,int> item) {
            heap.push_back(item);
            int i = (int)heap.size() - 1;
            while (i > 0) {
                int p = (i - 1) >> 1;
                if (heap[p].first <= heap[i].first) break;
                std::swap(heap[p], heap[i]);
                i = p;
            }
        };
        auto heapPop = [&]() -> std::pair<long long,int> {
            auto top = heap[0];
            auto last = heap.back();
            heap.pop_back();
            if (!heap.empty()) {
                heap[0] = last;
                int i = 0;
                while (true) {
                    int l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                    if (l < (int)heap.size() && heap[l].first < heap[smallest].first) smallest = l;
                    if (r < (int)heap.size() && heap[r].first < heap[smallest].first) smallest = r;
                    if (smallest == i) break;
                    std::swap(heap[i], heap[smallest]);
                    i = smallest;
                }
            }
            return top;
        };
        heapPush({0, src});
        while (!heap.empty()) {
            auto [d, u] = heapPop();
            if (d != dist[u]) continue;
            if (u == dst) return d;
            for (auto& [v, w] : adj[u]) {
                long long nd = d + w;
                if (nd < dist[v]) { dist[v] = nd; heapPush({nd, v}); }
            }
        }
        return -1;
    }
};

GraphObj Graph(int n, const std::vector<std::array<long long, 3>>& edges) {
    GraphObj g;
    g.adj.resize(n);
    for (const auto& e : edges) {
        int u = (int)e[0], v = (int)e[1]; long long w = e[2];
        g.adj[u].push_back({v, w});
    }
    return g;
}

