    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *l, TreeNode *r) : val(x), left(l), right(r) {}
};

TreeNode* replaceValueInTree(TreeNode* root) {
    if (!root) return nullptr;
    std::queue<std::pair<TreeNode*, TreeNode*>> q;
    q.push({root, nullptr});
    while (!q.empty()) {
        int sz = q.size();
        long long level_sum = 0;
        std::vector<TreeNode*> nodes;
        std::vector<TreeNode*> parents;
        nodes.reserve(sz);
        parents.reserve(sz);
        for (int i = 0; i < sz; ++i) {
            auto cur = q.front(); q.pop();
            TreeNode* node = cur.first;
            TreeNode* parent = cur.second;
            level_sum += node->val;
            nodes.push_back(node);
            parents.push_back(parent);
            if (node->left) q.push({node->left, node});
            if (node->right) q.push({node->right, node});
        }
        std::unordered_map<TreeNode*, long long> parent_sum;
        for (size_t i = 0; i < nodes.size(); ++i) {
            TreeNode* parent = parents[i];
            if (parent) parent_sum[parent] += nodes[i]->val;
        }
        for (size_t i = 0; i < nodes.size(); ++i) {
            if (parents[i] == nullptr) {
                nodes[i]->val = 0;
            } else {
                long long cousin_sum = level_sum - parent_sum[parents[i]];
                nodes[i]->val = static_cast<int>(cousin_sum);
            }
        }
    }
    return root;
}

