long long minimumTotalPrice(int n, const std::vector<std::vector<int>>& edges, const std::vector<int>& price, const std::vector<std::vector<int>>& trips) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int a = e[0], b = e[1];
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    std::vector<long long> cnt(n, 0);
    // For each trip, find path and increment counts
    for (const auto& tr : trips) {
        int s = tr[0], t = tr[1];
        std::vector<int> parent(n, -1);
        std::queue<int> q;
        q.push(s);
        parent[s] = s;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == t) break;
            for (int v : adj[u]) {
                if (parent[v] == -1) {
                    parent[v] = u;
                    q.push(v);
                }
            }
        }
        int cur = t;
        while (true) {
            cnt[cur] += 1;
            if (cur == s) break;
            cur = parent[cur];
        }
    }

    long long total = 0;
    std::vector<long long> saveWeight(n, 0);
    for (int i = 0; i < n; ++i) {
        total += static_cast<long long>(price[i]) * cnt[i];
        saveWeight[i] = static_cast<long long>(price[i] / 2) * cnt[i];
    }

    std::function<std::pair<long long, long long>(int,int)> dfs = [&](int u, int p) -> std::pair<long long,long long> {
        long long notSel = 0;
        long long sel = saveWeight[u];
        for (int v : adj[u]) {
            if (v == p) continue;
            auto child = dfs(v, u);
            notSel += std::max(child.first, child.second);
            sel += child.first; // child cannot be selected
        }
        return {notSel, sel};
    };

    auto res = dfs(0, -1);
    long long maxSaved = std::max(res.first, res.second);
    return total - maxSaved;
}

