int findValidSplit(const std::vector<int>& nums) {
    if (nums.empty()) return -1;
    int n = static_cast<int>(nums.size());
    int maxVal = 0;
    for (int v : nums) if (v > maxVal) maxVal = v;
    std::vector<int> spf(maxVal + 1);
    for (int i = 2; i <= maxVal; ++i) {
        if (spf[i] == 0) {
            spf[i] = i;
            if ((long long)i * i <= maxVal) {
                for (int j = i * i; j <= maxVal; j += i) {
                    if (spf[j] == 0) spf[j] = i;
                }
            }
        }
    }
    std::unordered_map<int, int> lastPos;
    for (int i = 0; i < n; ++i) {
        int x = nums[i];
        while (x > 1) {
            int p = spf[x];
            lastPos[p] = i;
            while (x % p == 0) x /= p;
        }
    }
    int curMax = -1;
    for (int i = 0; i < n - 1; ++i) {
        int x = nums[i];
        while (x > 1) {
            int p = spf[x];
            curMax = std::max(curMax, lastPos[p]);
            while (x % p == 0) x /= p;
        }
        if (curMax == i) return i;
    }
    return -1;
}

#include <bits/stdc++.h>

int minimumScore(std::string s, std::string t) {
    int m = static_cast<int>(s.size());
    int n = static_cast<int>(t.size());
    if (n == 0) return 0;

    std::vector<int> pref(m, 0);
    int p = 0;
    for (int i = 0; i < m; ++i) {
        if (p < n && s[i] == t[p]) ++p;
        pref[i] = p;
    }

    std::vector<int> suff(m, 0);
    int q = n - 1;
    for (int i = m - 1; i >= 0; --i) {
        if (q >= 0 && s[i] == t[q]) --q;
        suff[i] = n - 1 - q;
    }

    std::vector<int> suffixMax(m + 1, 0);
    for (int i = m - 1; i >= 0; --i) {
        suffixMax[i] = std::max(suff[i], suffixMax[i + 1]);
    }

    int answer = n; // worst case: delete whole t
    // consider split before first character of s
    answer = std::min(answer, n - (0 + suffixMax[0]));

    for (int i = 0; i < m; ++i) {
        int kept = pref[i] + suffixMax[i + 1];
        int removed = n - kept;
        if (removed < 0) removed = 0;
        answer = std::min(answer, removed);
    }

    return answer;
}

