std::vector<std::vector<int>> substringXorQueries(const std::string& s, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(s.size());
    const int MAX_BITS = 30; // since 2^30 > 1e9
    std::unordered_map<int, std::pair<int,int>> best;
    best.reserve(n * MAX_BITS);
    for (int i = 0; i < n; ++i) {
        int val = 0;
        for (int len = 1; len <= MAX_BITS && i + len - 1 < n; ++len) {
            val = (val << 1) | (s[i + len - 1] - '0');
            auto it = best.find(val);
            if (it == best.end() || len < (it->second.second - it->second.first + 1) ||
                (len == (it->second.second - it->second.first + 1) && i < it->second.first)) {
                best[val] = {i, i + len - 1};
            }
        }
    }
    std::vector<std::vector<int>> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        int target = q[0] ^ q[1];
        auto it = best.find(target);
        if (it != best.end()) {
            ans.push_back({it->second.first, it->second.second});
        } else {
            ans.push_back({-1, -1});
        }
    }
    return ans;
}

