long long minCost(const std::vector<int>& basket1, const std::vector<int>& basket2) {
    std::unordered_map<int, long long> freq1, freq2;
    for (size_t i = 0; i < basket1.size(); ++i) {
        ++freq1[basket1[i]];
        ++freq2[basket2[i]];
    }
    long long globalMin = LLONG_MAX;
    for (const auto& kv : freq1) {
        globalMin = std::min(globalMin, static_cast<long long>(kv.first));
    }
    for (const auto& kv : freq2) {
        globalMin = std::min(globalMin, static_cast<long long>(kv.first));
    }
    for (const auto& kv : freq1) {
        long long total = kv.second + freq2[kv.first];
        if (total % 2 != 0) {
            return -1;
        }
    }
    for (const auto& kv : freq2) {
        long long total = kv.second + freq1[kv.first];
        if (total % 2 != 0) {
            return -1;
        }
    }
    std::vector<int> excessA, excessB;
    for (const auto& kv : freq1) {
        int val = kv.first;
        long long diff = kv.second - freq2[val];
        if (diff > 0) {
            for (long long i = 0; i < diff / 2; ++i) excessA.push_back(val);
        } else if (diff < 0) {
            for (long long i = 0; i < (-diff) / 2; ++i) excessB.push_back(val);
        }
    }
    if (excessA.size() != excessB.size()) return -1;
    std::sort(excessA.begin(), excessA.end());
    std::sort(excessB.begin(), excessB.end());
    long long cost = 0;
    long long twoMin = 2LL * globalMin;
    for (size_t i = 0; i < excessA.size(); ++i) {
        long long a = excessA[i];
        long long b = excessB[i];
        cost += std::min({a, b, twoMin});
    }
    return cost;
}

