int maximizeWin(const std::vector<int>& prizePositions, int k) {
    int maxPrizes = 0;
    for (size_t i = 0; i < prizePositions.size(); ++i) {
        int leftSegmentCount = 0;
        for (size_t j = 0; j < prizePositions.size(); ++j) {
            if (prizePositions[j] >= prizePositions[i] && prizePositions[j] <= prizePositions[i] + k) {
                ++leftSegmentCount;
            }
        }
        for (size_t j = 0; j < prizePositions.size(); ++j) {
            int rightSegmentCount = 0;
            for (size_t m = 0; m < prizePositions.size(); ++m) {
                if (prizePositions[m] >= prizePositions[j] && prizePositions[m] <= prizePositions[j] + k) {
                    ++rightSegmentCount;
                }
            }
            int overlapping = 0;
            int leftStart = prizePositions[i];
            int leftEnd = prizePositions[i] + k;
            int rightStart = prizePositions[j];
            int rightEnd = prizePositions[j] + k;
            int overlapStart = std::max(leftStart, rightStart);
            int overlapEnd = std::min(leftEnd, rightEnd);
            if (overlapStart <= overlapEnd) {
                for (size_t m = 0; m < prizePositions.size(); ++m) {
                    if (prizePositions[m] >= overlapStart && prizePositions[m] <= overlapEnd) {
                        ++overlapping;
                    }
                }
            }
            maxPrizes = std::max(maxPrizes, leftSegmentCount + rightSegmentCount - overlapping);
        }
    }
    return maxPrizes;
}

