long long minCost(const std::vector<int>& nums, long long k) {
    int n = static_cast<int>(nums.size());
    const long long INF = LLONG_MAX / 4;
    std::vector<long long> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        std::unordered_map<int, int> count;
        int uniqueCount = 0;
        for (int j = i - 1; j >= 0; --j) {
            auto it = count.find(nums[j]);
            if (it == count.end()) {
                count[nums[j]] = 1;
                ++uniqueCount;
            } else if (it->second == 1) {
                ++(it->second);
                --uniqueCount;
            } else {
                ++(it->second);
            }
            long long candidate = dp[j] + k + (i - j - uniqueCount);
            if (candidate < dp[i]) dp[i] = candidate;
        }
    }
    return dp[n];
}

