long long putMarblesInBags(std::vector<int> weights, int k) {
    if (k == 1) {
        return 0LL;
    }
    std::vector<long long> pairSums;
    pairSums.reserve(weights.size() - 1);
    for (size_t i = 0; i + 1 < weights.size(); ++i) {
        pairSums.push_back(static_cast<long long>(weights[i]) + static_cast<long long>(weights[i + 1]));
    }
    std::sort(pairSums.begin(), pairSums.end());
    long long minSum = 0, maxSum = 0;
    for (int i = 0; i < k - 1; ++i) {
        minSum += pairSums[i];
        maxSum += pairSums[pairSums.size() - 1 - i];
    }
    return maxSum - minSum;
}

