bool makeEqual(std::string s, const std::string& target) {
    size_t n = s.size();
    int countS = 0, countTarget = 0;
    for (size_t i = 0; i < n; ++i) {
        if (s[i] == '1') ++countS;
        if (target[i] == '1') ++countTarget;
    }
    if (countS != countTarget) return false;
    std::vector<bool> visited(n, false);
    for (size_t i = 0; i < n; ++i) {
        if (s[i] != target[i]) {
            bool found = false;
            for (size_t j = 0; j < n; ++j) {
                if (!visited[j] && s[j] == target[i]) {
                    s[i] = (s[i] == '1' || s[j] == '1') ? '1' : '0';
                    s[j] = ((s[i] == '0' && s[j] == '1') || (s[i] == '1' && s[j] == '0')) ? '1' : '0';
                    visited[j] = true;
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
    }
    return true;
}

