int maxNumberofFish(const std::vector<std::vector<int>>& grid) {
    if (grid.empty()) return 0;
    int rows = grid.size();
    int cols = grid[0].size();
    std::vector<std::vector<bool>> visited(rows, std::vector<bool>(cols, false));
    std::function<int(int, int)> dfs = [&](int i, int j) -> int {
        if (i < 0 || i >= rows || j < 0 || j >= cols) return 0;
        if (grid[i][j] == 0 || visited[i][j]) return 0;
        visited[i][j] = true;
        int sum = grid[i][j];
        sum += dfs(i + 1, j);
        sum += dfs(i - 1, j);
        sum += dfs(i, j + 1);
        sum += dfs(i, j - 1);
        return sum;
    };
    int maxFish = 0;
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            if (grid[i][j] != 0 && !visited[i][j]) {
                int cur = dfs(i, j);
                maxFish = std::max(maxFish, cur);
            }
        }
    }
    return maxFish;
}

