int minOperations(std::vector<int> nums) {
    int n = static_cast<int>(nums.size());
    int ones = 0;
    for (int v : nums) if (v == 1) ++ones;
    if (ones > 0) {
        return n - ones;
    }
    auto mygcd = [](int a, int b) {
        while (b) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    int overall_gcd = nums[0];
    for (int i = 1; i < n; ++i) {
        overall_gcd = mygcd(overall_gcd, nums[i]);
    }
    if (overall_gcd != 1) return -1;
    int best_len = n + 1;
    for (int i = 0; i < n; ++i) {
        int cur = nums[i];
        for (int j = i; j < n; ++j) {
            cur = mygcd(cur, nums[j]);
            if (cur == 1) {
                best_len = std::min(best_len, j - i + 1);
                break;
            }
        }
    }
    return (best_len - 1) + (n - 1);
}

