template <typename T>
auto then(std::future<T>& fut, std::function<T(T)>&& cont) -> std::future<T> {
    return std::async(std::launch::async, [f = std::move(cont), &fut]() mutable {
        T value = fut.get();
        return f(value);
    });
}

template <typename T>
auto catch_error(std::future<T>& fut, std::function<void(std::exception_ptr)>&& handler) -> std::future<T> {
    return std::async(std::launch::async, [h = std::move(handler), &fut]() mutable {
        try {
            return fut.get();
        } catch (...) {
            h(std::current_exception());
            throw;
        }
    });
}

template <typename Generator>
auto cancellable(Generator& generator) {
    bool cancelled = false;
    using ResultType = decltype(generator.next());
    using ValueType = decltype(std::declval<ResultType>().value);
    std::promise<ValueType> promise;
    std::future<ValueType> future = promise.get_future();

    std::function<void()> cancel = [&]() {
        cancelled = true;
        generator.throw_("Cancelled");
    };

    std::function<void(std::function<ResultType()>)> step = [&](std::function<ResultType()> next) {
        if (cancelled) {
            generator.throw_("Cancelled");
        } else {
            try {
                ResultType result = next();
                if (result.done) {
                    promise.set_value(result.value);
                } else {
                    auto thenCont = [&](ValueType value) -> ValueType {
                        if (cancelled) {
                            generator.throw_("Cancelled");
                        } else {
                            step([&]() { return generator.next(value); });
                        }
                        return value;
                    };
                    auto catchCont = [&](std::exception_ptr err) {
                        try {
                            if (err) std::rethrow_exception(err);
                        } catch (...) {
                            generator.throw_(std::current_exception());
                        }
                    };
                    std::future<ValueType> innerFuture = result.value;
                    std::future<ValueType> continued = then(innerFuture, std::function<ValueType(ValueType)>(thenCont));
                    continued = catch_error(continued, std::function<void(std::exception_ptr)>(catchCont));
                }
            } catch (...) {
                promise.set_exception(std::current_exception());
            }
        }
    };

    step([&]() { return generator.next(); });
    return std::make_pair(cancel, std::move(future));
}

