long long minimumCost(std::vector<int> start, std::vector<int> target, std::vector<std::vector<int>> specialRoads) {
    using ll = long long;
    struct Point { int x, y; };
    std::vector<Point> points;
    auto encode = [](int x, int y) -> long long {
        return (static_cast<long long>(x) << 32) ^ static_cast<unsigned int>(y);
    };
    std::unordered_map<long long, int> idxMap;

    auto addPoint = [&](int x, int y) {
        long long key = encode(x, y);
        if (idxMap.find(key) == idxMap.end()) {
            int id = points.size();
            points.push_back({x, y});
            idxMap[key] = id;
        }
    };

    addPoint(start[0], start[1]);
    addPoint(target[0], target[1]);
    for (auto &r : specialRoads) {
        addPoint(r[0], r[1]);
        addPoint(r[2], r[3]);
    }

    int n = points.size();
    std::vector<std::vector<std::pair<int, ll>>> adj(n);
    auto manhattan = [&](int i, int j) -> ll {
        return llabs(points[i].x - points[j].x) + llabs(points[i].y - points[j].y);
    };
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            ll d = manhattan(i, j);
            adj[i].push_back({j, d});
            adj[j].push_back({i, d});
        }
    }
    for (auto &r : specialRoads) {
        int sx = r[0], sy = r[1], ex = r[2], ey = r[3];
        ll cost = r[4];
        int u = idxMap[encode(sx, sy)];
        int v = idxMap[encode(ex, ey)];
        adj[u].push_back({v, cost});
    }

    int startIdx = idxMap[encode(start[0], start[1])];
    int targetIdx = idxMap[encode(target[0], target[1])];

    const ll INF = LLONG_MAX / 4;
    std::vector<ll> dist(n, INF);
    dist[startIdx] = 0;
    using Node = std::pair<ll, int>;
    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;
    pq.push({0, startIdx});

    while (!pq.empty()) {
        Node cur = pq.top();
        pq.pop();
        ll d = cur.first;
        int u = cur.second;
        if (d != dist[u]) continue;
        if (u == targetIdx) break;
        for (auto &e : adj[u]) {
            int v = e.first;
            ll w = e.second;
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist[targetIdx];
}

