std::string smallestBeautifulString(const std::string& s, int k) {
    const int n = static_cast<int>(s.size());
    const char maxChar = static_cast<char>('a' + k - 1);
    for (int i = n - 1; i >= 0; --i) {
        for (char c = static_cast<char>(s[i] + 1); c <= maxChar; ++c) {
            if (i > 0 && c == s[i - 1]) continue;
            std::string candidate = s.substr(0, i);
            candidate.push_back(c);
            bool ok = true;
            for (int j = i + 1; j < n; ++j) {
                char pick = 'a';
                while (pick <= maxChar && pick == candidate[j - 1]) ++pick;
                if (pick > maxChar) {
                    ok = false;
                    break;
                }
                candidate.push_back(pick);
            }
            if (ok) return candidate;
        }
    }
    return "";
}

