    char expect = 'a';
    auto nextChar = [](char c) {
        if (c == 'a') return 'b';
        if (c == 'b') return 'c';
        return 'a';
    };
    for (char ch : word) {
        while (ch != expect) {
            ++insertions;
            expect = nextChar(expect);
        }
        expect = nextChar(expect);
    }
