long long minIncrements(int n, const std::vector<int>& cost) {
    if (n == 0) return 0;
    std::vector<long long> sum(n);
    std::vector<long long> inc(n);
    for (int i = n - 1; i >= 0; --i) {
        int left = 2 * i + 1;
        int right = 2 * i + 2;
        if (left >= n) {
            sum[i] = cost[i];
            inc[i] = 0;
        } else if (right >= n) {
            sum[i] = cost[i] + sum[left];
            inc[i] = inc[left];
        } else {
            long long leftSum = sum[left];
            long long rightSum = sum[right];
            long long target = std::max(leftSum, rightSum);
            inc[i] = inc[left] + inc[right] + (target - leftSum) + (target - rightSum);
            sum[i] = cost[i] + target;
        }
    }
    return inc[0];
}

