public:
    void add(int num) {
        if (freqCount.count(num)) {
            count[freqCount[num]]--;
            if (count[freqCount[num]] == 0) count.erase(freqCount[num]);
        }
        freqCount[num]++;
        count[freqCount[num]]++;
    }
    void remove(int num) {
        if (!freqCount.count(num)) return;
        count[freqCount[num]]--;
        if (count[freqCount[num]] == 0) count.erase(freqCount[num]);
        freqCount[num]--;
        if (freqCount[num] == 0) freqCount.erase(num);
        else count[freqCount[num]]++;
    }
    bool query(int num) {
        return count.count(num) > 0;
    }
};

