long long maximumOr(const std::vector<long long>& nums, int k) {
    long long maxOr = 0;
    std::size_t n = nums.size();
    unsigned long long total = 1ULL << (k * n);
    for (unsigned long long i = 0; i < total; ++i) {
        std::vector<long long> temp = nums;
        int operations = 0;
        for (std::size_t j = 0; j < n; ++j) {
            for (int bit = 0; bit < k; ++bit) {
                if (((i >> (j * k + bit)) & 1ULL) == 1ULL) {
                    temp[j] *= 2;
                    ++operations;
                }
            }
            if (operations > k) break;
        }
        if (operations > k) continue;
        long long orVal = 0;
        for (long long num : temp) {
            orVal |= num;
        }
        maxOr = std::max(maxOr, orVal);
    }
    return maxOr;
}

class Solution {
public:
    int sumOfPower(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        long long MOD = 1000000007;
        long long ans = 0, total = 0;
        for (int x : nums) {
            ans = (ans + (long long) x * x % MOD * ((x + total) % MOD)) % MOD;
            total = (2 * total + x) % MOD;
        }
        return (int) ans;
    }
};

