std::vector<int> circularGameLosers(int n, int k) {
    std::vector<bool> received(n, false);
    int current = 0;
    received[current] = true;
    long long step = k;
    while (true) {
        int next = static_cast<int>((current + step) % n);
        if (received[next]) break;
        received[next] = true;
        current = next;
        step += k;
    }
    std::vector<int> losers;
    for (int i = 0; i < n; ++i) {
        if (!received[i]) losers.push_back(i + 1);
    }
    return losers;
}

