int maximumMoves(const std::vector<std::vector<int>>& grid) {
    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());
    std::vector<std::vector<int>> memo(rows, std::vector<int>(cols, -1));
    std::function<int(int, int)> dfs = [&](int r, int c) -> int {
        if (c == cols - 1) return 0;
        int& res = memo[r][c];
        if (res != -1) return res;
        int best = 0;
        for (int dr = -1; dr <= 1; ++dr) {
            int nr = r + dr;
            int nc = c + 1;
            if (nr >= 0 && nr < rows && grid[nr][nc] > grid[r][c]) {
                best = std::max(best, 1 + dfs(nr, nc));
            }
        }
        res = best;
        return res;
    };
    int answer = 0;
    for (int i = 0; i < rows; ++i) {
        answer = std::max(answer, dfs(i, 0));
    }
    return answer;
}

