bool isTruthy(const JsonPtr& v) {
    switch (v->type) {
        case JsonType::Null: return false;
        case JsonType::Bool: return v->bool_val;
        case JsonType::Number: return v->num_val != 0;
        case JsonType::String: return !v->str_val.empty();
        case JsonType::Array: return true;
        case JsonType::Object: return true;
    }
    return false;
}

JsonPtr compactObject(const JsonPtr& obj) {
    if (obj->type == JsonType::Array) {
        const auto& arr = obj->arr_val;
        JsonArray result;
        result.reserve(arr.size());
        for (const auto& val : arr) {
            if (isTruthy(val)) {
                if (val->type == JsonType::Array || val->type == JsonType::Object) {
                    result.push_back(compactObject(val));
                } else {
                    result.push_back(val);
                }
            }
        }
        return std::make_shared<Json>(result);
    } else if (obj->type == JsonType::Object) {
        const auto& objMap = obj->obj_val;
        JsonObject result;
        for (const auto& kv : objMap) {
            if (isTruthy(kv.second)) {
                if (kv.second->type == JsonType::Array || kv.second->type == JsonType::Object) {
                    result[kv.first] = compactObject(kv.second);
                } else {
                    result[kv.first] = kv.second;
                }
            }
        }
        return std::make_shared<Json>(result);
    } else {
        return obj;
    }
}

