bool canPartition(long long square, int target) {
    std::string s = std::to_string(square);
    int len = static_cast<int>(s.size());
    std::function<bool(int, int)> dfs = [&](int pos, int sum) -> bool {
        if (pos == len) {
            return sum == target;
        }
        long long cur = 0;
        for (int i = pos; i < len; ++i) {
            cur = cur * 10 + (s[i] - '0');
            if (sum + cur > target) {
                continue;
            }
            if (dfs(i + 1, sum + static_cast<int>(cur))) {
                return true;
            }
        }
        return false;
    };
    return dfs(0, 0);
}

long long punishmentNumber(int n) {
    long long result = 0;
    for (int i = 1; i <= n; ++i) {
        long long square = 1LL * i * i;
        if (canPartition(square, i)) {
            result += square;
        }
    }
    return result;
}

