int minExtraCharacters(const std::string& s, const std::vector<std::string>& dictionary) {
    std::vector<int> dp(s.size() + 1, 0);
    for (size_t i = 1; i <= s.size(); ++i) {
        dp[i] = dp[i - 1] + 1;
        for (const std::string& word : dictionary) {
            size_t wlen = word.size();
            if (i >= wlen && s.compare(i - wlen, wlen, word) == 0) {
                dp[i] = std::min(dp[i], dp[i - wlen]);
            }
        }
    }
    return dp[s.size()];
}

