std::vector<std::vector<int>> differenceOfNumberOnDiagonals(const std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<int>> answer(m, std::vector<int>(n, 0));
    std::unordered_map<int, std::unordered_set<int>> diagonalCounts;
    for (int r = 0; r < m; ++r) {
        for (int c = 0; c < n; ++c) {
            int diagonalKey = r - c;
            int antiDiagonalKey = r + c;
            diagonalCounts[diagonalKey].insert(grid[r][c]);
            diagonalCounts[antiDiagonalKey].insert(grid[r][c]);
        }
    }
    for (int r = 0; r < m; ++r) {
        for (int c = 0; c < n; ++c) {
            int diagonalKey = r - c;
            int antiDiagonalKey = r + c;
            int diff = static_cast<int>(diagonalCounts[diagonalKey].size()) - static_cast<int>(diagonalCounts[antiDiagonalKey].size());
            answer[r][c] = std::abs(diff);
        }
    }
    return answer;
}

