class EventEmitter {
public:
    EventEmitter() {}

    int subscribe(const string& eventName, const function<any(const vector<any>&)>& callback) {
        int id = static_cast<int>(subs.size());
        subs.push_back({eventName, callback, true});
        evMap[eventName].push_back(id);
        return id;
    }

    vector<any> emit(const string& eventName) {
        return emit(eventName, {});
    }

    vector<any> emit(const string& eventName, const vector<any>& args) {
        vector<any> res;
        auto it = evMap.find(eventName);
        if (it == evMap.end()) return res;
        for (int id : it->second) {
            if (id >= 0 && id < static_cast<int>(subs.size()) && subs[id].active) {
                res.push_back(subs[id].callback(args));
            }
        }
        return res;
    }

    int unsubscribe(int id) {
        if (id < 0 || id >= static_cast<int>(subs.size()) || !subs[id].active) return id;
        const string& ev = subs[id].eventName;
        auto& vec = evMap[ev];
        vec.erase(std::remove(vec.begin(), vec.end(), id), vec.end());
        subs[id].active = false;
        return id;
    }

private:
    struct Subscription {
        string eventName;
        function<any(const vector<any>&)> callback;
        bool active;
    };
    vector<Subscription> subs;
    unordered_map<string, vector<int>> evMap;
};

