int minSwaps(std::vector<int>& nums) {
    size_t n = nums.size();
    if (n == 0) return 0;
    size_t pos1 = 0, posn = 0;
    for (size_t i = 0; i < n; ++i) {
        if (nums[i] == 1) pos1 = i;
        if (nums[i] == static_cast<int>(n)) posn = i;
