int maxCellsInMatrix(const std::vector<std::vector<int>>& mat) {
    int m = static_cast<int>(mat.size());
    int n = static_cast<int>(mat[0].size());
    struct Cell {
        int val;
        int i;
        int j;
    };
    std::vector<Cell> cells;
    cells.reserve(m * n);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            cells.push_back({mat[i][j], i, j});
        }
    }
    std::sort(cells.begin(), cells.end(), [](const Cell& a, const Cell& b) {
        return a.val < b.val;
    });
    std::vector<int> rowBest(m, 0);
    std::vector<int> colBest(n, 0);
    std::vector<std::vector<int>> dp(m, std::vector<int>(n, 1));
    int answer = 1;
    std::size_t idx = 0;
    while (idx < cells.size()) {
        std::size_t start = idx;
        while (idx < cells.size() && cells[idx].val == cells[start].val) {
            ++idx;
        }
        for (std::size_t k = start; k < idx; ++k) {
            const Cell& c = cells[k];
            int bestPrev = std::max(rowBest[c.i], colBest[c.j]);
            dp[c.i][c.j] = bestPrev + 1;
            if (dp[c.i][c.j] > answer) answer = dp[c.i][c.j];
        }
        for (std::size_t k = start; k < idx; ++k) {
            const Cell& c = cells[k];
            rowBest[c.i] = std::max(rowBest[c.i], dp[c.i][c.j]);
            colBest[c.j] = std::max(colBest[c.j], dp[c.i][c.j]);
        }
    }
    return answer;
}

