    long long total = 0;
    int unsetRows = n, unsetCols = n;
    for (int i = static_cast<int>(queries.size()) - 1; i >= 0; --i) {
        int type = queries[i][0];
        int idx = queries[i][1];
        int val = queries[i][2];
