int countGoodIntegers(const std::string& num1, const std::string& num2, int min_sum, int max_sum) {
    const int mod = 1000000007;
    long long result = 0;
    long long start = std::stoll(num1);
    long long end = std::stoll(num2);
    for (long long i = start; i <= end; ++i) {
        long long sum = 0;
        long long temp = i;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }
