template <typename T>
std::future<std::vector<T>> promiseAll(const std::vector<std::function<std::future<T>()>>& functions) {
    auto promisePtr = std::make_shared<std::promise<std::vector<T>>>();
    std::future<std::vector<T>> resultFuture = promisePtr->get_future();

    size_t n = functions.size();
    if (n == 0) {
        promisePtr->set_value({});
        return resultFuture;
    }

    auto results = std::make_shared<std::vector<T>>(n);
    auto remaining = std::make_shared<std::atomic<size_t>>(n);
    std::atomic<bool> settled{false};

    for (size_t i = 0; i < n; ++i) {
        std::async(std::launch::async, [i, &functions, results, remaining, promisePtr, &settled]() {
            try {
                T value = functions[i]().get();
                (*results)[i] = std::move(value);
                if (remaining->fetch_sub(1) == 1 && !settled.exchange(true)) {
                    promisePtr->set_value(*results);
                }
            } catch (...) {
                if (!settled.exchange(true)) {
                    try {
                        promisePtr->set_exception(std::current_exception());
                    } catch (...) {}
                }
            }
        });
    }

    return resultFuture;
}

