double calculate(const std::vector<std::string>& actions, const std::vector<double>& values) {
    double result = values[0];
    std::size_t index = 1;
    for (std::size_t i = 1; i < actions.size() - 1; ++i) {
        const std::string& act = actions[i];
        if (act == "add") result += values[index];
        else if (act == "subtract") result -= values[index];
        else if (act == "multiply") result *= values[index];
        else if (act == "divide") {
            if (values[index] == 0) throw std::runtime_error("Division by zero is not allowed");
            result /= values[index];
        }
        else if (act == "power") result = std::pow(result, values[index]);
        ++index;
    }
    return result;
}

