long long robotMovement(const std::vector<long long>& nums, const std::string& s, int d) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(nums.size());
    std::vector<long long> positions = nums;
    std::vector<int> directions(n);
    for (int i = 0; i < n; ++i) {
        directions[i] = (s[i] == 'L') ? -1 : 1;
    }
    for (int i = 0; i < d; ++i) {
        for (int j = 0; j < n; ++j) {
            positions[j] += directions[j];
        }
        for (int j = 0; j < n - 1; ++j) {
            for (int k = j + 1; k < n; ++k) {
                if (positions[j] == positions[k]) {
                    directions[j] *= -1;
                    directions[k] *= -1;
                }
            }
        }
    }
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            sum = (sum + std::llabs(positions[i] - positions[j])) % MOD;
        }
    }
    return sum;
}

