long long minimumPartitionValue(std::vector<long long> nums) {
    std::sort(nums.begin(), nums.end());
    long long minDiff = std::numeric_limits<long long>::max();
    for (size_t i = 0; i < nums.size(); ++i) {
        long long maxLeft = nums[i];
        if (i + 1 < nums.size()) {
            long long minRight = nums[i + 1];
            long long diff = maxLeft - minRight;
            if (diff < 0) diff = -diff;
            if (diff < minDiff) minDiff = diff;
        }
    }
    return minDiff;
}

#include <bits/stdc++.h>

long long countSpecialPermutations(std::vector<int> nums) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(nums.size());
    int totalMask = 1 << n;
    std::vector<std::vector<long long>> dp(totalMask, std::vector<long long>(n, 0));
    for (int i = 0; i < n; ++i) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 0; mask < totalMask; ++mask) {
        for (int last = 0; last < n; ++last) {
            if ((mask & (1 << last)) == 0) continue;
            long long cur = dp[mask][last];
            if (cur == 0) continue;
            for (int nxt = 0; nxt < n; ++nxt) {
                if (mask & (1 << nxt)) continue;
                if (nums[last] % nums[nxt] == 0 || nums[nxt] % nums[last] == 0) {
                    int nmask = mask | (1 << nxt);
                    dp[nmask][nxt] = (dp[nmask][nxt] + cur) % MOD;
                }
            }
        }
    }
    long long result = 0;
    int fullMask = totalMask - 1;
    for (int i = 0; i < n; ++i) {
        result = (result + dp[fullMask][i]) % MOD;
    }
    return result;
}

#include <bits/stdc++.h>

long long paintWalls(const std::vector<int>& cost, const std::vector<int>& time) {
    int n = static_cast<int>(cost.size());
    const long long INF = 4e18;
    std::vector<long long> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 0; i < n; ++i) {
        int w = time[i] + 1; // contribution to (paid time + number of paid walls)
        for (int j = n; j >= 0; --j) {
            if (dp[j] == INF) continue;
            int nj = j + w;
            if (nj > n) nj = n;
            dp[nj] = std::min(dp[nj], dp[j] + static_cast<long long>(cost[i]));
        }
    }
    return dp[n];
}

