int minStringLength(const std::string& s) {
    std::vector<char> stack;
    stack.reserve(s.size());
    for (size_t i = 0; i < s.size(); ++i) {
        stack.push_back(s[i]);
        while (stack.size() >= 2) {
            size_t n = stack.size();
            char a = stack[n - 2];
            char b = stack[n - 1];
            if ((a == 'A' && b == 'B') || (a == 'C' && b == 'D')) {
                stack.pop_back();
                stack.pop_back();
            } else {
                break;
            }
        }
    }
    return static_cast<int>(stack.size());
}

