std::string smallestPalindrome(const std::string& s) {
    std::string arr = s;
    std::size_t i = 0, j = arr.length() - 1;
    while (i < j) {
        if (arr[i] != arr[j]) {
            char smaller = (arr[i] < arr[j]) ? arr[i] : arr[j];
            arr[i] = smaller;
            arr[j] = smaller;
        }
        ++i;
        --j;
    }
    return arr;
}

