long long minimumCost(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) a[i] = s[i] - '0';
    const long long INF = (long long)4e18;
    auto solve = [&](int target) -> long long {
        long long cur[2] = {0, 0};
        for (int i = n - 1; i >= 0; --i) {
            long long nxt[2] = {INF, INF};
            for (int p = 0; p < 2; ++p) {
                int needSingle = (a[i] ^ p ^ target);
                long long cost = cur[p] + (needSingle ? (i + 1) : 0);
                nxt[p] = std::min(nxt[p], cost);
                int needSingle2 = (a[i] ^ p ^ 1 ^ target);
                long long cost2 = cur[p] + (i + 1) + (needSingle2 ? (i + 1) : 0);
                nxt[p ^ 1] = std::min(nxt[p ^ 1], cost2);
            }
            cur[0] = nxt[0];
            cur[1] = nxt[1];
        }
        return cur[0];
    };
    long long ans0 = solve(0);
    long long ans1 = solve(1);
    return std::min(ans0, ans1);
}

