int longestEvenOddSubarray(const std::vector<int>& nums, int threshold) {
    int n = static_cast<int>(nums.size());
    int ans = 0;
    int start = -1; // start index of current valid subarray
    for (int i = 0; i < n; ++i) {
        if (nums[i] > threshold) {
            start = -1;
            continue;
        }
        if (start == -1) {
            if (nums[i] % 2 == 0) {
                start = i;
                ans = std::max(ans, 1);
            }
        } else {
            if ((nums[i] % 2) == (nums[i - 1] % 2)) {
                if (nums[i] % 2 == 0) {
                    start = i;
                    ans = std::max(ans, 1);
                } else {
                    start = -1;
                }
            } else {
                ans = std::max(ans, i - start + 1);
            }
        }
    }
    return ans;
}

