std::vector<int> relocateMarbles(const std::vector<int>& nums, const std::vector<int>& moveFrom, const std::vector<int>& moveTo) {
    std::unordered_map<int, int> posCount;
    for (int p : nums) {
        ++posCount[p];
    }
    for (size_t i = 0; i < moveFrom.size(); ++i) {
        int from = moveFrom[i];
        int to = moveTo[i];
        auto it = posCount.find(from);
        if (it != posCount.end()) {
            int cnt = it->second;
            posCount[to] += cnt;
            posCount.erase(it);
        }
    }
    std::vector<int> result;
    result.reserve(posCount.size());
    for (const auto& kv : posCount) {
        result.push_back(kv.first);
    }
    std::sort(result.begin(), result.end());
    return result;
}

