long long countContinuousSubarrays(const std::vector<int>& nums) {
    long long total = 0;
    std::unordered_map<int, std::size_t> lastPos;
    std::size_t left = 0;
    for (std::size_t right = 0; right < nums.size(); ++right) {
        auto it = lastPos.find(nums[right]);
        if (it != lastPos.end() && it->second >= left) {
            left = it->second + 1;
        }
        lastPos[nums[right]] = right;
        total += static_cast<long long>(right - left + 1);
    }
    return total;
}

