int minimumLength(const std::vector<std::string>& words) {
    int n = static_cast<int>(words.size());
    if (n == 0) return 0;
    std::vector<int> lens(n);
    for (int i = 0; i < n; ++i) lens[i] = static_cast<int>(words[i].size());
    int totalLen = 0;
    for (int l : lens) totalLen += l;

    int fullMask = (1 << n) - 1;
    std::vector<std::vector<int>> dp(1 << n, std::vector<int>(n, -1));
    for (int i = 0; i < n; ++i) dp[1 << i][i] = 0;

    for (int mask = 0; mask <= fullMask; ++mask) {
        for (int last = 0; last < n; ++last) {
            if (dp[mask][last] < 0) continue;
            for (int nxt = 0; nxt < n; ++nxt) {
                if (mask & (1 << nxt)) continue;
                int add = (words[last].back() == words[nxt].front()) ? 1 : 0;
                int nmask = mask | (1 << nxt);
                dp[nmask][nxt] = std::max(dp[nmask][nxt], dp[mask][last] + add);
            }
        }
    }

    int best = 0;
    for (int last = 0; last < n; ++last) {
        best = std::max(best, dp[fullMask][last]);
    }
    return totalLen - best;
}

