std::string toBinary(unsigned long long x) {
    if (x == 0) return "0";
    std::string res;
    while (x > 0) {
        res.insert(res.begin(), (x & 1ULL) ? '1' : '0');
        x >>= 1ULL;
    }
    return res;
}

int minBeautifulSubstrings(const std::string& s) {
    const int n = static_cast<int>(s.size());
    std::vector<std::string> powers;
    unsigned long long val = 1ULL;
    while (true) {
        std::string bin = toBinary(val);
        if (static_cast<int>(bin.size()) > n) break;
        powers.push_back(bin);
        if (val > std::numeric_limits<unsigned long long>::max() / 5ULL) break;
        val *= 5ULL;
    }
    const long long INF = std::numeric_limits<long long>::max();
    std::vector<long long> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        for (const std::string& b : powers) {
            int len = static_cast<int>(b.size());
            if (len <= i && s.compare(i - len, len, b) == 0) {
                if (dp[i - len] != INF) {
                    dp[i] = std::min(dp[i], dp[i - len] + 1);
                }
            }
        }
    }
    return dp[n] == INF ? -1 : static_cast<int>(dp[n]);
}

