int maxJumps(const std::vector<int>& nums, int target) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return -1;
    if (n == 1) return 0;
    const int NEG_INF = INT_MIN;
    std::vector<int> dp(n, NEG_INF);
    dp[0] = 0;
    for (int i = 1; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (std::abs(nums[j] - nums[i]) <= target && dp[j] != NEG_INF) {
                dp[i] = std::max(dp[i], dp[j] + 1);
            }
        }
    }
    return dp[n - 1] == NEG_INF ? -1 : dp[n - 1];
}

#include <bits/stdc++.h>

long long sumImbalanceNumbers(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    long long total = 0;
    std::vector<int> freq(n + 2, 0);
    for (int i = 0; i < n; ++i) {
        std::fill(freq.begin(), freq.end(), 0);
        std::set<int> distinct;
        int cur = 0;
        for (int j = i; j < n; ++j) {
            int x = nums[j];
            if (freq[x] == 0) {
                auto it = distinct.lower_bound(x);
                int succ = -1, pred = -1;
                if (it != distinct.end()) succ = *it;
                if (it != distinct.begin()) {
                    auto it2 = it;
                    --it2;
                    pred = *it2;
                }
                int before = 0;
                if (pred != -1 && succ != -1) {
                    before = (succ - pred > 1) ? 1 : 0;
                }
                int after = 0;
                if (pred != -1) after += (x - pred > 1) ? 1 : 0;
                if (succ != -1) after += (succ - x > 1) ? 1 : 0;
                cur += (after - before);
                distinct.insert(x);
            }
            ++freq[x];
            total += cur;
        }
    }
    return total;
}

