bool checkArray(std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<long long> diff(n + 1, 0);
    long long cur = 0;
    for (int i = 0; i < n; ++i) {
        cur += diff[i];
        long long need = static_cast<long long>(nums[i]) - cur;
        if (need < 0) return false;
        if (need > 0) {
            if (i + k > n) return false;
            cur += need;
            diff[i + k] -= need;
        }
    }
    return true;
}

