std::vector<long long> numberOfBlackBlocks(int m, int n, const std::vector<std::vector<int>>& coordinates) {
    std::vector<long long> ans(5, 0);
    std::unordered_map<std::string, int> blockCount;
    for (const auto& coord : coordinates) {
        int x = coord[0];
        int y = coord[1];
        for (int dx = -1; dx <= 0; ++dx) {
            for (int dy = -1; dy <= 0; ++dy) {
                int i = x + dx;
                int j = y + dy;
                if (i < 0 || j < 0 || i >= m - 1 || j >= n - 1) continue;
                std::string key = std::to_string(i) + "," + std::to_string(j);
                ++blockCount[key];
            }
        }
    }
    for (const auto& kv : blockCount) {
        ans[kv.second]++;
    }
    long long totalBlocks = std::max(0, (m - 1) * (n - 1));
    long long nonZero = ans[1] + ans[2] + ans[3] + ans[4];
    ans[0] = totalBlocks - nonZero;
    return ans;
}

