int maxLength(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    int n = nums1.size();
    int best = 1;
    int prev1 = 1, prev2 = 1; // lengths ending at previous index using nums1[i-1] and nums2[i-1]
    for (int i = 0; i < n; ++i) {
        int cur1 = 1, cur2 = 1;
        if (i > 0) {
            if (nums1[i - 1] <= nums1[i]) cur1 = std::max(cur1, prev1 + 1);
            if (nums2[i - 1] <= nums1[i]) cur1 = std::max(cur1, prev2 + 1);
            if (nums1[i - 1] <= nums2[i]) cur2 = std::max(cur2, prev1 + 1);
            if (nums2[i - 1] <= nums2[i]) cur2 = std::max(cur2, prev2 + 1);
        }
        best = std::max({best, cur1, cur2});
        prev1 = cur1;
        prev2 = cur2;
    }
    return best;
}

