int maximumBeauty(std::vector<int> nums, int k) {
    std::vector<std::pair<long long, int>> events;
    events.reserve(nums.size() * 2);
    for (int v : nums) {
        long long L = static_cast<long long>(v) - k;
        long long R = static_cast<long long>(v) + k;
        events.emplace_back(L, 1);
        events.emplace_back(R + 1, -1);
    }
    std::sort(events.begin(), events.end(),
              [](const std::pair<long long, int>& a, const std::pair<long long, int>& b) {
                  if (a.first != b.first) return a.first < b.first;
                  return a.second < b.second; // process -1 before +1 at same point
              });
    int cur = 0, best = 0;
    for (const auto& e : events) {
        cur += e.second;
        if (cur > best) best = cur;
    }
    return best;
}

