    int n = static_cast<int>(word.size());
    int left = 0, best = 0;
    for (int i = 0; i < n; ++i) {
        for (int len = 1; len <= 10 && len <= i + 1; ++len) {
            std::string sub = word.substr(i - len + 1, len);
            if (forb.find(sub) != forb.end()) {
                left = std::max(left, i - len + 2);
            }
        }
        best = std::max(best, i - left + 1);
    }
    return best;
}

#include <bits/stdc++.h>

long long maxScore(const std::vector<int>& nums, int x) {
    const long long NEG_INF = -4e18;
    long long bestEven = NEG_INF, bestOdd = NEG_INF;
    if (nums.empty()) return 0;
    if (nums[0] % 2 == 0) bestEven = nums[0];
    else bestOdd = nums[0];
    for (size_t i = 1; i < nums.size(); ++i) {
        long long val = nums[i];
        bool isEven = (val % 2 == 0);
        long long same = isEven ? bestEven : bestOdd;
        long long opp = isEven ? bestOdd : bestEven;
        long long candidate = val + std::max(same, opp - x);
        if (isEven) bestEven = std::max(bestEven, candidate);
        else bestOdd = std::max(bestOdd, candidate);
    }
    return std::max(bestEven, bestOdd);
}

