long long maxPossibleElement(const std::vector<long long>& nums) {
    std::vector<long long> stack;
    long long max = 0;
    for (int i = static_cast<int>(nums.size()) - 1; i >= 0; --i) {
        long long cur = nums[i];
        while (!stack.empty() && cur <= stack.back()) {
            cur += stack.back();
            stack.pop_back();
        }
        stack.push_back(cur);
        if (cur > max) {
            max = cur;
        }
    }
    return max;
}

