std::vector<std::string> splitStringsBySeparator(const std::vector<std::string>& words, const std::string& separator) {
    std::vector<std::string> result;
    for (size_t i = 0; i < words.size(); ++i) {
        const std::string& w = words[i];
        if (separator.empty()) {
            for (char c : w) {
                std::string part(1, c);
                if (!part.empty()) {
                    result.push_back(part);
                }
            }
            continue;
        }
        size_t start = 0;
        while (true) {
            size_t pos = w.find(separator, start);
            if (pos == std::string::npos) {
                std::string part = w.substr(start);
                if (!part.empty()) {
                    result.push_back(part);
                }
                break;
            } else {
                std::string part = w.substr(start, pos - start);
                if (!part.empty()) {
                    result.push_back(part);
                }
                start = pos + separator.size();
            }
        }
    }
    return result;
}

