std::string sortVowels(const std::string& s) {
    auto isVowel = [](char c) {
        static const std::string vowels = "aeiouAEIOU";
        return vowels.find(c) != std::string::npos;
    };

    std::vector<char> vowels;
    for (size_t i = 0; i < s.size(); ++i) {
        if (isVowel(s[i])) {
            vowels.push_back(s[i]);
        }
    }

    std::sort(vowels.begin(), vowels.end());

    std::string result;
    result.reserve(s.size());
    size_t vi = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        if (isVowel(s[i])) {
            result.push_back(vowels[vi++]);
        } else {
            result.push_back(s[i]);
        }
    }
    return result;
}

#include <bits/stdc++.h>
long long countPairs(const std::vector<int>& parent, const std::string& s) {
    int n = parent.size();
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) {
        children[parent[i]].push_back(i);
    }
    std::vector<int> mask(n, 0);
    std::unordered_map<int, int> freq;
    freq.reserve(n * 2);
    freq.max_load_factor(0.7);
    freq[0] = 1; // root mask
    long long ans = 0;
    std::function<void(int)> dfs = [&](int u) {
        for (int v : children[u]) {
            int bit = s[v] - 'a';
            mask[v] = mask[u] ^ (1 << bit);
            int cur = mask[v];
            auto it = freq.find(cur);
            if (it != freq.end()) ans += it->second;
            for (int b = 0; b < 26; ++b) {
                int nxt = cur ^ (1 << b);
                it = freq.find(nxt);
                if (it != freq.end()) ans += it->second;
            }
            ++freq[cur];
            dfs(v);
        }
    };
    dfs(0);
    return ans;
}

