int countWays(int n, int x) {
    const int MOD = 1000000007;
    std::vector<long long> powers;
    for (int i = 1; ; ++i) {
        long long v = 1;
        for (int j = 0; j < x; ++j) {
            v *= i;
            if (v > n) break;
        }
        if (v > n) break;
        powers.push_back(v);
    }
    std::vector<int> dp(n + 1, 0);
    dp[0] = 1;
    for (long long v : powers) {
        for (int s = n; s >= v; --s) {
            dp[s] = (dp[s] + dp[s - v]) % MOD;
        }
    }
    return dp[n];
}

