int maxIncreasingGroups(const std::vector<int>& usageLimits) {
    int n = static_cast<int>(usageLimits.size());
    int low = 0, high = n;
    while (low < high) {
        int mid = (low + high + 1) / 2;
        long long sum = 0;
        for (int v : usageLimits) {
            sum += std::min<long long>(v, mid);
        }
        long long need = 1LL * mid * (mid + 1) / 2;
        if (sum >= need) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

