long long countCompleteSubarrays(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::unordered_set<int> distinctSet(nums.begin(), nums.end());
    int totalDistinct = static_cast<int>(distinctSet.size());

    std::unordered_map<int, int> freq;
    int distinctInWindow = 0;
    long long ans = 0;
    int right = 0;

    for (int left = 0; left < n; ++left) {
        while (right < n && distinctInWindow < totalDistinct) {
            int val = nums[right];
            if (++freq[val] == 1) {
                ++distinctInWindow;
            }
            ++right;
        }
        if (distinctInWindow == totalDistinct) {
            ans += static_cast<long long>(n - right + 1);
        } else {
            break;
        }
        int leftVal = nums[left];
        if (--freq[leftVal] == 0) {
            --distinctInWindow;
        }
    }
    return ans;
}

