std::string shortestString(std::string a, std::string b, std::string c) {
    auto merge = [](const std::string& s, const std::string& t) -> std::string {
        if (s.find(t) != std::string::npos) return s;
        if (t.find(s) != std::string::npos) return t;
        int maxOverlap = 0;
        int limit = std::min(s.size(), t.size());
        for (int l = 1; l <= limit; ++l) {
            if (s.compare(s.size() - l, l, t, 0, l) == 0) {
                maxOverlap = l;
            }
        }
        return s + t.substr(maxOverlap);
    };
    std::vector<std::string> strs = {a, b, c};
    std::vector<int> idx = {0, 1, 2};
    std::string best;
    bool first = true;
    do {
        std::string cur = strs[idx[0]];
        cur = merge(cur, strs[idx[1]]);
        cur = merge(cur, strs[idx[2]]);
        if (first || cur.size() < best.size() || (cur.size() == best.size() && cur < best)) {
            best = cur;
            first = false;
        }
    } while (std::next_permutation(idx.begin(), idx.end()));
    return best;
}

