static int gcd(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

ListNode* insertGreatestCommonDivisors(ListNode* head) {
    ListNode* cur = head;
    while (cur && cur->next) {
        int g = gcd(cur->val, cur->next->val);
        ListNode* newNode = new ListNode(g, cur->next);
        cur->next = newNode;
        cur = newNode->next;
    }
    return head;
}

