static const long long MOD = 1000000007LL;

long long dfsDP(int pos, int prev, bool tight, bool started, const string& s,
                vector<vector<vector<vector<long long>>>>& memo) {
    if (pos == (int)s.size()) return started ? 1 : 0;
    int prevIdx = (prev == -1 ? 10 : prev);
    long long& res = memo[pos][prevIdx][tight][started];
    if (res != -1) return res;
    long long ans = 0;
    int limit = tight ? (s[pos] - '0') : 9;
    for (int d = 0; d <= limit; ++d) {
        bool newStarted = started || (d != 0);
        int newPrev = -1;
        if (!newStarted) {
            newPrev = -1;
        } else if (!started) {
            newPrev = d;
        } else {
            if (abs(d - prev) != 1) continue;
            newPrev = d;
        }
        bool newTight = tight && (d == limit);
        ans += dfsDP(pos + 1, newPrev, newTight, newStarted, s, memo);
        if (ans >= MOD) ans -= MOD;
    }
    res = ans % MOD;
    return res;
}

long long countUpTo(const string& s) {
    int n = s.size();
    vector<vector<vector<vector<long long>>>> memo(
        n, vector<vector<vector<long long>>>(11, vector<vector<long long>>(2, vector<long long>(2, -1))));
    return dfsDP(0, -1, true, false, s, memo);
}

string subtractOne(string s) {
    int i = s.size() - 1;
    while (i >= 0 && s[i] == '0') {
        s[i] = '9';
        --i;
    }
    if (i >= 0) s[i]--;
    size_t pos = s.find_first_not_of('0');
    if (pos == string::npos) return "0";
    return s.substr(pos);
}

int countSteppingNumbers(string low, string high) {
    long long highCnt = countUpTo(high);
    string lowMinusOne = subtractOne(low);
    long long lowCnt = countUpTo(lowMinusOne);
    long long ans = (highCnt - lowCnt) % MOD;
    if (ans < 0) ans += MOD;
    return (int)ans;
}

