long long findMaximumElegance(const std::vector<std::vector<int>>& items, int k) {
    struct Item {
        long long profit;
        int category;
    };
    std::vector<Item> a;
    a.reserve(items.size());
    for (const auto& v : items) {
        a.push_back({static_cast<long long>(v[0]), v[1]});
    }
    std::sort(a.begin(), a.end(), [](const Item& x, const Item& y) {
        return x.profit > y.profit;
    });

    std::unordered_map<int, int> freq;
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> dupHeap;

    long long sum = 0;
    int distinct = 0;
    for (int i = 0; i < k; ++i) {
        const Item& it = a[i];
        sum += it.profit;
        if (freq[it.category] == 0) {
            ++distinct;
        } else {
            dupHeap.push(it.profit);
        }
        ++freq[it.category];
    }

    long long best = sum + 1LL * distinct * distinct;

    for (std::size_t i = static_cast<std::size_t>(k); i < a.size(); ++i) {
        const Item& it = a[i];
        if (freq[it.category] > 0) {
            continue; // category already present
        }
        if (dupHeap.empty()) {
            break; // no duplicate to replace
        }
        long long smallestDup = dupHeap.top();
        dupHeap.pop();
        sum = sum - smallestDup + it.profit;
        ++distinct;
        freq[it.category] = 1;
        best = std::max(best, sum + 1LL * distinct * distinct);
    }

    return best;
}

#include <bits/stdc++.h>
int minimumSeconds(std::vector<int>& nums) {
    int n = nums.size();
    std::unordered_map<int, std::vector<int>> pos;
    pos.reserve(n * 2);
    for (int i = 0; i < n; ++i) {
        pos[nums[i]].push_back(i);
    }
    int answer = n; // upper bound
    for (auto& kv : pos) {
        const std::vector<int>& v = kv.second;
        int maxGap = 0;
        for (size_t i = 1; i < v.size(); ++i) {
            int gap = v[i] - v[i - 1] - 1;
            if (gap > maxGap) maxGap = gap;
        }
        // circular gap
        int circularGap = (v.front() + n) - v.back() - 1;
        if (circularGap > maxGap) maxGap = circularGap;
        int seconds = (maxGap + 1) / 2;
        if (seconds < answer) answer = seconds;
    }
    return answer;
}

