std::string faultyKeyboard(const std::string& s) {
    std::deque<char> result;
    bool reversed = false;
    for (char ch : s) {
        if (ch == 'i') {
            reversed = !reversed;
        } else {
            if (!reversed) {
                result.push_back(ch);
            } else {
                result.push_front(ch);
            }
        }
