ListNode* doubleLinkedList(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* cur = head;
    while (cur) { ListNode* nxt = cur->next; cur->next = prev; prev = cur; cur = nxt; }
    ListNode* node = prev;
    int carry = 0;
    while (node) {
        int sum = node->val * 2 + carry;
        node->val = sum % 10;
        carry = sum / 10;
        if (!node->next && carry) {
            node->next = new ListNode(carry);
            carry = 0;
            break; // FIX: don't re-process the freshly appended carry digit
        }
        node = node->next;
    }
    cur = prev; prev = nullptr;
    while (cur) { ListNode* nxt = cur->next; cur->next = prev; prev = cur; cur = nxt; }
    return prev;
}

