struct Node {
    long long key;
    uint32_t pri;
    int cnt;
    Node* left;
    Node* right;
    Node(long long k, uint32_t p) : key(k), pri(p), cnt(1), left(nullptr), right(nullptr) {}
};

static std::mt19937 _rng(std::random_device{}());
static std::uniform_int_distribution<uint32_t> _dist;

static Node* rotateRight(Node* p) {
    Node* q = p->left;
    p->left = q->right;
    q->right = p;
    return q;
}

static Node* rotateLeft(Node* p) {
    Node* q = p->right;
    p->right = q->left;
    q->left = p;
    return q;
}

static Node* insert(Node* node, long long key) {
    if (!node) return new Node(key, _dist(_rng));
    if (key == node->key) {
        node->cnt++;
    } else if (key < node->key) {
        node->left = insert(node->left, key);
        if (node->left->pri < node->pri) node = rotateRight(node);
    } else {
        node->right = insert(node->right, key);
        if (node->right->pri < node->pri) node = rotateLeft(node);
    }
    return node;
}

static Node* lowerBound(Node* node, long long key) {
    if (!node) return nullptr;
    if (node->key >= key) {
        Node* left = lowerBound(node->left, key);
        return left ? left : node;
    }
    return lowerBound(node->right, key);
}

static Node* predecessor(Node* node, long long key) {
    if (!node) return nullptr;
    if (node->key < key) {
        Node* right = predecessor(node->right, key);
        return right ? right : node;
    }
    return predecessor(node->left, key);
}

long long minimumAbsoluteDifference(const std::vector<int>& nums, int x) {
    Node* root = nullptr;
    long long best = LLONG_MAX;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (static_cast<long long>(i) - x >= 0) {
            root = insert(root, nums[i - x]);
        }
        Node* lb = lowerBound(root, nums[i]);
        if (lb) {
            long long diff = std::llabs(lb->key - nums[i]);
            if (diff < best) best = diff;
        }
        Node* pred = predecessor(root, nums[i]);
        if (pred) {
            long long diff = std::llabs(pred->key - nums[i]);
            if (diff < best) best = diff;
        }
    }
    return best == LLONG_MAX ? 0 : best;
}

#include <bits/stdc++.h>
using namespace std;

long long maxScore(std::vector<int> nums, int k) {
    int n = nums.size();
    const long long MOD = 1000000007;
    auto primeScore = [](int x) {
        int count = 0;
        for (int p = 2; (long long)p * p <= x; p++) {
            if (x % p == 0) {
                count++;
                while (x % p == 0) x /= p;
            }
        }
        if (x > 1) count++;
        return count;
    };
    vector<int> scores(n);
    for (int i = 0; i < n; i++) scores[i] = primeScore(nums[i]);

    vector<int> left(n, -1), right(n, n);
    vector<int> stk;
    for (int i = 0; i < n; i++) {
        while (!stk.empty() && scores[stk.back()] < scores[i]) stk.pop_back();
        left[i] = stk.empty() ? -1 : stk.back();
        stk.push_back(i);
    }
    stk.clear();
    for (int i = n - 1; i >= 0; i--) {
        while (!stk.empty() && scores[stk.back()] <= scores[i]) stk.pop_back();
        right[i] = stk.empty() ? n : stk.back();
        stk.push_back(i);
    }

    vector<long long> count(n);
    for (int i = 0; i < n; i++) count[i] = (long long)(i - left[i]) * (right[i] - i);

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) { return nums[a] > nums[b]; });

    auto modpow = [&](long long base, long long exp, long long mod) {
        base %= mod;
        long long result = 1;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    };

    long long remaining = k;
    long long ans = 1;
    for (int i : order) {
        if (remaining <= 0) break;
        long long take = min(count[i], remaining);
        ans = (ans * modpow(nums[i], take, MOD)) % MOD;
        remaining -= take;
    }
    return ans;
}

