int maxPairSum(const std::vector<int>& nums) {
    std::vector<int> first(10, -1);
    std::vector<int> second(10, -1);

    for (size_t i = 0; i < nums.size(); ++i) {
        int n = nums[i];
        int maxDigit = 0;
        if (n == 0) {
            maxDigit = 0;
        } else {
            while (n > 0) {
                int d = n % 10;
                if (d > maxDigit) maxDigit = d;
                n = n / 10;
            }
        }

        if (nums[i] > first[maxDigit]) {
            second[maxDigit] = first[maxDigit];
            first[maxDigit] = nums[i];
        } else if (nums[i] > second[maxDigit]) {
            second[maxDigit] = nums[i];
        }
    }

    int best = -1;
    for (int d = 0; d < 10; ++d) {
        if (second[d] != -1) {
            int sum = first[d] + second[d];
            if (sum > best) best = sum;
        }
    }
    return best;
}

#include <bits/stdc++.h>

int maximumSafenessFactor(std::vector<std::vector<int>>& grid) {
    int n = grid.size();
    const int INF = 1e9;
    std::vector<std::vector<int>> dist(n, std::vector<int>(n, INF));
    std::queue<std::pair<int, int>> q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                dist[i][j] = 0;
                q.emplace(i, j);
            }
        }
    }
    const int dr[4] = { -1, 1, 0, 0 };
    const int dc[4] = { 0, 0, -1, 1 };
    while (!q.empty()) {
        std::pair<int, int> cur = q.front();
        q.pop();
        int r = cur.first;
        int c = cur.second;
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
            if (dist[nr][nc] > dist[r][c] + 1) {
                dist[nr][nc] = dist[r][c] + 1;
                q.emplace(nr, nc);
            }
        }
    }
    std::vector<std::vector<int>> best(n, std::vector<int>(n, -1));
    using Node = std::tuple<int, int, int>;
    std::priority_queue<Node> pq;
    best[0][0] = dist[0][0];
    pq.emplace(best[0][0], 0, 0);
    while (!pq.empty()) {
        Node curNode = pq.top();
        pq.pop();
        int safety = std::get<0>(curNode);
        int r = std::get<1>(curNode);
        int c = std::get<2>(curNode);
        if (r == n - 1 && c == n - 1) return safety;
        if (safety < best[r][c]) continue;
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (nr < 0 || nr >= n || nc < 0 || nc >= n) continue;
            int newSafety = std::min(safety, dist[nr][nc]);
            if (newSafety > best[nr][nc]) {
                best[nr][nc] = newSafety;
                pq.emplace(newSafety, nr, nc);
            }
        }
    }
    return best[n - 1][n - 1];
}

