bool makeStringSubsequence(const std::string& str1, const std::string& str2) {
    std::size_t n = str1.size(), m = str2.size();
    std::size_t i = 0, j = 0;
    while (i < n && j < m) {
        char cur = str1[i];
        char next = (cur == 'z') ? 'a' : static_cast<char>(cur + 1);
        if (cur == str2[j] || next == str2[j]) {
            ++j;
        }
        ++i;
    }
    return j == m;
}

