int maxProfit(int n, const std::vector<std::vector<int>>& offers) {
    std::vector<std::vector<int>> sortedOffers = offers;
    std::sort(sortedOffers.begin(), sortedOffers.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[1] < b[1];
              });

    int m = static_cast<int>(sortedOffers.size());
    std::vector<int> ends(m);
    std::vector<int> dp(m);

    for (int i = 0; i < m; ++i) {
        ends[i] = sortedOffers[i][1];
    }

    for (int i = 0; i < m; ++i) {
        int start = sortedOffers[i][0];
        int gold = sortedOffers[i][2];

        int lo = 0, hi = i - 1, prev = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (ends[mid] < start) {
                prev = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        int take = gold + (prev >= 0 ? dp[prev] : 0);
        int skip = i > 0 ? dp[i - 1] : 0;
        dp[i] = take > skip ? take : skip;
    }

    return m > 0 ? dp[m - 1] : 0;
}

