#include <bits/stdc++.h>

long long countUpTo(long long x, int k) {
    if (x < 0) return 0;
    std::vector<int> digits;
    if (x == 0) {
        digits.push_back(0);
    } else {
        while (x > 0) {
            digits.push_back(static_cast<int>(x % 10));
            x /= 10;
        }
        std::reverse(digits.begin(), digits.end());
    }
    int n = static_cast<int>(digits.size());
    int offset = n; // maximum absolute difference
    std::vector<std::vector<std::vector<std::vector<long long>>>> memo(
        n,
        std::vector<std::vector<std::vector<long long>>>(
            2 * offset + 1,
            std::vector<std::vector<long long>>(k, std::vector<long long>(2, -1))
        )
    );

    std::function<long long(int,int,int,bool,bool)> dfs = [&](int pos, int diff, int rem, bool tight, bool started) -> long long {
        if (pos == n) {
            return (started && diff == 0 && rem == 0) ? 1LL : 0LL;
        }
        if (!tight) {
            long long &cached = memo[pos][diff + offset][rem][started];
            if (cached != -1) return cached;
            long long ans = 0;
            for (int d = 0; d <= 9; ++d) {
                bool nstarted = started || (d != 0);
                int ndiff = diff;
                int nrem = rem;
                if (nstarted) {
                    ndiff += (d % 2 == 0) ? -1 : 1;
                    nrem = (rem * 10 + d) % k;
                }
                ans += dfs(pos + 1, ndiff, nrem, false, nstarted);
            }
            cached = ans;
            return ans;
        } else {
            long long ans = 0;
            int limit = digits[pos];
            for (int d = 0; d <= limit; ++d) {
                bool ntight = tight && (d == limit);
                bool nstarted = started || (d != 0);
                int ndiff = diff;
                int nrem = rem;
                if (nstarted) {
                    ndiff += (d % 2 == 0) ? -1 : 1;
                    nrem = (rem * 10 + d) % k;
                }
                ans += dfs(pos + 1, ndiff, nrem, ntight, nstarted);
            }
            return ans;
        }
    };

    return dfs(0, 0, 0, true, false);
}

int beautifulIntegers(int low, int high, int k) {
    long long result = countUpTo(high, k) - countUpTo(static_cast<long long>(low) - 1, k);
    return static_cast<int>(result);
}

