int longestEqualSubarray(const std::vector<int>& nums, int k) {
    if (nums.empty()) return 0;
    int maxVal = 0;
    for (int v : nums) if (v > maxVal) maxVal = v;
    std::vector<std::vector<int>> pos(maxVal + 1);
    for (int i = 0; i < (int)nums.size(); ++i) {
        pos[nums[i]].push_back(i);
    }
    int answer = 0;
    for (const auto& indices : pos) {
        if (indices.empty()) continue;
        int left = 0;
        for (int right = 0; right < (int)indices.size(); ++right) {
            while ((indices[right] - indices[left] + 1) - (right - left + 1) > k) {
                ++left;
            }
            int cnt = right - left + 1;
            if (cnt > answer) answer = cnt;
        }
    }
    return answer;
}

