long long minimumBeautifulArraySum(long long n, long long target) {
    const long long MOD = 1000000007LL;
    long long N = n;
    long long T = target;
    long long A = T / 2;
    long long countUpToTarget = A + 1;
    long long sum;
    if (N <= A) {
        sum = N * (N + 1) / 2;
    } else if (N == countUpToTarget) {
        sum = A * (A + 1) / 2 + T;
    } else {
        long long extra = N - countUpToTarget;
        sum = A * (A + 1) / 2 + T + extra * T + extra * (extra + 1) / 2;
    }
    long long res = sum % MOD;
    if (res < 0) res += MOD;
    return res;
}

#include <bits/stdc++.h>

long long maxScore(const std::vector<int>& receiver, long long k) {
    const std::size_t n = receiver.size();
    long long best = 0;
    for (std::size_t start = 0; start < n; ++start) {
        long long cur = static_cast<long long>(start);
        long long steps = 0;
        long long sum = cur;               // include starting node
        ++steps;
        std::unordered_map<long long, long long> visited;
        std::vector<long long> path;
        visited[cur] = 0;
        path.push_back(cur);
        while (steps <= k) {
            cur = receiver[static_cast<std::size_t>(cur)];
            if (steps == k + 1) break;    // already have k+1 nodes
            if (visited.find(cur) != visited.end()) break;
            visited[cur] = steps;
            path.push_back(cur);
            sum += cur;
            ++steps;
        }
        if (steps == k + 1) {
            best = std::max(best, sum);
            continue;
        }
        // cur is the first repeated node, not yet added for remaining steps
        long long remaining = k + 1 - steps; // nodes still needed
        long long cycleStartIdx = visited[cur];
        long long cycleLen = steps - cycleStartIdx;
        long long cycleSum = 0;
        for (long long i = cycleStartIdx; i < steps; ++i) {
            cycleSum += path[i];
        }
        long long fullCycles = remaining / cycleLen;
        sum += fullCycles * cycleSum;
        remaining %= cycleLen;
        for (long long i = 0; i < remaining; ++i) {
            sum += path[cycleStartIdx + i];
        }
        best = std::max(best, sum);
    }
    return best;
}

