        ++cnt[idx];
        if (cnt[idx] > 1) hasDuplicate = true;
    }
    for (char c : s2) {
        int idx = static_cast<int>(c) - aCode;
        --cnt[idx];
    }
    for (int v : cnt) {
        if (v != 0) return false;
    }
    if (hasDuplicate) return true;
    int mismatches = 0;
    for (size_t i = 0; i < s1.size(); ++i) {
        if (s1[i] != s2[i]) ++mismatches;
