long long maxSumAlmostUnique(const std::vector<int>& nums, int m, int k) {
    if (k > static_cast<int>(nums.size())) return 0;
    std::unordered_map<int, int> freq;
    int distinctCount = 0;
    long long windowSum = 0;
    long long best = 0;
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        int right = nums[i];
        windowSum += right;
        int rightFreq = (freq.count(right) ? freq[right] : 0) + 1;
        freq[right] = rightFreq;
        if (rightFreq == 1) ++distinctCount;
        if (i >= k) {
            int left = nums[i - k];
            windowSum -= left;
            int leftFreq = freq[left] - 1;
            if (leftFreq == 0) {
                freq.erase(left);
                --distinctCount;
            } else {
                freq[left] = leftFreq;
            }
        }
        if (i >= k - 1) {
            if (distinctCount >= m && windowSum > best) {
                best = windowSum;
            }
        }
    }
    return best;
}

#include <bits/stdc++.h>
#include <vector>

int minOperations(const std::vector<int>& nums, int target) {
    const int MAX_BITS = 31;
    std::vector<int> cnt(MAX_BITS, 0);
    for (int v : nums) {
        int e = 0;
        while (v > 1) {
            v >>= 1;
            ++e;
        }
        cnt[e]++;
    }
    long long ops = 0;
    for (int i = 0; i < MAX_BITS; ++i) {
        if ((target >> i) & 1) {
            if (cnt[i] > 0) {
                cnt[i]--;
            } else {
                int j = i + 1;
                while (j < MAX_BITS && cnt[j] == 0) ++j;
                if (j == MAX_BITS) return -1;
                while (j > i) {
                    cnt[j]--;
                    cnt[j - 1] += 2;
                    ++ops;
                    --j;
                }
                cnt[i]--;
            }
        }
        if (i + 1 < MAX_BITS) {
            cnt[i + 1] += cnt[i] / 2;
        }
    }
    return static_cast<int>(ops);
}

