            if (deletions < answer) answer = deletions;
            break;
        }
    }
    return answer;
}

#include <bits/stdc++.h>
std::vector<int> minOperationsQueries(int n, const std::vector<std::vector<int>>& edges, const std::vector<std::vector<int>>& queries) {
    const int MAXW = 26;
    const int LOG = 15; // since 2^14 > 10000
    std::vector<std::vector<std::pair<int,int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1], w = e[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    std::vector<int> depth(n, 0);
    std::vector<std::array<int, MAXW+1>> pref(n);
    for (auto& arr : pref) arr.fill(0);
    std::vector<std::array<int, LOG>> up(n);
    for (auto& arr : up) arr.fill(-1);
    std::function<void(int,int,int)> dfs = [&](int u, int p, int w) {
        up[u][0] = p;
        if (p != -1) {
            depth[u] = depth[p] + 1;
            pref[u] = pref[p];
            pref[u][w] += 1;
        }
        for (const auto& edge : adj[u]) {
            int v = edge.first;
            int wt = edge.second;
            if (v == p) continue;
            dfs(v, u, wt);
        }
    };
    dfs(0, -1, 0);
    for (int k = 1; k < LOG; ++k) {
        for (int v = 0; v < n; ++v) {
            int mid = up[v][k-1];
            up[v][k] = (mid == -1 ? -1 : up[mid][k-1]);
        }
    }
    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) std::swap(a, b);
        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; ++k) {
            if (diff & (1<<k)) a = up[a][k];
        }
        if (a == b) return a;
        for (int k = LOG-1; k >= 0; --k) {
            if (up[a][k] != up[b][k]) {
                a = up[a][k];
                b = up[b][k];
            }
        }
        return up[a][0];
    };
    std::vector<int> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        int a = q[0], b = q[1];
        int L = lca(a, b);
        int pathLen = depth[a] + depth[b] - 2 * depth[L];
        int best = 0;
        for (int w = 1; w <= MAXW; ++w) {
            int cnt = pref[a][w] + pref[b][w] - 2 * pref[L][w];
            if (cnt > best) best = cnt;
        }
        ans.push_back(pathLen - best);
    }
    return ans;
}

