using namespace std;

static const long long MOD = 1000000007LL;

long long modPow(long long a, long long e) {
    long long res = 1 % MOD;
    a %= MOD;
    while (e > 0) {
        if (e & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return res;
}

int countKSubsequences(const string& s, int k) {
    long long freq[26] = {0};
    for (char ch : s) freq[ch - 'a']++;

    vector<long long> f;
    for (int i = 0; i < 26; ++i) if (freq[i] > 0) f.push_back(freq[i]);

    int distinct = (int)f.size();
    if (k > distinct) return 0;

    sort(f.begin(), f.end(), greater<long long>());
    long long threshold = f[k - 1];

    int cntGreater = 0, cntEqual = 0;
    long long productMandatory = 1;
    for (long long val : f) {
        if (val > threshold) {
            ++cntGreater;
            productMandatory = (productMandatory * (val % MOD)) % MOD;
        } else if (val == threshold) {
            ++cntEqual;
        }
    }

    int r = k - cntGreater; // number to choose from equal-frequency characters
    // precompute factorials up to 26
    static long long fact[27] = {0}, invFact[27] = {0};
    fact[0] = 1;
    for (int i = 1; i <= 26; ++i) fact[i] = (fact[i - 1] * i) % MOD;
    invFact[26] = modPow(fact[26], MOD - 2);
    for (int i = 25; i >= 0; --i) invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;

    auto comb = [&](int n, int k)->long long{
        if (k < 0 || k > n) return 0;
        return (((fact[n] * invFact[k]) % MOD) * invFact[n - k]) % MOD;
    };

    long long waysChoose = comb(cntEqual, r);
    long long powThresh = modPow(threshold % MOD, r);
    long long answer = productMandatory;
    answer = (answer * powThresh) % MOD;
    answer = (answer * waysChoose) % MOD;
    return (int)answer;
}

#include <bits/stdc++.h>
