int minMoves(std::vector<std::vector<int>>& grid) {
    std::vector<std::pair<int, int>> stones;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            for (int k = 0; k < grid[i][j]; ++k) {
                stones.emplace_back(i, j);
            }
        }
    }
    const int n = 9;
    int cost[n][n];
    for (int i = 0; i < n; ++i) {
        int si = stones[i].first;
        int sj = stones[i].second;
        for (int t = 0; t < n; ++t) {
            int ti = t / 3;
            int tj = t % 3;
            cost[i][t] = std::abs(si - ti) + std::abs(sj - tj);
        }
    }
    const int FULL = (1 << n) - 1;
    std::vector<int> dp(1 << n, INT_MAX);
    dp[0] = 0;
    for (int mask = 0; mask <= FULL; ++mask) {
        int i = __builtin_popcount(mask);
        if (i >= n || dp[mask] == INT_MAX) continue;
        for (int t = 0; t < n; ++t) {
            if (!(mask & (1 << t))) {
                int nmask = mask | (1 << t);
                dp[nmask] = std::min(dp[nmask], dp[mask] + cost[i][t]);
            }
        }
    }
    return dp[FULL];
}

#include <bits/stdc++.h>
#include <string>

static const long long MOD = 1000000007LL;

static long long modPow(long long base, long long exp) {
    long long res = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

static long long modInv(long long a) {
    return modPow(a, MOD - 2);
}

long long countTransformWays(const std::string& s, const std::string& t, long long k) {
    if (s.size() != t.size()) return 0;
    long long n = static_cast<long long>(s.size());
    if (n == 0) return (k == 0) ? 1 : 0;

    std::string ss = s + s;
    std::vector<long long> validShifts;
    for (long long i = 0; i < n; ++i) {
        if (ss.compare(i, n, t) == 0) {
            validShifts.push_back(i);
        }
    }
    if (validShifts.empty()) return 0;

    long long pow1 = modPow(n - 1, k);
    long long pow2 = (k % 2 == 0) ? 1 : MOD - 1; // (-1)^k mod MOD
    long long inv_n = modInv(n);

    long long ans = 0;
    for (long long shift : validShifts) {
        long long ways;
        if (shift == 0) {
            ways = (pow1 + ((n - 1) % MOD) * pow2) % MOD;
        } else {
            ways = (pow1 + MOD - pow2) % MOD;
        }
        ways = (ways * inv_n) % MOD;
        ans += ways;
        if (ans >= MOD) ans -= MOD;
    }
    return ans;
}

