long long countPairs(const std::vector<std::pair<int, int>>& coordinates, int k) {
    std::unordered_map<std::string, int> freq;
    for (const auto& p : coordinates) {
        int x = p.first;
        int y = p.second;
        std::string key = std::to_string(x) + ',' + std::to_string(y);
        auto it = freq.find(key);
        if (it != freq.end()) {
            it->second += 1;
        } else {
            freq.emplace(key, 1);
        }
    }

    long long ans = 0;

    for (const auto& p : coordinates) {
        int x = p.first;
        int y = p.second;
        std::string curKey = std::to_string(x) + ',' + std::to_string(y);
        auto curIt = freq.find(curKey);
        if (curIt != freq.end()) {
            curIt->second -= 1;
        }

        for (int a = 0; a <= k; ++a) {
            int b = k - a;
            int nx = x ^ a;
            int ny = y ^ b;
            std::string partnerKey = std::to_string(nx) + ',' + std::to_string(ny);
            auto it = freq.find(partnerKey);
            if (it != freq.end()) {
                ans += it->second;
            }
        }
    }

    return ans;
}

