long long countInterestingSubarrays(const std::vector<int>& nums, int modulo, int k) {
    std::unordered_map<long long, long long> freq;
    long long ans = 0;
    long long pref = 0;
    freq[0] = 1;
    for (int x : nums) {
        if (x % modulo == k) ++pref;
        long long need = (pref - k) % modulo;
        if (need < 0) need += modulo;
        auto it = freq.find(need);
        if (it != freq.end()) ans += it->second;
        long long rem = pref % modulo;
        freq[rem] += 1;
    }
    return ans;
}

