long long maximumSum(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> spf(n + 1);
    for (int i = 2; i <= n; ++i) {
        if (spf[i] == 0) {
            for (int j = i; j <= n; j += i) {
                if (spf[j] == 0) spf[j] = i;
            }
        }
    }
    std::unordered_map<int, long long> groupSum;
    long long best = 0;
    for (int idx = 1; idx <= n; ++idx) {
        int x = idx;
        int sf = 1;
        while (x > 1) {
            int p = spf[x];
            int cnt = 0;
            while (x % p == 0) {
                x /= p;
                ++cnt;
            }
            if (cnt % 2 == 1) sf *= p;
        }
        long long cur = groupSum[sf] + static_cast<long long>(nums[idx - 1]);
        groupSum[sf] = cur;
        if (cur > best) best = cur;
    }
    return best;
}

