long long maxNumberOfAlloys(int n, int k, long long budget,
                            const std::vector<std::vector<int>>& composition,
                            const std::vector<int>& stock,
                            const std::vector<int>& cost) {
    auto can = [&](long long x) -> bool {
        for (int i = 0; i < k; ++i) {
            long long total = 0;
            for (int j = 0; j < n; ++j) {
                long long need = x * static_cast<long long>(composition[i][j]) - static_cast<long long>(stock[j]);
                if (need > 0) {
                    total += need * static_cast<long long>(cost[j]);
                    if (total > budget) break;
                }
            }
            if (total <= budget) return true;
        }
        return false;
    };

    long long lo = 0, hi = 2000000000LL; // sufficiently large upper bound
    while (lo < hi) {
        long long mid = (lo + hi + 1) / 2;
        if (can(mid))
            lo = mid;
        else
            hi = mid - 1;
    }
    return lo;
}

class Solution {
public:
    int countWays(vector<int>& nums) {
        int n = nums.size();
        sort(nums.begin(), nums.end());
        int count = 0;
        for (int k = 0; k <= n; k++) {
            bool leftOk = (k == 0) || (nums[k-1] < k);
            bool rightOk = (k == n) || (nums[k] > k);
            if (leftOk && rightOk) count++;
        }
        return count;
    }
};

