long long maximumSum(const std::vector<int>& maxHeights) {
    int n = static_cast<int>(maxHeights.size());
    std::vector<long long> left(n), right(n);
    std::vector<std::pair<long long, long long>> st;
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        long long cnt = 1;
        while (!st.empty() && st.back().first >= static_cast<long long>(maxHeights[i])) {
            cnt += st.back().second;
            sum -= st.back().first * st.back().second;
            st.pop_back();
        }
        st.emplace_back(static_cast<long long>(maxHeights[i]), cnt);
        sum += static_cast<long long>(maxHeights[i]) * cnt;
        left[i] = sum;
    }
    st.clear();
    sum = 0;
    for (int i = n - 1; i >= 0; --i) {
        long long cnt = 1;
        while (!st.empty() && st.back().first >= static_cast<long long>(maxHeights[i])) {
            cnt += st.back().second;
            sum -= st.back().first * st.back().second;
            st.pop_back();
        }
        st.emplace_back(static_cast<long long>(maxHeights[i]), cnt);
        sum += static_cast<long long>(maxHeights[i]) * cnt;
        right[i] = sum;
    }
    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        long long total = left[i] + right[i] - static_cast<long long>(maxHeights[i]);
        if (total > ans) ans = total;
    }
    return ans;
}

