        long long leftSum = 0;
        long long cur = heights[peak];
        for (int j = peak; j >= 0; --j) {
            cur = std::min<long long>(cur, heights[j]);
            leftSum += cur;
        }
        long long rightSum = 0;
        cur = heights[peak];
        for (int j = peak; j < n; ++j) {
            cur = std::min<long long>(cur, heights[j]);
            rightSum += cur;
