long long countPaths(int n, std::vector<std::vector<int>> edges) {
    // Sieve for primality up to n
    std::vector<bool> isPrime(n + 1, true);
    if (n >= 0) isPrime[0] = false;
    if (n >= 1) isPrime[1] = false;
    for (int i = 2; i * i <= n; ++i) {
        if (isPrime[i]) {
            for (int j = i * i; j <= n; j += i) isPrime[j] = false;
        }
    }

    // Build adjacency list
    std::vector<std::vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // Find connected components consisting only of non‑prime nodes
    std::vector<int> compId(n + 1, -1);
    std::vector<long long> compSize;
    int compCnt = 0;
    std::vector<int> stack;
    for (int v = 1; v <= n; ++v) {
        if (isPrime[v] || compId[v] != -1) continue;
        long long sz = 0;
        stack.clear();
        stack.push_back(v);
        compId[v] = compCnt;
        while (!stack.empty()) {
            int cur = stack.back();
            stack.pop_back();
            ++sz;
            for (int nb : adj[cur]) {
                if (!isPrime[nb] && compId[nb] == -1) {
                    compId[nb] = compCnt;
                    stack.push_back(nb);
                }
            }
        }
        compSize.push_back(sz);
        ++compCnt;
    }

    long long answer = 0;
    // For each prime node, collect sizes of distinct adjacent non‑prime components
    std::vector<int> seen(compCnt, 0);
    int curMark = 1;
    for (int p = 1; p <= n; ++p) {
        if (!isPrime[p]) continue;
        long long total = 0;
        long long sumSq = 0;
        for (int nb : adj[p]) {
            if (isPrime[nb]) continue;
            int cid = compId[nb];
            if (cid == -1) continue;
            if (seen[cid] == curMark) continue;
            seen[cid] = curMark;
            long long sz = compSize[cid];
            total += sz;
            sumSq += sz * sz;
        }
        ++curMark;
        if (total == 0) continue;
        long long pairs = total + (total * total - sumSq) / 2;
        answer += pairs;
    }
    return answer;
}

