struct Result {
    long long modSum;
    long long compCnt;
};

long long maxKDivisibleComponents(int n, const std::vector<std::pair<int, int>>& edges, const std::vector<long long>& values, long long k) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e.first;
        int v = e.second;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::function<Result(int, int)> dfs = [&](int u, int parent) -> Result {
        long long sumMod = values[u] % k;
        long long comps = 0;
        for (int v : adj[u]) {
            if (v == parent) continue;
            Result child = dfs(v, u);
            if (child.modSum == 0) {
                comps += child.compCnt + 1;
            } else {
                comps += child.compCnt;
                sumMod = (sumMod + child.modSum) % k;
            }
        }
        return {sumMod, comps};
    };

    Result root = dfs(0, -1);
    return root.compCnt + (root.modSum == 0 ? 1 : 0);
}

