long long maxValue(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n < 3) return 0;
    std::vector<long long> bestDiff(n, LLONG_MIN);
    long long maxLeft = nums[0];
    for (int j = 1; j < n; ++j) {
        long long diff = maxLeft - static_cast<long long>(nums[j]);
        if (j == 1) bestDiff[j] = diff;
        else bestDiff[j] = std::max(bestDiff[j - 1], diff);
        maxLeft = std::max(maxLeft, static_cast<long long>(nums[j]));
    }
    std::vector<long long> suffixMax(n);
    suffixMax[n - 1] = nums[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        suffixMax[i] = std::max(static_cast<long long>(nums[i]), suffixMax[i + 1]);
    }
    long long ans = LLONG_MIN;
    for (int j = 1; j <= n - 2; ++j) {
        long long cur = bestDiff[j] * suffixMax[j + 1];
        ans = std::max(ans, cur);
    }
    return std::max(0LL, ans);
}

