std::vector<int> countVisitedNodes(const std::vector<int>& edges) {
    int n = static_cast<int>(edges.size());
    std::vector<int> answer(n);
    std::vector<char> state(n, 0); // 0 = unvisited, 1 = visiting, 2 = visited
    std::function<int(int)> dfs = [&](int u) -> int {
        if (state[u] == 2) return answer[u];
        if (state[u] == 1) {
            int cur = u;
            int size = 0;
            do {
                ++size;
                cur = edges[cur];
            } while (cur != u);
            cur = u;
            do {
                answer[cur] = size;
                state[cur] = 2;
                cur = edges[cur];
            } while (cur != u);
            return answer[u];
        }
        state[u] = 1;
        int v = edges[u];
        int childAns = dfs(v);
        if (state[u] == 1) {
            answer[u] = childAns + 1;
            state[u] = 2;
        }
        return answer[u];
    };
    for (int i = 0; i < n; ++i) {
        if (state[i] == 0) dfs(i);
    }
    return answer;
}

