long long minimumSizeSubarrayInInfiniteArray(const std::vector<long long>& nums, long long target) {
    size_t n = nums.size();
    std::vector<long long> prefix(n + 1);
    prefix[0] = 0;
    std::unordered_map<long long, size_t> map;
    map[0] = 0;
    for (size_t i = 1; i <= n; ++i) {
        prefix[i] = prefix[i - 1] + nums[i - 1];
        map[prefix[i]] = i;
    }
    long long totalSum = prefix[n];
    long long answer = LLONG_MAX;

    for (size_t s = 0; s < n; ++s) {
        long long startPref = prefix[s];
        long long sumToEnd = totalSum - startPref;

        if (target == sumToEnd) {
            answer = std::min(answer, static_cast<long long>(n - s));
            continue;
        }

        if (target < sumToEnd) {
            long long needed = target + startPref;
            auto it = map.find(needed);
            if (it != map.end() && it->second > s) {
                answer = std::min(answer, static_cast<long long>(it->second - s));
            }
            continue;
        }

        long long remaining = target - sumToEnd;
        long long cycles = totalSum != 0 ? remaining / totalSum : 0;
        long long leftover = remaining - cycles * totalSum;

        if (leftover == 0) {
            long long len = static_cast<long long>(n - s) + cycles * static_cast<long long>(n);
            answer = std::min(answer, len);
        } else {
            auto it = map.find(leftover);
            if (it != map.end()) {
                long long len = static_cast<long long>(n - s) + cycles * static_cast<long long>(n) + static_cast<long long>(it->second);
                answer = std::min(answer, len);
            }
        }
    }

    return answer == LLONG_MAX ? -1 : answer;
}

