std::vector<int> minimumEdgeReversals(int n, const std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (size_t i = 0; i < edges.size(); ++i) {
        int u = edges[i][0];
        int v = edges[i][1];
        adj[u].push_back({v, 0});
        adj[v].push_back({u, 1});
    }

    std::vector<int> answer(n);
    int rootReversals = 0;
    std::vector<std::pair<int, int>> stack;
    stack.push_back({0, -1});
    while (!stack.empty()) {
        auto node_parent = stack.back();
        stack.pop_back();
        int node = node_parent.first;
        int parent = node_parent.second;
        for (const auto& nei_cost : adj[node]) {
            int nei = nei_cost.first;
            int cost = nei_cost.second;
            if (nei == parent) continue;
            rootReversals += cost;
            stack.push_back({nei, node});
        }
    }
    answer[0] = rootReversals;

    std::vector<std::pair<int, int>> stack2;
    stack2.push_back({0, -1});
    while (!stack2.empty()) {
        auto node_parent = stack2.back();
        stack2.pop_back();
        int node = node_parent.first;
        int parent = node_parent.second;
        for (const auto& nei_cost : adj[node]) {
            int nei = nei_cost.first;
            int cost = nei_cost.second;
            if (nei == parent) continue;
            answer[nei] = answer[node] + (cost == 0 ? 1 : -1);
            stack2.push_back({nei, node});
        }
    }

    return answer;
}

