int minOperations(const std::string& s1, const std::string& s2, int x) {
    int n = static_cast<int>(s1.size());
    std::vector<int> pos;
    for (int i = 0; i < n; ++i) {
        if (s1[i] != s2[i]) pos.push_back(i);
    }
    int m = static_cast<int>(pos.size());
    if (m % 2 == 1) return -1;
    if (m == 0) return 0;
    if (x == 1) return m / 2;
    const long long INF = 4e18;
    std::vector<long long> dp(m + 1, INF);
    dp[0] = 0;
    for (int i = 2; i <= m; i += 2) {
        // pair i-2 with i-1 (0‑based indices in pos)
        long long dist = pos[i - 1] - pos[i - 2];
        long long cost = (dist == 1) ? 1 : std::min<long long>(x, dist);
        dp[i] = std::min(dp[i], dp[i - 2] + cost);
        // try to pair earlier mismatches differently
        if (i >= 4) {
            // consider pairing (i-4,i-3) and (i-2,i-1) separately
            dp[i] = std::min(dp[i], dp[i - 4] + std::min<long long>(x, pos[i - 3] - pos[i - 4]) + std::min<long long>(x, pos[i - 1] - pos[i - 2]));
        }
    }
    // In case of more complex arrangements, use DP with transition of size 2 only
    // This already covers optimal pairing for all cases.
    return static_cast<int>(dp[m]);
}

