std::vector<int> findLastVisitedIntegers(const std::vector<int>& nums) {
    std::vector<int> seen;
    std::vector<int> ans;
    int lastIdx = -1;
    for (int v : nums) {
        if (v == -1) {
            if (lastIdx >= 0) {
                ans.push_back(seen[lastIdx]);
                lastIdx--;
            } else {
                ans.push_back(-1);
            }
        } else {
            seen.push_back(v);
            lastIdx = static_cast<int>(seen.size()) - 1;
        }
    }
    return ans;
}

