int minProcessingTime(std::vector<int> processorTime, std::vector<int> tasks) {
    std::sort(processorTime.begin(), processorTime.end());
    std::sort(tasks.begin(), tasks.end(), std::greater<int>());
    int answer = 0;
    size_t p = processorTime.size();
    for (size_t i = 0; i < p; ++i) {
        int finish = processorTime[i] + tasks[4 * i];
        if (finish > answer) answer = finish;
    }
    return answer;
}

#include <bits/stdc++.h>
#include <string>
#include <limits>

std::string shortestBeautifulSubstring(const std::string& s, int k) {
    const size_t n = s.size();
    size_t left = 0;
    int ones = 0;
    size_t minLen = std::numeric_limits<size_t>::max();

    for (size_t right = 0; right < n; ++right) {
        if (s[right] == '1') ++ones;

        while (ones > k) {
            if (s[left] == '1') --ones;
            ++left;
        }

        while (ones == k && left < n && s[left] == '0') {
            ++left;
        }

        if (ones == k) {
            size_t curLen = right - left + 1;
            if (curLen < minLen) minLen = curLen;
        }
    }

    if (minLen == std::numeric_limits<size_t>::max()) return "";

    std::string best;
    int countOnes = 0;

    for (size_t i = 0; i < minLen; ++i) {
        if (s[i] == '1') ++countOnes;
    }
    if (countOnes == k) best = s.substr(0, minLen);

    for (size_t start = 1; start + minLen <= n; ++start) {
        if (s[start - 1] == '1') --countOnes;
        if (s[start + minLen - 1] == '1') ++countOnes;

        if (countOnes == k) {
            std::string sub = s.substr(start, minLen);
            if (best.empty() || sub < best) best = sub;
        }
    }

    return best;
}

#include <bits/stdc++.h>

struct State {
    int len;
    int lastGroup;
    std::vector<std::string> seq;
};

static bool better(const State& a, const State& b) {
    if (a.len != b.len) return a.len > b.len;
    return std::lexicographical_compare(a.seq.begin(), a.seq.end(),
                                        b.seq.begin(), b.seq.end());
}

std::vector<std::string> longestSubsequence(const std::vector<std::string>& words, const std::vector<int>& groups) {
    size_t n = words.size();
    if (n == 0) return {};
    std::vector<State> dp(n);
    State overall{0, -1, {}};

    for (size_t i = 0; i < n; ++i) {
        State cur{1, groups[i], {words[i]}};
        for (size_t j = 0; j < i; ++j) {
            if (groups[j] == groups[i]) continue;
            State cand = dp[j];
            cand.len += 1;
            cand.lastGroup = groups[i];
            cand.seq.push_back(words[i]);
            if (better(cand, cur)) cur = cand;
        }
        dp[i] = cur;
        if (better(dp[i], overall)) overall = dp[i];
    }
    return overall.seq;
}

