std::vector<int> findIndices(const std::vector<int>& nums, int indexDifference, int valueDifference) {
    int n = static_cast<int>(nums.size());
    if (indexDifference <= 0 && valueDifference <= 0) {
        return {0, 0};
    }
    long long maxVal = LLONG_MIN;
    int maxIdx = -1;
    long long minVal = LLONG_MAX;
    int minIdx = -1;
    for (int j = 0; j < n; ++j) {
        int i = j - indexDifference;
        if (i >= 0) {
            long long v = nums[i];
            if (v > maxVal) { maxVal = v; maxIdx = i; }
            if (v < minVal) { minVal = v; minIdx = i; }
        }
        if (maxIdx != -1 && maxVal - nums[j] >= valueDifference) {
            return {maxIdx, j};
        }
        if (minIdx != -1 && static_cast<long long>(nums[j]) - minVal >= valueDifference) {
            return {minIdx, j};
        }
    }
    return {-1, -1};
}

