std::vector<std::string> longestAlternatingSubsequence(const std::vector<std::string>& words, const std::vector<int>& groups) {
    std::vector<std::string> result;
    int prevGroup = -1; // no previous group
    for (size_t i = 0; i < words.size(); ++i) {
        if (groups[i] != prevGroup) {
            result.push_back(words[i]);
            prevGroup = groups[i];
        }
    }
    return result;
}

#include <bits/stdc++.h>

int minimumSum(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n < 3) return -1;
    const int INF = 1e9;
    std::vector<int> leftMin(n, INF), rightMin(n, INF);
    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < j; ++i) {
            if (nums[i] < nums[j]) {
                leftMin[j] = std::min(leftMin[j], nums[i]);
            }
        }
    }
    for (int j = n - 1; j >= 0; --j) {
        for (int k = j + 1; k < n; ++k) {
            if (nums[k] < nums[j]) {
                rightMin[j] = std::min(rightMin[j], nums[k]);
            }
        }
    }
    int ans = INF;
    for (int j = 0; j < n; ++j) {
        if (leftMin[j] != INF && rightMin[j] != INF) {
            ans = std::min(ans, leftMin[j] + nums[j] + rightMin[j]);
        }
    }
    return ans == INF ? -1 : ans;
}

