int minChanges(const std::string& s, int k) {
    int n = static_cast<int>(s.size());
    if (k >= n) return 0;

    std::vector<std::vector<int>> cost(n, std::vector<int>(n, 0));
    for (int len = 2; len <= n; ++len) {
        for (int i = 0; i + len <= n; ++i) {
            int j = i + len - 1;
            if (s[i] == s[j]) {
                cost[i][j] = (len == 2) ? 0 : cost[i + 1][j - 1];
            } else {
                cost[i][j] = (len == 2) ? 1 : cost[i + 1][j - 1] + 1;
            }
        }
    }

    const int INF = 1000000000;
    std::vector<std::vector<int>> dp(k + 1, std::vector<int>(n + 1, INF));
    dp[0][0] = 0;

    for (int p = 1; p <= k; ++p) {
        for (int i = 1; i <= n; ++i) {
            for (int t = p - 1; t < i; ++t) {
                int prev = dp[p - 1][t];
                if (prev == INF) continue;
                int cur = prev + cost[t][i - 1];
                if (cur < dp[p][i]) dp[p][i] = cur;
            }
        }
    }
    return dp[k][n];
}

