long long subarraysDistinctElementSumOfSquaresI(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        std::unordered_map<int, int> freq;
        int distinct = 0;
        for (int j = i; j < n; ++j) {
            int v = nums[j];
            auto it = freq.find(v);
            if (it == freq.end()) {
                freq[v] = 1;
                ++distinct;
            } else {
                ++(it->second);
            }
            ans += 1LL * distinct * distinct;
        }
    }
    return ans;
}

