long long sumDistinctSquares(const std::vector<int>& nums) {
    const int64_t MOD = 1000000007LL;
    int n = static_cast<int>(nums.size());
    int64_t total = 0;
    for (int i = 0; i < n; ++i) {
        std::unordered_set<int> seen;
        for (int j = i; j < n; ++j) {
            seen.insert(nums[j]);
            int64_t k = static_cast<int64_t>(seen.size());
            total = (total + k * k) % MOD;
        }
    }
    return total;
}

