int maxPairs(const std::vector<std::string>& words) {
    std::unordered_map<std::string, int> wordCount;
    for (const auto& word : words) {
        wordCount[word] = (wordCount[word] ? wordCount[word] : 0) + 1;
    }
    int pairs = 0;
    for (const auto& word : words) {
        std::string reversedWord(word.rbegin(), word.rend());
        auto it = wordCount.find(reversedWord);
        if (it != wordCount.end() && it->second > 0 && word != reversedWord) {
            wordCount[reversedWord]--;
            wordCount[word]--;
            pairs++;
        }
    }
    return pairs;
}

#include <bits/stdc++.h>

int longestString(int x, int y, int z) {
    const int MAXX = x, MAXY = y, MAXZ = z;
    // dp[a][b][c][last][run] = max length using a AA, b BB, c AB pieces,
    // last: 0 = A, 1 = B, 2 = none (start), run: consecutive count of last (0..2)
    static int dp[51][51][51][3][3];
    for (int a = 0; a <= MAXX; ++a)
        for (int b = 0; b <= MAXY; ++b)
            for (int c = 0; c <= MAXZ; ++c)
                for (int l = 0; l < 3; ++l)
                    for (int r = 0; r < 3; ++r)
                        dp[a][b][c][l][r] = -1;
    dp[0][0][0][2][0] = 0; // start state

    int answer = 0;
    for (int a = 0; a <= MAXX; ++a) {
        for (int b = 0; b <= MAXY; ++b) {
            for (int c = 0; c <= MAXZ; ++c) {
                for (int last = 0; last < 3; ++last) {
                    for (int run = 0; run < 3; ++run) {
                        int curLen = dp[a][b][c][last][run];
                        if (curLen < 0) continue;
                        answer = std::max(answer, curLen);
                        // Try to add an "AA" piece
                        if (a < MAXX) {
                            int nl = last, nr = run;
                            bool ok = true;
                            // first 'A'
                            if (nl == 0) nr++; else { nl = 0; nr = 1; }
                            if (nr >= 3) ok = false;
                            // second 'A'
                            if (ok) {
                                if (nl == 0) nr++; else { nl = 0; nr = 1; }
                                if (nr >= 3) ok = false;
                            }
                            if (ok) {
                                dp[a+1][b][c][nl][nr] = std::max(dp[a+1][b][c][nl][nr], curLen + 2);
                            }
                        }
                        // Try to add a "BB" piece
                        if (b < MAXY) {
                            int nl = last, nr = run;
                            bool ok = true;
                            // first 'B'
                            if (nl == 1) nr++; else { nl = 1; nr = 1; }
                            if (nr >= 3) ok = false;
                            // second 'B'
                            if (ok) {
                                if (nl == 1) nr++; else { nl = 1; nr = 1; }
                                if (nr >= 3) ok = false;
                            }
                            if (ok) {
                                dp[a][b+1][c][nl][nr] = std::max(dp[a][b+1][c][nl][nr], curLen + 2);
                            }
                        }
                        // Try to add an "AB" piece
                        if (c < MAXZ) {
                            int nl = last, nr = run;
                            bool ok = true;
                            // first 'A'
                            if (nl == 0) nr++; else { nl = 0; nr = 1; }
                            if (nr >= 3) ok = false;
                            // second 'B'
                            if (ok) {
                                if (nl == 1) nr++; else { nl = 1; nr = 1; }
                                if (nr >= 3) ok = false;
                            }
                            if (ok) {
                                dp[a][b][c+1][nl][nr] = std::max(dp[a][b][c+1][nl][nr], curLen + 2);
                            }
                        }
                    }
                }
            }
        }
    }
    return answer;
}

