struct Record {
    int time;
    int returned;
};

std::vector<Record> cancellable(const std::function<int(const std::vector<int>&)>& fn,
                                const std::vector<int>& args,
                                int t,
                                int cancelTimeMs) {
    std::vector<Record> result;
    for (int cur = 0; cur < cancelTimeMs; cur += t) {
        int ret = fn(args);
        result.push_back({cur, ret});
    }
    return result;
}

