struct Obj {
    int id;
    std::unordered_map<std::string, std::string> props;
};

std::vector<Obj> joinTwoArraysByid(const std::vector<Obj>& arr1, const std::vector<Obj>& arr2) {
    std::unordered_map<int, Obj> map;
    for (const Obj& obj : arr1) {
        map.emplace(obj.id, obj);
    }
    for (const Obj& obj : arr2) {
        auto it = map.find(obj.id);
        if (it != map.end()) {
            Obj& existingObj = it->second;
            for (const auto& kv : obj.props) {
                existingObj.props[kv.first] = kv.second;
            }
        } else {
            map.emplace(obj.id, obj);
        }
    }
    std::vector<Obj> result;
    result.reserve(map.size());
    for (auto& kv : map) {
        result.push_back(std::move(kv.second));
    }
    std::sort(result.begin(), result.end(), [](const Obj& a, const Obj& b) {
        return a.id < b.id;
    });
    return result;
}

#include <bits/stdc++.h>

int waysToSplit(const std::vector<int>& nums) {
    const int MOD = 1000000007;
    long long result = 1;
    int previousOne = -1;
    int totalOnes = 0;
    for (int i = 0; i < static_cast<int>(nums.size()); ++i) {
        if (nums[i] == 1) {
            ++totalOnes;
            if (previousOne != -1) {
                result = (result * (i - previousOne)) % MOD;
            }
            previousOne = i;
        }
    }
    if (totalOnes == 0) {
        return 0;
    }
    return static_cast<int>(result);
}

