std::vector<int> countZeroRequestServers(int n, const std::vector<std::vector<int>>& logs, int x, const std::vector<int>& queries) {
    std::vector<int> result(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        int startTime = queries[i] - x;
        std::unordered_set<int> serverRequests;
        for (const auto& log : logs) {
            if (log[1] >= startTime && log[1] <= queries[i]) {
                serverRequests.insert(log[0]);
            }
        }
        result[i] = n - static_cast<int>(serverRequests.size());
    }
    return result;
}

#include <bits/stdc++.h>
#include <vector>

std::vector<int> findGoodSubset(const std::vector<std::vector<int>>& grid) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    std::vector<int> result;
    for (int mask = 1; mask < (1 << m); ++mask) {
        std::vector<int> subset;
        int subsetSize = 0;
        for (int i = 0; i < m; ++i) {
            if ((mask & (1 << i)) != 0) {
                subset.push_back(i);
                ++subsetSize;
            }
        }
        bool isGood = true;
        for (int j = 0; j < n; ++j) {
            int sum = 0;
            for (size_t i = 0; i < subset.size(); ++i) {
                sum += grid[subset[i]][j];
            }
            if (sum > subsetSize / 2) {
                isGood = false;
                break;
            }
        }
        if (isGood && (result.empty() || subsetSize > static_cast<int>(result.size()))) {
            result = subset;
        }
    }
    return result;
}

