static int firstDigit(int x) {
    while (x >= 10) {
        x /= 10;
    }
    return x;
}

static int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long countBeautifulPairs(const std::vector<int>& nums) {
    long long result = 0;
    long long freq[10] = {};
    for (int num : nums) {
        int last = num % 10;
        for (int d = 1; d <= 9; ++d) {
            if (freq[d] && gcd_int(d, last) == 1) {
                result += freq[d];
            }
        }
        int first = firstDigit(num);
        ++freq[first];
    }
    return result;
}

#include <bits/stdc++.h>

struct Robot {
    int position;
    int health;
    bool direction; // true for 'R', false for 'L'
};

std::vector<int> robotCollisions(const std::vector<int>& positions, const std::vector<int>& healths, const std::string& directions) {
    int n = static_cast<int>(positions.size());
    std::vector<Robot> robots;
    robots.reserve(n);
    for (int i = 0; i < n; ++i) {
        robots.emplace_back(Robot{positions[i], healths[i], directions[i] == 'R'});
    }
    std::sort(robots.begin(), robots.end(), [](const Robot& a, const Robot& b) {
        return a.position < b.position;
    });
    std::vector<Robot> stack;
    stack.reserve(n);
    for (int i = 0; i < n; ++i) {
        if (stack.empty() || robots[i].direction) {
            stack.push_back(robots[i]);
        } else {
            bool currentAlive = true;
            // FIX 1: collide while the stack top is moving RIGHT (toward us), not left.
            while (!stack.empty() && stack.back().direction && currentAlive) {
                Robot topRobot = stack.back();
                stack.pop_back();
                if (robots[i].health > topRobot.health) {
                    robots[i].health -= 1;
                } else if (robots[i].health < topRobot.health) {
                    robots[i] = topRobot;
                    robots[i].health -= 1; // FIX 2: surviving top still pays the 1-health collision cost
                } else {
                    currentAlive = false;
                }
            }
            if (currentAlive) {
                stack.push_back(robots[i]);
            }
        }
    }
    std::unordered_map<int, int> healthMap;
    healthMap.reserve(stack.size());
    for (const auto& r : stack) {
        healthMap[r.position] = r.health;
    }
    std::vector<int> result;
    result.reserve(n);
    for (int i = 0; i < n; ++i) {
        auto it = healthMap.find(positions[i]);
        if (it != healthMap.end()) {
            result.push_back(it->second);
        }
        // FIX 3: destroyed robots are omitted entirely, not zero-padded.
    }
    return result;
}

#include <bits/stdc++.h>

long long makeTheIntegerZero(long long num1, long long num2) {
    if (num1 == 0) return 0;
    for (int k = 1; k <= 60; ++k) {
        long long S = num1 - (long long)k * num2;
        if (S < 0) continue;
        int bits = __builtin_popcountll((unsigned long long)S);
        if (bits <= k && k <= S) {
            return k;
        }
    }
    return -1;
}

#include <bits/stdc++.h>
#include <vector>
#include <unordered_map>

int longestSubsequenceSum(const std::vector<int>& nums, int target) {
    std::unordered_map<int, int> dp;
    for (int num : nums) {
        std::unordered_map<int, int> newDp(dp);
        if (!newDp.count(num) || newDp[num] < 1) {
            newDp[num] = 1;
        }
        for (const auto& entry : dp) {
            int sum = entry.first;
            int len = entry.second;
            int newSum = sum + num;
            int newLen = len + 1;
            if (!newDp.count(newSum) || newDp[newSum] < newLen) {
                newDp[newSum] = newLen;
            }
        }
        dp = std::move(newDp);
    }
    return dp.count(target) ? dp[target] : -1;
}

#include <bits/stdc++.h>
#include <vector>

int findKOr(const std::vector<int>& nums, int k) {
    int result = 0;
    for (int bit = 0; bit < 32; ++bit) {
        int count = 0;
        for (size_t i = 0; i < nums.size(); ++i) {
            if ((nums[i] >> bit) & 1) {
                ++count;
                if (count >= k) break;
            }
        }
        if (count >= k) {
            result |= (1 << bit);
        }
    }
    return result;
}

#include <bits/stdc++.h>
int countSubMultisets(std::vector<int> nums, int l, int r) {
    const int MOD = 1000000007;
    std::unordered_map<int, int> freq;
    int totalSum = 0;
    for (int v : nums) {
        ++freq[v];
        totalSum += v;
    }
    std::vector<int> dp(totalSum + 1, 0);
    dp[0] = 1;
    for (auto &p : freq) {
        int val = p.first;
        int cnt = p.second;
        if (val == 0) {
            long long mult = cnt + 1LL;
            for (int s = 0; s <= totalSum; ++s) {
                dp[s] = (int)((dp[s] * mult) % MOD);
            }
            continue;
        }
        std::vector<int> ndp(totalSum + 1, 0);
        for (int rem = 0; rem < val; ++rem) {
            long long windowSum = 0;
            int k = 0;
            for (int s = rem; s <= totalSum; s += val, ++k) {
                windowSum += dp[s];
                if (windowSum >= MOD) windowSum -= MOD;
                if (k > cnt) {
                    int idx = s - (cnt + 1) * val;
                    windowSum -= dp[idx];
                    if (windowSum < 0) windowSum += MOD;
                }
                ndp[s] = (int)windowSum;
            }
        }
        dp.swap(ndp);
    }
    long long ans = 0;
    for (int s = l; s <= r && s <= totalSum; ++s) {
        ans += dp[s];
        if (ans >= MOD) ans -= MOD;
    }
    return (int)ans;
}

