int minimumSum(const std::vector<int>& nums) {
    int n = nums.size();
    if (n < 3) return -1;
    std::vector<int> prefixMin(n);
    prefixMin[0] = nums[0];
    for (int i = 1; i < n; ++i) {
        prefixMin[i] = std::min(prefixMin[i - 1], nums[i]);
    }
    std::vector<int> suffixMin(n);
    suffixMin[n - 1] = nums[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        suffixMin[i] = std::min(suffixMin[i + 1], nums[i]);
    }
    long long best = LLONG_MAX;
    for (int j = 1; j <= n - 2; ++j) {
        int left = prefixMin[j - 1];
        int right = suffixMin[j + 1];
        if (left < nums[j] && right < nums[j]) {
            long long sum = (long long)left + nums[j] + right;
            if (sum < best) best = sum;
        }
    }
    return best == LLONG_MAX ? -1 : static_cast<int>(best);
}

