long long minimumSum(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    long long sum1 = 0, sum2 = 0;
    long long zeros1 = 0, zeros2 = 0;
    for (int v : nums1) {
        if (v == 0) ++zeros1;
        else sum1 += v;
    }
    for (int v : nums2) {
        if (v == 0) ++zeros2;
        else sum2 += v;
    }
    if (zeros1 == 0 && zeros2 == 0) {
        return (sum1 == sum2) ? sum1 : -1;
    }
    if (zeros1 == 0) {
        if (sum1 >= sum2 && sum1 - sum2 >= zeros2) return sum1;
        return -1;
    }
    if (zeros2 == 0) {
        if (sum2 >= sum1 && sum2 - sum1 >= zeros1) return sum2;
        return -1;
    }
    long long candidate = std::max(sum1 + zeros1, sum2 + zeros2);
    return candidate;
}

