long long maximumScoreAfterOperations(const std::vector<std::vector<int>>& edges, const std::vector<int>& values) {
    int n = values.size();
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int a = e[0], b = e[1];
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    const long long INF = (long long)4e18;
    std::vector<long long> dp_keep(n), dp_take(n);
    std::function<void(int,int)> dfs = [&](int u, int parent) {
        bool isLeaf = true;
        long long sumTake = 0;
        for (int v : adj[u]) {
            if (v == parent) continue;
            isLeaf = false;
            dfs(v, u);
            sumTake += std::min(dp_keep[v], dp_take[v]);
        }
        if (isLeaf) {
            dp_keep[u] = values[u];
            dp_take[u] = INF; // cannot take leaf without keeping any node below
        } else {
            dp_keep[u] = values[u];
            dp_take[u] = sumTake;
        }
    };
    dfs(0, -1);
    long long minKeep = std::min(dp_keep[0], dp_take[0]);
    long long total = 0;
    for (int v : values) total += v;
    return total - minKeep;
}

