long long maxPoints(const std::vector<std::vector<int>>& edges,
                    const std::vector<int>& coins,
                    int k) {
    int n = static_cast<int>(coins.size());
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    long long sum = 0;
    for (int c : coins) sum += c;
    std::vector<int> dist(n, -1);
    std::queue<int> q;
    dist[0] = 0;
    q.push(0);
    int maxDepth = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                maxDepth = std::max(maxDepth, dist[v]);
                q.push(v);
            }
        }
    }
    long long traversals = 2LL * (n - 1) - maxDepth;
    return sum - traversals * static_cast<long long>(k);
}

