int maximumBalancedSubsequenceSum(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::vector<int> comp = nums;
    std::sort(comp.begin(), comp.end());
    comp.erase(std::unique(comp.begin(), comp.end()), comp.end());
    int m = static_cast<int>(comp.size());
    std::vector<long long> bit(m + 1, LLONG_MIN);
    auto bitUpdate = [&](int idx, long long val) {
        for (++idx; idx <= m; idx += idx & -idx) {
            bit[idx] = std::max(bit[idx], val);
        }
    };
    auto bitQuery = [&](int idx) {
        long long res = LLONG_MIN;
        for (++idx; idx > 0; idx -= idx & -idx) {
            res = std::max(res, bit[idx]);
        }
        return res;
    };
    long long answer = LLONG_MIN;
    for (int x : nums) {
        int pos = static_cast<int>(std::lower_bound(comp.begin(), comp.end(), x) - comp.begin());
        long long bestPrev = bitQuery(pos - 1);
        long long cur = static_cast<long long>(x);
        if (bestPrev != LLONG_MIN) {
            cur = std::max(cur, bestPrev + x);
        }
        answer = std::max(answer, cur);
        bitUpdate(pos, cur);
    }
    return static_cast<int>(answer);
}

