static const long long MOD = 1000000007LL;

static long long modPow(long long base, long long exp) {
    long long res = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int stringCount(int n) {
    if (n < 4) return 0;
    long long pow26 = modPow(26, n);
    long long pow25 = modPow(25, n);
    long long pow24 = modPow(24, n);
    long long pow23 = modPow(23, n);

    long long pow25_n1 = modPow(25, n - 1);
    long long pow24_n1 = modPow(24, n - 1);
    long long pow23_n1 = modPow(23, n - 1);

    long long nn = n % MOD;

    long long termA = pow25;                           // no 'l'
    long long termC = pow25;                           // no 't'
    long long termB = (pow25 + nn * pow25_n1) % MOD;   // at most one 'e'

    long long termAC = pow24;                          // no 'l' and no 't'
    long long termAB = (pow24 + nn * pow24_n1) % MOD;  // no 'l' and at most one 'e'
    long long termBC = termAB;                         // no 't' and at most one 'e'

    long long termABC = (pow23 + nn * pow23_n1) % MOD; // no 'l', no 't', at most one 'e'

    long long bad = (termA + termB + termC) % MOD;
    bad = (bad - termAB - termAC - termBC) % MOD;
    bad = (bad + termABC) % MOD;
    if (bad < 0) bad += MOD;

    long long ans = (pow26 - bad) % MOD;
    if (ans < 0) ans += MOD;
    return static_cast<int>(ans);
}

