long long maximumSpending(const std::vector<std::vector<long long>>& values) {
    size_t m = values.size();
    size_t n = values[0].size();
    long long totalSpending = 0;
    long long day = static_cast<long long>(m * n);
    struct Node {
        long long value;
        size_t shop;
        size_t idx;
        bool operator<(const Node& other) const { return value < other.value; }
    };
    std::priority_queue<Node> pq;
    for (size_t i = 0; i < m; ++i) {
        pq.push({values[i][0], i, 0});
    }
    while (!pq.empty()) {
        Node cur = pq.top();
        pq.pop();
        totalSpending += cur.value * day;
        --day;
        if (cur.idx + 1 < n) {
            pq.push({values[cur.shop][cur.idx + 1], cur.shop, cur.idx + 1});
        }
    }
    return totalSpending;
}

