int minOperationsToMakeIncreasing(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    int n = nums1.size();
    auto tryCase = [&](int end1, int end2) -> int {
        int ops = 0;
        for (int i = 0; i < n - 1; i++) {
            int a = nums1[i], b = nums2[i];
            bool noSwapOk = a <= end1 && b <= end2;
            bool swapOk = b <= end1 && a <= end2;
            if (noSwapOk) continue;
            else if (swapOk) ops++;
            else return -1;
        }
        return ops;
    };
    int n1 = nums1[n-1], n2 = nums2[n-1];
    int case1 = tryCase(n1, n2);
    int case2 = tryCase(n2, n1);
    int best = INT_MAX;
    if (case1 != -1) best = min(best, case1);
    if (case2 != -1) best = min(best, case2 + 1);
    return best == INT_MAX ? -1 : best;
}

