struct TrieNode {
    TrieNode* children[2];
    int cnt;
    TrieNode() : children{nullptr, nullptr}, cnt(0) {}
};

int maximumStrongPairXor(std::vector<int> nums) {
    std::sort(nums.begin(), nums.end());
    const int MAX_BIT = 20;
    TrieNode* root = new TrieNode();

    auto insert = [&](int val) {
        TrieNode* node = root;
        node->cnt++;
        for (int i = MAX_BIT; i >= 0; --i) {
            int bit = (val >> i) & 1;
            if (!node->children[bit]) {
                node->children[bit] = new TrieNode();
            }
            node = node->children[bit];
            node->cnt++;
        }
    };

    auto remove = [&](int val) {
        TrieNode* node = root;
        node->cnt--;
        for (int i = MAX_BIT; i >= 0; --i) {
            int bit = (val >> i) & 1;
            node = node->children[bit];
            node->cnt--;
        }
    };

    auto query = [&](int val) {
        TrieNode* node = root;
        int xorVal = 0;
        for (int i = MAX_BIT; i >= 0; --i) {
            int bit = (val >> i) & 1;
            int toggled = bit ^ 1;
            if (node->children[toggled] && node->children[toggled]->cnt > 0) {
                xorVal |= (1 << i);
                node = node->children[toggled];
            } else {
                node = node->children[bit];
            }
        }
        return xorVal;
    };

    int ans = 0;
    std::size_t left = 0;
    for (std::size_t right = 0; right < nums.size(); ++right) {
        while (static_cast<long long>(nums[right]) > 2LL * nums[left]) {
            remove(nums[left]);
            ++left;
        }
        insert(nums[right]);
        int cur = query(nums[right]);
        if (cur > ans) ans = cur;
    }
    return ans;
}

