int maxAreaOfSquareHole(int n, int m, const std::vector<int>& hBars, const std::vector<int>& vBars) {
    std::vector<int> rows = hBars;
    rows.push_back(0);
    rows.push_back(n + 1);
    std::sort(rows.begin(), rows.end());
    int maxRowGap = 0;
    for (size_t i = 1; i < rows.size(); ++i) {
        int gap = rows[i] - rows[i - 1];
        if (gap > maxRowGap) maxRowGap = gap;
    }

    std::vector<int> cols = vBars;
    cols.push_back(0);
    cols.push_back(m + 1);
    std::sort(cols.begin(), cols.end());
    int maxColGap = 0;
    for (size_t i = 1; i < cols.size(); ++i) {
        int gap = cols[i] - cols[i - 1];
        if (gap > maxColGap) maxColGap = gap;
    }

    int side = std::min(maxRowGap, maxColGap);
    return side * side;
}

