std::vector<int> findMeetingBuilding(const std::vector<int>& heights, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(heights.size());
    std::vector<int> seg(4 * n);
    std::function<void(int,int,int)> build = [&](int node, int l, int r) {
        if (l == r) {
            seg[node] = heights[l];
            return;
        }
        int mid = (l + r) / 2;
        build(node * 2, l, mid);
        build(node * 2 + 1, mid + 1, r);
        seg[node] = std::max(seg[node * 2], seg[node * 2 + 1]);
    };
    build(1, 0, n - 1);
    std::function<int(int,int,int,int,int)> findFirst = [&](int node, int l, int r, int ql, int target) -> int {
        if (r < ql || seg[node] < target) return -1;
        if (l == r) return l;
        int mid = (l + r) / 2;
        int leftRes = findFirst(node * 2, l, mid, ql, target);
        if (leftRes != -1) return leftRes;
        return findFirst(node * 2 + 1, mid + 1, r, ql, target);
    };
    std::vector<int> result;
    result.reserve(queries.size());
    for (const auto& q : queries) {
        int a = q[0];
        int b = q[1];
        int start = std::max(a, b);
        int targetHeight = std::max(heights[a], heights[b]);
        int idx = findFirst(1, 0, n - 1, start, targetHeight);
        result.push_back(idx);
    }
    return result;
}

#include <bits/stdc++.h>

int findMaximumLength(const std::vector<int>& nums) {
    long long prevSum = 0;          // sum of the last formed block
    long long curSum = 0;           // sum of the current building block
    int groups = 0;                 // number of blocks formed

    for (int x : nums) {
        curSum += x;
        if (curSum >= prevSum) {
            ++groups;
            prevSum = curSum;
            curSum = 0;
        }
    }
    // Any remaining curSum (< prevSum) cannot form an additional non‑decreasing block,
    // so the answer is the number of groups already counted.
    return groups;
}

