bool isSimilarAfterCyclicShifts(std::vector<std::vector<int>>& mat, int k) {
    std::vector<std::vector<int>> originalMat = mat;
    for (int i = 0; i < k; ++i) {
        for (std::size_t j = 0; j < mat.size(); ++j) {
            if (j % 2 == 0) {
                if (!mat[j].empty()) {
                    std::rotate(mat[j].begin(), mat[j].begin() + 1, mat[j].end());
                }
            } else {
                if (!mat[j].empty()) {
                    std::rotate(mat[j].begin(), mat[j].end() - 1, mat[j].end());
                }
            }
        }
    }
    for (std::size_t i = 0; i < mat.size(); ++i) {
        for (std::size_t j = 0; j < mat[i].size(); ++j) {
            if (mat[i][j] != originalMat[i][j]) return false;
        }
    }
    return true;
}

