int makeThreeStringsEqual(const std::string& s1, const std::string& s2, const std::string& s3) {
    std::size_t minLen = std::min({s1.size(), s2.size(), s3.size()});
    std::size_t lcpLen = 0;
    while (lcpLen < minLen && s1[lcpLen] == s2[lcpLen] && s2[lcpLen] == s3[lcpLen]) {
        ++lcpLen;
    }
    if (lcpLen == 0) return -1;
    return static_cast<int>((s1.size() - lcpLen) + (s2.size() - lcpLen) + (s3.size() - lcpLen));
}

