int minOperations(const std::string& word) {
    const int INF = 1e9;
    if (word.empty()) return 0;
    std::vector<int> prev(26, INF), cur(26, INF);
    for (int c = 0; c < 26; ++c) {
        prev[c] = (c != (word[0] - 'a')) ? 1 : 0;
    }
    for (size_t i = 1; i < word.size(); ++i) {
        std::fill(cur.begin(), cur.end(), INF);
        for (int c = 0; c < 26; ++c) {
            int cost = (c != (word[i] - 'a')) ? 1 : 0;
            int best = INF;
            for (int p = 0; p < 26; ++p) {
                if (std::abs(c - p) > 1) {
                    best = std::min(best, prev[p]);
                }
            }
            cur[c] = best + cost;
        }
        prev.swap(cur);
    }
    return *std::min_element(prev.begin(), prev.end());
}

