static long long modPow(long long base, long long exp, long long mod) {
    long long result = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long numInfectionSequences(int n, const std::vector<int>& sick) {
    const long long MOD = 1000000007LL;
    int m = sick.size();
    std::vector<int> s = sick;
    std::sort(s.begin(), s.end());
    int remaining = n - m;
    std::vector<long long> fact(remaining + 1), invFact(remaining + 1);
    fact[0] = 1;
    for (int i = 1; i <= remaining; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[remaining] = modPow(fact[remaining], MOD - 2, MOD);
    for (int i = remaining; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;

    long long result = fact[remaining];
    // first segment
    int leftSize = s.empty() ? n : s[0];
    if (leftSize > 0) result = result * invFact[leftSize] % MOD;
    // middle segments
    for (int i = 0; i + 1 < m; ++i) {
        int seg = s[i + 1] - s[i] - 1;
        if (seg > 0) {
            result = result * invFact[seg] % MOD;
            result = result * modPow(2, seg - 1, MOD) % MOD;
        }
    }
    // last segment
    int rightSize = s.empty() ? 0 : (n - 1 - s.back());
    if (rightSize > 0) result = result * invFact[rightSize] % MOD;

    return result;
}

