int longestSubarray(const std::vector<int>& nums, int k) {
    int maxLength = 0;
    std::unordered_map<int, int> frequencyMap;
    int left = 0;
    for (int right = 0; right < static_cast<int>(nums.size()); ++right) {
        frequencyMap[nums[right]] = frequencyMap[nums[right]] + 1;
        while (true) {
            bool anyGreater = false;
            for (const auto& kv : frequencyMap) {
                if (kv.second > k) {
                    anyGreater = true;
                    break;
                }
            }
            if (!anyGreater) break;
            frequencyMap[nums[left]] -= 1;
            if (frequencyMap[nums[left]] == 0) {
                frequencyMap.erase(nums[left]);
            }
            ++left;
        }
        maxLength = std::max(maxLength, right - left + 1);
    }
    return maxLength;
}

