long long numberOfSubarrays(const std::vector<int>& nums, int k) {
    long long count = 0;
    int n = static_cast<int>(nums.size());
    for (int length = 1; length <= n; ++length) {
        for (int i = 0; i <= n - length; ++i) {
            std::vector<int> subarray(nums.begin() + i, nums.begin() + i + length);
            int maxElement = *std::max_element(subarray.begin(), subarray.end());
            int maxElementCount = 0;
            for (int x : subarray) {
                if (x == maxElement) {
                    ++maxElementCount;
                }
            }
            if (maxElementCount >= k) {
                ++count;
            }
        }
    }
    return count;
}

