int countGoodPartitions(const std::vector<int>& nums) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    std::unordered_map<int, int> lastPos;
    for (int i = 0; i < n; ++i) {
        lastPos[nums[i]] = i;
    }
    int blocks = 0;
    int curMax = -1;
    for (int i = 0; i < n; ++i) {
        curMax = std::max(curMax, lastPos[nums[i]]);
        if (i == curMax) {
            ++blocks;
        }
    }
    long long result = 1;
    for (int i = 0; i < blocks - 1; ++i) {
        result = (result * 2) % MOD;
    }
    return static_cast<int>(result);
}

#include <bits/stdc++.h>

long long numberOfSets(int n, int maxDistance, const std::vector<std::vector<int>>& roads) {
    const long long INF = 4e18;
    // store minimal edge weight between each pair
    std::vector<std::vector<long long>> base(n, std::vector<long long>(n, INF));
    for (int i = 0; i < n; ++i) base[i][i] = 0;
    for (const auto& r : roads) {
        int u = r[0], v = r[1];
        long long w = r[2];
        if (w < base[u][v]) {
            base[u][v] = base[v][u] = w;
        }
    }

    long long answer = 0;
    int totalMasks = 1 << n; // closed set mask
    for (int mask = 0; mask < totalMasks; ++mask) {
        // dist matrix for this subset
        std::vector<std::vector<long long>> dist = base;
        // deactivate closed vertices
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                for (int j = 0; j < n; ++j) {
                    dist[i][j] = INF;
                    dist[j][i] = INF;
                }
                dist[i][i] = INF; // not needed but keep consistency
            }
        }
        // Floyd-Warshall using only active vertices as intermediates
        for (int k = 0; k < n; ++k) {
            if (mask & (1 << k)) continue;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) continue;
                if (dist[i][k] == INF) continue;
                for (int j = 0; j < n; ++j) {
                    if (mask & (1 << j)) continue;
                    if (dist[k][j] == INF) continue;
                    long long nd = dist[i][k] + dist[k][j];
                    if (nd < dist[i][j]) dist[i][j] = nd;
                }
            }
        }
        // verify condition
        bool ok = true;
        for (int i = 0; i < n && ok; ++i) {
            if (mask & (1 << i)) continue;
            for (int j = i + 1; j < n; ++j) {
                if (mask & (1 << j)) continue;
                if (dist[i][j] > maxDistance) {
                    ok = false;
                    break;
                }
            }
        }
        if (ok) ++answer;
    }
    return answer;
}

