            }
            if (ok) {
                ++count;
            }
        }
    }
    return count;
}

#include <bits/stdc++.h>

long long minCostToMakeEqualindromic(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    std::vector<int> sorted = nums;
    std::sort(sorted.begin(), sorted.end());
    int n = static_cast<int>(sorted.size());
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + sorted[i];
    long long totalSum = pref[n];
    long long best = LLONG_MAX;

    auto evaluate = [&](long long p) {
        int idx = static_cast<int>(std::lower_bound(sorted.begin(), sorted.end(), static_cast<int>(p)) - sorted.begin());
        long long leftCnt = idx;
        long long leftSum = pref[idx];
        long long rightCnt = n - idx;
        long long rightSum = totalSum - leftSum;
        long long cost = p * leftCnt - leftSum + rightSum - p * rightCnt;
        if (cost < best) best = cost;
    };

    int maxVal = sorted.back();
    int maxDigits = static_cast<int>(std::to_string(maxVal).size());

    for (int len = 1; len <= maxDigits; ++len) {
        int half = (len + 1) / 2;
        int start = (len == 1) ? 0 : static_cast<int>(std::pow(10, half - 1));
        int end = static_cast<int>(std::pow(10, half));
        for (int prefix = start; prefix < end; ++prefix) {
            std::string s = std::to_string(prefix);
            std::string rev = s;
            if (len % 2 == 1) rev.pop_back();
            std::reverse(rev.begin(), rev.end());
            long long pal = std::stoll(s + rev);
            if (pal > maxVal) continue;
            evaluate(pal);
        }
    }
    return best;
}

#include <bits/stdc++.h>

int maxFrequencyScore(std::vector<int> nums, long long k) {
    std::sort(nums.begin(), nums.end());
    int n = nums.size();
    std::vector<long long> pref(n);
    for (int i = 0; i < n; ++i) {
        pref[i] = nums[i];
        if (i) pref[i] += pref[i - 1];
    }

    auto rangeSum = [&](int l, int r) -> long long {
        if (l > r) return 0LL;
        return pref[r] - (l ? pref[l - 1] : 0LL);
    };

    int best = 1;
    int l = 0;
    for (int r = 0; r < n; ++r) {
        while (l < r) {
            int len = r - l + 1;
            int mid = l + len / 2;
            long long median = nums[mid];

            long long leftCount = mid - l;
            long long leftSum = rangeSum(l, mid - 1);
            long long leftCost = median * leftCount - leftSum;

            long long rightCount = r - mid;
            long long rightSum = rangeSum(mid + 1, r);
            long long rightCost = rightSum - median * rightCount;

            long long cost = leftCost + rightCost;
            if (cost <= k) break;
            ++l;
        }
        best = std::max(best, r - l + 1);
    }
    return best;
}

