int largestPerimeter(std::vector<int> nums) {
    if (nums.size() < 3) {
        return -1;
    }
    std::sort(nums.begin(), nums.end(), std::greater<int>());
    long long total = 0;
    for (int v : nums) {
        total += v;
    }
    for (size_t i = 0; i < nums.size(); ++i) {
        long long longest = nums[i];
        long long rest = total - longest;
        if (longest < rest) {
            return static_cast<int>(total);
        }
        total = rest;
    }
    return -1;
}

