std::vector<long long> placedCoins(const std::vector<std::vector<int>>& edges, const std::vector<int>& cost) {
    int n = cost.size();
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<long long> answer(n, 1);
    std::function<std::vector<long long>(int,int)> dfs = [&](int u, int parent) -> std::vector<long long> {
        std::vector<long long> top;
        top.push_back(cost[u]);
        for (int v : adj[u]) {
            if (v == parent) continue;
            std::vector<long long> childTop = dfs(v, u);
            top.insert(top.end(), childTop.begin(), childTop.end());
        }
        std::sort(top.begin(), top.end(), std::greater<long long>());
        if (top.size() > 3) top.resize(3);
        if (top.size() < 3) {
            answer[u] = 1;
        } else {
            long long prod = top[0] * top[1] * top[2];
            answer[u] = (prod > 0) ? prod : 0;
        }
        return top;
    };
    dfs(0, -1);
    return answer;
}

