#include <bits/stdc++.h>

long long maxSquareArea(int m, int n, std::vector<int> hFences, std::vector<int> vFences) {
    const long long MOD = 1000000007LL;
    std::vector<long long> H;
    std::vector<long long> V;
    H.reserve(hFences.size() + 2);
    V.reserve(vFences.size() + 2);
    H.push_back(1);
    H.push_back(m);
    for (int x : hFences) H.push_back(x);
    V.push_back(1);
    V.push_back(n);
    for (int y : vFences) V.push_back(y);
    std::sort(H.begin(), H.end());
    std::sort(V.begin(), V.end());

    std::unordered_set<long long> diffH;
    diffH.reserve(H.size() * H.size());
    for (size_t i = 0; i < H.size(); ++i) {
        for (size_t j = i + 1; j < H.size(); ++j) {
            diffH.insert(H[j] - H[i]);
        }
    }

    long long best = 0;
    for (size_t i = 0; i < V.size(); ++i) {
        for (size_t j = i + 1; j < V.size(); ++j) {
            long long d = V[j] - V[i];
            if (diffH.find(d) != diffH.end()) {
                if (d > best) best = d;
            }
        }
    }

    if (best == 0) return -1;
    long long sideMod = best % MOD;
    return (sideMod * sideMod) % MOD;
}

#include <bits/stdc++.h>

static const long long INF = 4e18;

long long shortestPath(const std::string& start,
                       const std::string& goal,
                       const std::unordered_map<std::string, std::vector<std::pair<std::string, int>>>& adj) {
    if (start == goal) return 0;
    std::unordered_map<std::string, long long> dist;
    using Node = std::pair<long long, std::string>;
    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;
    dist[start] = 0;
    pq.emplace(0, start);
    while (!pq.empty()) {
        Node top = pq.top();
        pq.pop();
        long long d = top.first;
        const std::string& u = top.second;
        if (d != dist[u]) continue;
        if (u == goal) return d;
        auto it = adj.find(u);
        if (it == adj.end()) continue;
        for (const auto& e : it->second) {
            const std::string& v = e.first;
            long long nd = d + e.second;
            auto itDist = dist.find(v);
            if (itDist == dist.end() || nd < itDist->second) {
                dist[v] = nd;
                pq.emplace(nd, v);
            }
        }
    }
    return INF;
}

long long minimumCost(const std::string& source,
                      const std::string& target,
                      const std::vector<std::string>& original,
                      const std::vector<std::string>& changed,
                      const std::vector<int>& cost) {
    int n = static_cast<int>(source.size());
    std::unordered_map<std::string, std::vector<std::pair<std::string, int>>> adj;
    for (size_t i = 0; i < original.size(); ++i) {
        adj[original[i]].push_back({changed[i], cost[i]});
    }

    std::vector<long long> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 0; i < n; ++i) {
        if (dp[i] == INF) continue;
        for (int j = i + 1; j <= n; ++j) {
            int len = j - i;
            std::string s = source.substr(i, len);
            std::string t = target.substr(i, len);
            long long c = (s == t) ? 0 : shortestPath(s, t, adj);
            if (c == INF) continue;
            if (dp[i] + c < dp[j]) dp[j] = dp[i] + c;
        }
    }
    return dp[n] == INF ? -1 : dp[n];
}

#include <bits/stdc++.h>

long long minimumCost(const std::string& source,
                      const std::string& target,
                      const std::vector<char>& original,
                      const std::vector<char>& changed,
                      const std::vector<int>& cost) {
    const long long INF = 4e18;
    const int ALPH = 26;
    long long dist[ALPH][ALPH];
    for (int i = 0; i < ALPH; ++i) {
        for (int j = 0; j < ALPH; ++j) {
            dist[i][j] = (i == j) ? 0 : INF;
        }
    }
    for (size_t i = 0; i < original.size(); ++i) {
        int u = original[i] - 'a';
        int v = changed[i] - 'a';
        long long w = cost[i];
        if (w < dist[u][v]) dist[u][v] = w;
    }
    for (int k = 0; k < ALPH; ++k) {
        for (int i = 0; i < ALPH; ++i) {
            if (dist[i][k] == INF) continue;
            for (int j = 0; j < ALPH; ++j) {
                if (dist[k][j] == INF) continue;
                long long nd = dist[i][k] + dist[k][j];
                if (nd < dist[i][j]) dist[i][j] = nd;
            }
        }
    }
    long long total = 0;
    for (size_t i = 0; i < source.size(); ++i) {
        int s = source[i] - 'a';
        int t = target[i] - 'a';
        if (s == t) continue;
        if (dist[s][t] == INF) return -1;
        total += dist[s][t];
    }
    return total;
}

