int maximumLength(const std::string& s) {
    int n = static_cast<int>(s.size());
    int best = 0;
    for (char ch = 'a'; ch <= 'z'; ++ch) {
        std::vector<int> runs;
        int i = 0;
        while (i < n) {
            if (s[i] != ch) {
                ++i;
                continue;
            }
            int j = i;
            while (j < n && s[j] == ch) ++j;
            runs.push_back(j - i);
            i = j;
        }
        if (runs.empty()) continue;
        int maxRun = 0;
        for (int len : runs) if (len > maxRun) maxRun = len;
        int lo = 1, hi = maxRun, curBest = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            long long occ = 0;
            for (int len : runs) {
                if (len >= mid) occ += (len - mid + 1);
                if (occ >= 3) break;
            }
            if (occ >= 3) {
                curBest = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        if (curBest > best) best = curBest;
    }
    return best == 0 ? -1 : best;
}

