std::vector<bool> canMakePalindrome(const std::string& s, const std::vector<std::vector<int>>& queries) {
    std::vector<bool> result;
    int n = static_cast<int>(s.size());
    for (const auto& q : queries) {
        int a = q[0];
        int b = q[1];
        int c = q[2];
        int d = q[3];
        std::vector<char> mutablePos(n, 0);
        for (int i = a; i <= b; ++i) mutablePos[i] = 1;
        for (int i = c; i <= d; ++i) mutablePos[i] = 1;
        std::vector<int> cnt(26, 0);
        for (int i = 0; i < n; ++i) {
            if (mutablePos[i]) ++cnt[s[i] - 'a'];
        }
        bool ok = true;
        for (int i = 0; i < n / 2; ++i) {
            int j = n - 1 - i;
            bool mi = mutablePos[i];
            bool mj = mutablePos[j];
            if (!mi && !mj) {
                if (s[i] != s[j]) { ok = false; break; }
            } else if (mi && !mj) {
                int idx = s[j] - 'a';
                if (cnt[idx] == 0) { ok = false; break; }
                --cnt[idx];
            } else if (!mi && mj) {
                int idx = s[i] - 'a';
                if (cnt[idx] == 0) { ok = false; break; }
                --cnt[idx];
            }
        }
        if (ok) {
            if (n % 2 == 1) {
                int mid = n / 2;
                if (mutablePos[mid]) {
                    int odd = 0;
                    for (int v : cnt) if (v % 2) ++odd;
                    if (odd > 1) ok = false;
                } else {
                    for (int v : cnt) if (v % 2) { ok = false; break; }
                }
            } else {
                for (int v : cnt) if (v % 2) { ok = false; break; }
            }
        }
        result.push_back(ok);
    }
    return result;
}

