double maxAreaOfLongestDiagonalRectangle(const std::vector<std::vector<double>>& dimensions) {
    double maxDiagonal = 0.0;
    double maxArea = 0.0;
    for (size_t i = 0; i < dimensions.size(); ++i) {
        double length = dimensions[i][0];
        double width = dimensions[i][1];
        double diagonal = std::sqrt(length * length + width * width);
        if (diagonal > maxDiagonal) {
            maxDiagonal = diagonal;
            maxArea = length * width;
        } else if (diagonal == maxDiagonal) {
            maxArea = std::max(maxArea, length * width);
        }
    }
    return maxArea;
}

