unsigned long long accumulatedPrice(unsigned long long n, int x) {
    unsigned long long total = 0;
    for (int p = x - 1; p < 63; p += x) {
        unsigned long long period = 1ULL << (p + 1);
        unsigned long long fullCycles = (n + 1) / period;
        total += fullCycles * (1ULL << p);
        unsigned long long remainder = (n + 1) % period;
        if (remainder > (1ULL << p))
            total += remainder - (1ULL << p);
    }
    return total;
}

long long findMaximumNumber(long long k, int x) {
    unsigned long long low = 0, high = (1ULL << 62), ans = 0;
    while (low <= high) {
        unsigned long long mid = (low + high) >> 1;
        if (accumulatedPrice(mid, x) <= (unsigned long long)k) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return static_cast<long long>(ans);
}

