int minOrAfterOperations(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    int segments = n - k; // number of remaining elements after at most k merges
    int answer = 0;
    for (int bit = 0; bit < 30; ++bit) {
        int zeroCount = 0;
        for (int v : nums) {
            if (((v >> bit) & 1) == 0) ++zeroCount;
        }
        if (zeroCount < segments) {
            answer |= (1 << bit);
        }
    }
    return answer;
}

class Solution {
public:
    int maximumLength(vector<int>& nums) {
        unordered_map<long long,int> cnt;
        for (int x : nums) cnt[x]++;
        int ans = cnt.count(1) ? cnt[1] : 0;
        if (ans % 2 == 0) ans -= 1;
        ans = max(ans, 0);
        cnt.erase(1);
        const long long LIMIT = (long long)4e18; // overflow guard: repeated squaring can blow past int64 fast
        for (auto& [x0, c0] : unordered_map<long long,int>(cnt)) {
            long long x = x0;
            int t = 0;
            unordered_set<long long> visitedChain;
            bool overflowed = false;
            while (cnt.count(x) && cnt[x] > 1 && !visitedChain.count(x)) {
                visitedChain.insert(x);
                t += 2;
                if (x > LIMIT / x) { overflowed = true; break; }
                x = x * x;
            }
            if (!overflowed && cnt.count(x) && !visitedChain.count(x)) t += 1;
            else t -= 1;
            ans = max(ans, t);
        }
        return ans;
    }
};

