std::vector<std::vector<int>> findGridRegionAverage(const std::vector<std::vector<int>>& image, int threshold) {
    int m = static_cast<int>(image.size());
    int n = static_cast<int>(image[0].size());

    std::vector<std::vector<long long>> sum(m, std::vector<long long>(n, 0));
    std::vector<std::vector<int>> cnt(m, std::vector<int>(n, 0));

    for (int i = 0; i <= m - 3; ++i) {
        for (int j = 0; j <= n - 3; ++j) {
            bool ok = true;
            for (int r = 0; r < 3 && ok; ++r) {
                for (int c = 0; c < 3 && ok; ++c) {
                    int cur = image[i + r][j + c];
                    if (c < 2 && std::abs(cur - image[i + r][j + c + 1]) > threshold) ok = false;
                    if (r < 2 && std::abs(cur - image[i + r + 1][j + c]) > threshold) ok = false;
                }
            }
            if (!ok) continue;

            long long regionSum = 0;
            for (int r = 0; r < 3; ++r) {
                for (int c = 0; c < 3; ++c) {
                    regionSum += image[i + r][j + c];
                }
            }
            int regionAvg = static_cast<int>(regionSum / 9);

            for (int r = 0; r < 3; ++r) {
                for (int c = 0; c < 3; ++c) {
                    int x = i + r;
                    int y = j + c;
                    sum[x][y] += regionAvg;
                    cnt[x][y] += 1;
                }
            }
        }
    }

    std::vector<std::vector<int>> result(m, std::vector<int>(n));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            result[i][j] = (cnt[i][j] == 0) ? image[i][j] : static_cast<int>(sum[i][j] / cnt[i][j]);
        }
    }
    return result;
}

