    for (int i = 1; i <= nx; ++i) {
        int rowSum = 0;
        for (int j = 1; j <= ny; ++j) {
            rowSum += grid[i][j];
            ps[i][j] = ps[i - 1][j] + rowSum;
        }
    }
    int ans = 0;
    for (int a = 0; a < n; ++a) {
        int xa = points[a][0];
        int ya = points[a][1];
        int xiA = xIndex.at(xa);
        int yiA = yIndex.at(ya);
        for (int b = 0; b < n; ++b) {
            if (a == b) continue;
            int xb = points[b][0];
            int yb = points[b][1];
            int xiB = xIndex.at(xb);
            int yiB = yIndex.at(yb);
            if (xa <= xb && ya >= yb && (xa < xb || ya > yb)) {
                int x1 = xiA;
                int x2 = xiB;
                int y1 = yiA;
                int y2 = yiB;
                int cnt = ps[x2][y1] - ps[x1 - 1][y1] - ps[x2][y2 - 1] + ps[x1 - 1][y2 - 1];
                if (cnt == 2) ++ans;
            }
        }
    }
    return ans;
}

