int minimumTime(const std::string& word, int k) {
    int n = static_cast<int>(word.size());
    std::vector<std::uint32_t> pi(n);
    for (int i = 1; i < n; ++i) {
        int j = pi[i - 1];
        while (j > 0 && word[i] != word[j]) {
            j = pi[j - 1];
        }
        if (word[i] == word[j]) ++j;
        pi[i] = j;
    }
    std::vector<int> borders;
    borders.push_back(0);
    int len = pi[n - 1];
    while (len > 0) {
        borders.push_back(len);
        len = pi[len - 1];
    }
    int ans = (n + k - 1) / k;
    for (int L : borders) {
        int diff = n - L;
        if (diff > 0 && diff % k == 0) {
            int t = diff / k;
            if (t < ans) ans = t;
        }
    }
    return ans;
}

