int numberOfSubarrays(const std::vector<int>& nums, const std::vector<int>& pattern) {
    int n = static_cast<int>(nums.size());
    int m = static_cast<int>(pattern.size());

    if (m == 0) return n;
    if (m > n - 1) return 0;

    std::vector<int> diff(n - 1);
    for (int i = 0; i < n - 1; ++i) {
        int delta = nums[i + 1] - nums[i];
        diff[i] = (delta > 0) ? 1 : (delta < 0) ? -1 : 0;
    }

    std::vector<int> lps(m, 0);
    for (int i = 1, len = 0; i < m; ) {
        if (pattern[i] == pattern[len]) {
            lps[i++] = ++len;
        } else if (len) {
            len = lps[len - 1];
        } else {
            lps[i++] = 0;
        }
    }

    int count = 0;
    for (int i = 0, j = 0; i < static_cast<int>(diff.size()); ) {
        if (diff[i] == pattern[j]) {
            ++i;
            ++j;
            if (j == m) {
                ++count;
                j = lps[j - 1];
            }
        } else if (j) {
            j = lps[j - 1];
        } else {
            ++i;
        }
    }
    return count;
}

#include <bits/stdc++.h>
int maxPalindromes(std::vector<std::string> &words) {
    int charCount[26] = {0};
    int totalChars = 0;
    for (const std::string &w : words) {
        for (char c : w) {
            ++charCount[c - 'a'];
            ++totalChars;
        }
    }
    int totalPairs = 0;
    for (int i = 0; i < 26; ++i) totalPairs += charCount[i] / 2;

    std::vector<int> needPairs;
    std::vector<int> parity;
    needPairs.reserve(words.size());
    parity.reserve(words.size());
    for (const std::string &w : words) {
        int len = static_cast<int>(w.size());
        needPairs.push_back(len / 2);
        parity.push_back(len % 2);
    }

    const int INF_NEG = -1000000;
    std::vector<int> dpCnt(totalPairs + 1, INF_NEG);
    std::vector<int> dpOdd(totalPairs + 1, INT_MAX);
    dpCnt[0] = 0;
    dpOdd[0] = 0;

    for (size_t idx = 0; idx < needPairs.size(); ++idx) {
        int a = needPairs[idx];
        int b = parity[idx];
        for (int p = totalPairs - a; p >= 0; --p) {
            if (dpCnt[p] == INF_NEG) continue;
            int np = p + a;
            int newCnt = dpCnt[p] + 1;
            int newOdd = dpOdd[p] + b;
            if (newCnt > dpCnt[np] || (newCnt == dpCnt[np] && newOdd < dpOdd[np])) {
                dpCnt[np] = newCnt;
                dpOdd[np] = newOdd;
            }
        }
    }

    int answer = 0;
    for (int p = 0; p <= totalPairs; ++p) {
        if (dpCnt[p] == INF_NEG) continue;
        int oddCnt = dpOdd[p];
        if (oddCnt <= totalChars - 2 * p) {
            answer = std::max(answer, dpCnt[p]);
        }
    }
    return answer;
}

