int countMatchingSubarrays(std::vector<int>& nums, std::vector<int>& pattern) {
    int n = static_cast<int>(nums.size());
    int m = static_cast<int>(pattern.size());
    if (n < 2 || m == 0 || n - 1 < m) return 0;

    std::vector<int> diff(n - 1);
    for (int i = 0; i < n - 1; ++i) {
        long long d = static_cast<long long>(nums[i + 1]) - static_cast<long long>(nums[i]);
        diff[i] = (d > 0) ? 1 : (d == 0 ? 0 : -1);
    }

    std::vector<int> lps(m, 0);
    for (int i = 1; i < m; ++i) {
        int len = lps[i - 1];
        while (len > 0 && pattern[i] != pattern[len]) {
            len = lps[len - 1];
        }
        if (pattern[i] == pattern[len]) ++len;
        lps[i] = len;
    }

    int count = 0;
    int j = 0;
    for (int i = 0; i < n - 1; ++i) {
        while (j > 0 && diff[i] != pattern[j]) {
            j = lps[j - 1];
        }
        if (diff[i] == pattern[j]) ++j;
        if (j == m) {
            ++count;
            j = lps[j - 1];
        }
    }
    return count;
}

