int maxConsecutiveElements(std::vector<int> nums) {
    if (nums.empty()) return 0;
    int maxVal = 0;
    for (int v : nums) if (v > maxVal) maxVal = v;
    std::sort(nums.begin(), nums.end());
    std::vector<char> used(maxVal + 2, 0);
    for (int x : nums) {
        if (!used[x]) {
            used[x] = 1;
        } else if (x + 1 <= maxVal + 1 && !used[x + 1]) {
            used[x + 1] = 1;
        }
    }
    int best = 0, cur = 0;
    for (size_t i = 0; i < used.size(); ++i) {
        if (used[i]) {
            ++cur;
        } else {
            if (cur > best) best = cur;
            cur = 0;
        }
    }
    if (cur > best) best = cur;
    return best;
}

