bool isPrime(int x) {
    if (x < 2) return false;
    if (x % 2 == 0) return x == 2;
    for (int i = 3; i * i <= x; i += 2) {
        if (x % i == 0) return false;
    }
    return true;
}

int mostFrequentPrime(const std::vector<std::vector<int>>& mat) {
    int m = static_cast<int>(mat.size());
    int n = static_cast<int>(mat[0].size());
    const int dx[8] = {-1, -1, -1, 0, 0, 1, 1, 1};
    const int dy[8] = {-1, 0, 1, -1, 1, -1, 0, 1};
    std::unordered_map<int, int> freq;

    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            for (int dir = 0; dir < 8; ++dir) {
                int x = i, y = j;
                int num = 0;
                int steps = 0;
                while (x >= 0 && x < m && y >= 0 && y < n) {
                    num = num * 10 + mat[x][y];
                    ++steps;
                    if (steps >= 2 && num > 10 && isPrime(num)) {
                        ++freq[num];
                    }
                    x += dx[dir];
                    y += dy[dir];
                }
            }
        }
    }

    int best = -1;
    int bestCount = 0;
    for (const auto& p : freq) {
        if (p.second > bestCount || (p.second == bestCount && p.first > best)) {
            bestCount = p.second;
            best = p.first;
        }
    }
    return bestCount == 0 ? -1 : best;
}

