long long largestSquareArea(const std::vector<std::vector<int>>& bottomLeft, const std::vector<std::vector<int>>& topRight) {
    std::size_t n = bottomLeft.size();
    int maxSide = 0;
    for (std::size_t i = 0; i < n; ++i) {
        for (std::size_t j = i + 1; j < n; ++j) {
            int left   = std::max(bottomLeft[i][0], bottomLeft[j][0]);
            int bottom = std::max(bottomLeft[i][1], bottomLeft[j][1]);
            int right  = std::min(topRight[i][0], topRight[j][0]);
            int top    = std::min(topRight[i][1], topRight[j][1]);
            if (left < right && bottom < top) {
                int side = std::min(right - left, top - bottom);
                if (side > maxSide) maxSide = side;
            }
        }
    }
    return static_cast<long long>(maxSide) * maxSide;
}

