    Node() : end(0) {
        for (int i = 0; i < 26; ++i) child[i] = nullptr;
    }
};

long long countPrefixAndSuffixPairs(const std::vector<std::string>& words) {
    Node* root = new Node();
    long long ans = 0;
    for (const std::string& w : words) {
        int n = static_cast<int>(w.size());
        std::vector<int> pi(n);
        for (int i = 1; i < n; ++i) {
            int j = pi[i - 1];
            while (j > 0 && w[i] != w[j]) {
                j = pi[j - 1];
            }
            if (w[i] == w[j]) {
                ++j;
            }
            pi[i] = j;
        }
        std::vector<bool> isBorder(n + 1, false);
        int len = n;
        while (len > 0) {
            isBorder[len] = true;
            len = pi[len - 1];
        }
        Node* node = root;
        for (int i = 0; i < n; ++i) {
            int idx = w[i] - 'a';
            if (node) node = node->child[idx];
            if (isBorder[i + 1] && node) {
                ans += node->end;
            }
        }
        node = root;
        for (int i = 0; i < n; ++i) {
            int idx = w[i] - 'a';
            if (node->child[idx] == nullptr) {
                node->child[idx] = new Node();
            }
            node = node->child[idx];
        }
        node->end++;
    }
    return ans;
}

