std::vector<int> beautifulIndices(const std::string& s, const std::string& a, const std::string& b, int k) {
    std::vector<int> indices;
    for (size_t i = 0; i + a.size() <= s.size(); ++i) {
        if (s.compare(i, a.size(), a) == 0) {
            for (size_t j = 0; j + b.size() <= s.size(); ++j) {
                size_t diff = (i > j) ? (i - j) : (j - i);
                if (s.compare(j, b.size(), b) == 0 && diff <= static_cast<size_t>(k)) {
                    indices.push_back(static_cast<int>(i));
                    break;
