using namespace std;

bool feasible(int s, const vector<int>& nums, const vector<vector<int>>& pos, int n) {
    vector<pair<int, long long>> tasks;
    tasks.reserve(n);
    long long totalDecrements = 0;
    for (int i = 1; i <= n; ++i) {
        const auto& v = pos[i];
        int latest = -1;
        int lo = 0, hi = (int)v.size() - 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (v[mid] <= s) {
                latest = v[mid];
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        if (latest == -1) return false;               // no chance to mark this index
        tasks.emplace_back(latest - 1, (long long)nums[i - 1]); // deadline for decrements
        totalDecrements += nums[i - 1];
    }
    if (totalDecrements > (long long)s - n) return false; // not enough free seconds
    sort(tasks.begin(), tasks.end(),
         [](const pair<int, long long>& a, const pair<int, long long>& b) {
             return a.first < b.first;
         });
    long long cum = 0;
    for (auto& t : tasks) {
        cum += t.second;
        if (cum > t.first) return false; // cannot finish required decrements before its deadline
    }
    return true;
}

int earliestSecondToMarkIndices(vector<int> nums, vector<int> changeIndices) {
    int n = (int)nums.size();
    int m = (int)changeIndices.size();
    vector<vector<int>> pos(n + 1);
    for (int t = 0; t < m; ++t) {
        int idx = changeIndices[t];
        if (1 <= idx && idx <= n) pos[idx].push_back(t + 1); // seconds are 1‑based
    }
    int lo = 1, hi = m, ans = -1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (feasible(mid, nums, pos, n)) {
            ans = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    return ans;
}

class Solution {
public:
    int earliestSecondToMarkIndices(vector<int>& nums, vector<int>& changeIndices) {
        int n = nums.size(), m = changeIndices.size();
        long long numsSum = 0;
        for (int v : nums) numsSum += v;
        unordered_map<int,int> indexToFirstSecond;
        for (int s = 0; s < m; s++) {
            int idx = changeIndices[s] - 1;
            if (nums[idx] > 0 && !indexToFirstSecond.count(idx)) indexToFirstSecond[idx] = s;
        }
        unordered_map<int,int> secondToIndex;
        for (auto& [idx, s] : indexToFirstSecond) secondToIndex[s] = idx;

        auto canMark = [&](int maxSecond) {
            priority_queue<int, vector<int>, greater<int>> minHeap;
            int marks = 0;
            long long heapSum = 0;
            for (int second = maxSecond - 1; second >= 0; second--) {
                auto it = secondToIndex.find(second);
                if (it != secondToIndex.end()) {
                    int idx = it->second;
                    minHeap.push(nums[idx]);
                    heapSum += nums[idx];
                    if (marks == 0) {
                        heapSum -= minHeap.top();
                        minHeap.pop();
                        marks++;
                    } else {
                        marks--;
                    }
                } else {
                    marks++;
                }
            }
            int heapSize = minHeap.size();
            long long decrementAndMarkCost = (numsSum - heapSum) + (n - heapSize);
            long long zeroAndMarkCost = (long long) heapSize * 2;
            return decrementAndMarkCost + zeroAndMarkCost <= maxSecond;
        };

        int lo = 0, hi = m + 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (canMark(mid)) hi = mid; else lo = mid + 1;
        }
        return lo <= m ? lo : -1;
    }
};

