int minOperations(const std::vector<int>& nums, int k) {
    if (nums.size() < 2) {
        return -1;
    }
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> heap;
    for (int v : nums) {
        heap.push(v);
    }
    int ops = 0;
    while (heap.size() >= 2) {
        long long a = heap.top();
        heap.pop();
        long long b = heap.top();
        heap.pop();
        if (a + b > k) {
            heap.push(a);
            heap.push(b);
            break;
        }
        heap.push(a + b);
        ++ops;
    }
    return ops;
}

