int signalSpeedG;
vector<vector<pair<int,int>>> adjG;

int dfs(int u, int parent, long long dist) {
    int cnt = (dist % signalSpeedG == 0) ? 1 : 0;
    for (auto& [v, w] : adjG[u]) {
        if (v == parent) continue;
        cnt += dfs(v, u, dist + w);
    }
    return cnt;
}

vector<int> countPairsOfConnectableServers(vector<vector<int>>& edges, int signalSpeed) {
    int n = edges.size() + 1;
    signalSpeedG = signalSpeed;
    adjG.assign(n, {});
    for (auto& e : edges) {
        adjG[e[0]].push_back({e[1], e[2]});
        adjG[e[1]].push_back({e[0], e[2]});
    }
    vector<int> count(n, 0);
    for (int root = 0; root < n; root++) {
        long long total = 0, pairs = 0;
        for (auto& [child, w] : adjG[root]) {
            long long branchCount = dfs(child, root, w);
            pairs += total * branchCount;
            total += branchCount;
        }
        count[root] = (int)pairs;
    }
    return count;
}

