void solve() {
    std::vector<long long> data;
    long long val;
    while (std::cin >> val) {
        data.push_back(val);
    }
    if (data.empty()) return;
    size_t idx = 0;
    long long n = data[idx++];
    std::vector<long long> nums;
    nums.reserve(n);
    for (long long i = 0; i < n; ++i) {
        nums.push_back(data[idx++]);
    }
    long long k = data[idx++];
    for (long long i = 0; i < n - 1; ++i) {
        idx += 2;
    }
    long long base_sum = 0;
    for (long long v : nums) base_sum += v;
    long long pos_sum = 0;
    long long pos_cnt = 0;
    long long min_pos = 0;
    bool has_min_pos = false;
    long long max_neg = 0;
    bool has_max_neg = false;
    for (long long v : nums) {
        long long y = v ^ k;
        long long diff = y - v;
        if (diff > 0) {
            pos_sum += diff;
            ++pos_cnt;
            if (!has_min_pos || diff < min_pos) {
                min_pos = diff;
                has_min_pos = true;
            }
        } else {
            if (!has_max_neg || diff > max_neg) {
                max_neg = diff;
                has_max_neg = true;
            }
        }
    }
    long long ans;
    if (pos_cnt % 2 == 0) {
        ans = base_sum + pos_sum;
    } else {
        long long cand1 = LLONG_MIN;
        if (has_min_pos) cand1 = base_sum + pos_sum - min_pos;
        long long cand2 = LLONG_MIN;
        if (has_max_neg) cand2 = base_sum + pos_sum + max_neg;
        ans = std::max(cand1, cand2);
    }
    std::cout << ans;
}

