std::vector<std::vector<int>> parse_grid_literal(const std::string& s) {
    std::vector<std::vector<int>> grid;
    std::vector<int> row;
    bool in_outer = false;
    bool in_row = false;
    size_t i = 0;
    while (i < s.size()) {
        char ch = s[i];
        if (ch == '[') {
            if (!in_outer) {
                in_outer = true;
            } else if (in_outer && !in_row) {
                in_row = true;
                row.clear();
            }
            ++i;
        } else if (ch == ']') {
            if (in_row) {
                grid.push_back(row);
                in_row = false;
            }
            ++i;
        } else if (ch == '-' || std::isdigit(static_cast<unsigned char>(ch))) {
            int sign = 1;
            if (ch == '-') {
                sign = -1;
                ++i;
            }
            long long num = 0;
            while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
                num = num * 10 + (s[i] - '0');
                ++i;
            }
            int val = static_cast<int>(sign * num);
            if (in_row) {
                row.push_back(val);
            }
        } else {
            ++i;
        }
    }
    return grid;
}

int minimum_operations(const std::vector<std::vector<int>>& grid) {
    int n = static_cast<int>(grid.size());
    int mid = n / 2;
    std::array<int, 3> ycnt = {0, 0, 0};
    std::array<int, 3> othercnt = {0, 0, 0};
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            int val = grid[r][c];
            bool isY = (c == mid && r >= mid) ||
                       (r == c && r <= mid) ||
                       (r + c == n - 1 && r <= mid);
            if (isY) {
                ycnt[val] += 1;
            } else {
                othercnt[val] += 1;
            }
        }
    }
    int y_total = ycnt[0] + ycnt[1] + ycnt[2];
    int other_total = othercnt[0] + othercnt[1] + othercnt[2];
    int best = INT_MAX;
    for (int a = 0; a < 3; ++a) {
        for (int b = 0; b < 3; ++b) {
            if (a == b) continue;
            int changes = (y_total - ycnt[a]) + (other_total - othercnt[b]);
            if (changes < best) best = changes;
        }
    }
    return best;
}

void solve() {
    std::string data((std::istreambuf_iterator<char>(std::cin)), std::istreambuf_iterator<char>());
    size_t pos = data.find_first_not_of(" \t\r\n");
