class BIT {
    int size;
    std::vector<int> tree;
public:
    BIT(int n) : size(n), tree(n + 2, 0) {}
    void update(int idx, int delta) {
        while (idx <= size) {
            tree[idx] += delta;
            idx += idx & -idx;
        }
    }
    int query(int idx) const {
        int sum = 0;
        while (idx > 0) {
            sum += tree[idx];
            idx -= idx & -idx;
        }
        return sum;
    }
};

std::vector<int> resultArray(const std::vector<int>& nums) {
    int n = nums.size();
    std::vector<int> sorted = nums;
    std::sort(sorted.begin(), sorted.end());
    sorted.erase(std::unique(sorted.begin(), sorted.end()), sorted.end());
    int m = sorted.size();

    std::unordered_map<int, int> idxMap;
    idxMap.reserve(m * 2);
    for (int i = 0; i < m; ++i) {
        idxMap[sorted[i]] = i + 1;
    }

    BIT bit1(m);
    BIT bit2(m);
    int total1 = 0, total2 = 0;

    std::vector<int> arr1;
    std::vector<int> arr2;
    arr1.reserve(n);
    arr2.reserve(n);

    for (int i = 0; i < n; ++i) {
        int val = nums[i];
        int idx = idxMap[val];
        if (i == 0) {
            arr1.push_back(val);
            bit1.update(idx, 1);
            ++total1;
        } else if (i == 1) {
            arr2.push_back(val);
            bit2.update(idx, 1);
            ++total2;
        } else {
            int cnt1 = total1 - bit1.query(idx);
            int cnt2 = total2 - bit2.query(idx);
            if (cnt1 > cnt2) {
                arr1.push_back(val);
                bit1.update(idx, 1);
                ++total1;
            } else if (cnt2 > cnt1) {
                arr2.push_back(val);
                bit2.update(idx, 1);
                ++total2;
            } else {
                if (arr1.size() < arr2.size()) {
                    arr1.push_back(val);
                    bit1.update(idx, 1);
                    ++total1;
                } else if (arr2.size() < arr1.size()) {
                    arr2.push_back(val);
                    bit2.update(idx, 1);
                    ++total2;
                } else {
                    arr1.push_back(val);
                    bit1.update(idx, 1);
                    ++total1;
                }
            }
        }
    }

    std::vector<int> result;
    result.reserve(n);
    result.insert(result.end(), arr1.begin(), arr1.end());
    result.insert(result.end(), arr2.begin(), arr2.end());
    return result;
}

