long long maximumStrength(const std::vector<long long>& nums, int k) {
    int n = (int)nums.size();
    const long long NEG_INF = std::numeric_limits<long long>::min() / 4;
    // f[i][j][0/1] = best value using first i elements, j subarrays chosen so far,
    // 0 = not currently inside a subarray, 1 = currently inside a subarray
    std::vector<std::vector<std::array<long long,2>>> f(
        n+1, std::vector<std::array<long long,2>>(k+1, {NEG_INF, NEG_INF}));
    f[0][0][0] = 0;
    for (int i = 1; i <= n; i++) {
        long long x = nums[i-1];
        for (int j = 0; j <= k; j++) {
            long long sign = (j % 2 == 1) ? 1 : -1;
            long long val = sign * x * (k - j + 1);
            f[i][j][0] = std::max(f[i-1][j][0], f[i-1][j][1]);
            f[i][j][1] = (f[i-1][j][1] != NEG_INF) ? f[i-1][j][1] + val : NEG_INF;
            if (j > 0) {
                long long prevBest = std::max(f[i-1][j-1][0], f[i-1][j-1][1]);
                if (prevBest != NEG_INF) {
                    f[i][j][1] = std::max(f[i][j][1], prevBest + val);
                }
            }
        }
    }
    return std::max(f[n][k][0], f[n][k][1]);
}

