std::vector<std::string> shortestUncommonSubstrings(const std::vector<std::string>& arr) {
    std::unordered_map<std::string, int> cnt;
    for (const std::string& s : arr) {
        std::unordered_set<std::string> local;
        int m = static_cast<int>(s.size());
        for (int i = 0; i < m; ++i) {
            for (int len = 1; i + len <= m; ++len) {
                local.insert(s.substr(i, len));
            }
        }
        for (const auto& sub : local) {
            ++cnt[sub];
        }
    }

    std::vector<std::string> answer;
    answer.reserve(arr.size());
    for (const std::string& s : arr) {
        std::unordered_set<std::string> seen;
        std::string best = "";
        int bestLen = std::numeric_limits<int>::max();
        int m = static_cast<int>(s.size());
        for (int i = 0; i < m; ++i) {
            for (int len = 1; i + len <= m; ++len) {
                std::string sub = s.substr(i, len);
                if (!seen.insert(sub).second) continue;
                if (cnt[sub] == 1) {
                    if (len < bestLen || (len == bestLen && sub < best)) {
                        best = sub;
                        bestLen = len;
                    }
                }
            }
        }
        answer.push_back(best);
    }
    return answer;
}

