int minDeletions(std::string word, int k) {
    int freq[26] = {0};
    for (char ch : word) {
        freq[ch - 'a']++;
    }
    int n = word.size();
    int maxFreq = 0;
    for (int i = 0; i < 26; ++i) {
        if (freq[i] > maxFreq) maxFreq = freq[i];
    }
    int answer = n; // delete all characters
    for (int target = 1; target <= maxFreq; ++target) {
        int lower = target - k;
        if (lower < 0) lower = 0;
        int deletions = 0;
        for (int i = 0; i < 26; ++i) {
            int c = freq[i];
            if (c > target) deletions += c - target;
            else if (c < lower) deletions += c;
        }
        if (deletions < answer) answer = deletions;
    }
    return answer;
}

