const long long MOD = 1000000007LL;

void solve() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::vector<long long> data;
    long long x;
    while (std::cin >> x) {
        data.push_back(x);
    }
    if (data.empty()) return;
    int n = static_cast<int>(data[0]);
    int k = static_cast<int>(data[1]);
    std::vector<int> nums;
    nums.reserve(n);
    for (int i = 0; i < n; ++i) {
        nums.push_back(static_cast<int>(data[2 + i]));
    }
    std::vector<long long> pow2(n + 1);
    pow2[0] = 1;
    for (int i = 1; i <= n; ++i) {
        pow2[i] = (pow2[i - 1] * 2) % MOD;
    }
    std::vector<std::vector<long long>> dp(n + 1, std::vector<long long>(k + 1, 0));
    dp[0][0] = 1;
    for (int val : nums) {
        for (int t = n; t >= 1; --t) {
            for (int s = k; s >= val; --s) {
                dp[t][s] = (dp[t][s] + dp[t - 1][s - val]) % MOD;
            }
        }
    }
    long long ans = 0;
    for (int t = 0; t <= n; ++t) {
        long long cnt = dp[t][k];
        if (cnt) {
            ans = (ans + cnt * pow2[n - t]) % MOD;
        }
    }
    std::cout << ans;
}

