std::vector<long long> sumOfMarkedElements(const std::vector<int>& nums, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(nums.size());
    int m = static_cast<int>(queries.size());
    long long total = 0LL;
    for (int v : nums) total += v;
    std::vector<char> marked(n, 0);
    struct Compare {
        bool operator()(const std::array<int, 2>& a, const std::array<int, 2>& b) const {
            if (a[0] != b[0]) return a[0] > b[0];
            return a[1] > b[1];
        }
    };
    std::priority_queue<std::array<int, 2>, std::vector<std::array<int, 2>>, Compare> pq;
    for (int i = 0; i < n; ++i) {
        pq.push({nums[i], i});
    }
    std::vector<long long> ans(m);
    for (int i = 0; i < m; ++i) {
        int idx = queries[i][0];
        int k = queries[i][1];
        if (!marked[idx]) {
            marked[idx] = 1;
            total -= nums[idx];
        }
        int cnt = 0;
        while (cnt < k && !pq.empty()) {
            const auto& top = pq.top();
            int val = top[0];
            int id = top[1];
            if (marked[id]) {
                pq.pop();
                continue;
            }
            marked[id] = 1;
            total -= val;
            pq.pop();
            ++cnt;
        }
        ans[i] = total;
    }
    return ans;
}

#include <bits/stdc++.h>
long long minimumMoves(const std::vector<int>& nums, long long k, long long maxChanges) {
    long long n = static_cast<long long>(nums.size());
    std::vector<long long> cnt(n + 1, 0), s(n + 1, 0);
    for (long long i = 1; i <= n; ++i) {
        long long x = nums[i - 1];
        cnt[i] = cnt[i - 1] + x;
        s[i] = s[i - 1] + i * x;
    }
    long long ans = LLONG_MAX;
    for (long long i = 1; i <= n; ++i) {
        long long x = nums[i - 1];
        long long t = 0;
        long long need = k - x;
        for (long long j : {i - 1, i + 1}) {
            if (need > 0 && j >= 1 && j <= n && nums[j - 1] == 1) { need -= 1; t += 1; }
        }
        long long c = std::min(need, maxChanges);
        need -= c;
        t += c * 2;
        if (need <= 0) { ans = std::min(ans, t); continue; }
        long long l = 2, r = std::max(i - 1, n - i);
        while (l <= r) {
            long long mid = (l + r) >> 1;
            long long l1 = std::max(1LL, i - mid), r1 = std::max(0LL, i - 2);
            long long l2 = std::min(n + 1, i + 2), r2 = std::min(n, i + mid);
            long long c1 = cnt[r1] - cnt[l1 - 1];
            long long c2 = cnt[r2] - cnt[l2 - 1];
            if (c1 + c2 >= need) {
                long long t1 = c1 * i - (s[r1] - s[l1 - 1]);
                long long t2 = s[r2] - s[l2 - 1] - c2 * i;
                ans = std::min(ans, t + t1 + t2);
                r = mid - 1;
            } else { l = mid + 1; }
        }
    }
    return ans;
}

