int maxLengthSubstringWithTwoOccurrences(const std::string& s) {
    int n = s.size();
    if (n == 0) return 0;
    unordered_map<char,int> cnt;
    int left = 0, maxLen = 0;
    for (int right = 0; right < n; right++) {
        cnt[s[right]]++;
        while (cnt[s[right]] > 2) {
            cnt[s[left]]--;
            left++;
