    for (std::size_t i = 0; i < wordsContainer.size(); ++i) {
        const std::string& word = wordsContainer[i];
        std::size_t wLen = word.size();
        Node* cur = root;
        if (wLen < cur->bestLen || (wLen == cur->bestLen && static_cast<int>(i) < cur->bestIdx)) {
            cur->bestLen = wLen;
            cur->bestIdx = static_cast<int>(i);
        }
        for (int p = static_cast<int>(wLen) - 1; p >= 0; --p) {
            char ch = word[p];
            auto it = cur->children.find(ch);
            if (it == cur->children.end()) {
                Node* newNode = new Node();
                cur->children[ch] = newNode;
                cur = newNode;
            } else {
                cur = it->second;
            }
            if (wLen < cur->bestLen || (wLen == cur->bestLen && static_cast<int>(i) < cur->bestIdx)) {
                cur->bestLen = wLen;
                cur->bestIdx = static_cast<int>(i);
            }
        }
    }

    std::vector<int> answer(wordsQuery.size());
    for (std::size_t q = 0; q < wordsQuery.size(); ++q) {
        const std::string& query = wordsQuery[q];
        Node* cur = root;
        for (int p = static_cast<int>(query.size()) - 1; p >= 0; --p) {
            char ch = query[p];
            auto it = cur->children.find(ch);
            if (it == cur->children.end()) break;
            cur = it->second;
        }
        answer[q] = cur->bestIdx;
    }
    return answer;
}

#include <bits/stdc++.h>
#include <vector>
#include <unordered_map>

std::vector<int> mostFrequentIDs(const std::vector<int>& nums, const std::vector<int>& freq) {
    std::unordered_map<int, int> idCount;
    std::unordered_map<int, int> freqCount;
    int maxFreq = 0;
    std::vector<int> ans(nums.size());

    for (size_t i = 0; i < nums.size(); ++i) {
        int id = nums[i];
        int delta = freq[i];
        int oldCnt = 0;
        auto itId = idCount.find(id);
        if (itId != idCount.end()) {
            oldCnt = itId->second;
        }
        int newCnt = oldCnt + delta;

        if (oldCnt > 0) {
            auto itFreq = freqCount.find(oldCnt);
            if (itFreq != freqCount.end()) {
                int oldFreqNum = itFreq->second - 1;
                if (oldFreqNum == 0) {
                    freqCount.erase(itFreq);
                } else {
                    itFreq->second = oldFreqNum;
                }
            }
        }

        if (newCnt > 0) {
            idCount[id] = newCnt;
            freqCount[newCnt] = (freqCount.find(newCnt) != freqCount.end() ? freqCount[newCnt] : 0) + 1;
        } else {
            if (itId != idCount.end()) {
                idCount.erase(itId);
            }
        }

        if (newCnt > maxFreq) {
            maxFreq = newCnt;
        }
        while (maxFreq > 0) {
            auto itFreq = freqCount.find(maxFreq);
            int countAtMax = (itFreq != freqCount.end() ? itFreq->second : 0);
            if (countAtMax == 0) {
                --maxFreq;
            } else {
                break;
            }
        }

        ans[i] = maxFreq;
    }

    return ans;
}

