#include <algorithm>
#include <climits>

int minimumSubarrayLength(const std::vector<int>& nums, int k) {
    if (nums.empty()) return -1;
    if (k == 0) return 1;  // any single element works

    const int MAX_BITS = 31; // because nums[i] <= 1e9 < 2^30
    int bitCount[MAX_BITS] = {0};
    int currentOr = 0;
    int left = 0;
    int best = INT_MAX;

    for (int right = 0; right < (int)nums.size(); ++right) {
        int x = nums[right];
        for (int b = 0; b < MAX_BITS; ++b) {
            if (x & (1 << b)) {
                if (bitCount[b] == 0) currentOr |= (1 << b);
                ++bitCount[b];
            }
        }

        while (currentOr >= k && left <= right) {
            best = std::min(best, right - left + 1);
            int y = nums[left];
            for (int b = 0; b < MAX_BITS; ++b) {
                if (y & (1 << b)) {
                    --bitCount[b];
                    if (bitCount[b] == 0) currentOr &= ~(1 << b);
                }
            }
            ++left;
        }
    }

    return (best == INT_MAX) ? -1 : best;
}

