int shortestSubarray(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    int ans = INT_MAX;
    int left = 0;
    int bitCnt[32] = {0};
    int currentOR = 0;

    for (int right = 0; right < n; ++right) {
        int val = nums[right];
        for (int b = 0; b < 32; ++b) {
            if ((val & (1 << b)) != 0) {
                ++bitCnt[b];
            }
        }
        currentOR = 0;
        for (int b = 0; b < 32; ++b) {
            if (bitCnt[b] > 0) {
                currentOR |= (1 << b);
            }
        }

        while (left <= right && currentOR >= k) {
            ans = std::min(ans, right - left + 1);
            int removeVal = nums[left];
            for (int b = 0; b < 32; ++b) {
                if ((removeVal & (1 << b)) != 0) {
                    --bitCnt[b];
                }
            }
            ++left;
            currentOR = 0;
            for (int b = 0; b < 32; ++b) {
                if (bitCnt[b] > 0) {
                    currentOR |= (1 << b);
                }
            }
        }
    }

    return ans == INT_MAX ? -1 : ans;
}

