#include <bits/stdc++.h>

long long sumSubsequencePowers(const std::vector<long long>& nums, int k) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(nums.size());
    if (k <= 1) return 0LL;
    std::vector<long long> a = nums;
    std::sort(a.begin(), a.end());

    std::vector<long long> diffs;
    diffs.reserve(n * (n - 1) / 2);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            diffs.push_back(a[j] - a[i]);
        }
    }
    std::sort(diffs.begin(), diffs.end());
    diffs.erase(std::unique(diffs.begin(), diffs.end()), diffs.end());

    std::unordered_map<long long, long long> countMap;
    for (long long d : diffs) {
        std::vector<std::vector<long long>> dp(n, std::vector<long long>(k + 1, 0LL));
        for (int i = 0; i < n; ++i) dp[i][1] = 1LL;
        for (int t = 2; t <= k; ++t) {
            for (int i = 0; i < n; ++i) {
                long long sum = 0LL;
                for (int p = 0; p < i; ++p) {
                    if (a[i] - a[p] >= d) {
                        sum += dp[p][t - 1];
                        if (sum >= MOD) sum -= MOD;
                    }
                }
                dp[i][t] = sum % MOD;
            }
        }
        long long total = 0LL;
        for (int i = 0; i < n; ++i) {
            total += dp[i][k];
            if (total >= MOD) total -= MOD;
        }
        countMap[d] = total % MOD;
    }

    long long ans = 0LL;
    long long prev = 0LL;
    for (int idx = static_cast<int>(diffs.size()) - 1; idx >= 0; --idx) {
        long long d = diffs[idx];
        long long cntAtLeast = countMap[d];
        long long cntExact = (cntAtLeast - prev + MOD) % MOD;
        ans = (ans + cntExact * (d % MOD)) % MOD;
        prev = cntAtLeast;
    }
    return ans;
}

#include <bits/stdc++.h>
long long minimumDistance(const std::vector<std::vector<int>>& points) {
    int n = points.size();
    std::vector<long long> u(n), v(n);
    for (int i = 0; i < n; ++i) {
        long long x = points[i][0];
        long long y = points[i][1];
        u[i] = x + y;
        v[i] = x - y;
    }

    long long max_u = LLONG_MIN, second_max_u = LLONG_MIN, cnt_max_u = 0;
    long long min_u = LLONG_MAX, second_min_u = LLONG_MAX, cnt_min_u = 0;
    long long max_v = LLONG_MIN, second_max_v = LLONG_MIN, cnt_max_v = 0;
    long long min_v = LLONG_MAX, second_min_v = LLONG_MAX, cnt_min_v = 0;

    for (int i = 0; i < n; ++i) {
        long long val = u[i];
        if (val > max_u) {
            second_max_u = max_u;
            max_u = val;
            cnt_max_u = 1;
        } else if (val == max_u) {
            ++cnt_max_u;
        } else if (val > second_max_u) {
            second_max_u = val;
        }

        if (val < min_u) {
            second_min_u = min_u;
            min_u = val;
            cnt_min_u = 1;
        } else if (val == min_u) {
            ++cnt_min_u;
        } else if (val < second_min_u) {
            second_min_u = val;
        }

        val = v[i];
        if (val > max_v) {
            second_max_v = max_v;
            max_v = val;
            cnt_max_v = 1;
        } else if (val == max_v) {
            ++cnt_max_v;
        } else if (val > second_max_v) {
            second_max_v = val;
        }

        if (val < min_v) {
            second_min_v = min_v;
            min_v = val;
            cnt_min_v = 1;
        } else if (val == min_v) {
            ++cnt_min_v;
        } else if (val < second_min_v) {
            second_min_v = val;
        }
    }

    long long answer = LLONG_MAX;
    for (int i = 0; i < n; ++i) {
        long long cur_max_u = (u[i] == max_u && cnt_max_u == 1) ? second_max_u : max_u;
        long long cur_min_u = (u[i] == min_u && cnt_min_u == 1) ? second_min_u : min_u;
        long long cur_max_v = (v[i] == max_v && cnt_max_v == 1) ? second_max_v : max_v;
        long long cur_min_v = (v[i] == min_v && cnt_min_v == 1) ? second_min_v : min_v;

        long long candidate = std::max(cur_max_u - cur_min_u, cur_max_v - cur_min_v);
        if (candidate < answer) answer = candidate;
    }
    return answer;
}

