    for (size_t i = 1; i < nums.size(); ++i) {
        if (nums[i] > nums[i - 1]) {
            incLen = incLen + 1;
            decLen = 1;
        } else if (nums[i] < nums[i - 1]) {
            decLen = decLen + 1;
            incLen = 1;
        } else {
            incLen = 1;
            decLen = 1;
        }
        best = std::max(best, std::max(incLen, decLen));
    }
    return best;
}

