std::string getSmallestString(const std::string& s, int k) {
    int n = static_cast<int>(s.length());
    const int maxPerPos = 13;
    std::string result;
    int remaining = k;
    for (int i = 0; i < n; ++i) {
        char original = s[i];
        bool found = false;
        for (char c = 'a'; c <= 'z'; ++c) {
            int d = distanceChar(original, c);
            if (d <= remaining) {
                int maxPossible = maxPerPos * (n - i - 1);
                if (remaining - d <= maxPossible) {
                    result.push_back(c);
                    remaining -= d;
                    found = true;
                    break;
                }
            }
        }
        if (!found) {
            return "";
        }
    }
    if (remaining != 0) {
        return "";
    }
    return result;
}

