long long countSubarrays(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> nextGreater(n, n);
    std::vector<int> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[i] > nums[st.back()]) {
            int idx = st.back();
            st.pop_back();
            nextGreater[idx] = i;
        }
        st.push_back(i);
    }

    std::unordered_map<int, std::vector<int>> posMap;
    for (int i = 0; i < n; ++i) {
        int v = nums[i];
        posMap[v].push_back(i);
    }

    long long ans = 0;
    for (auto& kv : posMap) {
        const std::vector<int>& positions = kv.second;
        long long cnt = 0;
        int prev = -1;
        for (int pos : positions) {
            if (cnt == 0) {
                cnt = 1;
                prev = pos;
            } else {
                if (nextGreater[prev] > pos) {
                    ++cnt;
                } else {
                    ans += cnt * (cnt + 1) / 2;
                    cnt = 1;
                }
                prev = pos;
            }
        }
        ans += cnt * (cnt + 1) / 2;
    }
    return ans;
}

#include <bits/stdc++.h>
std::vector<int> minimumCostWalk(int n, const std::vector<std::vector<int>>& edges, const std::vector<std::vector<int>>& query) {
    std::vector<int> parent(n), sz(n, 1);
    std::vector<unsigned int> compAnd(n, ~0u);
    for (int i = 0; i < n; ++i) parent[i] = i;
    std::function<int(int)> find = [&](int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    };
    auto unite = [&](int a, int b, unsigned int w) {
        int ra = find(a), rb = find(b);
        if (ra == rb) {
            compAnd[ra] &= w;
            return;
        }
        unsigned int newAnd = compAnd[ra] & compAnd[rb] & w;
        if (sz[ra] < sz[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
        compAnd[ra] = newAnd;
    };
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        unsigned int w = static_cast<unsigned int>(e[2]);
        unite(u, v, w);
    }
    std::vector<int> ans;
    ans.reserve(query.size());
    for (const auto& q : query) {
        int s = q[0], t = q[1];
        if (find(s) != find(t)) ans.push_back(-1);
        else ans.push_back(static_cast<int>(compAnd[find(s)]));
    }
    return ans;
}

#include <bits/stdc++.h>
#include <vector>
#include <queue>
#include <climits>

std::vector<long long> minimumTime(int n, const std::vector<std::vector<int>>& edges, const std::vector<long long>& disappear) {
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int w = e[2];
        adj[u].emplace_back(v, w);
        adj[v].emplace_back(u, w);
    }
    const long long INF = LLONG_MAX / 4;
    std::vector<long long> dist(n, INF);
    if (0 < disappear[0]) {
        dist[0] = 0;
    } else {
        return std::vector<long long>(n, -1);
    }
    using Node = std::pair<long long, int>;
    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> heap;
    heap.emplace(0LL, 0);
    while (!heap.empty()) {
        auto cur = heap.top();
        heap.pop();
        long long time = cur.first;
        int node = cur.second;
        if (time != dist[node]) continue;
        if (time >= disappear[node]) continue;
        for (const auto& nb : adj[node]) {
            int nbr = nb.first;
            int w = nb.second;
            long long newTime = time + w;
            if (newTime < disappear[nbr] && newTime < dist[nbr]) {
                dist[nbr] = newTime;
                heap.emplace(newTime, nbr);
            }
        }
    }
    std::vector<long long> result(n);
    for (int i = 0; i < n; ++i) {
        result[i] = (dist[i] == INF) ? -1 : dist[i];
    }
    return result;
}

