using std::vector;
using std::uint64_t;
using std::size_t;

static uint64_t gcd_uint64(uint64_t a, uint64_t b) {
    while (b) {
        uint64_t t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static uint64_t lcm_uint64(uint64_t a, uint64_t b, uint64_t limit) {
    uint64_t g = gcd_uint64(a, b);
    uint64_t div = a / g;
    if (div > limit / b) return limit + 1; // overflow or exceeds limit
    return div * b;
}

static uint64_t count_le(uint64_t X, const vector<int>& coins) {
    size_t n = coins.size();
    uint64_t total = 0;
    uint64_t limit = X;
    for (uint32_t mask = 1; mask < (1u << n); ++mask) {
        uint64_t cur_lcm = 1;
        bool overflow = false;
        for (size_t i = 0; i < n; ++i) {
            if (mask & (1u << i)) {
                cur_lcm = lcm_uint64(cur_lcm, static_cast<uint64_t>(coins[i]), limit);
                if (cur_lcm > limit) { overflow = true; break; }
            }
        }
        if (overflow) continue;
        uint64_t add = X / cur_lcm;
        if (__builtin_popcount(mask) & 1) total += add;
        else total -= add;
    }
    return total;
}

long long kthSmallestAmount(const vector<int>& coins, long long k) {
    uint64_t min_coin = static_cast<uint64_t>(*std::min_element(coins.begin(), coins.end()));
    uint64_t low = 1, high = min_coin * static_cast<uint64_t>(k);
    while (low < high) {
        uint64_t mid = low + (high - low) / 2;
        if (count_le(mid, coins) >= static_cast<uint64_t>(k))
            high = mid;
        else
            low = mid + 1;
    }
    return static_cast<long long>(low);
}

