int countSpecialCharacters(const std::string& word) {
    std::unordered_set<char> lowerSet;
    std::unordered_set<char> upperSet;
    for (size_t i = 0; i < word.size(); ++i) {
        char ch = word[i];
        if (ch >= 'a' && ch <= 'z') {
            lowerSet.insert(ch);
        } else if (ch >= 'A' && ch <= 'Z') {
            upperSet.insert(ch);
        }
