    int specialCount = 0;
    for (char lc : lowerSet) {
        char uc = static_cast<char>(std::toupper(static_cast<unsigned char>(lc)));
        if (upperSet.find(uc) != upperSet.end()) {
            ++specialCount;
        }
    }
    return specialCount;
}

