    for (int i = 0; i < static_cast<int>(word.size()); ++i) {
        char c = word[i];
        if ('a' <= c && c <= 'z') {
            lastLower[c - 'a'] = i;
        } else if ('A' <= c && c <= 'Z') {
            int idx = c - 'A';
            if (firstUpper[idx] == INF) {
                firstUpper[idx] = i;
            }
        }
    }
    int count = 0;
    for (int i = 0; i < 26; ++i) {
        if (lastLower[i] != -1 && firstUpper[i] != INF && lastLower[i] < firstUpper[i]) {
            ++count;
        }
    }
    return count;
}

