int max_prime_difference(const std::vector<int>& nums) {
    auto is_prime = [](int x) -> bool {
        if (x < 2) return false;
        if (x == 2) return true;
        if (x % 2 == 0) return false;
        int limit = static_cast<int>(std::sqrt(x));
        for (int d = 3; d <= limit; d += 2) {
            if (x % d == 0) return false;
        }
        return true;
    };
    int first = -1;
    int last = -1;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (is_prime(nums[i])) {
            if (first == -1) first = static_cast<int>(i);
            last = static_cast<int>(i);
        }
    }
    if (first == -1) return 0;
    return last - first;
}

#include <bits/stdc++.h>
long long minimumSum(const std::vector<long long>& nums, const std::vector<long long>& andValues) {
    long long n = nums.size(), m = andValues.size();
    if (m == 0) return 0;
    if (m > n) return -1;
    const long long INF = 4e18;
    std::vector<std::vector<long long>> dp(n+1, std::vector<long long>(m+1, INF));
    dp[0][0] = 0;
    for (long long i = 1; i <= n; ++i) {
        long long curAnd = 0;
        for (long long left = i; left >= 1; --left) {
            if (left == i) curAnd = nums[i-1];
            else curAnd &= nums[left-1];
            for (long long k = 1; k <= m; ++k) {
                if (curAnd == andValues[k-1]) {
                    long long prev = dp[left-1][k-1];
                    if (prev != INF) {
                        long long cand = prev + nums[i-1];
                        if (cand < dp[i][k]) dp[i][k] = cand;
                    }
                }
            }
        }
    }
    long long ans = dp[n][m];
    return ans != INF ? ans : -1;
}

