#include <bits/stdc++.h>
#include <vector>

int countStableBinaryArrays(int zero, int one, int limit) {
    const int MOD = 1000000007;
    std::vector<std::vector<std::vector<std::vector<int>>>> dp(
        zero + 1,
        std::vector<std::vector<std::vector<int>>>(
            one + 1,
            std::vector<std::vector<int>>(
                2,
                std::vector<int>(limit + 1, 0)
            )
        )
    );
    if (zero > 0) dp[1][0][0][1] = 1;
    if (one > 0) dp[0][1][1][1] = 1;
    for (int z = 0; z <= zero; ++z) {
        for (int o = 0; o <= one; ++o) {
            for (int last = 0; last <= 1; ++last) {
                const std::vector<int>& curArr = dp[z][o][last];
                for (int len = 1; len <= limit; ++len) {
                    int cur = curArr[len];
                    if (cur == 0) continue;
                    if (last == 0) {
                        if (z < zero && len < limit) {
                            std::vector<int>& nxt = dp[z + 1][o][0];
                            nxt[len + 1] = (nxt[len + 1] + cur) % MOD;
                        }
                        if (o < one) {
                            std::vector<int>& nxt = dp[z][o + 1][1];
                            nxt[1] = (nxt[1] + cur) % MOD;
                        }
                    } else {
                        if (o < one && len < limit) {
                            std::vector<int>& nxt = dp[z][o + 1][1];
                            nxt[len + 1] = (nxt[len + 1] + cur) % MOD;
                        }
                        if (z < zero) {
                            std::vector<int>& nxt = dp[z + 1][o][0];
                            nxt[1] = (nxt[1] + cur) % MOD;
                        }
                    }
                }
            }
        }
    }
    int ans = 0;
    for (int last = 0; last <= 1; ++last) {
        const std::vector<int>& arr = dp[zero][one][last];
        for (int len = 1; len <= limit; ++len) {
            ans = (ans + arr[len]) % MOD;
        }
    }
    return ans;
}

