std::vector<long long> dijkstra(int n, int src, const std::vector<std::vector<std::pair<int,int>>>& adj) {
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<long long> dist(n, INF);
    dist[src] = 0;
    using Node = std::pair<long long,int>;
    std::priority_queue<Node, std::vector<Node>, std::greater<Node>> pq;
    pq.emplace(0LL, src);
    while (!pq.empty()) {
        Node top = pq.top();
        pq.pop();
        long long d = top.first;
        int u = top.second;
        if (d != dist[u]) continue;
        for (const auto& edge : adj[u]) {
            int v = edge.first;
            int w = edge.second;
            long long nd = d + static_cast<long long>(w);
            if (nd < dist[v]) {
                dist[v] = nd;
                pq.emplace(nd, v);
            }
        }
    }
    return dist;
}

std::vector<bool> findEdgesInShortestPaths(int n, std::vector<std::vector<int>>& edges) {
    std::vector<std::vector<std::pair<int,int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int w = e[2];
        adj[u].emplace_back(v, w);
        adj[v].emplace_back(u, w);
    }
    std::vector<long long> distStart = dijkstra(n, 0, adj);
    std::vector<long long> distEnd = dijkstra(n, n - 1, adj);
    const long long INF = std::numeric_limits<long long>::max() / 4;
    std::vector<bool> answer(edges.size(), false);
    long long shortest = distStart[n - 1];
    if (shortest == INF) return answer;
    for (size_t i = 0; i < edges.size(); ++i) {
        int u = edges[i][0];
        int v = edges[i][1];
        int w = edges[i][2];
        long long wll = static_cast<long long>(w);
        if (distStart[u] != INF && distEnd[v] != INF) {
            if (distStart[u] + wll + distEnd[v] == shortest) {
                answer[i] = true;
                continue;
            }
        }
        if (distStart[v] != INF && distEnd[u] != INF) {
            if (distStart[v] + wll + distEnd[u] == shortest) {
                answer[i] = true;
            }
        }
    }
    return answer;
}

