std::size_t minLengthAnagramConcat(const std::string& s) {
    std::unordered_map<char, std::size_t> freq;
    for (char ch : s) {
        ++freq[ch];
    }
    auto gcd = [](std::size_t a, std::size_t b) {
        while (b != 0) {
            std::size_t t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    std::size_t g = 0;
    for (const auto& kv : freq) {
        std::size_t v = kv.second;
        g = (g == 0) ? v : gcd(g, v);
    }
    return s.size() / g;
}

