int medianUniqueness(const std::vector<int>& nums) {
    long long n = static_cast<long long>(nums.size());
    long long total = n * (n + 1) / 2;
    long long k = (total + 1) / 2;

    auto countAtMost = [&](int limit) -> long long {
        std::unordered_map<int, int> freq;
        int left = 0;
        int distinct = 0;
        long long cnt = 0;
        for (int right = 0; right < static_cast<int>(n); ++right) {
            int val = nums[right];
            int cur = freq[val];
            if (cur == 0) ++distinct;
            freq[val] = cur + 1;
            while (distinct > limit) {
                int lval = nums[left];
                int lcur = freq[lval];
                if (lcur == 1) --distinct;
                freq[lval] = lcur - 1;
                ++left;
            }
            cnt += right - left + 1;
        }
        return cnt;
    };

    int low = 1;
    int high = static_cast<int>(n);
    while (low < high) {
        int mid = (low + high) / 2;
        if (countAtMost(mid) >= k) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

