#include <bits/stdc++.h>
long long minimumCost(const std::vector<int>& nums, long long cost1, long long cost2) {
    const long long MOD = 1000000007LL;
    int n = nums.size();
    long long maxVal = *std::max_element(nums.begin(), nums.end());

    auto costForTarget = [&](long long target) -> long long {
        std::vector<long long> diffs(n);
        long long S = 0, D = LLONG_MIN;
        for (int i = 0; i < n; i++) { diffs[i] = target - nums[i]; S += diffs[i]; D = std::max(D, diffs[i]); }
        if (cost2 >= 2*cost1 || n < 2) return S * cost1;
        long long rest = S - D;
        if (D <= rest) {
            long long pairs = S / 2;
            long long odd = S % 2;
            return pairs * cost2 + odd * cost1;
        } else {
            long long excess = D - rest;
            return excess * cost1 + rest * cost2;
        }
    };

    if (cost2 >= 2*cost1 || n <= 2) {
        long long r = costForTarget(maxVal) % MOD;
        if (r < 0) r += MOD;
        return r;
    }

    std::vector<long long> diffs0(n);
    long long S0 = 0, D0 = LLONG_MIN;
    for (int i=0;i<n;i++){ diffs0[i]=maxVal-nums[i]; S0+=diffs0[i]; D0=std::max(D0,diffs0[i]); }
    long long rest0 = S0 - D0;
    long long excess0 = D0 - rest0;
    long long tStar;
    if (excess0 <= 0) tStar = 0;
    else tStar = (excess0 + (n-2) - 1) / (n-2);

    std::set<long long> candidates = {0, tStar-1, tStar, tStar+1};
    long long best = LLONG_MAX;
    for (long long t : candidates) {
        if (t < 0) continue;
        best = std::min(best, costForTarget(maxVal + t));
    }
    best %= MOD;
    if (best < 0) best += MOD;
    return best;
}

