long long maxEnergy(const std::vector<int>& energy, int k) {
    int n = static_cast<int>(energy.size());
    std::vector<long long> dp(n);
    for (int i = n - 1; i >= 0; --i) {
        if (i + k < n) {
            dp[i] = static_cast<long long>(energy[i]) + dp[i + k];
        } else {
            dp[i] = static_cast<long long>(energy[i]);
        }
    }
    long long best = dp[0];
    for (int i = 1; i < n; ++i) {
        if (dp[i] > best) best = dp[i];
    }
    return best;
}

