std::vector<int> minCostPermutation(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    int fullMask = (1 << n) - 1;
    const long long INF = 1000000000000000LL;

    std::vector<std::vector<long long>> cost(n, std::vector<long long>(n, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cost[i][j] = std::llabs(static_cast<long long>(i) - static_cast<long long>(nums[j]));
        }
    }

    std::vector<std::vector<long long>> dp(1 << n, std::vector<long long>(n, INF));
    dp[1 << 0][0] = 0;

    for (int mask = 0; mask <= fullMask; ++mask) {
        for (int last = 0; last < n; ++last) {
            long long cur = dp[mask][last];
            if (cur == INF) continue;
            for (int nxt = 0; nxt < n; ++nxt) {
                if (mask & (1 << nxt)) continue;
                int newMask = mask | (1 << nxt);
                long long newCost = cur + cost[last][nxt];
                if (newCost < dp[newMask][nxt]) {
                    dp[newMask][nxt] = newCost;
                }
            }
        }
    }

    long long bestTotal = INF;
    for (int last = 0; last < n; ++last) {
        long long cur = dp[fullMask][last];
        if (cur == INF) continue;
        long long total = cur + cost[last][0];
        if (total < bestTotal) bestTotal = total;
    }

    std::vector<std::vector<long long>> extra(1 << n, std::vector<long long>(n, -1));
    std::function<long long(int, int)> extraCost = [&](int mask, int last) -> long long {
        if (extra[mask][last] != -1) return extra[mask][last];
        if (mask == fullMask) {
            extra[mask][last] = cost[last][0];
            return extra[mask][last];
        }
        long long best = INF;
        for (int nxt = 0; nxt < n; ++nxt) {
            if (mask & (1 << nxt)) continue;
            long long cand = cost[last][nxt] + extraCost(mask | (1 << nxt), nxt);
            if (cand < best) best = cand;
        }
        extra[mask][last] = best;
        return best;
    };

    std::vector<int> perm;
    perm.push_back(0);
    int mask = 1 << 0;
    int last = 0;
    while (mask != fullMask) {
        for (int nxt = 0; nxt < n; ++nxt) {
            if (mask & (1 << nxt)) continue;
            long long cur = dp[mask][last];
            long long candTotal = cur + cost[last][nxt] + extraCost(mask | (1 << nxt), nxt);
            if (candTotal == bestTotal) {
                perm.push_back(nxt);
                mask |= 1 << nxt;
                last = nxt;
                break;
            }
        }
    }
    return perm;
}

