int maxPointsInsideSquare(const std::vector<std::pair<long long, long long>>& points, const std::vector<std::string>& s) {
    size_t n = points.size();
    struct Item { long long d; std::string tag; };
    std::vector<Item> arr;
    arr.reserve(n);
    for (size_t i = 0; i < n; ++i) {
        long long x = points[i].first;
        long long y = points[i].second;
        long long d = std::max(std::llabs(x), std::llabs(y));
        arr.push_back({d, s[i]});
    }
    std::sort(arr.begin(), arr.end(), [](const Item& a, const Item& b) { return a.d < b.d; });
    std::unordered_set<std::string> seen;
    int count = 0;
    size_t i = 0;
    while (i < n) {
        long long curD = arr[i].d;
        std::unordered_set<std::string> groupTags;
        size_t j = i;
        while (j < n && arr[j].d == curD) {
            const std::string& tag = arr[j].tag;
            if (seen.find(tag) != seen.end() || groupTags.find(tag) != groupTags.end()) {
                return count;
            }
            groupTags.insert(tag);
            ++j;
        }
        for (const auto& t : groupTags) {
            seen.insert(t);
        }
        count += static_cast<int>(groupTags.size());
        i = j;
    }
    return count;
}

