long long sumDigitDifferences(const std::vector<long long>& nums) {
    long long n = static_cast<long long>(nums.size());
    if (n < 2) return 0;

    int digitCount = static_cast<int>(std::to_string(nums[0]).size());
    long long totalSum = 0;

    for (int pos = 0; pos < digitCount; ++pos) {
        long long freq[10] = {0};
        long long divisor = 1;
        for (int i = 0; i < digitCount - 1 - pos; ++i) {
            divisor *= 10;
        }

        for (long long i = 0; i < n; ++i) {
            int digit = static_cast<int>((nums[i] / divisor) % 10);
            ++freq[digit];
        }

        long long totalPairs = n * (n - 1) / 2;
        long long sameDigitPairs = 0;
        for (int d = 0; d < 10; ++d) {
            sameDigitPairs += freq[d] * (freq[d] - 1) / 2;
        }

        long long diffDigitPairs = totalPairs - sameDigitPairs;
        totalSum += diffDigitPairs;
    }

    return totalSum;
}

