int minBalancedPartitions(const std::string& s) {
    int n = s.size();
    const int INF = 1000000000;
    std::vector<int> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        int cnt[26] = {0};
        int maxFreq = 0;
        for (int j = i - 1; j >= 0; --j) {
            int idx = s[j] - 'a';
            ++cnt[idx];
            if (cnt[idx] > maxFreq) maxFreq = cnt[idx];
            bool balanced = true;
            for (int k = 0; k < 26; ++k) {
                if (cnt[k] != 0 && cnt[k] != maxFreq) {
                    balanced = false;
                    break;
                }
            }
            if (balanced) {
                dp[i] = std::min(dp[i], dp[j] + 1);
            }
        }
    }
    return dp[n];
}

