int maxScore(const std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    if (m == 0) return -1;
    int n = grid[0].size();
    if (m < 2 || n < 2) return -1;
    std::vector<std::vector<int>> minUpTo(m, std::vector<int>(n, 0));
    minUpTo[0][0] = grid[0][0];
    for (int j = 1; j < n; ++j) {
        minUpTo[0][j] = std::min(minUpTo[0][j - 1], grid[0][j]);
    }
    for (int i = 1; i < m; ++i) {
        minUpTo[i][0] = std::min(minUpTo[i - 1][0], grid[i][0]);
    }
    for (int i = 1; i < m; ++i) {
        for (int j = 1; j < n; ++j) {
            minUpTo[i][j] = std::min({grid[i][j], minUpTo[i - 1][j], minUpTo[i][j - 1]});
        }
    }
    int ans = INT_MIN;
    for (int i = 1; i < m; ++i) {
        for (int j = 1; j < n; ++j) {
            ans = std::max(ans, grid[i][j] - minUpTo[i - 1][j - 1]);
        }
    }
    return ans > 0 ? ans : -1;
}

