std::vector<bool> getResults(const std::vector<std::vector<int>>& queries) {
    std::set<int> occupied;
    std::vector<bool> results;
    for (const auto& q : queries) {
        if (q[0] == 1) {
            occupied.insert(q[1]);
        } else {
            int x = q[1];
            int l = q[2];
            if (x == 0) {
                results.push_back(false);
                continue;
            }
            auto it = occupied.lower_bound(x);
            int prev = -1;
            if (it != occupied.begin()) {
                --it;
                prev = *it;
            }
            int maxLen = x - prev;
            results.push_back(maxLen >= l);
        }
    }
    return results;
}

