std::vector<int> findDistinctColors(int limit, const std::vector<std::pair<int, int>>& queries) {
    std::unordered_map<int, int> ballColor;
    std::unordered_map<int, int> colorCount;
    std::vector<int> result;
    result.reserve(queries.size());

    for (const auto& q : queries) {
        int ball = q.first;
        int newColor = q.second;

        auto itBall = ballColor.find(ball);
        if (itBall != ballColor.end()) {
            int oldColor = itBall->second;
            auto itOldCnt = colorCount.find(oldColor);
            if (itOldCnt != colorCount.end()) {
                int oldCnt = itOldCnt->second - 1;
                if (oldCnt == 0) {
                    colorCount.erase(itOldCnt);
                } else {
                    itOldCnt->second = oldCnt;
                }
            }
        }

        ballColor[ball] = newColor;
        auto itNewCnt = colorCount.find(newColor);
        if (itNewCnt != colorCount.end()) {
            itNewCnt->second += 1;
        } else {
            colorCount.emplace(newColor, 1);
        }

        result.push_back(static_cast<int>(colorCount.size()));
    }

    return result;
}

