const long long MOD = 1000000007LL;
const long long NEG = -(1LL << 60);

struct Matrix {
    long long m[2][2];
    Matrix(long long a = 0, long long b = 0, long long c = 0, long long d = 0) {
        m[0][0] = a; m[0][1] = b;
        m[1][0] = c; m[1][1] = d;
    }
};

Matrix multiply(const Matrix& A, const Matrix& B) {
    Matrix C(NEG, NEG, NEG, NEG);
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            long long best = NEG;
            for (int k = 0; k < 2; ++k) {
                if (A.m[i][k] == NEG || B.m[k][j] == NEG) continue;
                best = max(best, A.m[i][k] + B.m[k][j]);
            }
            C.m[i][j] = best;
        }
    }
    return C;
}

class SegmentTree {
public:
    int n;
    vector<Matrix> tree;
    SegmentTree(const vector<int>& arr) {
        n = arr.size();
        tree.assign(4 * n, Matrix());
        build(1, 0, n - 1, arr);
    }
    void update(int idx, int val) {
        update(1, 0, n - 1, idx, val);
    }
    Matrix queryAll() const {
        return tree[1];
    }
private:
    void build(int node, int l, int r, const vector<int>& arr) {
        if (l == r) {
            long long a = arr[l];
            tree[node] = Matrix(0, 0, a, NEG);
            return;
        }
        int mid = (l + r) >> 1;
        build(node << 1, l, mid, arr);
        build(node << 1 | 1, mid + 1, r, arr);
        tree[node] = multiply(tree[node << 1 | 1], tree[node << 1]);
    }
    void update(int node, int l, int r, int idx, int val) {
        if (l == r) {
            long long a = val;
            tree[node] = Matrix(0, 0, a, NEG);
            return;
        }
        int mid = (l + r) >> 1;
        if (idx <= mid) update(node << 1, l, mid, idx, val);
        else update(node << 1 | 1, mid + 1, r, idx, val);
        tree[node] = multiply(tree[node << 1 | 1], tree[node << 1]);
    }
};

int maximumSumQueries(vector<int> nums, vector<vector<int>> queries) {
    SegmentTree seg(nums);
    long long total = 0;
    for (const auto& q : queries) {
        int pos = q[0];
        int x = q[1];
        seg.update(pos, x);
        Matrix root = seg.queryAll();
        long long ans = max(root.m[0][0], root.m[1][0]);
        total = (total + ans) % MOD;
    }
    return static_cast<int>(total);
}

