std::string clearDigits(const std::string& s) {
    std::vector<char> stack;
    auto isDigit = [](char ch) { return ch >= '0' && ch <= '9'; };
    for (size_t i = 0; i < s.size(); ++i) {
        char ch = s[i];
        if (isDigit(ch) && !stack.empty() && !isDigit(stack.back())) {
            stack.pop_back();
        } else {
            stack.push_back(ch);
        }
    }
    return std::string(stack.begin(), stack.end());
}

#include <bits/stdc++.h>

int maximumLength(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    k = std::min(k, n); // safety, though constraints already ensure this
    std::vector<std::unordered_map<int, int>> dp(k + 1);
    std::vector<int> best(k + 1, 0);

    for (int x : nums) {
        for (int t = k; t >= 0; --t) {
            int cur = 0;
            auto it = dp[t].find(x);
            if (it != dp[t].end()) cur = it->second;

            int cand = cur + 1;                // extend same value
            if (t > 0) {
                cand = std::max(cand, best[t - 1] + 1); // start new block
            }
            cand = std::max(cand, 1);          // start fresh subsequence

            if (cand > cur) {
                dp[t][x] = cand;
                if (cand > best[t]) best[t] = cand;
            }
        }
    }

    int answer = 0;
    for (int t = 0; t <= k; ++t) {
        answer = std::max(answer, best[t]);
    }
    return answer;
}

