int maxLengthGoodSubsequence(const vector<int>& nums, int k) {
    vector<unordered_map<int, int>> dp(k + 1);
    for (int x : nums) {
        vector<unordered_map<int, int>> old = dp;
        dp[0][x] = max(dp[0][x], 1);
        for (int c = 0; c <= k; ++c) {
            for (const auto& p : old[c]) {
                int v = p.first;
                int len = p.second;
                int nc = c + (v != x);
                if (nc <= k) {
                    int& ref = dp[nc][x];
                    ref = max(ref, len + 1);
                }
            }
        }
    }
    int ans = 0;
    for (int c = 0; c <= k; ++c) {
        for (const auto& p : dp[c]) {
            ans = max(ans, p.second);
        }
    }
    return ans;
}

