long long maxTotalDamage(const std::vector<int>& power) {
    std::unordered_map<int, int> freq;
    for (int d : power) {
        ++freq[d];
    }

    std::vector<int> values;
    values.reserve(freq.size());
    for (const auto& p : freq) {
        values.push_back(p.first);
    }
    std::sort(values.begin(), values.end());

    size_t m = values.size();
    if (m == 0) return 0;

    std::vector<long long> dp(m, 0);

    for (size_t i = 0; i < m; ++i) {
        int dmg = values[i];
        long long gain = static_cast<long long>(dmg) * freq[dmg];

        int lo = 0, hi = static_cast<int>(i) - 1, j = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (values[mid] <= dmg - 3) {
                j = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        long long take = gain + (j >= 0 ? dp[j] : 0);
        long long skip = i > 0 ? dp[i - 1] : 0;
        dp[i] = take > skip ? take : skip;
    }

    return dp[m - 1];
}

