using std::vector;

class Fenwick {
public:
    Fenwick(int n) : bit(n + 1, 0) {}
    void add(int idx, int delta) {
        ++idx; // 1‑based
        for (int i = idx; i < (int)bit.size(); i += i & -i)
            bit[i] += delta;
    }
    int sumPrefix(int idx) const {
        ++idx;
        int res = 0;
        for (int i = idx; i > 0; i -= i & -i)
            res += bit[i];
        return res;
    }
    int rangeSum(int l, int r) const {
        if (l > r) return 0;
        return sumPrefix(r) - (l ? sumPrefix(l - 1) : 0);
    }
private:
    vector<int> bit;
};

vector<int> countPeaks(vector<int>& nums, vector<vector<int>>& queries) {
    int n = nums.size();
    Fenwick ft(n);
    vector<char> isPeak(n, 0);
    auto compute = [&](int i) -> char {
        if (i <= 0 || i >= n - 1) return 0;
        return (nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) ? 1 : 0;
    };
    for (int i = 1; i < n - 1; ++i) {
        isPeak[i] = compute(i);
        if (isPeak[i]) ft.add(i, 1);
    }
    vector<int> answer;
    for (const auto& q : queries) {
        int type = q[0];
        if (type == 1) {
            int l = q[1];
            int r = q[2];
            int left = l + 1;
            int right = r - 1;
            answer.push_back(ft.rangeSum(left, right));
        } else if (type == 2) {
            int pos = q[1];
            int val = q[2];
            nums[pos] = val;
            for (int i = pos - 1; i <= pos + 1; ++i) {
                if (i <= 0 || i >= n - 1) continue;
                char newPeak = compute(i);
                if (newPeak != isPeak[i]) {
                    ft.add(i, newPeak - isPeak[i]);
                    isPeak[i] = newPeak;
                }
            }
        }
    }
    return answer;
}

