}

#include <bits/stdc++.h>
int countPermutations(int n, std::vector<std::vector<int>>& requirements) {
    const int MOD = 1000000007;
    std::vector<int> reqCnt(n, -1);
    int maxCnt = 0;
    for (const auto& r : requirements) {
        int endi = r[0];
        int cnti = r[1];
        reqCnt[endi] = cnti;
        if (cnti > maxCnt) maxCnt = cnti;
    }
    // DP table: dp[i][k] = number of permutations of length i with k inversions
    std::vector<std::vector<int>> dp(n + 1, std::vector<int>(maxCnt + 1, 0));
    dp[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        // prefix sums of dp[i-1]
        std::vector<int> pref(maxCnt + 1, 0);
        pref[0] = dp[i - 1][0];
        for (int k = 1; k <= maxCnt; ++k) {
            pref[k] = pref[k - 1] + dp[i - 1][k];
            if (pref[k] >= MOD) pref[k] -= MOD;
        }
        for (int k = 0; k <= maxCnt; ++k) {
            int left = k - (i - 1);
            long long val = pref[k];
            if (left > 0) {
                val -= pref[left - 1];
                if (val < 0) val += MOD;
            }
            dp[i][k] = (int)val;
        }
        int endIdx = i - 1;
        if (reqCnt[endIdx] != -1) {
            int need = reqCnt[endIdx];
            // If need exceeds possible inversions for this prefix, answer is 0.
            if (need > endIdx * (endIdx + 1) / 2) {
                return 0;
            }
            for (int k = 0; k <= maxCnt; ++k) {
                if (k != need) dp[i][k] = 0;
            }
        }
    }
    int finalNeed = reqCnt[n - 1];
    if (finalNeed == -1) return 0;
    return dp[n][finalNeed];
}

