int maxHeight(int red, int blue) {
    long long total = static_cast<long long>(red) + static_cast<long long>(blue);
    long long low = 0, high = 1;
    while (high * (high + 1) / 2 <= total) ++high;
    while (low < high) {
        long long mid = (low + high + 1) / 2;
        long long oddRows = (mid + 1) / 2;          // ceil(mid/2)
        long long evenRows = mid / 2;               // floor(mid/2)
        long long oddBalls = oddRows * oddRows;     // sum of first oddRows odd numbers
        long long evenBalls = evenRows * (evenRows + 1); // sum of first evenRows even numbers
        bool ok = (static_cast<long long>(red) >= oddBalls && static_cast<long long>(blue) >= evenBalls) ||
                  (static_cast<long long>(blue) >= oddBalls && static_cast<long long>(red) >= evenBalls);
        if (ok) low = mid;
        else high = mid - 1;
    }
    return static_cast<int>(low);
}

