long long countSubarrays(const std::vector<int>& nums, int k) {
    long long answer = 0;
    std::vector<std::pair<int, long long>> prev;
    for (int x : nums) {
        std::vector<std::pair<int, long long>> cur;
        cur.emplace_back(x, 1);
        for (const auto& p : prev) {
            int newVal = p.first & x;
            auto& last = cur.back();
            if (newVal == last.first) {
                last.second += p.second;
            } else {
                cur.emplace_back(newVal, p.second);
            }
        }
        for (const auto& p : cur) {
            if (p.first == k) {
                answer += p.second;
            }
        }
        prev = std::move(cur);
    }
    return answer;
}

