std::vector<std::string> generateBinaryStrings(int n) {
    std::vector<std::string> result;
    std::function<void(int, bool, const std::string&)> dfs = [&](int pos, bool prevZero, const std::string& cur) {
        if (pos == n) {
            result.push_back(cur);
            return;
        }
        if (!prevZero) {
            dfs(pos + 1, true, cur + '0');
        }
        dfs(pos + 1, false, cur + '1');
    };
    dfs(0, false, "");
    return result;
}

class Solution {
public:
    int numberOfSubmatrices(vector<vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        // rowX[j]/rowY[j]: running count of X/Y in the submatrix from (0,0) to (current row, j)
        vector<int> rowX(n, 0), rowY(n, 0);
        int ans = 0;
        for (int i = 0; i < m; i++) {
            int cx = 0, cy = 0; // running count within THIS row up to column j
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'X') cx++;
                else if (grid[i][j] == 'Y') cy++;
                rowX[j] += cx;
                rowY[j] += cy;
                if (rowX[j] > 0 && rowX[j] == rowY[j]) ans++;
            }
        }
        return ans;
    }
};

