int numberOfAlternatingGroups(std::vector<int>& colors, int k) {
    int n = static_cast<int>(colors.size());
    std::vector<int> ext(2 * n);
    for (int i = 0; i < n; ++i) {
        ext[i] = colors[i];
        ext[i + n] = colors[i];
    }
    int m = static_cast<int>(ext.size());
    std::vector<int> diff(m - 1);
    for (int i = 0; i < m - 1; ++i) {
        diff[i] = (ext[i] != ext[i + 1]) ? 1 : 0;
    }
    int need = k - 1;
    int sum = 0;
    for (int i = 0; i < need; ++i) {
        sum += diff[i];
    }
    int ans = 0;
    if (sum == need) ++ans;
    for (int start = 1; start < n; ++start) {
        sum -= diff[start - 1];
        sum += diff[start + need - 1];
        if (sum == need) ++ans;
    }
    return ans;
}

