ListNode* deleteNodes(const std::vector<int>& nums, ListNode* head) {
    std::unordered_set<int> toDelete(nums.begin(), nums.end());

    ListNode dummy(0);
    dummy.next = head;
    ListNode* prev = &dummy;
    ListNode* curr = head;

    while (curr != nullptr) {
        if (toDelete.find(curr->val) != toDelete.end()) {
            prev->next = curr->next;
        } else {
            prev = curr;
        }
        curr = curr->next;
    }

    return dummy.next;
}

int minimumLength(string s) {
    unordered_map<char,int> freq;
    for (char c : s) freq[c]++;
    int total = 0;
    for (auto& kv : freq) {
        int f = kv.second;
        if (f <= 2) total += f;
        else total += (f % 2 == 1) ? 1 : 2;
    }
    return total;
}

class Solution {
public:
    int minChanges(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> d(k + 2, 0);
        for (int i = 0; i < n / 2; i++) {
            int x = nums[i], y = nums[n - 1 - i];
            if (x > y) swap(x, y);
            d[0] += 1;
            d[y - x] -= 1;
            d[y - x + 1] += 1;
            int idx = max(y, k - x) + 1;
            d[idx] += 1;
        }
        int ans = n, s = 0;
        for (int v : d) {
            s += v;
            ans = min(ans, s);
        }
        return ans;
    }
};

