int number_of_bit_changes(int n, int k) {
    if ((n & k) != k) {
        return -1;
    }
    int diff = n ^ k;
    int changes = 0;
    while (diff) {
        diff &= diff - 1;
        ++changes;
    }
    return changes;
}

