long long countNotSpecial(long long l, long long r) {
    long long total = r - l + 1;

    long long low = static_cast<long long>(std::ceil(std::sqrt(static_cast<long double>(l))));
    long long high = static_cast<long long>(std::floor(std::sqrt(static_cast<long double>(r))));
    if (low > high) return total;

    std::vector<bool> isPrime(high + 1, true);
    if (high >= 0) isPrime[0] = false;
    if (high >= 1) isPrime[1] = false;
    long long limit = static_cast<long long>(std::floor(std::sqrt(static_cast<long double>(high))));
    for (long long i = 2; i <= limit; ++i) {
        if (isPrime[i]) {
            for (long long j = i * i; j <= high; j += i) {
                isPrime[j] = false;
            }
        }
    }

    long long primeSquareCount = 0;
    for (long long p = low; p <= high; ++p) {
        if (isPrime[p]) ++primeSquareCount;
    }

    return total - primeSquareCount;
}

