struct DSU {
    std::vector<int> parent;
    std::vector<int> rank;
    DSU(int n) : parent(n), rank(n, 0) {
        std::iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (rank[a] < rank[b]) std::swap(a, b);
        parent[b] = a;
        if (rank[a] == rank[b]) ++rank[a];
    }
};

bool isPathPossible(int xCorner, int yCorner, const std::vector<std::vector<int>>& circles) {
    int n = static_cast<int>(circles.size());
    int leftIdx = n;
    int rightIdx = n + 1;
    int bottomIdx = n + 2;
    int topIdx = n + 3;
    DSU dsu(n + 4);

    for (int i = 0; i < n; ++i) {
        long long x = circles[i][0];
        long long y = circles[i][1];
        long long r = circles[i][2];

        if (x - r <= 0) dsu.unite(i, leftIdx);
        if (x + r >= static_cast<long long>(xCorner)) dsu.unite(i, rightIdx);
        if (y - r <= 0) dsu.unite(i, bottomIdx);
        if (y + r >= static_cast<long long>(yCorner)) dsu.unite(i, topIdx);
    }

    for (int i = 0; i < n; ++i) {
        long long xi = circles[i][0];
        long long yi = circles[i][1];
        long long ri = circles[i][2];
        for (int j = i + 1; j < n; ++j) {
            long long xj = circles[j][0];
            long long yj = circles[j][1];
            long long rj = circles[j][2];
            long long dx = xi - xj;
            long long dy = yi - yj;
            long long dist2 = dx * dx + dy * dy;
            long long radSum = ri + rj;
            if (dist2 <= radSum * radSum) {
                dsu.unite(i, j);
            }
        }
    }

    if (dsu.find(leftIdx) == dsu.find(rightIdx)) return false;
    if (dsu.find(bottomIdx) == dsu.find(topIdx)) return false;
    if (dsu.find(leftIdx) == dsu.find(bottomIdx)) return false;
    if (dsu.find(rightIdx) == dsu.find(topIdx)) return false;
    return true;
}

