int minFlips(std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    std::vector<std::vector<char>> visited(m, std::vector<char>(n, 0));
    std::vector<int> sizes;
    std::vector<int> onesCount;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (visited[i][j]) continue;
            std::vector<std::pair<int,int>> cells;
            int xs[4] = {i, i, m - 1 - i, m - 1 - i};
            int ys[4] = {j, n - 1 - j, j, n - 1 - j};
            for (int k = 0; k < 4; ++k) {
                int x = xs[k];
                int y = ys[k];
                if (!visited[x][y]) {
                    visited[x][y] = 1;
                    cells.emplace_back(x, y);
                }
            }
            int sz = cells.size();
            int ones = 0;
            for (auto &p : cells) {
                ones += grid[p.first][p.second];
            }
            sizes.push_back(sz);
            onesCount.push_back(ones);
        }
    }
    const long long INF = (1LL << 60);
    std::array<long long, 4> dp, ndp;
    dp.fill(INF);
    dp[0] = 0;
    for (size_t idx = 0; idx < sizes.size(); ++idx) {
        int sz = sizes[idx];
        int ones = onesCount[idx];
        long long cost0 = ones;
        long long cost1 = sz - ones;
        ndp.fill(INF);
        for (int mod = 0; mod < 4; ++mod) {
            if (dp[mod] == INF) continue;
            ndp[mod] = std::min(ndp[mod], dp[mod] + cost0);
            int nmod = (mod + sz) % 4;
            ndp[nmod] = std::min(ndp[nmod], dp[mod] + cost1);
        }
        dp = ndp;
    }
    return static_cast<int>(dp[0]);
}

