std::vector<double> shortest_distance_after_road_addition_queries_ii(int n, const std::vector<std::pair<int, int>>& queries) {
    std::vector<std::vector<int>> adj(n);
    std::vector<double> results;
    const double INF = std::numeric_limits<double>::infinity();
    for (const auto& q : queries) {
        int l = q.first;
        int r = q.second;
        adj[l].push_back(r);
        std::vector<double> dist(n, INF);
        dist[0] = 0.0;
        for (int i = 0; i < n; ++i) {
            if (i + 1 < n && dist[i] + 1.0 < dist[i + 1]) {
                dist[i + 1] = dist[i] + 1.0;
            }
            for (int to : adj[i]) {
                if (dist[i] + 1.0 < dist[to]) {
                    dist[to] = dist[i] + 1.0;
                }
            }
        }
        results.push_back(dist[n - 1]);
    }
    return results;
}

