int snakePosition(int n, const std::vector<std::string>& commands) {
    int row = 0, col = 0;
    for (size_t i = 0; i < commands.size(); ++i) {
        const std::string& cmd = commands[i];
        if (cmd == "UP") {
            --row;
        } else if (cmd == "DOWN") {
            ++row;
        } else if (cmd == "LEFT") {
            --col;
        } else if (cmd == "RIGHT") {
            ++col;
        }
    }
    return row * n + col;
}

