int countGoodNodes(const std::vector<std::vector<int>>& edges) {
    int n = static_cast<int>(edges.size()) + 1;
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int a = e[0];
        int b = e[1];
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    int good = 0;

    std::function<int(int, int)> dfs = [&](int u, int parent) -> int {
        std::vector<int> childSizes;
        for (int v : adj[u]) {
            if (v == parent) continue;
            int sz = dfs(v, u);
            childSizes.push_back(sz);
        }

        bool isGood = true;
        if (!childSizes.empty()) {
            int first = childSizes[0];
            for (size_t i = 1; i < childSizes.size(); ++i) {
                if (childSizes[i] != first) {
                    isGood = false;
                    break;
                }
            }
        }
        if (isGood) ++good;

        int total = 1;
        for (int s : childSizes) total += s;
        return total;
    };

    dfs(0, -1);
    return good;
}

