int find_smallest_missing_integer(const std::vector<int>& nums) {
    long long longest_prefix_sum = 0;
    int longest_prefix_length = 0;
    int n = static_cast<int>(nums.size());
    for (int i = 0; i < n; ++i) {
        long long current_prefix_sum = 0;
        int current_prefix_length = 0;
        for (int j = i; j < n; ++j) {
            if (j == i || nums[j] == nums[j - 1] + 1) {
                current_prefix_sum += nums[j];
                ++current_prefix_length;
            } else {
                break;
            }
        }
        if (current_prefix_length > longest_prefix_length) {
            longest_prefix_length = current_prefix_length;
            longest_prefix_sum = current_prefix_sum;
        }
    }
    std::unordered_set<int> num_set(nums.begin(), nums.end());
    long long smallest_missing_integer = longest_prefix_sum;
    while (num_set.find(static_cast<int>(smallest_missing_integer)) != num_set.end()) {
        ++smallest_missing_integer;
    }
    return static_cast<int>(smallest_missing_integer);
}

