class NeighborSum {
public:
    int n;
    std::vector<std::vector<int>> grid;
    std::unordered_map<int, std::pair<int,int>> pos;
    NeighborSum(std::vector<std::vector<int>>& g) : n((int)g.size()), grid(g) {
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) pos[grid[i][j]] = {i,j};
    }
    int adjacentSum(int value) {
        auto it = pos.find(value);
        if (it == pos.end()) return 0;
        auto [i,j] = it->second;
        int total = 0;
        if (i > 0) total += grid[i-1][j];
        if (i < n-1) total += grid[i+1][j];
        if (j > 0) total += grid[i][j-1];
        if (j < n-1) total += grid[i][j+1];
        return total;
    }
};

