int countMonotonicPairs(const std::vector<int>& nums) {
    const int MOD = 1000000007;
    const int MAX = 50;
    std::vector<int> dp(MAX + 1, 0);
    for (int v = 0; v <= nums[0]; ++v) dp[v] = 1;
    for (size_t i = 0; i + 1 < nums.size(); ++i) {
        int diff = nums[i + 1] - nums[i];
        int need = diff > 0 ? diff : 0;
        std::vector<int> pref(MAX + 1, 0);
        pref[0] = dp[0];
        for (int v = 1; v <= MAX; ++v) {
            pref[v] = (pref[v - 1] + dp[v]) % MOD;
        }
        std::vector<int> next(MAX + 1, 0);
        for (int v = 0; v <= nums[i + 1]; ++v) {
            int limit = v - need;
            if (limit >= 0) next[v] = pref[limit];
        }
        dp.swap(next);
    }
    int ans = 0;
    int last = nums.back();
    for (int v = 0; v <= last; ++v) {
        ans = (ans + dp[v]) % MOD;
    }
    return ans;
}

