long long countDominantOnes(const std::string& s) {
    std::size_t n = s.size();
    std::vector<int> prefOnes(n + 1, 0);
    std::vector<int> prefZeros(n + 1, 0);
    for (std::size_t i = 0; i < n; ++i) {
        prefOnes[i + 1] = prefOnes[i] + (s[i] == '1' ? 1 : 0);
        prefZeros[i + 1] = prefZeros[i] + (s[i] == '0' ? 1 : 0);
    }
    int maxZeros = static_cast<int>(std::floor(std::sqrt(static_cast<double>(n))));
    long long ans = 0;
    for (std::size_t r = 0; r < n; ++r) {
        for (std::size_t l = r + 1; l-- > 0;) {
            int zeros = prefZeros[r + 1] - prefZeros[l];
            if (zeros > maxZeros) break;
            int ones = prefOnes[r + 1] - prefOnes[l];
            if (ones >= zeros * zeros) ++ans;
        }
    }
    return ans;
}

