std::vector<int> shortestDistanceAfterRoadAdditionQueriesI(int n, const std::vector<std::vector<int>>& queries) {
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < n - 1; ++i) {
        adj[i].push_back(i + 1);
    }
    std::vector<int> result;
    for (const auto& q : queries) {
        int u = q[0];
        int v = q[1];
        adj[u].push_back(v);
        const int INF = std::numeric_limits<int>::max();
        std::vector<int> dist(n, INF);
        std::queue<int> que;
        dist[0] = 0;
        que.push(0);
        while (!que.empty()) {
            int cur = que.front();
            que.pop();
            int d = dist[cur];
            for (int nxt : adj[cur]) {
                if (dist[nxt] > d + 1) {
                    dist[nxt] = d + 1;
                    que.push(nxt);
                }
            }
        }
        result.push_back(dist[n - 1]);
    }
    return result;
}

