long long minOperations(const std::vector<int>& nums, const std::vector<int>& target) {
    std::size_t n = nums.size();
    long long prev = 0;
    long long ops = 0;
    for (std::size_t i = 0; i < n; ++i) {
        long long diff = static_cast<long long>(target[i]) - static_cast<long long>(nums[i]);
        long long delta = diff - prev;
        if (delta > 0) {
            ops += delta;
        }
        prev = diff;
    }
    return ops;
}

