std::vector<long long> alternatingGroups(std::vector<int> colors, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(colors.size());
    std::vector<int> diff(n);
    for (int i = 0; i < n; ++i) {
        diff[i] = (colors[i] != colors[(i + 1) % n]) ? 1 : 0;
    }
    std::vector<long long> result;
    for (const auto& q : queries) {
        if (q[0] == 1) {
            int k = q[1];
            int L = k - 1;
            long long ans = 0;
            int cur = 0;
            for (int i = 0; i < 2 * n; ++i) {
                int idx = i % n;
                if (diff[idx] == 1) {
                    ++cur;
                } else {
                    cur = 0;
                }
                if (cur >= L) {
                    int start = i - (L - 1);
                    if (start < n) ++ans;
                }
            }
            result.push_back(ans);
        } else {
            int i = q[1];
            int v = q[2];
            if (colors[i] == v) continue;
            colors[i] = v;
            int left = (i - 1 + n) % n;
            diff[left] = (colors[left] != colors[i]) ? 1 : 0;
            diff[i] = (colors[i] != colors[(i + 1) % n]) ? 1 : 0;
        }
    }
    return result;
}

