long long maximumValueSum(const std::vector<std::vector<int>>& board) {
    int m = board.size();
    int n = board[0].size();
    std::vector<std::vector<std::pair<int, long long>>> top(m);
    for (int i = 0; i < m; ++i) {
        std::vector<std::pair<int, long long>> cells;
        cells.reserve(n);
        for (int j = 0; j < n; ++j) {
            cells.emplace_back(j, static_cast<long long>(board[i][j]));
        }
        std::nth_element(cells.begin(), cells.begin() + std::min(3, n) - 1, cells.end(),
                         [](const auto& a, const auto& b) { return a.second > b.second; });
        int limit = std::min(3, n);
        top[i].assign(cells.begin(), cells.begin() + limit);
    }
    long long ans = LLONG_MIN;
    for (int i = 0; i < m; ++i) {
        for (int j = i + 1; j < m; ++j) {
            for (int k = j + 1; k < m; ++k) {
                for (const auto& a : top[i]) {
                    for (const auto& b : top[j]) {
                        if (b.first == a.first) continue;
                        for (const auto& c : top[k]) {
                            if (c.first == a.first || c.first == b.first) continue;
                            long long sum = a.second + b.second + c.second;
                            if (sum > ans) ans = sum;
                        }
                    }
                }
            }
        }
    }
    return ans;
}

