std::vector<int> findPowerOfKSizeSubarrays(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<int> result(n - k + 1);
    for (int i = 0; i <= n - k; ++i) {
        bool increasing = true;
        for (int j = i + 1; j < i + k; ++j) {
            if (nums[j] <= nums[j - 1]) {
                increasing = false;
                break;
            }
        }
        result[i] = increasing ? nums[i + k - 1] : -1;
    }
    return result;
}

