long long maximumValueSum(const std::vector<std::vector<int>>& board) {
    int m = static_cast<int>(board.size());
    int n = static_cast<int>(board[0].size());
    const long long NEG_INF = std::numeric_limits<long long>::min() / 4;
    long long answer = NEG_INF;

    if (m <= n) {
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                for (int k = j + 1; k < m; ++k) {
                    int rows[3] = {i, j, k};
                    std::vector<long long> dp(8, NEG_INF);
                    dp[0] = 0;
                    for (int col = 0; col < n; ++col) {
                        std::vector<long long> ndp = dp;
                        for (int mask = 0; mask < 8; ++mask) {
                            if (dp[mask] == NEG_INF) continue;
                            for (int r = 0; r < 3; ++r) {
                                if (mask & (1 << r)) continue;
                                int nmask = mask | (1 << r);
                                long long val = dp[mask] + static_cast<long long>(board[rows[r]][col]);
                                if (val > ndp[nmask]) ndp[nmask] = val;
                            }
                        }
                        dp.swap(ndp);
                    }
                    if (dp[7] > answer) answer = dp[7];
                }
            }
        }
    } else {
        for (int c1 = 0; c1 < n; ++c1) {
            for (int c2 = c1 + 1; c2 < n; ++c2) {
                for (int c3 = c2 + 1; c3 < n; ++c3) {
                    int cols[3] = {c1, c2, c3};
                    std::vector<long long> dp(8, NEG_INF);
                    dp[0] = 0;
                    for (int row = 0; row < m; ++row) {
                        std::vector<long long> ndp = dp;
                        for (int mask = 0; mask < 8; ++mask) {
                            if (dp[mask] == NEG_INF) continue;
                            for (int c = 0; c < 3; ++c) {
                                if (mask & (1 << c)) continue;
                                int nmask = mask | (1 << c);
                                long long val = dp[mask] + static_cast<long long>(board[row][cols[c]]);
                                if (val > ndp[nmask]) ndp[nmask] = val;
                            }
                        }
                        dp.swap(ndp);
                    }
                    if (dp[7] > answer) answer = dp[7];
                }
            }
        }
    }

    return answer;
}

#include <bits/stdc++.h>
#include <vector>

std::vector<int> powerOfKSizeSubarrays(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<int> inc(n, 0);
    for (int i = 1; i < n; ++i) {
        inc[i] = nums[i] > nums[i - 1] ? 1 : 0;
    }
    int sumInc = 0;
    for (int i = 1; i < k; ++i) {
        sumInc += inc[i];
    }
    std::vector<int> results;
    results.reserve(n - k + 1);
    int target = k - 1;
    for (int start = 0; start <= n - k; ++start) {
        if (sumInc == target) {
            results.push_back(nums[start + k - 1]);
        } else {
            results.push_back(-1);
        }
        if (start < n - k) {
            int removeIdx = start + 1;
            int addIdx = start + k;
            sumInc = sumInc - inc[removeIdx] + inc[addIdx];
        }
    }
    return results;
}

#include <bits/stdc++.h>
#include <vector>
#include <string>
#include <algorithm>

std::vector<long long> countKConstraintSubstrings(const std::string& s, int k, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(s.size());
    std::vector<int> r0(n), r1(n);
    int right = -1;
    int zeros = 0;
    for (int left = 0; left < n; ++left) {
        while (right + 1 < n && zeros + (s[right + 1] == '0' ? 1 : 0) <= k) {
            ++right;
            if (s[right] == '0') ++zeros;
        }
        r0[left] = right;
        if (right >= left) {
            if (s[left] == '0') --zeros;
        } else {
            right = left - 1;
        }
    }
    right = -1;
    int ones = 0;
    for (int left = 0; left < n; ++left) {
        while (right + 1 < n && ones + (s[right + 1] == '1' ? 1 : 0) <= k) {
            ++right;
            if (s[right] == '1') ++ones;
        }
        r1[left] = right;
        if (right >= left) {
            if (s[left] == '1') --ones;
        } else {
            right = left - 1;
        }
    }
    std::vector<int> maxGood(n);
    for (int i = 0; i < n; ++i) {
        maxGood[i] = std::max(r0[i], r1[i]);
    }
    struct Fenwick {
        int n;
        std::vector<long long> bit;
        Fenwick(int size) : n(size), bit(size + 1, 0) {}
        void add(int idx, long long delta) {
            for (int i = idx; i <= n; i += i & -i) bit[i] += delta;
        }
        long long sum(int idx) const {
            long long res = 0;
            for (int i = idx; i > 0; i -= i & -i) res += bit[i];
            return res;
        }
        long long rangeSum(int l, int r) const { // inclusive, 0‑based
            return sum(r + 1) - sum(l);
        }
    };
    Fenwick bitCnt(n), bitSum(n);
    struct Q { int l; int r; int idx; };
    std::vector<Q> qObjs;
    qObjs.reserve(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        qObjs.push_back({queries[i][0], queries[i][1], static_cast<int>(i)});
    }
    std::sort(qObjs.begin(), qObjs.end(), [](const Q& a, const Q& b) { return a.r < b.r; });
    std::vector<long long> ans(queries.size());
    int pos = 0;
    for (const Q& q : qObjs) {
        while (pos < n && maxGood[pos] <= q.r) {
            bitCnt.add(pos + 1, 1);
            bitSum.add(pos + 1, maxGood[pos]);
            ++pos;
        }
        long long len = static_cast<long long>(q.r) - q.l + 1;
        long long cntLe = bitCnt.rangeSum(q.l, q.r);
        long long sumLe = bitSum.rangeSum(q.l, q.r);
        long long cntGt = len - cntLe;
        long long sumMin = sumLe + static_cast<long long>(q.r) * cntGt;
        long long sumI = (static_cast<long long>(q.l) + q.r) * len / 2;
        ans[q.idx] = sumMin + len - sumI;
    }
    return ans;
}

