struct HeapNode {
    long long value;
    std::size_t index;
};

static void heapSwap(std::vector<HeapNode>& heap, std::size_t i, std::size_t j) {
    HeapNode tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

static bool heapLess(const HeapNode& a, const HeapNode& b) {
    if (a.value != b.value) return a.value < b.value;
    return a.index < b.index;
}

static void heapifyUp(std::vector<HeapNode>& heap, std::size_t pos) {
    while (pos > 0) {
        std::size_t parent = (pos - 1) >> 1;
        if (heapLess(heap[pos], heap[parent])) {
            heapSwap(heap, pos, parent);
            pos = parent;
        } else {
            break;
        }
    }
}

static void heapifyDown(std::vector<HeapNode>& heap, std::size_t pos) {
    std::size_t size = heap.size();
    while (true) {
        std::size_t left = pos * 2 + 1;
        std::size_t right = left + 1;
        std::size_t smallest = pos;

        if (left < size && heapLess(heap[left], heap[smallest])) smallest = left;
        if (right < size && heapLess(heap[right], heap[smallest])) smallest = right;

        if (smallest != pos) {
            heapSwap(heap, pos, smallest);
            pos = smallest;
        } else {
            break;
        }
    }
}

std::vector<long long> finalArrayState(std::vector<long long> nums, long long k, long long multiplier) {
    std::size_t n = nums.size();
    if (n == 0) return {};

    std::vector<HeapNode> heap;
    heap.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        heap.push_back({nums[i], i});
        heapifyUp(heap, heap.size() - 1);
    }

    for (long long op = 0; op < k; ++op) {
        HeapNode& node = heap[0];
        node.value *= multiplier;
        nums[node.index] = node.value;
        heapifyDown(heap, 0);
    }

    return nums;
}

