int findKey(int num1, int num2, int num3) {
    std::string s1 = std::to_string(num1);
    std::string s2 = std::to_string(num2);
    std::string s3 = std::to_string(num3);
    if (s1.length() < 4) s1 = std::string(4 - s1.length(), '0') + s1;
    if (s2.length() < 4) s2 = std::string(4 - s2.length(), '0') + s2;
    if (s3.length() < 4) s3 = std::string(4 - s3.length(), '0') + s3;
    std::string keyStr;
    keyStr.reserve(4);
    for (int i = 0; i < 4; ++i) {
        int d1 = s1[i] - '0';
        int d2 = s2[i] - '0';
        int d3 = s3[i] - '0';
        int minDigit = std::min(d1, std::min(d2, d3));
        keyStr.push_back('0' + minDigit);
    }
    return std::stoi(keyStr);
}

#include <bits/stdc++.h>

long long countPairs(const std::vector<int>& nums) {
    auto trimLeadingZeros = [](const std::string& s) -> std::string {
        std::size_t pos = s.find_first_not_of('0');
        if (pos == std::string::npos) return "0";
        return s.substr(pos);
    };

    auto canTransform = [&](const std::string& from, const std::string& to) -> bool {
        int n = static_cast<int>(from.size());
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                std::string swapped = from;
                std::swap(swapped[i], swapped[j]);
                if (trimLeadingZeros(swapped) == to) return true;
            }
        }
        return false;
    };

    auto canBecomeEqual = [&](int a, int b) -> bool {
        std::string sa = std::to_string(a);
        std::string sb = std::to_string(b);
        if (sa == sb) return true;
        if (canTransform(sa, sb)) return true;
        if (canTransform(sb, sa)) return true;
        return false;
    };

    long long ans = 0;
    int n = static_cast<int>(nums.size());
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (canBecomeEqual(nums[i], nums[j])) ++ans;
        }
    }
    return ans;
}

#include <bits/stdc++.h>

static std::unordered_set<int> generate(int num) {
    std::string s = std::to_string(num);
    int L = static_cast<int>(s.size());
    std::unordered_set<int> result;
    // original number
    {
        size_t pos = s.find_first_not_of('0');
        std::string trimmed = (pos == std::string::npos) ? "" : s.substr(pos);
        int val = trimmed.empty() ? 0 : std::stoi(trimmed);
        result.insert(val);
    }
    // one swap
    for (int i = 0; i < L; ++i) {
        for (int j = i + 1; j < L; ++j) {
            std::string t = s;
            std::swap(t[i], t[j]);
            size_t pos = t.find_first_not_of('0');
            std::string trimmed = (pos == std::string::npos) ? "" : t.substr(pos);
            int val = trimmed.empty() ? 0 : std::stoi(trimmed);
            result.insert(val);
        }
    }
    return result;
}

long long countAlmostEqualPairsII(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<std::unordered_set<int>> reachable(n);
    for (int i = 0; i < n; ++i) {
        reachable[i] = generate(nums[i]);
    }
    std::unordered_map<int, std::vector<int>> valueMap;
    for (int i = 0; i < n; ++i) {
        for (int v : reachable[i]) {
            valueMap[v].push_back(i);
        }
    }
    std::unordered_set<long long> seenPairs;
    long long ans = 0;
    for (const auto& kv : valueMap) {
        const std::vector<int>& arr = kv.second;
        int m = static_cast<int>(arr.size());
        for (int a = 0; a < m; ++a) {
            for (int b = a + 1; b < m; ++b) {
                int i = arr[a];
                int j = arr[b];
                long long code = static_cast<long long>(i) * n + j;
                if (seenPairs.insert(code).second) {
                    ++ans;
                }
            }
        }
    }
    return ans;
}

#include <bits/stdc++.h>

static long long modPow(long long base, long long exp, long long mod) {
    long long result = 1 % mod;
    long long b = base % mod;
    while (exp) {
        if (exp & 1) result = (result * b) % mod;
        b = (b * b) % mod;
        exp >>= 1;
    }
    return result;
}

std::vector<int> finalArrayState(std::vector<int> nums, long long k, int multiplier) {
    const long long MOD = 1000000007LL;
    std::size_t n = nums.size();
    if (multiplier == 1 || k == 0) {
        std::vector<int> res(n);
        for (std::size_t i = 0; i < n; ++i) {
            long long v = nums[i] % MOD;
            if (v < 0) v += MOD;
            res[i] = static_cast<int>(v);
        }
        return res;
    }

    std::vector<long long> cnt(n, 0);
    long double logM = std::log((long double)multiplier);
    std::vector<long double> key(n);
    for (std::size_t i = 0; i < n; ++i) {
        if (nums[i] == 0) {
            key[i] = -std::numeric_limits<long double>::infinity();
        } else {
            key[i] = std::log((long double)std::llabs((long long)nums[i])) + cnt[i] * logM;
            if (nums[i] < 0) key[i] = -key[i]; // preserve sign for ordering
        }
    }

    struct Node {
        long double key;
        std::size_t idx;
    };
    struct Compare {
        bool operator()(const Node& a, const Node& b) const {
            return a.key > b.key;
        }
    };
    std::priority_queue<Node, std::vector<Node>, Compare> pq;
    for (std::size_t i = 0; i < n; ++i) {
        pq.push({key[i], i});
    }

    for (long long step = 0; step < k; ++step) {
        Node cur = pq.top();
        pq.pop();
        std::size_t i = cur.idx;
        ++cnt[i];
        if (nums[i] == 0) {
            cur.key = -std::numeric_limits<long double>::infinity();
        } else {
            long double magnitude = std::log((long double)std::llabs((long long)nums[i])) + cnt[i] * logM;
            cur.key = (nums[i] < 0) ? -magnitude : magnitude;
        }
        pq.push({cur.key, i});
    }

    std::vector<int> result(n);
    for (std::size_t i = 0; i < n; ++i) {
        long long base = nums[i] % MOD;
        if (base < 0) base += MOD;
        long long mult = modPow(multiplier, cnt[i], MOD);
        long long val = (base * mult) % MOD;
        result[i] = static_cast<int>(val);
    }
    return result;
}

