std::vector<int> kthNearestObstacle(const std::vector<std::pair<int, int>>& queries, int k) {
    std::vector<int> heap;
    std::vector<int> results;
    auto swap = [&](size_t i, size_t j) {
        int t = heap[i];
        heap[i] = heap[j];
        heap[j] = t;
    };
    auto bubbleUp = [&](size_t idx) {
        size_t i = idx;
        while (i > 0) {
            size_t p = (i - 1) >> 1;
            if (heap[p] >= heap[i]) break;
            swap(p, i);
            i = p;
        }
    };
    auto bubbleDown = [&](size_t idx) {
        size_t i = idx;
        while (true) {
            size_t largest = i;
            size_t l = i * 2 + 1;
            size_t r = i * 2 + 2;
            if (l < heap.size() && heap[l] > heap[largest]) largest = l;
            if (r < heap.size() && heap[r] > heap[largest]) largest = r;
            if (largest == i) break;
            swap(i, largest);
            i = largest;
        }
    };
    auto push = [&](int val) {
        heap.push_back(val);
        bubbleUp(heap.size() - 1);
    };
    auto popMax = [&]() -> int {
        int max = heap[0];
        int end = heap.back();
        heap.pop_back();
        if (!heap.empty()) {
            heap[0] = end;
            bubbleDown(0);
        }
        return max;
    };
    auto peek = [&]() -> int {
        return heap[0];
    };
    for (const auto& p : queries) {
        int dist = std::abs(p.first) + std::abs(p.second);
        if (heap.size() < static_cast<size_t>(k)) {
            push(dist);
        } else if (dist < peek()) {
            popMax();
            push(dist);
        }
        results.push_back(heap.size() == static_cast<size_t>(k) ? peek() : -1);
    }
    return results;
}

