std::string hashDividedString(const std::string& s, int k) {
    int n = static_cast<int>(s.length());
    std::string result;
    result.reserve((n + k - 1) / k);
    for (int i = 0; i < n; i += k) {
        int sum = 0;
        for (int j = i; j < i + k; ++j) {
            sum += s[j] - 'a';
        }
        char hashedChar = static_cast<char>((sum % 26) + 'a');
        result.push_back(hashedChar);
    }
    return result;
}

