int maxScore(const std::vector<std::vector<int>>& grid) {
    int rows = static_cast<int>(grid.size());
    int cols = static_cast<int>(grid[0].size());
    int maxMask = 1 << cols;
    const int NEG = -INT_MAX;
    std::vector<int> dp(maxMask, NEG);
    dp[0] = 0;
    for (int i = 0; i < rows; ++i) {
        std::vector<int> ndp = dp; // skipping this row
        for (int mask = 0; mask < maxMask; ++mask) {
            if (dp[mask] == NEG) continue;
            for (int j = 0; j < cols; ++j) {
                if ((mask & (1 << j)) == 0) {
                    int nmask = mask | (1 << j);
                    ndp[nmask] = std::max(ndp[nmask], dp[mask] + grid[i][j]);
                }
            }
        }
        dp.swap(ndp);
    }
    int ans = 0;
    for (int mask = 1; mask < maxMask; ++mask) {
        ans = std::max(ans, dp[mask]);
    }
    return ans;
}

class Solution {
public:
    vector<int> maximumSubarrayXor(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        // f[i][j]: XOR score of nums[i..j] (repeated adjacent-XOR reduction), via the
        // Pascal's-triangle-style recurrence f[i][j] = f[i][j-1] ^ f[i+1][j]
        vector<vector<int>> f(n, vector<int>(n, 0)), dp(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) { f[i][i] = nums[i]; dp[i][i] = nums[i]; }
        for (int length = 2; length <= n; length++) {
            for (int i = 0; i + length - 1 < n; i++) {
                int j = i + length - 1;
                f[i][j] = f[i][j - 1] ^ f[i + 1][j];
                // dp[i][j] = best XOR score of any sub-subarray within [i,j]
                dp[i][j] = max({f[i][j], dp[i][j - 1], dp[i + 1][j]});
            }
        }
        vector<int> ans;
        for (auto& q : queries) ans.push_back(dp[q[0]][q[1]]);
        return ans;
    }
};

