long long countGoodIntegers(int n, int k) {
    vector<long long> fact(n+1, 1);
    for (int i = 2; i <= n; i++) fact[i] = fact[i-1]*i;

    long long answer = 0;
    vector<int> cnt(10, 0);

    function<void(int,int)> dfs = [&](int digit, int remaining) {
        if (digit == 10) {
            if (remaining != 0) return;
            int oddCnt = 0;
            for (int c : cnt) oddCnt += (c % 2);
            if (oddCnt > 1) return;

            int halfLen = n / 2;
            vector<int> halfCounts(10);
            for (int d = 0; d < 10; d++) halfCounts[d] = cnt[d] / 2;
            int middleDigit = -1;
            for (int d = 0; d < 10; d++) if (cnt[d] % 2 == 1) { middleDigit = d; break; }

            vector<int> halfPerm(halfLen);
            vector<int> used(10, 0);
            bool found = false;

            function<void(int)> backtrack = [&](int pos) {
                if (found) return;
                if (pos == halfLen) {
                    vector<int> digits = halfPerm;
                    if (middleDigit != -1) digits.push_back(middleDigit);
                    for (int i = halfLen-1; i >= 0; i--) digits.push_back(halfPerm[i]);
                    if (!digits.empty() && digits[0] == 0) return;
                    long long mod = 0;
                    for (int d : digits) mod = (mod*10 + d) % k;
                    if (mod == 0) {
                        long long total = fact[n];
                        for (int c : cnt) total /= fact[c];
                        if (cnt[0] > 0) {
                            long long leadingZero = fact[n-1];
                            leadingZero /= fact[cnt[0]-1];
                            for (int d = 1; d < 10; d++) leadingZero /= fact[cnt[d]];
                            total -= leadingZero;
                        }
                        answer += total;
                        found = true;
                    }
                    return;
                }
                for (int d = 0; d < 10; d++) {
                    if (used[d] < halfCounts[d]) {
                        used[d]++;
                        halfPerm[pos] = d;
                        backtrack(pos+1);
                        used[d]--;
                        if (found) return;
                    }
                }
            };
            backtrack(0);
            return;
        }
        for (int c = 0; c <= remaining; c++) {
            cnt[digit] = c;
            dfs(digit+1, remaining-c);
        }
        cnt[digit] = 0;
    };
    dfs(0, n);
    return answer;
}

#include <bits/stdc++.h>
int maxMoves(int kx, int ky, std::vector<std::vector<int>> positions) {
    const int N = 50;
    int p = (int)positions.size();
    std::vector<std::pair<int,int>> nodes;
    nodes.emplace_back(kx, ky);
    for (auto &pos : positions) nodes.emplace_back(pos[0], pos[1]);
    int m = p + 1;
    std::vector<std::vector<int>> dist(m, std::vector<int>(m, 0));
    int dx[8] = {2,2,1,1,-1,-1,-2,-2};
    int dy[8] = {1,-1,2,-2,2,-2,1,-1};
    for (int s = 0; s < m; ++s) {
        std::vector<std::vector<int>> d(N, std::vector<int>(N, -1));
        std::queue<std::pair<int,int>> q;
        int sx = nodes[s].first;
        int sy = nodes[s].second;
        d[sx][sy] = 0;
        q.emplace(sx, sy);
        while (!q.empty()) {
            int x = q.front().first;
            int y = q.front().second;
            q.pop();
            for (int dir = 0; dir < 8; ++dir) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];
                if (nx < 0 || ny < 0 || nx >= N || ny >= N) continue;
                if (d[nx][ny] == -1) {
                    d[nx][ny] = d[x][y] + 1;
                    q.emplace(nx, ny);
                }
            }
        }
        for (int t = 0; t < m; ++t) {
            int tx = nodes[t].first;
            int ty = nodes[t].second;
            dist[s][t] = d[tx][ty];
        }
    }
    int fullMask = (1 << p) - 1;
    std::vector<std::vector<int>> dp(1 << p, std::vector<int>(m, -1));
    std::function<int(int,int)> solve = [&](int mask, int cur) -> int {
        if (mask == fullMask) return 0;
        int &res = dp[mask][cur];
        if (res != -1) return res;
        bool aliceTurn = (__builtin_popcount(mask) % 2 == 0);
        if (aliceTurn) res = -1000000;
        else res = 1000000;
        for (int nxt = 1; nxt < m; ++nxt) {
            int bit = 1 << (nxt - 1);
            if (mask & bit) continue;
            int cost = dist[cur][nxt];
            int total = cost + solve(mask | bit, nxt);
            if (aliceTurn) res = std::max(res, total);
            else res = std::min(res, total);
        }
        return res;
    };
    return solve(0, 0);
}

#include <bits/stdc++.h>
int countOfPairs(std::vector<int> nums) {
    const int MOD = 1000000007;
    int n = nums.size();
    int maxVal = *std::max_element(nums.begin(), nums.end());
    std::vector<int> dp(maxVal + 1, 0), ndp(maxVal + 1, 0), pref(maxVal + 1, 0);
    for (int v = 0; v <= nums[0]; ++v) dp[v] = 1;
    for (int i = 1; i < n; ++i) {
        pref[0] = dp[0];
        for (int v = 1; v <= maxVal; ++v) {
            pref[v] = pref[v - 1] + dp[v];
            if (pref[v] >= MOD) pref[v] -= MOD;
        }
        int delta = nums[i] - nums[i - 1];
        if (delta < 0) delta = 0;
        std::fill(ndp.begin(), ndp.end(), 0);
        for (int v = 0; v <= nums[i]; ++v) {
            int limit = v - delta;
            if (limit >= 0) ndp[v] = pref[limit];
        }
        dp.swap(ndp);
    }
    long long ans = 0;
    for (int v = 0; v <= nums.back(); ++v) {
        ans += dp[v];
        if (ans >= MOD) ans -= MOD;
    }
    return (int)ans;
}

