int maxScore(std::vector<int> start, int d) {
    int n = static_cast<int>(start.size());
    std::vector<std::pair<std::int64_t, std::int64_t>> intervals;
    intervals.reserve(n);
    for (int i = 0; i < n; ++i) {
        std::int64_t l = start[i];
        std::int64_t r = static_cast<std::int64_t>(start[i]) + d;
        intervals.emplace_back(l, r);
    }
    std::sort(intervals.begin(), intervals.end(),
              [](const auto& a, const auto& b) { return a.first < b.first; });
    std::int64_t minL = intervals.front().first;
    std::int64_t maxR = intervals.back().second;
    std::int64_t lo = 0;
    std::int64_t hi = maxR - minL + 1; // exclusive upper bound

    auto feasible = [&](std::int64_t dist) -> bool {
        std::int64_t prev = intervals[0].first;
        for (int i = 1; i < n; ++i) {
            std::int64_t need = prev + dist;
            std::int64_t pos = intervals[i].first > need ? intervals[i].first : need;
            if (pos > intervals[i].second) return false;
            prev = pos;
        }
        return true;
    };

    while (lo < hi) {
        std::int64_t mid = lo + (hi - lo) / 2;
        if (feasible(mid)) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return static_cast<int>(lo - 1);
}

