int longestIncreasingPath(const std::vector<std::vector<int>>& coordinates, int k) {
    int n = static_cast<int>(coordinates.size());
    struct Point { int x; int y; int idx; };
    std::vector<Point> points;
    points.reserve(n);
    for (int i = 0; i < n; ++i) {
        points.push_back({coordinates[i][0], coordinates[i][1], i});
    }
    std::sort(points.begin(), points.end(), [](const Point& a, const Point& b) {
        if (a.x == b.x) return a.y > b.y;
        return a.x < b.x;
    });
    int targetPos = -1;
    for (int i = 0; i < n; ++i) {
        if (points[i].idx == k) {
            targetPos = i;
            break;
        }
    }
    std::vector<int> forward(n, 1);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (points[j].x < points[i].x && points[j].y < points[i].y) {
                if (forward[j] + 1 > forward[i]) forward[i] = forward[j] + 1;
            }
        }
    }
    std::vector<int> backward(n, 1);
    for (int i = n - 1; i >= 0; --i) {
        for (int j = n - 1; j > i; --j) {
            if (points[i].x < points[j].x && points[i].y < points[j].y) {
                if (backward[j] + 1 > backward[i]) backward[i] = backward[j] + 1;
            }
        }
    }
    return forward[targetPos] + backward[targetPos] - 1;
}

