bool canReachSafe(const std::vector<std::vector<int>>& grid, int health) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());

    const int INF = std::numeric_limits<int>::max();
    std::vector<std::vector<int>> dist(m, std::vector<int>(n, INF));
    std::deque<std::pair<int, int>> dq;

    dist[0][0] = grid[0][0];
    dq.push_front({0, 0});

    const int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    while (!dq.empty()) {
        std::pair<int, int> cur = dq.front();
        dq.pop_front();
        int x = cur.first;
        int y = cur.second;

        for (const auto& d : dirs) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx < 0 || ny < 0 || nx >= m || ny >= n) continue;

            int newCost = dist[x][y] + grid[nx][ny];
            if (newCost < dist[nx][ny]) {
                dist[nx][ny] = newCost;
                if (grid[nx][ny] == 0) {
                    dq.push_front({nx, ny});
                } else {
                    dq.push_back({nx, ny});
                }
            }
        }
    }

    return dist[m - 1][n - 1] <= health - 1;
}

