long long minimumSeconds(long long mountainHeight, const std::vector<long long>& workerTimes) {
    long long minTime = *std::min_element(workerTimes.begin(), workerTimes.end());
    long double highEst = (long double)minTime * (long double)mountainHeight * (long double)(mountainHeight + 1) / 2.0L;
    long long low = 0;
    long long high = (long long)highEst;
    while (low < high) {
        long long mid = low + (high - low) / 2;
        long long total = 0;
        for (long long t : workerTimes) {
            if (t == 0) continue;
            long long val = (2 * mid) / t;
            long double disc = 1.0L + 4.0L * (long double)val;
            long long x = (long long)((std::sqrt(disc) - 1.0L) / 2.0L);
            while ((long double)t * x * (x + 1) / 2.0L > (long double)mid) --x;
            while ((long double)t * (x + 1) * (x + 2) / 2.0L <= (long double)mid) ++x;
            total += x;
            if (total >= mountainHeight) break;
        }
        if (total >= mountainHeight) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

#include <bits/stdc++.h>

int minValidStrings(const std::vector<std::string>& words, const std::string& target) {
    std::unordered_set<std::string> pref;
    pref.reserve(200000);
    size_t maxLen = 0;
    for (const std::string& w : words) {
        for (size_t l = 1; l <= w.size(); ++l) {
            pref.insert(w.substr(0, l));
        }
        if (w.size() > maxLen) maxLen = w.size();
    }

    const int n = static_cast<int>(target.size());
    const int INF = n + 5;
    std::vector<int> dp(n + 1, INF);
    dp[n] = 0;

    for (int i = n - 1; i >= 0; --i) {
        for (size_t l = 1; l <= maxLen && i + static_cast<int>(l) <= n; ++l) {
            std::string sub = target.substr(i, l);
            if (pref.find(sub) != pref.end()) {
                if (dp[i + static_cast<int>(l)] + 1 < dp[i]) {
                    dp[i] = dp[i + static_cast<int>(l)] + 1;
                }
            }
        }
    }

    return dp[0] >= INF ? -1 : dp[0];
}

