long long minElementAfterDigitSum(const std::vector<long long>& nums) {
    long long minValue = std::numeric_limits<long long>::max();
    for (size_t i = 0; i < nums.size(); ++i) {
        long long x = nums[i];
        long long digitSum = 0;
        while (x > 0) {
            digitSum += x % 10;
            x /= 10;
        }
        if (digitSum < minValue) {
            minValue = digitSum;
        }
    }
    return minValue;
}

#include <bits/stdc++.h>
long long countSubstrings(const std::string& word1, const std::string& word2) {
    int n = static_cast<int>(word1.size());
    int m = static_cast<int>(word2.size());
    if (m > n) return 0LL;
    std::vector<int> need(26, 0), have(26, 0);
    for (char c : word2) need[c - 'a']++;
    int missing = 0;
    for (int v : need) missing += v;
    long long ans = 0;
    int R = 0;
    for (int L = 0; L < n; ++L) {
        while (R < n && missing > 0) {
            int idx = word1[R] - 'a';
            if (have[idx] < need[idx]) missing--;
            have[idx]++;
            ++R;
        }
        if (missing == 0) {
            ans += static_cast<long long>(n - (R - 1));
        } else {
            break;
        }
        int idxL = word1[L] - 'a';
        if (have[idxL] <= need[idxL]) missing++;
        have[idxL]--;
    }
    return ans;
}

#include <bits/stdc++.h>
std::vector<int> getLexicographicallySmallestValidSequence(const std::string& word1, const std::string& word2) {
    int n = (int)word1.size();
    int m = (int)word2.size();
    if (m == 0) return {};
    struct State {
        bool reachable = false;
        std::vector<int> seq;
    };
    std::vector<std::vector<State>> dp(m + 1, std::vector<State>(2));
    dp[0][0].reachable = true; // empty sequence
    for (int idx = 0; idx < n; ++idx) {
        // iterate backwards to avoid using the same idx multiple times
        for (int i = m - 1; i >= 0; --i) {
            for (int err = 0; err <= 1; ++err) {
                if (!dp[i][err].reachable) continue;
                int lastPos = -1;
                if (!dp[i][err].seq.empty()) lastPos = dp[i][err].seq.back();
                if (lastPos >= idx) continue; // must be increasing
                int newErr = err + (word1[idx] != word2[i] ? 1 : 0);
                if (newErr > 1) continue;
                std::vector<int> cand = dp[i][err].seq;
                cand.push_back(idx);
                if (!dp[i + 1][newErr].reachable ||
                    std::lexicographical_compare(cand.begin(), cand.end(),
                                                dp[i + 1][newErr].seq.begin(),
                                                dp[i + 1][newErr].seq.end())) {
                    dp[i + 1][newErr].reachable = true;
                    dp[i + 1][newErr].seq = std::move(cand);
                }
            }
        }
    }
    std::vector<int> best;
    bool found = false;
    for (int err = 0; err <= 1; ++err) {
        if (!dp[m][err].reachable) continue;
        if (!found || std::lexicographical_compare(dp[m][err].seq.begin(), dp[m][err].seq.end(),
                                                    best.begin(), best.end())) {
            best = dp[m][err].seq;
            found = true;
        }
    }
    if (!found) return {};
    return best;
}

#include <bits/stdc++.h>

long long countSubstrings(const std::string& word1, const std::string& word2) {
    int n = static_cast<int>(word1.size());
    int m = static_cast<int>(word2.size());
    if (m > n) return 0;
    int need[26] = {0};
    for (char c : word2) need[c - 'a']++;
    int cur[26] = {0};
    int deficit = 0;
    for (int i = 0; i < 26; ++i) if (need[i] > 0) ++deficit;
    long long ans = 0;
    int r = 0;
    for (int l = 0; l < n; ++l) {
        while (r < n && deficit > 0) {
            int idx = word1[r] - 'a';
            ++cur[idx];
            if (need[idx] > 0 && cur[idx] == need[idx]) --deficit;
            ++r;
        }
        if (deficit > 0) break;
        ans += static_cast<long long>(n - r + 1);
        int idxL = word1[l] - 'a';
        if (need[idxL] > 0 && cur[idxL] == need[idxL]) ++deficit;
        --cur[idxL];
    }
    return ans;
}

