char kthCharacter(long long k) {
    if (k <= 0) return '\0';
    long long len = 1;
    while (len < k) len <<= 1;
    std::function<char(long long, long long)> solve = [&](long long pos, long long curLen) -> char {
        if (curLen == 1) return 'a';
        long long half = curLen >> 1;
        if (pos <= half) return solve(pos, half);
        char c = solve(pos - half, half);
        return c == 'z' ? 'a' : c + 1;
    };
    return solve(k, len);
}

