long long max_total_height(std::vector<int> maximum_height) {
    std::sort(maximum_height.rbegin(), maximum_height.rend());
    long long prev = std::numeric_limits<long long>::max();
    long long total = 0;
    for (int h : maximum_height) {
        long long cur = std::min<long long>(h, prev - 1);
        if (cur <= 0) {
