char kthCharacter(long long k, const std::vector<int>& operations) {
    int n = static_cast<int>(operations.size());
    unsigned long long len = 1ULL;
    for (int i = 0; i < n; ++i) {
        if (len > ULLONG_MAX / 2) {
            len = ULLONG_MAX;
        } else {
            len <<= 1;
        }
    }
    int shift = 0;
    for (int i = n - 1; i >= 0; --i) {
        unsigned long long half = len >> 1;
        if (static_cast<unsigned long long>(k) > half) {
            k -= static_cast<long long>(half);
            if (operations[i] == 1) {
                shift = (shift + 1) % 26;
            }
        }
        len = half;
    }
    return static_cast<char>('a' + shift);
}

