long long count_vowel_consonant_substrings(const std::string& word, int k) {
    std::unordered_set<char> vowels = {'a', 'e', 'i', 'o', 'u'};
    int n = static_cast<int>(word.size());

    std::vector<int> prefC(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        char ch = word[i];
        prefC[i + 1] = prefC[i] + (vowels.count(ch) ? 0 : 1);
    }

    std::unordered_map<char, int> last;
    for (char v : vowels) {
        last[v] = -1;
    }

    std::unordered_map<int, std::vector<int>> positions;
    positions[0].push_back(0);

    long long ans = 0;

    for (int i = 0; i < n; ++i) {
        char ch = word[i];
        if (vowels.count(ch)) {
            last[ch] = i;
        }

        int min_last = INT_MAX;
        for (char v : vowels) {
            min_last = std::min(min_last, last[v]);
        }

        if (min_last != -1) {
            int target = prefC[i + 1] - k;
            auto it = positions.find(target);
            if (it != positions.end()) {
                const std::vector<int>& arr = it->second;
                int cnt = static_cast<int>(std::upper_bound(arr.begin(), arr.end(), min_last) - arr.begin());
                ans += cnt;
            }
        }

        positions[prefC[i + 1]].push_back(i + 1);
    }

    return ans;
}

#include <bits/stdc++.h>

long long countVowelConsonantSubstrings(const std::string& word, int k) {
    int n = static_cast<int>(word.size());
    auto vowelIndex = [&](char c) -> int {
        switch (c) {
            case 'a': return 0;
            case 'e': return 1;
            case 'i': return 2;
            case 'o': return 3;
            case 'u': return 4;
            default: return -1;
        }
    };

    std::vector<int> latest(5, -1);
    int leftAtMostK = 0, leftAtMostKm1 = 0;
    int cntConK = 0, cntConKm1 = 0;
    long long answer = 0;

    for (int r = 0; r < n; ++r) {
        int vIdx = vowelIndex(word[r]);
        if (vIdx == -1) { // consonant
            ++cntConK;
            ++cntConKm1;
        } else {
            latest[vIdx] = r;
        }

        while (cntConK > k) {
            if (vowelIndex(word[leftAtMostK]) == -1) --cntConK;
            ++leftAtMostK;
        }

        if (k > 0) {
            while (cntConKm1 > k - 1) {
                if (vowelIndex(word[leftAtMostKm1]) == -1) --cntConKm1;
                ++leftAtMostKm1;
            }
        }

        int minPos = n;
        for (int i = 0; i < 5; ++i) {
            if (latest[i] == -1) {
                minPos = -1;
                break;
            }
            if (latest[i] < minPos) minPos = latest[i];
        }

        long long cntAtMostK = 0, cntAtMostKm1 = 0;
        if (minPos >= leftAtMostK) cntAtMostK = static_cast<long long>(minPos - leftAtMostK + 1);
        if (k > 0 && minPos >= leftAtMostKm1) cntAtMostKm1 = static_cast<long long>(minPos - leftAtMostKm1 + 1);

        answer += cntAtMostK - cntAtMostKm1;
    }

    return answer;
}

