std::vector<int> removeMethods(int n, int k, const std::vector<std::pair<int, int>>& invocations) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& p : invocations) {
        adj[p.first].push_back(p.second);
    }

    std::unordered_set<int> suspicious;
    std::vector<int> stack;
    stack.push_back(k);
    while (!stack.empty()) {
        int cur = stack.back();
        stack.pop_back();
        if (suspicious.find(cur) != suspicious.end()) continue;
        suspicious.insert(cur);
        for (int nxt : adj[cur]) {
            if (suspicious.find(nxt) == suspicious.end()) {
                stack.push_back(nxt);
            }
        }
    }

    for (const auto& p : invocations) {
        if (suspicious.find(p.first) == suspicious.end() && suspicious.find(p.second) != suspicious.end()) {
            std::vector<int> all;
            all.reserve(n);
            for (int i = 0; i < n; ++i) all.push_back(i);
            return all;
        }
    }

    std::vector<int> remaining;
    remaining.reserve(n);
    for (int i = 0; i < n; ++i) {
        if (suspicious.find(i) == suspicious.end()) remaining.push_back(i);
    }
    return remaining;
}

