std::vector<int> constructMinimumBitwiseArray(const std::vector<int>& nums) {
    std::vector<int> ans(nums.size());
    for (size_t i = 0; i < nums.size(); ++i) {
        int p = nums[i];
        if (p % 2 == 0) {
            ans[i] = -1;
            continue;
        }
        int temp = p;
        int t = 0;
        while ((temp & 1) == 1) {
            ++t;
            temp >>= 1;
        }
        int x = p - (1 << (t - 1));
        ans[i] = x;
    }
    return ans;
}

