unsigned long long maxBinaryConcat(const std::vector<int>& nums) {
    std::vector<int> bitLen(3);
    for (std::size_t i = 0; i < 3; ++i) {
        int v = nums[i];
        if (v == 0) {
            bitLen[i] = 1;
        } else {
            bitLen[i] = static_cast<int>(std::floor(std::log2(v))) + 1;
        }
    }

    const int perms[6][3] = {
        {0, 1, 2}, {0, 2, 1},
        {1, 0, 2}, {1, 2, 0},
        {2, 0, 1}, {2, 1, 0}
    };

    unsigned long long best = 0;
    for (int p = 0; p < 6; ++p) {
        unsigned long long a = static_cast<unsigned long long>(nums[perms[p][0]]);
        unsigned long long b = static_cast<unsigned long long>(nums[perms[p][1]]);
        unsigned long long c = static_cast<unsigned long long>(nums[perms[p][2]]);
        int lenB = bitLen[perms[p][1]];
        int lenC = bitLen[perms[p][2]];
        unsigned long long val = ((a << lenB) | b) << lenC | c;
        if (val > best) best = val;
    }
    return best;
}

vector<vector<int>> tryBuild(int n, int H, int W, int corner, int X, int Y,
                              vector<vector<int>>& adj) {
    vector<vector<int>> grid(H, vector<int>(W, -1));
    vector<char> placed(n, 0);
    grid[0][0] = corner; placed[corner] = 1;
    grid[0][1] = X; placed[X] = 1;
    grid[1][0] = Y; placed[Y] = 1;

    auto commonNeighbor = [&](int a, int b, int exclude) -> int {
        unordered_set<int> sa(adj[a].begin(), adj[a].end());
        for (int x : adj[b]) if (x != exclude && sa.count(x)) return x;
        return -1;
    };
    auto unplacedNeighbor = [&](int a) -> int {
        for (int x : adj[a]) if (!placed[x]) return x;
        return -1;
    };

    for (int d = 2; d <= H + W - 2; ++d) {
        for (int i = max(1, d - W + 1); i <= min(d, H - 1); ++i) {
            int j = d - i;
            if (j < 1 || j > W - 1) continue;
            int val = commonNeighbor(grid[i-1][j], grid[i][j-1], grid[i-1][j-1]);
            if (val == -1) return {};
            grid[i][j] = val; placed[val] = 1;
        }
        if (d <= W - 1) {
            int val = unplacedNeighbor(grid[0][d-1]);
            if (val == -1) return {};
            grid[0][d] = val; placed[val] = 1;
        }
        if (d <= H - 1) {
            int val = unplacedNeighbor(grid[d-1][0]);
            if (val == -1) return {};
            grid[d][0] = val; placed[val] = 1;
        }
    }
    return grid;
}

vector<vector<int>> constructGrid(int n, const vector<pair<int,int>>& edges) {
    vector<vector<int>> adj(n);
    vector<int> deg(n, 0);
    for (auto& e : edges) { adj[e.first].push_back(e.second); adj[e.second].push_back(e.first); deg[e.first]++; deg[e.second]++; }
    int degCount[5] = {0,0,0,0,0};
    for (int d : deg) if (d <= 4) degCount[d]++;
    int limit = (int)sqrt((double)n);
    int H = -1, W = -1;
    for (int h = 1; h <= limit; ++h) {
        if (n % h != 0) continue;
        int w = n / h;
        if (h == 1 && w == 1) continue;
        int expect[5] = {0,0,0,0,0};
        if (h == 1 || w == 1) { expect[1] = 2; expect[2] = n - 2; }
        else { expect[2] = 4; expect[3] = 2*(h-2)+2*(w-2); expect[4] = (h-2)*(w-2); }
        bool ok = true;
        for (int d = 0; d <= 4; ++d) if (degCount[d] != expect[d]) { ok = false; break; }
        if (ok) { H = h; W = w; break; }
    }
    if (H == -1) throw runtime_error("Input graph is not a rectangular grid");
    if (H == 1 || W == 1) {
        vector<char> placed(n, 0);
        int start = -1;
        for (int i = 0; i < n; ++i) if (deg[i] == 1) { start = i; break; }
        vector<int> path; path.push_back(start); placed[start] = 1;
        int cur = start;
        while ((int)path.size() < n) {
            int nxt = -1;
            for (int x : adj[cur]) if (!placed[x]) { nxt = x; break; }
            path.push_back(nxt); placed[nxt] = 1; cur = nxt;
        }
        if (H == 1) return {path};
        vector<vector<int>> res;
        for (int x : path) res.push_back({x});
        return res;
    }
    int corner = -1;
    for (int i = 0; i < n; ++i) if (deg[i] == 2) { corner = i; break; }
    int A = adj[corner][0], B = adj[corner][1];
    auto result = tryBuild(n, H, W, corner, A, B, adj);
    if (result.empty()) result = tryBuild(n, H, W, corner, B, A, adj);
    if (result.empty()) throw runtime_error("Could not construct grid");
    return result;
}

