std::vector<long long> xSumAllKLongSubarrays(const std::vector<int>& nums, int k, int x) {
    int n = static_cast<int>(nums.size());
    std::vector<long long> result;
    if (k > n) return result;
    for (int i = 0; i <= n - k; ++i) {
        std::unordered_map<int, int> freq;
        for (int j = i; j < i + k; ++j) {
            int v = nums[j];
            ++freq[v];
        }
        std::vector<std::pair<int, int>> entries;
        entries.reserve(freq.size());
        for (const auto& p : freq) {
            entries.emplace_back(p.first, p.second);
        }
        std::sort(entries.begin(), entries.end(),
            [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
                if (a.second != b.second) return a.second > b.second;
                return a.first > b.first;
            });
        int limit = std::min(x, static_cast<int>(entries.size()));
        long long sum = 0;
        for (int t = 0; t < limit; ++t) {
            sum += static_cast<long long>(entries[t].first) * entries[t].second;
        }
        result.push_back(sum);
    }
    return result;
}

