struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int kthLargestPerfectSubtree(TreeNode* root, int k) {
    std::vector<int> sizes;

    struct Info {
        bool isPerfect;
        int height;
        int size;
    };

    std::function<Info(TreeNode*)> dfs = [&](TreeNode* node) -> Info {
        if (node == nullptr) {
            return {true, -1, 0};
        }
        Info leftInfo = dfs(node->left);
        Info rightInfo = dfs(node->right);
        bool isPerf = leftInfo.isPerfect && rightInfo.isPerfect && leftInfo.height == rightInfo.height;
        int h = std::max(leftInfo.height, rightInfo.height) + 1;
        int sz = isPerf ? ((1 << (h + 1)) - 1) : std::max(leftInfo.size, rightInfo.size);
        if (isPerf) {
            sizes.push_back(sz);
        }
        return {isPerf, h, sz};
    };

    dfs(root);
    std::sort(sizes.begin(), sizes.end(), std::greater<int>());
    if (k <= 0 || k > static_cast<int>(sizes.size())) {
        return -1;
    }
    return sizes[k - 1];
}

#include <bits/stdc++.h>
std::vector<int> sortedGCDPairQueries(const std::vector<int>& nums, const std::vector<int>& queries) {
    int n = nums.size();
    int maxVal = 0;
    for (int v : nums) if (v > maxVal) maxVal = v;
    std::vector<int> freq(maxVal + 1, 0);
    for (int v : nums) ++freq[v];
    std::vector<int> cntDiv(maxVal + 1, 0);
    for (int d = 1; d <= maxVal; ++d) {
        for (int m = d; m <= maxVal; m += d) {
            cntDiv[d] += freq[m];
        }
    }
    std::vector<long long> exact(maxVal + 1, 0);
    for (int d = maxVal; d >= 1; --d) {
        long long total = 1LL * cntDiv[d] * (cntDiv[d] - 1) / 2;
        for (int m = d * 2; m <= maxVal; m += d) {
            total -= exact[m];
        }
        exact[d] = total;
    }
    std::vector<long long> prefix(maxVal + 1, 0);
    for (int d = 1; d <= maxVal; ++d) {
        prefix[d] = prefix[d - 1] + exact[d];
    }
    std::vector<int> answer;
    answer.reserve(queries.size());
    for (int q : queries) {
        long long target = (long long)q + 1;
        auto it = std::lower_bound(prefix.begin() + 1, prefix.end(), target);
        int d = static_cast<int>(it - prefix.begin());
        answer.push_back(d);
    }
    return answer;
}

#include <bits/stdc++.h>

int maxRemovals(const std::string& source, const std::string& pattern, const std::vector<int>& targetIndices) {
    int n = static_cast<int>(source.size());
    int m = static_cast<int>(pattern.size());
    std::vector<bool> deletable(n, false);
    for (int idx : targetIndices) {
        if (idx >= 0 && idx < n) deletable[idx] = true;
    }
    const int INF = 1e9;
    std::vector<int> prev(m + 1, INF), cur(m + 1, INF);
    prev[0] = 0;
    for (int i = 1; i <= n; ++i) {
        cur = prev; // skipping source[i-1]
        for (int j = 1; j <= m; ++j) {
            if (source[i - 1] == pattern[j - 1]) {
                int cost = prev[j - 1] + (deletable[i - 1] ? 1 : 0);
                if (cost < cur[j]) cur[j] = cost;
            }
        }
        prev.swap(cur);
    }
    int minNeeded = prev[m];
    int totalDeletable = static_cast<int>(targetIndices.size());
    return totalDeletable - minNeeded;
}

#include <bits/stdc++.h>
const int MOD = 1000000007;

int countWinningSequences(const std::string& s) {
    int n = s.size();
    int offset = n; // shift for zero score
    int range = 2 * n + 1;
    // map characters to indices: F=0, W=1, E=2
    auto idx = [&](char c) -> int {
        if (c == 'F') return 0;
        if (c == 'W') return 1;
        return 2; // 'E'
    };
    std::vector<int> alice(n);
    for (int i = 0; i < n; ++i) alice[i] = idx(s[i]);

    // win matrix: 1 if Bob beats Alice, -1 if loses, 0 if tie
    int win[3][3] = {};
    for (int b = 0; b < 3; ++b) {
        for (int a = 0; a < 3; ++a) {
            if (b == a) win[b][a] = 0;
            else if ((b == 0 && a == 2) || (b == 1 && a == 0) || (b == 2 && a == 1))
                win[b][a] = 1;
            else
                win[b][a] = -1;
        }
    }

    std::vector<std::vector<int>> dpPrev(4, std::vector<int>(range, 0));
    dpPrev[3][offset] = 1; // start with no previous move

    for (int i = 0; i < n; ++i) {
        std::vector<std::vector<int>> dpCurr(4, std::vector<int>(range, 0));
        for (int prev = 0; prev < 4; ++prev) {
            for (int sc = 0; sc < range; ++sc) {
                int ways = dpPrev[prev][sc];
                if (!ways) continue;
                for (int cur = 0; cur < 3; ++cur) {
                    if (prev != 3 && cur == prev) continue; // cannot repeat
                    int delta = win[cur][alice[i]];
                    int nsc = sc + delta;
                    if (nsc < 0 || nsc >= range) continue;
                    int &ref = dpCurr[cur][nsc];
                    ref += ways;
                    if (ref >= MOD) ref -= MOD;
                }
            }
        }
        dpPrev.swap(dpCurr);
    }

    long long ans = 0;
    for (int prev = 0; prev < 3; ++prev) {
        for (int sc = offset + 1; sc < range; ++sc) {
            ans += dpPrev[prev][sc];
            if (ans >= MOD) ans -= MOD;
        }
    }
    return (int)(ans % MOD);
}

