std::vector<long long> xSumOfKSubarrays(const std::vector<int>& nums, int k, int x) {
    int n = nums.size();
    std::vector<long long> result;
    for (int i = 0; i + k <= n; ++i) {
        std::unordered_map<int,int> freq;
        long long windowSum = 0;
        for (int j = i; j < i+k; ++j) { windowSum += nums[j]; freq[nums[j]]++; }
        if ((int)freq.size() <= x) { result.push_back(windowSum); continue; }
        std::vector<std::pair<int,int>> items(freq.begin(), freq.end()); // (val,cnt)
        std::sort(items.begin(), items.end(), [](const auto&a, const auto&b){
            if (a.second != b.second) return a.second > b.second;
            return a.first > b.first;
        });
        long long xsum = 0;
        for (int t = 0; t < x; ++t) xsum += (long long)items[t].first * items[t].second;
        result.push_back(xsum);
    }
    return result;
}

#include <bits/stdc++.h>
const int MOD = 1000000007;

long long modPow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int numberOfWays(int n, int x, int y) {
    int maxN = std::max(n, x);
    std::vector<long long> fact(maxN + 1), invFact(maxN + 1);
    fact[0] = 1;
    for (int i = 1; i <= maxN; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[maxN] = modPow(fact[maxN], MOD - 2);
    for (int i = maxN; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;

    auto C = [&](int N, int K) -> long long {
        if (K < 0 || K > N) return 0;
        return fact[N] * invFact[K] % MOD * invFact[N - K] % MOD;
    };

    std::vector<std::vector<long long>> S(n + 1, std::vector<long long>(n + 1, 0));
    S[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            S[i][j] = (j * S[i - 1][j] + S[i - 1][j - 1]) % MOD;
        }
    }

    long long ans = 0;
    int limit = std::min(n, x);
    for (int k = 1; k <= limit; ++k) {
        long long ways = C(x, k);                 // choose used stages
        ways = ways * fact[k] % MOD;               // assign subsets to stages (k!)
        ways = ways * S[n][k] % MOD;               // partition performers
        ways = ways * modPow(y, k) % MOD;          // scores for each used stage
        ans = (ans + ways) % MOD;
    }
    return (int)ans;
}

