int minimumOperations(std::vector<int> nums) {
    const int MAXV = 1000000;
    static std::vector<int> spfAll;
    if (spfAll.empty()) {
        spfAll.resize(MAXV + 1);
        for (int i = 0; i <= MAXV; ++i) spfAll[i] = i;
        for (int i = 2; i * i <= MAXV; ++i) {
            if (spfAll[i] == i) {
                for (int j = i * i; j <= MAXV; j += i) {
                    if (spfAll[j] == j) spfAll[j] = i;
                }
            }
        }
    }

    const int INF = 1e9;
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;

    int prevOrig = nums[0];
    int prevSpf = (nums[0] == 1) ? 1 : spfAll[nums[0]];
    bool prevHasSpf = (prevSpf != prevOrig);

    int dp0 = 0;                         // keep original value
    int dp1 = prevHasSpf ? 1 : INF;      // replace with smallest prime factor

    for (int i = 1; i < n; ++i) {
        int curOrig = nums[i];
        int curSpf = (nums[i] == 1) ? 1 : spfAll[nums[i]];
        bool curHasSpf = (curSpf != curOrig);

        int ndp0 = INF, ndp1 = INF;

        if (dp0 < INF) {
            if (prevOrig <= curOrig) ndp0 = std::min(ndp0, dp0);
            if (curHasSpf && prevOrig <= curSpf) ndp1 = std::min(ndp1, dp0 + 1);
        }
        if (dp1 < INF) {
            if (prevSpf <= curOrig) ndp0 = std::min(ndp0, dp1);
            if (curHasSpf && prevSpf <= curSpf) ndp1 = std::min(ndp1, dp1 + 1);
        }

        dp0 = ndp0;
        dp1 = ndp1;
        prevOrig = curOrig;
        prevSpf = curSpf;
    }

    int ans = std::min(dp0, dp1);
    return ans >= INF ? -1 : ans;
}

