long long countSubstringsWithKFrequency(const std::string& s, int k) {
    std::size_t n = s.size();
    long long totalSubstrings = static_cast<long long>(n) * (n + 1) / 2;
    if (k <= 1) return totalSubstrings;
    std::vector<int> freq(26, 0);
    std::size_t left = 0;
    long long badCount = 0;
    for (std::size_t right = 0; right < n; ++right) {
        int idx = s[right] - 'a';
        ++freq[idx];
        while (freq[idx] >= k) {
            int leftIdx = s[left] - 'a';
            --freq[leftIdx];
            ++left;
        }
        badCount += static_cast<long long>(right - left + 1);
    }
    return totalSubstrings - badCount;
}

