using std::vector; using std::string;
vector<bool> dfsStringsArePalindromes(const vector<int>& parent, const string& s) {
    int n = parent.size();
    vector<vector<int>> children(n);
    for (int i = 1; i < n; ++i) children[parent[i]].push_back(i);
    // children[] naturally in increasing index order already

    vector<int> postStart(n), postEnd(n);
    string seq;
    seq.reserve(n);
    std::function<void(int)> dfs = [&](int u) {
        postStart[u] = (int)seq.size();
        for (int v : children[u]) dfs(v);
        seq.push_back(s[u]);   // single post-order append, matches real dfs(x) definition
        postEnd[u] = (int)seq.size() - 1;
    };
    dfs(0);

    int m = seq.size(); // == n
    const long long mod1 = 1000000007LL, mod2 = 1000000009LL, base = 91138233LL % mod1;
    vector<long long> pow1(m+1), pow2(m+1);
    pow1[0]=pow2[0]=1;
    for (int i=1;i<=m;i++){ pow1[i]=(pow1[i-1]*base)%mod1; pow2[i]=(pow2[i-1]*base)%mod2; }
    vector<long long> pref1(m+1), pref2(m+1);
    for (int i=0;i<m;i++){ pref1[i+1]=(pref1[i]*base+seq[i])%mod1; pref2[i+1]=(pref2[i]*base+seq[i])%mod2; }
    string rev(seq.rbegin(), seq.rend());
    vector<long long> rpref1(m+1), rpref2(m+1);
    for (int i=0;i<m;i++){ rpref1[i+1]=(rpref1[i]*base+rev[i])%mod1; rpref2[i+1]=(rpref2[i]*base+rev[i])%mod2; }
    auto getHash = [&](const vector<long long>& pref, const vector<long long>& pw, int l, int r, long long mod)->long long {
        long long res = (pref[r+1] - pref[l]*pw[r-l+1]) % mod;
        if (res<0) res+=mod;
        return res;
    };
    vector<bool> answer(n);
    for (int i=0;i<n;i++){
        int l=postStart[i], r=postEnd[i];
        long long h1=getHash(pref1,pow1,l,r,mod1), h2=getHash(pref2,pow2,l,r,mod2);
        int rl=m-1-r, rr=m-1-l;
        long long rh1=getHash(rpref1,pow1,rl,rr,mod1), rh2=getHash(rpref2,pow2,rl,rr,mod2);
        answer[i] = (h1==rh1 && h2==rh2);
    }
    return answer;
}

#include <bits/stdc++.h>
#include <vector>

static long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static long long lcm_ll(long long a, long long b) {
    if (a == 0 || b == 0) return 0;
    return a / gcd_ll(a, b) * b;
}

long long maxFactorScore(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<long long> prefGcd(n);
    std::vector<long long> prefLcm(n);
    std::vector<long long> suffGcd(n);
    std::vector<long long> suffLcm(n);

    prefGcd[0] = nums[0];
    prefLcm[0] = nums[0];
    for (int i = 1; i < n; ++i) {
        prefGcd[i] = gcd_ll(prefGcd[i - 1], nums[i]);
        prefLcm[i] = lcm_ll(prefLcm[i - 1], nums[i]);
    }

    suffGcd[n - 1] = nums[n - 1];
    suffLcm[n - 1] = nums[n - 1];
    for (int i = n - 2; i >= 0; --i) {
        suffGcd[i] = gcd_ll(suffGcd[i + 1], nums[i]);
        suffLcm[i] = lcm_ll(suffLcm[i + 1], nums[i]);
    }

    long long best = prefLcm[n - 1] * prefGcd[n - 1];

    for (int i = 0; i < n; ++i) {
        long long leftGcd = (i > 0) ? prefGcd[i - 1] : 0;
        long long rightGcd = (i < n - 1) ? suffGcd[i + 1] : 0;
        long long curGcd;
        if (leftGcd == 0) curGcd = rightGcd;
        else if (rightGcd == 0) curGcd = leftGcd;
        else curGcd = gcd_ll(leftGcd, rightGcd);

        long long leftLcm = (i > 0) ? prefLcm[i - 1] : 1;
        long long rightLcm = (i < n - 1) ? suffLcm[i + 1] : 1;
        long long curLcm = lcm_ll(leftLcm, rightLcm);

        long long score = curLcm * curGcd;
        if (score > best) best = score;
    }

    return best;
}

