int countEqualGcdSubsequencePairs(const std::vector<int>& nums) {
    const int MOD = 1000000007;
    const int MAX = 200;
    auto gcd = [](int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    };
    std::vector<std::vector<std::uint32_t>> dp(MAX + 1, std::vector<std::uint32_t>(MAX + 1, 0));
    dp[0][0] = 1;
    for (int x : nums) {
        std::vector<std::vector<std::uint32_t>> ndp(MAX + 1, std::vector<std::uint32_t>(MAX + 1, 0));
        for (int a = 0; a <= MAX; ++a) {
            const std::vector<std::uint32_t>& row = dp[a];
            for (int b = 0; b <= MAX; ++b) {
                std::uint32_t cur = row[b];
                if (cur == 0) continue;
                ndp[a][b] = (ndp[a][b] + cur) % MOD;
                int na = (a == 0) ? x : gcd(a, x);
                ndp[na][b] = (ndp[na][b] + cur) % MOD;
                int nb = (b == 0) ? x : gcd(b, x);
                ndp[a][nb] = (ndp[a][nb] + cur) % MOD;
            }
        }
        dp.swap(ndp);
    }
    long long ans = 0;
    for (int g = 1; g <= MAX; ++g) {
        ans = (ans + dp[g][g]) % MOD;
    }
    return static_cast<int>(ans);
}

#include <bits/stdc++.h>

std::vector<int> findSubtreeSizes(const std::vector<int>& parent, const std::string& s) {
    int n = static_cast<int>(parent.size());
    std::vector<std::vector<int>> origChildren(n);
    for (int i = 1; i < n; ++i) {
        origChildren[parent[i]].push_back(i);
    }

    std::vector<int> newParent(n, -1);
    std::vector<int> last(26, -1);

    struct Frame {
        int node;
        size_t childIdx;
        int prevLast;
        bool entered;
    };
    std::vector<Frame> stack;
    stack.reserve(n);
    stack.push_back({0, 0, -1, false});

    while (!stack.empty()) {
        Frame &f = stack.back();
        if (!f.entered) {
            int ch = s[f.node] - 'a';
            int np = (last[ch] != -1 ? last[ch] : parent[f.node]);
            newParent[f.node] = np;
            f.prevLast = last[ch];
            last[ch] = f.node;
            f.entered = true;
        }
        if (f.childIdx < origChildren[f.node].size()) {
            int child = origChildren[f.node][f.childIdx++];
            stack.push_back({child, 0, -1, false});
        } else {
            int ch = s[f.node] - 'a';
            last[ch] = f.prevLast;
            stack.pop_back();
        }
    }

    std::vector<std::vector<int>> newChildren(n);
    for (int i = 1; i < n; ++i) {
        int p = newParent[i];
        if (p != -1) {
            newChildren[p].push_back(i);
        }
    }

    std::vector<int> answer(n, 1);
    std::vector<std::pair<int, bool>> st;
    st.reserve(2 * n);
    st.emplace_back(0, false);
    while (!st.empty()) {
        int u = st.back().first;
        bool visited = st.back().second;
        st.pop_back();
        if (!visited) {
            st.emplace_back(u, true);
            for (int v : newChildren[u]) {
                st.emplace_back(v, false);
            }
        } else {
            int sz = 1;
            for (int v : newChildren[u]) {
                sz += answer[v];
            }
            answer[u] = sz;
        }
    }
    return answer;
}

#include <bits/stdc++.h>
static const int MOD = 1000000007;

int originalStringCount(const std::string& word, int k) {
    int n = word.size();
    std::vector<int> groups;
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && word[j] == word[i]) ++j;
        groups.push_back(j - i);
        i = j;
    }
    long long totalWays = 1;
    for (int g : groups) {
        totalWays = (totalWays * g) % MOD;
    }

    std::vector<int> dp(k, 0), ndp(k, 0);
    dp[0] = 1; // zero groups, length 0

    for (int g : groups) {
        int limit = std::min(g, k - 1);
        std::vector<int> pref(k, 0);
        pref[0] = dp[0];
        for (int i = 1; i < k; ++i) {
            pref[i] = pref[i - 1] + dp[i];
            if (pref[i] >= MOD) pref[i] -= MOD;
        }
        ndp[0] = 0;
        for (int t = 1; t < k; ++t) {
            int left = t - limit;
            if (left < 0) left = 0;
            int sum = pref[t - 1];
            if (left > 0) {
                sum -= pref[left - 1];
                if (sum < 0) sum += MOD;
            }
            ndp[t] = sum;
        }
        dp.swap(ndp);
    }

    long long lessThanK = 0;
    for (int i = 0; i < k; ++i) {
        lessThanK += dp[i];
        if (lessThanK >= MOD) lessThanK -= MOD;
    }

    long long ans = (totalWays - lessThanK) % MOD;
    if (ans < 0) ans += MOD;
    return (int)ans;
}

