long long maxPoints(int n, int k, const std::vector<std::vector<long long>>& stayScore, const std::vector<std::vector<long long>>& travelScore) {
    if (k == 0) return 0;
    std::vector<long long> dpPrev(n);
    for (int c = 0; c < n; ++c) dpPrev[c] = stayScore[0][c];
    for (int day = 1; day < k; ++day) {
        std::vector<long long> dpCurr(n, std::numeric_limits<long long>::lowest());
        for (int c = 0; c < n; ++c) {
            long long stay = dpPrev[c] + stayScore[day][c];
            long long bestTravel = std::numeric_limits<long long>::lowest();
            for (int p = 0; p < n; ++p) {
                if (p == c) continue;
                long long cand = dpPrev[p] + travelScore[p][c];
                if (cand > bestTravel) bestTravel = cand;
            }
            dpCurr[c] = (stay > bestTravel) ? stay : bestTravel;
        }
        dpPrev = dpCurr;
    }
    long long answer = std::numeric_limits<long long>::lowest();
    for (int c = 0; c < n; ++c) if (dpPrev[c] > answer) answer = dpPrev[c];
    return answer;
}

