int totalLengthAfterTransformations(const std::string& s, int t) {
    const int MOD = 1000000007;
    std::vector<int> cnt(26, 0);
    for (size_t i = 0; i < s.size(); ++i) {
        int idx = s[i] - 'a';
        cnt[idx] = (cnt[idx] + 1) % MOD;
    }
    for (int step = 0; step < t; ++step) {
        std::vector<int> newCnt(26, 0);
        for (int i = 0; i < 26; ++i) {
            int val = cnt[i];
            if (val == 0) continue;
            if (i == 25) {
                newCnt[0] = static_cast<int>((newCnt[0] + static_cast<long long>(val) * 2) % MOD);
            } else {
                newCnt[i + 1] = (newCnt[i + 1] + val) % MOD;
            }
        }
        cnt.swap(newCnt);
    }
    int ans = 0;
    for (int i = 0; i < 26; ++i) {
        ans = (ans + cnt[i]) % MOD;
    }
    return ans;
}

