bool check(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    if (n < 2 * k) return false;
    std::vector<int> inc(n - 1, 0);
    for (int i = 0; i < n - 1; ++i) {
        inc[i] = (nums[i] < nums[i + 1]) ? 1 : 0;
    }
    std::vector<int> pref(n, 0);
    for (int i = 0; i < n - 1; ++i) {
        pref[i + 1] = pref[i] + inc[i];
    }
    for (int a = 0; a + 2 * k <= n; ++a) {
        int sum1 = pref[a + k - 1] - pref[a];
        int sum2 = pref[a + 2 * k - 1] - pref[a + k];
        if (sum1 == k - 1 && sum2 == k - 1) {
            return true;
        }
    }
    return false;
}

#include <bits/stdc++.h>

int maxFrequency(std::vector<int>& nums, int k, int numOperations) {
    if (k == 0) {
        std::unordered_map<int, int> cnt;
        int best = 0;
        for (int v : nums) {
            ++cnt[v];
            best = std::max(best, cnt[v]);
        }
        return best;
    }

    std::unordered_map<int, std::vector<long long>> groups;
    groups.reserve(nums.size() * 2);
    for (int v : nums) {
        int r = v % k;
        long long base = (v - r) / k;
        groups[r].push_back(base);
    }

    int answer = 0;
    for (auto& entry : groups) {
        std::vector<long long>& bases = entry.second;
        std::sort(bases.begin(), bases.end());
        long long sum = 0;
        std::size_t left = 0;
        for (std::size_t right = 0; right < bases.size(); ++right) {
            sum += bases[right];
            while (bases[right] * (right - left + 1) - sum > static_cast<long long>(numOperations)) {
                sum -= bases[left];
                ++left;
            }
            answer = std::max(answer, static_cast<int>(right - left + 1));
        }
    }
    return answer;
}

