int maxFrequencyAfterOperations(const std::vector<int>& nums, int k, int numOperations) {
    std::vector<int> sorted(nums);
    std::sort(sorted.begin(), sorted.end());
    std::unordered_map<int, int> freq;
    for (int v : nums) {
        ++freq[v];
    }
    int ans = 0;
    for (const auto& entry : freq) {
        int v = entry.first;
        int cntSame = entry.second;
        int left = std::lower_bound(sorted.begin(), sorted.end(), v - k) - sorted.begin();
        int right = std::upper_bound(sorted.begin(), sorted.end(), v + k) - sorted.begin() - 1;
        int intervalCount = (right >= left) ? (right - left + 1) : 0;
        int cntOther = intervalCount - cntSame;
        int possible = cntSame + std::min(numOperations, cntOther);
        if (possible > ans) ans = possible;
    }
    return ans;
}

