int max_adjacent_increasing_subarrays(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n < 2) {
        return 0;
    }
    std::vector<int> inc(n);
    inc[n - 1] = 1;
    for (int i = n - 2; i >= 0; --i) {
        inc[i] = (nums[i] < nums[i + 1]) ? inc[i + 1] + 1 : 1;
    }
    auto can = [&](int k) -> bool {
        int limit = n - 2 * k;
        if (limit < 0) return false;
        for (int i = 0; i <= limit; ++i) {
            if (inc[i] >= k && inc[i + k] >= k) {
                return true;
            }
        }
        return false;
    };
    int low = 0, high = n / 2;
    while (low < high) {
        int mid = (low + high + 1) / 2;
        if (can(mid)) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

int countValidSelections(vector<int>& nums) {
    int n = nums.size();
    vector<long long> prefix(n, 0), suffix(n, 0);
    for (int i = 1; i < n; i++) prefix[i] = prefix[i-1] + nums[i-1];
    for (int i = n-2; i >= 0; i--) suffix[i] = suffix[i+1] + nums[i+1];
    int ans = 0;
    for (int i = 0; i < n; i++) {
        if (nums[i] > 0) continue;
        long long diff = prefix[i] - suffix[i];
        if (diff == 0) ans += 2;
        else if (llabs(diff) == 1) ans += 1;
    }
    return ans;
}

