string smallestNumber(string num, long long k) {
    if (k == 1) return num;
    long long x = k;
    int need2=0, need3=0, need5=0, need7=0;
    while (x % 2 == 0) { x /= 2; need2++; }
    while (x % 3 == 0) { x /= 3; need3++; }
    while (x % 5 == 0) { x /= 5; need5++; }
    while (x % 7 == 0) { x /= 7; need7++; }
    if (x > 1) return "-1";

    long long prod = 1;
    for (char ch : num) { prod *= (ch - '0'); if (prod > (long long)1e18) break; }
    if (prod % k == 0) return num;

    int digitExp[10][4] = {};
    digitExp[1][0]=0;digitExp[1][1]=0;digitExp[1][2]=0;digitExp[1][3]=0;
    digitExp[2][0]=1; digitExp[3][1]=1; digitExp[4][0]=2; digitExp[5][2]=1;
    digitExp[6][0]=1; digitExp[6][1]=1; digitExp[7][3]=1; digitExp[8][0]=3; digitExp[9][1]=2;

    int sz2=need2+1, sz3=need3+1, sz5=need5+1, sz7=need7+1;
    long long total = (long long)sz2*sz3*sz5*sz7;
    const string INF = "#";
    vector<string> dp(total, INF);
    auto idx = [&](int a,int b,int c,int d){ return ((long long)((a*sz3+b))*sz5+c)*sz7+d; };
    dp[0] = "";
    for (int i2=0;i2<=need2;i2++)
    for (int i3=0;i3<=need3;i3++)
    for (int i5=0;i5<=need5;i5++)
    for (int i7=0;i7<=need7;i7++) {
        string cur = dp[idx(i2,i3,i5,i7)];
        if (cur == INF) continue;
        for (int d=2; d<=9; d++) {
            int ni2=min(need2,i2+digitExp[d][0]), ni3=min(need3,i3+digitExp[d][1]);
            int ni5=min(need5,i5+digitExp[d][2]), ni7=min(need7,i7+digitExp[d][3]);
            long long nxt = idx(ni2,ni3,ni5,ni7);
            string ns = cur + char('0'+d);
            sort(ns.begin(), ns.end());
            string& old = dp[nxt];
            if (old==INF || ns.size()<old.size() || (ns.size()==old.size() && ns<old)) old = ns;
        }
    }
    string ans = dp[idx(need2,need3,need5,need7)];
    if (ans == INF) return "-1";
    if ((int)ans.size() < (int)num.size() || ((int)ans.size()==(int)num.size() && ans < num)) {
        ans = string(num.size()-ans.size(), '1') + ans;
        sort(ans.begin(), ans.end());
    }
    return ans;
}

#include <bits/stdc++.h>

long long sumGoodSubsequences(const std::vector<int>& nums) {
    const long long MOD = 1000000007LL;
    if (nums.empty()) return 0;
    int maxVal = *std::max_element(nums.begin(), nums.end());
    std::vector<long long> cnt(maxVal + 3, 0), sum(maxVal + 3, 0);
    long long answer = 0;
    for (int a : nums) {
        long long leftCnt = (a > 0) ? cnt[a - 1] : 0;
        long long rightCnt = cnt[a + 1];
        long long leftSum = (a > 0) ? sum[a - 1] : 0;
        long long rightSum = sum[a + 1];
        long long addCnt = (1 + leftCnt + rightCnt) % MOD;
        long long addSum = ( (a % MOD) + (leftSum + rightSum) % MOD
                           + ( (a % MOD) * ((leftCnt + rightCnt) % MOD) ) % MOD ) % MOD;
        cnt[a] = (cnt[a] + addCnt) % MOD;
        sum[a] = (sum[a] + addSum) % MOD;
        answer = (answer + addSum) % MOD;
    }
    return answer;
}

