int countKReducibleNumbers(const std::string& s, int k) {
    const int64_t MOD = 1000000007LL;
    int L = static_cast<int>(s.size());

    std::vector<std::vector<int64_t>> C(L + 1, std::vector<int64_t>(L + 1, 0));
    for (int i = 0; i <= L; ++i) {
        C[i][0] = 1;
        C[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
    }

    std::vector<int> steps(L + 1, 0);
    if (L >= 1) steps[1] = 0;
    for (int c = 2; c <= L; ++c) {
        int pc = __builtin_popcount(c);
        steps[c] = 1 + steps[pc];
    }

    std::vector<int> good;
    for (int c = 1; c <= L; ++c) {
        if (steps[c] <= k - 1) good.push_back(c);
    }

    auto countLessThan = [&](int target) -> int64_t {
        int64_t ans = 0;
        int onesSoFar = 0;
        for (int i = 0; i < L; ++i) {
            if (s[i] == '1') {
                int remaining = L - i - 1;
                int need = target - onesSoFar;
                if (need >= 0 && need <= remaining) {
                    ans = (ans + C[remaining][need]) % MOD;
                }
                ++onesSoFar;
                if (onesSoFar > target) break;
            }
        }
        return ans;
    };

    int64_t total = 0;
    for (int c : good) {
        total = (total + countLessThan(c)) % MOD;
    }
    return static_cast<int>(total);
}

