long long shiftDistance(const std::string& s, const std::string& t,
                        const std::vector<int>& nextCost,
                        const std::vector<int>& previousCost) {
    std::size_t n = s.size();
    std::vector<long long> prefNext(27, 0), prefPrev(27, 0);
    for (int i = 0; i < 26; ++i) {
        prefNext[i + 1] = prefNext[i] + nextCost[i];
        prefPrev[i + 1] = prefPrev[i] + previousCost[i];
    }
    long long total = 0;
    for (std::size_t i = 0; i < n; ++i) {
        int a = s[i] - 'a';
        int b = t[i] - 'a';
        if (a == b) continue;
        long long forward = 0, backward = 0;
        if (a < b) {
            forward = prefNext[b] - prefNext[a];
            backward = (prefPrev[a + 1] - prefPrev[0]) + (prefPrev[26] - prefPrev[b + 1]);
        } else { // a > b
            forward = (prefNext[26] - prefNext[a]) + prefNext[b];
            backward = prefPrev[a + 1] - prefPrev[b + 1];
        }
        total += std::min(forward, backward);
    }
    return total;
}

