int minimumOperations(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
    int n = nums.size(), m = queries.size();
    auto feasible = [&](int k) {
        std::vector<long long> diff(n+1, 0);
        for (int i = 0; i < k; i++) {
            int l=queries[i][0], r=queries[i][1], val=queries[i][2];
            diff[l] += val; diff[r+1] -= val;
        }
        long long cur = 0;
        for (int i = 0; i < n; i++) { cur += diff[i]; if (cur < nums[i]) return false; }
        return true;
    };
    if (!feasible(m)) return -1;
    int lo=0, hi=m;
    while (lo<hi) { int mid=(lo+hi)/2; if (feasible(mid)) hi=mid; else lo=mid+1; }
    return lo;
}

