bool canRearrange(const std::string& s, const std::string& t, int k) {
    size_t n = s.size();
    if (n != t.size()) return false;
    if (k == 0) return false;
    if (n % k != 0) return false;
    size_t blockSize = n / k;
    std::unordered_map<std::string, int> blockCount;
    for (size_t i = 0; i < n; i += blockSize) {
        std::string block = s.substr(i, blockSize);
        ++blockCount[block];
    }
    for (size_t i = 0; i < n; i += blockSize) {
        std::string block = t.substr(i, blockSize);
        auto it = blockCount.find(block);
        if (it == blockCount.end() || it->second == 0) return false;
        --it->second;
    }
    return true;
}

