using namespace std;

int minArraySum(vector<int>& nums, int k, int op1, int op2) {
    int n = nums.size();
    const int INF = 1e9;
    vector<vector<vector<int>>> f(n+1, vector<vector<int>>(op1+1, vector<int>(op2+1, INF)));
    f[0][0][0] = 0;
    for (int i = 1; i <= n; i++) {
        int x = nums[i-1];
        for (int j = 0; j <= op1; j++) {
            for (int kk = 0; kk <= op2; kk++) {
                int best = INF;
                if (f[i-1][j][kk] < INF)
                    best = min(best, f[i-1][j][kk] + x);
                if (j > 0 && f[i-1][j-1][kk] < INF)
                    best = min(best, f[i-1][j-1][kk] + (x+1)/2);
                if (kk > 0 && x >= k && f[i-1][j][kk-1] < INF)
                    best = min(best, f[i-1][j][kk-1] + (x-k));
                if (j > 0 && kk > 0 && f[i-1][j-1][kk-1] < INF) {
                    int y = (x+1)/2;
                    if (y >= k) best = min(best, f[i-1][j-1][kk-1] + (y-k));
                    if (x >= k) best = min(best, f[i-1][j-1][kk-1] + (x-k+1)/2);
                }
                f[i][j][kk] = best;
            }
        }
    }
    int ans = INF;
    for (int j = 0; j <= op1; j++)
        for (int kk = 0; kk <= op2; kk++)
            ans = min(ans, f[n][j][kk]);
    return ans;
}

