    for (int start = 0; start < n; ++start) {
        int minLen = std::max(l, 1);
        int maxLen = std::min(r, n - start);
        for (int len = minLen; len <= maxLen; ++len) {
            long long sum = pref[start + len] - pref[start];
            if (sum > 0 && sum < answer) {
                answer = sum;
            }
        }
    }

    return answer == LLONG_MAX ? -1 : answer;
}

