int max_removable_queries(const std::vector<int>& nums, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(nums.size());
    int q = static_cast<int>(queries.size());
    std::vector<std::vector<int>> start_at(n);
    for (int i = 0; i < q; ++i) {
        int l = queries[i][0];
        int r = queries[i][1];
        start_at[l].push_back(r);
    }
    std::priority_queue<int, std::vector<int>, std::greater<int>> start_heap;
    std::priority_queue<int, std::vector<int>, std::greater<int>> selected_heap;
    int active = 0;
    int used = 0;
    for (int i = 0; i < n; ++i) {
        for (int r : start_at[i]) {
            start_heap.push(r);
        }
        while (!selected_heap.empty() && selected_heap.top() < i) {
            selected_heap.pop();
            --active;
        }
        while (active < nums[i]) {
            if (start_heap.empty()) {
                return -1;
            }
            int r = start_heap.top();
            start_heap.pop();
            selected_heap.push(r);
            ++active;
            ++used;
        }
    }
    return q - used;
}

