std::vector<int> maximizeTargetNodes(const std::vector<std::vector<int>>& edges1, const std::vector<std::vector<int>>& edges2, int k) {
    int n = static_cast<int>(edges1.size()) + 1;
    int m = static_cast<int>(edges2.size()) + 1;

    auto buildAdj = [&](int num, const std::vector<std::vector<int>>& edges) {
        std::vector<std::vector<int>> adj(num);
        for (const auto& e : edges) {
            int a = e[0];
            int b = e[1];
            adj[a].push_back(b);
            adj[b].push_back(a);
        }
        return adj;
    };

    std::vector<std::vector<int>> adj1 = buildAdj(n, edges1);
    std::vector<std::vector<int>> adj2 = buildAdj(m, edges2);

    auto allPairsDist = [&](int num, const std::vector<std::vector<int>>& adj) {
        std::vector<std::vector<int16_t>> dist(num, std::vector<int16_t>(num, -1));
        std::vector<int> queue(num);
        for (int s = 0; s < num; ++s) {
            auto& d = dist[s];
            std::fill(d.begin(), d.end(), static_cast<int16_t>(-1));
            int head = 0, tail = 0;
            d[s] = 0;
            queue[tail++] = s;
            while (head < tail) {
                int u = queue[head++];
                int16_t du = d[u];
                for (int v : adj[u]) {
                    if (d[v] == -1) {
                        d[v] = du + 1;
                        queue[tail++] = v;
                    }
                }
            }
        }
        return dist;
    };

    std::vector<std::vector<int16_t>> dist1 = allPairsDist(n, adj1);
    std::vector<std::vector<int16_t>> dist2 = allPairsDist(m, adj2);

    std::vector<int16_t> countFirst(n);
    for (int i = 0; i < n; ++i) {
        int16_t cnt = 0;
        const auto& drow = dist1[i];
        for (int j = 0; j < n; ++j) {
            int16_t d = drow[j];
            if (d != -1 && d <= k) ++cnt;
        }
        countFirst[i] = cnt;
    }

    std::vector<int16_t> bestSecond(k + 1, 0);
    for (int v = 0; v < m; ++v) {
        std::vector<int16_t> cnt(k + 1, 0);
        const auto& drow = dist2[v];
        for (int w = 0; w < m; ++w) {
            int16_t d = drow[w];
            if (d != -1 && d <= k) ++cnt[d];
        }
        for (int r = 1; r <= k; ++r) cnt[r] += cnt[r - 1];
        for (int r = 0; r <= k; ++r) {
            if (cnt[r] > bestSecond[r]) bestSecond[r] = cnt[r];
        }
    }

    std::vector<int16_t> answer(n);
    for (int i = 0; i < n; ++i) {
        int16_t maxAdd = 0;
        const auto& drow = dist1[i];
        for (int u = 0; u < n; ++u) {
            int16_t d = drow[u];
            int R = k - d - 1;
            if (R >= 0) {
                int16_t add = bestSecond[R];
                if (add > maxAdd) maxAdd = add;
            }
        }
        answer[i] = countFirst[i] + maxAdd;
    }

    std::vector<int> result(answer.size());
    for (size_t i = 0; i < answer.size(); ++i) result[i] = static_cast<int>(answer[i]);
    return result;
}

#include <bits/stdc++.h>

long long smallestAllSetBits(long long n) {
    if (n <= 0) {
        return 0;
    }
    unsigned long long num = static_cast<unsigned long long>(n);
    int len = 0;
    unsigned long long tmp = num;
    while (tmp > 0) {
        tmp >>= 1;
        ++len;
    }
    unsigned long long candidate = (len >= 64) ? ULLONG_MAX : ((1ULL << len) - 1ULL);
    if (candidate >= num) {
        return static_cast<long long>(candidate);
    }
    unsigned long long result = (len + 1 >= 64) ? ULLONG_MAX : ((1ULL << (len + 1)) - 1ULL);
    return static_cast<long long>(result);
}

