bool isPrime(long long x) {
    if (x <= 1) return false;
    if (x == 2) return true;
    if (x % 2 == 0) return false;
    long long r = static_cast<long long>(std::sqrt(static_cast<double>(x)));
    for (long long i = 3; i <= r; i += 2) {
        if (x % i == 0) return false;
    }
    return true;
}

long long minimumTransformationCost(long long n, long long m) {
    std::string sn = std::to_string(n);
    std::string sm = std::to_string(m);
    int lenN = static_cast<int>(sn.length());
    int lenM = static_cast<int>(sm.length());
    if (lenN != lenM) return -1;
    int d = lenN;

    if (isPrime(n) || isPrime(m)) return -1;
    if (n == m) return n;

    int maxVal = 1;
    for (int i = 0; i < d; ++i) maxVal *= 10;
    maxVal -= 1;

    const long long INF = LLONG_MAX / 4;
    std::vector<long long> dist(maxVal + 1, INF);
    std::vector<char> visited(maxVal + 1, 0);

    using Pair = std::pair<long long, int>;
    std::priority_queue<Pair, std::vector<Pair>, std::greater<Pair>> heap;

    dist[static_cast<int>(n)] = n;
    heap.push({n, static_cast<int>(n)});

    while (!heap.empty()) {
        auto top = heap.top();
        heap.pop();
        long long curDist = top.first;
        int u = top.second;
        if (visited[u]) continue;
        visited[u] = 1;
        if (u == m) return curDist;

        std::string s = std::to_string(u);
        if (static_cast<int>(s.length()) < d) s = std::string(d - s.length(), '0') + s;

        for (int i = 0; i < d; ++i) {
            int digit = s[i] - '0';
            // decrease
            if (digit > 0) {
                if (!(i == 0 && digit == 1)) {
                    std::string t = s;
                    t[i] = static_cast<char>('0' + (digit - 1));
                    long long v = std::stoll(t);
                    if (!isPrime(v) && curDist + v < dist[static_cast<int>(v)]) {
                        dist[static_cast<int>(v)] = curDist + v;
                        heap.push({dist[static_cast<int>(v)], static_cast<int>(v)});
                    }
                }
            }
            // increase
            if (digit < 9) {
                std::string t = s;
                t[i] = static_cast<char>('0' + (digit + 1));
                long long v = std::stoll(t);
                if (!isPrime(v) && curDist + v < dist[static_cast<int>(v)]) {
                    dist[static_cast<int>(v)] = curDist + v;
                    heap.push({dist[static_cast<int>(v)], static_cast<int>(v)});
                }
            }
        }
    }

    return -1;
}

