long long maxSubarraySumDivisibleByK(const std::vector<int>& nums, int k) {
    long long prefix = 0;
    long long answer = std::numeric_limits<long long>::lowest();
    std::vector<long long> minPrefix(k, std::numeric_limits<long long>::max());
    minPrefix[0] = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        prefix += static_cast<long long>(nums[i]);
        int r = static_cast<int>((i + 1) % static_cast<size_t>(k));
        if (minPrefix[r] != std::numeric_limits<long long>::max()) {
            answer = std::max(answer, prefix - minPrefix[r]);
        }
        if (prefix < minPrefix[r]) {
            minPrefix[r] = prefix;
        }
    }
    return answer;
}

