int maxAreaRectangle(const std::vector<std::vector<int>>& points) {
    int n = static_cast<int>(points.size());
    std::unordered_set<std::string> pointSet;
    for (const auto& p : points) {
        pointSet.insert(std::to_string(p[0]) + "," + std::to_string(p[1]));
    }
    int best = -1;
    for (int i = 0; i < n; ++i) {
        int x1 = points[i][0];
        int y1 = points[i][1];
        for (int j = i + 1; j < n; ++j) {
            int x2 = points[j][0];
            int y2 = points[j][1];
            if (x1 == x2 || y1 == y2) continue;
            std::string c1 = std::to_string(x1) + "," + std::to_string(y2);
            std::string c2 = std::to_string(x2) + "," + std::to_string(y1);
            if (pointSet.find(c1) == pointSet.end() || pointSet.find(c2) == pointSet.end()) continue;
            int minX = std::min(x1, x2);
            int maxX = std::max(x1, x2);
            int minY = std::min(y1, y2);
            int maxY = std::max(y1, y2);
            bool ok = true;
            for (const auto& p : points) {
                int x = p[0];
                int y = p[1];
                if ((x == x1 && y == y1) ||
                    (x == x2 && y == y2) ||
                    (x == x1 && y == y2) ||
                    (x == x2 && y == y1)) {
                    continue;
                }
                if (x >= minX && x <= maxX && y >= minY && y <= maxY) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                int area = (maxX - minX) * (maxY - minY);
                if (area > best) best = area;
            }
        }
    }
    return best;
}

