int minOperationsToMakeGood(const std::string& s) {
    int n = static_cast<int>(s.size());
    std::vector<int> freq(26, 0);
    for (int i = 0; i < n; ++i) {
        freq[s[i] - 'a']++;
    }
    std::vector<int> sorted = freq;
    std::sort(sorted.begin(), sorted.end(), std::greater<int>());
    int best = n;
    for (int k = 1; k <= 26 && k <= n; ++k) {
        int sumTop = 0;
        for (int i = 0; i < k; ++i) sumTop += sorted[i];
        int extra = n - sumTop;
        for (int f = 1; f <= n; ++f) {
            int surplus = extra;
            int deficit = 0;
            for (int i = 0; i < k; ++i) {
                int cur = sorted[i];
                if (cur > f) surplus += cur - f;
                else deficit += f - cur;
            }
            int ops = surplus > deficit ? surplus : deficit;
            if (ops < best) best = ops;
        }
    }
    return best;
}

