int longestPushButton(const std::vector<std::vector<int>>& events) {
    int prevTime = 0;
    int bestIndex = -1;
    int bestDuration = -1;
    for (size_t i = 0; i < events.size(); ++i) {
        int idx = events[i][0];
        int curTime = events[i][1];
        int duration = curTime - prevTime;
        if (duration > bestDuration) {
            bestDuration = duration;
            bestIndex = idx;
        } else if (duration == bestDuration && idx < bestIndex) {
            bestIndex = idx;
        }
        prevTime = curTime;
    }
    return bestIndex;
}

#include <bits/stdc++.h>
double maxAmountAfterTwoDays(
    const std::string& initialCurrency,
    const std::vector<std::vector<std::string>>& pairs1,
    const std::vector<double>& rates1,
    const std::vector<std::vector<std::string>>& pairs2,
    const std::vector<double>& rates2)
{
    std::unordered_map<std::string, int> id;
    auto getId = [&](const std::string& s) -> int {
        auto it = id.find(s);
        if (it != id.end()) return it->second;
        int newId = (int)id.size();
        id[s] = newId;
        return newId;
    };
    getId(initialCurrency);
    for (const auto& p : pairs1) {
        getId(p[0]);
        getId(p[1]);
    }
    for (const auto& p : pairs2) {
        getId(p[0]);
        getId(p[1]);
    }
    int n = id.size();
    std::vector<std::vector<std::pair<int,double>>> adj1(n), adj2(n);
    for (size_t i = 0; i < pairs1.size(); ++i) {
        int u = id[pairs1[i][0]];
        int v = id[pairs1[i][1]];
        double r = rates1[i];
        adj1[u].push_back({v, r});
        adj1[v].push_back({u, 1.0 / r});
    }
    for (size_t i = 0; i < pairs2.size(); ++i) {
        int u = id[pairs2[i][0]];
        int v = id[pairs2[i][1]];
        double r = rates2[i];
        adj2[u].push_back({v, r});
        adj2[v].push_back({u, 1.0 / r});
    }
    int start = id[initialCurrency];
    auto computeFactors = [&](const std::vector<std::vector<std::pair<int,double>>>& adj) {
        std::vector<double> f(n, 0.0);
        std::queue<int> q;
        f[start] = 1.0;
        q.push(start);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto &e : adj[u]) {
                int v = e.first;
                double w = e.second;
                if (f[v] == 0.0) {
                    f[v] = f[u] * w;
                    q.push(v);
                }
            }
        }
        return f;
    };
    std::vector<double> f1 = computeFactors(adj1);
    std::vector<double> f2 = computeFactors(adj2);
    double best = 1.0;
    for (int i = 0; i < n; ++i) {
        if (f1[i] > 0.0 && f2[i] > 0.0) {
            double candidate = f1[i] / f2[i];
            if (candidate > best) best = candidate;
        }
    }
    return best;
}

