bool canMakeCuts(int n, const std::vector<std::vector<int>>& rectangles) {
    auto check = [&](bool vertical) -> bool {
        std::vector<std::pair<int,int>> intervals;
        std::vector<int> coords;
        coords.reserve(rectangles.size()*2 + 2);
        coords.push_back(0);
        coords.push_back(n);
        for (const auto& r : rectangles) {
            int a = vertical ? r[0] : r[1];
            int b = vertical ? r[2] : r[3];
            intervals.emplace_back(a, b);
            coords.push_back(a);
            coords.push_back(b);
        }
        std::sort(intervals.begin(), intervals.end(),
                  [](const auto& p1, const auto& p2){ return p1.first < p2.first; });
        std::sort(coords.begin(), coords.end());
        coords.erase(std::unique(coords.begin(), coords.end()), coords.end());

        std::multiset<int> activeEnds;
        size_t idx = 0;
        int freeCount = 0;
        for (int x : coords) {
            while (idx < intervals.size() && intervals[idx].first < x) {
                activeEnds.insert(intervals[idx].second);
                ++idx;
            }
            while (!activeEnds.empty() && *activeEnds.begin() <= x) {
                activeEnds.erase(activeEnds.begin());
            }
            bool blocked = !activeEnds.empty(); // some interval strictly contains x
            if (!blocked && x > 0 && x < n) {
                ++freeCount;
                if (freeCount >= 2) return true;
            }
        }
        return false;
    };

    return check(true) || check(false);
}

