int countUniqueMiddleMode(const std::vector<int>& nums) {
    const std::int64_t MOD = 1000000007LL;
    std::int64_t ans = 0;
    int n = static_cast<int>(nums.size());
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            for (int k = j + 1; k < n; ++k) {
                for (int l = k + 1; l < n; ++l) {
                    for (int m = l + 1; m < n; ++m) {
                        int middle = nums[k];
                        std::unordered_map<int, int> freq;
                        ++freq[nums[i]];
                        ++freq[nums[j]];
                        ++freq[nums[k]];
                        ++freq[nums[l]];
                        ++freq[nums[m]];
                        int maxcnt = 0;
                        for (const auto& p : freq) {
                            if (p.second > maxcnt) maxcnt = p.second;
                        }
                        int cntMax = 0;
                        int valMax = 0;
                        for (const auto& p : freq) {
                            if (p.second == maxcnt) {
                                ++cntMax;
                                valMax = p.first;
                            }
                        }
                        if (cntMax == 1 && valMax == middle) {
                            ans = (ans + 1) % MOD;
                        }
                    }
                }
            }
        }
    }
    return static_cast<int>(ans);
}

