int count_paths_xor(const std::vector<std::vector<int>>& grid, int k) {
    const int MOD = 1000000007;
    const int max_xor = 16;
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());

    std::vector<std::vector<int>> dp_prev(n, std::vector<int>(max_xor, 0));
    dp_prev[0][grid[0][0]] = 1;

    for (int j = 1; j < n; ++j) {
        std::vector<int> cur(max_xor, 0);
        int val = grid[0][j];
        const std::vector<int>& left = dp_prev[j - 1];
        for (int x = 0; x < max_xor; ++x) {
            if (left[x] != 0) {
                int nx = x ^ val;
                cur[nx] = (cur[nx] + left[x]) % MOD;
            }
        }
        dp_prev[j] = std::move(cur);
    }

    for (int i = 1; i < m; ++i) {
        std::vector<std::vector<int>> dp_curr(n, std::vector<int>(max_xor, 0));
        int val_first_col = grid[i][0];
        const std::vector<int>& above_first = dp_prev[0];
        for (int x = 0; x < max_xor; ++x) {
            if (above_first[x] != 0) {
                int nx = x ^ val_first_col;
                dp_curr[0][nx] = (dp_curr[0][nx] + above_first[x]) % MOD;
            }
        }

        for (int j = 1; j < n; ++j) {
            int val = grid[i][j];
            std::vector<int>& cur = dp_curr[j];
            const std::vector<int>& above = dp_prev[j];
            const std::vector<int>& left = dp_curr[j - 1];

            for (int x = 0; x < max_xor; ++x) {
                if (above[x] != 0) {
                    int nx = x ^ val;
                    cur[nx] = (cur[nx] + above[x]) % MOD;
                }
            }

            for (int x = 0; x < max_xor; ++x) {
                if (left[x] != 0) {
                    int nx = x ^ val;
                    cur[nx] = (cur[nx] + left[x]) % MOD;
                }
            }
        }

        dp_prev = std::move(dp_curr);
    }

    return dp_prev[n - 1][k] % MOD;
}

