int smallestSubstring(const std::string& s, int numOps) {
    int n = static_cast<int>(s.size());
    auto feasible = [&](int L) -> bool {
        const int INF = n + 5;
        std::vector<std::vector<int>> prev(2, std::vector<int>(L + 1, INF));
        for (int c = 0; c < 2; ++c) {
            prev[c][1] = (s[0] - '0' != c);
        }
        for (int i = 1; i < n; ++i) {
            std::vector<std::vector<int>> cur(2, std::vector<int>(L + 1, INF));
            for (int pc = 0; pc < 2; ++pc) {
                for (int plen = 1; plen <= L; ++plen) {
                    int curFlips = prev[pc][plen];
                    if (curFlips == INF) continue;
                    for (int nc = 0; nc < 2; ++nc) {
                        int nlen = (nc == pc) ? plen + 1 : 1;
                        if (nlen > L) continue;
                        int add = (s[i] - '0' != nc);
                        int& dest = cur[nc][nlen];
                        dest = std::min(dest, curFlips + add);
                    }
                }
            }
            prev.swap(cur);
        }
        for (int c = 0; c < 2; ++c) {
            for (int len = 1; len <= L; ++len) {
                if (prev[c][len] <= numOps) return true;
            }
        }
        return false;
    };
    int low = 1, high = n;
    while (low < high) {
        int mid = (low + high) / 2;
        if (feasible(mid)) high = mid;
        else low = mid + 1;
    }
    return low;
}

