bool substringMatchingPattern(const std::string& s, const std::string& p) {
    std::size_t starPos = p.find('*');
    std::string pre = p.substr(0, starPos);
    std::string suf = p.substr(starPos + 1);
    if (pre.empty() && suf.empty()) return true;
    if (pre.empty()) return s.find(suf) != std::string::npos;
    if (suf.empty()) return s.find(pre) != std::string::npos;
    for (std::size_t i = 0; i + pre.size() <= s.size(); ++i) {
        if (s.compare(i, pre.size(), pre) == 0) {
            std::size_t after = i + pre.size();
            if (s.find(suf, after) != std::string::npos) {
                return true;
            }
        }
    }
    return false;
}

