const long long MOD = 1000000007LL;

long long modPow(long long base, long long exp) {
    long long res = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int countArrays(int n, int m, int k) {
    if (k < 0 || k > n - 1) return 0;
    if (n == 0) return 0;
    // precompute factorials up to n-1
    int limit = n - 1;
    std::vector<long long> fact(limit + 1), invFact(limit + 1);
    fact[0] = 1;
    for (int i = 1; i <= limit; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[limit] = modPow(fact[limit], MOD - 2);
    for (int i = limit; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;
    long long comb = fact[limit] * invFact[k] % MOD * invFact[limit - k] % MOD;
    long long powTerm = modPow(m - 1, n - k - 1);
    long long ans = comb * (m % MOD) % MOD * powTerm % MOD;
    return static_cast<int>(ans);
}

