using namespace std;
struct Node { int userId, taskId, priority, idx; };
class TaskManager {
public:
    vector<Node*> heap;
    unordered_map<int,Node*> taskMap;
    bool less_(Node* a, Node* b) { return a->priority != b->priority ? a->priority > b->priority : a->taskId > b->taskId; }
    void swapNodes(int i, int j) { swap(heap[i],heap[j]); heap[i]->idx=i; heap[j]->idx=j; }
    void heapifyUp(int i) { while(i>0){int p=(i-1)>>1; if(less_(heap[i],heap[p])){swapNodes(i,p);i=p;} else break;} }
    void heapifyDown(int i) { int n=heap.size(); while(true){int l=i*2+1,r=i*2+2,best=i; if(l<n&&less_(heap[l],heap[best]))best=l; if(r<n&&less_(heap[r],heap[best]))best=r; if(best!=i){swapNodes(i,best);i=best;} else break;} }
    void removeAt(int idx) { swapNodes(idx, heap.size()-1); Node* removed=heap.back(); heap.pop_back(); taskMap.erase(removed->taskId); delete removed; if(idx<(int)heap.size()){heapifyUp(idx);heapifyDown(idx);} }
    TaskManager(vector<array<int,3>>& tasks) {
        for (auto& t: tasks) { Node* node=new Node{t[0],t[1],t[2],(int)heap.size()}; heap.push_back(node); taskMap[t[1]]=node; }
        for (int i=(int)(heap.size()>>1)-1;i>=0;i--) heapifyDown(i);
    }
    void add(int userId,int taskId,int priority) { if(taskMap.count(taskId))return; Node* node=new Node{userId,taskId,priority,(int)heap.size()}; heap.push_back(node); taskMap[taskId]=node; heapifyUp(node->idx); }
    void edit(int taskId,int newPriority) { auto it=taskMap.find(taskId); if(it==taskMap.end())return; it->second->priority=newPriority; heapifyUp(it->second->idx); heapifyDown(it->second->idx); }
    void rmv(int taskId) { auto it=taskMap.find(taskId); if(it==taskMap.end())return; removeAt(it->second->idx); }
    int execTop() { if(heap.empty())return -1; int userId=heap[0]->userId; removeAt(0); return userId; }
};

