long long maxSubarraySumAfterRemoval(const std::vector<int>& nums) {
    long long cur = 0;
    long long best = std::numeric_limits<long long>::min();
    for (int x : nums) {
        cur = std::max(cur + static_cast<long long>(x), static_cast<long long>(x));
        best = std::max(best, cur);
    }
    long long answer = best;

    std::unordered_set<int> distinct(nums.begin(), nums.end());

    for (int v : distinct) {
        long long curV = 0;
        long long bestV = std::numeric_limits<long long>::min();
        bool hasNonV = false;
        for (int x : nums) {
            if (x == v) continue;
            if (!hasNonV) {
                curV = static_cast<long long>(x);
                hasNonV = true;
            } else {
                curV = std::max(curV + static_cast<long long>(x), static_cast<long long>(x));
            }
            bestV = std::max(bestV, curV);
        }
        if (hasNonV) {
            answer = std::max(answer, bestV);
        }
    }
    return answer;
}

#include <bits/stdc++.h>

long long maxCoins(const std::vector<std::vector<int>>& coins, long long k) {
    int n = coins.size();
    std::vector<long long> L(n), R(n), C(n);
    for (int i = 0; i < n; ++i) {
        L[i] = coins[i][0];
        R[i] = coins[i][1];
        C[i] = coins[i][2];
    }
    // sort by left coordinate
    std::vector<int> idx(n);
    for (int i = 0; i < n; ++i) idx[i] = i;
    std::sort(idx.begin(), idx.end(), [&](int a, int b){ return L[a] < L[b]; });
    std::vector<long long> Ls, Rs, Cs;
    Ls.reserve(n); Rs.reserve(n); Cs.reserve(n);
    for (int id : idx) {
        Ls.push_back(L[id]);
        Rs.push_back(R[id]);
        Cs.push_back(C[id]);
    }
    L.swap(Ls); R.swap(Rs); C.swap(Cs);
    // prefix sum of total coins up to each interval end
    std::vector<long long> pref(n);
    for (int i = 0; i < n; ++i) {
        long long segSum = C[i] * (R[i] - L[i] + 1);
        pref[i] = segSum + (i ? pref[i-1] : 0);
    }
    // helper to compute sum for a given window start
    auto getSum = [&](long long start) -> long long {
        long long end = start + k - 1;
        // find first interval with R >= start
        int leftIdx = std::lower_bound(R.begin(), R.end(), start) - R.begin();
        // find last interval with L <= end
        int rightIdx = std::upper_bound(L.begin(), L.end(), end) - L.begin() - 1;
        if (leftIdx > rightIdx || leftIdx == n || rightIdx < 0) return 0LL;
        if (leftIdx == rightIdx) {
            long long overlap = std::min(R[leftIdx], end) - std::max(L[leftIdx], start) + 1;
            if (overlap < 0) overlap = 0;
            return overlap * C[leftIdx];
        }
        long long sum = 0;
        // left partial
        long long leftOverlap = R[leftIdx] - std::max(L[leftIdx], start) + 1;
        if (leftOverlap > 0) sum += leftOverlap * C[leftIdx];
        // right partial
        long long rightOverlap = std::min(R[rightIdx], end) - L[rightIdx] + 1;
        if (rightOverlap > 0) sum += rightOverlap * C[rightIdx];
        // full intervals between
        if (rightIdx - leftIdx > 1) {
            sum += pref[rightIdx - 1] - pref[leftIdx];
        }
        return sum;
    };
    std::vector<long long> candidates;
    candidates.reserve(2 * n + 1);
    candidates.push_back(1); // start at coordinate 1
    for (int i = 0; i < n; ++i) {
        candidates.push_back(L[i]);
        long long s = R[i] - k + 1;
        if (s < 1) s = 1;
        candidates.push_back(s);
    }
    std::sort(candidates.begin(), candidates.end());
    candidates.erase(std::unique(candidates.begin(), candidates.end()), candidates.end());
    long long best = 0;
    for (long long st : candidates) {
        long long cur = getSum(st);
        if (cur > best) best = cur;
    }
    return best;
}

#include <bits/stdc++.h>

int longestProductEquivalentSubarray(const std::vector<int>& nums) {
    int n = nums.size();
    if (n == 0) return 0;
    // Precompute distinct prime factors for each element
    std::vector<std::vector<int>> factors(n);
    for (int i = 0; i < n; ++i) {
        int x = nums[i];
        int d = 2;
        while (d * d <= x) {
            if (x % d == 0) {
                factors[i].push_back(d);
                while (x % d == 0) x /= d;
            }
            ++d;
        }
        if (x > 1) factors[i].push_back(x);
    }

    std::unordered_map<int, int> cnt;
    int conflict = 0; // number of primes appearing more than once in the window
    int left = 0;
    int maxLen = 0;

    for (int right = 0; right < n; ++right) {
        for (int p : factors[right]) {
            int before = cnt[p];
            cnt[p] = before + 1;
            if (cnt[p] == 2) ++conflict;
        }
        while (conflict > 0) {
            for (int p : factors[left]) {
                if (cnt[p] == 2) --conflict;
                cnt[p]--;
                if (cnt[p] == 0) cnt.erase(p);
            }
            ++left;
        }
        maxLen = std::max(maxLen, right - left + 1);
    }

    // Any subarray of length 2 is always product‑equivalent
    int answer = std::max(maxLen, std::min(2, n));
    return answer;
}

