int longestSubsequenceWithDecreasingAdjacentDifference(const std::vector<int>& nums) {
    const int n = static_cast<int>(nums.size());
    const int MAX_DIFF = 300;
    std::vector<std::vector<uint16_t>> dp(n, std::vector<uint16_t>(MAX_DIFF + 1, 0));
    std::vector<std::vector<uint16_t>> suffix(n, std::vector<uint16_t>(MAX_DIFF + 1, 0));
    int answer = 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            int d = std::abs(nums[i] - nums[j]);
            int best = 2;
            uint16_t prev = suffix[j][d];
            if (prev > 0) {
                int cand = static_cast<int>(prev) + 1;
                if (cand > best) best = cand;
            }
            if (best > dp[i][d]) {
                dp[i][d] = static_cast<uint16_t>(best);
                if (best > answer) answer = best;
            }
        }
        int curMax = 0;
        for (int d = MAX_DIFF; d >= 0; --d) {
            if (dp[i][d] > curMax) curMax = dp[i][d];
            suffix[i][d] = static_cast<uint16_t>(curMax);
        }
    }
    return answer;
}

