long long mirrorScore(const std::string& s) {
    std::vector<std::vector<int>> waiting(26);
    long long total = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        char c = s[i];
        int idx = c - 'a';
        char mirrorChar = 'z' - (c - 'a');
        int mirrorIdx = mirrorChar - 'a';
        if (!waiting[mirrorIdx].empty()) {
            int pos = waiting[mirrorIdx].back();
            waiting[mirrorIdx].pop_back();
            total += i - pos;
        } else {
            waiting[idx].push_back(i);
        }
    }
    return total;
}

