struct State {
    long long sum = 0;
    int len = 0;
    int idx[4];
};

static bool lexicographicallySmaller(const State& a, const State& b) {
    int m = std::min(a.len, b.len);
    for (int i = 0; i < m; ++i) {
        if (a.idx[i] != b.idx[i]) return a.idx[i] < b.idx[i];
    }
    return a.len < b.len;
}

static bool better(const State& a, const State& b) {
    if (a.sum != b.sum) return a.sum > b.sum;
    return lexicographicallySmaller(a, b);
}

static State addIdx(const State& s, int newIdx) {
    State res = s;
    int pos = 0;
    while (pos < res.len && res.idx[pos] < newIdx) ++pos;
    for (int i = res.len; i > pos; --i) {
        res.idx[i] = res.idx[i - 1];
    }
    res.idx[pos] = newIdx;
    ++res.len;
    return res;
}

std::vector<int> maxScore(std::vector<std::vector<int>>& intervals) {
    int n = intervals.size();
    struct Item {
        int l, r;
        long long w;
        int orig;
    };
    std::vector<Item> items;
    items.reserve(n);
    for (int i = 0; i < n; ++i) {
        items.push_back({intervals[i][0], intervals[i][1], intervals[i][2], i});
    }
    std::sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
        if (a.l != b.l) return a.l < b.l;
        return a.r < b.r;
    });
    std::vector<int> starts(n);
    for (int i = 0; i < n; ++i) starts[i] = items[i].l;
    std::vector<int> nxt(n);
    for (int i = 0; i < n; ++i) {
        int pos = std::upper_bound(starts.begin(), starts.end(), items[i].r) - starts.begin();
        nxt[i] = pos;
    }
    const int K = 4;
    std::vector<std::array<State, K + 1>> dp(n + 1);
    for (int c = 0; c <= K; ++c) dp[n][c] = State();
    for (int i = n - 1; i >= 0; --i) {
        dp[i][0] = State();
        for (int c = 1; c <= K; ++c) {
            State best = dp[i + 1][c]; // skip
            State take = dp[nxt[i]][c - 1];
            take.sum += items[i].w;
            take = addIdx(take, items[i].orig);
            if (better(take, best)) best = take;
            dp[i][c] = best;
        }
    }
    State ans = dp[0][K];
    std::vector<int> res;
    for (int i = 0; i < ans.len; ++i) res.push_back(ans.idx[i]);
    return res;
}

