long long countNonDecreasingSubarrays(const std::vector<int>& nums, long long k) {
    std::size_t n = nums.size();
    long long answer = 0;
    for (std::size_t i = 0; i < n; ++i) {
        int curMax = nums[i];
        long long cost = 0;
        ++answer;
        for (std::size_t j = i + 1; j < n; ++j) {
            if (nums[j] >= curMax) {
                curMax = nums[j];
            } else {
                cost += static_cast<long long>(curMax) - nums[j];
                if (cost > k) break;
            }
            if (cost <= k) ++answer;
        }
    }
    return answer;
}

