long long maxProfit(vector<vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    const long long NEG = -4e18;
    vector<vector<long long>> dpPrev(n, vector<long long>(3, NEG));
    vector<vector<long long>> dpCurr(n, vector<long long>(3, NEG));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == 0 && j == 0) {
                dpCurr[0][0] = grid[0][0];
                dpCurr[0][1] = 0;
                dpCurr[0][2] = NEG;
                continue;
            }
            for (int k = 0; k <= 2; ++k) {
                long long best = NEG;
                if (i > 0) {
                    if (dpPrev[j][k] != NEG) best = max(best, dpPrev[j][k] + grid[i][j]);
                    if (k > 0 && dpPrev[j][k - 1] != NEG) best = max(best, dpPrev[j][k - 1]);
                }
                if (j > 0) {
                    if (dpCurr[j - 1][k] != NEG) best = max(best, dpCurr[j - 1][k] + grid[i][j]);
                    if (k > 0 && dpCurr[j - 1][k - 1] != NEG) best = max(best, dpCurr[j - 1][k - 1]);
                }
                dpCurr[j][k] = best;
            }
        }
        dpPrev.swap(dpCurr);
        for (int j = 0; j < n; ++j) {
            std::fill(dpCurr[j].begin(), dpCurr[j].end(), NEG);
        }
    }
    long long ans = NEG;
    for (int k = 0; k <= 2; ++k) ans = max(ans, dpPrev[n - 1][k]);
    return ans;
}

