long long sumMaxMinSubseq(const std::vector<int>& nums, int k) {
    const long long MOD = 1000000007LL;
    int n = static_cast<int>(nums.size());
    std::vector<int> sorted(nums);
    std::sort(sorted.begin(), sorted.end());
    std::vector<long long> fact(n + 1);
    std::vector<long long> invFact(n + 1);
    fact[0] = 1LL;
    for (int i = 1; i <= n; ++i) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    auto modPow = [&](long long base, long long exp) -> long long {
        long long res = 1LL;
        long long b = base % MOD;
        long long e = exp;
        while (e > 0) {
            if (e & 1LL) res = (res * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1LL;
        }
        return res;
    };
    auto modInv = [&](long long x) -> long long {
        return modPow(x, MOD - 2LL);
    };
    invFact[n] = modInv(fact[n]);
    for (int i = n - 1; i >= 0; --i) {
        invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
    }
    auto comb = [&](int m, int r) -> long long {
        if (r < 0 || r > m) return 0LL;
        return (((fact[m] * invFact[r]) % MOD) * invFact[m - r]) % MOD;
    };
    long long ans = 0LL;
    int maxChoose = k - 1;
    for (int i = 0; i < n; ++i) {
        int left = i;
        int right = n - 1 - i;
        long long waysMax = 0LL;
        int upMax = std::min(maxChoose, left);
        for (int t = 0; t <= upMax; ++t) {
            waysMax = (waysMax + comb(left, t)) % MOD;
        }
        long long waysMin = 0LL;
        int upMin = std::min(maxChoose, right);
        for (int t = 0; t <= upMin; ++t) {
            waysMin = (waysMin + comb(right, t)) % MOD;
        }
        long long val = static_cast<long long>(sorted[i]) % MOD;
        long long contrib = (val * ((waysMax + waysMin) % MOD)) % MOD;
        ans = (ans + contrib) % MOD;
    }
    return ans;
}

