static vector<vector<pair<int,int>>> adj;
static vector<int> nodeVals;
static long long bestLen;
static int bestNodes;

void dfs(int u, int parent, int leftBound, long long curDist,
         vector<int>& path, vector<long long>& distPath,
         unordered_map<int,int>& lastPos) {
    path.push_back(u);
    distPath.push_back(curDist);
    int depthIdx = (int)path.size() - 1;

    int prevIdx = -1;
    auto it = lastPos.find(nodeVals[u]);
    if (it != lastPos.end()) prevIdx = it->second;

    int newLeft = leftBound;
    if (prevIdx != -1) newLeft = max(newLeft, prevIdx + 1);

    long long length = curDist - (newLeft == 0 ? 0LL : distPath[newLeft]);
    int nodesCnt = depthIdx - newLeft + 1;

    if (length > bestLen || (length == bestLen && nodesCnt < bestNodes)) {
        bestLen = length;
        bestNodes = nodesCnt;
    }

    int savedPrev = prevIdx;
    lastPos[nodeVals[u]] = depthIdx;

    for (const auto& p : adj[u]) {
        int v = p.first;
        int w = p.second;
        if (v == parent) continue;
        dfs(v, u, newLeft, curDist + w, path, distPath, lastPos);
    }

    if (savedPrev == -1) lastPos.erase(nodeVals[u]);
    else lastPos[nodeVals[u]] = savedPrev;

    path.pop_back();
    distPath.pop_back();
}

vector<long long> longestSpecialPath(const vector<vector<int>>& edges, const vector<int>& nums) {
    int n = (int)nums.size();
    nodeVals = nums;
    adj.assign(n, {});
    for (const auto& e : edges) {
        int u = e[0], v = e[1], w = e[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    bestLen = 0;
    bestNodes = 1;

    vector<int> path;
    vector<long long> distPath;
    unordered_map<int,int> lastPos;
    dfs(0, -1, 0, 0LL, path, distPath, lastPos);

    return {bestLen, bestNodes};
}

