using namespace std;

const long long MOD = 1000000007LL;

long long modPow(long long a, long long e) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int sumManhattanDistances(int m, int n, int k) {
    int N = m * n;
    if (k < 2) return 0;
    // factorials up to N
    vector<long long> fact(N + 1), invFact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;
    invFact[N] = modPow(fact[N], MOD - 2);
    for (int i = N; i > 0; --i) invFact[i - 1] = invFact[i] * i % MOD;

    auto C = [&](int nn, int kk) -> long long {
        if (kk < 0 || kk > nn) return 0;
        return fact[nn] * invFact[kk] % MOD * invFact[nn - kk] % MOD;
    };

    long long ways = C(N - 2, k - 2); // number of arrangements containing a given unordered pair

    long long inv6 = modPow(6, MOD - 2);

    long long m_mod = m % MOD;
    long long n_mod = n % MOD;

    long long m3 = m_mod * m_mod % MOD * m_mod % MOD;
    long long n3 = n_mod * n_mod % MOD * n_mod % MOD;

    long long rowPart = ( (m3 - m_mod + MOD) % MOD ) * inv6 % MOD; // (m^3 - m)/6
    long long colPart = ( (n3 - n_mod + MOD) % MOD ) * inv6 % MOD; // (n^3 - n)/6

    long long n2 = n_mod * n_mod % MOD;
    long long m2 = m_mod * m_mod % MOD;

    long long rowSum = n2 * rowPart % MOD;
    long long colSum = m2 * colPart % MOD;

    long long totalPairDist = (rowSum + colSum) % MOD;

    long long answer = ways * totalPairDist % MOD;
    return (int)answer;
}

