class Solution {
public:
    int minCost(int n, vector<vector<int>>& cost) {
        int half = n / 2;
        map<pair<int,int>, long long> dp;
        for (int cL = 0; cL < 3; cL++) for (int cR = 0; cR < 3; cR++) if (cL != cR) {
            dp[{cL, cR}] = cost[0][cL] + cost[n - 1][cR];
        }
        for (int i = 1; i < half; i++) {
            int j = n - 1 - i;
            map<pair<int,int>, long long> newDp;
            for (int cL = 0; cL < 3; cL++) for (int cR = 0; cR < 3; cR++) {
                if (cL == cR) continue;
                long long best = LLONG_MAX;
                for (int pL = 0; pL < 3; pL++) for (int pR = 0; pR < 3; pR++) {
                    if (pL == pR || pL == cL || pR == cR) continue;
                    auto it = dp.find({pL, pR});
                    if (it != dp.end()) best = min(best, it->second);
                }
                if (best < LLONG_MAX) newDp[{cL, cR}] = best + cost[i][cL] + cost[j][cR];
            }
            dp = newDp;
        }
        long long ans = LLONG_MAX;
        for (auto& kv : dp) ans = min(ans, kv.second);
        return (int) ans;
    }
};

