long long maxMinSumAtMostK(const std::vector<long long>& nums, long long k) {
    size_t n = nums.size();
    std::vector<long long> leftGreater(n), rightGreater(n), leftSmaller(n), rightSmaller(n);
    std::vector<int> stack;

    // previous greater (strict)
    for (size_t i = 0; i < n; ++i) {
        while (!stack.empty() && nums[stack.back()] <= nums[i]) stack.pop_back();
        leftGreater[i] = stack.empty() ? -1 : stack.back();
        stack.push_back(static_cast<int>(i));
    }

    // next greater or equal
    stack.clear();
    for (long long i = static_cast<long long>(n) - 1; i >= 0; --i) {
        while (!stack.empty() && nums[stack.back()] < nums[i]) stack.pop_back();
        rightGreater[i] = stack.empty() ? static_cast<long long>(n) : stack.back();
        stack.push_back(static_cast<int>(i));
    }

    // previous smaller (strict)
    stack.clear();
    for (size_t i = 0; i < n; ++i) {
        while (!stack.empty() && nums[stack.back()] >= nums[i]) stack.pop_back();
        leftSmaller[i] = stack.empty() ? -1 : stack.back();
        stack.push_back(static_cast<int>(i));
    }

    // next smaller or equal
    stack.clear();
    for (long long i = static_cast<long long>(n) - 1; i >= 0; --i) {
        while (!stack.empty() && nums[stack.back()] > nums[i]) stack.pop_back();
        rightSmaller[i] = stack.empty() ? static_cast<long long>(n) : stack.back();
        stack.push_back(static_cast<int>(i));
    }

    long long S = k + 1;
    auto countPairs = [&](long long L, long long R) -> long long {
        long long limit = S - R;
        long long a = 0;
        if (limit > 0) a = std::min(L, limit);
        long long cnt = a * R;
        long long start = a + 1;
        long long end = std::min(L, S - 1);
        if (start <= end) {
            long long num = end - start + 1;
            long long sum = num * S - (start + end) * num / 2;
            cnt += sum;
        }
        return cnt;
    };

    long long ans = 0;
    for (size_t i = 0; i < n; ++i) {
        long long Lmax = static_cast<long long>(i) - leftGreater[i];
        long long Rmax = rightGreater[i] - static_cast<long long>(i);
        long long pairsMax = countPairs(Lmax, Rmax);
        ans += nums[i] * pairsMax;

        long long Lmin = static_cast<long long>(i) - leftSmaller[i];
        long long Rmin = rightSmaller[i] - static_cast<long long>(i);
        long long pairsMin = countPairs(Lmin, Rmin);
        ans += nums[i] * pairsMin;
    }
    return ans;
}

