long long maxFreeTime(int eventTime, int k, const std::vector<int>& startTime, const std::vector<int>& endTime) {
    size_t n = startTime.size();
    size_t m = n + 1;
    std::vector<long long> gaps(m);
    gaps[0] = startTime[0];
    for (size_t i = 1; i < n; ++i) {
        gaps[i] = static_cast<long long>(startTime[i]) - endTime[i - 1];
    }
    gaps[m - 1] = static_cast<long long>(eventTime) - endTime[n - 1];
    long long totalFree = 0;
    for (auto g : gaps) totalFree += g;
    if (k >= static_cast<int>(m - 1)) return totalFree;
    std::vector<std::pair<long long, size_t>> sorted;
    sorted.reserve(m);
    for (size_t i = 0; i < m; ++i) {
        sorted.emplace_back(gaps[i], i);
    }
    std::sort(sorted.begin(), sorted.end(),
              [](const std::pair<long long, size_t>& a, const std::pair<long long, size_t>& b) {
                  return a.first > b.first;
              });
    std::vector<long long> prefix(m + 1);
    prefix[0] = 0;
    for (size_t i = 0; i < m; ++i) {
        prefix[i + 1] = prefix[i] + sorted[i].first;
    }
    std::vector<int> rank(m);
    for (size_t i = 0; i < m; ++i) {
        rank[sorted[i].second] = static_cast<int>(i);
    }
    long long answer = 0;
    for (size_t i = 0; i < m; ++i) {
        long long sumTopK;
        if (rank[i] < k) {
            sumTopK = prefix[k + 1] - gaps[i];
        } else {
            sumTopK = prefix[k];
        }
        long long candidate = gaps[i] + sumTopK;
        if (candidate > answer) answer = candidate;
    }
    return answer;
}

