std::vector<std::vector<int>> frequencies_of_shortest_supersequences(const std::vector<std::string>& words) {
    std::set<char> letters_set;
    for (const std::string& w : words) {
        for (char c : w) {
            letters_set.insert(c);
        }
    }
    std::vector<char> letters(letters_set.begin(), letters_set.end());
    int n = static_cast<int>(letters.size());
    std::unordered_map<char, int> idx;
    for (int i = 0; i < n; ++i) {
        idx[letters[i]] = i;
    }

    std::vector<uint32_t> out_mask(n, 0);
    std::vector<int> self_loop(n, 0);
    for (const std::string& w : words) {
        char a = w[0];
        char b = w[1];
        int i = idx[a];
        int j = idx[b];
        if (i == j) {
            self_loop[i] = 1;
        } else {
            out_mask[i] |= (1u << j);
        }
    }

    int full_mask = (1 << n) - 1;
    const int INF = 1e9;
    std::vector<int> dp_cost(1 << n, INF);
    dp_cost[0] = 0;

    for (int mask = 1; mask <= full_mask; ++mask) {
        int best = INF;
        for (int v = 0; v < n; ++v) {
            if (mask & (1 << v)) {
                int prev = mask ^ (1 << v);
                int cost_v = __builtin_popcount(out_mask[v] & static_cast<uint32_t>(prev));
                int cand = dp_cost[prev] + cost_v;
                if (cand < best) best = cand;
            }
        }
        dp_cost[mask] = best;
    }

    std::vector<std::set<std::vector<int>>> dp_vec(1 << n);
    std::vector<int> zero_vec(n, 0);
    dp_vec[0].insert(zero_vec);

    for (int mask = 1; mask <= full_mask; ++mask) {
        for (int v = 0; v < n; ++v) {
            if (mask & (1 << v)) {
                int prev = mask ^ (1 << v);
                int cost_v = __builtin_popcount(out_mask[v] & static_cast<uint32_t>(prev));
                if (dp_cost[mask] == dp_cost[prev] + cost_v) {
                    for (const std::vector<int>& vec : dp_vec[prev]) {
                        std::vector<int> lst = vec;
                        lst[v] += cost_v;
                        dp_vec[mask].insert(std::move(lst));
                    }
                }
            }
        }
    }

    std::vector<std::vector<int>> result;
    for (const std::vector<int>& vec : dp_vec[full_mask]) {
        std::vector<int> freq(26, 0);
        for (int i = 0; i < n; ++i) {
            char ch = letters[i];
            int cnt = 1 + self_loop[i] + vec[i];
            freq[static_cast<int>(ch - 'a')] = cnt;
        }
        result.push_back(std::move(freq));
    }
    return result;
}

