std::string minimumCostGoodCaption(std::string s) {
    int n = s.size();
    if (n == 2 && s[0] != s[1]) return "";
    std::map<char,int> freq;
    for (char c : s) freq[c]++;
    int maxFreq = 0;
    for (auto& p : freq) maxFreq = std::max(maxFreq, p.second);
    char chosen = 0;
    for (auto& p : freq) { if (p.second == maxFreq) { chosen = p.first; break; } } // map iterates sorted by key -> smallest first
    return std::string(n, chosen);
}

