int maxManhattanDistanceAfterKChanges(const std::string& s, int k) {
    int x = 0, y = 0;
    int inward = 0;
    int answer = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        bool outward;
        if (c == 'N') outward = (y >= 0);
        else if (c == 'S') outward = (y <= 0);
        else if (c == 'E') outward = (x >= 0);
        else outward = (x <= 0); // 'W'
        if (!outward) ++inward;
        if (c == 'N') ++y;
        else if (c == 'S') --y;
        else if (c == 'E') ++x;
        else --x; // 'W'
        int dist = std::abs(x) + std::abs(y);
        int best = dist + 2 * std::min(k, inward);
        if (best > answer) answer = best;
    }
    return answer;
}

#include <bits/stdc++.h>

static long long gcd_ll(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

long long minimumIncrements(const std::vector<int>& nums, const std::vector<int>& target) {
    int n = static_cast<int>(nums.size());
    int m = static_cast<int>(target.size());
    int fullMask = (1 << m) - 1;
    const long long INF = (long long)4e18;

    std::vector<long long> lcmMask(1 << m, 1);
    for (int mask = 1; mask <= fullMask; ++mask) {
        int bit = __builtin_ctz(mask);
        int prev = mask ^ (1 << bit);
        long long prevL = (prev == 0) ? 1 : lcmMask[prev];
        long long t = target[bit];
        long long g = gcd_ll(prevL, t);
        long long l = prevL / g * t;
        lcmMask[mask] = l;
    }

    std::vector<long long> dp(1 << m, INF);
    dp[0] = 0;

    for (int i = 0; i < n; ++i) {
        std::vector<long long> costMask(1 << m, 0);
        for (int mask = 1; mask <= fullMask; ++mask) {
            long long L = lcmMask[mask];
            long long cur = nums[i];
            long long mult = (cur + L - 1) / L;
            long long nxt = mult * L;
            costMask[mask] = nxt - cur;
        }

        std::vector<long long> ndp = dp;
        for (int mask = 0; mask <= fullMask; ++mask) {
            if (dp[mask] == INF) continue;
            for (int sub = 0; sub <= fullMask; ++sub) {
                int nmask = mask | sub;
                long long cand = dp[mask] + costMask[sub];
                if (cand < ndp[nmask]) ndp[nmask] = cand;
            }
        }
        dp.swap(ndp);
    }

    return dp[fullMask];
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>

struct Interval {
    int start;
    int end;
    int dur;
    Interval(int s, int e) : start(s), end(e), dur(e - s) {}
};

int computeMaxGap(const std::vector<Interval>& remaining, int newStart, int newEnd, int eventTime) {
    std::vector<Interval> all = remaining;
    size_t idx = 0;
    while (idx < all.size() && all[idx].start < newStart) {
        ++idx;
    }
    all.insert(all.begin() + idx, Interval(newStart, newEnd));
    int prevEnd = 0;
    int maxGap = 0;
    for (const Interval& iv : all) {
        maxGap = std::max(maxGap, iv.start - prevEnd);
        prevEnd = iv.end;
    }
    maxGap = std::max(maxGap, eventTime - prevEnd);
    return maxGap;
}

int maxFreeTime(int eventTime, std::vector<int> startTime, std::vector<int> endTime) {
    int n = static_cast<int>(startTime.size());
    std::vector<Interval> intervals;
    intervals.reserve(n);
    for (int i = 0; i < n; ++i) {
        intervals.emplace_back(startTime[i], endTime[i]);
    }
    std::sort(intervals.begin(), intervals.end(),
              [](const Interval& a, const Interval& b) { return a.start < b.start; });

    int best = 0;
    int prevEnd = 0;
    for (const Interval& iv : intervals) {
        best = std::max(best, iv.start - prevEnd);
        prevEnd = iv.end;
    }
    best = std::max(best, eventTime - prevEnd);

    for (int i = 0; i < n; ++i) {
        const Interval& moved = intervals[i];
        std::vector<Interval> remaining;
        remaining.reserve(n - 1);
        for (int j = 0; j < n; ++j) {
            if (j != i) remaining.push_back(intervals[j]);
        }

        std::vector<std::pair<int, int>> gaps;
        int prev = 0;
        for (const Interval& iv : remaining) {
            if (iv.start > prev) {
                gaps.emplace_back(prev, iv.start);
            }
            prev = iv.end;
        }
        if (eventTime > prev) {
            gaps.emplace_back(prev, eventTime);
        }

        for (const auto& g : gaps) {
            int gapLen = g.second - g.first;
            if (gapLen < moved.dur) continue;

            int newStart = g.first;
            int newEnd = newStart + moved.dur;
            best = std::max(best, computeMaxGap(remaining, newStart, newEnd, eventTime));

            if (gapLen > moved.dur) {
                newStart = g.second - moved.dur;
                newEnd = g.second;
                best = std::max(best, computeMaxGap(remaining, newStart, newEnd, eventTime));
            }
        }
    }

    return best;
}

