std::vector<std::vector<int>> sortMatrixByDiagonals(std::vector<std::vector<int>> grid) {
    int n = static_cast<int>(grid.size());
    for (int k = -(n - 1); k <= n - 1; ++k) {
        std::vector<int> values;
        std::vector<std::pair<int, int>> positions;
        for (int i = 0; i < n; ++i) {
            int j = i - k;
            if (j >= 0 && j < n) {
                values.push_back(grid[i][j]);
                positions.emplace_back(i, j);
            }
        }
        if (k >= 0) {
            std::sort(values.begin(), values.end(), std::greater<int>());
        } else {
            std::sort(values.begin(), values.end());
        }
        for (size_t idx = 0; idx < positions.size(); ++idx) {
            grid[positions[idx].first][positions[idx].second] = values[idx];
        }
    }
    return grid;
}

#include <bits/stdc++.h>

std::vector<int> assignElements(const std::vector<int>& groups, const std::vector<int>& elements) {
    const int MAXV = 100000;
    const int INF = 1e9;
    std::vector<int> firstIdx(MAXV + 1, INF);
    for (int i = 0; i < (int)elements.size(); ++i) {
        int v = elements[i];
        if (v <= MAXV && firstIdx[v] == INF) {
            firstIdx[v] = i;
        }
    }
    std::vector<int> result;
    result.reserve(groups.size());
    for (int g : groups) {
        int best = INF;
        for (int d = 1; d * d <= g; ++d) {
            if (g % d == 0) {
                if (d <= MAXV && firstIdx[d] < best) best = firstIdx[d];
                int d2 = g / d;
                if (d2 != d && d2 <= MAXV && firstIdx[d2] < best) best = firstIdx[d2];
            }
        }
        if (best == INF) result.push_back(-1);
        else result.push_back(best);
    }
    return result;
}

#include <bits/stdc++.h>

int maxDifferenceEvenOdd(const std::string& s, int k) {
    int n = static_cast<int>(s.size());
    if (k > n) return -1;
    int even = 0, odd = 0;
    for (int i = 0; i < k; ++i) {
        int d = s[i] - '0';
        if (d % 2 == 0) ++even;
        else ++odd;
    }
    int best = std::numeric_limits<int>::min();
    if (even > 0 && odd > 0) best = std::max(best, even - odd);
    for (int i = k; i < n; ++i) {
        int out = s[i - k] - '0';
        if (out % 2 == 0) --even;
        else --odd;
        int in = s[i] - '0';
        if (in % 2 == 0) ++even;
        else ++odd;
        if (even > 0 && odd > 0) best = std::max(best, even - odd);
    }
    return (best <= 0) ? -1 : best;
}

