long long maxScore(const std::vector<int>& points, long long m) {
    long long maxP = 0;
    for (int v : points) if (v > maxP) maxP = v;
    long long low = 0, high = maxP * m;
    while (low < high) {
        long long mid = (low + high + 1) / 2;
        long long need = 0;
        for (int v : points) {
            need += (mid + v - 1) / v;
            if (need > m) break;
        }
        if (need <= m) low = mid;
        else high = mid - 1;
    }
    return low;
}

