long long countDivisibleSubstrings(const std::string& s) {
    std::vector<std::vector<long long>> cnt(10);
    for (int d = 1; d <= 9; ++d) cnt[d].assign(d, 0);
    long long answer = 0;
    for (char ch : s) {
        int cur = ch - '0';
        std::vector<std::vector<long long>> ndcnt(10);
        for (int d = 1; d <= 9; ++d) {
            ndcnt[d].assign(d, 0);
            for (int r = 0; r < d; ++r) {
                long long ways = cnt[d][r];
                if (ways) {
                    int nr = (r * 10 + cur) % d;
                    ndcnt[d][nr] += ways;
                }
            }
            int nr = cur % d;
            ndcnt[d][nr] += 1; // start new substring with only cur
        }
        if (cur != 0) {
            answer += ndcnt[cur][0];
        }
        cnt.swap(ndcnt);
    }
    return answer;
}

