long long sumGoodNumbers(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    long long total = 0;
    for (int i = 0; i < n; ++i) {
        bool good = true;
        int left = i - k;
        if (left >= 0 && !(nums[i] > nums[left])) {
            good = false;
        }
        int right = i + k;
        if (right < n && !(nums[i] > nums[right])) {
            good = false;
        }
        if (good) {
            total += nums[i];
        }
    }
    return total;
}

#include <bits/stdc++.h>
#include <cmath>

double separateSquares(std::vector<std::vector<int>>& squares) {
    using ld = long double;
    ld total = 0;
    ld low = 1e18, high = -1e18;
    for (const auto& sq : squares) {
        ld y = sq[1];
        ld l = sq[2];
        total += l * l;
        low = std::min(low, y);
        high = std::max(high, y + l);
    }
    ld half = total / 2.0;
    auto above = [&](ld h) {
        ld sum = 0;
        for (const auto& sq : squares) {
            ld y = sq[1];
            ld l = sq[2];
            if (h <= y) {
                sum += l * l;
            } else if (h < y + l) {
                sum += (y + l - h) * l;
            }
        }
        return sum;
    };
    ld lo = low, hi = high;
    for (int i = 0; i < 100; ++i) {
        ld mid = (lo + hi) / 2;
        if (above(mid) > half) lo = mid;
        else hi = mid;
    }
    ld result = (lo + hi) / 2;
    double rounded = std::round(static_cast<double>(result) * 100000.0) / 100000.0;
    return rounded;
}

