bool findSpecialSubstring(const std::string& s, int k) {
    if (k <= 0) return false;
    int consecutive = 1;
    for (size_t i = 1; i < s.size(); ++i) {
        if (s[i] == s[i - 1]) {
            ++consecutive;
        } else {
            consecutive = 1;
        }
        if (consecutive >= k) return true;
    }
    return false;
}

#include <bits/stdc++.h>
#include <string>
#include <vector>
#include <climits>

int shortestMatchingSubstring(const std::string& s, const std::string& p) {
    size_t first = p.find('*');
    size_t second = p.find('*', first + 1);
    std::string A = p.substr(0, first);
    std::string B = p.substr(first + 1, second - first - 1);
    std::string C = p.substr(second + 1);
    int n = static_cast<int>(s.size());

    auto findMatches = [&](const std::string& sub) -> std::vector<int> {
        std::vector<int> res;
        if (sub.empty()) {
            res.reserve(n + 1);
            for (int i = 0; i <= n; ++i) res.push_back(i);
            return res;
        }
        int m = static_cast<int>(sub.size());
        for (int i = 0; i + m <= n; ++i) {
            if (s.compare(i, m, sub) == 0) res.push_back(i);
        }
        return res;
    };

    std::vector<int> startsA = findMatches(A);
    std::vector<int> startsB = findMatches(B);
    std::vector<int> startsC = findMatches(C);

    std::vector<int> nextB(n + 1, -1);
    size_t idxB = 0;
    for (int pos = 0; pos <= n; ++pos) {
        while (idxB < startsB.size() && startsB[idxB] < pos) ++idxB;
        if (idxB < startsB.size()) nextB[pos] = startsB[idxB];
    }

    std::vector<int> nextC(n + 1, -1);
    size_t idxC = 0;
    for (int pos = 0; pos <= n; ++pos) {
        while (idxC < startsC.size() && startsC[idxC] < pos) ++idxC;
        if (idxC < startsC.size()) nextC[pos] = startsC[idxC];
    }

    int best = INT_MAX;
    int lenA = static_cast<int>(A.size());
    int lenB = static_cast<int>(B.size());
    int lenC = static_cast<int>(C.size());

    for (int i : startsA) {
        int posB = i + lenA;
        int j = nextB[posB];
        if (j == -1) continue;
        int posC = j + lenB;
        int k = nextC[posC];
        if (k == -1) continue;
        int len = (k + lenC) - i;
        if (len < best) best = len;
    }

    return best == INT_MAX ? -1 : best;
}

#include <bits/stdc++.h>
#include <vector>
