double separateSquaresII(const std::vector<std::vector<double>>& squares) {
    auto lowerBound = [](const std::vector<double>& arr, double target) -> std::size_t {
        std::size_t l = 0, r = arr.size();
        while (l < r) {
            std::size_t m = (l + r) >> 1;
            if (arr[m] < target) l = m + 1;
            else r = m;
        }
        return l;
    };

    struct Event {
        double x;
        int type;
        double y1;
        double y2;
    };

    auto unionArea = [&](const std::vector<std::vector<double>>& rects) -> double {
        if (rects.empty()) return 0.0;
        std::vector<Event> events;
        std::vector<double> yVals;
        events.reserve(rects.size() * 2);
        yVals.reserve(rects.size() * 2);
        for (const auto& r : rects) {
            double x1 = r[0], x2 = r[1], y1 = r[2], y2 = r[3];
            events.push_back({x1, 1, y1, y2});
            events.push_back({x2, -1, y1, y2});
            yVals.push_back(y1);
            yVals.push_back(y2);
        }
        std::sort(events.begin(), events.end(), [](const Event& a, const Event& b) {
            return a.x < b.x;
        });
        std::sort(yVals.begin(), yVals.end());
        std::vector<double> uniqY;
        uniqY.reserve(yVals.size());
        for (std::size_t i = 0; i < yVals.size(); ++i) {
            if (i == 0 || yVals[i] != yVals[i - 1]) uniqY.push_back(yVals[i]);
        }
        std::size_t m = uniqY.size() > 0 ? uniqY.size() - 1 : 0;
        if (m == 0) return 0.0;
        std::vector<int> cnt((m + 2) * 4);
        std::vector<double> len((m + 2) * 4);

        std::function<void(std::size_t, std::size_t, std::size_t, std::size_t, std::size_t, int)> update;
        update = [&](std::size_t node, std::size_t l, std::size_t r, std::size_t ql, std::size_t qr, int delta) {
            if (ql > r || qr < l) return;
            if (ql <= l && r <= qr) {
                cnt[node] += delta;
            } else {
                std::size_t mid = (l + r) >> 1;
                update(node * 2, l, mid, ql, qr, delta);
                update(node * 2 + 1, mid + 1, r, ql, qr, delta);
            }
            if (cnt[node] > 0) {
                len[node] = uniqY[r + 1] - uniqY[l];
            } else if (l == r) {
                len[node] = 0.0;
            } else {
                len[node] = len[node * 2] + len[node * 2 + 1];
            }
        };

        double area = 0.0;
        double prevX = events[0].x;
        for (const auto& e : events) {
            double dx = e.x - prevX;
            if (dx != 0.0) area += len[1] * dx;
            std::size_t y1Idx = lowerBound(uniqY, e.y1);
            std::size_t y2Idx = lowerBound(uniqY, e.y2);
            if (y2Idx > 0) --y2Idx;
            if (y1Idx <= y2Idx) update(1, 0, m - 1, y1Idx, y2Idx, e.type);
            prevX = e.x;
        }
        return area;
    };

    std::vector<std::vector<double>> fullRects;
    fullRects.reserve(squares.size());
    for (const auto& s : squares) {
        double x = s[0], y = s[1], l = s[2];
        fullRects.push_back({x, x + l, y, y + l});
    }
    double totalArea = unionArea(fullRects);
    double halfArea = totalArea / 2.0;

    double low = std::numeric_limits<double>::infinity();
    double high = -std::numeric_limits<double>::infinity();
    for (const auto& s : squares) {
        double x = s[0], y = s[1], l = s[2];
        if (y < low) low = y;
        if (y + l > high) high = y + l;
    }

    for (int iter = 0; iter < 60; ++iter) {
        double mid = (low + high) * 0.5;
        std::vector<std::vector<double>> rects;
        rects.reserve(squares.size());
        for (const auto& s : squares) {
            double x = s[0], y = s[1], l = s[2];
            double y2 = std::min(y + l, mid);
            if (y2 > y) rects.push_back({x, x + l, y, y2});
        }
        double areaBelow = unionArea(rects);
        if (areaBelow >= halfArea) high = mid;
        else low = mid;
    }
    return high;
}

