long long maxSumWithAtMostK(const std::vector<std::vector<int>>& grid, const std::vector<int>& limits, int k) {
    std::vector<int> candidates;
    for (size_t i = 0; i < grid.size(); ++i) {
        const std::vector<int>& row = grid[i];
        std::vector<int> sorted = row;
        std::sort(sorted.begin(), sorted.end(), std::greater<int>());
        int limit_i = 0;
        if (i < limits.size()) limit_i = limits[i];
        size_t take = std::min(static_cast<size_t>(limit_i), sorted.size());
        for (size_t j = 0; j < take; ++j) {
            candidates.push_back(sorted[j]);
        }
    }
    std::sort(candidates.begin(), candidates.end(), std::greater<int>());
    size_t limit = std::min(static_cast<size_t>(k), candidates.size());
    long long sum = 0;
    for (size_t i = 0; i < limit; ++i) {
        sum += candidates[i];
    }
    return sum;
}

