long long maxWeight(const std::vector<int>& pizzas) {
    std::size_t n = pizzas.size();
    std::size_t k = n / 4;
    const long long NEG = std::numeric_limits<long long>::min() / 4;
    std::vector<long long> dp_not(k + 1, NEG), dp_take(k + 1, NEG);
    dp_not[0] = 0;
    for (std::size_t i = 0; i < n; ++i) {
        std::vector<long long> new_not(k + 1, NEG), new_take(k + 1, NEG);
        for (std::size_t j = 0; j <= k; ++j) {
            new_not[j] = std::max(dp_not[j], dp_take[j]);
            if (j > 0 && dp_not[j - 1] != NEG) {
                new_take[j] = dp_not[j - 1] + static_cast<long long>(pizzas[i]);
            }
        }
        dp_not.swap(new_not);
        dp_take.swap(new_take);
    }
    return std::max(dp_not[k], dp_take[k]);
}

