static std::size_t lowerBound(const std::vector<long long>& arr, long long target, std::size_t start) {
    std::size_t l = start, r = arr.size();
    while (l < r) {
        std::size_t m = (l + r) >> 1;
        if (arr[m] < target) l = m + 1;
        else r = m;
    }
    return l;
}

long long maxMinManhattanDistance(long long side, const std::vector<std::pair<long long, long long>>& points, int k) {
    long long P = 4 * side;
    std::vector<long long> s;
    s.reserve(points.size());
    for (const auto& p : points) {
        long long x = p.first;
        long long y = p.second;
        long long pos;
        if (y == 0) {
            pos = x; // bottom side
        } else if (x == side) {
            pos = side + y; // right side
        } else if (y == side) {
            pos = 3 * side - x; // top side
        } else { // x == 0
            pos = 4 * side - y; // left side
        }
        s.push_back(pos);
    }
    std::sort(s.begin(), s.end());
    std::size_t N = s.size();
    std::vector<long long> dup;
    dup.reserve(2 * N);
    dup.insert(dup.end(), s.begin(), s.end());
    for (long long v : s) dup.push_back(v + P);

    auto feasible = [&](long long d) -> bool {
        for (std::size_t i = 0; i < N; ++i) {
            int cnt = 1;
            long long lastPos = dup[i];
            std::size_t idx = i;
            while (cnt < k) {
                long long target = lastPos + d;
                std::size_t j = lowerBound(dup, target, idx + 1);
                if (j >= i + N) break;
                ++cnt;
                lastPos = dup[j];
                idx = j;
            }
            if (cnt == k) {
                long long span = lastPos - dup[i];
                if (span <= P - d) return true;
            }
        }
        return false;
    };

    long long low = 0, high = P / 2;
    while (low < high) {
        long long mid = (low + high + 1) / 2;
        if (feasible(mid)) low = mid;
        else high = mid - 1;
    }
    return low;
}

