std::string smallestGeneratedString(const std::string& str1, const std::string& str2) {
    size_t n = str1.size();
    size_t m = str2.size();
    size_t L = n + m - 1;
    std::vector<char> word(L, 0);
    for (size_t i = 0; i < n; ++i) {
        if (str1[i] == 'T') {
            for (size_t j = 0; j < m; ++j) {
                size_t pos = i + j;
                char c = str2[j];
                if (word[pos] == 0) {
                    word[pos] = c;
                } else if (word[pos] != c) {
                    return "";
                }
            }
        }
    }
    for (size_t i = 0; i < n; ++i) {
        if (str1[i] == 'F') {
            bool alreadyDiff = false;
            for (size_t j = 0; j < m; ++j) {
                size_t pos = i + j;
                char c = str2[j];
                if (word[pos] != 0 && word[pos] != c) {
                    alreadyDiff = true;
                    break;
                }
            }
            if (alreadyDiff) continue;
            bool changed = false;
            for (size_t j = m; j-- > 0;) {
                size_t pos = i + j;
                if (word[pos] == 0) {
                    char c = str2[j];
                    word[pos] = (c == 'a' ? 'b' : 'a');
                    changed = true;
                    break;
                }
            }
            if (!changed) return "";
        }
    }
    for (size_t i = 0; i < L; ++i) {
        if (word[i] == 0) word[i] = 'a';
    }
    return std::string(word.begin(), word.end());
}

