static const unsigned long long INF = 1000000000000000000ULL; // 1e18

static unsigned long long mul_cap(unsigned long long a, unsigned long long b) {
    if (a == 0 || b == 0) return 0;
    if (a > INF / b) return INF;
    unsigned long long res = a * b;
    return res > INF ? INF : res;
}

vector<int> getPermutation(int n, long long k) {
    int totalOdd = (n + 1) / 2;
    int totalEven = n / 2;
    vector<vector<array<unsigned long long, 2>>> dp(totalOdd + 1,
        vector<array<unsigned long long, 2>>(totalEven + 1));
    dp[0][0][0] = dp[0][0][1] = 1;
    for (int o = 0; o <= totalOdd; ++o) {
        for (int e = 0; e <= totalEven; ++e) {
            if (o == 0 && e == 0) continue;
            unsigned long long val0 = 0, val1 = 0;
            if (o > 0) val0 = mul_cap((unsigned long long)o, dp[o - 1][e][1]);
            if (e > 0) val1 = mul_cap((unsigned long long)e, dp[o][e - 1][0]);
            dp[o][e][0] = val0;
            dp[o][e][1] = val1;
        }
    }

    vector<int> ans;
    vector<char> used(n + 1, 0);
    int oddLeft = totalOdd, evenLeft = totalEven;
    int lastParity = -1;
    unsigned long long K = (unsigned long long)k;

    for (int pos = 0; pos < n; ++pos) {
        bool found = false;
        for (int x = 1; x <= n; ++x) {
            if (used[x]) continue;
            int parity = x % 2;
            if (pos > 0 && parity == lastParity) continue;
            int o = oddLeft - (parity == 1);
            int e = evenLeft - (parity == 0);
            unsigned long long cnt = dp[o][e][parity];
            if (cnt >= K) {
                ans.push_back(x);
                used[x] = 1;
                oddLeft = o;
                evenLeft = e;
                lastParity = parity;
                found = true;
                break;
            } else {
                K -= cnt;
            }
        }
        if (!found) return vector<int>();
    }
    return ans;
}

#include <bits/stdc++.h>

int longestPalindromeSubseqAfterOperations(const std::string& s, int k) {
    int n = static_cast<int>(s.size());
    int K = k;
    auto dist = [](char a, char b) -> int {
        int diff = std::abs(a - b);
        return std::min(diff, 26 - diff);
    };
    std::vector<std::vector<std::vector<int>>> dp(
        n, std::vector<std::vector<int>>(n, std::vector<int>(K + 1, 0)));
    for (int i = 0; i < n; ++i) {
        for (int c = 0; c <= K; ++c) dp[i][i][c] = 1;
    }
    for (int len = 2; len <= n; ++len) {
        for (int l = 0; l + len - 1 < n; ++l) {
            int r = l + len - 1;
            int d = dist(s[l], s[r]);
            for (int c = 0; c <= K; ++c) {
                int best = std::max(dp[l + 1][r][c], dp[l][r - 1][c]);
                if (c >= d) {
                    int inner = (l + 1 <= r - 1) ? dp[l + 1][r - 1][c - d] : 0;
                    best = std::max(best, inner + 2);
                }
                dp[l][r][c] = best;
            }
        }
    }
    int ans = 0;
    for (int c = 0; c <= K; ++c) ans = std::max(ans, dp[0][n - 1][c]);
    return ans;
}

