int countUnplacedFruits(const std::vector<int>& fruits, const std::vector<int>& baskets) {
    int m = static_cast<int>(baskets.size());
    std::vector<int> sorted = baskets;
    std::sort(sorted.begin(), sorted.end());
    std::vector<int> parent(m + 1);
    for (int i = 0; i <= m; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    int unplaced = 0;
    for (int need : fruits) {
        int idx = std::upper_bound(sorted.begin(), sorted.end(), need) - sorted.begin();
        int avail = find(idx);
        if (avail == m) {
            ++unplaced;
        } else {
            parent[avail] = find(avail + 1);
        }
    }
    return unplaced;
}

