long long maxSubarrays(int n, const std::vector<std::pair<int, int>>& conflictingPairs) {
    auto countValid = [&](const std::vector<std::pair<int, int>>& pairs) -> long long {
        std::vector<std::vector<int>> ending(n + 1);
        for (const auto& pr : pairs) {
            int a = pr.first;
            int b = pr.second;
            if (a > b) std::swap(a, b);
            ending[b].push_back(a);
        }
        int left = 1;
        long long total = 0;
        for (int r = 1; r <= n; ++r) {
            const auto& list = ending[r];
            for (int a : list) {
                if (a + 1 > left) left = a + 1;
            }
            if (left <= r) {
                total += r - left + 1;
            }
        }
        return total;
    };

    long long best = 0;
    int m = static_cast<int>(conflictingPairs.size());
    for (int removeIdx = 0; removeIdx < m; ++removeIdx) {
        std::vector<std::pair<int, int>> remaining;
        remaining.reserve(m - 1);
        for (int i = 0; i < m; ++i) {
            if (i != removeIdx) remaining.push_back(conflictingPairs[i]);
        }
        long long cur = countValid(remaining);
        if (cur > best) best = cur;
    }
    return best;
}

