        for (auto& e : edges) {
            graph[e[0]].push_back({e[1], e[2]});
            graph[e[1]].push_back({e[0], e[2]});
        }
        array<int,2> lb0 = {0, 0};
        dfs(0, -1, lb0);
        return {maxLength, minNodes};
    }
    void dfs(int u, int prev, array<int,2> leftBoundary) {
        int prevDepth = lastSeenDepth.count(nums[u]) ? lastSeenDepth[nums[u]] : 0;
        lastSeenDepth[nums[u]] = prefix_.size();
        array<int,2> lb = leftBoundary;
        if (prevDepth != 0) {
            array<int,3> combined = {leftBoundary[0], leftBoundary[1], prevDepth};
            sort(combined.begin(), combined.end());
            lb = {combined[1], combined[2]};
        }
        int length = prefix_.back() - prefix_[lb[0]];
        int nodes = (int)prefix_.size() - lb[0];
        if (length > maxLength || (length == maxLength && nodes < minNodes)) {
            maxLength = length;
            minNodes = nodes;
        }
        for (auto& [v, w] : graph[u]) {
            if (v == prev) continue;
            prefix_.push_back(prefix_.back() + w);
            dfs(v, u, lb);
            prefix_.pop_back();
        }
        lastSeenDepth[nums[u]] = prevDepth;
    }
};

