std::vector<int> distanceToClosest(const std::vector<int>& nums, const std::vector<int>& queries) {
    int n = static_cast<int>(nums.size());
    std::unordered_map<int, std::vector<int>> positions;
    positions.reserve(n * 2);
    for (int i = 0; i < n; ++i) {
        positions[nums[i]].push_back(i);
    }
    std::vector<int> answer;
    answer.reserve(queries.size());
    for (int idx : queries) {
        int val = nums[idx];
        const std::vector<int>& vec = positions[val];
        if (vec.size() == 1) {
            answer.push_back(-1);
            continue;
        }
        auto it = std::lower_bound(vec.begin(), vec.end(), idx);
        size_t posIdx = static_cast<size_t>(it - vec.begin());
        size_t sz = vec.size();
        int nextIdx = vec[(posIdx + 1) % sz];
        int prevIdx = vec[(posIdx + sz - 1) % sz];
        int forward = (nextIdx - idx + n) % n;
        int backward = (idx - prevIdx + n) % n;
        answer.push_back(std::min(forward, backward));
    }
    return answer;
}

