int minimumQueriesToZeroArray(const std::vector<int>& nums, const std::vector<std::vector<int>>& queries) {
    std::vector<int> cur = nums;
    auto allZero = [&]() -> bool {
        for (int v : cur) {
            if (v != 0) return false;
        }
        return true;
    };
    if (allZero()) return 0;
    for (size_t i = 0; i < queries.size(); ++i) {
        int l = queries[i][0];
        int r = queries[i][1];
        int val = queries[i][2];
        for (int j = l; j <= r; ++j) {
            cur[j] = std::max(0, cur[j] - val);
        }
        if (allZero()) return static_cast<int>(i) + 1;
    }
    return -1;
}

