struct TrieNode {
    std::array<int, 26> next;
    int cnt;
    int depth;
    TrieNode() : cnt(0), depth(0) {
        next.fill(-1);
    }
};

std::vector<int> longestCommonPrefix(const std::vector<std::string>& words, int k) {
    int n = static_cast<int>(words.size());
    if (n - 1 < k) {
        return std::vector<int>(n, 0);
    }

    std::vector<TrieNode> nodes;
    nodes.emplace_back(); // root at index 0
    int maxWordLen = 0;

    for (const std::string& w : words) {
        int cur = 0;
        int d = 0;
        for (char ch : w) {
            int idx = ch - 'a';
            if (nodes[cur].next[idx] == -1) {
                TrieNode newNode;
                newNode.depth = d + 1;
                nodes.push_back(newNode);
                nodes[cur].next[idx] = static_cast<int>(nodes.size()) - 1;
            }
            cur = nodes[cur].next[idx];
            ++d;
            ++nodes[cur].cnt;
        }
        if (static_cast<int>(w.length()) > maxWordLen) maxWordLen = static_cast<int>(w.length());
    }

    std::vector<int> goodCount(maxWordLen + 1, 0);
    int globalMaxDepth = 0;
    for (size_t i = 1; i < nodes.size(); ++i) {
        const TrieNode& node = nodes[i];
        if (node.cnt >= k) {
            ++goodCount[node.depth];
            if (node.depth > globalMaxDepth) globalMaxDepth = node.depth;
        }
    }

    std::vector<int> answer(n, 0);

    auto shrinkMaxDepth = [&]() {
        while (globalMaxDepth > 0 && goodCount[globalMaxDepth] == 0) {
            --globalMaxDepth;
        }
    };

    for (int i = 0; i < n; ++i) {
        const std::string& w = words[i];
        int cur = 0;
        for (char ch : w) {
            int idx = ch - 'a';
            cur = nodes[cur].next[idx];
            TrieNode& node = nodes[cur];
            if (node.cnt == k) {
                --goodCount[node.depth];
                if (node.depth == globalMaxDepth && goodCount[node.depth] == 0) {
                    shrinkMaxDepth();
                }
            }
            --node.cnt;
        }

        answer[i] = globalMaxDepth;

        cur = 0;
        for (char ch : w) {
            int idx = ch - 'a';
            cur = nodes[cur].next[idx];
            TrieNode& node = nodes[cur];
            ++node.cnt;
            if (node.cnt == k) {
                ++goodCount[node.depth];
                if (node.depth > globalMaxDepth) globalMaxDepth = node.depth;
            }
        }
    }

    return answer;
}

