using namespace std;

static long long memo[11][91][91][2];
static bool seen[11][91][91][2];
static vector<int> dig;
static int L;
static int targetSum;

long long dfs(int pos, int sum, int prodMod, int started, bool tight) {
    if (pos == L) {
        return (started && sum == targetSum && prodMod == 0) ? 1LL : 0LL;
    }
    if (!tight && seen[pos][sum][prodMod][started]) {
        return memo[pos][sum][prodMod][started];
    }
    int limit = tight ? dig[pos] : 9;
    long long res = 0;
    for (int d = 0; d <= limit; ++d) {
        int nStarted = started || (d != 0);
        int nSum = sum + (nStarted ? d : 0);
        if (nSum > targetSum) continue;
        int nProdMod;
        if (!nStarted) {
            nProdMod = prodMod; // still leading zeros, product unchanged (still 1 % S)
        } else {
            if (!started) {
                // first non‑zero digit
                nProdMod = d % targetSum;
            } else {
                nProdMod = (int)((1LL * prodMod * (d % targetSum)) % targetSum);
            }
        }
        res += dfs(pos + 1, nSum, nProdMod, nStarted, tight && (d == limit));
    }
    if (!tight) {
        seen[pos][sum][prodMod][started] = true;
        memo[pos][sum][prodMod][started] = res;
    }
    return res;
}

long long countUpTo(long long X) {
    if (X <= 0) return 0;
    dig.clear();
    string s = to_string(X);
    for (char c : s) dig.push_back(c - '0');
    L = (int)dig.size();
    long long total = 0;
    for (int S = 1; S <= 90; ++S) {
        targetSum = S;
        // reset memoization for this S
        for (int i = 0; i <= L; ++i)
            for (int a = 0; a <= S; ++a)
                for (int b = 0; b < S; ++b)
                    seen[i][a][b][0] = seen[i][a][b][1] = false;
        // initial product modulo S is 1 % S (neutral element)
        int initProdMod = 1 % S;
        total += dfs(0, 0, initProdMod, 0, true);
    }
    return total;
}

long long countBeautiful(long long l, long long r) {
    return countUpTo(r) - countUpTo(l - 1);
}

class Solution {
public:
    long long minTime(vector<int>& skill, vector<int>& mana) {
        int n = skill.size(), m = mana.size();
        vector<long long> prefix(n + 1, 0);
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + skill[i];
        long long total = prefix[n];
        long long start = 0; // start time of the current potion at wizard 0
        for (int j = 1; j < m; j++) {
            // wizard i's start for potion j must be >= wizard i's finish for potion j-1;
            // solving for the minimal valid start[j] gives this per-wizard lower bound, take the max
            long long best = LLONG_MIN;
            for (int i = 0; i < n; i++) {
                long long val = start + (long long) mana[j - 1] * prefix[i + 1] - (long long) mana[j] * prefix[i];
                best = max(best, val);
            }
            start = best;
        }
        return start + (long long) mana[m - 1] * total;
    }
};

