long long maxUniqueSubarraySum(const std::vector<int>& nums) {
    std::size_t left = 0;
    long long curSum = 0;
    long long best = std::numeric_limits<long long>::min();
    std::unordered_map<int, int> freq;

    for (std::size_t right = 0; right < nums.size(); ++right) {
        int v = nums[right];

        while (freq[v] > 0) {
            int leftVal = nums[left];
            freq[leftVal] -= 1;
            curSum -= leftVal;
            ++left;
        }

        freq[v] = freq[v] + 1;
        curSum += v;
        if (curSum > best) best = curSum;
    }

    return best;
}

