class DSU {
public:
    DSU(int n) : parent(n), rank(n, 0) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) ++rank[ra];
    }
private:
    std::vector<int> parent;
    std::vector<int> rank;
};

int numberOfComponents(std::vector<std::vector<int>>& properties, int k) {
    int n = properties.size();
    if (n == 0) return 0;
    std::vector<std::unordered_set<int>> sets(n);
    for (int i = 0; i < n; ++i) {
        for (int v : properties[i]) {
            sets[i].insert(v);
        }
    }
    DSU dsu(n);
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            const auto& a = sets[i];
            const auto& b = sets[j];
            const std::unordered_set<int>* small = &a;
            const std::unordered_set<int>* large = &b;
            if (a.size() > b.size()) {
                small = &b;
                large = &a;
            }
            int common = 0;
            for (int val : *small) {
                if (large->find(val) != large->end()) {
                    ++common;
                    if (common >= k) break;
                }
            }
            if (common >= k) dsu.unite(i, j);
        }
    }
    std::unordered_set<int> roots;
    for (int i = 0; i < n; ++i) {
        roots.insert(dsu.find(i));
    }
    return static_cast<int>(roots.size());
}

