#include <bits/stdc++.h>
using namespace std;

int R;
vector<int> runChar, runStart, runEnd, fullLen;
vector<vector<int>> spInnerBC, spMinOne, spMaxZero;
const int NEG_INF = INT_MIN/2, POS_INF = INT_MAX/2;

vector<vector<int>> buildSparse(vector<int>& arr, bool isMax) {
    int m = arr.size();
    if (m == 0) return {};
    int LOG = 32 - __builtin_clz(m);
    vector<vector<int>> sp(LOG, vector<int>(m));
    sp[0] = arr;
    for (int j = 1; j < LOG; j++) {
        int half = 1 << (j-1);
        for (int i = 0; i + (1<<j) <= m; i++) {
            sp[j][i] = isMax ? max(sp[j-1][i], sp[j-1][i+half]) : min(sp[j-1][i], sp[j-1][i+half]);
        }
    }
    return sp;
}
int querySparse(vector<vector<int>>& sp, int l, int r, bool isMax) {
    if (sp.empty() || l > r) return isMax ? NEG_INF : POS_INF;
    int len = r - l + 1;
    int k = 31 - __builtin_clz(len);
    int a = sp[k][l], b = sp[k][r - (1<<k) + 1];
    return isMax ? max(a,b) : min(a,b);
}
int findRun(int pos) {
    int lo = 0, hi = R-1;
    while (lo < hi) {
        int mid = (lo+hi+1)/2;
        if (runStart[mid] <= pos) lo = mid; else hi = mid-1;
    }
    return lo;
}

vector<int> maxActiveSectionsAfterTrade(string s, vector<vector<int>>& queries) {
    int n = s.size();
    vector<array<int,3>> runsList;
    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && s[j] == s[i]) j++;
        runsList.push_back({s[i]-'0', i, j-1});
        i = j;
    }
    R = runsList.size();
    runChar.resize(R); runStart.resize(R); runEnd.resize(R); fullLen.resize(R);
    for (int k = 0; k < R; k++) {
        runChar[k] = runsList[k][0];
        runStart[k] = runsList[k][1];
        runEnd[k] = runsList[k][2];
        fullLen[k] = runEnd[k]-runStart[k]+1;
    }
    int globalTotalOnes = 0;
    for (int k = 0; k < R; k++) if (runChar[k]==1) globalTotalOnes += fullLen[k];

    vector<int> innerBC(R), oneLenOrInf(R), zeroLenOrNegInf(R);
    for (int k = 0; k < R; k++) {
        innerBC[k] = (runChar[k]==1 && k-1>=0 && k+1<R) ? fullLen[k-1]+fullLen[k+1] : NEG_INF;
        oneLenOrInf[k] = runChar[k]==1 ? fullLen[k] : POS_INF;
        zeroLenOrNegInf[k] = runChar[k]==0 ? fullLen[k] : NEG_INF;
    }
    spInnerBC = buildSparse(innerBC, true);
    spMinOne = buildSparse(oneLenOrInf, false);
    spMaxZero = buildSparse(zeroLenOrNegInf, true);

    int q = queries.size();
    vector<int> ans(q);
    for (int qi = 0; qi < q; qi++) {
        int l = queries[qi][0], r = queries[qi][1];
        int idxL = findRun(l), idxR = findRun(r);
        if (idxL == idxR) { ans[qi] = globalTotalOnes; continue; }
        int truncFirst = min(runEnd[idxL], r) - l + 1;
        int truncLast = r - max(runStart[idxR], l) + 1;

        int bestExtra = 0;
        int loI = idxL+1, hiI = idxR-1;
        if (loI <= hiI) {
            int minBlock = querySparse(spMinOne, loI, hiI, false);
            int maxZero = querySparse(spMaxZero, loI, hiI, true);
            if (runChar[idxL]==0) maxZero = max(maxZero, truncFirst);
            if (runChar[idxR]==0) maxZero = max(maxZero, truncLast);
            if (minBlock < POS_INF && maxZero > NEG_INF) {
                bestExtra = max(bestExtra, maxZero - minBlock);
            }
            if (loI+1 <= hiI-1) {
                bestExtra = max(bestExtra, querySparse(spInnerBC, loI+1, hiI-1, true));
            }
            set<int> boundaryIdx = {loI, hiI};
            for (int idx : boundaryIdx) {
                if (runChar[idx] != 1) continue;
                int B = (idx-1 == idxL) ? truncFirst : (idx-1>=0 ? fullLen[idx-1] : 0);
                int C = (idx+1 == idxR) ? truncLast : (idx+1<R ? fullLen[idx+1] : 0);
                bestExtra = max(bestExtra, B+C);
            }
        }
        ans[qi] = globalTotalOnes + bestExtra;
    }
    return ans;
}

