static bool isPal(const std::string& str) {
    size_t i = 0;
    size_t j = str.size();
    if (j == 0) return true;
    --j;
    while (i < j) {
        if (str[i] != str[j]) {
            return false;
        }
        ++i;
        --j;
    }
    return true;
}

int longestPalindromeAfterConcat(const std::string& s, const std::string& t) {
    int n = static_cast<int>(s.size());
    int m = static_cast<int>(t.size());
    int maxLen = 0;
    for (int i = 0; i <= n; ++i) {
        for (int j = i; j <= n; ++j) {
            std::string subS = s.substr(i, j - i);
            for (int p = 0; p <= m; ++p) {
                for (int q = p; q <= m; ++q) {
                    std::string subT = t.substr(p, q - p);
                    std::string combined = subS + subT;
                    int len = static_cast<int>(combined.size());
                    if (len > maxLen && isPal(combined)) {
                        maxLen = len;
                    }
                }
            }
        }
    }
    return maxLen;
}

