int minOperations(std::vector<int> nums, int x, int k) {
    int n = static_cast<int>(nums.size());
    int m = n - x + 1;
    std::vector<long long> cost(m);
    for (int i = 0; i < m; i++) {
        std::vector<int> window(nums.begin()+i, nums.begin()+i+x);
        std::sort(window.begin(), window.end());
        int median = window[window.size()/2];
        long long c = 0;
        for (int v : window) c += std::abs(v - median);
        cost[i] = c;
    }
    const long long INF = LLONG_MAX/2;
    std::vector<std::vector<long long>> dp(n+1, std::vector<long long>(k+1, INF));
    dp[0][0] = 0;
    for (int pos = 0; pos < n; pos++) {
        for (int t = 0; t <= k; t++) {
            if (dp[pos][t] == INF) continue;
            if (dp[pos][t] < dp[pos+1][t]) dp[pos+1][t] = dp[pos][t];
            if (pos < m && t < k) {
                int np = pos + x;
                long long nc = dp[pos][t] + cost[pos];
                if (nc < dp[np][t+1]) dp[np][t+1] = nc;
            }
        }
    }
    return (int)dp[n][k];
}

class Solution {
public:
    int maxActiveSectionsAfterTrade(std::string s) {
        int n = s.length();
        int ans = 0, i = 0;
        int pre = INT_MIN, mx = 0;
        while (i < n) {
            int j = i + 1;
            while (j < n && s[j] == s[i]) j++;
            int cur = j - i;
            if (s[i] == '1') ans += cur;
            else { mx = std::max(mx, pre + cur); pre = cur; }
            i = j;
        }
        ans += mx;
        return ans;
    }
};

class Solution {
public:
    long long minimumCost(vector<int>& nums, vector<int>& cost, int k) {
        int n = nums.size();
        vector<long long> prefixNums(n + 1, 0), prefixCost(n + 1, 0);
        for (int i = 0; i < n; i++) {
            prefixNums[i + 1] = prefixNums[i] + nums[i];
            prefixCost[i + 1] = prefixCost[i] + cost[i];
        }
        vector<long long> dp(n + 1, LLONG_MAX);
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                long long val = prefixNums[j + 1] * (prefixCost[j + 1] - prefixCost[i]) +
                                (long long) k * (prefixCost[n] - prefixCost[i]) + dp[j + 1];
                dp[i] = min(dp[i], val);
            }
        }
        return dp[0];
    }
};

