long long maxProductAlternatingSum(const std::vector<int>& nums, long long k, long long limit) {
    std::unordered_map<long long, long long> dpEven;
    std::unordered_map<long long, long long> dpOdd;
    for (int x : nums) {
        auto nextEven = dpEven;
        auto nextOdd = dpOdd;
        long long val = static_cast<long long>(x);
        if (val <= limit) {
            auto it = nextOdd.find(val);
            if (it == nextOdd.end() || val > it->second) {
                nextOdd[val] = val;
            }
        }
        for (const auto& p : dpEven) {
            long long curProd = p.second;
            if (val != 0 && curProd > limit / val) continue;
            long long newProd = curProd * val;
            long long newSum = p.first + val;
            auto it = nextOdd.find(newSum);
            if (it == nextOdd.end() || newProd > it->second) {
                nextOdd[newSum] = newProd;
            }
        }
        for (const auto& p : dpOdd) {
            long long curProd = p.second;
            if (val != 0 && curProd > limit / val) continue;
            long long newProd = curProd * val;
            long long newSum = p.first - val;
            auto it = nextEven.find(newSum);
            if (it == nextEven.end() || newProd > it->second) {
                nextEven[newSum] = newProd;
            }
        }
        dpEven.swap(nextEven);
        dpOdd.swap(nextOdd);
    }
    long long ans = -1;
    auto it = dpEven.find(k);
    if (it != dpEven.end()) ans = std::max(ans, it->second);
    it = dpOdd.find(k);
    if (it != dpOdd.end()) ans = std::max(ans, it->second);
    return ans;
}

