int minOperations(const std::vector<int>& nums) {
    if (nums.empty()) return 0;
    std::vector<int> tails;
    for (int x : nums) {
        int lo = 0, hi = static_cast<int>(tails.size());
        while (lo < hi) {
            int mid = (lo + hi) >> 1;
            if (tails[mid] <= x) lo = mid + 1;
            else hi = mid;
        }
        if (lo == static_cast<int>(tails.size())) {
            tails.push_back(x);
        } else {
            tails[lo] = x;
        }
    }
    return static_cast<int>(nums.size()) - static_cast<int>(tails.size());
}

