int longestPalindromeAfterSubstringConcatII(const std::string& s, const std::string& t) {
    auto longestPalindromicSubstring = [](const std::string& str) -> int {
        int n = static_cast<int>(str.size());
        int best = 0;
        for (int center = 0; center < n; ++center) {
            int l = center, r = center;
            while (l >= 0 && r < n && str[l] == str[r]) {
                best = std::max(best, r - l + 1);
                --l;
                ++r;
            }
            l = center;
            r = center + 1;
            while (l >= 0 && r < n && str[l] == str[r]) {
                best = std::max(best, r - l + 1);
                --l;
                ++r;
            }
        }
        return best;
    };

    int n = static_cast<int>(s.size());
    int m = static_cast<int>(t.size());
    std::string revT = t;
    std::reverse(revT.begin(), revT.end());

    std::vector<int> dpPrev(m + 1, 0);
    int maxLen = 0;
    int maxOdd = 1;

    for (int i = 0; i < n; ++i) {
        std::vector<int> dpCurr(m + 1, 0);
        for (int j = 0; j < m; ++j) {
            if (s[i] == revT[j]) {
                dpCurr[j + 1] = dpPrev[j] + 1;
                int len = dpCurr[j + 1];
                if (len > maxLen) maxLen = len;

                bool canExtendRightInS = i + 1 < n;
                int startInT = m - 1 - j;
                bool canExtendLeftInT = startInT > 0;

                if (canExtendRightInS || canExtendLeftInT) {
                    int oddLen = 2 * len + 1;
                    if (oddLen > maxOdd) maxOdd = oddLen;
                }
            }
        }
        dpPrev = std::move(dpCurr);
    }

    int bestSingle = std::max(longestPalindromicSubstring(s), longestPalindromicSubstring(t));
    int bestEven = 2 * maxLen;
    int answer = std::max({bestSingle, bestEven, maxOdd});
    return answer;
}

