int countUniqueXorTriplets(const std::vector<int>& nums) {
    const int LIMIT = 2048; // sufficient for values up to 1500 and their XORs
    std::vector<char> present(LIMIT, 0);
    for (int x : nums) {
        if (x >= 0 && x < LIMIT) present[x] = 1;
    }

    std::vector<char> pairXor(LIMIT, 0);
    for (int a = 0; a < LIMIT; ++a) if (present[a]) {
        for (int b = 0; b < LIMIT; ++b) if (present[b]) {
            pairXor[a ^ b] = 1;
        }
    }

    std::vector<char> result(LIMIT, 0);
    // single elements are reachable
    for (int v = 0; v < LIMIT; ++v) if (present[v]) result[v] = 1;

    // triple XORs
    for (int p = 0; p < LIMIT; ++p) if (pairXor[p]) {
        for (int c = 0; c < LIMIT; ++c) if (present[c]) {
            result[p ^ c] = 1;
        }
    }

    int count = 0;
    for (int v = 0; v < LIMIT; ++v) if (result[v]) ++count;
    return count;
}

