std::string smallestPalindromicPermutation(const std::string& s) {
    std::vector<int> freq(256, 0);
    for (size_t i = 0; i < s.size(); ++i) {
        freq[static_cast<unsigned char>(s[i])]++;
    }
    std::string leftHalf;
    std::string middle;
    for (int code = 0; code < 256; ++code) {
        int count = freq[code];
        if (count == 0) continue;
        int half = count >> 1;
        if (half > 0) leftHalf.append(half, static_cast<char>(code));
        if (count & 1) middle = static_cast<char>(code);
    }
    std::string rightHalf = leftHalf;
    std::reverse(rightHalf.begin(), rightHalf.end());
    return leftHalf + middle + rightHalf;
}

