#include <bits/stdc++.h>

class Fenwick {
public:
    Fenwick(int n) : n_(n), bit_(n + 2, 0) {}
    void add(int idx, long long val) {
        for (int i = idx; i <= n_; i += i & -i) bit_[i] += val;
    }
    void rangeAdd(int l, int r, long long val) {
        add(l, val);
        add(r + 1, -val);
    }
    long long pointQuery(int idx) const {
        long long res = 0;
        for (int i = idx; i > 0; i -= i & -i) res += bit_[i];
        return res;
    }
private:
    int n_;
    std::vector<long long> bit_;
};

std::vector<long long> shortestPathQueries(int n, std::vector<std::vector<int>>& edges, std::vector<std::vector<int>>& queries) {
    std::vector<std::vector<std::pair<int,int>>> adj(n + 1);
    for (auto &e : edges) {
        int u = e[0], v = e[1], w = e[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    std::vector<int> parent(n + 1, 0), tin(n + 1), tout(n + 1);
    std::vector<long long> dist(n + 1, 0), edgeWeight(n + 1, 0);
    int timer = 0;
    std::stack<std::pair<int,int>> st;
    st.push({1, 0});
    parent[1] = 0;
    while (!st.empty()) {
        auto topPair = st.top(); st.pop();
        int v = topPair.first;
        int state = topPair.second;
        if (state == 0) {
            tin[v] = ++timer;
            st.push({v, 1});
            for (auto &p : adj[v]) {
                int to = p.first, w = p.second;
                if (to == parent[v]) continue;
                parent[to] = v;
                edgeWeight[to] = w;
                dist[to] = dist[v] + w;
                st.push({to, 0});
            }
        } else {
            tout[v] = timer;
        }
    }
    Fenwick fenwick(n);
    std::vector<long long> answer;
    for (auto &q : queries) {
        if (q[0] == 1) {
            int u = q[1], v = q[2], wnew = q[3];
            int child = (parent[u] == v) ? u : v;
            long long delta = (long long)wnew - edgeWeight[child];
            edgeWeight[child] = wnew;
            fenwick.rangeAdd(tin[child], tout[child], delta);
        } else {
            int x = q[1];
            long long cur = dist[x] + fenwick.pointQuery(tin[x]);
            answer.push_back(cur);
        }
    }
    return answer;
}

