using namespace std;

static const unsigned long long INF = 2000000000000000000ULL; // large enough

static vector<vector<unsigned long long>> combTable;

static void buildComb(int n) {
    combTable.assign(n + 1, vector<unsigned long long>(n + 1, 0));
    for (int i = 0; i <= n; ++i) {
        combTable[i][0] = combTable[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            unsigned long long v = combTable[i - 1][j - 1] + combTable[i - 1][j];
            combTable[i][j] = v >= INF ? INF : v;
        }
    }
}

static unsigned long long countPerms(const vector<int>& cnt, int total) {
    unsigned long long res = 1;
    int remaining = total;
    for (int c : cnt) {
        if (c == 0) continue;
        unsigned long long ways = combTable[remaining][c];
        if (res > INF / ways) return INF;
        res *= ways;
        if (res >= INF) return INF;
        remaining -= c;
    }
    return res;
}

std::string smallestPalindromicRearrangementII(const std::string& s, long long k) {
    if (k <= 0) return "";
    int freq[26] = {0};
    for (char ch : s) freq[ch - 'a']++;

    string middle = "";
    vector<int> halfCnt(26, 0);
    for (int i = 0; i < 26; ++i) {
        if (freq[i] % 2 == 1) middle.push_back('a' + i);
        halfCnt[i] = freq[i] / 2;
    }

    int halfLen = 0;
    for (int v : halfCnt) halfLen += v;
    buildComb(halfLen); // comb up to half length

    unsigned long long totalPerms = countPerms(halfCnt, halfLen);
    if ((unsigned long long)k > totalPerms) return "";

    string left;
    left.reserve(halfLen);
    for (int pos = 0; pos < halfLen; ++pos) {
        for (int i = 0; i < 26; ++i) {
            if (halfCnt[i] == 0) continue;
            halfCnt[i]--;
            unsigned long long cntPerm = countPerms(halfCnt, halfLen - pos - 1);
            if ((unsigned long long)k > cntPerm) {
                k -= cntPerm;
                halfCnt[i]++; // restore
            } else {
                left.push_back('a' + i);
                break;
            }
        }
    }

    string right = left;
    reverse(right.begin(), right.end());
    return left + middle + right;
}

