int maxSizeNonDecreasing(const std::vector<int>& nums) {
    std::vector<int> stack;
    for (size_t i = 0; i < nums.size(); ++i) {
        int cur = nums[i];
        while (!stack.empty() && stack.back() > cur) {
            cur = std::max(stack.back(), cur);
            stack.pop_back();
        }
        stack.push_back(cur);
    }
    return static_cast<int>(stack.size());
}

#include <bits/stdc++.h>

struct Node {
    int prod;                       // product modulo k for the whole segment
    std::vector<int> cnt;           // cnt[r] = number of prefix positions inside the segment whose product modulo k equals r
    Node() : prod(1), cnt() {}
};

static int MODK;
static std::vector<int> arr;
static std::vector<Node> seg;

Node combine(const Node& left, const Node& right) {
    Node res;
    res.prod = (int)((1LL * left.prod * right.prod) % MODK);
    res.cnt.assign(MODK, 0);
    // prefixes coming from the left part keep their remainder
    for (int r = 0; r < MODK; ++r) {
        res.cnt[r] += left.cnt[r];
    }
    // prefixes that end inside the right part have their remainder shifted by left.prod
    for (int r = 0; r < MODK; ++r) {
        int shifted = (int)((1LL * left.prod * r) % MODK);
        res.cnt[shifted] += right.cnt[r];
    }
    return res;
}

void build(int idx, int l, int r) {
    if (l == r) {
        seg[idx].prod = arr[l] % MODK;
        seg[idx].cnt.assign(MODK, 0);
        seg[idx].cnt[seg[idx].prod] = 1;
        return;
    }
    int mid = (l + r) / 2;
    build(idx * 2, l, mid);
    build(idx * 2 + 1, mid + 1, r);
    seg[idx] = combine(seg[idx * 2], seg[idx * 2 + 1]);
}

void pointUpdate(int idx, int l, int r, int pos, int val) {
    if (l == r) {
        seg[idx].prod = val % MODK;
        std::fill(seg[idx].cnt.begin(), seg[idx].cnt.end(), 0);
        seg[idx].cnt[seg[idx].prod] = 1;
        return;
    }
    int mid = (l + r) / 2;
    if (pos <= mid) pointUpdate(idx * 2, l, mid, pos, val);
    else pointUpdate(idx * 2 + 1, mid + 1, r, pos, val);
    seg[idx] = combine(seg[idx * 2], seg[idx * 2 + 1]);
}

Node rangeQuery(int idx, int l, int r, int ql, int qr) {
    if (ql > r || qr < l) {
        Node identity;
        identity.prod = 1 % MODK;
        identity.cnt.assign(MODK, 0);
        return identity;
    }
    if (ql <= l && r <= qr) {
        return seg[idx];
    }
    int mid = (l + r) / 2;
    Node leftRes = rangeQuery(idx * 2, l, mid, ql, qr);
    Node rightRes = rangeQuery(idx * 2 + 1, mid + 1, r, ql, qr);
    return combine(leftRes, rightRes);
}

std::vector<long long> findXValueArrayII(std::vector<int> nums, int k, std::vector<std::vector<int>> queries) {
    MODK = k;
    int n = (int)nums.size();
    arr = nums;
    seg.assign(4 * n + 4, Node());
    build(1, 0, n - 1);

    std::vector<long long> answer;
    answer.reserve(queries.size());

    for (const auto& q : queries) {
        int index = q[0];
        int value = q[1];
        int start = q[2];
        int xi = q[3];

        // point update
        pointUpdate(1, 0, n - 1, index, value);
        // product of prefix before start
        int preProd = 1 % MODK;
        if (start > 0) {
            Node preNode = rangeQuery(1, 0, n - 1, 0, start - 1);
            preProd = preNode.prod;
        }
        // query suffix range [start, n-1]
        Node suffixNode = rangeQuery(1, 0, n - 1, start, n - 1);
        long long cnt = 0;
        for (int r = 0; r < MODK; ++r) {
            if ((1LL * preProd * r) % MODK == xi) {
                cnt += suffixNode.cnt[r];
            }
        }
        answer.push_back(cnt);
    }
    return answer;
}

#include <bits/stdc++.h>
const long long MOD = 1000000007LL;

std::vector<int> decimalToBase(const std::string& s, int b) {
    if (s == "0") return {0};
    std::string cur = s;
    std::vector<int> rev;
    while (!(cur.size() == 1 && cur[0] == '0')) {
        std::string next;
        int carry = 0;
        for (char ch : cur) {
            int num = carry * 10 + (ch - '0');
            int q = num / b;
            carry = num % b;
            if (!next.empty() || q != 0) next.push_back(char('0' + q));
        }
        rev.push_back(carry);
        cur = next.empty() ? "0" : next;
    }
    std::reverse(rev.begin(), rev.end());
    return rev;
}

std::string decrementString(const std::string& s) {
    std::string res = s;
    int i = (int)res.size() - 1;
    while (i >= 0 && res[i] == '0') {
        res[i] = '9';
        --i;
    }
    if (i >= 0) {
        res[i] = char(res[i] - 1);
    }
    // remove leading zeros
    size_t pos = res.find_first_not_of('0');
    if (pos == std::string::npos) return "0";
    return res.substr(pos);
}

long long countUpTo(const std::vector<int>& digits, int b) {
    int n = (int)digits.size();
    std::vector<std::vector<std::vector<long long>>> memo(n, std::vector<std::vector<long long>>(b, std::vector<long long>(2, -1)));
    std::function<long long(int,int,bool,bool)> dfs = [&](int idx, int prev, bool tight, bool started) -> long long {
        if (idx == n) return 1LL;
        if (!tight && memo[idx][prev][started] != -1) return memo[idx][prev][started];
        int limit = tight ? digits[idx] : b - 1;
        long long res = 0;
        for (int d = 0; d <= limit; ++d) {
            bool nstarted = started || d != 0;
            bool ntight = tight && (d == limit);
            if (!nstarted) {
                res += dfs(idx + 1, 0, ntight, false);
            } else {
                if (!started) {
                    res += dfs(idx + 1, d, ntight, true);
                } else {
                    if (d >= prev) {
                        res += dfs(idx + 1, d, ntight, true);
                    }
                }
            }
            if (res >= MOD) res -= MOD;
        }
        if (!tight) memo[idx][prev][started] = res % MOD;
        return res % MOD;
    };
    return dfs(0, 0, true, false) % MOD;
}

void solve() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::string l, r;
    int b;
    if (!(std::cin >> l >> r >> b)) return;
    std::vector<int> rDigits = decimalToBase(r, b);
    long long cntR = countUpTo(rDigits, b);
    long long cntLMinus = 0;
    if (l != "0") {
        std::string lMinus = decrementString(l);
        std::vector<int> lDigits = decimalToBase(lMinus, b);
        cntLMinus = countUpTo(lDigits, b);
    }
    long long ans = (cntR - cntLMinus) % MOD;
    if (ans < 0) ans += MOD;
    std::cout << ans << "\n";
}

#include <bits/stdc++.h>

int countCells(const std::vector<std::vector<char>>& grid, const std::string& pattern) {
    int m = static_cast<int>(grid.size());
    if (m == 0) return 0;
    int n = static_cast<int>(grid[0].size());
    int M = m * n;
    int L = static_cast<int>(pattern.size());
    if (L > M) return 0;

    // Build row-major string
    std::string rowStr;
    rowStr.reserve(M);
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            rowStr.push_back(grid[i][j]);
        }
    }

    // Build column-major string
    std::string colStr;
    colStr.reserve(M);
    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < m; ++i) {
            colStr.push_back(grid[i][j]);
        }
    }

    // KMP prefix function for pattern
    std::vector<int> lps(L, 0);
    for (int i = 1, len = 0; i < L; ) {
        if (pattern[i] == pattern[len]) {
            lps[i++] = ++len;
        } else if (len) {
            len = lps[len - 1];
        } else {
            lps[i++] = 0;
        }
    }

    auto getStarts = [&](const std::string& text) -> std::vector<int> {
        std::vector<int> starts;
        int N = static_cast<int>(text.size());
        for (int i = 0, j = 0; i < N; ) {
            if (text[i] == pattern[j]) {
                ++i; ++j;
                if (j == L) {
                    starts.push_back(i - L);
                    j = lps[j - 1];
                }
            } else if (j) {
                j = lps[j - 1];
            } else {
                ++i;
            }
        }
        return starts;
    };

    std::vector<int> horDiff(M + 1, 0), verDiff(M + 1, 0);

    // Horizontal occurrences
    for (int start : getStarts(rowStr)) {
        horDiff[start] += 1;
        if (start + L <= M) horDiff[start + L] -= 1;
    }

    // Vertical occurrences
    for (int start : getStarts(colStr)) {
        verDiff[start] += 1;
        if (start + L <= M) verDiff[start + L] -= 1;
    }

    std::vector<char> horCover(M, 0), verCover(M, 0);
    int cur = 0;
    for (int i = 0; i < M; ++i) {
        cur += horDiff[i];
        horCover[i] = (cur > 0);
    }
    cur = 0;
    for (int i = 0; i < M; ++i) {
        cur += verDiff[i];
        verCover[i] = (cur > 0);
    }

    int answer = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int idxRow = i * n + j;
            int idxCol = j * m + i;
            if (horCover[idxRow] && verCover[idxCol]) ++answer;
        }
    }
    return answer;
}

