long long calculateScore(const std::vector<std::string>& instructions, const std::vector<int>& values) {
    long long score = 0;
    int n = static_cast<int>(instructions.size());
    std::vector<char> visited(n, 0);
    int idx = 0;
    while (idx >= 0 && idx < n && !visited[idx]) {
        visited[idx] = 1;
        if (instructions[idx] == "add") {
            score += static_cast<long long>(values[idx]);
            ++idx;
        } else { // "jump"
            idx += values[idx];
        }
    }
    return score;
}

