std::vector<long long> find_x_value(const std::vector<int>& nums, int k) {
    std::vector<long long> result(k, 0);
    std::vector<long long> dp(k, 0);
    for (int v : nums) {
        std::vector<long long> new_dp(k, 0);
        int single_rem = v % k;
        if (single_rem < 0) single_rem += k;
        new_dp[single_rem] += 1;
        for (int r = 0; r < k; ++r) {
            long long cnt = dp[r];
            if (cnt == 0) continue;
            long long prod = static_cast<long long>(r) * v;
            int new_rem = prod % k;
            if (new_rem < 0) new_rem += k;
            new_dp[new_rem] += cnt;
        }
        for (int r = 0; r < k; ++r) {
            if (new_dp[r] != 0) {
                result[r] += new_dp[r];
            }
        }
        dp.swap(new_dp);
    }
    return result;
}

