std::vector<bool> pathExistenceQueries(int n, const std::vector<int>& nums, int maxDiff, const std::vector<std::vector<int>>& queries) {
    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) -> int {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto union_sets = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) parent[ra] = rb;
        else if (rank[ra] > rank[rb]) parent[rb] = ra;
        else {
            parent[rb] = ra;
            rank[ra]++;
        }
    };

    for (int i = 1; i < n; ++i) {
        if (nums[i] - nums[i - 1] <= maxDiff) {
            union_sets(i, i - 1);
        }
    }

    std::vector<bool> answer(queries.size());
    for (size_t i = 0; i < queries.size(); ++i) {
        int u = queries[i][0];
        int v = queries[i][1];
        answer[i] = find(u) == find(v);
    }
    return answer;
}

