#include <bits/stdc++.h>
using std::vector;

vector<int> smallestDivisiblePermutation(const vector<int>& nums, int k) {
    int n = nums.size();
    int fullMask = (1 << n) - 1;

    // precompute length and 10^len % k for each number
    vector<int> len(n), pow10mod(n);
    for (int i = 0; i < n; ++i) {
        int x = nums[i];
        int l = 0;
        while (x > 0) {
            ++l;
            x /= 10;
        }
        len[i] = l;
        int p = 1 % k;
        for (int j = 0; j < l; ++j) p = (p * 10) % k;
        pow10mod[i] = p;
    }

    // memo[mask][rem] = -1 unknown, 0 false, 1 true
    vector<vector<char>> memo(1 << n, vector<char>(k, -1));

    std::function<char(int,int)> can = [&](int mask, int rem) -> char {
        if (mask == fullMask) return rem == 0;
        char &res = memo[mask][rem];
        if (res != -1) return res;
        res = 0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) continue;
            int newRem = ( (rem * pow10mod[i]) % k + nums[i] % k ) % k;
            if (can(mask | (1 << i), newRem)) {
                res = 1;
                break;
            }
        }
        return res;
    };

    if (!can(0, 0)) return {};

    // prepare indices sorted by value for lexicographic order
    vector<int> order(n);
    for (int i = 0; i < n; ++i) order[i] = i;
    std::sort(order.begin(), order.end(), [&](int a, int b) {
        return nums[a] < nums[b];
    });

    vector<int> answer;
    int mask = 0, rem = 0;
    for (int pos = 0; pos < n; ++pos) {
        for (int idx : order) {
            if (mask & (1 << idx)) continue;
            int newRem = ( (rem * pow10mod[idx]) % k + nums[idx] % k ) % k;
            if (can(mask | (1 << idx), newRem)) {
                answer.push_back(nums[idx]);
                mask |= (1 << idx);
                rem = newRem;
                break;
            }
        }
    }
    return answer;
}

