std::vector<int> baseUnitConversion(const std::vector<std::vector<int>>& conversions) {
    int n = (int)conversions.size() + 1;
    const int64_t MOD = 1000000007LL;
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (const auto& conv : conversions) {
        int src = conv[0];
        int tgt = conv[1];
        int factor = conv[2];
        adj[src].push_back({tgt, factor});
    }
    std::vector<int64_t> ans64(n, 0);
    ans64[0] = 1;
    std::vector<int> stack;
    stack.reserve(n);
    stack.push_back(0);
    while (!stack.empty()) {
        int u = stack.back();
        stack.pop_back();
        for (const auto& p : adj[u]) {
            int v = p.first;
            int factor = p.second;
            ans64[v] = (ans64[u] * factor) % MOD;
            stack.push_back(v);
        }
    }
    std::vector<int> ans(n);
    for (int i = 0; i < n; ++i) {
        ans[i] = static_cast<int>(ans64[i]);
    }
    return ans;
}

