long long maxProfit(int n, const std::vector<std::pair<int,int>>& edges, const std::vector<long long>& score) {
    std::vector<int> preMask(n, 0);
    for (const auto& e : edges) {
        int u = e.first;
        int v = e.second;
        preMask[v] |= 1 << u;
    }

    int totalMask = (1 << n) - 1;
    const long long NEG_INF = LLONG_MIN;
    std::vector<long long> dp(1 << n, NEG_INF);
    dp[0] = 0;

    for (int mask = 0; mask <= totalMask; ++mask) {
        long long placed = dp[mask];
        if (placed == NEG_INF) continue;
        int pos = __builtin_popcount(mask) + 1;

        for (int v = 0; v < n; ++v) {
            if (mask & (1 << v)) continue;
            if ((preMask[v] & ~mask) != 0) continue;
            int nextMask = mask | (1 << v);
            long long profit = placed + score[v] * pos;
            if (profit > dp[nextMask]) dp[nextMask] = profit;
        }
    }
    return dp[totalMask];
}

