std::vector<std::vector<int>> fillSpecialGrid(int n) {
    int size = 1 << n;
    std::vector<std::vector<int>> grid(size, std::vector<int>(size));
    std::function<void(int, int, int, int)> fill = [&](int r, int c, int sz, int start) {
        if (sz == 1) {
            grid[r][c] = start;
            return;
        }
        int half = sz >> 1;
        int quad = half * half;
        fill(r, c + half, half, start + 0 * quad);
        fill(r + half, c + half, half, start + 1 * quad);
        fill(r + half, c, half, start + 2 * quad);
        fill(r, c, half, start + 3 * quad);
    };
    fill(0, 0, size, 0);
    return grid;
}

