int maxProductTwoDigits(long long n) {
    std::string s = std::to_string(n);
    std::vector<int> freq(10, 0);
    for (size_t i = 0; i < s.size(); ++i) {
        freq[s[i] - '0']++;
    }
    int first = -1;
    for (int d = 9; d >= 0; --d) {
        if (freq[d] > 0) { first = d; break; }
    }
    if (first == -1) return 0;
    if (freq[first] >= 2) return first * first;
    int second = -1;
    for (int d = first - 1; d >= 0; --d) {
        if (freq[d] > 0) { second = d; break; }
    }
    if (second == -1) return 0;
    return first * second;
}

