int minOperations(const std::vector<int>& nums) {
    int ops = 0;
    std::deque<int> stack;
    for (int h : nums) {
        while (!stack.empty() && stack.back() > h) {
            stack.pop_back();
        }
        if (h > 0 && (stack.empty() || stack.back() < h)) {
            stack.push_back(h);
            ++ops;
        }
    }
    return ops;
}

