int minDeletions(const std::string& s, int k) {
    std::vector<int> freq(26, 0);
    for (char ch : s) {
        freq[ch - 'a']++;
    }
    std::vector<int> present;
    for (int v : freq) {
        if (v > 0) present.push_back(v);
    }
    int distinct = static_cast<int>(present.size());
    if (distinct <= k) return 0;
    std::sort(present.begin(), present.end());
    int deletions = 0;
    int toRemove = distinct - k;
    for (int i = 0; i < toRemove; ++i) {
        deletions += present[i];
    }
    return deletions;
}

#include <bits/stdc++.h>
long long maxSubtreeInversionSum(const std::vector<std::pair<int,int>>& edges, const std::vector<long long>& nums, int k) {
    int n = (int)nums.size();
    std::vector<std::vector<int>> adj(n);
    for (auto& e : edges) { adj[e.first].push_back(e.second); adj[e.second].push_back(e.first); }
    std::vector<int> parent(n, -1);
    // memo[v][d][s] where s: 0 => sign +1, 1 => sign -1
    std::vector<std::array<std::array<long long,2>, 51>> memo(n);
    for (auto& row : memo) for (auto& cell : row) cell = {LLONG_MIN, LLONG_MIN};

    std::function<long long(int,int,int)> F = [&](int v, int d, int sIdx) -> long long {
        if (memo[v][d][sIdx] != LLONG_MIN) return memo[v][d][sIdx];
        long long s = (sIdx == 0) ? 1 : -1;
        long long noInvert = s * nums[v];
        for (int c : adj[v]) if (c != parent[v]) { parent[c] = v; noInvert += F(c, std::max(d-1,0), sIdx); }
        long long best = noInvert;
        if (d == 0) {
            long long invVal = -s * nums[v];
            int otherS = 1 - sIdx;
            for (int c : adj[v]) if (c != parent[v]) invVal += F(c, k-1, otherS);
            best = std::max(best, invVal);
        }
        memo[v][d][sIdx] = best;
        return best;
    };
    return F(0, 0, 0);
}

#include <bits/stdc++.h>
static const long long MOD = 1000000007LL;
int sumOfProducts(int m, int k, const std::vector<int>& nums) {
    int n = (int)nums.size();
    std::vector<std::vector<long long>> C(m+1, std::vector<long long>(m+1, 0));
    for (int i = 0; i <= m; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) C[i][j] = (C[i-1][j-1] + (j<=i-1?C[i-1][j]:0)) % MOD;
    }
    std::map<std::tuple<int,int,int,int>, long long> memo;
    std::function<long long(int,int,int,int)> dp = [&](int mm, int kk, int i, int carry) -> long long {
        int popcarry = __builtin_popcount((unsigned)carry);
        if (mm < 0 || kk < 0 || (mm + popcarry < kk)) return 0;
        if (mm == 0) return (kk == popcarry) ? 1 : 0;
        if (i == n) return 0;
        auto key = std::make_tuple(mm, kk, i, carry);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        long long res = 0;
        for (int count = 0; count <= mm; ++count) {
            long long p = 1, base = nums[i] % MOD; int e = count;
            while (e > 0) { if (e&1) p = p*base%MOD; base=base*base%MOD; e>>=1; }
            long long contribution = C[mm][count] * p % MOD;
            int newCarry = carry + count;
            long long sub = dp(mm-count, kk-(newCarry&1), i+1, newCarry>>1);
            res = (res + contribution * sub) % MOD;
        }
        memo[key] = res;
        return res;
    };
    return (int)dp(m, k, 0, 0);
}

