int maxWeightPath(int n, const std::vector<std::vector<int>>& edges, int k, int t) {
    const int NEG = -1000000000;
    std::vector<std::vector<int>> dp(k + 1, std::vector<int>(n, NEG));
    for (int v = 0; v < n; ++v) dp[0][v] = 0;
    for (int step = 1; step <= k; ++step) {
        for (const auto& e : edges) {
            int u = e[0];
            int v = e[1];
            int w = e[2];
            if (dp[step - 1][u] == NEG) continue;
            int cand = dp[step - 1][u] + w;
            if (cand < t && cand > dp[step][v]) dp[step][v] = cand;
        }
    }
    int ans = NEG;
    for (int v = 0; v < n; ++v) ans = std::max(ans, dp[k][v]);
    return ans == NEG ? -1 : ans;
}

