bool equalSumGridPartition(const std::vector<std::vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();
    std::vector<long long> rowSums(m, 0);
    std::vector<long long> colSums(n, 0);
    long long total = 0;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            int v = grid[i][j];
            total += v;
            rowSums[i] += v;
            colSums[j] += v;
        }
    }
    long long prefix = 0;
    for (int i = 0; i < m - 1; ++i) {
        prefix += rowSums[i];
        if (prefix * 2 == total) return true;
    }
    prefix = 0;
    for (int j = 0; j < n - 1; ++j) {
        prefix += colSums[j];
        if (prefix * 2 == total) return true;
    }
    return false;
}

#include <bits/stdc++.h>
std::vector<long long> minimumWeightedSubgraph(const std::vector<std::vector<int>>& edges,
                                               const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(edges.size()) + 1;
    std::vector<std::vector<std::pair<int,int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int w = e[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    int LOG = 1;
    while ((1 << LOG) <= n) ++LOG;
    std::vector<std::vector<int>> up(LOG, std::vector<int>(n, -1));
    std::vector<int> depth(n, 0);
    std::vector<long long> distRoot(n, 0);
    std::vector<int> stack;
    stack.reserve(n);
    stack.push_back(0);
    up[0][0] = 0;
    while (!stack.empty()) {
        int u = stack.back();
        stack.pop_back();
        for (const auto& p : adj[u]) {
            int v = p.first;
            int w = p.second;
            if (v == up[0][u]) continue;
            up[0][v] = u;
            depth[v] = depth[u] + 1;
            distRoot[v] = distRoot[u] + w;
            stack.push_back(v);
        }
    }
    for (int k = 1; k < LOG; ++k) {
        for (int v = 0; v < n; ++v) {
            up[k][v] = up[k-1][ up[k-1][v] ];
        }
    }
    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) std::swap(a, b);
        int diff = depth[a] - depth[b];
        for (int k = LOG - 1; k >= 0; --k) {
            if (diff & (1 << k)) a = up[k][a];
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; --k) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    };
    auto dist = [&](int a, int b) {
        int g = lca(a, b);
        return distRoot[a] + distRoot[b] - 2 * distRoot[g];
    };
    std::vector<long long> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        int s1 = q[0];
        int s2 = q[1];
        int d = q[2];
        long long d12 = dist(s1, s2);
        long long d1d = dist(s1, d);
        long long d2d = dist(s2, d);
        ans.push_back((d12 + d1d + d2d) / 2);
    }
    return ans;
}

#include <bits/stdc++.h>
long long maximumEdgeSum(int n, const std::vector<std::pair<int,int>>& edges) {
    std::vector<std::vector<int>> adj(n);
    for (auto& e : edges) { adj[e.first].push_back(e.second); adj[e.second].push_back(e.first); }
    std::vector<int> order;
    bool isCycle = true;
    int start = -1;
    for (int i=0;i<n;i++) if ((int)adj[i].size()==1) { start=i; isCycle=false; break; }
    if (isCycle) {
        start=0; int prev=-1, cur=start;
        for (int i=0;i<n;i++) {
            order.push_back(cur);
            int next=adj[cur][0];
            if (next==prev && adj[cur].size()>1) next=adj[cur][1];
            prev=cur; cur=next;
        }
    } else {
        int prev=-1, cur=start;
        while (true) {
            order.push_back(cur);
            int next=-1; bool found=false;
            for (int nb : adj[cur]) if (nb!=prev) { next=nb; found=true; break; }
            if (!found) break;
            prev=cur; cur=next;
        }
    }
    // Build the optimal VALUE sequence (not just 1..n in traversal order).
    std::vector<int> seq;
    if (!isCycle) {
        for (int v=1; v<=n; v+=2) seq.push_back(v);
        std::vector<int> evens;
        for (int v=2; v<=n; v+=2) evens.push_back(v);
        for (auto it=evens.rbegin(); it!=evens.rend(); ++it) seq.push_back(*it);
    } else {
        seq.push_back(1);
        for (int v=2; v<=n; v+=2) seq.push_back(v);
        std::vector<int> odds;
        for (int v=3; v<=n; v+=2) odds.push_back(v);
        for (auto it=odds.rbegin(); it!=odds.rend(); ++it) seq.push_back(*it);
    }
    std::vector<int> value(n);
    for (int i = 0; i < n; ++i) value[order[i]] = seq[i];
    long long sum = 0;
    for (auto& e : edges) sum += (long long)value[e.first]*value[e.second];
    return sum;
}

#include <bits/stdc++.h>
using namespace std;

bool checkSection(vector<vector<int>>& mat) {
    int rows = mat.size(), cols = mat[0].size();
    vector<long long> rowSum(rows,0);
    for (int i=0;i<rows;i++) for (int v: mat[i]) rowSum[i]+=v;
    long long total = 0; for (auto s: rowSum) total += s;
    long long topSum = 0;
    unordered_map<int,int> topFreq, fullFreq;
    for (auto& row: mat) for (int v: row) fullFreq[v]++;
    unordered_map<int,int> botFreq = fullFreq;

    for (int r = 0; r < rows-1; r++) {
        topSum += rowSum[r];
        for (int v: mat[r]) {
            topFreq[v]++;
            botFreq[v]--;
            if (botFreq[v]==0) botFreq.erase(v);
        }
        long long botSum = total - topSum;
        int topRows = r+1, botRows = rows-topRows;
        if (topSum == botSum) return true;
        long long diff = llabs(topSum-botSum);
        if (topSum > botSum) {
            if (topFreq.count((int)diff)) {
                if (topRows>=2 && cols>=2) return true;
                if (topRows==1) { if (mat[0][0]==diff || mat[0][cols-1]==diff) return true; }
                else if (cols==1) { if (mat[0][0]==diff || mat[topRows-1][0]==diff) return true; }
            }
        } else {
            if (botFreq.count((int)diff)) {
                if (botRows>=2 && cols>=2) return true;
                if (botRows==1) { if (mat[r+1][0]==diff || mat[r+1][cols-1]==diff) return true; }
                else if (cols==1) { if (mat[r+1][0]==diff || mat[rows-1][0]==diff) return true; }
            }
        }
    }
    return false;
}

bool equalSumGridPartition(vector<vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size();
    if (checkSection(grid)) return true;
    vector<vector<int>> t(n, vector<int>(m));
    for (int i=0;i<m;i++) for (int j=0;j<n;j++) t[j][i]=grid[i][j];
    if (checkSection(t)) return true;
    return false;
}

