bool isPrime(long long num) {
    if (num < 2) return false;
    if (num % 2 == 0) return num == 2;
    for (long long i = 3; i * i <= num; i += 2) {
        if (num % i == 0) return false;
    }
    return true;
}

long long sumLargestPrimes(const std::string& s) {
    std::size_t n = s.length();
    std::unordered_set<long long> primeSet;
    for (std::size_t i = 0; i < n; ++i) {
        long long num = 0;
        for (std::size_t j = i; j < n; ++j) {
            int digit = s[j] - '0';
            if (num > (LLONG_MAX - digit) / 10) break; // prevent overflow
            num = num * 10 + digit;
            if (num >= 2 && isPrime(num)) {
                primeSet.insert(num);
            }
        }
    }
    std::vector<long long> primes(primeSet.begin(), primeSet.end());
    std::sort(primes.begin(), primes.end(), std::greater<long long>());
    long long sum = 0;
    for (std::size_t k = 0; k < std::min<std::size_t>(3, primes.size()); ++k) {
        sum += primes[k];
    }
    return sum;
}

