int maxNumberOfNonIntersectingSubstrings(const std::string& word) {
    int n = static_cast<int>(word.size());
    std::vector<std::vector<int>> pos(26);
    for (int i = 0; i < n; ++i) {
        pos[word[i] - 'a'].push_back(i);
    }
    struct Interval { int l, r; };
    std::vector<Interval> intervals;
    intervals.reserve(n);
    for (int i = 0; i < n; ++i) {
        int c = word[i] - 'a';
        const auto& vec = pos[c];
        auto it = std::lower_bound(vec.begin(), vec.end(), i + 3);
        if (it != vec.end()) {
            intervals.push_back({i, *it});
        }
    }
    std::sort(intervals.begin(), intervals.end(),
              [](const Interval& a, const Interval& b) {
                  return a.r < b.r;
              });
    int count = 0;
    int lastEnd = -1;
    for (const auto& iv : intervals) {
        if (iv.l > lastEnd) {
            ++count;
            lastEnd = iv.r;
        }
    }
    return count;
}

