int digitSum(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

int minSwaps(const std::vector<int>& nums) {
    struct Item {
        int value;
        int digitSum;
        int originalIdx;
    };
    std::vector<Item> withKeys;
    withKeys.reserve(nums.size());
    for (size_t i = 0; i < nums.size(); ++i) {
        withKeys.push_back({nums[i], digitSum(nums[i]), static_cast<int>(i)});
    }
    std::sort(withKeys.begin(), withKeys.end(), [](const Item& a, const Item& b) {
        if (a.digitSum != b.digitSum) return a.digitSum < b.digitSum;
        return a.value < b.value;
    });
    std::unordered_map<int, size_t> targetPos;
    targetPos.reserve(withKeys.size());
    for (size_t idx = 0; idx < withKeys.size(); ++idx) {
        targetPos[withKeys[idx].value] = idx;
    }
    std::vector<bool> visited(nums.size(), false);
    int swaps = 0;
    for (size_t i = 0; i < nums.size(); ++i) {
        if (visited[i]) continue;
        size_t cycleLen = 0;
        size_t j = i;
        while (!visited[j]) {
            visited[j] = true;
            int nextValue = nums[j];
            j = targetPos[nextValue];
            ++cycleLen;
        }
        if (cycleLen > 1) swaps += static_cast<int>(cycleLen - 1);
    }
    return swaps;
}

