#include <bits/stdc++.h>

int minimumMoves(const std::vector<std::string>& matrix) {
    int m = matrix.size();
    if (m == 0) return -1;
    int n = matrix[0].size();
    if (matrix[0][0] == '#') return -1;

    std::vector<std::vector<int>> dist(m, std::vector<int>(n, -1));
    std::unordered_map<char, std::vector<std::pair<int, int>>> portals;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            char ch = matrix[i][j];
            if (ch >= 'A' && ch <= 'Z') {
                portals[ch].emplace_back(i, j);
            }
        }
    }

    std::deque<std::pair<int, int>> dq;
    dist[0][0] = 0;
    dq.emplace_back(0, 0);
    std::array<int, 4> dr = {-1, 1, 0, 0};
    std::array<int, 4> dc = {0, 0, -1, 1};
    std::array<bool, 26> usedLetter{};
    for (bool &b : usedLetter) b = false;

    while (!dq.empty()) {
        auto rc = dq.front();
        dq.pop_front();
        int r = rc.first;
        int c = rc.second;

        if (r == m - 1 && c == n - 1) return dist[r][c];

        char ch = matrix[r][c];
        if (ch >= 'A' && ch <= 'Z' && !usedLetter[ch - 'A']) {
            usedLetter[ch - 'A'] = true;
            const auto& vec = portals[ch];
            for (const auto& p : vec) {
                int nr = p.first, nc = p.second;
                if (dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c];
                    dq.emplace_front(nr, nc);
                }
            }
        }

        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            if (matrix[nr][nc] == '#') continue;
            if (dist[nr][nc] != -1) continue;
            dist[nr][nc] = dist[r][c] + 1;
            dq.emplace_back(nr, nc);
        }
    }
    return -1;
}

