const long long MOD = 1000000007LL;

static long long modPow(long long base, long long exp) {
    long long res = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int numberOfWays(const vector<vector<int>>& edges) {
    int n = edges.size() + 1;
    vector<vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    vector<int> depth(n + 1, -1);
    queue<int> q;
    depth[1] = 0;
    q.push(1);
    int maxDepth = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (depth[v] == -1) {
                depth[v] = depth[u] + 1;
                if (depth[v] > maxDepth) maxDepth = depth[v];
                q.push(v);
            }
        }
    }
    if (maxDepth == 0) return 0;
    long long ans = modPow(2, maxDepth - 1);
    return static_cast<int>(ans);
}

#include <bits/stdc++.h>
