static const long long MOD = 1000000007LL;

vector<int> numberOfWays(vector<vector<int>>& edges, vector<vector<int>>& queries) {
    int n = edges.size() + 1;
    vector<vector<int>> adj(n + 1);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    int LOG = 1;
    while ((1 << LOG) <= n) ++LOG;
    vector<int> depth(n + 1, 0);
    vector<vector<int>> up(LOG, vector<int>(n + 1, 0));
    std::queue<int> q;
    q.push(1);
    depth[1] = 0;
    up[0][1] = 0;
    vector<int> visited(n + 1, 0);
    visited[1] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = 1;
                depth[v] = depth[u] + 1;
                up[0][v] = u;
                for (int k = 1; k < LOG; ++k) {
                    up[k][v] = up[k - 1][ up[k - 1][v] ];
                }
                q.push(v);
            }
        }
    }
    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) std::swap(a, b);
        int diff = depth[a] - depth[b];
        for (int k = 0; diff; ++k) {
            if (diff & 1) a = up[k][a];
            diff >>= 1;
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; --k) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    };
    vector<long long> pow2(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        pow2[i] = (pow2[i - 1] * 2) % MOD;
    }
    vector<int> answer;
    answer.reserve(queries.size());
    for (const auto& qu : queries) {
        int u = qu[0], v = qu[1];
        int w = lca(u, v);
        int L = depth[u] + depth[v] - 2 * depth[w];
        if (L == 0) {
            answer.push_back(0);
        } else {
            answer.push_back(static_cast<int>(pow2[L - 1]));
        }
    }
    return answer;
}

