std::vector<std::vector<int>> minAbsDiffInSlidingSubmatrix(const std::vector<std::vector<int>>& grid, int k) {
    int m = static_cast<int>(grid.size());
    int n = static_cast<int>(grid[0].size());
    int rows = m - k + 1;
    int cols = n - k + 1;
    std::vector<std::vector<int>> ans(rows, std::vector<int>(cols, 0));

    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            std::vector<int> values;
            values.reserve(k * k);
            for (int x = i; x < i + k; ++x) {
                for (int y = j; y < j + k; ++y) {
                    values.push_back(grid[x][y]);
                }
            }
            if (values.size() < 2) {
                ans[i][j] = 0;
                continue;
            }
            std::sort(values.begin(), values.end());
            int minDiff = std::numeric_limits<int>::max();
            for (size_t p = 1; p < values.size(); ++p) {
                if (values[p] != values[p - 1]) {
                    int diff = values[p] - values[p - 1];
                    if (diff < minDiff) {
                        minDiff = diff;
                    }
                }
            }
            ans[i][j] = (minDiff == std::numeric_limits<int>::max()) ? 0 : minDiff;
        }
    }
    return ans;
}

#include <bits/stdc++.h>
using namespace std;
long long maxProfitFromStocks(int n, const vector<int>& present, const vector<int>& future,
                               const vector<pair<int,int>>& hierarchy, int budget) {
    vector<vector<int>> tree(n);
    for (auto& e : hierarchy) tree[e.first-1].push_back(e.second-1);

    const long long NEG = LLONG_MIN/4;
    auto merge = [&](const vector<long long>& A, const vector<long long>& B) {
        vector<long long> merged(A.size(), NEG);
        for (int i = 0; i < (int)A.size(); i++) {
            if (A[i] == NEG) continue;
            for (int j = 0; j + i < (int)A.size(); j++) {
                if (B[j] == NEG) continue;
                merged[i+j] = max(merged[i+j], A[i]+B[j]);
            }
        }
        return merged;
    };

    map<pair<int,int>, pair<vector<long long>,vector<long long>>> memo;
    function<pair<vector<long long>,vector<long long>>(int,int)> dp = [&](int u, int parent) -> pair<vector<long long>,vector<long long>> {
        auto key = make_pair(u,parent);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        vector<long long> noDiscount(budget+1, 0), withDiscount(budget+1, 0);
        for (int v : tree[u]) {
            if (v == parent) continue;
            auto [cnd, cwd] = dp(v, u);
            noDiscount = merge(noDiscount, cnd);
            withDiscount = merge(withDiscount, cwd);
        }
        vector<long long> newDp0 = noDiscount, newDp1 = noDiscount;
        int fullCost = present[u];
        for (int b = fullCost; b <= budget; b++) {
            long long profit = (long long)future[u] - fullCost;
            if (withDiscount[b-fullCost] != NEG) newDp0[b] = max(newDp0[b], withDiscount[b-fullCost]+profit);
        }
        int halfCost = present[u]/2;
        for (int b = halfCost; b <= budget; b++) {
            long long profit = (long long)future[u] - halfCost;
            if (withDiscount[b-halfCost] != NEG) newDp1[b] = max(newDp1[b], withDiscount[b-halfCost]+profit);
        }
        auto result = make_pair(newDp0, newDp1);
        memo[key] = result;
        return result;
    };
    auto [dp0, dp1] = dp(0, -1);
    long long ans = 0;
    for (long long v : dp0) if (v > ans) ans = v;
    return ans;
}

