std::string smallestStringAfterRemovals(const std::string& s) {
    size_t n = s.size();
    if (n == 0) return "";
    auto isConsecutive = [&](char a, char b) {
        int diff = std::abs(static_cast<int>(a) - static_cast<int>(b));
        return diff == 1 || diff == 25;
    };
    std::vector<std::vector<bool>> can(n, std::vector<bool>(n, false));
    for (size_t len = 2; len <= n; ++len) {
        for (size_t i = 0; i + len - 1 < n; ++i) {
            size_t j = i + len - 1;
            for (size_t k = i + 1; k <= j; ++k) {
                if (isConsecutive(s[i], s[k]) &&
                    (i + 1 > k - 1 || can[i + 1][k - 1]) &&
                    (k + 1 > j || can[k + 1][j])) {
                    can[i][j] = true;
                    break;
                }
            }
        }
    }
    std::vector<std::vector<std::string>> best(n, std::vector<std::string>(n, ""));
    for (size_t i = 0; i < n; ++i) best[i][i] = s.substr(i, 1);
    for (size_t len = 2; len <= n; ++len) {
        for (size_t i = 0; i + len - 1 < n; ++i) {
            size_t j = i + len - 1;
            if (can[i][j]) {
                best[i][j] = "";
                continue;
            }
            std::string cur = s.substr(i, j - i + 1);
            for (size_t m = i; m < j; ++m) {
                std::string cand = best[i][m] + best[m + 1][j];
                if (cand < cur) cur = cand;
            }
            best[i][j] = cur;
        }
    }
    return best[0][n - 1];
}

