bool can_partition(const std::vector<int>& nums, int target) {
    int n = static_cast<int>(nums.size());
    long long total = 1;
    for (int v : nums) {
        total *= v;
    }
    long long target_ll = static_cast<long long>(target);
    if (total != target_ll * target_ll) {
        return false;
    }
    std::vector<int> sorted = nums;
    std::sort(sorted.begin(), sorted.end(), std::greater<int>());
    std::function<bool(int, long long, int)> dfs = [&](int idx, long long prod, int cnt) -> bool {
        if (prod == target_ll) {
            return cnt > 0 && cnt < n;
        }
        if (prod > target_ll || idx == n) {
            return false;
        }
        if (dfs(idx + 1, prod * sorted[idx], cnt + 1)) {
            return true;
        }
        if (dfs(idx + 1, prod, cnt)) {
            return true;
        }
        return false;
    };
    return dfs(0, 1, 0);
}

#include <bits/stdc++.h>
int minimumMoves(std::vector<std::string> classroom, int energy) {
    int m = classroom.size();
    int n = classroom[0].size();
    int startR = -1, startC = -1;
    std::vector<std::pair<int,int>> litter;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            char ch = classroom[i][j];
            if (ch == 'S') {
                startR = i;
                startC = j;
            } else if (ch == 'L') {
                litter.emplace_back(i, j);
            }
        }
    }
    int L = litter.size();
    int fullMask = (1 << L) - 1;
    if (fullMask == 0) return 0;
    int maxE = energy;
    int totalMasks = 1 << L;
    int cells = m * n;
    std::vector<char> visited(cells * totalMasks * (maxE + 1), 0);
    struct Node {
        int r, c, mask, e, d;
    };
    std::queue<Node> q;
    int startIdx = (startR * n + startC) * totalMasks * (maxE + 1) + (0) * (maxE + 1) + maxE;
    visited[startIdx] = 1;
    q.push({startR, startC, 0, maxE, 0});
    const int dr[4] = {-1,1,0,0};
    const int dc[4] = {0,0,-1,1};
    while (!q.empty()) {
        Node cur = q.front(); q.pop();
        if (cur.mask == fullMask) return cur.d;
        int curEnergy = cur.e;
        if (classroom[cur.r][cur.c] == 'R') curEnergy = maxE;
        for (int dir = 0; dir < 4; ++dir) {
            int nr = cur.r + dr[dir];
            int nc = cur.c + dc[dir];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            char nxtCell = classroom[nr][nc];
            if (nxtCell == 'X') continue;
            int ne = curEnergy - 1;
            if (ne < 0) continue;
            if (nxtCell == 'R') ne = maxE;
            int nmask = cur.mask;
            if (nxtCell == 'L') {
                for (int i = 0; i < L; ++i) {
                    if (litter[i].first == nr && litter[i].second == nc) {
                        nmask |= (1 << i);
                        break;
                    }
                }
            }
            int idx = (nr * n + nc) * totalMasks * (maxE + 1) + nmask * (maxE + 1) + ne;
            if (!visited[idx]) {
                visited[idx] = 1;
                q.push({nr, nc, nmask, ne, cur.d + 1});
            }
        }
    }
    return -1;
}

#include <bits/stdc++.h>

int maximumGoodSubtreeScore(const std::vector<int>& vals, const std::vector<int>& par) {
    const int MOD = 1000000007;
    const int n = static_cast<int>(vals.size());
    std::vector<std::vector<int>> children(n);
    for (int i = 1; i < n; ++i) {
        children[par[i]].push_back(i);
    }

    std::vector<int> nodeMask(n);
    for (int i = 0; i < n; ++i) {
        int v = vals[i];
        int mask = 0;
        bool ok = true;
        while (v > 0) {
            int d = v % 10;
            if (mask & (1 << d)) {
                ok = false;
                break;
            }
            mask |= 1 << d;
            v /= 10;
        }
        nodeMask[i] = ok ? mask : -1;
    }

    std::vector<long long> maxScore(n, 0);
    const long long NEG_INF = -(1LL << 60);

    std::function<std::vector<long long>(int)> dfs = [&](int u) -> std::vector<long long> {
        std::vector<long long> dp(1024, NEG_INF);
        dp[0] = 0;
        for (int v : children[u]) {
            std::vector<long long> childDP = dfs(v);
            std::vector<long long> newDP(1024, NEG_INF);
            for (int m1 = 0; m1 < 1024; ++m1) {
                if (dp[m1] == NEG_INF) continue;
                for (int m2 = 0; m2 < 1024; ++m2) {
                    if (childDP[m2] == NEG_INF) continue;
                    if ((m1 & m2) != 0) continue;
                    int nm = m1 | m2;
                    long long val = dp[m1] + childDP[m2];
                    if (val > newDP[nm]) newDP[nm] = val;
                }
            }
            for (int m = 0; m < 1024; ++m) {
                if (newDP[m] > dp[m]) dp[m] = newDP[m];
            }
        }

        int mask = nodeMask[u];
        if (mask != -1) {
            for (int m = 0; m < 1024; ++m) {
                if (dp[m] == NEG_INF) continue;
                if ((m & mask) != 0) continue;
                int nm = m | mask;
                long long val = dp[m] + vals[u];
                if (val > dp[nm]) dp[nm] = val;
            }
        }

        long long best = 0;
        for (int m = 0; m < 1024; ++m) {
            if (dp[m] > best) best = dp[m];
        }
        maxScore[u] = best;
        return dp;
    };

    dfs(0);

    long long total = 0;
    for (int i = 0; i < n; ++i) {
        total = (total + maxScore[i]) % MOD;
    }
    return static_cast<int>(total);
}

static const int MAXV = 100000;
static vector<bool> buildSieve() {
    vector<bool> isP(MAXV + 1, true);
    isP[0] = isP[1] = false;
    for (int i = 2; (long long) i * i <= MAXV; i++)
        if (isP[i]) for (int j = i * i; j <= MAXV; j += i) isP[j] = false;
    return isP;
}
static vector<bool> IS_PRIME = buildSieve();

class Solution {
public:
    vector<int> maximizeDistinctPrimeCount(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<int> ans;
        for (auto& q : queries) {
            int idx = q[0], val = q[1];
            nums[idx] = val;
            unordered_map<int, pair<int,int>> positions;
            int totalDistinct = 0;
            for (int i = 0; i < n; i++) {
                int v = nums[i];
                if (v <= MAXV && IS_PRIME[v]) {
                    auto it = positions.find(v);
                    if (it == positions.end()) {
                        positions[v] = {i, i};
                        totalDistinct++;
                    } else {
                        it->second.second = i;
                    }
                }
            }
            vector<int> diff(n + 1, 0);
            for (auto& [v, pr] : positions) {
                int first = pr.first, last = pr.second;
                if (last > first) {
                    int l = first + 1, r = last;
                    diff[l] += 1;
                    diff[r + 1] -= 1;
                }
            }
            int bestOverlap = 0, cur = 0;
            for (int p = 1; p < n; p++) {
                cur += diff[p];
                bestOverlap = max(bestOverlap, cur);
            }
            ans.push_back(totalDistinct + bestOverlap);
        }
        return ans;
    }
};

