static int gcd(int a, int b) {
    while (b != 0) {
        int tmp = a % b;
        a = b;
        b = tmp;
    }
    return a;
}

long long maxScore(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    long long best = 0;
    for (int i = 0; i < n; ++i) {
        int oddCount = 0;
        int g = 0;
        for (int j = i; j < n; ++j) {
            int val = nums[j];
            g = gcd(g, val);
            if ((val & 1) == 1) {
                ++oddCount;
            }
            long long len = static_cast<long long>(j - i + 1);
            long long score = len * g;
            if (score > best) {
                best = score;
            }
            if (oddCount <= k) {
                long long score2 = len * static_cast<long long>(g) * 2;
                if (score2 > best) {
                    best = score2;
                }
            }
        }
    }
    return best;
}

class Solution {
public:
    bool check(vector<int>& nums, int k, int target) {
        int sign = 1, cnt = 0;
        int n = nums.size();
        for (int i = 0; i < n - 1; i++) {
            int x = nums[i] * sign;
            if (x == target) {
                sign = 1;
            } else {
                sign = -1;
                cnt++;
            }
        }
        return cnt <= k && nums[n - 1] * sign == target;
    }

    bool canMakeEqual(vector<int>& nums, int k) {
        // the final array must be all-nums[0] or all-(-nums[0]); try both targets
        return check(nums, k, nums[0]) || check(nums, k, -nums[0]);
    }
};

