long long maxYSum(const std::vector<int>& x, const std::vector<int>& y) {
    std::unordered_map<int, int> best;
    for (size_t i = 0; i < x.size(); ++i) {
        int curX = x[i];
        int curY = y[i];
        auto it = best.find(curX);
        if (it == best.end() || curY > it->second) {
            best[curX] = curY;
        }
    }
    long long first = std::numeric_limits<long long>::lowest();
    long long second = std::numeric_limits<long long>::lowest();
    long long third = std::numeric_limits<long long>::lowest();
    for (const auto& kv : best) {
        long long val = kv.second;
        if (val > first) {
            third = second;
            second = first;
            first = val;
        } else if (val > second) {
            third = second;
            second = val;
        } else if (val > third) {
            third = val;
        }
    }
    return third == std::numeric_limits<long long>::lowest() ? -1 : first + second + third;
}

