long long maxProfit(std::vector<int>& prices, int k) {
    int n = static_cast<int>(prices.size());
    if (n == 0 || k == 0) return 0LL;
    const long long NEG = std::numeric_limits<long long>::min() / 4;
    std::vector<std::vector<long long>> dp(k + 1, std::vector<long long>(3, NEG));
    dp[0][0] = 0;
    dp[0][1] = -static_cast<long long>(prices[0]);
    dp[0][2] =  static_cast<long long>(prices[0]);
    for (int i = 1; i < n; ++i) {
        std::vector<std::vector<long long>> ndp = dp; // carry over doing nothing
        long long price = static_cast<long long>(prices[i]);
        for (int t = 0; t <= k; ++t) {
            if (dp[t][1] != NEG && t + 1 <= k) {
                ndp[t + 1][0] = std::max(ndp[t + 1][0], dp[t][1] + price); // sell long
            }
            if (dp[t][2] != NEG && t + 1 <= k) {
                ndp[t + 1][0] = std::max(ndp[t + 1][0], dp[t][2] - price); // buy short
            }
            if (dp[t][0] != NEG) {
                ndp[t][1] = std::max(ndp[t][1], dp[t][0] - price); // buy to go long
                ndp[t][2] = std::max(ndp[t][2], dp[t][0] + price); // sell to go short
            }
        }
        dp.swap(ndp);
    }
    long long ans = 0;
    for (int t = 0; t <= k; ++t) {
        ans = std::max(ans, dp[t][0]);
    }
    return ans;
}

#include <bits/stdc++.h>
