#include <deque>
#include <cstdint>

int countPartitions(const std::vector<int>& nums, int k) {
    const int MOD = 1000000007;
    int n = static_cast<int>(nums.size());
    std::vector<int> dp(n + 1, 0);
    std::vector<int> pref(n + 1, 0);
    dp[0] = 1;
    pref[0] = 1;
    std::deque<int> minDeque, maxDeque;
    int left = 0;
    for (int i = 1; i <= n; ++i) {
        int val = nums[i - 1];
        while (!minDeque.empty() && nums[minDeque.back()] >= val) minDeque.pop_back();
        minDeque.push_back(i - 1);
        while (!maxDeque.empty() && nums[maxDeque.back()] <= val) maxDeque.pop_back();
        maxDeque.push_back(i - 1);
        while (!minDeque.empty() && !maxDeque.empty() && (int64_t)nums[maxDeque.front()] - (int64_t)nums[minDeque.front()] > k) {
            ++left;
            if (!minDeque.empty() && minDeque.front() < left) minDeque.pop_front();
            if (!maxDeque.empty() && maxDeque.front() < left) maxDeque.pop_front();
        }
        int L = left;
        int64_t sum = pref[i - 1];
        if (L > 0) {
            sum = (sum - pref[L - 1]) % MOD;
            if (sum < 0) sum += MOD;
        }
        dp[i] = static_cast<int>(sum);
        pref[i] = (pref[i - 1] + dp[i]) % MOD;
    }
    return dp[n];
}

