std::string generateTag(const std::string& caption) {
    std::string result = "#";
    std::string word;
    bool first = true;
    for (size_t i = 0; i <= caption.size(); ++i) {
        if (i == caption.size() || caption[i] == ' ') {
            if (!word.empty()) {
                // convert whole word to lower case
                for (char& c : word) c = static_cast<char>(std::tolower(c));
                if (!first) {
                    // capitalize first character
                    if (!word.empty()) {
                        word[0] = static_cast<char>(std::toupper(word[0]));
                    }
                }
                result += word;
                word.clear();
                first = false;
            }
        } else {
            word.push_back(caption[i]);
        }
    }
    if (result.size() > 100) {
        result = result.substr(0, 100);
    }
    return result;
}

