const std::int64_t MOD = 1000000007LL;

int countUnlockPermutations(const std::vector<int>& complexity) {
    int n = static_cast<int>(complexity.size());
    if (n == 0) return 0;
    int minVal = complexity[0];
    for (int v : complexity) {
        if (v < minVal) minVal = v;
    }
    int cnt = 0;
    for (int v : complexity) {
        if (v == minVal) ++cnt;
    }
    if (cnt != 1 || complexity[0] != minVal) return 0;
    std::int64_t fact = 1;
    for (int i = 2; i <= n - 1; ++i) {
        fact = (fact * i) % MOD;
    }
    return static_cast<int>(fact);
}

class Solution {
public:
    int minOperations(string word1, string word2) {
        int n = word1.length();
        vector<int> f(n + 1, INT_MAX);
        f[0] = 0;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (f[j] == INT_MAX) continue;
                int a = calc(word1, word2, j, i - 1, false);
                int b = 1 + calc(word1, word2, j, i - 1, true);
                int t = min(a, b);
                f[i] = min(f[i], f[j] + t);
            }
        }
        return f[n];
    }
private:
    int calc(const string& word1, const string& word2, int l, int r, bool rev) {
        int cnt[26][26] = {0};
        int res = 0;
        for (int i = l; i <= r; ++i) {
            int j = rev ? r - (i - l) : i;
            int a = word1[j] - 'a';
            int b = word2[i] - 'a';
            if (a != b) {
                if (cnt[b][a] > 0) cnt[b][a]--;
                else { cnt[a][b]++; res++; }
            }
        }
        return res;
    }
};

