std::vector<int> weightedMedianNode(int n, const std::vector<std::vector<int>>& edges, const std::vector<std::vector<int>>& queries) {
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1], w = e[2];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    int LOG = 0;
    while ((1 << LOG) < n) ++LOG;
    ++LOG;

    std::vector<std::vector<int>> parent(LOG, std::vector<int>(n, -1));
    std::vector<std::vector<long long>> upDist(LOG, std::vector<long long>(n, 0));
    std::vector<int> depth(n, 0);
    std::vector<long long> dist(n, 0);

    std::vector<int> stack;
    stack.push_back(0);
    std::vector<char> visited(n, false);
    visited[0] = true;
    while (!stack.empty()) {
        int node = stack.back();
        stack.pop_back();
        for (const auto& p : adj[node]) {
            int nei = p.first;
            int w = p.second;
            if (!visited[nei]) {
                visited[nei] = true;
                parent[0][nei] = node;
                upDist[0][nei] = w;
                depth[nei] = depth[node] + 1;
                dist[nei] = dist[node] + w;
                stack.push_back(nei);
            }
        }
    }

    for (int k = 1; k < LOG; ++k) {
        for (int v = 0; v < n; ++v) {
            int mid = parent[k - 1][v];
            if (mid != -1) {
                parent[k][v] = parent[k - 1][mid];
                upDist[k][v] = upDist[k - 1][v] + upDist[k - 1][mid];
            }
        }
    }

    auto lca = [&](int a, int b) {
        if (depth[a] < depth[b]) std::swap(a, b);
        int diff = depth[a] - depth[b];
        for (int k = LOG - 1; k >= 0; --k) {
            if ((diff >> k) & 1) a = parent[k][a];
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; --k) {
            if (parent[k][a] != -1 && parent[k][a] != parent[k][b]) {
                a = parent[k][a];
                b = parent[k][b];
            }
        }
        return parent[0][a];
    };

    auto climbExact = [&](int node, long long need) {
        for (int k = LOG - 1; k >= 0; --k) {
            if (parent[k][node] != -1 && upDist[k][node] <= need) {
                need -= upDist[k][node];
                node = parent[k][node];
            }
        }
        return node;
    };

    std::vector<int> ans;
    for (const auto& q : queries) {
        int u = q[0], v = q[1];
        int w = lca(u, v);
        long long total = dist[u] + dist[v] - 2 * dist[w];
        long long target = (total + 1) / 2;
        long long du = dist[u] - dist[w];
        if (target <= du) {
            int cur = u;
            long long need = target;
            for (int k = LOG - 1; k >= 0; --k) {
                if (parent[k][cur] != -1 && upDist[k][cur] < need) {
                    need -= upDist[k][cur];
                    cur = parent[k][cur];
                }
            }
            ans.push_back(parent[0][cur]);
        } else {
            long long upNeeded = total - target;
            int node = climbExact(v, upNeeded);
            ans.push_back(node);
        }
    }
    return ans;
}

#include <bits/stdc++.h>
static const long long MOD = 1000000007LL;

long long countSpecialTriplets(std::vector<int>& nums) {
    // Correct approach: a special triplet needs nums[i] == 2*nums[j] AND nums[k] == 2*nums[j],
    // i.e. count, for each middle index j, how many equal-to-2*nums[j] values sit to its left
    // times how many sit to its right.
    std::unordered_map<int, long long> left, right;
    for (int x : nums) right[x]++;
    long long ans = 0;
    for (int x : nums) {
        right[x]--;
        long long target = 2LL * x;
        long long l = (target <= 200000) && left.count((int)target) ? left[(int)target] : 0;
        long long r = (target <= 200000) && right.count((int)target) ? right[(int)target] : 0;
        ans = (ans + (l * r) % MOD) % MOD;
        left[x]++;
    }
    return ans;
}

