long long minSwaps(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    std::vector<int> evenPos;
    std::vector<int> oddPos;
    evenPos.reserve(n);
    oddPos.reserve(n);
    for (int i = 0; i < n; ++i) {
        if (nums[i] % 2 == 0) {
            evenPos.push_back(i);
        } else {
            oddPos.push_back(i);
        }
    }
    int evenCnt = static_cast<int>(evenPos.size());
    int oddCnt = static_cast<int>(oddPos.size());
    if (std::abs(evenCnt - oddCnt) > 1) return -1;
    long long answer = LLONG_MAX;
    if (evenCnt >= oddCnt) {
        std::vector<int> targetEven;
        targetEven.reserve(evenCnt);
        for (int i = 0; i < n; i += 2) targetEven.push_back(i);
        long long swaps = 0;
        for (int i = 0; i < evenCnt; ++i) {
            swaps += std::abs(static_cast<long long>(evenPos[i]) - static_cast<long long>(targetEven[i]));
        }
        if (swaps < answer) answer = swaps;
    }
    if (oddCnt >= evenCnt) {
        std::vector<int> targetEven;
        targetEven.reserve(evenCnt);
        for (int i = 1; i < n; i += 2) targetEven.push_back(i);
        long long swaps = 0;
        for (int i = 0; i < evenCnt; ++i) {
            swaps += std::abs(static_cast<long long>(evenPos[i]) - static_cast<long long>(targetEven[i]));
        }
        if (swaps < answer) answer = swaps;
    }
    return answer;
}

#include <bits/stdc++.h>

long long maxArea(const std::vector<std::vector<int>>& coords) {
    if (coords.size() < 3) return -1;
    long long best = 0;
    for (size_t i = 0; i < coords.size(); ++i) {
        long long x1 = coords[i][0];
        long long y1 = coords[i][1];
        for (size_t j = i + 1; j < coords.size(); ++j) {
            long long x2 = coords[j][0];
            long long y2 = coords[j][1];
            for (size_t k = j + 1; k < coords.size(); ++k) {
                long long x3 = coords[k][0];
                long long y3 = coords[k][1];
                long long area2 = std::llabs((x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1));
                if (area2 > best) best = area2;
            }
        }
    }
    return best == 0 ? -1 : best;
}

#include <bits/stdc++.h>

long long maxProduct(const std::vector<int>& nums, int m) {
    int n = static_cast<int>(nums.size());
    long long bestMax = LLONG_MIN;
    long long bestMin = LLONG_MAX;
    long long answer = LLONG_MIN;
    for (int j = 0; j < n; ++j) {
        int idx = j - (m - 1);
        if (idx >= 0) {
            long long val = static_cast<long long>(nums[idx]);
            if (val > bestMax) bestMax = val;
            if (val < bestMin) bestMin = val;
            long long cur = static_cast<long long>(nums[j]);
            long long prod1 = bestMax * cur;
            long long prod2 = bestMin * cur;
            answer = std::max(answer, std::max(prod1, prod2));
        }
    }
    return answer;
}

#include <bits/stdc++.h>

std::vector<int> kthSmallestPathXor(const std::vector<int>& par, const std::vector<int>& vals, const std::vector<std::vector<int>>& queries) {
    int n = static_cast<int>(vals.size());
    std::vector<std::vector<int>> adj(n);
    for (int i = 1; i < n; ++i) {
        int p = par[i];
        adj[p].push_back(i);
    }
    std::vector<int> pathXor(n);
    std::vector<int> tin(n);
    std::vector<int> tout(n);
    std::vector<int> euler(n);
    int timer = 0;
    std::vector<std::pair<int, int>> stack;
    stack.emplace_back(0, 0);
    while (!stack.empty()) {
        auto pr = stack.back();
        stack.pop_back();
        int node = pr.first;
        int state = pr.second;
        if (state == 0) {
            tin[node] = timer;
            euler[timer] = node;
            ++timer;
            if (par[node] == -1) pathXor[node] = vals[node];
            else pathXor[node] = pathXor[par[node]] ^ vals[node];
            stack.emplace_back(node, 1);
            const auto& children = adj[node];
            for (int i = static_cast<int>(children.size()) - 1; i >= 0; --i) {
                stack.emplace_back(children[i], 0);
            }
        } else {
            tout[node] = timer - 1;
        }
    }
    int q = static_cast<int>(queries.size());
    int blockSize = static_cast<int>(std::sqrt(n));
    if (blockSize == 0) blockSize = 1;
    struct Query { int l, r, k, idx; };
    std::vector<Query> qObjs(q);
    for (int i = 0; i < q; ++i) {
        int u = queries[i][0];
        int k = queries[i][1];
        qObjs[i] = { tin[u], tout[u], k, i };
    }
    std::sort(qObjs.begin(), qObjs.end(), [&](const Query& a, const Query& b) {
        int blockA = a.l / blockSize;
        int blockB = b.l / blockSize;
        if (blockA != blockB) return blockA < blockB;
        if (blockA % 2 == 0) return a.r < b.r;
        return a.r > b.r;
    });
    const int MAX_VAL = 1 << 17;
    int bitSize = MAX_VAL + 2;
    std::vector<int> bit(bitSize, 0);
    std::vector<int> freq(MAX_VAL, 0);
    int distinctCount = 0;
    auto bitAdd = [&](int i, int delta) {
        while (i < bitSize) {
            bit[i] += delta;
            i += i & -i;
        }
    };
    auto bitFindKth = [&](int k) {
        int idx = 0;
        int mask = 1;
        while (mask < bitSize) mask <<= 1;
        for (mask >>= 1; mask > 0; mask >>= 1) {
            int next = idx + mask;
            if (next < bitSize && bit[next] < k) {
                idx = next;
                k -= bit[next];
            }
        }
        return idx + 1;
    };
    auto addPos = [&](int pos) {
        int node = euler[pos];
        int v = pathXor[node];
        if (freq[v] == 0) {
            bitAdd(v + 1, 1);
            ++distinctCount;
        }
        ++freq[v];
    };
    auto removePos = [&](int pos) {
        int node = euler[pos];
        int v = pathXor[node];
        --freq[v];
        if (freq[v] == 0) {
            bitAdd(v + 1, -1);
            --distinctCount;
        }
    };
    std::vector<int> ans(q);
    int curL = 0, curR = -1;
    for (const auto& qq : qObjs) {
        while (curL > qq.l) addPos(--curL);
        while (curR < qq.r) addPos(++curR);
        while (curL < qq.l) removePos(curL++);
        while (curR > qq.r) removePos(curR--);
        if (qq.k > distinctCount) {
            ans[qq.idx] = -1;
        } else {
            int idx = bitFindKth(qq.k);
            ans[qq.idx] = idx - 1;
        }
    }
    return ans;
}

#include <bits/stdc++.h>
using namespace std;

double minTime(int n, int k, int m, vector<int>& time_, vector<double>& mul) {
    int FULL = (1<<n) - 1;
    vector<vector<vector<double>>> dist(1<<n, vector<vector<double>>(2, vector<double>(m, 1e18)));
    dist[FULL][0][0] = 0.0;
    // priority queue of (cost, remaining, direction, stage)
    priority_queue<tuple<double,int,int,int>, vector<tuple<double,int,int,int>>, greater<>> pq;
    pq.push({0.0, FULL, 0, 0});
    const double EPS = 1e-9;

    // precompute combinations lazily via bitmask subset enumeration up to size k
    while (!pq.empty()) {
        auto [cost, remaining, direction, stage] = pq.top(); pq.pop();
        if (cost > dist[remaining][direction][stage] + EPS) continue;
        if (direction == 1 && remaining == 0) return cost;
        if (direction == 0) {
            vector<int> people;
            for (int i = 0; i < n; i++) if (remaining & (1<<i)) people.push_back(i);
            int np = people.size();
            // enumerate all non-empty subsets of `people` with size <= k
            for (int sub = 1; sub < (1<<np); sub++) {
                int sz = __builtin_popcount(sub);
                if (sz > k) continue;
                double gtime = 0;
                int newRemaining = remaining;
                for (int b = 0; b < np; b++) {
                    if (sub & (1<<b)) {
                        gtime = max(gtime, (double)time_[people[b]]);
                        newRemaining &= ~(1<<people[b]);
                    }
                }
                gtime *= mul[stage];
                int newStage = ((int)floor(gtime) + stage) % m;
                double newCost = cost + gtime;
                if (newCost < dist[newRemaining][1][newStage] - EPS) {
                    dist[newRemaining][1][newStage] = newCost;
                    pq.push({newCost, newRemaining, 1, newStage});
                }
            }
        } else {
            for (int i = 0; i < n; i++) {
                if (!(remaining & (1<<i))) {
                    double rtime = time_[i] * mul[stage];
                    int newRemaining = remaining | (1<<i);
                    int newStage = ((int)floor(rtime) + stage) % m;
                    double newCost = cost + rtime;
                    if (newCost < dist[newRemaining][0][newStage] - EPS) {
                        dist[newRemaining][0][newStage] = newCost;
                        pq.push({newCost, newRemaining, 0, newStage});
                    }
                }
            }
        }
    }
    return -1.0;
}

static const int MAXV = 100000;
static vector<bool> buildPrimeSieve() {
    vector<bool> isP(MAXV + 1, true);
    isP[0] = isP[1] = false;
    for (int i = 2; (long long) i * i <= MAXV; i++)
        if (isP[i]) for (int j = i * i; j <= MAXV; j += i) isP[j] = false;
    return isP;
}
static vector<bool> IS_PRIME_PG = buildPrimeSieve();

class Solution {
public:
    long long primeSubarray(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> marks(n);
        for (int i = 0; i < n; i++) marks[i] = (nums[i] <= MAXV && IS_PRIME_PG[nums[i]]) ? nums[i] : 0;
        multiset<int> ms; // multiset of primes currently in the window
        int j1 = 0, cnt = 0, j2 = 0;
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int x = marks[i];
            if (x > 0) { cnt++; ms.insert(x); }
            // shrink from the left while max-min exceeds k
            while (!ms.empty() && *ms.rbegin() - *ms.begin() > k) {
                if (marks[j1] > 0) ms.erase(ms.find(marks[j1]));
                j1++;
            }
            // separately track the farthest left boundary with AT MOST 1 prime
            while (cnt > 1) {
                if (marks[j2] > 0) cnt--;
                j2++;
            }
            ans += j2 - j1;
        }
        return ans;
    }
};

