bool isPrime(int n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    for (int i = 3; i * (long long)i <= n; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

bool hasPrimeFrequency(const std::vector<int>& nums) {
    std::unordered_map<int, int> freq;
    for (int v : nums) {
        auto it = freq.find(v);
        if (it == freq.end()) {
            freq[v] = 1;
        } else {
            it->second += 1;
        }
    }
    for (const auto& pair : freq) {
        if (isPrime(pair.second)) return true;
    }
    return false;
}

