std::vector<int> recoverDenominations(const std::vector<int>& numWays) {
    int n = static_cast<int>(numWays.size());
    std::vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    std::vector<int> denominations;
    for (int i = 1; i <= n; ++i) {
        long long cur = dp[i];
        long long target = static_cast<long long>(numWays[i - 1]);
        if (target < cur) {
            return {};
        }
        if (target == cur) {
            continue;
        }
        if (target == cur + 1) {
            denominations.push_back(i);
            for (int j = i; j <= n; ++j) {
                dp[j] += dp[j - i];
            }
        } else {
            return {};
        }
    }
    for (int i = 1; i <= n; ++i) {
        if (dp[i] != static_cast<long long>(numWays[i - 1])) {
            return {};
        }
    }
    return denominations;
}

