long long minNodesToIncrease(int n, const std::vector<std::vector<int>>& edges, const std::vector<long long>& cost) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    std::vector<std::vector<int>> children(n);
    std::vector<int> parent(n, -1);
    std::vector<int> order;
    std::vector<int> stack;
    stack.push_back(0);
    parent[0] = 0;
    while (!stack.empty()) {
        int node = stack.back();
        stack.pop_back();
        order.push_back(node);
        for (int nb : adj[node]) {
            if (nb == parent[node]) continue;
            parent[nb] = node;
            children[node].push_back(nb);
            stack.push_back(nb);
        }
    }

    std::vector<long long> maxSum(n, 0);
    std::vector<long long> touches(n, 0);

    for (int i = static_cast<int>(order.size()) - 1; i >= 0; --i) {
        int node = order[i];
        const std::vector<int>& childs = children[node];
        if (childs.empty()) {
            maxSum[node] = cost[node];
            touches[node] = 0;
        } else {
            long long maxChildSum = std::numeric_limits<long long>::min();
            for (int ch : childs) {
                if (maxSum[ch] > maxChildSum) maxChildSum = maxSum[ch];
            }
            long long total = 0;
            for (int ch : childs) {
                total += touches[ch];
                if (maxSum[ch] < maxChildSum) total += 1;
            }
            maxSum[node] = cost[node] + maxChildSum;
            touches[node] = total;
        }
    }

    return touches[0];
}

