int lcp(const string& a, const string& b) {
    int len = min(a.size(), b.size());
    int i = 0;
    while (i < len && a[i] == b[i]) ++i;
    return i;
}

vector<int> longestCommonPrefixAfterRemoval(const vector<string>& words) {
    int n = static_cast<int>(words.size());
    if (n == 0) return {};
    int m = n - 1;
    vector<int> L(m);
    for (int i = 0; i < m; ++i) {
        L[i] = lcp(words[i], words[i + 1]);
    }
    vector<int> pref(m), suff(m);
    for (int i = 0; i < m; ++i) {
        pref[i] = (i == 0) ? L[i] : max(pref[i - 1], L[i]);
    }
    for (int i = m - 1; i >= 0; --i) {
        suff[i] = (i == m - 1) ? L[i] : max(suff[i + 1], L[i]);
    }
    vector<int> ans(n);
    for (int i = 0; i < n; ++i) {
        int left = (i - 2 >= 0) ? pref[i - 2] : 0;
        int right = (i + 1 <= m - 1) ? suff[i + 1] : 0;
        int best = max(left, right);
        if (i > 0 && i < n - 1) {
            int newL = lcp(words[i - 1], words[i + 1]);
            best = max(best, newL);
        }
        ans[i] = best;
    }
    return ans;
}

#include <bits/stdc++.h>
struct DSU {
    std::vector<int> parent, rank;
    DSU(int n) : parent(n), rank(n, 0) {
        std::iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (rank[a] < rank[b]) std::swap(a, b);
        parent[b] = a;
        if (rank[a] == rank[b]) ++rank[a];
        return true;
    }
};

bool feasible(int n, const std::vector<std::vector<int>>& edges, int k, int X) {
    DSU dsu(n);
    int used = 0;
    // Process mandatory edges
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        int s = e[2];
        int must = e[3];
        if (must == 1) {
            if (s < X) return false;            // cannot satisfy required stability
            if (!dsu.unite(u, v)) return false; // cycle among mandatory edges
            ++used;
        }
    }
    std::vector<std::pair<int,int>> cost0;
    std::vector<std::pair<int,int>> cost1;
    cost0.reserve(edges.size());
    cost1.reserve(edges.size());
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        int s = e[2];
        int must = e[3];
        if (must == 1) continue; // already handled
        if (s >= X) {
            cost0.emplace_back(u, v);
        } else if (2LL * s >= X) {
            cost1.emplace_back(u, v);
        }
    }
    // Add optional edges without upgrade first
    for (auto &p : cost0) {
        if (used == n - 1) break;
        if (dsu.unite(p.first, p.second)) ++used;
    }
    int upgrades = 0;
    // Add optional edges with upgrade
    for (auto &p : cost1) {
        if (used == n - 1) break;
        if (dsu.unite(p.first, p.second)) {
            ++used;
            ++upgrades;
            if (upgrades > k) return false;
        }
    }
    return used == n - 1 && upgrades <= k;
}

int maxStability(int n, std::vector<std::vector<int>>& edges, int k) {
    int maxS = 0;
    for (const auto& e : edges) maxS = std::max(maxS, e[2]);
    int low = 0, high = maxS * 2;
    while (low < high) {
        int mid = low + (high - low + 1) / 2;
        if (feasible(n, edges, k, mid))
            low = mid;
        else
            high = mid - 1;
    }
    return (low > 0 && feasible(n, edges, k, low)) ? low : -1;
}

#include <bits/stdc++.h>

int minMaxXor(const std::vector<int>& nums, int k) {
    int n = static_cast<int>(nums.size());
    std::vector<int> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] ^ nums[i];

    auto can = [&](int limit) -> bool {
        std::vector<std::vector<char>> dp(n + 1, std::vector<char>(k + 1, 0));
        dp[0][0] = 1;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < i; ++j) {
                int subXor = pref[i] ^ pref[j];
                if (subXor <= limit) {
                    for (int cnt = 0; cnt < k; ++cnt) {
                        if (dp[j][cnt]) dp[i][cnt + 1] = 1;
                    }
                }
            }
        }
        return dp[n][k];
    };

    int low = 0;
    int high = (1 << 31) - 1;
    while (low < high) {
        int mid = low + ((high - low) >> 1);
        if (can(mid)) high = mid;
        else low = mid + 1;
    }
    return low;
}

class Solution {
public:
    long long minCost(int m, int n, vector<vector<int>>& waitCost) {
        vector<vector<long long>> f(m, vector<long long>(n, 0));
        f[0][0] = 1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) continue;
                long long entry = (long long)(i+1)*(j+1);
                long long best = LLONG_MAX;
                if (i > 0) {
                    long long p = f[i-1][j];
                    if (!(i-1 == 0 && j == 0)) p += waitCost[i-1][j];
                    best = min(best, p);
                }
                if (j > 0) {
                    long long p = f[i][j-1];
                    if (!(i == 0 && j-1 == 0)) p += waitCost[i][j-1];
                    best = min(best, p);
                }
                f[i][j] = entry + best;
            }
        }
        return f[m-1][n-1];
    }
};

