std::string solution(int n) {
    long long sq = 1LL * n * n;
    long long cu = 1LL * n * n * n;

    auto toBase = [](long long value, int base) -> std::string {
        if (value == 0) return "0";
        std::string res;
        while (value > 0) {
            int digit = static_cast<int>(value % base);
            if (digit < 10) res.push_back('0' + digit);
            else res.push_back('A' + (digit - 10));
            value /= base;
        }
        std::reverse(res.begin(), res.end());
        return res;
    };

    std::string hexPart = toBase(sq, 16);
    std::string base36Part = toBase(cu, 36);
    return hexPart + base36Part;
}

#include <bits/stdc++.h>

long long minimumTime(int n, const std::vector<std::vector<int>>& edges) {
    struct Edge {
        int to;
        int start;
        int end;
    };
    std::vector<std::vector<Edge>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1], s = e[2], t = e[3];
        adj[u].push_back({v, s, t});
    }
    const long long INF = (1LL << 62);
    std::vector<long long> dist(n, INF);
    dist[0] = 0;
    using State = std::pair<long long, int>; // (time, node)
    std::priority_queue<State, std::vector<State>, std::greater<State>> pq;
    pq.emplace(0, 0);
    while (!pq.empty()) {
        State top = pq.top();
        pq.pop();
        long long curTime = top.first;
        int u = top.second;
        if (curTime != dist[u]) continue;
        if (u == n - 1) break;
        for (const auto& e : adj[u]) {
            if (curTime > e.end) continue; // edge already closed
            long long wait = 0;
            if (curTime < e.start) wait = static_cast<long long>(e.start) - curTime;
            long long arrival = curTime + wait + 1;
            if (arrival < dist[e.to]) {
                dist[e.to] = arrival;
                pq.emplace(arrival, e.to);
            }
        }
    }
    return dist[n - 1] == INF ? -1 : dist[n - 1];
}

