std::vector<std::string> validCouponCodes(const std::vector<std::string>& code,
                                          const std::vector<std::string>& businessLine,
                                          const std::vector<bool>& isActive) {
    std::unordered_map<std::string, int> lineOrder = {
        {"electronics", 0},
        {"grocery", 1},
        {"pharmacy", 2},
        {"restaurant", 3}
    };
    std::vector<std::vector<std::string>> groups(4);
    size_t n = code.size();
    for (size_t i = 0; i < n; ++i) {
        if (!isActive[i]) continue;
        auto it = lineOrder.find(businessLine[i]);
        if (it == lineOrder.end()) continue;
        const std::string& c = code[i];
        if (c.empty()) continue;
        bool ok = true;
        for (char ch : c) {
            unsigned char uch = static_cast<unsigned char>(ch);
            if (!std::isalnum(uch) && ch != '_') {
                ok = false;
                break;
            }
        }
        if (!ok) continue;
        groups[it->second].push_back(c);
    }
    std::vector<std::string> result;
    for (int idx = 0; idx < 4; ++idx) {
        std::sort(groups[idx].begin(), groups[idx].end());
        result.insert(result.end(), groups[idx].begin(), groups[idx].end());
    }
    return result;
}

