int minimumStabilityFactor(const std::vector<int>& nums, int maxC) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;

    std::vector<int> lg(n + 1);
    lg[1] = 0;
    for (int i = 2; i <= n; ++i) lg[i] = lg[i / 2] + 1;

    int K = lg[n] + 1;
    std::vector<std::vector<int>> st(K, std::vector<int>(n));
    for (int i = 0; i < n; ++i) st[0][i] = nums[i];
    for (int k = 1; k < K; ++k) {
        for (int i = 0; i + (1 << k) <= n; ++i) {
            st[k][i] = std::__gcd(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
        }
    }

    auto range_gcd = [&](int l, int r) -> int {
        int len = r - l + 1;
        int k = lg[len];
        return std::__gcd(st[k][l], st[k][r - (1 << k) + 1]);
    };

    auto can = [&](int L) -> bool {
        int len = L + 1;
        if (len > n) return true;
        int modifications = 0;
        int lastChosen = -1;
        for (int start = 0; start + len - 1 < n; ++start) {
            int end = start + len - 1;
            if (range_gcd(start, end) >= 2) {
                if (lastChosen < start) {
                    ++modifications;
                    if (modifications > maxC) return false;
                    lastChosen = end;
                }
            }
        }
        return modifications <= maxC;
    };

    int low = 0, high = n;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (can(mid)) high = mid;
        else low = mid + 1;
    }
    return low;
}

