class DSU {
public:
    DSU(int n) : parent(n), rank(n, 0) {
        for (int i = 0; i < n; ++i) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    bool unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (rank[ra] < rank[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) ++rank[ra];
        return true;
    }
private:
    vector<int> parent;
    vector<int> rank;
};

int minimumTime(int n, vector<vector<int>>& edges, int k) {
    // Compute the initial component count with ALL edges present (i.e. at time 0,
    // before anything has been removed). The original code assumed this was always
    // n (all nodes isolated), which is only true when the graph has no edges yet -
    // wrong whenever edges already connect some of the n nodes.
    {
        DSU dsu0(n);
        int comp0 = n;
        for (auto& e : edges) if (dsu0.unite(e[0], e[1])) --comp0;
        if (comp0 >= k) return 0;
    }
    // Sort edges by time descending.
    sort(edges.begin(), edges.end(),
         [](const vector<int>& a, const vector<int>& b) {
             return a[2] > b[2];
         });
    DSU dsu(n);
    int components = n;
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int t = e[2];
        if (dsu.unite(u, v)) {
            // Edge connects two different components.
            if (components == k) {
                // Adding this edge reduces components below k.
                return t;
            }
            --components;
        }
    }
    // Never dropped below k, so answer is 0.
    return 0;
}

