int minMovesGrid(int sx, int sy, int tx, int ty) {
    if (sx == tx && sy == ty) return 0;
    std::deque<std::array<int, 3>> queue;
    std::unordered_set<std::string> visited;
    queue.push_back({sx, sy, 0});
    visited.insert(std::to_string(sx) + "," + std::to_string(sy));
    while (!queue.empty()) {
        auto cur = queue.front();
        queue.pop_front();
        int x = cur[0];
        int y = cur[1];
        int d = cur[2];
        int m = std::max(x, y);
        std::array<std::pair<int, int>, 2> candidates = { std::make_pair(x + m, y), std::make_pair(x, y + m) };
        for (const auto& p : candidates) {
            int nx = p.first;
            int ny = p.second;
            if (nx > tx || ny > ty) continue;
            if (nx == tx && ny == ty) return d + 1;
            std::string key = std::to_string(nx) + "," + std::to_string(ny);
            if (visited.find(key) == visited.end()) {
                visited.insert(key);
                queue.push_back({nx, ny, d + 1});
            }
        }
    }
    return -1;
}

