std::vector<int> powerGridMaintenance(int c, const std::vector<std::vector<int>>& connections, const std::vector<std::vector<int>>& queries) {
    std::vector<std::vector<int>> adj(c + 1);
    for (const auto& e : connections) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    for (int i = 1; i <= c; ++i) {
        std::sort(adj[i].begin(), adj[i].end());
    }

    std::vector<uint8_t> online(c + 1, 1);
    std::vector<int> answer;
    answer.reserve(queries.size());

    std::vector<int> visited(c + 1, 0);
    int visitMark = 1;

    for (const auto& q : queries) {
        int type = q[0];
        int x = q[1];
        if (type == 2) {
            online[x] = 0;
        } else {
            std::queue<int> bfs;
            bfs.push(x);
            visited[x] = visitMark;
            int result = -1;
            while (!bfs.empty()) {
                int cur = bfs.front();
                bfs.pop();
                if (online[cur]) {
                    result = cur;
                    break;
                }
                for (int nb : adj[cur]) {
                    if (visited[nb] != visitMark) {
                        visited[nb] = visitMark;
                        bfs.push(nb);
                    }
                }
            }
            ++visitMark;
            if (visitMark == 0) { // overflow guard
                std::fill(visited.begin(), visited.end(), 0);
                visitMark = 1;
            }
            answer.push_back(result);
        }
    }
    return answer;
}

