std::string processString(const std::string& s) {
    std::vector<char> out;
    std::vector<char> deleted;
    for (char ch : s) {
        if (ch >= 'a' && ch <= 'z') {
            out.push_back(ch);
        } else if (ch == '#') {
            if (!out.empty()) {
                deleted.push_back(out.back());
                out.pop_back();
            }
        } else if (ch == '%') {
            if (!deleted.empty()) {
                out.push_back(deleted.back());
                deleted.pop_back();
            }
        } else if (ch == '*') {
            deleted.clear();
        }
    }
    return std::string(out.begin(), out.end());
}

