int minimumMaximumComponentCost(int n, std::vector<std::vector<int>>& edges, int k) {
    if (k >= n) return 0;
    std::sort(edges.begin(), edges.end(),
              [](const std::vector<int>& a, const std::vector<int>& b) {
                  return a[2] < b[2];
              });
    DSU dsu(n);
    int components = n;
    int answer = 0;
    for (const auto& e : edges) {
        if (components <= k) break;
        int u = e[0], v = e[1], w = e[2];
        if (dsu.unite(u, v)) {
            answer = w;
            --components;
        }
    }
    return answer;
}

