int longestPalindromePath(int n, std::vector<std::vector<int>>& edges, std::string label) {
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    int maxMask = 1 << n;
    int totalStates = maxMask * n * n;
    std::vector<int> dp(totalStates, -1);
    auto idx = [&](int mask, int i, int j) {
        return (mask * n + i) * n + j;
    };
    int answer = 0;
    for (int i = 0; i < n; ++i) {
        int mask = 1 << i;
        dp[idx(mask, i, i)] = 1;
        answer = std::max(answer, 1);
    }
    for (const auto& e : edges) {
        int u = e[0], v = e[1];
        if (label[u] == label[v]) {
            int mask = (1 << u) | (1 << v);
            dp[idx(mask, u, v)] = std::max(dp[idx(mask, u, v)], 2);
            dp[idx(mask, v, u)] = std::max(dp[idx(mask, v, u)], 2);
            answer = std::max(answer, 2);
        }
    }
    for (int mask = 0; mask < maxMask; ++mask) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int cur = dp[idx(mask, i, j)];
                if (cur == -1) continue;
                for (int ni : adj[i]) {
                    if (mask & (1 << ni)) continue;
                    for (int nj : adj[j]) {
                        if (mask & (1 << nj)) continue;
                        if (ni == nj) continue;
                        if (label[ni] != label[nj]) continue;
                        int newMask = mask | (1 << ni) | (1 << nj);
                        int &next = dp[idx(newMask, ni, nj)];
                        if (next < cur + 2) {
                            next = cur + 2;
                            if (next > answer) answer = next;
                        }
                    }
                }
            }
        }
    }
    return answer;
}

