int countIslands(const std::vector<std::vector<int>>& grid, int k) {
    int rows = static_cast<int>(grid.size());
    if (rows == 0) return 0;
    int cols = static_cast<int>(grid[0].size());
    std::vector<std::vector<bool>> visited(rows, std::vector<bool>(cols, false));
    int islandCount = 0;
    const std::vector<std::pair<int, int>> dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (grid[r][c] > 0 && !visited[r][c]) {
                int sum = 0;
                std::vector<std::pair<int, int>> stack;
                stack.emplace_back(r, c);
                visited[r][c] = true;
                while (!stack.empty()) {
                    int cr = stack.back().first;
                    int cc = stack.back().second;
                    stack.pop_back();
                    sum += grid[cr][cc];
                    for (const auto& d : dirs) {
                        int nr = cr + d.first;
                        int nc = cc + d.second;
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                            grid[nr][nc] > 0 && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.emplace_back(nr, nc);
                        }
                    }
                }
                if (sum % k == 0) ++islandCount;
            }
        }
    }
    return islandCount;
}

#include <bits/stdc++.h>

int maximumPathScore(const std::vector<std::vector<int>>& edges, const std::vector<bool>& online, long long k) {
    int n = static_cast<int>(online.size());
    std::vector<std::vector<std::pair<int,int>>> adj(n);
    std::vector<int> indegree(n, 0);
    int maxCost = 0;
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int c = e[2];
        adj[u].push_back({v, c});
        ++indegree[v];
        if (c > maxCost) maxCost = c;
    }
    // topological order (Kahn's algorithm)
    std::queue<int> q;
    for (int i = 0; i < n; ++i) if (indegree[i] == 0) q.push(i);
    std::vector<int> topo;
    topo.reserve(n);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        topo.push_back(u);
        for (auto& p : adj[u]) {
            int v = p.first;
            if (--indegree[v] == 0) q.push(v);
        }
    }
    const long long INF = LLONG_MAX / 4;
    auto feasible = [&](int B) -> bool {
        if (!online[0] || !online[n-1]) return false;
        std::vector<long long> dist(n, INF);
        dist[0] = 0;
        for (int u : topo) {
            if (!online[u]) continue;
            if (dist[u] == INF) continue;
            for (auto& p : adj[u]) {
                int v = p.first;
                int c = p.second;
                if (c < B) continue;
                if (!online[v]) continue;
                long long nd = dist[u] + c;
                if (nd < dist[v]) dist[v] = nd;
            }
        }
        return dist[n-1] <= k;
    };
    int low = 0, high = maxCost;
    while (low < high) {
        int mid = low + (high - low + 1) / 2;
        if (feasible(mid)) low = mid;
        else high = mid - 1;
    }
    if (!feasible(low)) return -1;
    return low;
}

