static unsigned long long C[61][61];
static vector<vector<int>> targets(6);
static bool init = []() {
    for (int i = 0; i <= 60; ++i) {
        C[i][0] = C[i][i] = 1ULL;
        for (int j = 1; j < i; ++j) {
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
    }
    const int MAXC = 60;
    vector<int> depth(MAXC + 1, -1);
    depth[1] = 0;
    for (int i = 2; i <= MAXC; ++i) {
        int pc = __builtin_popcount(i);
        depth[i] = 1 + depth[pc];
    }
    for (int i = 1; i <= MAXC; ++i) {
        int d = depth[i];
        if (d + 1 < (int)targets.size()) {
            targets[d + 1].push_back(i);
        }
    }
    return true;
}();

static unsigned long long countUpTo(long long n, const vector<int>& target) {
    if (n < 0) return 0ULL;
    unsigned long long res = 0ULL;
    int ones = 0;
    for (int bit = 60; bit >= 0; --bit) {
        if ((n >> bit) & 1LL) {
            int remaining = bit;
            for (int t : target) {
                int need = t - ones;
                if (need < 0) continue;
                if (need > remaining) continue;
                res += C[remaining][need];
            }
            ++ones;
        }
    }
    for (int t : target) {
        if (t == ones) {
            ++res;
            break;
        }
    }
    return res;
}

long long countNumbers(long long n, int k) {
    if (n <= 0) return 0LL;
    if (k == 0) return 1LL; // only the number 1
    if (k >= (int)targets.size()) return 0LL;
    const vector<int>& target = targets[k];
    unsigned long long ans = countUpTo(n, target);
    if (n >= 1 && std::binary_search(target.begin(), target.end(), 1)) {
        --ans; // exclude the number 1 which has depth 0
    }
    return static_cast<long long>(ans);
}

