long long splitArrayByPrimeIndices(const std::vector<int>& nums) {
    std::size_t n = nums.size();
    std::vector<bool> isPrime(n, false);
    if (n > 2) {
        std::vector<bool> primeFlag(n, true);
        primeFlag[0] = false;
        primeFlag[1] = false;
        for (std::size_t i = 2; i * i < n; ++i) {
            if (primeFlag[i]) {
                for (std::size_t j = i * i; j < n; j += i) {
                    primeFlag[j] = false;
                }
            }
        }
        for (std::size_t i = 2; i < n; ++i) {
            if (primeFlag[i]) {
                isPrime[i] = true;
            }
        }
    }

    long long sumPrime = 0;
    long long sumNonPrime = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (isPrime[i]) {
            sumPrime += nums[i];
        } else {
            sumNonPrime += nums[i];
        }
    }

    long long diff = sumPrime - sumNonPrime;
    return diff >= 0 ? diff : -diff;
}

#include <bits/stdc++.h>
int countTrapezoids(std::vector<std::vector<int>>& points) {
    const long long MOD = 1000000007LL;
    const long long INV2 = 500000004LL; // modular inverse of 2 modulo MOD
    std::unordered_map<long long, long long> freq;
    freq.reserve(points.size() * 2);
    for (const auto& p : points) {
        long long y = p[1];
        ++freq[y];
    }
    std::vector<long long> combs;
    combs.reserve(freq.size());
    for (const auto& kv : freq) {
        long long cnt = kv.second;
        if (cnt >= 2) {
            long long c = cnt * (cnt - 1) / 2;
            combs.push_back(c % MOD);
        }
    }
    long long sum = 0, sumSq = 0;
    for (long long v : combs) {
        sum = (sum + v) % MOD;
        sumSq = (sumSq + v * v) % MOD;
    }
    long long ans = ( ( (sum * sum) % MOD - sumSq + MOD) % MOD ) * INV2 % MOD;
    return static_cast<int>(ans);
}

#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<int> bit;
    Fenwick(int n = 0) : n(n), bit(n + 1, 0) {}
    void add(int idx, int delta) {
        for (++idx; idx <= n; idx += idx & -idx) bit[idx] += delta;
    }
    long long sumPrefix(int idx) const {
        long long res = 0;
        for (++idx; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
    long long rangeSum(int l, int r) const {
        if (l > r) return 0;
        return sumPrefix(r) - (l ? sumPrefix(l - 1) : 0);
    }
};

int popDepth(long long x) {
    int d = 0;
    while (x != 1) {
        x = __builtin_popcountll((unsigned long long)x);
        ++d;
    }
    return d;
}

vector<long long> numberOfIntegers(vector<long long>& nums, vector<vector<long long>>& queries) {
    const int MAXK = 6; // depths 0..5
    int n = nums.size();
    vector<Fenwick> bits;
    bits.reserve(MAXK);
    for (int i = 0; i < MAXK; ++i) bits.emplace_back(n);
    vector<int> depth(n);
    for (int i = 0; i < n; ++i) {
        int d = popDepth(nums[i]);
        depth[i] = d;
        bits[d].add(i, 1);
    }
    vector<long long> answer;
    answer.reserve(queries.size());
    for (const auto& q : queries) {
        int type = static_cast<int>(q[0]);
        if (type == 1) {
            int l = static_cast<int>(q[1]);
            int r = static_cast<int>(q[2]);
            int k = static_cast<int>(q[3]);
            long long cnt = bits[k].rangeSum(l, r);
            answer.push_back(cnt);
        } else { // type == 2
            int idx = static_cast<int>(q[1]);
            long long val = q[2];
            int oldD = depth[idx];
            int newD = popDepth(val);
            if (oldD != newD) {
                bits[oldD].add(idx, -1);
                bits[newD].add(idx, 1);
                depth[idx] = newD;
            }
            nums[idx] = val;
        }
    }
    return answer;
}

