static long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

struct LineEntry {
    long long count = 0;
    std::unordered_map<int, int> pointDegLine;
};

struct SlopeEntry {
    long long total = 0;
    std::unordered_map<int, int> pointDeg;
    std::unordered_map<std::string, LineEntry> lineMap;
};

long long countNumberOfTrapezoids(const std::vector<std::vector<long long>>& points) {
    int n = static_cast<int>(points.size());
    std::unordered_map<std::string, SlopeEntry> slopeMap;
    std::unordered_map<std::string, long long> midMap;

    for (int i = 0; i < n; ++i) {
        long long xi = points[i][0];
        long long yi = points[i][1];
        for (int j = i + 1; j < n; ++j) {
            long long xj = points[j][0];
            long long yj = points[j][1];
            long long dx = xj - xi;
            long long dy = yj - yi;
            long long g = gcd_ll(std::llabs(dx), std::llabs(dy));
            dx /= g;
            dy /= g;
            if (dx < 0) {
                dx = -dx;
                dy = -dy;
            } else if (dx == 0 && dy < 0) {
                dy = -dy;
            }
            std::string slopeKey = std::to_string(dy) + '/' + std::to_string(dx);
            long long c = dy * xi - dx * yi;
            std::string lineKey = slopeKey + '/' + std::to_string(c);
            std::string midKey = std::to_string(xi + xj) + ',' + std::to_string(yi + yj);
            midMap[midKey] = midMap[midKey] + 1;

            SlopeEntry& slopeEntry = slopeMap[slopeKey];
            slopeEntry.total += 1;
            slopeEntry.pointDeg[i] = slopeEntry.pointDeg[i] + 1;
            slopeEntry.pointDeg[j] = slopeEntry.pointDeg[j] + 1;

            LineEntry& lineEntry = slopeEntry.lineMap[lineKey];
            lineEntry.count += 1;
            lineEntry.pointDegLine[i] = lineEntry.pointDegLine[i] + 1;
            lineEntry.pointDegLine[j] = lineEntry.pointDegLine[j] + 1;
        }
    }

    long long trapezoidPairs = 0;
    for (const auto& slopePair : slopeMap) {
        const SlopeEntry& slopeEntry = slopePair.second;
        long long m = slopeEntry.total;
        long long totalPairs = m * (m - 1) / 2;

        long long sharePoint = 0;
        for (const auto& degPair : slopeEntry.pointDeg) {
            long long deg = degPair.second;
            sharePoint += deg * (deg - 1) / 2;
        }

        long long sameLinePairs = 0;
        long long sameLineSharePoint = 0;
        for (const auto& linePair : slopeEntry.lineMap) {
            const LineEntry& lineEntry = linePair.second;
            long long t = lineEntry.count;
            sameLinePairs += t * (t - 1) / 2;
            for (const auto& degLPair : lineEntry.pointDegLine) {
                long long degL = degLPair.second;
                sameLineSharePoint += degL * (degL - 1) / 2;
            }
        }

        long long valid = totalPairs - sharePoint - sameLinePairs + sameLineSharePoint;
        trapezoidPairs += valid;
    }

    long long parallelogramCount = 0;
    for (const auto& midPair : midMap) {
        long long cnt = midPair.second;
        if (cnt > 1) {
            parallelogramCount += cnt * (cnt - 1) / 2;
        }
    }

    long long result = trapezoidPairs - parallelogramCount;
    return result;
}

