long long maxLCT(const std::string& s) {
    std::size_t n = s.size();
    std::vector<long long> prefixL(n + 1, 0);
    std::vector<long long> prefixLC(n + 1, 0);
    std::vector<long long> suffixT(n + 1, 0);
    std::vector<long long> suffixCT(n + 1, 0);

    long long cntL = 0, cntLC = 0;
    for (std::size_t i = 0; i < n; ++i) {
        prefixL[i] = cntL;
        prefixLC[i] = cntLC;
        char ch = s[i];
        if (ch == 'L') {
            ++cntL;
        } else if (ch == 'C') {
            cntLC += cntL;
        }
    }
    prefixL[n] = cntL;
    prefixLC[n] = cntLC;

    long long cntT = 0, cntCT = 0;
    for (std::size_t i = n; i-- > 0;) {
        suffixT[i + 1] = cntT;
        suffixCT[i + 1] = cntCT;
        char ch = s[i];
        if (ch == 'T') {
            ++cntT;
        } else if (ch == 'C') {
            cntCT += cntT;
        }
    }
    suffixT[0] = cntT;
    suffixCT[0] = cntCT;

    long long original = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (s[i] == 'C') {
            original += prefixL[i] * suffixT[i + 1];
        }
    }

    long long bestInc = 0;
    for (std::size_t i = 0; i <= n; ++i) {
        long long incL = suffixCT[i];
        if (incL > bestInc) bestInc = incL;
        long long incT = prefixLC[i];
        if (incT > bestInc) bestInc = incT;
        long long incC = prefixL[i] * suffixT[i];
        if (incC > bestInc) bestInc = incC;
    }

    return original + bestInc;
}

#include <bits/stdc++.h>

int minJumps(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n <= 1) return 0;

    int maxVal = 0;
    for (int v : nums) if (v > maxVal) maxVal = v;

    std::vector<int> spf(maxVal + 1);
    for (int i = 2; i <= maxVal; ++i) {
        if (spf[i] == 0) {
            spf[i] = i;
            if (1LL * i * i <= maxVal) {
                for (int j = i * i; j <= maxVal; j += i) {
                    if (spf[j] == 0) spf[j] = i;
                }
            }
        }
    }

    std::unordered_map<int, std::vector<int>> primeIndices;
    primeIndices.reserve(n * 2);
    for (int i = 0; i < n; ++i) {
        int x = nums[i];
        while (x > 1) {
            int p = spf[x];
            primeIndices[p].push_back(i);
            while (x % p == 0) x /= p;
        }
    }

    std::vector<int> dist(n, -1);
    std::queue<int> q;
    dist[0] = 0;
    q.push(0);

    while (!q.empty()) {
        int i = q.front();
        q.pop();
        int d = dist[i] + 1;

        if (i - 1 >= 0 && dist[i - 1] == -1) {
            dist[i - 1] = d;
            if (i - 1 == n - 1) return d;
            q.push(i - 1);
        }
        if (i + 1 < n && dist[i + 1] == -1) {
            dist[i + 1] = d;
            if (i + 1 == n - 1) return d;
            q.push(i + 1);
        }

        if (nums[i] > 1 && spf[nums[i]] == nums[i]) {
            int p = nums[i];
            auto it = primeIndices.find(p);
            if (it != primeIndices.end()) {
                std::vector<int>& vec = it->second;
                for (int idx : vec) {
                    if (dist[idx] == -1) {
                        dist[idx] = d;
                        if (idx == n - 1) return d;
                        q.push(idx);
                    }
                }
                vec.clear();
            }
        }
    }
    return -1;
}

#include <bits/stdc++.h>
// Correct brute-force over all 3^n assignments (0=A,1=B,2=C). Exact for any n,
// but exponential - fine for verification purposes on the given examples.
long long maxValue(const std::vector<int>& nums) {
    int n = nums.size();
    long long best = 0;
    std::vector<int> assign(n, 0);
    std::function<void(int)> rec = [&](int i) {
        if (i == n) {
            long long xorA = 0, xorC = 0;
            long long andB = -1; bool bEmpty = true;
            for (int j = 0; j < n; j++) {
                if (assign[j] == 0) xorA ^= nums[j];
                else if (assign[j] == 1) { andB &= nums[j]; bEmpty = false; }
                else xorC ^= nums[j];
            }
            long long val = xorA + (bEmpty ? 0 : andB) + xorC;
            if (val > best) best = val;
            return;
        }
        for (int g = 0; g < 3; g++) { assign[i] = g; rec(i+1); }
    };
    rec(0);
    return best;
}

