int minRemovals(std::vector<long long> nums, long long k) {
    std::sort(nums.begin(), nums.end());
    int n = static_cast<int>(nums.size());
    int left = 0;
    int best = 0;
    for (int right = 0; right < n; ++right) {
        while (left <= right && nums[right] > k * nums[left]) {
            ++left;
        }
        int windowSize = right - left + 1;
        if (windowSize > best) best = windowSize;
    }
    return n - best;
}

#include <bits/stdc++.h>
int earliestFinishTime(std::vector<int> landStartTime, std::vector<int> landDuration,
                       std::vector<int> waterStartTime, std::vector<int> waterDuration) {
    int n = landStartTime.size();
    int m = waterStartTime.size();
    using Pair = std::pair<int,int>;
    std::vector<Pair> land(n), water(m);
    for (int i = 0; i < n; ++i) land[i] = {landStartTime[i], landDuration[i]};
    for (int i = 0; i < m; ++i) water[i] = {waterStartTime[i], waterDuration[i]};
    std::sort(land.begin(), land.end(),
              [](const Pair& a, const Pair& b){ return a.first < b.first; });
    std::sort(water.begin(), water.end(),
              [](const Pair& a, const Pair& b){ return a.first < b.first; });
    std::vector<int> landStarts(n);
    std::vector<int> landSuffMinEnd(n);
    std::vector<int> landPrefMinDur(n);
    for (int i = 0; i < n; ++i) landStarts[i] = land[i].first;
    landSuffMinEnd[n-1] = land[n-1].first + land[n-1].second;
    for (int i = n-2; i >= 0; --i)
        landSuffMinEnd[i] = std::min(land[i].first + land[i].second, landSuffMinEnd[i+1]);
    landPrefMinDur[0] = land[0].second;
    for (int i = 1; i < n; ++i)
        landPrefMinDur[i] = std::min(landPrefMinDur[i-1], land[i].second);
    std::vector<int> waterStarts(m);
    std::vector<int> waterSuffMinEnd(m);
    std::vector<int> waterPrefMinDur(m);
    for (int i = 0; i < m; ++i) waterStarts[i] = water[i].first;
    waterSuffMinEnd[m-1] = water[m-1].first + water[m-1].second;
    for (int i = m-2; i >= 0; --i)
        waterSuffMinEnd[i] = std::min(water[i].first + water[i].second, waterSuffMinEnd[i+1]);
    waterPrefMinDur[0] = water[0].second;
    for (int i = 1; i < m; ++i)
        waterPrefMinDur[i] = std::min(waterPrefMinDur[i-1], water[i].second);
    int answer = INT_MAX;
    // water then land
    for (int i = 0; i < m; ++i) {
        int finishWater = water[i].first + water[i].second;
        int idx = std::lower_bound(landStarts.begin(), landStarts.end(), finishWater) - landStarts.begin();
        if (idx < n) answer = std::min(answer, landSuffMinEnd[idx]);
        if (idx > 0) answer = std::min(answer, finishWater + landPrefMinDur[idx-1]);
    }
    // land then water
    for (int i = 0; i < n; ++i) {
        int finishLand = land[i].first + land[i].second;
        int idx = std::lower_bound(waterStarts.begin(), waterStarts.end(), finishLand) - waterStarts.begin();
        if (idx < m) answer = std::min(answer, waterSuffMinEnd[idx]);
        if (idx > 0) answer = std::min(answer, finishLand + waterPrefMinDur[idx-1]);
    }
    return answer;
}

#include <bits/stdc++.h>

int earliestFinish(std::vector<int> landStart, std::vector<int> landDuration,
                   std::vector<int> waterStart, std::vector<int> waterDuration) {
    const long long INF = 4e18;
    int n = static_cast<int>(landStart.size());
    int m = static_cast<int>(waterStart.size());

    std::vector<std::pair<int,int>> land(n), water(m);
    for (int i = 0; i < n; ++i) land[i] = {landStart[i], landDuration[i]};
    for (int i = 0; i < m; ++i) water[i] = {waterStart[i], waterDuration[i]};
    std::sort(land.begin(), land.end());
    std::sort(water.begin(), water.end());

    std::vector<long long> landS(n), landD(n), waterS(m), waterD(m);
    for (int i = 0; i < n; ++i) {
        landS[i] = land[i].first;
        landD[i] = land[i].second;
    }
    for (int i = 0; i < m; ++i) {
        waterS[i] = water[i].first;
        waterD[i] = water[i].second;
    }

    // Preprocess water: suffix min of start+duration, prefix min of duration
    std::vector<long long> waterSuffix(m);
    for (int i = m - 1; i >= 0; --i) {
        long long val = waterS[i] + waterD[i];
        waterSuffix[i] = (i == m - 1) ? val : std::min(val, waterSuffix[i + 1]);
    }
    std::vector<long long> waterPrefixDur(m);
    for (int i = 0; i < m; ++i) {
        waterPrefixDur[i] = (i == 0) ? waterD[i] : std::min(waterPrefixDur[i - 1], waterD[i]);
    }

    // Preprocess land similarly
    std::vector<long long> landSuffix(n);
    for (int i = n - 1; i >= 0; --i) {
        long long val = landS[i] + landD[i];
        landSuffix[i] = (i == n - 1) ? val : std::min(val, landSuffix[i + 1]);
    }
    std::vector<long long> landPrefixDur(n);
    for (int i = 0; i < n; ++i) {
        landPrefixDur[i] = (i == 0) ? landD[i] : std::min(landPrefixDur[i - 1], landD[i]);
    }

    long long best = INF;

    // Land first then water
    for (int i = 0; i < n; ++i) {
        long long landEnd = landS[i] + landD[i];
        auto it = std::lower_bound(waterS.begin(), waterS.end(), landEnd);
        int idx = static_cast<int>(it - waterS.begin());
        if (idx < m) {
            best = std::min(best, waterSuffix[idx]);
        }
        if (idx > 0) {
            best = std::min(best, landEnd + waterPrefixDur[idx - 1]);
        }
    }

    // Water first then land
    for (int i = 0; i < m; ++i) {
        long long waterEnd = waterS[i] + waterD[i];
        auto it = std::lower_bound(landS.begin(), landS.end(), waterEnd);
        int idx = static_cast<int>(it - landS.begin());
        if (idx < n) {
            best = std::min(best, landSuffix[idx]);
        }
        if (idx > 0) {
            best = std::min(best, waterEnd + landPrefixDur[idx - 1]);
        }
    }

    return static_cast<int>(best);
}

#include <bits/stdc++.h>
#include <vector>

bool isTrionicArray(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n < 6) return false;
    std::vector<bool> incPrefix(n, false);
    incPrefix[0] = true;
    for (int i = 1; i < n; ++i) {
        incPrefix[i] = incPrefix[i - 1] && (nums[i - 1] < nums[i]);
    }
    std::vector<bool> incSuffix(n, false);
    incSuffix[n - 1] = true;
    for (int i = n - 2; i >= 0; --i) {
        incSuffix[i] = incSuffix[i + 1] && (nums[i] < nums[i + 1]);
    }
    for (int p = 1; p <= n - 4; ++p) {
        if (!incPrefix[p]) continue;
        bool decreasing = true;
        for (int q = p + 1; q <= n - 3; ++q) {
            if (q > p + 1 && nums[q - 1] <= nums[q]) decreasing = false;
            if (!decreasing) break;
            if (q - p >= 2 && incSuffix[q + 1]) return true;
        }
    }
    return false;
}

#include <bits/stdc++.h>
std::vector<int> thresholdMajorityQueries(const std::vector<int>& nums, const std::vector<std::vector<int>>& queries) {
    int n = nums.size();
    // coordinate compression
    std::unordered_map<int,int> mp;
    std::vector<int> rev;
    rev.reserve(n);
    for (int v : nums) {
        if (mp.find(v) == mp.end()) {
            mp[v] = rev.size();
            rev.push_back(v);
        }
    }
    int m = rev.size();
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) a[i] = mp[nums[i]];
    struct Q {int l, r, thr, idx;};
    int qn = queries.size();
    std::vector<Q> qs(qn);
    for (int i = 0; i < qn; ++i) {
        qs[i] = {queries[i][0], queries[i][1], queries[i][2], i};
    }
    int block = std::max(1, (int)std::sqrt(n));
    std::sort(qs.begin(), qs.end(), [&](const Q& a, const Q& b){
        int block_a = a.l / block;
        int block_b = b.l / block;
        if (block_a != block_b) return block_a < block_b;
        if (block_a & 1) return a.r > b.r;
        return a.r < b.r;
    });
    std::vector<int> freq(m, 0);
    std::vector<std::set<int>> bucket(n + 1);
    int maxFreq = 0;
    auto add = [&](int pos){
        int idx = a[pos];
        int val = rev[idx];
        int f = freq[idx];
        if (f > 0) bucket[f].erase(val);
        ++freq[idx];
        ++f;
        bucket[f].insert(val);
        if (f > maxFreq) maxFreq = f;
    };
    auto remove = [&](int pos){
        int idx = a[pos];
        int val = rev[idx];
        int f = freq[idx];
        bucket[f].erase(val);
        --freq[idx];
        --f;
        if (f > 0) bucket[f].insert(val);
        while (maxFreq > 0 && bucket[maxFreq].empty()) --maxFreq;
    };
    std::vector<int> ans(qn, -1);
    int curL = 0, curR = -1;
    for (const auto& qq : qs) {
        while (curL > qq.l) add(--curL);
        while (curR < qq.r) add(++curR);
        while (curL < qq.l) remove(curL++);
        while (curR > qq.r) remove(curR--);
        if (maxFreq >= qq.thr && !bucket[maxFreq].empty())
            ans[qq.idx] = *bucket[maxFreq].begin();
        else
            ans[qq.idx] = -1;
    }
    return ans;
}

class Solution {
public:
    long long maxSumTrionic(vector<int>& nums) {
        int n = nums.size();
        int i = 0;
        long long ans = LLONG_MIN;
        while (i < n) {
            int l = i;
            i += 1;
            while (i < n && nums[i - 1] < nums[i]) i += 1;
            if (i == l + 1) continue;
            int p = i - 1;
            long long s = (long long) nums[p - 1] + nums[p];
            while (i < n && nums[i - 1] > nums[i]) { s += nums[i]; i += 1; }
            if (i == p + 1 || i == n || nums[i - 1] == nums[i]) continue;
            int q = i - 1;
            s += nums[i];
            i += 1;
            long long mx = 0, t = 0;
            while (i < n && nums[i - 1] < nums[i]) { t += nums[i]; i += 1; mx = max(mx, t); }
            s += mx;
            mx = 0; t = 0;
            int j = p - 2;
            while (j >= l) { t += nums[j]; mx = max(mx, t); j -= 1; }
            s += mx;
            ans = max(ans, s);
            i = q;
        }
        return ans;
    }
};

#include <bits/stdc++.h>

int minimumTime(std::string s, std::vector<int> order, long long k) {
    int n = (int)s.size();
    long long total = 1LL * n * (n + 1) / 2;
    long long sumBad = total; // initially all substrings are bad
    std::map<int, int> intervals;
    intervals[0] = n - 1; // one interval covering whole string

    for (int t = 0; t < n; ++t) {
        int p = order[t];
        // find interval containing p
        auto it = intervals.upper_bound(p);
        if (it == intervals.begin()) {
            // should not happen
        } else {
            --it;
        }
        int l = it->first;
        int r = it->second;
        // remove this interval
        intervals.erase(it);
        long long len = r - l + 1;
        sumBad -= len * (len + 1) / 2;
        // left part
        if (l <= p - 1) {
            int nl = l;
            int nr = p - 1;
            long long lenL = nr - nl + 1;
            sumBad += lenL * (lenL + 1) / 2;
            intervals[nl] = nr;
        }
        // right part
        if (p + 1 <= r) {
            int nl = p + 1;
            int nr = r;
            long long lenR = nr - nl + 1;
            sumBad += lenR * (lenR + 1) / 2;
            intervals[nl] = nr;
        }
        long long good = total - sumBad;
        if (good >= k) {
            return t;
        }
    }
    return -1;
}

