int maxBalancedShipments(const std::vector<int>& weight) {
    std::size_t n = weight.size();
    std::size_t i = 0;
    int shipments = 0;

    while (i < n) {
        int maxSoFar = weight[i];
        std::size_t j = i + 1;

        while (j < n) {
            if (weight[j] > maxSoFar) {
                maxSoFar = weight[j];
            } else if (weight[j] < maxSoFar) {
                shipments++;
                break;
            }
            ++j;
        }

        if (j == n) break;
        i = j + 1;
    }

    return shipments;
}

#include <bits/stdc++.h>
