long long maxTotal(const std::vector<int>& value, const std::vector<int>& limit) {
    int n = (int)value.size();
    std::vector<std::pair<int,int>> arr(n); // (limit, value)
    for (int i = 0; i < n; i++) arr[i] = {limit[i], value[i]};
    std::sort(arr.begin(), arr.end(), [](const std::pair<int,int>& a, const std::pair<int,int>& b) {
        if (a.first != b.first) return a.first < b.first;
        return a.second > b.second;
    });
    std::vector<int> status(n, 0);
    int i = 0, j = 0, active = 0;
    long long ans = 0;
    while (j < n) {
        int val = arr[j].second, lmt = arr[j].first;
        if (active < lmt) {
            status[j] = 1;
            ans += val;
            active += 1;
            if (active == lmt) {
                while (j < n && arr[j].first == active) j++;
            } else {
                j++;
            }
        } else {
            j++;
        }
        while (i < j && arr[i].first <= active) {
            active -= status[i];
            i++;
        }
    }
    return ans;
}

