std::vector<std::vector<int>> flipSquareSubmatrixVertically(std::vector<std::vector<int>>& matrix, int row, int col, int k) {
    for (int i = 0; i < k / 2; ++i) {
        int top = row + i;
        int bottom = row + k - 1 - i;
        for (int j = 0; j < k; ++j) {
            int idx = col + j;
            std::swap(matrix[top][idx], matrix[bottom][idx]);
        }
    }
    return matrix;
}

