class Solution {
public:
    vector<pair<int, map<int,int>>> allMultisets() {
        vector<int> evenDigits = {2,4,6,8};
        vector<int> oddChoices = {0,1,3,5,7,9};
        vector<pair<int, map<int,int>>> result;
        int n = evenDigits.size();
        for (int mask = 0; mask < (1<<n); mask++) {
            vector<int> combo;
            for (int i = 0; i < n; i++) if (mask & (1<<i)) combo.push_back(evenDigits[i]);
            for (int odd : oddChoices) {
                vector<int> digits = combo;
                if (odd != 0) digits.push_back(odd);
                if (digits.empty()) continue;
                map<int,int> counts;
                int total = 0;
                for (int d : digits) { counts[d] = d; total += d; }
                result.push_back({total, counts});
            }
        }
        return result;
    }

    pair<map<int,int>, int> halfMultiset(map<int,int>& counts) {
        map<int,int> half;
        int middle = -1;
        for (auto& [d,c] : counts) {
            if (c % 2 == 1) middle = d;
            half[d] = c/2;
        }
        return {half, middle};
    }

    string minArrangement(map<int,int> counts) {
        auto [half, middle] = halfMultiset(counts);
        string halfDigits;
        for (auto& [d,c] : half) for (int i=0;i<c;i++) halfDigits += ('0'+d);
        sort(halfDigits.begin(), halfDigits.end());
        string mid = (middle != -1) ? string(1, '0'+middle) : "";
        string rev = halfDigits; reverse(rev.begin(), rev.end());
        return halfDigits + mid + rev;
    }

    string bestGreaterArrangement(map<int,int> counts, const string& nStr) {
        int L = 0; for (auto& [d,c] : counts) L += c;
        auto [half, middle] = halfMultiset(counts);
        string halfItems;
        for (auto& [d,c] : half) for (int i=0;i<c;i++) halfItems += ('0'+d);
        sort(halfItems.begin(), halfItems.end());
        string best = "";
        string mid = (middle != -1) ? string(1, '0'+middle) : "";
        if (halfItems.empty()) {
            string full = mid;
            if ((int)full.size() == L && full > nStr) best = full;
            return best;
        }
        do {
            string rev = halfItems; reverse(rev.begin(), rev.end());
            string full = halfItems + mid + rev;
            if ((int)full.size() != L) continue;
            if (full > nStr) {
                if (best == "" || full < best) best = full;
            }
        } while (next_permutation(halfItems.begin(), halfItems.end()));
        return best;
    }

    long long nextSpecialPalindrome(long long n) {
        string nStr = to_string(n);
        int L0 = nStr.size();
        auto multisets = allMultisets();
        map<int, vector<map<int,int>>> byLen;
        for (auto& [len, counts] : multisets) byLen[len].push_back(counts);

        string best = "";
        if (byLen.count(L0)) {
            for (auto& counts : byLen[L0]) {
                string res = bestGreaterArrangement(counts, nStr);
                if (!res.empty() && (best.empty() || res < best)) best = res;
            }
            if (!best.empty()) return stoll(best);
        }
        for (auto& [l, list] : byLen) {
            if (l <= L0) continue;
            best = "";
            for (auto& counts : list) {
                string arr = minArrangement(counts);
                if (best.empty() || arr < best) best = arr;
            }
            return stoll(best);
        }
        return -1;
    }
};

