int minCost(std::vector<std::vector<int>>& grid, int k) {
    int m = grid.size(), n = grid[0].size();
    const int INF = INT_MAX / 2;
    std::vector<std::vector<std::vector<int>>> f(k+1, std::vector<std::vector<int>>(m, std::vector<int>(n, INF)));
    f[0][0][0] = 0;
    for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
        if (i > 0) f[0][i][j] = std::min(f[0][i][j], f[0][i-1][j] + grid[i][j]);
        if (j > 0) f[0][i][j] = std::min(f[0][i][j], f[0][i][j-1] + grid[i][j]);
    }
    std::map<int, std::vector<std::pair<int,int>>, std::greater<int>> g;
    for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) g[grid[i][j]].push_back({i,j});
    for (int t = 1; t <= k; t++) {
        int mn = INF;
        for (auto& [key, pos] : g) {
            for (auto& [i,j] : pos) mn = std::min(mn, f[t-1][i][j]);
            for (auto& [i,j] : pos) f[t][i][j] = mn;
        }
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            if (i > 0) f[t][i][j] = std::min(f[t][i][j], f[t][i-1][j] + grid[i][j]);
            if (j > 0) f[t][i][j] = std::min(f[t][i][j], f[t][i][j-1] + grid[i][j]);
        }
    }
    int ans = INF;
    for (int t = 0; t <= k; t++) ans = std::min(ans, f[t][m-1][n-1]);
    return ans;
}

class Solution {
public:
    long long numberOfPerfectPairs(vector<int>& nums) {
        int n = nums.size();
        long long count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                long long a = nums[i], b = nums[j];
                long long mn = min(llabs(a - b), llabs(a + b));
                long long mx = max(llabs(a - b), llabs(a + b));
                if (mn <= min(llabs(a), llabs(b)) && mx >= max(llabs(a), llabs(b))) {
                    count++;
                }
            }
        }
        return count;
    }
};

