long long maxProfit(std::vector<int>& prices, std::vector<int>& strategy, int k) {
    int n = prices.size();
    int h = k / 2;
    long long pOriginal = 0;
    for (int i = 0; i < n; i++) pOriginal += (long long)strategy[i] * prices[i];
    long long newSeg = 0;
    for (int i = h; i < k; i++) newSeg += prices[i];
    long long oldSeg = 0;
    for (int i = 0; i < k; i++) oldSeg += (long long)strategy[i] * prices[i];
    long long maxDelta = std::max(0LL, newSeg - oldSeg);
    for (int j = 1; j <= n - k; j++) {
        oldSeg += -(long long)strategy[j-1]*prices[j-1] + (long long)strategy[j+k-1]*prices[j+k-1];
        newSeg += -prices[j-1+h] + prices[j+k-1];
        maxDelta = std::max(maxDelta, newSeg - oldSeg);
    }
    return pOriginal + maxDelta;
}

