long long minimumSumAfterDivisibleSumDeletions(const std::vector<int>& a, int K) {
    long long total = 0;
    for (int v : a) total += v;
    std::unordered_map<int, long long> best;
    best.reserve(a.size() * 2 + 1);
    best[0] = 0;
    long long pref = 0;
    long long dp = 0;
    for (int v : a) {
        pref += v;
        int rem = static_cast<int>((pref % K + K) % K);
        long long cand = dp;
        auto it = best.find(rem);
        if (it != best.end()) {
            cand = std::max(cand, pref + it->second);
        }
        dp = cand;
        long long cur = dp - pref;
        auto it2 = best.find(rem);
        if (it2 == best.end()) {
            best[rem] = cur;
        } else if (cur > it2->second) {
            it2->second = cur;
        }
    }
    return total - dp;
}

