long long dp(int i, int j, int direction) {
    while (i >= 0 && i < n_ && j >= 0 && j < m_ && grid_[i][j] == 1) {
        direction = 1 - direction;
        if (direction == 0) i += 1; else j += 1;
    }
    if (i < 0 || i >= n_ || j < 0 || j >= m_) return 0;
