int minOperations(std::string s, int k) {
    int n = s.size();
    int cnt0 = 0; for (char c : s) if (c=='0') cnt0++;
    std::vector<bool> visited(n+1, false);
    visited[cnt0] = true;
    std::vector<int> q = {cnt0};
    int ans = 0;
    while (!q.empty()) {
        std::vector<int> nxt;
        for (int cur : q) {
            if (cur == 0) return ans;
            int l = cur + k - 2*std::min(cur,k);
            int r = cur + k - 2*std::max(k-n+cur, 0);
            for (int v = l; v <= r; v += 2) {
                if (v < 0 || v > n) continue;
                if (!visited[v]) { visited[v]=true; nxt.push_back(v); }
            }
        }
        q = nxt;
        ans++;
    }
    return -1;
}

