long long maxProduct(std::vector<int>& nums) {
    if (nums.size() < 2) return 0;
    int maxVal = 0;
    std::unordered_map<int, int> freq;
    for (int x : nums) {
        maxVal = std::max(maxVal, x);
        ++freq[x];
    }
    int bits = 0;
    while ((1 << bits) <= maxVal) ++bits;
    if (bits == 0) bits = 1; // at least one bit to avoid size 1<<0 = 1
    int size = 1 << bits;
    std::vector<int> best(size, -1);
    for (int x : nums) {
        best[x] = std::max(best[x], x);
    }
    for (int i = 0; i < bits; ++i) {
        for (int mask = 0; mask < size; ++mask) {
            if (mask & (1 << i)) {
                best[mask] = std::max(best[mask], best[mask ^ (1 << i)]);
            }
        }
    }
    long long ans = 0;
    int fullMask = size - 1;
    for (int x : nums) {
        int complement = fullMask ^ x;
        int y = best[complement];
        if (y == -1) continue;
        if (y == x && freq[x] < 2) continue;
        ans = std::max(ans, static_cast<long long>(x) * y);
    }
    return ans;
}

long long _countIncreasingSubseqs(vector<int>& values) {
    const long long MOD = 1e9 + 7;
    if (values.empty()) return 0;
    vector<int> sortedUnique = values;
    sort(sortedUnique.begin(), sortedUnique.end());
    sortedUnique.erase(unique(sortedUnique.begin(), sortedUnique.end()), sortedUnique.end());
    int m = sortedUnique.size();
    vector<long long> bit(m + 1, 0);
    auto update = [&](int i, long long delta) {
        for (; i <= m; i += i & (-i)) bit[i] = (bit[i] + delta) % MOD;
    };
    auto query = [&](int i) {
        long long s = 0;
        for (; i > 0; i -= i & (-i)) s = (s + bit[i]) % MOD;
        return s;
    };
    long long total = 0;
    for (int v : values) {
        int r = lower_bound(sortedUnique.begin(), sortedUnique.end(), v) - sortedUnique.begin() + 1;
        long long prefix = query(r - 1);
        long long dp = (1 + prefix) % MOD;
        update(r, dp);
        total = (total + dp) % MOD;
    }
    return total;
}

class Solution {
public:
    int sumOfBeauty(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        int maxv = *max_element(nums.begin(), nums.end());
        vector<long long> f(maxv + 1, 0);
        for (int g = 1; g <= maxv; g++) {
            vector<int> filtered;
            for (int x : nums) if (x % g == 0) filtered.push_back(x);
            f[g] = _countIncreasingSubseqs(filtered);
        }
        vector<long long> exact(maxv + 2, 0);
        long long ans = 0;
        for (int g = maxv; g >= 1; g--) {
            long long val = f[g];
            for (int m = 2 * g; m <= maxv; m += g) {
                val = (val - exact[m] % MOD + MOD) % MOD;
            }
            exact[g] = val;
            ans = (ans + (long long) g % MOD * exact[g]) % MOD;
        }
        return (int) ans;
    }
};

