std::vector<long long> balancedKFactorDecomposition(long long n, int k){
    std::vector<long long> path(k,0), best;
    long long bestD = LLONG_MAX;
    std::function<void(int,long long,long long,long long)> dfs = [&](int i, long long x, long long mi, long long mx){
        if (i==0){
            long long d = std::max(mx,x)-std::min(mi,x);
