unsigned long long buildPalindrome(unsigned long long prefix, int totalLen) {
    unsigned long long pal = prefix;
    unsigned long long rev = prefix;
    if (totalLen % 2 == 1) {
        rev >>= 1;
    }
    while (rev > 0) {
        pal = (pal << 1) | (rev & 1ULL);
        rev >>= 1;
    }
    return pal;
}

unsigned long long countBinaryPalindromes(unsigned long long N) {
    // FIXED: original returned 0 for N==0 and never counted the number 0 in the
    // general case either, even though "0" is itself a valid binary palindrome
    // that must always be included whenever N >= 0.
    if (N == 0) return 1;
    int binLen = 0;
    unsigned long long tmp = N;
    while (tmp > 0) {
        ++binLen;
        tmp >>= 1;
    }
    unsigned long long total = 1; // count the number 0 itself
    for (int len = 1; len < binLen; ++len) {
        int half = (len + 1) / 2;
        total += 1ULL << (half - 1);
    }
    int halfLen = (binLen + 1) / 2;
    unsigned long long start = 1ULL << (halfLen - 1);
    unsigned long long end = 1ULL << halfLen;
    for (unsigned long long prefix = start; prefix < end; ++prefix) {
        unsigned long long palindrome = buildPalindrome(prefix, binLen);
        if (palindrome <= N) ++total;
    }
    return total;
}

