unsigned long long maximumXOR(const std::vector<unsigned long long>& arr) {
    const int MAX_BIT = 60;
    std::vector<unsigned long long> basis(MAX_BIT + 1, 0ULL);

    for (unsigned long long num : arr) {
        unsigned long long x = num;
        for (int b = MAX_BIT; b >= 0; --b) {
            if (((x >> b) & 1ULL) == 0ULL) continue;
            if (basis[b] == 0ULL) {
                basis[b] = x;
                break;
            }
            x ^= basis[b];
        }
    }

    unsigned long long result = 0ULL;
    for (int b = MAX_BIT; b >= 0; --b) {
        if ((result ^ basis[b]) > result) {
            result ^= basis[b];
        }
    }
    return result;
}

class Solution {
public:
    static const int MAXK = 4001;
    vector<bool> subsequenceSumAfterCapping(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> freq(n + 2, 0);
        for (int v : nums) freq[v]++;
        // freeDP: achievable sums using items whose true value <= current x (uncapped, real value)
        bitset<MAXK> freeDP;
        freeDP[0] = 1;
        int runningCappedCount = n; // items still strictly above current x, each contributing exactly x
        vector<bool> ans(n, false);
        for (int x = 1; x <= n; x++) {
            int cntX = freq[x];
            for (int i = 0; i < cntX; i++) {
                freeDP |= (freeDP << x);
            }
            runningCappedCount -= cntX;
            int m = runningCappedCount;
            int maxJ = min(m, k / x);
            // combine freeDP with 0..m copies of value x (harmonic-series bitset trick)
            bitset<MAXK> combined;
            bitset<MAXK> shifted = freeDP;
            for (int j = 0; j <= maxJ; j++) {
                combined |= shifted;
                shifted <<= x;
            }
            ans[x - 1] = combined[k];
        }
        return ans;
    }
};

