int minArrivalsToDiscard(std::vector<int>& arrivals, int w, int m) {
    int n = arrivals.size();
    std::vector<bool> kept(n, false);
    std::unordered_map<int,int> cnt;
    int discards = 0;
    for (int i = 0; i < n; i++) {
        int x = arrivals[i];
        int left = i - w;
        if (left >= 0 && kept[left]) cnt[arrivals[left]]--;
        if (cnt[x] >= m) { discards++; kept[i] = false; }
        else { cnt[x]++; kept[i] = true; }
    }
    return discards;
}

class Solution {
public:
    vector<vector<int>> generateSchedule(int n) {
        if (n <= 4) return {};
        map<pair<int,int>, bool> remaining;
        vector<int> deg(n, 0);
        for (int a = 0; a < n; a++)
            for (int b = 0; b < n; b++)
                if (a != b) { remaining[{a,b}] = true; deg[a]++; deg[b]++; }

        vector<vector<int>> seq;
        pair<int,int> last = {-1,-1};
        bool hasLast = false;
        int total = n*(n-1);
        for (int step = 0; step < total; step++) {
            int bestA=-1, bestB=-1, bestScore=-1;
            for (auto& [p, avail] : remaining) {
                if (!avail) continue;
                int a = p.first, b = p.second;
                if (hasLast && (a==last.first||a==last.second||b==last.first||b==last.second)) continue;
                int score = deg[a]+deg[b];
                if (score > bestScore) { bestScore = score; bestA = a; bestB = b; }
            }
            if (bestA == -1) return {};
            remaining[{bestA,bestB}] = false;
            deg[bestA]--; deg[bestB]--;
            seq.push_back({bestA,bestB});
            last = {bestA,bestB}; hasLast = true;
        }
        return seq;
    }
};

