class Solution {
public:
    int minSplitMerge(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        vector<int> start = nums1, target = nums2;
        if (start == target) return 0;
        // n <= 6 (per constraints), so BFS over the full state space of array configurations is feasible
        set<vector<int>> visited;
        visited.insert(start);
        queue<vector<int>> q;
        q.push(start);
        int steps = 0;
        while (!q.empty()) {
            steps++;
            int sz = q.size();
            for (int s = 0; s < sz; s++) {
                vector<int> cur = q.front(); q.pop();
                for (int l = 0; l < n; l++) {
                    for (int r = l; r < n; r++) {
                        vector<int> sub(cur.begin() + l, cur.begin() + r + 1);
                        vector<int> rest;
                        rest.insert(rest.end(), cur.begin(), cur.begin() + l);
                        rest.insert(rest.end(), cur.begin() + r + 1, cur.end());
                        for (int pos = 0; pos <= (int) rest.size(); pos++) {
                            vector<int> newState;
                            newState.insert(newState.end(), rest.begin(), rest.begin() + pos);
                            newState.insert(newState.end(), sub.begin(), sub.end());
                            newState.insert(newState.end(), rest.begin() + pos, rest.end());
                            if (newState == target) return steps;
                            if (!visited.count(newState)) {
                                visited.insert(newState);
                                q.push(newState);
                            }
                        }
                    }
                }
            }
        }
        return -1;
    }
};

