long long maxAlternatingSum(const std::vector<int>& arr, const std::vector<std::pair<int,int>>& swaps) {
    int n = static_cast<int>(arr.size());
    std::vector<int> parent(n);
    std::vector<int> rank(n, 0);
    for (int i = 0; i < n; ++i) parent[i] = i;

    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    auto union_sets = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) std::swap(ra, rb);
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) ++rank[ra];
    };

    for (const auto& p : swaps) {
        union_sets(p.first, p.second);
    }

    std::unordered_map<int, std::vector<int>> groups;
    groups.reserve(n);
    for (int i = 0; i < n; ++i) {
        int r = find(i);
        groups[r].push_back(i);
    }

    long long total = 0;
    for (auto& kv : groups) {
        const std::vector<int>& idxList = kv.second;
        std::vector<int> values;
        values.reserve(idxList.size());
        for (int i : idxList) values.push_back(arr[i]);
        std::sort(values.begin(), values.end(), std::greater<int>());

        int posCnt = 0;
        for (int i : idxList) if (i % 2 == 0) ++posCnt;

        long long posSum = 0, negSum = 0;
        for (size_t k = 0; k < values.size(); ++k) {
            if (static_cast<int>(k) < posCnt) posSum += values[k];
            else                           negSum += values[k];
        }
        total += posSum - negSum;
    }

    return total;
}

