long long splitArrayMinDiff(const std::vector<int>& arr) {
    int n = (int)arr.size();
    if (n < 2) return -1;
    std::vector<long long> s(n);
    s[0] = arr[0];
    std::vector<bool> f(n, true), g(n, true);
    for (int i = 1; i < n; i++) {
        s[i] = s[i-1] + arr[i];
        f[i] = f[i-1] && arr[i] > arr[i-1];
    }
    for (int i = n-2; i >= 0; i--) {
        g[i] = g[i+1] && arr[i] > arr[i+1];
    }
    long long ans = -1;
    bool found = false;
    for (int i = 0; i < n-1; i++) {
        if (f[i] && g[i+1]) {
            long long leftSum = s[i];
            long long rightSum = s[n-1] - s[i];
            long long diff = std::abs(leftSum - rightSum);
            if (!found || diff < ans) { ans = diff; found = true; }
        }
    }
    return found ? ans : -1;
}

