const long long MOD = 1000000007LL;
long long numberOfZigZagArrays(int n, int m) {
    if (n == 1) return m % MOD;
    std::vector<long long> dp(m + 2, 1), ndp(m + 2, 0);
    for (int i = 2; i <= n; ++i) {
        std::vector<long long> pref(m + 2, 0);
        for (int v = 1; v <= m; ++v) pref[v] = (pref[v-1] + dp[v]) % MOD;
        long long total = pref[m];
        if (i % 2 == 0) { for (int v = 1; v <= m; ++v) ndp[v] = pref[v-1]; }
        else { for (int v = 1; v <= m; ++v) ndp[v] = (total - pref[v] + MOD) % MOD; }
        dp.swap(ndp);
    }
    long long half = 0;
    for (int v = 1; v <= m; ++v) half = (half + dp[v]) % MOD;
    return (half * 2) % MOD;
}

