std::string removeSubstring(const std::string& s, int k) {
    struct Frame {
        std::size_t pos;
        int openCount;
    };
    std::vector<Frame> stack;
    std::string result;
    result.reserve(s.size());
    for (char c : s) {
        if (c == '(') {
            stack.push_back({result.size(), 1});
            result.push_back(c);
        } else { // c == ')'
            if (stack.empty()) {
                result.push_back(c);
                continue;
            }
            Frame top = stack.back();
            stack.pop_back();
            if (top.openCount == k) {
                result.resize(top.pos);
            } else {
                result.push_back(c);
                if (!stack.empty()) {
                    stack.back().openCount += top.openCount;
                }
            }
        }
    }
    return result;
}

