int longestBalancedSubstring(const std::string& s) {
    const int ALPH = 256;
    int n = static_cast<int>(s.size());
    int maxLen = 0;
    for (int i = 0; i < n; ++i) {
        int cnt[ALPH] = {0};
        for (int j = i; j < n; ++j) {
            unsigned char ch = static_cast<unsigned char>(s[j]);
            ++cnt[ch];
            int mn = INT_MAX, mx = 0;
            for (int k = 0; k < ALPH; ++k) {
                if (cnt[k] > 0) {
                    mn = std::min(mn, cnt[k]);
                    mx = std::max(mx, cnt[k]);
                }
            }
            if (mn == mx) {
                int len = j - i + 1;
                if (len > maxLen) maxLen = len;
            }
        }
    }
    return maxLen;
}

