    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + (s[i] - 'a' + 1);
    }
    for (int i = 0; i < n; ++i) {
        for (int len = 2; i + len <= n; len += 2) {
            int mid = i + len / 2;
            int sum1 = pref[mid] - pref[i];
