long long sumOfAncestors(int n, std::vector<std::vector<int>>& edges, std::vector<int>& nums) {
    auto squarefree = [](long long num) {
        for (long long i = 2; i*i <= num; i++) while (num % (i*i) == 0) num /= (i*i);
        return num;
    };
    std::vector<long long> vals(n);
    for (int i = 0; i < n; i++) vals[i] = squarefree(nums[i]);
    std::vector<std::vector<int>> graph(n);
    for (auto& e : edges) { graph[e[0]].push_back(e[1]); graph[e[1]].push_back(e[0]); }
    long long ans = 0;
    std::unordered_map<long long,int> history;
    std::function<void(int,int)> dfs = [&](int u, int p) {
        long long v = vals[u];
        ans += history[v];
        history[v]++;
        for (int w : graph[u]) if (w != p) dfs(w, u);
        history[v]--;
    };
    dfs(0, -1);
    return ans;
}

