long long maximumPartitionFactor(const std::vector<std::vector<int>>& points) {
    if (points.size() < 2) return 0;
    long long maxSum = LLONG_MIN, minSum = LLONG_MAX, maxDiff = LLONG_MIN, minDiff = LLONG_MAX;
    for (auto& p : points) {
        long long s = p[0] + p[1], d = p[0] - p[1];
        maxSum = std::max(maxSum, s);
        minSum = std::min(minSum, s);
        maxDiff = std::max(maxDiff, d);
        minDiff = std::min(minDiff, d);
    }
    return std::max(maxSum - minSum, maxDiff - minDiff);
}

