std::string smallestPermutationGreater(const std::string& s, const std::string& target) {
    int n = (int)s.size();
    std::array<int,26> base{};
    for (char c : s) base[c-'a']++;
    std::string best = "";
    bool found = false;
    for (int i = n-1; i >= 0; i--) {
        auto count = base;
        bool ok = true;
        for (int j = 0; j < i; j++) {
            int idx = target[j]-'a';
            if (count[idx] == 0) { ok = false; break; }
            count[idx]--;
        }
        if (!ok) continue;
        int tIdx = target[i]-'a';
        int pick = -1;
        for (int d = tIdx+1; d < 26; d++) if (count[d] > 0) { pick = d; break; }
        if (pick == -1) continue;
        count[pick]--;
        std::string suffix;
        for (int d = 0; d < 26; d++) suffix += std::string(count[d], 'a'+d);
        std::string candidate = target.substr(0, i) + char('a'+pick) + suffix;
        if (!found || candidate < best) { best = candidate; found = true; }
    }
    return best;
}

