int longestBalancedSubarray(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    int best = 0;
    for (int i = 0; i < n; ++i) {
        std::unordered_set<int> evens;
        std::unordered_set<int> odds;
        for (int j = i; j < n; ++j) {
            int x = nums[j];
            if (x % 2 == 0) {
                evens.insert(x);
            } else {
                odds.insert(x);
            }
            if (evens.size() == odds.size()) {
                int len = j - i + 1;
                if (len > best) best = len;
            }
        }
    }
    return best;
}

#include <bits/stdc++.h>

int countWays(const std::vector<std::vector<int>>& rows) {
    const int MOD = 1000000007;
    int maxVal = 0;
    for (const auto& r : rows) {
        for (int v : r) {
            if (v > maxVal) maxVal = v;
        }
    }
    std::vector<int> mu(maxVal + 1, 1);
    std::vector<int> is_composite(maxVal + 1, 0);
    std::vector<int> primes;
    mu[0] = 0;
    for (int i = 2; i <= maxVal; ++i) {
        if (!is_composite[i]) {
            primes.push_back(i);
            mu[i] = -1;
        }
        for (int p : primes) {
            long long v = 1LL * i * p;
            if (v > maxVal) break;
            is_composite[v] = 1;
            if (i % p == 0) {
                mu[v] = 0;
                break;
            } else {
                mu[v] = -mu[i];
            }
        }
    }
    std::vector<long long> ways(maxVal + 1, 0);
    for (int d = 1; d <= maxVal; ++d) {
        long long prod = 1;
        for (const auto& row : rows) {
            int cnt = 0;
            for (int val : row) {
                if (val % d == 0) ++cnt;
            }
            prod = (prod * cnt) % MOD;
            if (prod == 0) break;
        }
        ways[d] = prod;
    }
    long long ans = 0;
    for (int d = 1; d <= maxVal; ++d) {
        if (mu[d] == 0) continue;
        ans = (ans + mu[d] * ways[d]) % MOD;
    }
    if (ans < 0) ans += MOD;
    return static_cast<int>(ans);
}

