long long maxAlternatingSumSquares(const std::vector<long long>& arr) {
    std::vector<long long> squares(arr.size());
    for (size_t i = 0; i < arr.size(); ++i) {
        squares[i] = arr[i] * arr[i];
    }
    std::sort(squares.begin(), squares.end(), std::greater<long long>());
    size_t posCount = (squares.size() + 1) / 2;
    long long posSum = 0, negSum = 0;
    for (size_t i = 0; i < posCount; ++i) {
        posSum += squares[i];
    }
    for (size_t i = posCount; i < squares.size(); ++i) {
        negSum += squares[i];
    }
    return posSum - negSum;
}

