string lexicographicallySmallestStringAfterReverse(const string& s) {
    int n = (int)s.size();
    string ans = s;
    for (int k = 1; k <= n; k++) {
        string t1 = s.substr(0, k);
        reverse(t1.begin(), t1.end());
        t1 += s.substr(k);
        string t2 = s.substr(0, n - k);
        string suf = s.substr(n - k);
        reverse(suf.begin(), suf.end());
        t2 += suf;
        if (t1 < ans) ans = t1;
        if (t2 < ans) ans = t2;
    }
    return ans;
}

#include <bits/stdc++.h>
long long minOperations(std::vector<int>& nums1, std::vector<int>& nums2) {
    int n = nums1.size();
    long long base = 0;
    for (int i = 0; i < n; i++) base += std::abs(nums1[i] - nums2[i]);
    int target = nums2[n];
    long long bestExtra = LLONG_MAX;
    for (int i = 0; i < n; i++) {
        int lo = std::min(nums1[i], nums2[i]), hi = std::max(nums1[i], nums2[i]);
        long long extra;
        if (target < lo) extra = lo - target;
        else if (target > hi) extra = target - hi;
        else extra = 0;
        bestExtra = std::min(bestExtra, extra);
    }
    return base + 1 + bestExtra;
}

