long long countStableSubarrays(const vector<int>& capacity) {
    int n = (int)capacity.size();
    vector<long long> s(n + 1, 0);
    for (int i = 1; i <= n; i++) s[i] = s[i - 1] + capacity[i - 1];

    map<pair<int,long long>, int> cnt;
    long long ans = 0;
    for (int r = 2; r < n; r++) {
        int l = r - 2;
        int lv = capacity[l];
        auto leftKey = make_pair(lv, s[l] + 2LL * lv);
        cnt[leftKey]++;

        int rv = capacity[r];
        auto rightKey = make_pair(rv, s[r]);
        auto it = cnt.find(rightKey);
        if (it != cnt.end()) ans += it->second;
    }
    return ans;
}

