#include <bits/stdc++.h>

std::string solvePalindromicPermutation(const std::string& s, const std::string& t) {
    int n = static_cast<int>(s.size());
    if (n != static_cast<int>(t.size())) return "";
    int cnt[256] = {0};
    for (unsigned char c : s) cnt[c]++;
    int oddCount = 0;
    for (int i = 0; i < 256; ++i) if (cnt[i] % 2) ++oddCount;
    if (oddCount > (n % 2)) return "";
    std::string res(n, ' ');
    int half = n / 2;
    std::function<bool(int, bool)> dfs = [&](int pos, bool greater) -> bool {
        if (pos == half) {
            if (n % 2) {
                unsigned char start = greater ? 0 : static_cast<unsigned char>(t[half]);
                for (int c = start; c < 256; ++c) {
                    if (cnt[c] > 0) {
                        res[half] = static_cast<char>(c);
                        cnt[c]--;
                        if (res > t) return true;
                        cnt[c]++;
                    }
                }
                return false;
            } else {
                return res > t;
            }
        }
        unsigned char start = greater ? 0 : static_cast<unsigned char>(t[pos]);
        for (int c = start; c < 256; ++c) {
            if (cnt[c] >= 2) {
                cnt[c] -= 2;
                res[pos] = res[n - 1 - pos] = static_cast<char>(c);
                bool nextGreater = greater || (c > static_cast<unsigned char>(t[pos]));
                if (dfs(pos + 1, nextGreater)) return true;
                cnt[c] += 2;
            }
        }
        return false;
    };
    if (dfs(0, false)) return res;
    return "";
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>
#include <unordered_map>

long long countSubarrays(const std::vector<int>& nums, int x) {
    int n = static_cast<int>(nums.size());
    std::vector<long long> pref(n + 1);
    pref[0] = 0;
    for (int i = 0; i < n; ++i) {
        pref[i + 1] = pref[i] + (nums[i] == x ? 1 : -1);
    }

    std::vector<long long> uniq = pref;
    std::sort(uniq.begin(), uniq.end());
    uniq.erase(std::unique(uniq.begin(), uniq.end()), uniq.end());

    std::unordered_map<long long, int> comp;
    comp.reserve(uniq.size() * 2);
    for (size_t i = 0; i < uniq.size(); ++i) {
        comp[uniq[i]] = static_cast<int>(i) + 1; // 1‑based index for BIT
    }

    std::vector<int> bit(uniq.size() + 2, 0);
    auto add = [&](int i, int delta) {
        while (i < static_cast<int>(bit.size())) {
            bit[i] += delta;
            i += i & -i;
        }
    };
    auto sum = [&](int i) {
        long long s = 0;
        while (i > 0) {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    };

    long long ans = 0;
    add(comp[pref[0]], 1);
    for (int i = 1; i <= n; ++i) {
        int idx = comp[pref[i]];
        ans += sum(idx - 1);
        add(idx, 1);
    }
    return ans;
}

#include <bits/stdc++.h>
long long minTime(std::vector<long long>& d, std::vector<long long>& r) {
    long long d1 = d[0], d2 = d[1], r1 = r[0], r2 = r[1];
    long long lcm = r1 / std::__gcd(r1, r2) * r2;
    auto feasible = [&](long long T) {
        long long a1 = T - T/r1;
        long long a2 = T - T/r2;
        long long atotal = T - T/lcm;
        return a1 >= d1 && a2 >= d2 && atotal >= d1 + d2;
    };
    long long lo = 1, hi = 4000000000LL;
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (feasible(mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
}

#include <bits/stdc++.h>
using namespace std;

long long countSubarrays(const vector<int>& nums, int target) {
    int n = (int)nums.size();
    int offset = n + 1;
    int size = 2 * n + 3;
    vector<long long> bit(size, 0);
    auto add = [&](int i) { for (; i < size; i += i & -i) bit[i]++; };
    auto query = [&](int i) { long long s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; };

    long long pref = 0, ans = 0;
    add(offset);
    for (int x : nums) {
        pref += (x == target) ? 1 : -1;
        int idx = (int)(pref + offset);
        ans += query(idx - 1);
        add(idx);
    }
    return ans;
}

#include <bits/stdc++.h>
static const long long NEG = LLONG_MIN / 4;
long long linearBest(const std::vector<int>& a, int k) {
    std::vector<std::array<long long,3>> f(k + 1, {NEG, NEG, NEG});
    f[0][1] = 0;
    for (int x : a) {
        auto g = f;
        for (int c = 0; c <= k; c++) for (int bi = 0; bi < 3; bi++) {
            long long cur = f[c][bi];
            if (cur == NEG) continue;
            int b = bi - 1;
            for (int sign : {1, -1}) {
                int nb = b + sign;
                if (nb < -1 || nb > 1) continue;
                int nc = c + (nb == 0 ? 1 : 0);
                if (nc > k) continue;
                long long val = cur + (long long)sign * x;
                if (val > g[nc][nb + 1]) g[nc][nb + 1] = val;
            }
        }
        f = g;
    }
    long long best = NEG;
    for (int c = 0; c <= k; c++) best = std::max(best, f[c][1]);
    return best;
}
long long maxCyclicPartitionScore(std::vector<int>& nums, int k) {
    int n = nums.size();
    long long ans = NEG;
    for (int r = 0; r < n; r++) {
        std::vector<int> a;
        for (int i = 0; i < n; i++) a.push_back(nums[(r + i) % n]);
        ans = std::max(ans, linearBest(a, k));
    }
    return ans;
}

#include <bits/stdc++.h>
#include <vector>
#include <algorithm>

int longestNonDecreasingAfterOneReplace(const std::vector<int>& arr) {
    int n = static_cast<int>(arr.size());
    if (n <= 2) return n;

    std::vector<int> left(n);
    std::vector<int> right(n);

    left[0] = 1;
    for (int i = 1; i < n; ++i) {
        left[i] = (arr[i] >= arr[i - 1]) ? left[i - 1] + 1 : 1;
    }

    right[n - 1] = 1;
    for (int i = n - 2; i >= 0; --i) {
        right[i] = (arr[i] <= arr[i + 1]) ? right[i + 1] + 1 : 1;
    }

    int best = 1;
    for (int i = 0; i < n; ++i) {
        best = std::max(best, left[i]);
    }

    for (int i = 0; i < n; ++i) {
        if (i > 0) best = std::max(best, left[i - 1] + 1);
        if (i < n - 1) best = std::max(best, right[i + 1] + 1);
        if (i > 0 && i < n - 1 && arr[i - 1] <= arr[i + 1]) {
            best = std::max(best, left[i - 1] + 1 + right[i + 1]);
        }
    }

    return std::min(best, n);
}

