#include <bits/stdc++.h>
int maxPathScore(std::vector<std::vector<int>>& grid, int k) {
    int m = grid.size(), n = grid[0].size();
    const int NEG = -1e9;
    std::vector<std::vector<std::vector<int>>> f(m, std::vector<std::vector<int>>(n, std::vector<int>(k+1, NEG)));
    f[0][0][0] = 0;
    for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) for (int c = 0; c <= k; c++) {
        if (i == 0 && j == 0) continue;
        int cost = grid[i][j] > 0 ? 1 : 0;
        if (c < cost) continue;
        int best = NEG;
        if (i > 0 && f[i-1][j][c-cost] > NEG) best = std::max(best, f[i-1][j][c-cost]);
        if (j > 0 && f[i][j-1][c-cost] > NEG) best = std::max(best, f[i][j-1][c-cost]);
        if (best > NEG) f[i][j][c] = best + grid[i][j];
    }
    int ans = NEG;
    for (int c = 0; c <= k; c++) ans = std::max(ans, f[m-1][n-1][c]);
    return ans <= NEG ? -1 : ans;
}

