std::vector<long long> countStableSubarrays(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
    int n = nums.size();
    std::vector<int> f(n, 1);
    for (int i = 1; i < n; i++) f[i] = nums[i] >= nums[i-1] ? f[i-1] + 1 : 1;
    std::vector<long long> out;
    for (auto& q : queries) {
        long long t = 0;
        for (int i = q[0]; i <= q[1]; i++) t += std::min(f[i], i - q[0] + 1);
        out.push_back(t);
    }
    return out;
}

