long long countDistinctIntegers(long long n) {
    unordered_set<long long> seen;
    for (long long i = 1; i <= n; i++) {
        long long x = i, y = 0, mul = 1;
        while (x) {
            int d = x % 10;
            if (d != 0) { y += d * mul; mul *= 10; }
            x /= 10;
        }
        seen.insert(y);
    }
    return (long long)seen.size();
}

#include <bits/stdc++.h>
long long maxExpression(const std::vector<long long>& nums) {
    int n = nums.size();
    std::vector<long long> suf(n);
    suf[n - 1] = nums[n - 1];
    for (int i = n - 2; i >= 0; i--) suf[i] = std::max(suf[i + 1], nums[i]);
    long long pre = nums[0], best = LLONG_MIN;
    for (int j = 1; j < n - 1; j++) {
        best = std::max(best, pre - nums[j] + suf[j + 1]);
        pre = std::max(pre, nums[j]);
    }
    return best;
}

