int maxBalancedXorLength(const vector<int>& nums) {
    map<pair<int,int>, int> firstPos;
    firstPos[{0, 0}] = -1;
    int xorVal = 0, delta = 0, maxLen = 0;
    for (int i = 0; i < (int)nums.size(); i++) {
        xorVal ^= nums[i];
        delta += (nums[i] % 2 == 0) ? 1 : -1;
        auto key = make_pair(xorVal, delta);
        auto it = firstPos.find(key);
        if (it != firstPos.end()) {
            int len = i - it->second;
            if (len > maxLen) maxLen = len;
        } else {
            firstPos[key] = i;
        }
    }
    return maxLen;
}

