std::vector<int> smallestNegatedPermutation(int n, int target) {
    long long total = 1LL * n * (n + 1) / 2;
    if (std::llabs(target) > total || ((total - target) & 1LL)) {
        return {};
    }
    long long needNegSum = (total - target) / 2;
    std::vector<int> ans;
    std::vector<char> used(n + 1, 0);
    for (int i = n; i >= 1; --i) {
        if (needNegSum >= i) {
            ans.push_back(-i);
            used[i] = 1;
            needNegSum -= i;
        }
    }
    for (int i = 1; i <= n; ++i) {
        if (!used[i]) {
            ans.push_back(i);
        }
    }
    return ans;
}

