static std::pair<long long,long long> go(int pos, int prev, int tight, int started) {
    if (pos == (int)dg.size()) return {1, 0};
    auto key = std::make_tuple(pos, prev, tight, started);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;
    long long cnt = 0, tot = 0;
    int hi = tight ? dg[pos] : 9;
