int minMirrorDistance(const std::vector<int>& arr) {
    std::unordered_map<int, int> revPos;
    int best = std::numeric_limits<int>::max();
    for (int i = 0; i < static_cast<int>(arr.size()); ++i) {
        int x = arr[i];
        auto it = revPos.find(x);
        if (it != revPos.end()) {
            int dist = i - it->second;
            if (dist < best) best = dist;
        }
        int rev = 0, tmp = x;
        while (tmp > 0) {
            rev = rev * 10 + (tmp % 10);
            tmp /= 10;
        }
        if (revPos.find(rev) == revPos.end()) {
            revPos[rev] = i;
        }
    }
    return best == std::numeric_limits<int>::max() ? -1 : best;
}

