long long minInversionCount(const std::vector<int>& arr, int k) {
    int n = static_cast<int>(arr.size());
    if (k > n) return 0;

    std::vector<int> sorted = arr;
    std::sort(sorted.begin(), sorted.end());
    sorted.erase(std::unique(sorted.begin(), sorted.end()), sorted.end());

    std::unordered_map<int, int> comp;
    comp.reserve(sorted.size() * 2);
    for (int i = 0; i < static_cast<int>(sorted.size()); ++i) {
        comp[sorted[i]] = i + 1; // BIT is 1‑based
    }

    int size = static_cast<int>(sorted.size());
    std::vector<int> bit(size + 1, 0);
    auto add = [&](int idx, int delta) {
        while (idx <= size) {
            bit[idx] += delta;
            idx += idx & -idx;
        }
    };
    auto sum = [&](int idx) {
        int res = 0;
        while (idx > 0) {
            res += bit[idx];
            idx -= idx & -idx;
        }
        return res;
    };

    long long inv = 0;
    for (int i = 0; i < k; ++i) {
        int idx = comp.at(arr[i]);
        inv += i - sum(idx);
        add(idx, 1);
    }

    long long best = inv;

    for (int left = 0, right = k; right < n; ++left, ++right) {
        int outIdx = comp.at(arr[left]);
        int lessThanOut = sum(outIdx - 1);
        inv -= lessThanOut;
        add(outIdx, -1);

        int inIdx = comp.at(arr[right]);
        int greaterThanIn = (k - 1) - sum(inIdx);
        inv += greaterThanIn;
        add(inIdx, 1);

        if (inv < best) best = inv;
    }

    return best;
}

