static long long reflectedValue(int x) {
    long long res = 0;
    while (x > 0) {
        res = (res << 1) | (x & 1);
        x >>= 1;
    }
    return res;
}

std::vector<int> sortByReflection(const std::vector<int>& nums) {
    std::vector<std::pair<long long, int>> paired;
    paired.reserve(nums.size());
    for (int v : nums) {
        paired.emplace_back(reflectedValue(v), v);
    }
    std::stable_sort(paired.begin(), paired.end(),
        [](const std::pair<long long, int>& a, const std::pair<long long, int>& b) {
            if (a.first != b.first) return a.first < b.first;
            return a.second < b.second;
        });
    std::vector<int> result;
    result.reserve(paired.size());
    for (const auto& p : paired) {
        result.push_back(p.second);
    }
    return result;
}

