std::vector<long long> maxSubgraphScore(int n, std::vector<std::vector<int>>& edges, std::vector<int>& good) {
    std::vector<std::vector<int>> adj(n);
    for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
    std::vector<int> value(n);
    for (int i = 0; i < n; i++) value[i] = good[i] == 1 ? 1 : -1;
    std::vector<int> parent(n, -1), order; order.reserve(n);
    std::vector<bool> visited(n, false);
    std::vector<int> stack = {0}; visited[0] = true;
    while (!stack.empty()) {
        int u = stack.back(); stack.pop_back();
        order.push_back(u);
        for (int v : adj[u]) if (!visited[v]) { visited[v] = true; parent[v] = u; stack.push_back(v); }
    }
    std::vector<std::vector<int>> children(n);
    for (int v = 0; v < n; v++) if (parent[v] != -1) children[parent[v]].push_back(v);
    std::vector<int> depth(n, 0);
    for (int u : order) if (parent[u] != -1) depth[u] = depth[parent[u]] + 1;
    std::vector<long long> down(n, 0);
    std::vector<int> byDepthDesc = order;
    std::sort(byDepthDesc.begin(), byDepthDesc.end(), [&](int a, int b){return depth[a] > depth[b];});
    for (int u : byDepthDesc) {
        long long s = value[u];
        for (int c : children[u]) s += std::max(0LL, down[c]);
        down[u] = s;
    }
    std::vector<long long> totalChildContrib(n, 0);
    for (int u = 0; u < n; u++) totalChildContrib[u] = down[u] - value[u];
    std::vector<long long> up(n, 0);
    std::vector<int> byDepthAsc = order;
    std::sort(byDepthAsc.begin(), byDepthAsc.end(), [&](int a, int b){return depth[a] < depth[b];});
    for (int u : byDepthAsc) {
        for (int c : children[u]) {
            long long siblingSum = totalChildContrib[u] - std::max(0LL, down[c]);
            up[c] = value[u] + std::max(0LL, up[u]) + siblingSum;
        }
    }
    std::vector<long long> answer(n);
    for (int i = 0; i < n; i++) answer[i] = down[i] + std::max(0LL, up[i]);
    return answer;
}

