long long maxScore(const vector<int>& technique1, const vector<int>& technique2, int k) {
    int n = (int)technique1.size();
    long long total = 0;
    int natural = 0;
    vector<int> losses;
    for (int i = 0; i < n; i++) {
        int a = technique1[i], b = technique2[i];
        total += max(a, b);
        if (a >= b) natural++;
        else losses.push_back(b - a);
    }
    int need = max(0, k - natural);
    sort(losses.begin(), losses.end());
    for (int i = 0; i < need && i < (int)losses.size(); i++) total -= losses[i];
    return total;
}

