class Solution {
public:
    long long minMoves(vector<int>& balance) {
        int n = balance.size();
        long long total = 0;
        for (auto b : balance) total += b;
        if (total < 0) return -1;
        long long mn = balance[0];
        int idx = 0;
        for (int i = 1; i < n; i++) {
            if (balance[i] < mn) { mn = balance[i]; idx = i; }
        }
        if (mn >= 0) return 0;
        long long deficit = -mn;
        vector<pair<long long,long long>> leftAvail, rightAvail; // dist, amt
        for (int j = 1; j < n; j++) {
            int li = ((idx - j) % n + n) % n;
            int ri = (idx + j) % n;
            if (balance[li] > 0) leftAvail.push_back({j, balance[li]});
            if (balance[ri] > 0) rightAvail.push_back({j, balance[ri]});
        }
        size_t li = 0, ri = 0;
        long long moves = 0;
        while (deficit > 0) {
            bool canLeft = li < leftAvail.size();
            bool canRight = ri < rightAvail.size();
            if (!canLeft && !canRight) break;
            if (canLeft && (!canRight || leftAvail[li].first <= rightAvail[ri].first)) {
                long long dist = leftAvail[li].first, amt = leftAvail[li].second;
                long long take = min(amt, deficit);
                moves += take * dist;
                deficit -= take;
                leftAvail[li].second -= take;
                if (leftAvail[li].second == 0) li++;
            } else {
                long long dist = rightAvail[ri].first, amt = rightAvail[ri].second;
                long long take = min(amt, deficit);
                moves += take * dist;
                deficit -= take;
                rightAvail[ri].second -= take;
                if (rightAvail[ri].second == 0) ri++;
            }
        }
        return moves;
    }
};

#include <bits/stdc++.h>
using namespace std;

vector<int> minDeletionsToMakeAlternatingSubstring(string s, vector<vector<int>>& queries) {
    int n = (int)s.size();
    vector<int> bit(n + 2, 0);
    auto add = [&](int i, int delta) { for (; i <= n; i += i & -i) bit[i] += delta; };
    auto sum = [&](int i) { int r = 0; for (; i > 0; i -= i & -i) r += bit[i]; return r; };
    auto rangeSum = [&](int l, int r) { return l > r ? 0 : sum(r) - sum(l - 1); };

    for (int i = 1; i < n; i++) {
        if (s[i] == s[i - 1]) add(i + 1, 1);
    }

    vector<int> answers;
    for (auto& q : queries) {
        if (q[0] == 1) {
            int j = q[1];
            char newChar = (s[j] == 'A') ? 'B' : 'A';
            if (j > 0) {
                int oldEq = (s[j] == s[j-1]) ? 1 : 0;
                int newEq = (newChar == s[j-1]) ? 1 : 0;
                if (oldEq != newEq) add(j + 1, newEq - oldEq);
            }
            if (j + 1 < n) {
                int oldEq = (s[j+1] == s[j]) ? 1 : 0;
                int newEq = (s[j+1] == newChar) ? 1 : 0;
                if (oldEq != newEq) add(j + 2, newEq - oldEq);
            }
            s[j] = newChar;
        } else {
            int l = q[1], r = q[2];
            if (l >= r) answers.push_back(0);
            else answers.push_back(rangeSum(l + 2, r + 1));
        }
    }
    return answers;
}

