long long minimumDeletionCost(const std::string& s, const std::vector<int>& cost) {
    long long totalCost = 0;
    std::unordered_map<char, long long> charCost;
    for (size_t i = 0; i < s.size(); ++i) {
        char ch = s[i];
        long long c = cost[i];
        totalCost += c;
        charCost[ch] = charCost[ch] + c;
    }
    long long maxKeep = 0;
    for (const auto& kv : charCost) {
        if (kv.second > maxKeep) maxKeep = kv.second;
    }
    return totalCost - maxKeep;
}

#include <bits/stdc++.h>

int minimumSwaps(const std::vector<int>& arr, const std::vector<int>& forbidden) {
    std::size_t n = arr.size();
    std::unordered_map<int, std::size_t> freqArr;
    std::unordered_map<int, std::size_t> cntForbidden;
    for (std::size_t i = 0; i < n; ++i) {
        ++freqArr[arr[i]];
        ++cntForbidden[forbidden[i]];
    }
    for (const auto& p : freqArr) {
        int val = p.first;
        std::size_t have = p.second;
        std::size_t forbiddenCount = cntForbidden.count(val) ? cntForbidden[val] : 0;
        if (have > n - forbiddenCount) {
            return -1;
        }
    }
    std::size_t bad = 0;
    for (std::size_t i = 0; i < n; ++i) {
        if (arr[i] == forbidden[i]) ++bad;
    }
    if (bad == 0) return 0;
    if (bad == 1) return 1;
    return static_cast<int>((bad + 1) / 2);
}

