class Solution {
public:
    int lastRemaining(int n) {
        vector<int> arr(n);
        iota(arr.begin(), arr.end(), 1);
        bool left = true;
        while (arr.size() > 1) {
            vector<int> next_;
            if (left) {
                // keep 1-indexed odd positions (0-indexed even)
                for (int i = 0; i < (int) arr.size(); i += 2) next_.push_back(arr[i]);
            } else {
                // "delete every second from the right" = reverse, do the same left-style keep, reverse back
                vector<int> rev(arr.rbegin(), arr.rend());
                vector<int> kept;
                for (int i = 0; i < (int) rev.size(); i += 2) kept.push_back(rev[i]);
                next_.assign(kept.rbegin(), kept.rend());
            }
            arr = next_;
            left = !left;
        }
        return arr[0];
    }
};

