int maxSumDivisibleByThree(const std::vector<int>& nums) {
    std::vector<int> rem0, rem1, rem2;
    for (size_t i = 0; i < nums.size(); ++i) {
        int v = nums[i];
        int mod = v % 3;
        if (mod == 0) rem0.push_back(v);
        else if (mod == 1) rem1.push_back(v);
        else rem2.push_back(v);
    }
    std::sort(rem0.begin(), rem0.end(), std::greater<int>());
    std::sort(rem1.begin(), rem1.end(), std::greater<int>());
    std::sort(rem2.begin(), rem2.end(), std::greater<int>());
    std::vector<int> candidates;
    if (rem0.size() >= 3) candidates.push_back(rem0[0] + rem0[1] + rem0[2]);
    if (rem1.size() >= 3) candidates.push_back(rem1[0] + rem1[1] + rem1[2]);
    if (rem2.size() >= 3) candidates.push_back(rem2[0] + rem2[1] + rem2[2]);
    if (!rem0.empty() && !rem1.empty() && !rem2.empty()) {
        candidates.push_back(rem0[0] + rem1[0] + rem2[0]);
    }
    return candidates.empty() ? 0 : *std::max_element(candidates.begin(), candidates.end());
}

