long long totalInteractionCost(int n, std::vector<std::vector<int>>& edges, std::vector<int>& group) {
    std::vector<std::vector<int>> adj(n);
    for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
    const int maxG = 21;
    std::vector<long long> totalFreq(maxG, 0);
    for (int g : group) totalFreq[g]++;
    long long total = 0;
    std::vector<int> parent(n, -1), order; order.reserve(n);
    std::vector<bool> visited(n, false);
    std::vector<int> stack = {0}; visited[0] = true;
    while (!stack.empty()) {
        int u = stack.back(); stack.pop_back(); order.push_back(u);
        for (int v : adj[u]) if (!visited[v]) { visited[v] = true; parent[v] = u; stack.push_back(v); }
    }
    std::vector<std::vector<long long>> subFreq(n, std::vector<long long>(maxG, 0));
    for (int i = order.size() - 1; i >= 0; i--) {
        int u = order[i];
        subFreq[u][group[u]]++;
        for (int v : adj[u]) {
            if (v == parent[u]) continue;
            for (int g = 0; g < maxG; g++) {
                long long cnt = subFreq[v][g];
                if (cnt > 0) total += cnt * (totalFreq[g] - cnt);
                subFreq[u][g] += cnt;
            }
        }
    }
    return total;
}

class Solution {
public:
    long long dfsCount(int pos, int diff, bool tight, int length, vector<int>& digits,
                        map<tuple<int,int,bool>, long long>& memo) {
        if (pos == length) return diff == 0 ? 1 : 0;
        auto key = make_tuple(pos, diff, tight);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int lo = pos > 0 ? 0 : 1;
        int hi = tight ? digits[pos] : 9;
        long long total = 0;
        for (int d = lo; d <= hi; d++) {
            int sign = (pos % 2 == 0) ? 1 : -1;
            total += dfsCount(pos + 1, diff + sign * d, tight && d == hi, length, digits, memo);
        }
        memo[key] = total;
        return total;
    }

    long long countLeLength(long long x, int length) {
        long long lowBound = 1;
        for (int i = 0; i < length - 1; i++) lowBound *= 10;
        if (x < lowBound) return 0;
        long long highBound = lowBound * 10 - 1;
        x = min(x, highBound);
        string s = to_string(x);
        if ((int) s.size() != length) return 0;
        vector<int> digits;
        for (char c : s) digits.push_back(c - '0');
        map<tuple<int,int,bool>, long long> memo;
        return dfsCount(0, 0, true, length, digits, memo);
    }

    long long countUpto(long long n) {
        if (n < 10) return 0;
        string s = to_string(n);
        long long total = 0;
        for (int length = 2; length <= (int) s.size(); length++) {
            total += countLeLength(n, length);
        }
        return total;
    }

    long long numberOfBalancedIntegers(long long low, long long high) {
        return countUpto(high) - countUpto(low - 1);
    }
};

class Solution {
public:
    long long maximumScore(vector<int>& nums) {
        int n = nums.size();
        long long best = LLONG_MIN;
        for (int i = 0; i < n - 1; i++) {
            long long prefix = 0;
            for (int k = 0; k <= i; k++) prefix += nums[k];
            long long sufMin = LLONG_MAX;
            for (int k = i + 1; k < n; k++) sufMin = min(sufMin, (long long)nums[k]);
            best = max(best, prefix - sufMin);
        }
        return best;
    }
};

