int minSubarrayLength(const std::vector<int>& arr, int K) {
    std::size_t left = 0;
    long long distinctSum = 0;
    std::unordered_map<int, int> freq;
    int best = INT_MAX;

    for (std::size_t right = 0; right < arr.size(); ++right) {
        int val = arr[right];
        int cnt = 0;
        auto it = freq.find(val);
        if (it != freq.end()) cnt = it->second;
        freq[val] = cnt + 1;
        if (cnt == 0) distinctSum += val;

        while (distinctSum >= K) {
            best = std::min(best, static_cast<int>(right - left + 1));
            int leftVal = arr[left];
            int leftCnt = freq[leftVal];
            if (leftCnt == 1) distinctSum -= leftVal;
            if (leftCnt == 1) {
                freq.erase(leftVal);
            } else {
                freq[leftVal] = leftCnt - 1;
            }
            ++left;
        }
    }

    return best == INT_MAX ? -1 : best;
}

