long long countCaesarCipherPairs(const std::vector<std::string>& words) {
    std::unordered_map<std::string, long long> freq;
    long long totalPairs = 0;

    for (const std::string& w : words) {
        int base = static_cast<unsigned char>(w[0]);
        std::string pattern;
        pattern.reserve(w.size() * 3);
        for (size_t i = 0; i < w.size(); ++i) {
            int diff = (static_cast<unsigned char>(w[i]) - base + 26) % 26;
            pattern += std::to_string(diff);
            pattern.push_back(',');
        }
        std::string key = std::to_string(w.size()) + ':' + pattern;

        long long prev = 0;
        auto it = freq.find(key);
        if (it != freq.end()) {
            prev = it->second;
        }
        totalPairs += prev;
        freq[key] = prev + 1;
    }

    return totalPairs;
}

