long long maximumAND(std::vector<long long>& nums, long long k, int m) {
    long long mxVal = *std::max_element(nums.begin(), nums.end()) + k;
    int mx = 0; long long tmp = mxVal;
    while (tmp > 0) { mx++; tmp >>= 1; }
    long long ans = 0;
    std::vector<long long> cost(nums.size());
    for (int bit = mx - 1; bit >= 0; bit--) {
        long long target = ans | (1LL << bit);
        for (size_t i = 0; i < nums.size(); i++) {
            long long x = nums[i];
            long long val = target & (~x);
            int j = 0; long long v2 = val;
            while (v2 > 0) { j++; v2 >>= 1; }
            long long mask = (1LL << j) - 1;
            cost[i] = (target & mask) - (x & mask);
        }
        std::sort(cost.begin(), cost.end());
        long long sum = 0;
        for (int i = 0; i < m; i++) sum += cost[i];
        if (sum <= k) ans = target;
    }
    return ans;
}

