vector<int> minimumEdgeToggles(int n, vector<vector<int>>& edges, string start, string target) {
    vector<vector<pair<int,int>>> adj(n);
    for (int idx = 0; idx < (int)edges.size(); idx++) {
        int u = edges[idx][0], v = edges[idx][1];
        adj[u].push_back({v, idx});
        adj[v].push_back({u, idx});
    }

    vector<int> d(n);
    for (int i = 0; i < n; i++) d[i] = (start[i] == target[i]) ? 0 : 1;

    vector<int> parent(n, -1), edgeToParent(n, -1), order;
    vector<bool> visited(n, false);
    stack<int> st;
    st.push(0);
    visited[0] = true;
    while (!st.empty()) {
        int u = st.top(); st.pop();
        order.push_back(u);
        for (auto& [v, idx] : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                parent[v] = u;
                edgeToParent[v] = idx;
                st.push(v);
            }
        }
    }

    vector<int> need(n, 0);
    for (int i = (int)order.size() - 1; i >= 0; i--) {
        int u = order[i];
        int parity = 0;
        for (auto& [v, idx] : adj[u]) {
            if (v != parent[u]) parity ^= need[v];
        }
        need[u] = d[u] ^ parity;
    }

    if (need[0] != 0) return {-1};

    vector<int> result;
    for (int u = 1; u < n; u++) {
        if (need[u] == 1) result.push_back(edgeToParent[u]);
    }
    sort(result.begin(), result.end());
    return result;
}

