long long maxCapacity(std::vector<int>& costs, std::vector<int>& capacity, int budget) {
    int n = costs.size();
    std::vector<std::pair<int,int>> arr;
    for (int i = 0; i < n; i++) if (costs[i] < budget) arr.push_back({costs[i], capacity[i]});
    if (arr.empty()) return 0;
    std::sort(arr.begin(), arr.end());
    int m = arr.size();
    long long ans = 0;
    for (auto& p : arr) ans = std::max(ans, (long long)p.second);
    int LOG = std::max(1, (int)std::ceil(std::log2(m + 1)));
    std::vector<std::vector<int>> sparse(LOG, std::vector<int>(m, 0));
    for (int i = 0; i < m; i++) sparse[0][i] = arr[i].second;
    for (int j = 1; (1 << j) <= m; j++) {
        int half = 1 << (j - 1);
        for (int i = 0; i + (1 << j) <= m; i++) sparse[j][i] = std::max(sparse[j-1][i], sparse[j-1][i+half]);
    }
    auto query = [&](int l, int r) -> long long {
        if (l > r) return LLONG_MIN;
        int length = r - l + 1;
        int k = (int)std::log2(length);
        return std::max(sparse[k][l], sparse[k][r - (1 << k) + 1]);
    };
    int hi = m - 1;
    for (int i = 0; i < m; i++) {
        if (hi < i) hi = i;
        while (hi > i && arr[i].first + arr[hi].first >= budget) hi--;
        if (hi > i) {
            long long bp = query(i + 1, hi);
            if (bp != LLONG_MIN) ans = std::max(ans, (long long)arr[i].second + bp);
        }
    }
    return ans;
}

