int countPythagoreanNodes(int n, std::vector<std::vector<int>>& edges, int x, int y, int z) {
    std::vector<std::vector<int>> adj(n);
    for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
    auto dx = bfsDist(n, adj, x), dy = bfsDist(n, adj, y), dz = bfsDist(n, adj, z);
    int count = 0;
    for (int u = 0; u < n; u++) {
