static unsigned long long binom73(int n, int k) {
    if (k < 0 || k > n || n < 0) return 0;
    unsigned long long res = 1;
    if (k > n - k) k = n - k;
    for (int i = 0; i < k; i++) res = res * (n - i) / (i + 1);
    return res;
}
long long nthSmallestWithKOnes(long long n, int k) {
    if (k == 0) return (n == 1) ? 0 : -1;
    int pos = k - 1;
    while ((long long)binom73(pos + 1, k) < n) ++pos;
    long long remaining = n - 1;
    int bitsLeft = k;
    long long result = 0;
    for (int p = pos; p >= 0; --p) {
        if (bitsLeft == 0) break;
        long long count = (p >= bitsLeft) ? (long long)binom73(p, bitsLeft) : 0;
        if (remaining >= count) { result |= (1LL << p); remaining -= count; --bitsLeft; }
    }
    return result;
}

