std::string reverseLettersThenSpecials(const std::string& s) {
    std::vector<char> chars(s.begin(), s.end());

    int left = 0;
    int right = static_cast<int>(chars.size()) - 1;
    while (left < right) {
        while (left < right && !isLetter(chars[left])) ++left;
        while (left < right && !isLetter(chars[right])) --right;
        if (left < right) {
            char tmp = chars[left];
            chars[left] = chars[right];
            chars[right] = tmp;
            ++left;
            --right;
        }
    }

    left = 0;
    right = static_cast<int>(chars.size()) - 1;
    while (left < right) {
        while (left < right && isLetter(chars[left])) ++left;
        while (left < right && isLetter(chars[right])) --right;
        if (left < right) {
            char tmp = chars[left];
            chars[left] = chars[right];
            chars[right] = tmp;
            ++left;
            --right;
        }
    }

    return std::string(chars.begin(), chars.end());
}

