int longestAlternating(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return 0;
    auto compute = [&](int skipIdx) {
        int maxLen = 0;
        int curLen = 0;
        bool havePrev = false;
        int prevVal = 0;
        bool havePrevSign = false;
        int prevSign = 0; // 1 for positive, -1 for negative
        for (int i = 0; i < n; ++i) {
            if (i == skipIdx) continue;
            int val = nums[i];
            if (!havePrev) {
                curLen = 1;
                havePrev = true;
                havePrevSign = false;
            } else {
                int diff = val - prevVal;
                if (diff == 0) {
                    curLen = 1;
                    havePrevSign = false;
                } else {
                    int sign = diff > 0 ? 1 : -1;
                    if (!havePrevSign) {
                        curLen = 2;
                        havePrevSign = true;
                        prevSign = sign;
                    } else if (sign != prevSign) {
                        ++curLen;
                        prevSign = sign;
                    } else {
                        curLen = 2;
                        prevSign = sign;
                    }
                }
            }
            prevVal = val;
            if (curLen > maxLen) maxLen = curLen;
        }
        return maxLen;
    };

    int answer = compute(-1); // no deletion
    for (int del = 0; del < n; ++del) {
        int cand = compute(del);
        if (cand > answer) answer = cand;
    }
    return answer;
}

