    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

std::pair<int,int> dfsRob(TreeNode* node) {
    if (!node) return {0, 0};
    auto lp = dfsRob(node->left);
    auto rp = dfsRob(node->right);
    int rob = node->val + lp.second + rp.second;
    int skip = std::max(lp.first, lp.second) + std::max(rp.first, rp.second);
    return {rob, skip};
}

int houseRobberV(TreeNode* root) {
    auto p = dfsRob(root);
    return std::max(p.first, p.second);
}

