std::vector<int> mergeAdjacent(const std::vector<int>& arr) {
    std::vector<int> stack;
    stack.reserve(arr.size());
    for (size_t i = 0; i < arr.size(); ++i) {
        stack.push_back(arr[i]);
        while (stack.size() >= 2) {
            int top = stack.back();
            int next = stack[stack.size() - 2];
            if (top != next) break;
            stack.pop_back();
            stack.pop_back();
            stack.push_back(top + next);
        }
    }
    return stack;
}

