long long countSubarrays(const std::vector<int>& arr, int K) {
    std::size_t n = arr.size();
    std::deque<std::size_t> maxDeque;
    std::deque<std::size_t> minDeque;
    std::size_t left = 0;
    long long total = 0;

    for (std::size_t right = 0; right < n; ++right) {
        while (!maxDeque.empty() && arr[maxDeque.back()] <= arr[right]) {
            maxDeque.pop_back();
        }
        maxDeque.push_back(right);

        while (!minDeque.empty() && arr[minDeque.back()] >= arr[right]) {
            minDeque.pop_back();
        }
        minDeque.push_back(right);

        while (!maxDeque.empty() && !minDeque.empty() &&
               static_cast<long long>(arr[maxDeque.front()] - arr[minDeque.front()]) *
               static_cast<long long>(right - left + 1) > static_cast<long long>(K)) {
            if (maxDeque.front() == left) {
                maxDeque.pop_front();
            }
            if (minDeque.front() == left) {
                minDeque.pop_front();
            }
            ++left;
        }

        total += static_cast<long long>(right - left + 1);
    }

    return total;
}

