typedef long long ll;
const ll MOD = 1000000007LL;

ll modpow(ll base, ll exp, ll mod) {
    base %= mod; if (base < 0) base += mod;
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = (__int128)result * base % mod;
        base = (__int128)base * base % mod;
        exp >>= 1;
    }
    return result;
}

// Each of the K digit-positions is filled independently & uniformly from [L,R].
// Position i contributes (avg digit sum S) * (count of combos for other K-1 positions)
// weighted by its place value 10^(K-1-i). Summed over positions gives:
// answer = S * m^(K-1) * (10^K - 1)/9   (mod 1e9+7), m = R-L+1
long long sumKDigit(long long L, long long R, long long K) {
    ll d = R - L + 1;
    ll inv2 = modpow(2, MOD - 2, MOD);
    ll S = ((L + R) % MOD) * (d % MOD) % MOD * inv2 % MOD;
    ll m = d % MOD;
    ll inv9 = modpow(9, MOD - 2, MOD);
    ll geo = (modpow(10, K, MOD) - 1 + MOD) % MOD * inv9 % MOD;
    ll mpow = modpow(m, K - 1, MOD);
    return (__int128)S * mpow % MOD * geo % MOD;
}

class Solution {
public:
    int n;
    long long k;
    vector<int>* numsPtr;
    map<tuple<int,long long,long long>, long long> f;
    long long gcd_(long long a, long long b) { while (b) { long long t = a % b; a = b; b = t; } return a; }
    long long dfs(int i, long long p, long long q) {
        if (i == n) return (p == k && q == 1LL) ? 1 : 0;
        auto key = make_tuple(i, p, q);
        auto it = f.find(key);
        if (it != f.end()) return it->second;
        long long res = dfs(i + 1, p, q);
        long long x = (*numsPtr)[i];
        long long g1 = gcd_(p * x, q);
        res += dfs(i + 1, (p * x) / g1, q / g1);
        long long g2 = gcd_(p, q * x);
        res += dfs(i + 1, p / g2, (q * x) / g2);
        f[key] = res;
        return res;
    }
    long long countSequences(vector<int>& nums, long long k) {
        numsPtr = &nums;
        n = nums.size();
        this->k = k;
        f.clear();
        return dfs(0, 1LL, 1LL);
    }
};

