long long subarraysWithKDistinct(const std::vector<int>& nums, int K) {
    auto atMost = [&](int k) -> long long {
        int left = 0;
        long long result = 0;
        std::unordered_map<int, int> freq;
        for (int right = 0; right < static_cast<int>(nums.size()); ++right) {
            int val = nums[right];
            ++freq[val];
            while (static_cast<int>(freq.size()) > k) {
                int leftVal = nums[left];
                int cnt = --freq[leftVal];
                if (cnt == 0) {
                    freq.erase(leftVal);
                }
                ++left;
            }
            result += right - left + 1;
        }
        return result;
    };
    return atMost(K) - atMost(K - 1);
}

