std::vector<int> smallestPairWithDifferentFrequencies(const std::vector<int>& arr) {
    std::unordered_map<int, int> freq;
    for (int v : arr) {
        ++freq[v];
    }

    std::vector<int> vals;
    vals.reserve(freq.size());
    for (const auto& kv : freq) {
        vals.push_back(kv.first);
    }
