int longestArithmeticAlgo(vector<int>& nums) {
    int n=nums.size();
    if (n<=2) return n;
    int best=2;
    set<int> diffSet;
    for (int a=0;a<n;a++) for (int b=0;b<n;b++) if (a!=b) diffSet.insert(nums[b]-nums[a]);
    diffSet.insert(0);
    for (int i=0;i<n;i++) {
        set<int> candidates;
        candidates.insert(nums[i]);
        for (int d : diffSet) {
            if (i>0) candidates.insert(nums[i-1]+d);
            if (i<n-1) candidates.insert(nums[i+1]-d);
        }
        for (int repl : candidates) {
            vector<int> arr=nums;
            arr[i]=repl;
            int cur=1, localBest=1;
            for (int j=1;j<n;j++) {
                if (j>=2 && arr[j]-arr[j-1]==arr[j-1]-arr[j-2]) cur++; else cur=2;
                localBest=max(localBest,cur);
            }
            best=max(best,localBest);
        }
    }
    return best;
}

