int maxPointsActivated(const vector<vector<int>>& points) {
    unordered_map<long long,long long> parent;
    unordered_map<long long,int> sz;
    function<long long(long long)> find = [&](long long x) -> long long {
        if (parent.find(x) == parent.end()) { parent[x] = x; sz[x] = 1; }
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    };
    auto unite = [&](long long a, long long b) {
        long long ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
    };
    const long long M = 3000000000LL;
    for (auto& p : points) unite(p[0], (long long)p[1] + M);
    unordered_map<long long,int> cnt;
    for (auto& p : points) { long long r = find(p[0]); cnt[r]++; }
    int mx1 = 0, mx2 = 0;
    for (auto& kv : cnt) {
        int v = kv.second;
        if (v > mx1) { mx2 = mx1; mx1 = v; }
        else if (v > mx2) mx2 = v;
    }
    return mx1 + mx2 + 1;
}

