long long countCommasInRange(long long L, long long R) {
    auto totalUpTo = [](long long N) -> long long {
        if (N <= 0) return 0;
        long long total = 0;
        long long power = 1;
        long long digit = 1;
        while (power <= N) {
            long long nextPower = power * 10;
            long long end = std::min(N, nextPower - 1);
            long long countNumbers = end - power + 1;
            long long commasPerNumber = (digit - 1) / 3;
            total += countNumbers * commasPerNumber;
            power = nextPower;
            ++digit;
        }
        return total;
    };
    return totalUpTo(R) - totalUpTo(L - 1);
}

