        while (!stk.empty() && (nums[stk.back()]|nums[i])==nums[i]) stk.pop_back();
        l[i] = stk.empty()? -1: stk.back();
        stk.push_back(i);
    }
    stk.clear();
    for (int i=n-1;i>=0;i--) {
        while (!stk.empty() && ((nums[stk.back()]|nums[i])==nums[i]) && nums[stk.back()]!=nums[i]) stk.pop_back();
        r[i] = stk.empty()? n: stk.back();
        stk.push_back(i);
    }
    long long ans=0;
    for (int i=0;i<n;i++) ans += (long long)(i-l[i]) * (r[i]-i);
    return ans;
}

