long long countCommasInRange(long long L, long long R) {
    if (L > R) return 0;
    unsigned long long pow10[20];
    pow10[0] = 1;
    for (int i = 1; i < 20; ++i) pow10[i] = pow10[i - 1] * 10ULL;

    unsigned long long total = 0;
    for (int d = 1; d < 20; ++d) {
        unsigned long long low = (d == 1) ? 0ULL : pow10[d - 1];
        unsigned long long high = pow10[d] - 1ULL;
        if (low > (unsigned long long)R) break;

        unsigned long long curL = std::max((unsigned long long)L, low);
        unsigned long long curR = std::min((unsigned long long)R, high);
        if (curL > curR) continue;

        unsigned long long cnt = curR - curL + 1ULL;
        unsigned long long commas = (d - 1) / 3;
        total += cnt * commas;
    }
    return static_cast<long long>(total);
}

