long long countVisiblePeople(int n, int pos, int k) {
    int l = pos, r = n-pos-1;
    int maxN = max(l,r)+1;
    vector<long long> fact(maxN+1,1), invFact(maxN+1,1);
    for (int i=1;i<=maxN;i++) fact[i]=fact[i-1]*i%MOD;
    invFact[maxN]=modpow(fact[maxN],MOD-2,MOD);
    for (int i=maxN;i>0;i--) invFact[i-1]=invFact[i]*i%MOD;
    auto comb=[&](int nn,int kk)->long long{ if(kk<0||kk>nn) return 0; return fact[nn]*invFact[kk]%MOD*invFact[nn-kk]%MOD; };
    long long ans=0;
    for (int a=0;a<=min(k,l);a++) {
        int b=k-a;
        if (b<=r) ans=(ans+2*comb(l,a)%MOD*comb(r,b))%MOD;
    }
    return ans;
}

