int minRemovals(const std::vector<int>& arr, int target) {
    std::size_t n = arr.size();
    std::unordered_map<int, int> dp;
    dp[0] = 0;
    for (int v : arr) {
        std::unordered_map<int, int> next(dp);
        for (const auto& kv : dp) {
            int xorVal = kv.first;
            int size = kv.second;
            int newXor = xorVal ^ v;
            int newSize = size + 1;
            auto it = next.find(newXor);
            if (it == next.end() || newSize > it->second) {
                next[newXor] = newSize;
            }
        }
        dp = std::move(next);
    }
    auto it = dp.find(target);
    if (it == dp.end()) return -1;
    return static_cast<int>(n) - it->second;
}

