int minAbsoluteDifference(std::vector<int>& nums) {
    int n = nums.size();
    int lastOne = -1, lastTwo = -1, ans = INT_MAX;
    for (int i = 0; i < n; i++) {
        if (nums[i] == 1) { if (lastTwo != -1) ans = std::min(ans, i - lastTwo); lastOne = i; }
        else if (nums[i] == 2) { if (lastOne != -1) ans = std::min(ans, i - lastOne); lastTwo = i; }
    }
    return ans == INT_MAX ? -1 : ans;
}

