int mirrorFrequencyDistance(const std::string& s) {
    std::vector<int> freqLetter(26, 0);
    std::vector<int> freqDigit(10, 0);
    for (char ch : s) {
        if (ch >= 'a' && ch <= 'z') {
            ++freqLetter[ch - 'a'];
        } else if (ch >= 'A' && ch <= 'Z') {
            ++freqLetter[ch - 'A'];
        } else if (ch >= '0' && ch <= '9') {
            ++freqDigit[ch - '0'];
        }
    }
    int distance = 0;
    for (int i = 0; i < 13; ++i) {
        int mirror = 25 - i;
        distance += std::abs(freqLetter[i] - freqLetter[mirror]);
    }
    for (int i = 0; i < 5; ++i) {
        int mirror = 9 - i;
        distance += std::abs(freqDigit[i] - freqDigit[mirror]);
    }
    return distance;
}

