std::vector<long long> integersWithMultipleSumOfTwoCubes(long long n) {
    long long limit = static_cast<long long>(std::floor(std::cbrt(static_cast<double>(n))));
    std::unordered_map<long long, int> countMap;
    for (long long a = 1; a <= limit; ++a) {
        long long aCubed = a * a * a;
        for (long long b = a; b <= limit; ++b) {
            long long sum = aCubed + b * b * b;
            if (sum > n) break;
            ++countMap[sum];
        }
    }
    std::vector<long long> result;
    result.reserve(countMap.size());
    for (const auto& kv : countMap) {
        if (kv.second > 1) result.push_back(kv.first);
    }
    std::sort(result.begin(), result.end());
    return result;
}

