    auto better = [](pair<long long,long long> a, pair<long long,long long> b) {
        if (a.first != b.first) return a.first > b.first ? a : b;
        return a.second <= b.second ? a : b;
    };
    pair<long long,long long> notTake = {0,0}, take = {-1,0};
    for (int i=1;i<n-1;i++) {
