bool check(vector<long long>& nums, long long p) {
    int n = nums.size();
    vector<long long> filtered;
    for (int i=0;i<n;i++) if (nums[i]%p==0) filtered.push_back(nums[i]/p);
    if (filtered.empty()) return false;
    if ((int)filtered.size() < n) {
        long long g=0;
        for (long long v: filtered) g=gcdll(g,v);
        return g==1;
    } else {
        int m = filtered.size();
        vector<long long> pre(m+1,0), suf(m+1,0);
        for (int i=0;i<m;i++) pre[i+1]=gcdll(pre[i], filtered[i]);
        for (int i=m-1;i>=0;i--) suf[i]=gcdll(suf[i+1], filtered[i]);
        for (int i=0;i<m;i++) if (gcdll(pre[i], suf[i+1])==1) return true;
        return false;
    }
}
