std::vector<double> angles(const std::vector<int>& sides) {
    if (sides.size() != 3) return {};
    double a = static_cast<double>(sides[0]);
    double b = static_cast<double>(sides[1]);
    double c = static_cast<double>(sides[2]);
    if (a <= 0 || b <= 0 || c <= 0) return {};
    if (a + b <= c || a + c <= b || b + c <= a) return {};
    const double PI = std::acos(-1.0);
    auto toDeg = [&](double rad) { return rad * 180.0 / PI; };
    auto clamp = [&](double v) { return std::max(-1.0, std::min(1.0, v)); };
    double angleA = toDeg(std::acos(clamp((b * b + c * c - a * a) / (2.0 * b * c))));
    double angleB = toDeg(std::acos(clamp((a * a + c * c - b * b) / (2.0 * a * c))));
    double angleC = toDeg(std::acos(clamp((a * a + b * b - c * c) / (2.0 * a * b))));
    auto round4 = [&](double v) { return std::round(v * 10000.0) / 10000.0; };
    std::vector<double> result{round4(angleA), round4(angleB), round4(angleC)};
    std::sort(result.begin(), result.end());
    return result;
}

