int countEvenConnectedSubgraphs(const std::vector<int>& values, const std::vector<std::pair<int,int>>& edges) {
    int n = static_cast<int>(values.size());
    std::vector<std::vector<int>> adj(n);
    for (const auto& e : edges) {
        int u = e.first;
        int v = e.second;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<std::uint32_t> sum(1 << n);
    for (int mask = 1; mask < (1 << n); ++mask) {
        int lsb = mask & -mask;
        int idx = __builtin_ctz(lsb);
        sum[mask] = sum[mask ^ lsb] + static_cast<std::uint32_t>(values[idx]);
    }
    long long answer = 0;
    std::vector<std::uint8_t> visited(n);
    for (int mask = 1; mask < (1 << n); ++mask) {
        if ((sum[mask] & 1u) == 1u) continue;
        int start = 0;
        while (((mask >> start) & 1) == 0) ++start;
        std::vector<int> queue;
        queue.push_back(start);
        std::fill(visited.begin(), visited.end(), 0);
        visited[start] = 1;
        int visitedCount = 0;
        while (!queue.empty()) {
            int v = queue.back();
            queue.pop_back();
            ++visitedCount;
            for (int nb : adj[v]) {
                if (visited[nb]) continue;
                if ((mask >> nb) & 1) {
                    visited[nb] = 1;
                    queue.push_back(nb);
                }
            }
        }
        if (visitedCount == __builtin_popcount(mask)) ++answer;
    }
    return static_cast<int>(answer);
}

