long long dfs(int pos, int last, bool lim) {
    if (pos == 16) return 1;
    if (!lim && memoSet[pos][last]) return memo[pos][last];
    long long res = 0;
    int start = key16[pos] ? last : 0;
    int end = lim ? (s16[pos]-'0') : 9;
    for (int i = start; i <= end; i++) {
        res += dfs(pos+1, key16[pos] ? i : last, lim && (i==end));
    }
    if (!lim) { memo[pos][last]=res; memoSet[pos][last]=true; }
    return res;
}
long long calc(long long x) {
    if (x < 0) return 0;
    s16 = string(16 - to_string(x).size(), '0') + to_string(x);
    memset(memoSet, 0, sizeof(memoSet));
    return dfs(0, 0, true);
}
long long countGoodIntegersOnPath(long long l, long long r, string directions) {
    memset(key16, 0, sizeof(key16));
    int row=0, col=0;
    key16[0]=true;
    for (char c: directions) {
        if (c=='D') row++; else col++;
        key16[row*4+col]=true;
    }
    return calc(r) - calc(l-1);
}

