std::vector<int> kthSmallestEven(const std::vector<int>& arr, const std::vector<std::vector<int>>& queries) {
    std::vector<int> results;
    results.reserve(queries.size());
    for (const auto& q : queries) {
        int l = q[0];
        int r = q[1];
        int k = q[2];
        std::vector<int> evens;
        evens.reserve(r - l + 1);
        for (int i = l; i <= r; ++i) {
            if (arr[i] % 2 == 0) {
                evens.push_back(arr[i]);
            }
        }
        std::sort(evens.begin(), evens.end());
        evens.erase(std::unique(evens.begin(), evens.end()), evens.end());
        long long ans = 2LL * k;
        for (int e : evens) {
            if (e <= ans) {
                ans += 2;
            } else {
                break;
            }
        }
        results.push_back(static_cast<int>(ans));
    }
    return results;
}

