vector<int> findValidElements(vector<int>& nums) {
    int n = nums.size();
    vector<int> sufMax(n);
    sufMax[n-1] = nums[n-1];
    for (int i=n-2;i>=0;i--) sufMax[i]=max(sufMax[i+1], nums[i]);
    vector<int> ans;
    int preMax = INT_MIN;
    for (int i=0;i<n;i++) {
        int x = nums[i];
        if (x > preMax || i == n-1 || x > sufMax[i+1]) ans.push_back(x);
        preMax = max(preMax, x);
    }
    return ans;
}

