int compareSums(const std::vector<int>& arr) {
    if (arr.empty()) {
        return 0;
    }
    std::size_t peakIdx = 0;
    for (std::size_t i = 1; i < arr.size(); ++i) {
        if (arr[i] > arr[peakIdx]) {
            peakIdx = i;
        }
    }
    long long leftSum = 0;
    for (std::size_t i = 0; i <= peakIdx; ++i) {
        leftSum += arr[i];
    }
    long long rightSum = 0;
    for (std::size_t i = peakIdx; i < arr.size(); ++i) {
        rightSum += arr[i];
    }
    if (leftSum < rightSum) {
        return 1;
    }
    if (leftSum == rightSum) {
        return -1;
    }
    return 0;
}

