class Solution {
public:
    static const int MAXV = 100001;
    long long bitDown[MAXV+2], bitUp[MAXV+2];
    void update(long long* bit, int i, long long val) {
        for (; i <= MAXV; i += i & (-i)) bit[i] = max(bit[i], val);
    }
    long long query(long long* bit, int i) {
        long long res = 0;
        for (; i > 0; i -= i & (-i)) res = max(res, bit[i]);
        return res;
    }
    long long maxAlternatingSum(vector<int>& nums, int k) {
        int n = nums.size();
        memset(bitDown, 0, sizeof(bitDown));
        memset(bitUp, 0, sizeof(bitUp));
        vector<long long> up(n), down(n);
        long long ans = LLONG_MIN;
        int inserted = -1;
        for (int i = 0; i < n; i++) {
            int limit = i - k;
            while (inserted < limit) {
                inserted++;
                update(bitDown, nums[inserted], down[inserted]);
                update(bitUp, MAXV + 1 - nums[inserted], up[inserted]);
            }
            long long bestDown = query(bitDown, nums[i]-1);
            up[i] = nums[i] + max(0LL, bestDown);
            long long bestUp = query(bitUp, MAXV + 1 - (nums[i]+1));
            down[i] = nums[i] + max(0LL, bestUp);
            ans = max({ans, up[i], down[i]});
        }
        return ans;
    }
};

