using namespace std;
string sortVowels(string s) {
    unordered_set<char> vowels = {'a','e','i','o','u'};
    unordered_map<char,int> freq, firstOcc;
    vector<int> positions;
    for (int i = 0; i < (int)s.size(); i++) {
        char c = s[i];
        if (vowels.count(c)) {
            positions.push_back(i);
            freq[c]++;
            if (!firstOcc.count(c)) firstOcc[c] = i;
        }
    }
    vector<char> letters;
    for (auto& kv : freq) letters.push_back(kv.first);
    sort(letters.begin(), letters.end(), [&](char a, char b) {
        if (freq[a] != freq[b]) return freq[a] > freq[b];
        return firstOcc[a] < firstOcc[b];
    });
    vector<char> sortedVowels;
    for (char c : letters) for (int k = 0; k < freq[c]; k++) sortedVowels.push_back(c);
    for (size_t idx = 0; idx < positions.size(); idx++) s[positions[idx]] = sortedVowels[idx];
    return s;
}

