long long sumPrimesBetweenReverse(long long num) {
    long long rev = 0, tmp = num;
    while (tmp > 0) {
        rev = rev * 10 + (tmp % 10);
        tmp = tmp / 10;
    }
    long long low = std::min(num, rev);
    long long high = std::max(num, rev);
    long long total = 0;
    for (long long i = low; i <= high; ++i) {
        if (i > 1) {
            bool isPrime = true;
            long long limit = static_cast<long long>(std::floor(std::sqrt(i)));
            for (long long d = 2; d <= limit; ++d) {
                if (i % d == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) total += i;
        }
    }
    return total;
}

