std::vector<int> scoreValidator(const std::vector<std::string>& scores) {
    int runs = 0;
    int wickets = 0;
    for (const std::string& s : scores) {
        if (wickets == 10) break;
        if (s == "W") {
            ++wickets;
        } else if (s == "WD" || s == "NB") {
            ++runs;
        } else {
            int val = 0;
            for (char c : s) {
                if (!std::isdigit(static_cast<unsigned char>(c))) {
                    return {};
                }
                val = val * 10 + (c - '0');
            }
            if (val < 0 || val > 6) return {};
            runs += val;
        }
    }
    return {runs, wickets};
}

