int maxFixedPoints(const std::vector<int>& nums) {
    int n = nums.size();
    std::vector<int> req(n), dp(n, 0);
    for (int i = 0; i < n; i++) req[i] = i - nums[i];
    int best = 0;
    for (int i = 0; i < n; i++) {
        if (req[i] < 0) { dp[i] = 0; continue; }
        dp[i] = 1;
        for (int j = 0; j < i; j++) {
            if (dp[j] > 0 && nums[j] < nums[i] && req[j] <= req[i])
                dp[i] = std::max(dp[i], dp[j] + 1);
        }
        best = std::max(best, dp[i]);
    }
    return best;
}

