int minGenerations(vector<vector<int>>& points, vector<int>& target) {
    set<vector<int>> pointSet(points.begin(), points.end());
    if (pointSet.count(target)) return 0;
    for (int gen = 1; gen <= 40; gen++) {
        vector<vector<int>> pts(pointSet.begin(), pointSet.end());
        set<vector<int>> newPoints;
        int n = pts.size();
        for (int i = 0; i < n; i++) {
            for (int j = i+1; j < n; j++) {
                vector<int> avg(pts[i].size());
                for (size_t k = 0; k < pts[i].size(); k++) avg[k] = (pts[i][k]+pts[j][k])/2;
                newPoints.insert(avg);
            }
        }
        bool addedNew = false;
        for (auto& p : newPoints) if (pointSet.insert(p).second) addedNew = true;
        if (pointSet.count(target)) return gen;
        if (!addedNew) break;
    }
    return -1;
}

