vector<int> countWordOccurrences(vector<string>& chunks, vector<string>& queries) {
    string s;
    for (auto& c : chunks) s += c;
    int n = s.size();
    unordered_map<string,int> cnt;
    auto isLower = [](char ch){ return ch>='a' && ch<='z'; };
    int i = 0;
    while (i < n) {
        char c = s[i];
        if (c == ' ' || c == '-') { i++; continue; }
        int j = i;
        while (j < n) {
            char cj = s[j];
            if (cj == ' ') break;
            if (cj == '-') {
                bool joiner = (j>i) && isLower(s[j-1]) && (j+1<n) && isLower(s[j+1]);
                if (!joiner) break;
            }
            j++;
        }
        cnt[s.substr(i, j-i)]++;
        i = j;
    }
    vector<int> ans;
    for (auto& q : queries) ans.push_back(cnt.count(q) ? cnt[q] : 0);
    return ans;
}

