int minimumThresholdPath(int n, const std::vector<std::vector<int>>& edges, int s, int t, int K) {
    std::vector<std::vector<std::pair<int, int>>> adj(n);
    std::unordered_set<int> weightSet;
    for (const auto& e : edges) {
        int u = e[0];
        int v = e[1];
        int w = e[2];
        adj[u].emplace_back(v, w);
        adj[v].emplace_back(u, w);
        weightSet.insert(w);
    }
    std::vector<int> uniq(weightSet.begin(), weightSet.end());
    uniq.push_back(0);
    std::sort(uniq.begin(), uniq.end());
    uniq.erase(std::unique(uniq.begin(), uniq.end()), uniq.end());

    auto feasible = [&](int limit) -> bool {
        const int INF = std::numeric_limits<int>::max();
        std::vector<int> dist(n, INF);
        std::deque<int> dq;
        dist[s] = 0;
        dq.push_back(s);
        while (!dq.empty()) {
            int u = dq.front();
            dq.pop_front();
            for (const auto& vw : adj[u]) {
                int v = vw.first;
                int w = vw.second;
                int cost = (w > limit) ? 1 : 0;
                int nd = dist[u] + cost;
                if (nd < dist[v] && nd <= K) {
                    dist[v] = nd;
                    if (cost == 0) {
                        dq.push_front(v);
                    } else {
                        dq.push_back(v);
                    }
                }
            }
        }
        return dist[t] <= K;
    };

    int lo = 0, hi = static_cast<int>(uniq.size()) - 1, ans = -1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        int thr = uniq[mid];
        if (feasible(thr)) {
            ans = thr;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    return ans;
}

