int smallestUniqueSubarray(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    if (n == 0) return -1;

    std::unordered_map<std::string, int> freq;
    freq.reserve(n * (n + 1) / 2);

    // First pass: count all subarrays
    for (int i = 0; i < n; ++i) {
        std::string key;
        key.reserve((n - i) * 12); // rough reservation
        for (int j = i; j < n; ++j) {
            key.append(std::to_string(nums[j]));
            key.push_back('#'); // delimiter
            ++freq[key];
        }
    }

    int best = std::numeric_limits<int>::max();

    // Second pass: find shortest unique subarray
    for (int i = 0; i < n; ++i) {
        std::string key;
        key.reserve((n - i) * 12);
        for (int j = i; j < n; ++j) {
            key.append(std::to_string(nums[j]));
            key.push_back('#');
            if (freq[key] == 1) {
                int len = j - i + 1;
                if (len < best) best = len;
                // No need to look at longer subarrays starting at i,
                // because they are longer than current best for this start.
                // But we continue to possibly find even shorter elsewhere.
            }
        }
    }

    return (best == std::numeric_limits<int>::max()) ? -1 : best;
}

