using namespace std;
const long long MOD = 1000000007LL;
int countNonAdjacentSubsets(vector<int>& parent, vector<int>& nums, int k) {
    int n = parent.size();
    vector<vector<int>> children(n);
    for (int i = 0; i < n; i++) if (parent[i] != -1) children[parent[i]].push_back(i);
    vector<int> order;
    vector<int> stk{0};
    while (!stk.empty()) {
        int u = stk.back(); stk.pop_back();
        order.push_back(u);
        for (int v : children[u]) stk.push_back(v);
    }
    vector<vector<long long>> dpNot(n), dpSel(n);
    for (int i = (int)order.size()-1; i >= 0; i--) {
        int u = order[i];
        vector<long long> dn(k,0), ds(k,0);
        dn[0]=1; ds[nums[u]%k]=1;
        for (int v : children[u]) {
            auto& cn = dpNot[v]; auto& cs = dpSel[v];
            vector<long long> comb(k);
            for (int j=0;j<k;j++) comb[j]=(cn[j]+cs[j])%MOD;
            vector<long long> nn(k,0), ns(k,0);
            for (int a=0;a<k;a++) {
                if (dn[a]) for (int b=0;b<k;b++) if (comb[b]) {
                    int idx=(a+b)%k;
                    nn[idx]=(nn[idx]+dn[a]*comb[b])%MOD;
                }
                if (ds[a]) for (int b=0;b<k;b++) if (cn[b]) {
                    int idx=(a+b)%k;
                    ns[idx]=(ns[idx]+ds[a]*cn[b])%MOD;
                }
            }
            dn=nn; ds=ns;
        }
        dpNot[u]=dn; dpSel[u]=ds;
    }
    return (int)((dpNot[0][0]+dpSel[0][0]-1+MOD)%MOD);
}

class Solution {
public:
    int maxIntersectionSum(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        map<pair<int,int>, long long> dp;
        for (int r1 = 0; r1 < m; r1++) {
            for (int r2 = 0; r2 < m; r2++) {
                int lo = max(0, r2), hi = min(r1, m - 1);
                long long contrib = 0;
                for (int r = lo; r <= hi; r++) contrib += grid[r][0];
                auto key = make_pair(r1, r2);
                if (!dp.count(key) || dp[key] < contrib) dp[key] = contrib;
            }
        }
        for (int c = 1; c < n; c++) {
            map<pair<int,int>, long long> ndp;
            for (auto& [key, val] : dp) {
                int pr1 = key.first, pr2 = key.second;
                for (int r1 = pr1; r1 < m; r1++) {
                    for (int r2 = 0; r2 <= pr2; r2++) {
                        int lo = max(pr1, r2), hi = min(r1, pr2);
                        long long contrib = 0;
                        for (int r = lo; r <= hi; r++) contrib += grid[r][c];
                        auto nkey = make_pair(r1, r2);
                        long long nv = val + contrib;
                        if (!ndp.count(nkey) || ndp[nkey] < nv) ndp[nkey] = nv;
                    }
                }
            }
            dp = ndp;
        }
        auto finalKey = make_pair(m - 1, 0);
        return dp.count(finalKey) ? (int) dp[finalKey] : 0;
    }
};

