using namespace std;
int countLocalMaximums(vector<vector<int>>& matrix) {
    int n = matrix.size(), m = matrix[0].size();
    int count = 0;
    for (int r = 0; r < n; r++) {
        for (int c = 0; c < m; c++) {
            int x = matrix[r][c];
            if (x == 0) continue;
            bool isMax = true;
            for (int dr = -x; dr <= x && isMax; dr++) {
                for (int dc = -x; dc <= x; dc++) {
                    if (abs(dr) == x && abs(dc) == x) continue;
                    int rr = r + dr, cc = c + dc;
                    if (rr < 0 || rr >= n || cc < 0 || cc >= m) continue;
                    if (matrix[rr][cc] > x) { isMax = false; break; }
                }
            }
            if (isMax) count++;
        }
    }
    return count;
}

