using namespace std;
int minOperations(vector<int>& nums, int k) {
    int n = nums.size();
    vector<int> residues(n);
    for (int i = 0; i < n; i++) residues[i] = ((nums[i] % k) + k) % k;
    int best = INT_MAX;
    for (int x = 0; x < k; x++) {
        for (int y = 0; y < k; y++) {
            if (x == y) continue;
            int cost = 0;
            for (int i = 0; i < n; i++) {
                int target = (i % 2 == 0) ? x : y;
                int diff = abs(residues[i] - target);
                cost += min(diff, k - diff);
            }
            best = min(best, cost);
        }
    }
    return best;
}

