using namespace std;
long long maximumSaleItems(vector<vector<int>>& items, long long budget) {
    int maxF = 0;
    for (auto& it : items) maxF = max(maxF, it[0]);
    vector<int> freq(maxF + 1, 0);
    for (auto& it : items) freq[it[0]]++;
    vector<long long> S(maxF + 1, 0);
    for (int f = 1; f <= maxF; f++) {
        long long total = 0;
        for (int m = f; m <= maxF; m += f) total += freq[m];
        S[f] = total;
    }
    long long minPrice = LLONG_MAX;
    for (auto& it : items) minPrice = min(minPrice, (long long)it[1]);
    vector<pair<long long,long long>> attractive;
    for (auto& it : items) {
        long long f = it[0], p = it[1];
        long long D = S[f] - 1;
        if (p <= 2 * minPrice) attractive.push_back({p, D});
    }
    sort(attractive.begin(), attractive.end());
    long long totalItems = 0, remaining = budget;
    for (auto& [price, D] : attractive) {
        if (D <= 0 || remaining < price) continue;
        long long buy = min(D, remaining / price);
        totalItems += buy * 2;
        remaining -= buy * price;
    }
    totalItems += remaining / minPrice;
    return totalItems;
}

