    int n = static_cast<int>(matrix.size());
    int low = matrix[0][0];
    int high = matrix[n - 1][n - 1];
    while (low < high) {
        int mid = low + (high - low) / 2;
        int count = 0;
        for (int row = 0; row < n; ++row) {
            int col = n - 1;
            while (col >= 0 && matrix[row][col] > mid) {
                --col;
