std::vector<int> inorderTraversal(TreeNode* root) {
    std::vector<int> result;
    std::function<void(TreeNode*)> traverse = [&](TreeNode* node) {
        if (!node) return;
        traverse(node->left);
        result.push_back(node->val);
        traverse(node->right);
    };
    traverse(root);
    return result;
}

