int kthLargestElement(const std::vector<int>& nums, int k) {
    std::vector<int> heap;

    auto parent = [](int i) { return (i - 1) >> 1; };
    auto left = [](int i) { return i * 2 + 1; };
    auto right = [](int i) { return i * 2 + 2; };

    auto heapifyUp = [&](int i) {
        while (i > 0 && heap[parent(i)] > heap[i]) {
            std::swap(heap[i], heap[parent(i)]);
            i = parent(i);
        }
    };

    auto heapifyDown = [&](int i) {
        while (true) {
            int smallest = i;
            int l = left(i), r = right(i);
            if (l < static_cast<int>(heap.size()) && heap[l] < heap[smallest]) smallest = l;
            if (r < static_cast<int>(heap.size()) && heap[r] < heap[smallest]) smallest = r;
            if (smallest == i) break;
            std::swap(heap[i], heap[smallest]);
            i = smallest;
        }
    };

    auto push = [&](int val) {
        heap.push_back(val);
        heapifyUp(static_cast<int>(heap.size()) - 1);
    };

    auto pop = [&]() -> int {
        if (heap.size() == 1) {
            int v = heap.back();
            heap.pop_back();
            return v;
        }
        int top = heap[0];
        heap[0] = heap.back();
        heap.pop_back();
        heapifyDown(0);
        return top;
    };

    auto peek = [&]() -> int {
        return heap[0];
    };

    for (size_t i = 0; i < nums.size(); ++i) {
        push(nums[i]);
        if (static_cast<int>(heap.size()) > k) pop();
    }

    return peek();
}

