std::vector<long long> rangeSumQuery(const std::vector<long long>& nums, const std::vector<std::vector<std::string>>& queries) {
    std::size_t n = nums.size();
    std::vector<long long> tree(4 * n, 0);

    std::function<void(int, int, int)> build = [&](int node, int l, int r) {
        if (l == r) {
            tree[node] = nums[l];
            return;
        }
        int mid = (l + r) >> 1;
        build(node * 2, l, mid);
        build(node * 2 + 1, mid + 1, r);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    };

    std::function<void(int, int, int, int, long long)> update = [&](int node, int l, int r, int idx, long long val) {
        if (l == r) {
            tree[node] = val;
            return;
        }
        int mid = (l + r) >> 1;
        if (idx <= mid) update(node * 2, l, mid, idx, val);
        else update(node * 2 + 1, mid + 1, r, idx, val);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    };

    std::function<long long(int, int, int, int, int)> query = [&](int node, int l, int r, int ql, int qr) -> long long {
        if (ql <= l && r <= qr) return tree[node];
        if (r < ql || l > qr) return 0;
        int mid = (l + r) >> 1;
        return query(node * 2, l, mid, ql, qr) + query(node * 2 + 1, mid + 1, r, ql, qr);
    };

    if (n > 0) build(1, 0, static_cast<int>(n) - 1);

    std::vector<long long> answers;
    for (const auto& q : queries) {
        if (!q.empty() && q[0] == "update") {
            int idx = std::stoi(q[1]);
            long long val = std::stoll(q[2]);
            update(1, 0, static_cast<int>(n) - 1, idx, val);
        } else if (!q.empty() && q[0] == "sum") {
            int left = std::stoi(q[1]);
            int right = std::stoi(q[2]);
            answers.push_back(query(1, 0, static_cast<int>(n) - 1, left, right));
        }
    }
    return answers;
}

