int bestTimeToBuySellCooldown(const std::vector<int>& prices) {
    if (prices.empty()) return 0;
    int cash = 0;
    int hold = -prices[0];
    int prevCash = 0;
    for (size_t i = 1; i < prices.size(); ++i) {
        int newCash = std::max(cash, hold + prices[i]);
        int newHold = std::max(hold, prevCash - prices[i]);
        prevCash = cash;
        cash = newCash;
        hold = newHold;
    }
    return cash;
}

