long long minCost(const std::vector<int>& nums) {
    size_t n = nums.size();
    long long minCost = LLONG_MAX;
    for (size_t i = 0; i < n - 2; ++i) {
        for (size_t j = i + 1; j < n - 1; ++j) {
            long long cost = static_cast<long long>(nums[0]) + nums[i + 1] + nums[j + 1];
            minCost = std::min(minCost, cost);
        }
    }
    return minCost;
}

#include <bits/stdc++.h>

int minOperations(const std::vector<int>& nums, int k) {
    int xorVal = 0;
    for (int num : nums) {
        xorVal ^= num;
    }
    if (xorVal == k) {
        return 0;
    }
    int diff = xorVal ^ k;
    for (int num : nums) {
        if ((num & diff) == diff) {
            return 1;
        }
    }
    return 2;
}

