long long maximumGoodSubarraySum(const std::vector<int>& nums, int k) {
    long long maxSum = LLONG_MIN;
    bool found = false;
    std::vector<long long> prefixSum;
    prefixSum.reserve(nums.size() + 1);
    prefixSum.push_back(0);
    for (size_t i = 0; i < nums.size(); ++i) {
        prefixSum.push_back(prefixSum[i] + nums[i]);
    }
    for (size_t i = 0; i < nums.size(); ++i) {
        for (size_t j = i; j < nums.size(); ++j) {
            if (std::abs(static_cast<long long>(nums[i]) - static_cast<long long>(nums[j])) == k) {
                long long sum = prefixSum[j + 1] - prefixSum[i];
                if (!found || sum > maxSum) {
                    maxSum = sum;
                    found = true;
                }
            }
        }
    }
    return found ? maxSum : 0;
}

#include <bits/stdc++.h>

long long powerfulIntegers(long long start, long long finish, long long limit, const std::string& s) {
    for (char c : s) {
        if (c < '0' || c > '9' || (c - '0') > limit) {
            return 0;
        }
    }
    long long suffixVal = std::stoll(s);
    int suffixLen = static_cast<int>(s.size());
    int maxLen = static_cast<int>(std::to_string(finish).size());

    std::vector<long long> pow10(maxLen + 1, 1);
    for (int i = 1; i <= maxLen; ++i) {
        pow10[i] = pow10[i - 1] * 10;
    }

    long long count = 0;
    std::function<void(long long, int)> dfs = [&](long long curVal, int curLen) {
        if (curLen >= suffixLen && curVal >= start && curVal <= finish) {
            ++count;
        }
        if (curLen == maxLen) {
            return;
        }
        for (int d = 0; d <= limit; ++d) {
            if (curLen == suffixLen && d == 0) {
                continue; // avoid leading zero on first added digit
            }
            long long newVal = d * pow10[curLen] + curVal;
            if (newVal > finish) {
                continue;
            }
            dfs(newVal, curLen + 1);
        }
    };

    dfs(suffixVal, suffixLen);
    return count;
}

#include <bits/stdc++.h>

long long minimumKeypresses(const std::string& word) {
    std::unordered_map<char, long long> freq;
    for (char c : word) {
        ++freq[c];
    }
    std::vector<long long> counts;
    counts.reserve(freq.size());
    for (const auto& kv : freq) {
        counts.push_back(kv.second);
    }
    std::sort(counts.begin(), counts.end(), std::greater<long long>());
    long long result = 0;
    for (size_t i = 0; i < counts.size(); ++i) {
        result += counts[i] * (static_cast<long long>(i / 8) + 1);
    }
    return result;
}

