std::vector<int> beautifulIndices(const std::string& s, const std::string& a, const std::string& b, int k) {
    std::vector<int> beautiful;
    int n = static_cast<int>(s.size());
    int alen = static_cast<int>(a.size());
    int blen = static_cast<int>(b.size());
    for (int i = 0; i <= n - alen; ++i) {
        if (s.substr(i, alen) == a) {
            for (int j = 0; j <= n - blen; ++j) {
                if (s.substr(j, blen) == b && std::abs(i - j) <= k) {
                    beautiful.push_back(i);
                    break;
                }
            }
        }
    }
    std::sort(beautiful.begin(), beautiful.end());
    beautiful.erase(std::unique(beautiful.begin(), beautiful.end()), beautiful.end());
    return beautiful;
}

#include <bits/stdc++.h>

int maximumSizeAfterRemovals(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    std::unordered_set<int> set1(nums1.begin(), nums1.end());
    std::unordered_set<int> set2(nums2.begin(), nums2.end());

    int common = 0;
    for (int v : set1) {
        if (set2.find(v) != set2.end()) ++common;
    }

    int exclusive1 = static_cast<int>(set1.size()) - common;
    int exclusive2 = static_cast<int>(set2.size()) - common;
    int k = static_cast<int>(nums1.size() / 2);

    return common + std::min(k, exclusive1) + std::min(k, exclusive2);
}

#include <bits/stdc++.h>

long long minimumCost(const std::vector<int>& nums, int k, int dist) {
    int n = static_cast<int>(nums.size());
    if (k == 1) return nums[0];
    int need = k - 1; // number of additional starts to choose
    const long long INF = (1LL << 60);
    long long best = INF;

    std::multiset<int> small; // holds the smallest 'need' elements
    std::multiset<int> large; // the rest
    long long sumSmall = 0;

    int left = 1; // window starts at index 1 (second subarray cannot start at 0)
    for (int right = 1; right < n; ++right) {
        // add nums[right] to the window
        small.insert(nums[right]);
        sumSmall += nums[right];
        if ((int)small.size() > need) {
            auto it = std::prev(small.end()); // largest in small
            sumSmall -= *it;
            large.insert(*it);
            small.erase(it);
        }

        // shrink window if its length exceeds dist
        while (right - left > dist) {
            int val = nums[left];
            auto itSmall = small.find(val);
            if (itSmall != small.end()) {
                sumSmall -= val;
                small.erase(itSmall);
            } else {
                auto itLarge = large.find(val);
                if (itLarge != large.end()) large.erase(itLarge);
            }
            ++left;
            // rebalance to keep 'need' smallest elements in 'small' if possible
            while ((int)small.size() < need && !large.empty()) {
                auto it = large.begin(); // smallest in large
                sumSmall += *it;
                small.insert(*it);
                large.erase(it);
            }
        }

        // if we have enough elements in the current window, consider its sum
        if ((int)small.size() == need) {
            best = std::min(best, sumSmall);
        }
    }

    return best == INF ? -1 : nums[0] + best;
}

#include <bits/stdc++.h>

long long minimumDamage(long long power, const std::vector<long long>& damage, const std::vector<long long>& health) {
    struct Enemy {
        long long d;
        long long p;
    };
    std::vector<Enemy> enemies;
    enemies.reserve(damage.size());
    for (std::size_t i = 0; i < damage.size(); ++i) {
        long long p = (health[i] + power - 1) / power;
        enemies.push_back({damage[i], p});
    }
    std::sort(enemies.begin(), enemies.end(),
        [](const Enemy& a, const Enemy& b) {
            return static_cast<long double>(a.d) * b.p > static_cast<long double>(b.d) * a.p;
        });
    long long total = 0;
    long long cur = 0;
    for (const auto& e : enemies) {
        cur += e.p;
        total += e.d * cur;
    }
    return total;
}

