int countSetBits(int x) {
    unsigned int v = static_cast<unsigned int>(x);
    int cnt = 0;
    while (v) {
        cnt += v & 1u;
        v >>= 1;
    }
    return cnt;
}

bool canSortArray(const std::vector<int>& nums) {
    std::vector<int> sortedNums = nums;
    std::sort(sortedNums.begin(), sortedNums.end());

    std::vector<int> setBitsCount(nums.size());
    for (size_t i = 0; i < nums.size(); ++i) {
        setBitsCount[i] = countSetBits(nums[i]);
    }

    std::vector<int> sortedSetBitsCount(nums.size());
    for (size_t i = 0; i < sortedNums.size(); ++i) {
        sortedSetBitsCount[i] = countSetBits(sortedNums[i]);
    }

    for (size_t i = 0; i < nums.size(); ++i) {
        if (setBitsCount[i] != sortedSetBitsCount[i]) {
            return false;
        }
    }
    return true;
}
